ui_restore_echo() {
    [ "${UI_ECHO_DISABLED:-0}" = '1' ] || return 0

    if command -v stty >/dev/null 2>&1; then
        case "${UI_ECHO_DEVICE:-}" in
            tty)
                stty echo </dev/tty >/dev/null 2>&1 || true
                ;;
            stdin)
                if [ -t 0 ]; then
                    stty echo >/dev/null 2>&1 || true
                elif [ -r /dev/tty ]; then
                    stty echo </dev/tty >/dev/null 2>&1 || true
                fi
                ;;
        esac
    fi

    UI_ECHO_DISABLED='0'
    UI_ECHO_DEVICE=''
}

cleanup_openlist_active_workdir() {
    [ -n "${OPENLIST_ACTIVE_WORKDIR:-}" ] || return 0

    case "$OPENLIST_ACTIVE_WORKDIR" in
        /tmp/storage/*/nradio-openlist-work.*|/mnt/app_data/nradio-openlist-work.*)
            rm -rf "$OPENLIST_ACTIVE_WORKDIR" 2>/dev/null || true
            ;;
    esac
    OPENLIST_ACTIVE_WORKDIR=''
}

cleanup() {
    ui_restore_echo
    terminate_active_download
    terminate_registered_background_jobs
    cleanup_openlist_active_workdir
    release_script_lock
    rm -rf "$WORKDIR"
}

abort_script() {
    [ "${ABORTING:-0}" = '1' ] && exit 130
    ABORTING='1'
    trap - EXIT INT TERM HUP QUIT
    cleanup
    printf '\n已取消\n' >&2
    exit 130
}

trap cleanup EXIT
trap abort_script INT TERM HUP QUIT

log() {
    printf '%s\n' "$*"
}

die() {
    printf 'ERROR: %s\n' "$*" >&2
    exit 1
}

_STAGE_T0=""

log_stage() {
    stage_index="$1"
    stage_total="$2"
    shift 2

    _bar_len=20
    _filled=$(( stage_index * _bar_len / stage_total ))
    [ "$_filled" -gt "$_bar_len" ] && _filled="$_bar_len"
    _empty=$(( _bar_len - _filled ))
    _pct=$(( stage_index * 100 / stage_total ))

    _bar=""
    _bi=0
    while [ "$_bi" -lt "$_filled" ]; do _bar="${_bar}="; _bi=$((_bi + 1)); done
    if [ "$_empty" -gt 0 ]; then
        _bar="${_bar}>"
        _bi=1
        while [ "$_bi" -lt "$_empty" ]; do _bar="${_bar}."; _bi=$((_bi + 1)); done
    fi

    _elapsed_tag=""
    _now="$(date +%s 2>/dev/null || printf '')"
    if [ -n "$_now" ] && [ -n "$_STAGE_T0" ]; then
        _dt=$((_now - _STAGE_T0))
        if [ "$_dt" -ge 60 ] 2>/dev/null; then
            _dm=$((_dt / 60))
            _ds=$((_dt % 60))
            _elapsed_tag="  (上一步耗时 ${_dm}分${_ds}秒)"
        elif [ "$_dt" -gt 0 ] 2>/dev/null; then
            _elapsed_tag="  (上一步耗时 ${_dt}秒)"
        fi
    fi
    [ -n "$_now" ] && _STAGE_T0="$_now"

    printf '[%s] %3d%%  [%s/%s] %s%s\n' "$_bar" "$_pct" "$stage_index" "$stage_total" "$*" "$_elapsed_tag"
}

stderr_is_tty() {
    [ -t 2 ]
}

get_file_size_bytes() {
    path="$1"
    [ -f "$path" ] || {
        printf '0\n'
        return 0
    }
    wc -c < "$path" 2>/dev/null | tr -d ' ' || printf '0\n'
}

format_bytes_human() {
    size_bytes="${1:-0}"
    case "$size_bytes" in
        ''|*[!0-9]*)
            size_bytes=0
            ;;
    esac
    if [ "$size_bytes" -ge 1073741824 ] 2>/dev/null; then
        awk -v v="$size_bytes" 'BEGIN { printf "%.1f GB", v / 1073741824 }'
    elif [ "$size_bytes" -ge 1048576 ] 2>/dev/null; then
        awk -v v="$size_bytes" 'BEGIN { printf "%.1f MB", v / 1048576 }'
    elif [ "$size_bytes" -ge 1024 ] 2>/dev/null; then
        awk -v v="$size_bytes" 'BEGIN { printf "%.1f KB", v / 1024 }'
    else
        printf '%s B' "$size_bytes"
    fi
}

get_path_free_bytes() {
    target_path="$1"
    [ -n "$target_path" ] || return 1
    df -kP "$target_path" 2>/dev/null | awk 'NR==2 {print $4 * 1024; exit}'
}

ensure_dir_writable() {
    target_dir="$1"
    target_label="${2:-$target_dir}"
    probe_file=""

    [ -d "$target_dir" ] || die "$target_label 不存在"
    probe_file="$target_dir/.nradio-write-test.$$"
    : > "$probe_file" 2>/dev/null || die "$target_label 不可写"
    rm -f "$probe_file" 2>/dev/null || true
}

ensure_free_space_bytes() {
    target_path="$1"
    required_bytes="$2"
    target_label="${3:-$target_path}"

    case "$required_bytes" in
        ''|*[!0-9]*)
            return 0
            ;;
    esac

    free_bytes="$(get_path_free_bytes "$target_path" 2>/dev/null || true)"
    case "$free_bytes" in
        ''|*[!0-9]*)
            die "$target_label 空间检查失败"
            ;;
    esac

    [ "$free_bytes" -ge "$required_bytes" ] 2>/dev/null || die "$target_label 可用空间不足：需要 $(format_bytes_human "$required_bytes")，当前仅剩 $(format_bytes_human "$free_bytes")"
}

estimate_archive_extract_bytes() {
    archive_path="$1"
    archive_size="$(get_file_size_bytes "$archive_path" 2>/dev/null || true)"
    case "$archive_size" in
        ''|*[!0-9]*)
            return 1
            ;;
    esac

    printf '%s\n' $(( archive_size * 2 + 16777216 ))
}

validate_tar_archive() {
    archive_path="$1"
    archive_label="${2:-压缩包}"
    validate_log="${3:-$WORKDIR/archive-validate.log}"

    [ -s "$archive_path" ] || die "$archive_label 文件为空或不存在"

    if ! tar -tzf "$archive_path" > /dev/null 2>"$validate_log"; then
        sed -n '1,20p' "$validate_log" >&2 || true
        die "$archive_label 目录校验失败，请查看 $validate_log"
    fi
}

find_archive_first_matching_entry() {
    archive_path="$1"
    entry_pattern="${2:-}"

    [ -n "$archive_path" ] || return 1
    [ -n "$entry_pattern" ] || return 1

    tar -tzf "$archive_path" 2>/dev/null | awk -v pat="$entry_pattern" '
        NF && $0 !~ /\/$/ && $0 ~ pat { print; exit }
    '
}

now_epoch_seconds() {
    date +%s 2>/dev/null || printf '0\n'
}

get_download_content_length() {
    [ "${DOWNLOAD_SKIP_CONTENT_LENGTH:-0}" != '1' ] || return 0
    [ -s "$1" ] || return 0
    awk '
        { sub(/\r$/, "") }
        /^HTTP\// { status=$2; length_value=""; range_total=""; chunked=0; complete=0; next }
        tolower($0) ~ /^content-length:/ {
            value=$0; sub(/^[^:]*:[ \t]*/, "", value); sub(/[ \t]+$/, "", value)
            if (value ~ /^[0-9]+$/) length_value=value
        }
        tolower($0) ~ /^content-range:/ {
            value=$0; sub(/^.*\//, "", value); sub(/[ \t]+$/, "", value)
            if (value ~ /^[0-9]+$/) range_total=value
        }
        tolower($0) ~ /^transfer-encoding:.*chunked/ { chunked=1 }
        /^$/ { complete=1 }
        END {
            if (!complete) exit
            if (status == 206 && range_total != "") print range_total
            else if (status == 200 && !chunked && length_value != "") print length_value
        }
    ' "$1"
}

render_download_progress() {
    progress_state="$1"
    current_bytes="$2"
    total_bytes="${3:-}"
    speed_bytes="${4:-}"
    display_elapsed="${5:-0}"
    current_human="$(format_bytes_human "$current_bytes")"
    current_human="${current_human% *}${current_human##* }"
    display_columns="${DOWNLOAD_DISPLAY_COLUMNS:-${COLUMNS:-80}}"
    case "$display_columns" in ''|*[!0-9]*) display_columns=80 ;; esac
    line="$progress_state $current_human"

    if [ -n "$total_bytes" ] && [ "$total_bytes" -gt 0 ] 2>/dev/null; then
        progress_percent=$(( current_bytes * 100 / total_bytes ))
        [ "$progress_percent" -le 100 ] || progress_percent=100
        if [ "$progress_state" != '下载完成' ] && [ "$progress_percent" -ge 100 ]; then
            progress_percent=99
        fi
        line="$progress_state ${progress_percent}% $current_human"
        if [ "$display_columns" -ge 60 ]; then
            total_human="$(format_bytes_human "$total_bytes")"
            total_human="${total_human% *}${total_human##* }"
            line="$line/$total_human"
        fi
        if [ "$display_columns" -ge 80 ]; then
            _dl_filled=$(( progress_percent * 15 / 100 ))
            _dl_bar=''
            _dbi=0
            while [ "$_dbi" -lt 15 ]; do
                if [ "$_dbi" -lt "$_dl_filled" ]; then
                    _dl_bar="${_dl_bar}="
                elif [ "$_dbi" -eq "$_dl_filled" ]; then
                    _dl_bar="${_dl_bar}>"
                else
                    _dl_bar="${_dl_bar}."
                fi
                _dbi=$((_dbi + 1))
            done
            line="[$_dl_bar] $line"
        fi
    fi

    case "$speed_bytes" in
        ''|*[!0-9]*) ;;
        *)
            if [ "$display_columns" -ge 40 ]; then
                speed_human="$(format_bytes_human "$speed_bytes")"
                speed_human="${speed_human% *}${speed_human##* }"
                line="$line $speed_human/s"
            fi
            ;;
    esac
    if [ "$display_columns" -ge 60 ]; then
        line="$line $((display_elapsed / 60))分$((display_elapsed % 60))秒"
    fi

    if stderr_is_tty; then
        printf '\r\033[K%s' "$line" >&2
    else
        printf '%s\n' "$line" >&2
    fi
}

finish_download_progress_line() {
    if stderr_is_tty; then
        printf '\n' >&2
    fi
}

sleep_abort_poll() {
    usleep 100000 2>/dev/null || sleep 0.1 2>/dev/null || sleep 1
}

sleep_download_poll() {
    poll_usec="${DOWNLOAD_PROGRESS_POLL_USEC:-250000}"
    case "$poll_usec" in
        ''|*[!0-9]*) poll_usec=250000 ;;
    esac
    [ "$poll_usec" -ge 100000 ] || poll_usec=100000
    usleep "$poll_usec" 2>/dev/null || sleep 0.25 2>/dev/null || sleep 1
}

terminate_pid_quick() {
    target_pid="$1"
    [ -n "$target_pid" ] || return 0

    if kill -0 "$target_pid" 2>/dev/null; then
        kill -INT "$target_pid" 2>/dev/null || kill "$target_pid" 2>/dev/null || true
        _tp_try=0
        while kill -0 "$target_pid" 2>/dev/null; do
            _tp_try=$((_tp_try + 1))
            [ "$_tp_try" -lt 4 ] || break
            sleep_abort_poll
        done
        if kill -0 "$target_pid" 2>/dev/null; then
            kill -TERM "$target_pid" 2>/dev/null || true
            _tp_try=0
            while kill -0 "$target_pid" 2>/dev/null; do
                _tp_try=$((_tp_try + 1))
                [ "$_tp_try" -lt 4 ] || break
                sleep_abort_poll
            done
        fi
        if kill -0 "$target_pid" 2>/dev/null; then
            kill -9 "$target_pid" 2>/dev/null || true
        fi
    fi

    wait "$target_pid" 2>/dev/null || true
}

wait_for_pid_list() {
    wait_pids="$*"
    [ -n "$wait_pids" ] || return 0

    while :; do
        wait_remaining=''
        for wait_pid in $wait_pids; do
            if kill -0 "$wait_pid" 2>/dev/null; then
                if [ -n "$wait_remaining" ]; then
                    wait_remaining="$wait_remaining $wait_pid"
                else
                    wait_remaining="$wait_pid"
                fi
            fi
        done
        [ -n "$wait_remaining" ] || break
        sleep_abort_poll
    done

    wait_rc=0
    for wait_pid in $wait_pids; do
        if wait "$wait_pid" 2>/dev/null; then
            wait_pid_rc=0
        else
            wait_pid_rc="$?"
        fi
        case "$wait_pid_rc" in
            0|127)
                ;;
            *)
                [ "$wait_rc" -eq 0 ] && wait_rc="$wait_pid_rc"
                ;;
        esac
    done

    return "$wait_rc"
}

terminate_registered_background_jobs() {
    bg_pids="${ACTIVE_BACKGROUND_PIDS:-}"
    [ -n "$bg_pids" ] || return 0

    for bg_pid in $bg_pids; do
        terminate_pid_quick "$bg_pid"
    done

    ACTIVE_BACKGROUND_PIDS=''
}

terminate_active_download() {
    active_pid="${ACTIVE_DOWNLOAD_PID:-}"
    [ -n "$active_pid" ] || return 0

    terminate_pid_quick "$active_pid"
    ACTIVE_DOWNLOAD_PID=''
    [ -z "${progress_headers:-}" ] || rm -f "$progress_headers"
    [ -z "${progress_error_log:-}" ] || rm -f "$progress_error_log"
}

run_download_with_progress() {
    progress_url="$1"
    progress_out="$2"
    shift 2

    progress_headers="$progress_out.headers"
    progress_error_log="$progress_out.download.log"
    : > "$progress_headers" || return 1
    : > "$progress_error_log" || { rm -f "$progress_headers"; return 1; }
    progress_total=''
    progress_speed=''
    DOWNLOAD_DISPLAY_COLUMNS="${COLUMNS:-80}"
    if stderr_is_tty; then
        progress_terminal_size="$(stty size </dev/tty 2>/dev/null || true)"
        case "$progress_terminal_size" in
            *' '*) DOWNLOAD_DISPLAY_COLUMNS="${progress_terminal_size##* }" ;;
        esac
    fi
    progress_start_epoch="$(date +%s)"
    progress_prev_sample_epoch="$progress_start_epoch"
    progress_prev_sample_size="$(get_file_size_bytes "$progress_out")"
    progress_initial_size="$progress_prev_sample_size"
    progress_last_change_epoch="$progress_start_epoch"
    progress_last_print_epoch="$progress_start_epoch"
    progress_timeout="${DOWNLOAD_MAX_TIME:-900}"
    case "$progress_timeout" in ''|*[!0-9]*) progress_timeout=900 ;; esac
    progress_timed_out=0
    render_download_progress "连接中" "$progress_initial_size" "" "" 0

    if [ "$1" = 'curl' ]; then
        "$@" --dump-header "$progress_headers" 2>"$progress_error_log" &
    else
        "$@" 2>"$progress_error_log" &
    fi
    progress_pid="$!"
    ACTIVE_DOWNLOAD_PID="$progress_pid"

    while kill -0 "$progress_pid" 2>/dev/null; do
        progress_now_epoch="$(date +%s)"
        progress_elapsed=$((progress_now_epoch - progress_start_epoch))
        if [ "$progress_timeout" -gt 0 ] && [ "$progress_elapsed" -ge "$progress_timeout" ]; then
            progress_timed_out=1
            terminate_pid_quick "$progress_pid"
            break
        fi
        progress_sample_elapsed=$((progress_now_epoch - progress_prev_sample_epoch))
        if [ "$progress_sample_elapsed" -ge 1 ]; then
            progress_size="$(get_file_size_bytes "$progress_out")"
            progress_total="$(get_download_content_length "$progress_headers")"
            progress_delta=$((progress_size - progress_prev_sample_size))
            if [ "$progress_delta" -ne 0 ]; then
                progress_last_change_epoch="$progress_now_epoch"
            fi
            [ "$progress_delta" -ge 0 ] || progress_delta=0
            progress_speed=$((progress_delta / progress_sample_elapsed))
            progress_prev_sample_size="$progress_size"
            progress_prev_sample_epoch="$progress_now_epoch"
            progress_state='下载中'
            if [ $((progress_now_epoch - progress_last_change_epoch)) -ge 10 ]; then
                progress_state='等待数据'
            elif [ "$progress_size" -eq "$progress_initial_size" ] && [ "$progress_speed" -eq 0 ]; then
                progress_state='连接中'
            fi
            if stderr_is_tty || [ $((progress_now_epoch - progress_last_print_epoch)) -ge 5 ]; then
                render_download_progress "$progress_state" "$progress_size" "$progress_total" "$progress_speed" "$progress_elapsed"
                progress_last_print_epoch="$progress_now_epoch"
            fi
        fi
        sleep_download_poll
    done

    if wait "$progress_pid"; then
        progress_rc=0
    else
        progress_rc="$?"
    fi
    ACTIVE_DOWNLOAD_PID=''
    [ "$progress_timed_out" -eq 0 ] || progress_rc=28
    progress_size="$(get_file_size_bytes "$progress_out")"
    progress_total="$(get_download_content_length "$progress_headers")"
    progress_elapsed=$(( $(date +%s) - progress_start_epoch ))
    [ "$progress_elapsed" -ge 0 ] || progress_elapsed=0
    if [ "$progress_rc" -eq 0 ] && [ "$progress_size" -eq 0 ]; then
        progress_rc=1
        printf '%s\n' '下载结果为空' >> "$progress_error_log"
    fi

    if [ "$progress_rc" -eq 0 ]; then
        render_download_progress "下载完成" "$progress_size" "$progress_size" "" "$progress_elapsed"
    else
        render_download_progress "下载失败" "$progress_size" "$progress_total" "" "$progress_elapsed"
    fi
    finish_download_progress_line
    if [ "$progress_timed_out" -eq 1 ]; then
        printf '下载超时：已达 %s 秒\n' "$progress_timeout" >&2
    fi
    if [ "$progress_rc" -ne 0 ] && [ -s "$progress_error_log" ]; then
        tail -n 8 "$progress_error_log" >&2
    fi
    rm -f "$progress_headers" "$progress_error_log"
    return "$progress_rc"
}

ui_read_line() {
    if [ -t 0 ]; then
        read -r UI_READ_RESULT || return 1
        return 0
    fi
    if read -r UI_READ_RESULT; then
        return 0
    fi
    if can_use_ui_tty; then
        read -r UI_READ_RESULT </dev/tty || return 1
        return 0
    fi
    return 1
}

can_use_ui_tty() {
    [ -r /dev/tty ] || return 1
    ( : </dev/tty ) >/dev/null 2>&1
}

ui_read_secret() {
    secret_prompt="${1:-}"

    if [ -t 0 ]; then
        if command -v stty >/dev/null 2>&1; then
            UI_ECHO_DISABLED='1'
            UI_ECHO_DEVICE='stdin'
            if ! stty -echo; then
                UI_ECHO_DISABLED='0'
                UI_ECHO_DEVICE=''
                return 1
            fi
            [ -n "$secret_prompt" ] && printf '%s' "$secret_prompt"
            if read -r UI_READ_RESULT; then
                rc='0'
            else
                rc="$?"
            fi
            ui_restore_echo
            printf '\n'
            return "$rc"
        fi
        [ -n "$secret_prompt" ] && printf '%s' "$secret_prompt"
        read -r UI_READ_RESULT || {
            return "$?"
        }
        return 0
    fi
    [ -n "$secret_prompt" ] && printf '%s' "$secret_prompt"
    if read -r UI_READ_RESULT; then
        return 0
    fi
    if can_use_ui_tty; then
        if command -v stty >/dev/null 2>&1; then
            UI_ECHO_DISABLED='1'
            UI_ECHO_DEVICE='tty'
            if ! stty -echo </dev/tty; then
                UI_ECHO_DISABLED='0'
                UI_ECHO_DEVICE=''
                return 1
            fi
            [ -n "$secret_prompt" ] && printf '%s' "$secret_prompt" >/dev/tty
            if read -r UI_READ_RESULT </dev/tty; then
                rc='0'
            else
                rc="$?"
            fi
            ui_restore_echo
            printf '\n' >/dev/tty
            return "$rc"
        fi
        [ -n "$secret_prompt" ] && printf '%s' "$secret_prompt" >/dev/tty
        read -r UI_READ_RESULT </dev/tty || {
            return "$?"
        }
        return 0
    fi
    return 1
}

confirm_or_exit() {
    prompt="$1"
    answer=""
    printf '%s [y/N]: ' "$prompt"
    ui_read_line || die "input cancelled"
    answer="$UI_READ_RESULT"
    case "$answer" in
        y|Y|yes|YES)
            return 0
            ;;
        *)
            log "已取消"
            exit 0
            ;;
    esac
}

confirm_default_yes() {
    prompt="$1"
    answer=""
    printf '%s [Y/n]: ' "$prompt"
    ui_read_line || die "input cancelled"
    answer="$UI_READ_RESULT"
    case "$answer" in
        n|N|no|NO)
            return 1
            ;;
        *)
            return 0
            ;;
    esac
}

run_startup_disclaimer_countdown() {
    disclaimer_countdown_remaining="${1:-10}"
    case "$disclaimer_countdown_remaining" in
        ''|*[!0-9]*) disclaimer_countdown_remaining=10 ;;
    esac

    if [ -t 1 ]; then
        while [ "$disclaimer_countdown_remaining" -gt 0 ]; do
            printf '\r\033[K阅读等待 %s 秒...' "$disclaimer_countdown_remaining"
            sleep 1
            disclaimer_countdown_remaining=$((disclaimer_countdown_remaining - 1))
        done
        printf '\r\033[K可以选择是否同意。\n'
    else
        printf '阅读等待 %s 秒...\n' "$disclaimer_countdown_remaining"
        while [ "$disclaimer_countdown_remaining" -gt 0 ]; do
            sleep 1
            disclaimer_countdown_remaining=$((disclaimer_countdown_remaining - 1))
        done
        printf '可以选择是否同意。\n'
    fi
}

clear_startup_screen() {
    [ -t 1 ] || return 0
    printf '\033[H\033[2J'
}

prime_startup_disclaimer_model() {
    [ -n "$CURRENT_DETECTED_MODEL" ] && return 0

    raw_model="$(detect_board_model_raw 2>/dev/null || true)"
    raw_board="$(detect_board_name_raw 2>/dev/null || true)"
    raw_compat="$(detect_board_compatible_raw 2>/dev/null || true)"
    normalized_model="$(normalize_nradio_model "$raw_model" "$raw_board" "$raw_compat" 2>/dev/null || true)"

    [ -n "$normalized_model" ] && CURRENT_DETECTED_MODEL="$normalized_model"
}

require_startup_disclaimer_acceptance_once() {
    disclaimer_answer=""

    [ -f "$DISCLAIMER_ACCEPTED_FLAG_FILE" ] && return 0

    prime_startup_disclaimer_model
    clear_startup_screen
    print_startup_disclaimer_text
    printf '\n'
    run_startup_disclaimer_countdown 10
    printf '\n同意并继续 [y/N，回车退出]: '
    ui_read_line || die "input cancelled"
    disclaimer_answer="$UI_READ_RESULT"

    case "$disclaimer_answer" in
        y|Y)
            mkdir -p "$STATE_DIR" >/dev/null 2>&1 || die "创建免责声明状态目录失败: $STATE_DIR"
            printf '%s\n' "accepted ${SCRIPT_VERSION} ${SCRIPT_RELEASE_DATE}" > "$DISCLAIMER_ACCEPTED_FLAG_FILE" || die "写入免责声明同意标记失败: $DISCLAIMER_ACCEPTED_FLAG_FILE"
            printf '\n已确认使用条款，进入功能菜单。\n'
            ;;
        *)
            log "未同意免责声明，脚本已退出"
            exit 0
            ;;
    esac
}

detect_current_nradio_model_quiet() {
    model="${CURRENT_DETECTED_MODEL:-}"
    if [ -z "$model" ]; then
        model="$(normalize_nradio_model "$(detect_board_model_raw)" "$(detect_board_name_raw)" "$(detect_board_compatible_raw)" 2>/dev/null || true)"
    fi
    printf '%s\n' "$model"
}

is_current_model_c2000pro() {
    [ "$(detect_current_nradio_model_quiet 2>/dev/null || true)" = 'NRadio_C2000Pro' ]
}

is_current_model_c8_788() {
    [ "$(detect_current_nradio_model_quiet 2>/dev/null || true)" = 'NRadio_C8-788' ]
}

is_current_model_ak798() {
    [ "$(detect_current_nradio_model_quiet 2>/dev/null || true)" = 'NRadio_AK68-798' ]
}

is_ak798_compat_appcenter_file() {
    [ -f "$1" ] && grep -Fq -e 'NRadio AK68-798 compatibility appcenter layer' -e 'NRadio AK798 compatibility appcenter layer' "$1" 2>/dev/null
}

is_c2000pro_compat_appcenter_file() {
    target_file="$1"
    [ -f "$target_file" ] || return 1
    grep -q 'NRadio C2000Pro compatibility appcenter layer' "$target_file" 2>/dev/null
}

detect_appcenter_environment_profile() {
    profile_model="$(detect_current_nradio_model_quiet 2>/dev/null || true)"

    if [ "$profile_model" = 'NRadio_AK68-798' ]; then
        if [ -f "$CFG" ] && is_ak798_compat_appcenter_file "$TPL" && is_ak798_compat_appcenter_file "$APPCENTER_CONTROLLER"; then
            printf '%s\n' 'ak798_compat'
        else
            printf '%s\n' 'ak798_base'
        fi
        return 0
    fi

    if [ "$profile_model" = 'NRadio_C2000Pro' ]; then
        if [ -f "$CFG" ] && is_c2000pro_compat_appcenter_file "$TPL" && is_c2000pro_compat_appcenter_file "$APPCENTER_CONTROLLER"; then
            printf '%s\n' 'c2000pro_compat'
        else
            printf '%s\n' 'c2000pro_base'
        fi
        return 0
    fi

    if [ -f "$CFG" ] && [ -f "$TPL" ]; then
        printf '%s\n' 'legacy_appcenter'
    else
        printf '%s\n' 'missing'
    fi
}

is_c2000pro_appcenter_environment() {
    case "$(detect_appcenter_environment_profile 2>/dev/null || true)" in
        c2000pro_base|c2000pro_compat)
            return 0
            ;;
    esac
    return 1
}

has_nradio_oem_appcenter() {
    case "$(detect_appcenter_environment_profile 2>/dev/null || true)" in
        legacy_appcenter|c2000pro_compat|ak798_compat)
            return 0
            ;;
    esac
    return 1
}

collect_missing_nradio_paths() {
    missing=""
    [ -f "$CFG" ] || missing="$missing $CFG"
    [ -f "$TPL" ] || missing="$missing $TPL"
    [ -f "$APPCENTER_CONTROLLER" ] || missing="$missing $APPCENTER_CONTROLLER"
    printf '%s\n' "${missing# }"
}

read_system_board_field() {
    field_name="$1"
    ubus call system board 2>/dev/null | sed -n "s/.*\"$field_name\"[[:space:]]*:[[:space:]]*\"\([^\"]*\)\".*/\1/p" | sed -n '1p'
}

detect_board_model_raw() {
    raw="$(read_system_board_field model 2>/dev/null || true)"
    [ -n "$raw" ] || raw="$(sed -n '1p' /tmp/sysinfo/model 2>/dev/null || true)"
    [ -n "$raw" ] || raw="$(tr -d '\000' < /proc/device-tree/model 2>/dev/null | sed -n '1p' || true)"
    printf '%s\n' "$raw"
}

detect_board_name_raw() {
    raw="$(read_system_board_field board_name 2>/dev/null || true)"
    [ -n "$raw" ] || raw="$(sed -n '1p' /tmp/sysinfo/board_name 2>/dev/null || true)"
    printf '%s\n' "$raw"
}

detect_board_compatible_raw() {
    raw="$(tr '\000' '\n' < /proc/device-tree/compatible 2>/dev/null | sed -n '1,8p' | tr '\n' ' ' || true)"
    printf '%s\n' "$raw"
}

detect_nros_revision() {
    rev="$(read_system_board_field revision 2>/dev/null || true)"
    [ -n "$rev" ] || rev="$(sed -n "s/^DISTRIB_REVISION='\\([^']*\\)'/\\1/p" /etc/openwrt_release 2>/dev/null | sed -n '1p' || true)"
    [ -n "$rev" ] || rev="$(sed -n 's/^BUILD_ID=\"\([^\"]*\)\"$/\1/p' /etc/os-release 2>/dev/null | sed -n '1p' || true)"
    rev="$(printf '%s' "$rev" | sed 's/^NROS[[:space:]]*//; s/^NROS//')"
    printf '%s\n' "$rev"
}

detect_current_nros_revision_quiet() {
    revision="${CURRENT_DETECTED_NROS_REVISION:-}"
    [ -n "$revision" ] || revision="$(detect_nros_revision 2>/dev/null || true)"
    printf '%s\n' "$revision"
}

nros_revision_at_least() {
    local required_major="$1" required_minor="$2" required_patch="$3"
    local revision revision_core old_ifs major minor patch

    revision="$(detect_current_nros_revision_quiet)"
    revision_core="${revision%%-*}"
    old_ifs="$IFS"
    IFS='.'
    set -- $revision_core
    IFS="$old_ifs"
    major="${1:-0}"
    minor="${2:-0}"
    patch="${3:-0}"
    patch="${patch%%[!0-9]*}"

    case "$major:$minor:$patch:$required_major:$required_minor:$required_patch" in
        *[!0-9:]*) return 1 ;;
    esac
    [ "$major" -gt "$required_major" ] && return 0
    [ "$major" -lt "$required_major" ] && return 1
    [ "$minor" -gt "$required_minor" ] && return 0
    [ "$minor" -lt "$required_minor" ] && return 1
    [ "$patch" -ge "$required_patch" ]
}

appcenter_has_native_mobile_save_support() {
    local factory_template="/rom$TPL"

    [ -f "$factory_template" ] || factory_template="$TPL"
    [ -f "$factory_template" ] || return 1
    grep -Fq "appcenter-open-mobile-style" "$factory_template" 2>/dev/null || return 1
    grep -Fq "html body div.cbi-page-actions > input.cbi-button-apply" "$factory_template" 2>/dev/null
}

normalize_nradio_model() {
    raw_model="$1"
    raw_board="$2"
    raw_compat="$3"
    combined="$(printf '%s %s %s' "$raw_model" "$raw_board" "$raw_compat" | tr '[:lower:]' '[:upper:]')"

    case "$combined" in
        *HC-WT9194*|*HCMT7987-S256*)
            printf '%s\n' 'NRadio_AK68-798'
            ;;
        *HC-WT9108*)
            printf '%s\n' 'NRadio_C8-668'
            ;;
        *HC-WT9104*)
            printf '%s\n' 'NRadio_C8-688'
            ;;
        *HC-WT9302*|*HCMT7987-NAND*)
            printf '%s\n' 'NRadio_C8-788'
            ;;
        *HC-WT9120*)
            printf '%s\n' 'NRadio_C5800-650'
            ;;
        *HC-WT9126*)
            printf '%s\n' 'NRadio_C5800-688'
            ;;
        *HC-WT9111*|*NRADIO-WT9111*)
            printf '%s\n' 'NRadio_NBCPE'
            ;;
        *HC-WT9500*)
            printf '%s\n' 'NRadio_C2000Ultra'
            ;;
        *HC-WT9303*)
            printf '%s\n' 'NRadio_C2000MAX'
            ;;
        *SPREADTRUM\ UDX710_4H10*|*SPRD,UDX710_4H10*|*UDX710-MODULE*|*UDX710\ MODULE*|*RG200U-CN*)
            printf '%s\n' 'NRadio_C2000Pro'
            ;;
        *)
            printf '%s\n' ''
            ;;
    esac
}

is_supported_nros_revision() {
    revision="$1"
    model="${2:-}"

    case "$revision" in
        2.*)
            return 0
            ;;
        1.9.*)
            [ "$model" = 'NRadio_C5800-650' ] && return 0
            return 1
            ;;
        *)
            return 1
            ;;
    esac
}

c2000_storage_swap_model_supported() {
    case "${1:-${CURRENT_DETECTED_MODEL:-}}" in
        NRadio_C2000MAX|NRadio_C2000Ultra) return 0 ;;
        *) return 1 ;;
    esac
}

detect_c2000max_storage_mount() {
    local mount_path

    mount_path="$(awk '$1 ~ /^\/dev\/mmcblk[0-9]+p[0-9]+$/ && $2 ~ /^\/tmp\/storage\// { print $2; exit }' /proc/mounts 2>/dev/null || true)"
    [ -n "$mount_path" ] && {
        printf '%s\n' "$mount_path"
        return 0
    }

    mount_path="$(awk '$1 ~ /^\/dev\/mmcblk[0-9]+p[0-9]+$/ && $2 == "/mnt/app_data" { print $2; exit }' /proc/mounts 2>/dev/null || true)"
    [ -n "$mount_path" ] && {
        printf '%s\n' "$mount_path"
        return 0
    }

    return 1
}

openlist_dir_is_writable() {
    local target_dir="$1"
    local probe_file

    [ -d "$target_dir" ] || return 1
    probe_file="$target_dir/.nradio-openlist-write-test.$$"
    : > "$probe_file" 2>/dev/null || return 1
    rm -f "$probe_file" 2>/dev/null || true
    return 0
}

resolve_openlist_storage_paths() {
    local prepare_mode="${1:-}"
    local storage_base storage_mount storage_path openlist_bin_real openlist_existing_root openlist_config_data_dir

    storage_base=""

    if [ -L "$OPENLIST_LINK_PATH" ]; then
        openlist_bin_real="$(readlink -f "$OPENLIST_LINK_PATH" 2>/dev/null || true)"
        case "$openlist_bin_real" in
            */openlist/bin/openlist)
                openlist_existing_root="$(dirname "$(dirname "$openlist_bin_real")")"
                storage_base="$(dirname "$openlist_existing_root")"
                ;;
        esac
    fi

    if [ -z "$storage_base" ] && command -v uci >/dev/null 2>&1; then
        openlist_config_data_dir="$(uci -q get openlist.main.data_dir 2>/dev/null || true)"
        case "$openlist_config_data_dir" in
            */openlist/data)
                openlist_existing_root="${openlist_config_data_dir%/data}"
                storage_base="$(dirname "$openlist_existing_root")"
                ;;
        esac
    fi

    if [ -z "$storage_base" ] && openlist_dir_is_writable /mnt/app_data; then
        storage_base="/mnt/app_data"
    fi

    if [ -z "$storage_base" ]; then
        storage_mount="$(detect_c2000max_storage_mount 2>/dev/null || true)"
        if [ -n "$storage_mount" ] && openlist_dir_is_writable "$storage_mount"; then
            storage_base="$storage_mount"
        fi
    fi

    if [ -z "$storage_base" ]; then
        for storage_path in /tmp/storage/*; do
            [ -d "$storage_path" ] || continue
            openlist_dir_is_writable "$storage_path" || continue
            storage_base="$storage_path"
            break
        done
    fi

    if [ -z "$storage_base" ] && [ -f "$ROOTFS_2ND_STORAGE_MARKER" ] && openlist_dir_is_writable "$ROOTFS_2ND_STORAGE_MOUNT_POINT"; then
        storage_base="$ROOTFS_2ND_STORAGE_MOUNT_POINT"
    fi

    [ -n "$storage_base" ] || storage_base="/overlay/app_data"

    if [ "$prepare_mode" = "prepare" ]; then
        mkdir -p "$storage_base" || die "创建 OpenList 存储根失败：$storage_base"
        ensure_dir_writable "$storage_base" "$storage_base"
    fi

    OPENLIST_ROOT_DIR="$storage_base/openlist"
    OPENLIST_BIN_DIR="$OPENLIST_ROOT_DIR/bin"
    OPENLIST_BIN_PATH="$OPENLIST_BIN_DIR/openlist"
    OPENLIST_DATA_DIR="$OPENLIST_ROOT_DIR/data"
    OPENLIST_TEMP_DIR="$OPENLIST_ROOT_DIR/tmp"
    OPENLIST_LOG_PATH="$OPENLIST_ROOT_DIR/openlist.log"
    OPENLIST_DEFAULT_DATA_DIR="$OPENLIST_DATA_DIR"
    OPENLIST_DEFAULT_TEMP_DIR="$OPENLIST_TEMP_DIR"
    OPENLIST_DEFAULT_LOG_PATH="$OPENLIST_LOG_PATH"
}

prepare_openlist_install_dirs() {
    local root_link_target root_real root_parent

    if [ -L "$OPENLIST_ROOT_DIR" ]; then
        root_link_target="$(readlink "$OPENLIST_ROOT_DIR" 2>/dev/null || true)"
        [ -n "$root_link_target" ] || die "OpenList 存储扩展链接读取失败：$OPENLIST_ROOT_DIR"
        case "$root_link_target" in
            /*)
                root_real="$root_link_target"
                ;;
            *)
                root_parent="$(dirname "$OPENLIST_ROOT_DIR")"
                root_real="$root_parent/$root_link_target"
                ;;
        esac
        log "提示: OpenList 检测到存储扩展链接：$OPENLIST_ROOT_DIR -> $root_real"
        log "提示: 正在修复 OpenList 存储扩展目标目录..."
        mkdir -p "$root_real" "$root_real/bin" "$root_real/data" "$root_real/tmp" || die "创建 OpenList 存储扩展目标目录失败：$root_real"
    else
        log "提示: OpenList 使用普通存储目录：$OPENLIST_ROOT_DIR"
        mkdir -p "$OPENLIST_ROOT_DIR" "$OPENLIST_BIN_DIR" "$OPENLIST_DATA_DIR" "$OPENLIST_TEMP_DIR" || die "创建 OpenList 存储目录失败：$OPENLIST_ROOT_DIR"
    fi

    ensure_dir_writable "$OPENLIST_ROOT_DIR" "$OPENLIST_ROOT_DIR"
    ensure_dir_writable "$OPENLIST_BIN_DIR" "$OPENLIST_BIN_DIR"
    ensure_dir_writable "$OPENLIST_DATA_DIR" "$OPENLIST_DATA_DIR"
    ensure_dir_writable "$OPENLIST_TEMP_DIR" "$OPENLIST_TEMP_DIR"
}

get_mount_available_kib() {
    local mount_path="$1"
    local avail_kib

    [ -n "$mount_path" ] || return 1
    avail_kib="$(df -k "$mount_path" 2>/dev/null | awk 'NR == 2 { print $4 }' | tr -d '\r' || true)"
    case "$avail_kib" in
        ''|*[!0-9]*)
            return 1
            ;;
    esac

    printf '%s\n' "$avail_kib"
}

format_mib_or_gib() {
    local size_mib="${1:-0}"

    case "$size_mib" in
        ''|*[!0-9]*)
            return 1
            ;;
    esac

    if [ "$size_mib" -ge 1024 ] 2>/dev/null; then
        awk -v v="$size_mib" 'BEGIN { printf "%.1fG", v / 1024 }'
    else
        printf '%sM' "$size_mib"
    fi
}

require_c2000max_storage_ready() {
    local normalized_model="$1"
    local storage_mount storage_avail_kib storage_avail_mib storage_avail_display

    c2000_storage_swap_model_supported "$normalized_model" || return 0

    storage_mount="$(detect_c2000max_storage_mount 2>/dev/null || true)"
    [ -n "$storage_mount" ] || die "环境检测失败：当前机型为 $normalized_model，但未检测到 SD 存储卡，已停止继续安装"

    storage_avail_kib="$(get_mount_available_kib "$storage_mount" 2>/dev/null || true)"
    [ -n "$storage_avail_kib" ] || die "环境检测失败：当前机型为 $normalized_model，但无法识别 SD 存储卡空间大小，已停止继续安装"

    storage_avail_mib="$((storage_avail_kib / 1024))"
    storage_avail_display="$(format_mib_or_gib "$storage_avail_mib" 2>/dev/null || printf '%sM' "$storage_avail_mib")"
    log "检测到 ${normalized_model#NRadio_} SD 存储卡：$storage_mount，可用空间约 ${storage_avail_display}"
}

require_supported_nradio_model_environment() {
    raw_model="$(detect_board_model_raw)"
    raw_board="$(detect_board_name_raw)"
    raw_compat="$(detect_board_compatible_raw)"
    nros_revision="$(detect_nros_revision)"
    normalized_model="$(normalize_nradio_model "$raw_model" "$raw_board" "$raw_compat")"

    [ -n "$normalized_model" ] || die "环境检测失败：当前设备不在支持列表内 (model=$raw_model board_name=$raw_board)"
    [ -n "$nros_revision" ] || die "环境检测失败：无法识别当前 NROS 版本"
    is_supported_nros_revision "$nros_revision" "$normalized_model" || die "环境检测失败：当前系统不是受支持的 NROS 1.9/2.x (model=$normalized_model revision=$nros_revision)"

    CURRENT_DETECTED_MODEL="$normalized_model"
    CURRENT_DETECTED_NROS_REVISION="$nros_revision"
    log "检测到机型：$normalized_model NROS$nros_revision"
    require_c2000max_storage_ready "$normalized_model"
}

log_nradio_oem_environment_hint() {
    appcenter_profile="$(detect_appcenter_environment_profile 2>/dev/null || true)"
    case "$appcenter_profile" in
        ak798_base|ak798_compat)
            log "环境检测: AK68-798 16 MiB NOR 轻量模式，应用商店通过 4 > 4 > 1 创建或更新"
            log "提示: 总脚本建议放在 /tmp；当前开放轻量商店维护与统一体检"
            return 0
            ;;
        legacy_appcenter)
            log "环境检测: 已检测到 NRadio 应用商店"
            return 0
            ;;
        c2000pro_compat)
            log "环境检测: 已检测到 C2000Pro 兼容应用商店层"
            return 0
            ;;
        c2000pro_base)
            missing_paths="$(collect_missing_nradio_paths)"
            log "环境检测: C2000Pro 原厂 NRadio/QuecHALO UI，未检测到旧应用商店"
            log "提示: 可进入主菜单；写入应用商店前会先生成 C2000Pro 兼容商店层"
            [ -n "$missing_paths" ] && log "missing: $missing_paths"
            return 0
            ;;
    esac

    missing_paths="$(collect_missing_nradio_paths)"
    log "环境检测: 未检测到 NRadio 应用商店"
    log "提示: 不支持标准 OpenWrt; 请使用 NRadio 官方固件"
    [ -n "$missing_paths" ] && log "missing: $missing_paths"
}


require_nradio_appcenter_startup_environment() {
    appcenter_profile="$(detect_appcenter_environment_profile 2>/dev/null || true)"
    case "$appcenter_profile" in
        legacy_appcenter|c2000pro_compat|c2000pro_base|ak798_compat|ak798_base)
            return 0
            ;;
    esac

    missing_paths="$(collect_missing_nradio_paths)"
    missing_suffix=""
    [ -n "$missing_paths" ] && missing_suffix=" (missing: $missing_paths)"
    die "unsupported firmware: 未检测到 NRadio 应用商店环境；本脚本仅适用于带 NRadio 应用商店的官方固件，并非标准 OpenWrt$missing_suffix"
}

require_nradio_oem_appcenter() {
    if is_current_model_ak798; then
        ensure_ak798_compat_appcenter
        return 0
    fi
    if is_c2000pro_appcenter_environment; then
        ensure_c2000pro_compat_appcenter
        return 0
    fi

    has_nradio_oem_appcenter && return 0
    missing_paths="$(collect_missing_nradio_paths)"
    missing_suffix=""
    [ -n "$missing_paths" ] && missing_suffix=" (missing: $missing_paths)"
    die "unsupported firmware: 未检测到 NRadio 应用商店环境；本脚本仅适用于带 NRadio 应用商店的官方固件，并非标准 OpenWrt$missing_suffix"
}

prompt_with_default() {
    prompt="$1"
    default_value="$2"
    if [ -n "$default_value" ]; then
        printf '%s [%s]: ' "$prompt" "$default_value"
    else
        printf '%s: ' "$prompt"
    fi
    ui_read_line || die "input cancelled"
    PROMPT_RESULT="$UI_READ_RESULT"
    [ -n "$PROMPT_RESULT" ] || PROMPT_RESULT="$default_value"
}

require_root() {
    [ "$(id -u)" = "0" ] || die "please run as root"
}

release_script_lock() {
    [ "${LOCK_OWNER:-0}" = '1' ] || return 0
    [ "$LOCK_DIR" = '/var/run/nradio-plugin-assistant.lock' ] || {
        log "警告: 拒绝清理非标准锁路径: $LOCK_DIR"
        LOCK_OWNER='0'
        return 1
    }
    if [ "$(cat "$LOCK_DIR/pid" 2>/dev/null || true)" = "$$" ] &&
       lock_pid_matches_owner "$LOCK_DIR" "$$"; then
        rm -f "$LOCK_DIR/pid" "$LOCK_DIR/starttime"
        for release_attempt in 1 2 3; do
            rmdir "$LOCK_DIR" 2>/dev/null && break
            sleep 1
        done
    fi
    LOCK_OWNER='0'
}

process_starttime() {
    process_pid="$1"
    case "$process_pid" in
        ''|*[!0-9]*) return 1 ;;
    esac
    [ -r "/proc/$process_pid/stat" ] || return 1
    sed 's/^[^)]*) //' "/proc/$process_pid/stat" 2>/dev/null | awk '{print $20}'
}

lock_pid_matches_owner() {
    lock_path="$1"
    lock_process_pid="$2"
    case "$lock_process_pid" in
        ''|*[!0-9]*) return 1 ;;
    esac
    kill -0 "$lock_process_pid" 2>/dev/null || return 1

    stored_starttime="$(cat "$lock_path/starttime" 2>/dev/null || true)"
    current_starttime="$(process_starttime "$lock_process_pid" 2>/dev/null || true)"
    if [ -n "$stored_starttime" ]; then
        [ -n "$current_starttime" ] && [ "$stored_starttime" = "$current_starttime" ]
        return
    fi

    lock_cmdline="$(tr '\000' ' ' < "/proc/$lock_process_pid/cmdline" 2>/dev/null || true)"
    case "$lock_cmdline" in
        *ssh-nradio-plugin-installer.sh*|*nradio-plugin-assistant*|*nradio-plugin-uninstall*) return 0 ;;
    esac
    return 1
}

write_lock_identity() {
    local lock_path="$1" current_starttime
    current_starttime="$(process_starttime "$$" 2>/dev/null || true)"
    [ -n "$current_starttime" ] || return 1
    printf '%s\n' "$current_starttime" > "$lock_path/starttime" &&
        printf '%s\n' "$$" > "$lock_path/pid"
}

reclaim_initialized_task_lock() {
    local path="$1" checker="$2" old_pid old_start
    [ -d "$path" ] && [ ! -L "$path" ] || return 1
    old_pid="$(cat "$path/pid" 2>/dev/null || true)"
    old_start="$(cat "$path/starttime" 2>/dev/null || true)"
    case "$old_pid" in ''|*[!0-9]*) return 1 ;; esac
    case "$old_start" in ''|*[!0-9]*) return 1 ;; esac
    mkdir "$path/reap" 2>/dev/null || return 1
    if [ "$(cat "$path/pid" 2>/dev/null || true)" = "$old_pid" ] &&
       [ "$(cat "$path/starttime" 2>/dev/null || true)" = "$old_start" ] &&
       ! "$checker" "$path" "$old_pid"; then
        rm -f "$path/pid" "$path/starttime" || { rmdir "$path/reap"; return 1; }
        rmdir "$path/reap" && rmdir "$path"
        return $?
    fi
    rmdir "$path/reap" 2>/dev/null || true
    return 1
}

acquire_script_lock() {
    [ "$LOCK_DIR" = '/var/run/nradio-plugin-assistant.lock' ] || die "拒绝使用非标准脚本锁路径: $LOCK_DIR"
    mkdir -p "$(dirname "$LOCK_DIR")" >/dev/null 2>&1 || true

    if mkdir "$LOCK_DIR" 2>/dev/null; then
        write_lock_identity "$LOCK_DIR" || die "写入脚本锁身份失败: $LOCK_DIR"
        LOCK_OWNER='1'
        return 0
    fi

    lock_pid="$(cat "$LOCK_DIR/pid" 2>/dev/null || true)"
    if lock_pid_matches_owner "$LOCK_DIR" "$lock_pid"; then
        die "已有其他 nradio-plugin-assistant 实例正在运行（pid $lock_pid）"
    fi

    reclaim_initialized_task_lock "$LOCK_DIR" lock_pid_matches_owner ||
        die "脚本锁正在初始化、回收或身份不完整，请核对后重试: $LOCK_DIR"
    mkdir "$LOCK_DIR" 2>/dev/null || die "获取脚本锁失败: $LOCK_DIR"
    write_lock_identity "$LOCK_DIR" || die "写入脚本锁身份失败: $LOCK_DIR"
    LOCK_OWNER='1'
    log "提示: 已清除过期的脚本锁"
}

download_file() {
    url="$1"
    out="$2"
    tmp_out="$out.tmp"
    tmp_url="$tmp_out.url"
    keep_partial="${DOWNLOAD_KEEP_PARTIAL:-0}"

    [ -n "$url" ] || return 1

    if [ "$keep_partial" = '1' ]; then
        previous_url="$(cat "$tmp_url" 2>/dev/null || true)"
        if [ -s "$tmp_out" ] && [ "$previous_url" != "$url" ]; then
            rm -f "$tmp_out" "$tmp_url" 2>/dev/null || return 1
        fi
        printf '%s\n' "$url" > "$tmp_url" || return 1
    else
        rm -f "$tmp_url" 2>/dev/null || true
    fi

    printf '正在下载: %s\n' "$(format_download_source_label "$url")" >&2

    if ! download_file_once "$url" "$tmp_out"; then
        if [ "$keep_partial" = '1' ] && [ -s "$tmp_out" ]; then
            partial_size="$(get_file_size_bytes "$tmp_out")"
            if [ "$partial_size" -ge "$DOWNLOAD_PARTIAL_RETRY_MIN_BYTES" ] 2>/dev/null && should_retry_partial_download; then
                saved_stall_time="$DOWNLOAD_STALL_TIME"
                saved_stall_speed="$DOWNLOAD_STALL_SPEED"
                DOWNLOAD_STALL_TIME="$DOWNLOAD_PARTIAL_RETRY_STALL_TIME"
                DOWNLOAD_STALL_SPEED="$DOWNLOAD_PARTIAL_RETRY_STALL_SPEED"
                log "提示: 当前镜像已下载 $(format_bytes_human "$partial_size")，正在放宽限速后继续续传..."
                if download_file_once "$url" "$tmp_out"; then
                    DOWNLOAD_STALL_TIME="$saved_stall_time"
                    DOWNLOAD_STALL_SPEED="$saved_stall_speed"
                else
                    DOWNLOAD_STALL_TIME="$saved_stall_time"
                    DOWNLOAD_STALL_SPEED="$saved_stall_speed"
                    return 1
                fi
            else
                return 1
            fi
        else
            if [ "$keep_partial" != '1' ] || [ ! -s "$tmp_out" ]; then
                rm -f "$tmp_out"
            fi
            return 1
        fi
    fi

    [ -s "$tmp_out" ] || { rm -f "$tmp_out" "$tmp_url"; return 1; }
    mv "$tmp_out" "$out" || return 1
    rm -f "$tmp_url" 2>/dev/null || true
}

should_retry_partial_download() {
    retry_tool="${LAST_DOWNLOAD_TOOL:-}"
    retry_rc="${LAST_DOWNLOAD_RC:-1}"

    case "$retry_tool:$retry_rc" in
        curl:18|curl:28)
            return 0
            ;;
        curl:*)
            return 1
            ;;
        *)
            return 0
            ;;
    esac
}

download_file_once() {
    url="$1"
    tmp_out="$2"
    keep_partial="${DOWNLOAD_KEEP_PARTIAL:-0}"
    LAST_DOWNLOAD_TOOL=''
    LAST_DOWNLOAD_RC='0'

    if [ "$keep_partial" != '1' ]; then
        rm -f "$tmp_out" 2>/dev/null || true
    fi

    if command -v curl >/dev/null 2>&1; then
        LAST_DOWNLOAD_TOOL='curl'
        curl_restart_attempted=0
        while :; do
            set -- curl -LfS --silent --show-error --connect-timeout "$DOWNLOAD_CONNECT_TIMEOUT" --max-time "$DOWNLOAD_MAX_TIME" --speed-time "$DOWNLOAD_STALL_TIME" --speed-limit "$DOWNLOAD_STALL_SPEED" --retry "$DOWNLOAD_RETRY" --retry-delay 2
            curl_resuming=0
            if [ -s "$tmp_out" ]; then
                curl_resuming=1
                set -- "$@" -C -
            fi
            case "$url" in
                https://api.github.com/repos/*/releases/assets/*|https://gh-proxy.com/https://api.github.com/repos/*/releases/assets/*)
                    set -- "$@" -H 'Accept: application/octet-stream' -H 'X-GitHub-Api-Version: 2022-11-28' -H 'User-Agent: nradio-plugin-assistant'
                    ;;
            esac
            if run_download_with_progress "$url" "$tmp_out" "$@" "$url" -o "$tmp_out"; then
                LAST_DOWNLOAD_RC='0'
                break
            else
                LAST_DOWNLOAD_RC="$?"
            fi
            if [ "$LAST_DOWNLOAD_RC" = '33' ] && [ "$curl_resuming" = '1' ] && [ "$curl_restart_attempted" = '0' ]; then
                curl_restart_attempted=1
                log "提示: 当前地址不支持续传，正在重新完整下载..." >&2
                rm -f "$tmp_out" || return 1
                continue
            fi
            if [ "$keep_partial" != '1' ] || [ ! -s "$tmp_out" ]; then
                rm -f "$tmp_out"
            fi
            return 1
        done
    elif command -v wget >/dev/null 2>&1; then
        LAST_DOWNLOAD_TOOL='wget'
        case "$DOWNLOAD_RETRY" in
            ''|*[!0-9]*) wget_tries='1' ;;
            *) wget_tries=$((DOWNLOAD_RETRY + 1)) ;;
        esac
        wget_help="$(wget --help 2>&1 || true)"
        if printf '%s\n' "$wget_help" | grep -Eq -- '(^|[[:space:],])-t([[:space:],]|$)|--tries'; then
            if run_download_with_progress "$url" "$tmp_out" wget -q -c -T "$DOWNLOAD_STALL_TIME" -t "$wget_tries" -O "$tmp_out" "$url"; then
                wget_rc='0'
            else
                wget_rc="$?"
            fi
        else
            if run_download_with_progress "$url" "$tmp_out" wget -q -c -T "$DOWNLOAD_STALL_TIME" -O "$tmp_out" "$url"; then
                wget_rc='0'
            else
                wget_rc="$?"
            fi
        fi
        if [ "$wget_rc" -eq 0 ]; then
            LAST_DOWNLOAD_RC='0'
        else
            LAST_DOWNLOAD_RC="$wget_rc"
            if command -v uclient-fetch >/dev/null 2>&1; then
                log "提示: wget 下载失败，正在尝试 uclient-fetch 后备下载..." >&2
                rm -f "$tmp_out" 2>/dev/null || true
                LAST_DOWNLOAD_TOOL='uclient-fetch'
                if run_download_with_progress "$url" "$tmp_out" uclient-fetch -T "$DOWNLOAD_MAX_TIME" -q -O "$tmp_out" "$url"; then
                    LAST_DOWNLOAD_RC='0'
                else
                    LAST_DOWNLOAD_RC="$?"
                    if [ "$keep_partial" != '1' ] || [ ! -s "$tmp_out" ]; then
                        rm -f "$tmp_out"
                    fi
                    return 1
                fi
            else
                if [ "$keep_partial" != '1' ] || [ ! -s "$tmp_out" ]; then
                    rm -f "$tmp_out"
                fi
                return 1
            fi
        fi
    elif command -v uclient-fetch >/dev/null 2>&1; then
        LAST_DOWNLOAD_TOOL='uclient-fetch'
        if run_download_with_progress "$url" "$tmp_out" uclient-fetch -T "$DOWNLOAD_MAX_TIME" -q -O "$tmp_out" "$url"; then
            LAST_DOWNLOAD_RC='0'
        else
            LAST_DOWNLOAD_RC="$?"
            if [ "$keep_partial" != '1' ] || [ ! -s "$tmp_out" ]; then
                rm -f "$tmp_out"
            fi
            return 1
        fi
    else
        die "系统缺少 curl、wget 或 uclient-fetch，无法下载文件"
    fi

    return 0
}

download_from_mirrors() {
    rel="$1"
    out="$2"
    base_list="$(prioritize_github_proxy_urls "${3:-$OPENCLASH_MIRRORS}")"
    mirror_count=0
    mirror_index=0
    LAST_DOWNLOAD_SOURCE=''

    for base in $base_list; do
        mirror_count=$((mirror_count + 1))
    done

    for base in $base_list; do
        mirror_index=$((mirror_index + 1))
        if download_file "$base/$rel" "$out"; then
            LAST_DOWNLOAD_SOURCE="$base"
            return 0
        fi
        if [ "$mirror_index" -lt "$mirror_count" ]; then
            log "提示: 当前镜像下载未完成，准备切换到下一个镜像..."
        fi
    done

    return 1
}

extract_url_host() {
    url="$1"
    host="${url#*://}"
    host="${host%%/*}"
    host="${host%%:*}"
    printf '%s\n' "$host"
}

extract_url_filename() {
    url="$1"
    path_part="${url#*://}"
    path_part="${path_part#*/}"
    path_part="${path_part%%\?*}"
    file_part="${path_part##*/}"

    case "$url" in
        *response-content-disposition=*)
            disposition_name="$(printf '%s\n' "$url" | sed -n 's/.*[?&]response-content-disposition=[^&]*filename%3D\([^&]*\).*/\1/p' | tail -n 1)"
            disposition_name="${disposition_name%%\%*}"
            if [ -n "$disposition_name" ]; then
                file_part="$disposition_name"
            fi
            ;;
    esac

    [ -n "$file_part" ] || file_part="未知文件"
    printf '%s\n' "$file_part"
}

format_download_source_label() {
    url="$1"
    host="$(extract_url_host "$url")"
    filename="$(extract_url_filename "$url")"

    case "$host" in
        gh-proxy.com)
            printf 'GitHub 加速（%s / %s）\n' "$host" "$filename"
            ;;
        release-assets.githubusercontent.com)
            printf 'GitHub 官方 CDN（%s / %s）\n' "$host" "$filename"
            ;;
        raw.githubusercontent.com)
            printf 'GitHub Raw（%s / %s）\n' "$host" "$filename"
            ;;
        github.com|api.github.com)
            printf 'GitHub 官方（%s / %s）\n' "$host" "$filename"
            ;;
        "")
            printf '%s\n' "$filename"
            ;;
        *)
            printf '%s / %s\n' "$host" "$filename"
            ;;
    esac
}

probe_host_ping_stats() {
    host="$1"
    ping_loss="100"
    ping_avg="999999000"

    if command -v ping >/dev/null 2>&1; then
        ping_output="$(ping -c "$OPENCLASH_CDN_PING_COUNT" -W "$OPENCLASH_CDN_PING_TIMEOUT" "$host" 2>/dev/null || true)"
        ping_loss_parsed="$(printf '%s\n' "$ping_output" | sed -n 's/.* \([0-9][0-9]*\)% packet loss.*/\1/p' | tail -n 1)"
        ping_avg_parsed="$(printf '%s\n' "$ping_output" | sed -n 's/^.*= *[^/]*\/\([^/]*\)\/.*$/\1/p' | tail -n 1)"
        [ -n "$ping_loss_parsed" ] && ping_loss="$ping_loss_parsed"
        if [ -n "$ping_avg_parsed" ]; then
            case "$ping_avg_parsed" in
                *.*)
                    ping_avg_int="${ping_avg_parsed%%.*}"
                    ping_avg_frac="${ping_avg_parsed#*.}"
                    ;;
                *)
                    ping_avg_int="$ping_avg_parsed"
                    ping_avg_frac=""
                    ;;
            esac
            case "$ping_avg_int" in
                ''|*[!0-9]*)
                    ping_avg=""
                    ;;
                *)
                    ping_avg_frac="$(printf '%s000' "$ping_avg_frac" | cut -c1-3)"
                    case "$ping_avg_frac" in
                        ''|*[!0-9]*) ping_avg_frac='000' ;;
                    esac
                    ping_avg="${ping_avg_int}${ping_avg_frac}"
                    ;;
            esac
            [ -n "$ping_avg" ] || ping_avg="999999000"
        fi
    fi

    printf '%s|%s|%s\n' "$ping_loss" "$ping_avg" "$host"
}

format_probe_ping_avg_label() {
    ping_avg_raw="$1"

    case "$ping_avg_raw" in
        ''|*[!0-9]*)
            printf '超时\n'
            return 0
            ;;
    esac

    ping_avg_raw="$(printf '%s' "$ping_avg_raw" | sed 's/^0*//')"
    [ -n "$ping_avg_raw" ] || ping_avg_raw='0'

    if [ "$ping_avg_raw" = '999999000' ]; then
        printf '超时\n'
    else
        printf '%sms\n' "$(( (ping_avg_raw + 500) / 1000 ))"
    fi
}

prioritize_github_proxy_urls() (
    # 只对已配置 gh-proxy 的列表应用固定优先级；自定义非代理源保持原序。
    case " $1" in
        *' https://gh-proxy.com/https://'*) ;;
        *) printf '%s\n' "$1"; return 0 ;;
    esac
    proxy_urls=''
    official_urls=''
    other_urls=''
    seen_urls=' '
    for candidate_url in $1; do
        case "$seen_urls" in *" $candidate_url "*) continue ;; esac
        seen_urls="$seen_urls$candidate_url "
        case "$candidate_url" in
            https://gh-proxy.com/https://*) proxy_urls="$proxy_urls $candidate_url" ;;
            https://github.com/*|https://raw.githubusercontent.com/*|https://api.github.com/*|https://nightly.link/*)
                official_urls="$official_urls $candidate_url"
                ;;
            *) other_urls="$other_urls $candidate_url" ;;
        esac
    done
    ordered_urls="$proxy_urls$official_urls$other_urls"
    printf '%s\n' "${ordered_urls# }"
)

reorder_urls_by_host_rank() {
    url_list="$1"
    ranked_hosts="$2"
    ordered_urls=""

    for ranked_host in $ranked_hosts; do
        for url in $url_list; do
            [ "$(extract_url_host "$url")" = "$ranked_host" ] || continue
            if [ -n "$ordered_urls" ]; then
                ordered_urls="$ordered_urls $url"
            else
                ordered_urls="$url"
            fi
        done
    done

    for url in $url_list; do
        url_host="$(extract_url_host "$url")"
        host_found='0'
        for ranked_host in $ranked_hosts; do
            if [ "$url_host" = "$ranked_host" ]; then
                host_found='1'
                break
            fi
        done
        [ "$host_found" = '1' ] && continue
        if [ -n "$ordered_urls" ]; then
            ordered_urls="$ordered_urls $url"
        else
            ordered_urls="$url"
        fi
    done

    prioritize_github_proxy_urls "$ordered_urls"
}

build_urls_from_base_list() {
    rel="$1"
    base_list="$2"

    for base in $base_list; do
        printf '%s/%s\n' "$base" "$rel"
    done
}

append_unique_list_item() {
    current_list="$1"
    candidate_item="$2"

    [ -n "$candidate_item" ] || {
        printf '%s\n' "$current_list"
        return 0
    }

    for existing_item in $current_list; do
        [ "$existing_item" = "$candidate_item" ] && {
            printf '%s\n' "$current_list"
            return 0
        }
    done

    if [ -n "$current_list" ]; then
        printf '%s %s\n' "$current_list" "$candidate_item"
    else
        printf '%s\n' "$candidate_item"
    fi
}

summarize_url_hosts() {
    host_list=""

    for url in "$@"; do
        [ -n "$url" ] || continue
        host="$(extract_url_host "$url" 2>/dev/null || true)"
        [ -n "$host" ] || continue
        host_list="$(append_unique_list_item "$host_list" "$host")"
    done

    printf '%s\n' "$host_list"
}

find_probe_url_for_host() {
    lookup_host="$1"
    shift

    for url_list in "$@"; do
        for url in $url_list; do
            [ "$(extract_url_host "$url")" = "$lookup_host" ] || continue
            printf '%s\n' "$url"
            return 0
        done
    done

    return 1
}

probe_url_http_ms() {
    probe_url="$1"
    probe_ms="999999"

    command -v curl >/dev/null 2>&1 || {
        printf '%s\n' "$probe_ms"
        return 0
    }

    probe_out="$(curl -fL -I -o /dev/null -sS --connect-timeout "$CDN_HTTP_PROBE_CONNECT_TIMEOUT" --max-time "$CDN_HTTP_PROBE_MAX_TIME" -w '%{http_code}|%{time_starttransfer}' "$probe_url" 2>/dev/null)" || probe_out='000|0'
    probe_code="${probe_out%%|*}"
    probe_time="${probe_out#*|}"

    if [ -n "$probe_time" ] && [ "$probe_code" -ge 200 ] && [ "$probe_code" -lt 300 ]; then
        probe_ms="$(printf '%s\n' "$probe_time" | awk '($1 ~ /^[0-9.]+$/) { printf "%d\n", ($1 * 1000) + 0.5 }')"
        [ -n "$probe_ms" ] || probe_ms="999999"
        printf '%s\n' "$probe_ms"
        return 0
    fi

    probe_out="$(curl -fL -r 0-0 -o /dev/null -sS --connect-timeout "$CDN_HTTP_PROBE_CONNECT_TIMEOUT" --max-time "$CDN_HTTP_PROBE_MAX_TIME" -w '%{http_code}|%{time_starttransfer}' "$probe_url" 2>/dev/null)" || probe_out='000|0'
    probe_code="${probe_out%%|*}"
    probe_time="${probe_out#*|}"

    if [ -n "$probe_time" ] && [ "$probe_code" -ge 200 ] && [ "$probe_code" -lt 300 ]; then
        probe_ms="$(printf '%s\n' "$probe_time" | awk '($1 ~ /^[0-9.]+$/) { printf "%d\n", ($1 * 1000) + 0.5 }')"
        [ -n "$probe_ms" ] || probe_ms="999999"
    fi

    printf '%s\n' "$probe_ms"
}

probe_url_partial_download_ms() {
    probe_url="$1"
    probe_ms="999999"
    probe_range_end="${2:-262143}"
    probe_min_bytes="${3:-1}"

    command -v curl >/dev/null 2>&1 || {
        printf '%s\n' "$probe_ms"
        return 0
    }

    probe_out="$(curl -fL -r "0-$probe_range_end" -o /dev/null -sS --connect-timeout "$CDN_HTTP_PROBE_CONNECT_TIMEOUT" --max-time "$CDN_HTTP_PROBE_MAX_TIME" -w '%{http_code}|%{time_total}|%{size_download}' "$probe_url" 2>/dev/null)" || probe_out='000|0|0'
    probe_code="${probe_out%%|*}"
    probe_rest="${probe_out#*|}"
    probe_time="${probe_rest%%|*}"
    probe_size="${probe_rest##*|}"

    if [ -n "$probe_time" ] && [ "$probe_code" -ge 200 ] && [ "$probe_code" -lt 300 ] && [ "${probe_size:-0}" -ge "$probe_min_bytes" ] 2>/dev/null; then
        probe_ms="$(printf '%s\n' "$probe_time" | awk '($1 ~ /^[0-9.]+$/) { printf "%d\n", ($1 * 1000) + 0.5 }')"
        [ -n "$probe_ms" ] || probe_ms="999999"
    fi

    printf '%s\n' "$probe_ms"
}

rank_hosts_by_partial_download_probe() {
    rank_prefix="$1"
    rank_label="$2"
    url_list="$3"
    rank_range_end="${4:-262143}"
    rank_min_bytes="${5:-1}"

    RANKED_URL_HOSTS=""
    case " $url_list" in
        *' https://gh-proxy.com/https://'*)
            RANKED_URL_HOSTS="$(summarize_url_hosts $(prioritize_github_proxy_urls "$url_list"))"
            log "下载源: $rank_label 使用 gh-proxy 优先，失败自动回退"
            return 0
            ;;
    esac
    command -v curl >/dev/null 2>&1 || return 0
    [ -n "$url_list" ] || return 0

    rank_tmp="$WORKDIR/${rank_prefix}-partial-rank.txt"
    : > "$rank_tmp"

    log "镜像:   $rank_label 小包测速"
    _pdl_dir="$WORKDIR/${rank_prefix}-partial-parallel"
    mkdir -p "$_pdl_dir" 2>/dev/null
    _pdl_pids=''
    rank_index=1
    for url in $url_list; do
        _pdl_i=$rank_index
        _pdl_url="$url"
        (
            _host="$(extract_url_host "$_pdl_url")"
            _ms="$(probe_url_partial_download_ms "$_pdl_url" "$rank_range_end" "$rank_min_bytes")"
            printf '%09d|%09d|%s\n' "$_ms" "$_pdl_i" "$_host"
        ) > "$_pdl_dir/$rank_index" </dev/null &
        _pdl_pid="$!"
        if [ -n "$_pdl_pids" ]; then
            _pdl_pids="$_pdl_pids $_pdl_pid"
        else
            _pdl_pids="$_pdl_pid"
        fi
        ACTIVE_BACKGROUND_PIDS="$_pdl_pids"
        rank_index=$((rank_index + 1))
    done
    wait_for_pid_list $_pdl_pids
    ACTIVE_BACKGROUND_PIDS=''

    _pdl_n=1
    while [ "$_pdl_n" -lt "$rank_index" ]; do
        if [ -f "$_pdl_dir/$_pdl_n" ]; then
            _pdl_line="$(cat "$_pdl_dir/$_pdl_n")"
            if [ -n "$_pdl_line" ]; then
                _pdl_host="${_pdl_line##*|}"
                _pdl_ms="${_pdl_line%%|*}"
                _pdl_ms_clean="$(printf '%s' "$_pdl_ms" | sed 's/^0*//')"
                [ -n "$_pdl_ms_clean" ] || _pdl_ms_clean="0"
                if [ "$_pdl_ms_clean" = '999999' ]; then
                    _pdl_label="超时"
                else
                    _pdl_label="${_pdl_ms_clean}ms"
                fi
                log "下载:   $_pdl_host 小包=$_pdl_label"
                printf '%s\n' "$_pdl_line" >> "$rank_tmp"
            fi
        fi
        _pdl_n=$((_pdl_n + 1))
    done
    rm -rf "$_pdl_dir" 2>/dev/null

    RANKED_URL_HOSTS="$(sort -t '|' -k1,1 -k2,2 "$rank_tmp" | cut -d'|' -f3 | tr '\n' ' ' | sed 's/[[:space:]]*$//')"
}

refine_ranked_hosts_by_http_probe() {
    refine_prefix="$1"
    refine_label="$2"
    ranked_hosts="$3"
    shift 3

    command -v curl >/dev/null 2>&1 || return 0
    [ -n "$ranked_hosts" ] || return 0

    refine_probe_candidates="$WORKDIR/${refine_prefix}-cdn-probe-candidates.txt"
    refine_probe_results="$WORKDIR/${refine_prefix}-cdn-probe-results.txt"
    : > "$refine_probe_candidates"
    : > "$refine_probe_results"

    refine_index=1
    refine_candidate_count=0
    for refine_host in $ranked_hosts; do
        refine_url="$(find_probe_url_for_host "$refine_host" "$@" 2>/dev/null || true)"
        [ -n "$refine_url" ] || continue
        printf '%09d|%s|%s\n' "$refine_index" "$refine_host" "$refine_url" >> "$refine_probe_candidates"
        refine_candidate_count=$((refine_candidate_count + 1))
        refine_index=$((refine_index + 1))
        [ "$refine_candidate_count" -ge "$CDN_HTTP_PROBE_TOP_HOSTS" ] && break
    done

    [ "$refine_candidate_count" -ge 2 ] || return 0

    log "CDN:    $refine_label HTTP 延迟复测"
    _http_dir="$WORKDIR/${refine_prefix}-http-parallel"
    mkdir -p "$_http_dir" 2>/dev/null
    _http_i=0
    _http_pids=''
    while IFS='|' read -r refine_order refine_host refine_url; do
        [ -n "$refine_host" ] || continue
        _http_i=$((_http_i + 1))
        (
            _ms="$(probe_url_http_ms "$refine_url")"
            printf '%09d|%s|%s\n' "$_ms" "$refine_order" "$refine_host"
        ) > "$_http_dir/$_http_i" </dev/null &
        _http_pid="$!"
        if [ -n "$_http_pids" ]; then
            _http_pids="$_http_pids $_http_pid"
        else
            _http_pids="$_http_pid"
        fi
        ACTIVE_BACKGROUND_PIDS="$_http_pids"
    done < "$refine_probe_candidates"
    wait_for_pid_list $_http_pids
    ACTIVE_BACKGROUND_PIDS=''

    _http_n=1
    while [ "$_http_n" -le "$_http_i" ]; do
        if [ -f "$_http_dir/$_http_n" ]; then
            _http_line="$(cat "$_http_dir/$_http_n")"
            if [ -n "$_http_line" ]; then
                _http_host="${_http_line##*|}"
                _http_ms_raw="${_http_line%%|*}"
                _http_ms_val="$(printf '%s' "$_http_ms_raw" | sed 's/^0*//')"
                [ -n "$_http_ms_val" ] || _http_ms_val="0"
                if [ "$_http_ms_val" = '999999' ]; then
                    _http_label="超时"
                else
                    _http_label="${_http_ms_val}ms"
                fi
                log "HTTP:   $_http_host 首字节=$_http_label"
                printf '%s\n' "$_http_line" >> "$refine_probe_results"
            fi
        fi
        _http_n=$((_http_n + 1))
    done
    rm -rf "$_http_dir" 2>/dev/null

    refined_hosts="$(sort -t '|' -k1,1 -k2,2 "$refine_probe_results" | cut -d'|' -f3 | tr '\n' ' ' | sed 's/[[:space:]]*$//')"
    [ -n "$refined_hosts" ] || return 0

    merged_hosts="$refined_hosts"
    for refine_host in $ranked_hosts; do
        refine_found='0'
        for refined_host in $refined_hosts; do
            if [ "$refine_host" = "$refined_host" ]; then
                refine_found='1'
                break
            fi
        done
        [ "$refine_found" = '1' ] && continue
        merged_hosts="$merged_hosts $refine_host"
    done

    RANKED_URL_HOSTS="$(printf '%s\n' "$merged_hosts" | sed 's/^[[:space:]]*//; s/[[:space:]]*$//; s/[[:space:]][[:space:]]*/ /g')"
}

rank_url_list_hosts() {
    rank_prefix="$1"
    rank_label="$2"
    shift 2

    RANKED_URL_HOSTS=""
    if ! command -v ping >/dev/null 2>&1; then
        log "CDN:    $rank_label 缺少 ping，沿用默认顺序"
        return 0
    fi
    mkdir -p "$WORKDIR" >/dev/null 2>&1 || return 0

    hosts_tmp="$WORKDIR/${rank_prefix}-cdn-hosts.txt"
    rank_tmp="$WORKDIR/${rank_prefix}-cdn-rank.txt"
    ranked_hosts_tmp="$WORKDIR/${rank_prefix}-cdn-ranked-hosts.txt"
    : > "$hosts_tmp"
    : > "$rank_tmp"

    for url_list in "$@"; do
        for url in $url_list; do
            host="$(extract_url_host "$url")"
            [ -n "$host" ] || continue
            grep -Fx -- "$host" "$hosts_tmp" >/dev/null 2>&1 || printf '%s\n' "$host" >> "$hosts_tmp"
        done
    done

    [ -s "$hosts_tmp" ] || return 0

    log "CDN:    $rank_label 节点测速"
    _ping_dir="$WORKDIR/${rank_prefix}-ping-parallel"
    mkdir -p "$_ping_dir" 2>/dev/null
    _ping_pids=''
    rank_index=1
    while IFS= read -r host; do
        [ -n "$host" ] || continue
        (
            _result="$(probe_host_ping_stats "$host")"
            _loss="${_result%%|*}"
            _rest="${_result#*|}"
            _avg="${_rest%%|*}"
            case "$_avg" in
                ''|*[!0-9]*) _avg_sort='999999000' ;;
                *)
                    _avg_sort="$(printf '%s' "$_avg" | sed 's/^0*//')"
                    [ -n "$_avg_sort" ] || _avg_sort='0'
                    ;;
            esac
            printf '%03d|%09d|%09d|%s\n' "$_loss" "$_avg_sort" "$rank_index" "$host"
        ) > "$_ping_dir/$rank_index" </dev/null &
        _ping_pid="$!"
        if [ -n "$_ping_pids" ]; then
            _ping_pids="$_ping_pids $_ping_pid"
        else
            _ping_pids="$_ping_pid"
        fi
        ACTIVE_BACKGROUND_PIDS="$_ping_pids"
        rank_index=$((rank_index + 1))
    done < "$hosts_tmp"
    wait_for_pid_list $_ping_pids
    ACTIVE_BACKGROUND_PIDS=''

    _pi=1
    while [ "$_pi" -lt "$rank_index" ]; do
        if [ -f "$_ping_dir/$_pi" ]; then
            _pl="$(cat "$_ping_dir/$_pi")"
            if [ -n "$_pl" ]; then
                _ph="${_pl##*|}"
                _ploss="${_pl%%|*}"
                case "$_ploss" in
                    ''|*[!0-9]*) _ploss_val='100' ;;
                    *)
                        _ploss_val="$(printf '%s' "$_ploss" | sed 's/^0*//')"
                        [ -n "$_ploss_val" ] || _ploss_val='0'
                        ;;
                esac
                _ptmp="${_pl#*|}"
                _pavg_raw="${_ptmp%%|*}"
                _pavg_label="$(format_probe_ping_avg_label "$_pavg_raw")"
                log "ping:   $_ph 丢包=${_ploss_val}% 延迟=$_pavg_label"
                printf '%s\n' "$_pl" >> "$rank_tmp"
            fi
        fi
        _pi=$((_pi + 1))
    done
    rm -rf "$_ping_dir" 2>/dev/null

    sort -t '|' -k1,1 -k2,2 -k3,3 "$rank_tmp" | cut -d'|' -f4 > "$ranked_hosts_tmp"
    RANKED_URL_HOSTS="$(tr '\n' ' ' < "$ranked_hosts_tmp" | sed 's/[[:space:]]*$//')"
    [ -n "$RANKED_URL_HOSTS" ] || return 0
}

optimize_openclash_cdn_order() {
    [ "${OPENCLASH_CDN_RANKED:-0}" = '1' ] && return 0

    rank_url_list_hosts \
        "openclash" \
        "$OPENCLASH_DISPLAY_NAME" \
        "$OPENCLASH_MIRRORS" \
        "$OPENCLASH_CORE_VERSION_MIRRORS" \
        "$OPENCLASH_CORE_SMART_MIRRORS" \
        "$OPENCLASH_GEOASN_MIRRORS"
    [ -n "${RANKED_URL_HOSTS:-}" ] || return 0
    openclash_probe_urls="$(build_urls_from_base_list "version" "$OPENCLASH_MIRRORS")"
    refine_ranked_hosts_by_http_probe "openclash" "$OPENCLASH_DISPLAY_NAME" "$RANKED_URL_HOSTS" "$openclash_probe_urls"

    OPENCLASH_MIRRORS="$(reorder_urls_by_host_rank "$OPENCLASH_MIRRORS" "$RANKED_URL_HOSTS")"
    OPENCLASH_CORE_VERSION_MIRRORS="$(reorder_urls_by_host_rank "$OPENCLASH_CORE_VERSION_MIRRORS" "$RANKED_URL_HOSTS")"
    OPENCLASH_CORE_SMART_MIRRORS="$(reorder_urls_by_host_rank "$OPENCLASH_CORE_SMART_MIRRORS" "$RANKED_URL_HOSTS")"
    OPENCLASH_GEOASN_MIRRORS="$(reorder_urls_by_host_rank "$OPENCLASH_GEOASN_MIRRORS" "$RANKED_URL_HOSTS")"
    OPENCLASH_CDN_RANKED='1'

    log "CDN:    $OPENCLASH_DISPLAY_NAME 顺序 = $RANKED_URL_HOSTS"
}

optimize_adguardhome_cdn_order() {
    [ "${ADGUARDHOME_CDN_RANKED:-0}" = '1' ] && return 0

    rank_url_list_hosts \
        "adguardhome" \
        "AdGuardHome" \
        "$ADGUARDHOME_IPK_URLS" \
        "$ADGUARDHOME_CORE_MIRRORS"
    [ -n "${RANKED_URL_HOSTS:-}" ] || return 0
    refine_ranked_hosts_by_http_probe "adguardhome" "AdGuardHome" "$RANKED_URL_HOSTS" "$ADGUARDHOME_IPK_URLS"

    ADGUARDHOME_IPK_URLS="$(reorder_urls_by_host_rank "$ADGUARDHOME_IPK_URLS" "$RANKED_URL_HOSTS")"
    ADGUARDHOME_CORE_MIRRORS="$(reorder_urls_by_host_rank "$ADGUARDHOME_CORE_MIRRORS" "$RANKED_URL_HOSTS")"
    ADGUARDHOME_CDN_RANKED='1'

    log "CDN:    AdGuardHome 顺序 = $RANKED_URL_HOSTS"
}

optimize_mosdns_cdn_order() {
    [ "${MOSDNS_CDN_RANKED:-0}" = '1' ] && return 0
    rank_url_list_hosts "mosdns" "MosDNS" "$MOSDNS_DOWNLOAD_URLS"
    [ -n "${RANKED_URL_HOSTS:-}" ] || return 0
    MOSDNS_DOWNLOAD_URLS="$(reorder_urls_by_host_rank "$MOSDNS_DOWNLOAD_URLS" "$RANKED_URL_HOSTS")"
    MOSDNS_CDN_RANKED='1'
    log "CDN:    MosDNS 顺序 = $RANKED_URL_HOSTS"
}

get_core_arch() {
    machine="$(uname -m 2>/dev/null || true)"

    case "$machine" in
        x86_64) printf '%s\n' amd64 ;;
        i386|i686) printf '%s\n' 386 ;;
        aarch64|arm64) printf '%s\n' arm64 ;;
        armv7l|armv7) printf '%s\n' armv7 ;;
        armv6l|armv6) printf '%s\n' armv6 ;;
        armv5tel|armv5*) printf '%s\n' armv5 ;;
        mips64el|mips64le) printf '%s\n' mips64le ;;
        mips64) printf '%s\n' mips64 ;;
        mipsel|mipsle)
            if opkg print-architecture 2>/dev/null | awk '$1=="arch" && $2 ~ /_sf$/ {found=1} END{exit found?0:1}'; then
                printf '%s\n' mipsle-softfloat
            else
                printf '%s\n' mipsle-hardfloat
            fi
            ;;
        mips)
            if opkg print-architecture 2>/dev/null | awk '$1=="arch" && $2 ~ /_sf$/ {found=1} END{exit found?0:1}'; then
                printf '%s\n' mips-softfloat
            else
                printf '%s\n' mips-hardfloat
            fi
            ;;
        ppc64le) printf '%s\n' ppc64le ;;
        riscv64) printf '%s\n' riscv64 ;;
        *) return 1 ;;
    esac
}

get_openclash_core_arch() { get_core_arch; }

install_openclash_smart_core() {
    optimize_openclash_cdn_order
    core_arch="$(get_openclash_core_arch 2>/dev/null || true)"
    [ -n "$core_arch" ] || die "无法识别 $OPENCLASH_SMART_DISPLAY_NAME 架构"

    mkdir -p "$WORKDIR/openclash/core" /etc/openclash/core
    core_version_file="$WORKDIR/openclash/core_version"
    smart_core_tar="$WORKDIR/openclash/clash-linux-${core_arch}.tar.gz"
    smart_core_dir="/etc/openclash/core"

    log "提示: 正在从 CDN 下载 $OPENCLASH_SMART_DISPLAY_NAME 版本文件..."
    download_from_mirrors "core_version" "$core_version_file" "$OPENCLASH_CORE_VERSION_MIRRORS" || die "无法从全部 CDN 镜像获取 $OPENCLASH_SMART_DISPLAY_NAME 版本文件"
    smart_core_ver="$(sed -n '2p' "$core_version_file" | sed 's/^v//g' | tr -d '\r\n')"
    [ -n "$smart_core_ver" ] || smart_core_ver="$(sed -n '1p' "$core_version_file" | sed 's/^v//g' | tr -d '\r\n')"
    [ -n "$smart_core_ver" ] || die "无法解析 $OPENCLASH_SMART_DISPLAY_NAME 版本"

    log "提示: 正在从 CDN 下载 $OPENCLASH_SMART_DISPLAY_NAME v$smart_core_ver ($core_arch)..."
    download_from_mirrors "clash-linux-${core_arch}.tar.gz" "$smart_core_tar" "$OPENCLASH_CORE_SMART_MIRRORS" || die "无法从全部 CDN 镜像获取 $OPENCLASH_SMART_DISPLAY_NAME"
    [ -s "$smart_core_tar" ] || die "$OPENCLASH_SMART_DISPLAY_NAME 下载失败"

    for existing in "$smart_core_dir"/clash*; do
        [ -f "$existing" ] && backup_file "$existing"
    done

    tar -xzf "$smart_core_tar" -C "$smart_core_dir" >/dev/null 2>&1 || die "$OPENCLASH_SMART_DISPLAY_NAME 解压失败"
    smart_core_entry="$(tar -tzf "$smart_core_tar" 2>/dev/null | awk 'NF && $0 !~ /\/$/ && $0 ~ /(^|\/)clash([._-]|$)/ { print; exit }')"
    [ -n "$smart_core_entry" ] || smart_core_entry="$(tar -tzf "$smart_core_tar" 2>/dev/null | awk 'NF && $0 !~ /\/$/ { print; exit }')"
    smart_core_entry_target="${smart_core_entry#./}"
    smart_core_binary="$(basename "$smart_core_entry_target" 2>/dev/null || true)"
    [ -n "$smart_core_binary" ] || die "无法定位解压后的 $OPENCLASH_SMART_DISPLAY_NAME 二进制"

    case "$smart_core_binary" in
        clash_meta)
            ;;
        *)
            mv -f "$smart_core_dir/$smart_core_binary" "$smart_core_dir/clash_meta" 2>/dev/null || ln -sf "$smart_core_binary" "$smart_core_dir/clash_meta"
            ;;
    esac

    [ -e "$smart_core_dir/clash" ] || ln -sf clash_meta "$smart_core_dir/clash"
    chmod 755 "$smart_core_dir"/clash* 2>/dev/null || true

    mkdir -p /etc/openclash
    printf '%s\n%s\n' "$(sed -n '1p' "$core_version_file")" "$(sed -n '2p' "$core_version_file")" > /etc/openclash/core_version
    chmod 644 /etc/openclash/core_version 2>/dev/null || true

    geoasn_mmdb="$WORKDIR/openclash/GeoLite2-ASN.mmdb"
    log "提示: 正在从 CDN 下载 $OPENCLASH_DISPLAY_NAME ASN.mmdb..."
    if download_from_mirrors "GeoLite2-ASN.mmdb" "$geoasn_mmdb" "$OPENCLASH_GEOASN_MIRRORS"; then
        backup_file /etc/openclash/ASN.mmdb
        cp -f "$geoasn_mmdb" /etc/openclash/ASN.mmdb
        chmod 644 /etc/openclash/ASN.mmdb 2>/dev/null || true
    else
        log "备注:     ASN.mmdb CDN 下载失败，继续安装"
    fi

    log "安装完成"
    log "核心:     $OPENCLASH_SMART_DISPLAY_NAME"
    log "版本:  $smart_core_ver"
    log "arch:     $core_arch"
    log "path:     $smart_core_dir"
}

download_from_urls() {
    out="$1"
    shift
    set -- $(prioritize_github_proxy_urls "$*")
    url_count=0
    url_index=0
    LAST_DOWNLOAD_SOURCE=''

    for url in "$@"; do
        url_count=$((url_count + 1))
    done

    for url in "$@"; do
        url_index=$((url_index + 1))
        if download_file "$url" "$out"; then
            LAST_DOWNLOAD_SOURCE="$url"
            return 0
        fi
        if [ "$url_index" -lt "$url_count" ]; then
            log "提示: 当前下载地址未完成，准备切换到下一个地址..."
        fi
    done

    return 1
}

download_openlist_from_urls() {
    out="$1"
    shift
    set -- $(prioritize_github_proxy_urls "$*")

    [ "${CURRENT_DETECTED_MODEL:-}" = 'NRadio_C2000MAX' ] || {
        download_from_urls "$out" "$@"
        return "$?"
    }

    url_count=0
    url_index=0
    LAST_DOWNLOAD_SOURCE=''

    for url in "$@"; do
        url_count=$((url_count + 1))
    done

    for url in "$@"; do
        url_index=$((url_index + 1))
        rm -f "$out.tmp" 2>/dev/null || true
        if download_file "$url" "$out"; then
            LAST_DOWNLOAD_SOURCE="$url"
            return 0
        fi
        rm -f "$out.tmp" 2>/dev/null || true
        if [ "$url_index" -lt "$url_count" ]; then
            log "提示: 当前下载地址未完成，已清理临时续传文件，准备切换到下一个地址..."
        fi
    done

    return 1
}

backup_file() {
    # 用户要求所有安装、修复和页面操作直接写入，不在路由器上生成持久备份。
    return 0
}

ensure_state_dir() {
    [ "${NRADIO_READONLY_SELFTEST:-0}" = '1' ] && return 0
    mkdir -p "$STATE_DIR"
    chmod 700 "$STATE_DIR" 2>/dev/null || true
}

nradio_sanitize_stream() {
    awk '
        BEGIN {
            sq = sprintf("%c", 39)
            redacted = "<redacted>"
            key_count = split("proxy_authorization proxy-authorization authorization access_token refresh_token session_token client_secret private_key secret_key api_key access-token refresh-token session-token client-secret private-key secret-key api-key apikey password passwd cookie token secret", keys, " ")
        }

        function is_key_char(ch) {
            return ch ~ /[[:alnum:]_-]/
        }

        function redact_urls(text,    lower, search_at, rel_http, rel_https, rel, start_pos, end_pos, ch) {
            search_at = 1
            while (search_at <= length(text)) {
                lower = tolower(text)
                rel_http = index(substr(lower, search_at), "http://")
                rel_https = index(substr(lower, search_at), "https://")
                if (rel_http == 0 && rel_https == 0)
                    break
                if (rel_http == 0 || (rel_https != 0 && rel_https < rel_http))
                    rel = rel_https
                else
                    rel = rel_http

                start_pos = search_at + rel - 1
                end_pos = start_pos
                while (end_pos <= length(text)) {
                    ch = substr(text, end_pos, 1)
                    if (ch ~ /[[:space:]<>]/ || ch == "\"" || ch == sq)
                        break
                    end_pos++
                }
                text = substr(text, 1, start_pos - 1) "<URL>" substr(text, end_pos)
                search_at = start_pos + 5
            }
            return text
        }

        function redact_key_value(text, key,    lower, search_at, rel, pos, before, after, i, delimiter, value_start, quote, close_pos, ch, value_end, escaped) {
            search_at = 1
            while (search_at <= length(text)) {
                lower = tolower(text)
                rel = index(substr(lower, search_at), key)
                if (rel == 0)
                    break
                pos = search_at + rel - 1
                before = pos > 1 ? substr(text, pos - 1, 1) : ""
                after = substr(text, pos + length(key), 1)
                if (is_key_char(before) || is_key_char(after)) {
                    search_at = pos + length(key)
                    continue
                }

                i = pos + length(key)
                ch = substr(text, i, 1)
                if (ch == "\"" || ch == sq)
                    i++
                while (substr(text, i, 1) ~ /[[:space:]]/)
                    i++
                delimiter = substr(text, i, 1)
                if (delimiter != ":" && delimiter != "=") {
                    search_at = pos + length(key)
                    continue
                }

                i++
                while (substr(text, i, 1) ~ /[[:space:]]/)
                    i++
                value_start = i
                quote = substr(text, value_start, 1)

                if (quote == "\"" || quote == sq) {
                    close_pos = value_start + 1
                    escaped = 0
                    while (close_pos <= length(text)) {
                        ch = substr(text, close_pos, 1)
                        if (quote == "\"" && ch == "\\" && escaped == 0) {
                            escaped = 1
                            close_pos++
                            continue
                        }
                        if (ch == quote && escaped == 0)
                            break
                        escaped = 0
                        close_pos++
                    }
                    if (close_pos <= length(text)) {
                        text = substr(text, 1, value_start) redacted substr(text, close_pos)
                        search_at = value_start + length(redacted) + 2
                    } else {
                        text = substr(text, 1, value_start) redacted
                        break
                    }
                } else {
                    if (key == "cookie" || key == "authorization" || key == "proxy_authorization" || key == "proxy-authorization") {
                        value_end = length(text) + 1
                    } else {
                        value_end = value_start
                        while (value_end <= length(text)) {
                            ch = substr(text, value_end, 1)
                            if (ch ~ /[,;}]/ || ch == "]" || ch == sq || ch == "\"")
                                break
                            value_end++
                        }
                    }
                    if (value_end == value_start) {
                        search_at = pos + length(key)
                        continue
                    }
                    text = substr(text, 1, value_start - 1) redacted substr(text, value_end)
                    search_at = value_start + length(redacted)
                }
            }
            return text
        }

        function redact_bearer(text,    lower, search_at, rel, pos, before, i, token_start, token_end, ch) {
            search_at = 1
            while (search_at <= length(text)) {
                lower = tolower(text)
                rel = index(substr(lower, search_at), "bearer")
                if (rel == 0)
                    break
                pos = search_at + rel - 1
                before = pos > 1 ? substr(text, pos - 1, 1) : ""
                i = pos + 6
                if (is_key_char(before) || substr(text, i, 1) !~ /[[:space:]]/) {
                    search_at = pos + 6
                    continue
                }
                while (substr(text, i, 1) ~ /[[:space:]]/)
                    i++
                token_start = i
                token_end = token_start
                while (token_end <= length(text)) {
                    ch = substr(text, token_end, 1)
                    if (ch ~ /[[:space:],;}]/ || ch == "]" || ch == sq || ch == "\"")
                        break
                    token_end++
                }
                if (token_end == token_start) {
                    search_at = pos + 6
                    continue
                }
                text = substr(text, 1, token_start - 1) redacted substr(text, token_end)
                search_at = token_start + length(redacted)
            }
            return text
        }

        {
            line = redact_urls($0)
            line = redact_bearer(line)
            for (key_index = 1; key_index <= key_count; key_index++)
                line = redact_key_value(line, keys[key_index])
            print line
        }
    '
}

nradio_action_safe_field() {
    printf '%s' "$1" | tr '\t\r\n' '   ' | nradio_sanitize_stream
}

record_action_history() {
    action_path="$(nradio_action_safe_field "$1")"
    action_name="$(nradio_action_safe_field "$2")"
    action_result="$(nradio_action_safe_field "$3")"
    action_backup='disabled'
    action_time="$(date '+%Y-%m-%d %H:%M:%S' 2>/dev/null || printf '%s' "$TS")"

    mkdir -p "$STATE_DIR" >/dev/null 2>&1 || return 0
    chmod 700 "$STATE_DIR" 2>/dev/null || true
    printf '%s\tversion=%s\tpath=%s\taction=%s\tbackup=%s\tresult=%s\n' \
        "$action_time" "$SCRIPT_VERSION" "$action_path" "$action_name" "${action_backup:-none}" "${action_result:-unknown}" >> "$ACTION_HISTORY_FILE" 2>/dev/null || return 0
    chmod 600 "$ACTION_HISTORY_FILE" 2>/dev/null || true

    if command -v tail >/dev/null 2>&1 && [ -f "$ACTION_HISTORY_FILE" ]; then
        action_history_lines="$(wc -l < "$ACTION_HISTORY_FILE" 2>/dev/null | tr -d ' ' || printf '0')"
        case "$action_history_lines" in
            ''|*[!0-9]*) action_history_lines=0 ;;
        esac
        if [ "$action_history_lines" -gt 300 ] 2>/dev/null; then
            action_history_tmp="/tmp/nradio-action-history.$$"
            tail -n 300 "$ACTION_HISTORY_FILE" > "$action_history_tmp" 2>/dev/null && mv "$action_history_tmp" "$ACTION_HISTORY_FILE" 2>/dev/null || rm -f "$action_history_tmp" 2>/dev/null || true
            chmod 600 "$ACTION_HISTORY_FILE" 2>/dev/null || true
        fi
    fi
}

run_recorded_menu_feature() {
    recorded_menu_path="$1"
    recorded_action_name="$2"
    shift 2

    "$@"
    record_action_history "$recorded_menu_path" "$recorded_action_name" "PASS" "${BACKUP_DIR:-}"
    return 0
}

nradio_print_backup_inventory_summary() {
    backup_root="${1:-$BACKUP_DIR}"
    backup_limit="${2:-10}"

    selfcheck_print_header "备份清单摘要"
    if [ -z "$backup_root" ] || [ ! -d "$backup_root" ]; then
        log "备份:   ${backup_root:-未设置} = 暂无"
    else
        backup_count="$(find "$backup_root" -type f 2>/dev/null | wc -l | tr -d ' ' || printf '0')"
        case "$backup_count" in
            ''|*[!0-9]*) backup_count=0 ;;
        esac
        log "备份:   $backup_root = ${backup_count} 个文件"
        if [ "$backup_count" -gt 0 ] 2>/dev/null; then
            find "$backup_root" -type f 2>/dev/null | sed -n "1,${backup_limit}p" | while IFS= read -r backup_item; do
                [ -n "$backup_item" ] || continue
                ls -ld "$backup_item" 2>/dev/null || true
            done | sed 's/^/备份项: /'
        fi
    fi

    log "说明:   新版脚本已禁用持久备份；此处只列出旧版本可能遗留的文件"
}

nradio_print_action_history_summary() {
    history_limit="${1:-10}"

    selfcheck_print_header "动作日志摘要"
    if [ ! -s "$ACTION_HISTORY_FILE" ]; then
        log "动作日志: $ACTION_HISTORY_FILE = 暂无"
        return 0
    fi
    log "动作日志: $ACTION_HISTORY_FILE"
    tail -n "$history_limit" "$ACTION_HISTORY_FILE" 2>/dev/null | nradio_sanitize_stream | sed 's/^/动作:   /'
}

nradio_print_rootfs_2nd_landing_summary() {
    selfcheck_print_header "rootfs_2nd 落点"
    rootfs_device="$(storage_expand_find_rootfs_2nd_device 2>/dev/null || true)"
    if [ -z "$rootfs_device" ]; then
        log "rootfs_2nd: 未发现 PARTLABEL=rootfs_2nd"
        return 0
    fi

    log "rootfs_2nd: device=$rootfs_device"
    if [ -f "$ROOTFS_2ND_STORAGE_MARKER" ]; then
        log "标记:   $ROOTFS_2ND_STORAGE_MARKER = 存在"
    else
        log "标记:   $ROOTFS_2ND_STORAGE_MARKER = 未启用"
    fi
    rootfs_mount_source="$(storage_expand_mount_source_for_mountpoint 2>/dev/null || true)"
    rootfs_other_mount="$(storage_expand_device_mountpoint "$rootfs_device" 2>/dev/null || true)"
    if [ -n "$rootfs_mount_source" ]; then
        log "挂载:   $ROOTFS_2ND_STORAGE_MOUNT_POINT <- $rootfs_mount_source"
        df -h "$ROOTFS_2ND_STORAGE_MOUNT_POINT" 2>/dev/null || true
    elif [ -n "$rootfs_other_mount" ]; then
        log "挂载:   rootfs_2nd 当前挂载在 $rootfs_other_mount"
    else
        log "挂载:   rootfs_2nd 当前未挂载"
    fi
    [ -d "$ROOTFS_2ND_STORAGE_APPS_DIR" ] && log "应用目录: $ROOTFS_2ND_STORAGE_APPS_DIR = 存在" || log "应用目录: $ROOTFS_2ND_STORAGE_APPS_DIR = 不存在"
    if [ -s "$ROOTFS_2ND_STORAGE_MIGRATE_LIST" ]; then
        log "迁移清单: $ROOTFS_2ND_STORAGE_MIGRATE_LIST"
        sed -n '1,10p' "$ROOTFS_2ND_STORAGE_MIGRATE_LIST" 2>/dev/null | sed 's/^/迁移项: /'
    else
        log "迁移清单: 暂无"
    fi
}

nradio_print_openclash_brief_summary() {
    selfcheck_print_header "$OPENCLASH_DISPLAY_NAME 摘要"
    openclash_report_storage_location "$OPENCLASH_DISPLAY_NAME 目录" /etc/openclash
    openclash_report_storage_location "$OPENCLASH_DISPLAY_NAME 核心目录" /etc/openclash/core
    [ -f /etc/config/openclash ] && log "配置:   /etc/config/openclash = 存在" || log "配置:   /etc/config/openclash = 未安装"
    [ -f /usr/lib/lua/luci/controller/openclash.lua ] && log "LuCI:   controller = 存在" || log "LuCI:   controller = 缺失"
    [ -x /etc/init.d/openclash ] && log "服务:   init = 存在" || log "服务:   init = 缺失"
    openclash_core_runtime_valid && log "核心:   smart/meta = 正常" || log "核心:   smart/meta = 缺失或异常"
    openclash_asn_mmdb_valid && log "ASN:    ASN.mmdb = 正常" || log "ASN:    ASN.mmdb = 缺失或异常"
    openclash_model_file_valid /etc/openclash/Model.bin && log "模型:   Model.bin = 正常" || log "模型:   Model.bin = 缺失或异常"
}

nradio_print_recent_install_log_brief() {
    selfcheck_print_header "安装日志简报"
    for log_pair in \
        "$OPENCLASH_DISPLAY_NAME 安装|$WORKDIR/openclash-install.log" \
        "opkg update|$WORKDIR/nradio-plugin-opkg.update.log" \
        "opkg 依赖安装|$WORKDIR/nradio-plugin-opkg.install.log" \
        "通用 ipk 安装|$WORKDIR/nradio-plugin-ipk.install.log"
    do
        log_label="${log_pair%%|*}"
        log_file="${log_pair#*|}"
        if [ ! -f "$log_file" ]; then
            log "日志:   $log_label = 未找到 ($log_file)"
            continue
        fi
        log_size="$(wc -c < "$log_file" 2>/dev/null | tr -d ' ' || printf '0')"
        log "日志:   $log_label = $log_file (${log_size:-0} bytes)"
        key_lines="$(grep -Ein 'error|failed|fail|cannot|missing|not found|No space|parse_from_stream|Missing new line|Collected errors|incompatible|architecture|dependency|depends|timeout|invalid|corrupt|Unknown package' "$log_file" 2>/dev/null | unified_install_log_filter_noise | sed -n '1,5p' | nradio_sanitize_stream || true)"
        if [ -n "$key_lines" ]; then
            printf '%s\n' "$key_lines" | sed 's/^/命中:   /'
        else
            log "命中:   $log_label = 无关键错误行"
        fi
    done
}

nradio_print_final_seal_summary() {
    selfcheck_print_header "封版摘要"
    seal_model="$(unified_detect_model_name 2>/dev/null || true)"
    seal_nros="$(detect_nros_revision 2>/dev/null || true)"
    log "脚本:   version=$SCRIPT_VERSION date=$SCRIPT_RELEASE_DATE"
    log "环境:   model=${seal_model:-未知} nros=${seal_nros:-未知}"
    has_nradio_oem_appcenter && log "应用商店: NRadio OEM = PASS" || log "应用商店: NRadio OEM = WARN"
    rootfs_device="$(storage_expand_find_rootfs_2nd_device 2>/dev/null || true)"
    rootfs_mount_source="$(storage_expand_mount_source_for_mountpoint 2>/dev/null || true)"
    log "rootfs_2nd: device=${rootfs_device:-未发现} mount=${rootfs_mount_source:-未挂载}"
    if [ -f /etc/config/openclash ]; then
        log "$OPENCLASH_DISPLAY_NAME: 配置 = 存在"
    else
        log "$OPENCLASH_DISPLAY_NAME: 配置 = 未安装"
    fi
    case "${NRADIO_UNIFIED_FAILS:-}" in
        ''|*[!0-9]*)
            log "总计:   未记录统一体检计数"
            ;;
        *)
            if [ "$NRADIO_UNIFIED_FAILS" -gt 0 ]; then
                log "总计:   FAIL pass=$NRADIO_UNIFIED_PASSES warn=$NRADIO_UNIFIED_WARNS fail=$NRADIO_UNIFIED_FAILS skip=$NRADIO_UNIFIED_SKIPS"
            elif [ "$NRADIO_UNIFIED_WARNS" -gt 0 ]; then
                log "总计:   WARN pass=$NRADIO_UNIFIED_PASSES warn=$NRADIO_UNIFIED_WARNS fail=0 skip=$NRADIO_UNIFIED_SKIPS"
            else
                log "总计:   PASS pass=$NRADIO_UNIFIED_PASSES skip=$NRADIO_UNIFIED_SKIPS"
            fi
            ;;
    esac
}

run_final_diagnostic_report_export() {
    require_root
    report_file="/tmp/nradio-final-diagnostic.$TS.txt"
    report_tmp="/tmp/nradio-final-diagnostic.$TS.tmp"

    {
        selfcheck_print_header "封版脱敏诊断报告"
        log "script=${SCRIPT_VERSION} date=${SCRIPT_RELEASE_DATE}"
        log "menu_path=5 > 7 > 1"
        log "generated_at=$(date '+%Y-%m-%d %H:%M:%S' 2>/dev/null || printf '%s' "$TS")"
        run_unified_sanitized_diagnostic_summary
        nradio_print_rootfs_2nd_landing_summary
        nradio_print_openclash_brief_summary
        nradio_print_recent_install_log_brief
        nradio_print_backup_inventory_summary "$BACKUP_DIR" 20
        nradio_print_action_history_summary 20
    } > "$report_tmp" 2>&1 || {
        rm -f "$report_tmp" 2>/dev/null || true
        die "导出脱敏诊断报告失败"
    }
    nradio_sanitize_stream < "$report_tmp" > "$report_file" 2>/dev/null || {
        rm -f "$report_tmp" "$report_file" 2>/dev/null || true
        die "脱敏诊断报告写入失败"
    }
    rm -f "$report_tmp" 2>/dev/null || true
    chmod 600 "$report_file" 2>/dev/null || true
    log "报告:   $report_file"
    log "说明:   已脱敏 URL、password/passwd、token/API key、cookie、secret、private key 与 Bearer 凭据"
    record_action_history "5 > 7 > 1" "导出脱敏诊断报告" "PASS" "/tmp"
}

run_final_stability_toolbox() {
    while :; do
        printf '\n封版工具箱:\n'
        printf '1. 导出脱敏诊断报告\n'
        printf '2. 查看备份清单\n'
        printf '3. 查看动作日志\n'
        printf '0. 返回设备维护与检测\n'
        printf '请选择 0、1、2 或 3: '
        read_category_choice
        case "$UI_READ_RESULT" in
            0) return 0 ;;
            1) run_final_diagnostic_report_export; MENU_ACTION_COMPLETED='1'; return 0 ;;
            2) nradio_print_backup_inventory_summary "$BACKUP_DIR" 30; MENU_ACTION_COMPLETED='1'; return 0 ;;
            3) nradio_print_action_history_summary 30; MENU_ACTION_COMPLETED='1'; return 0 ;;
            *) die_menu_input_issue "$UI_READ_RESULT" ;;
        esac
    done
}

write_plugin_uninstall_assets() {
    helper="$PLUGIN_UNINSTALL_HELPER"
    controller="$PLUGIN_UNINSTALL_CONTROLLER"

    mkdir -p "$(dirname "$helper")" "$(dirname "$controller")"
    [ -f "$helper" ] && backup_file "$helper"
    [ -f "$controller" ] && backup_file "$controller"

cat > "$helper" <<'EOF_PLUGIN_UNINSTALL_HELPER'
#!/bin/sh
set -eu
umask 077

plugin="${1:-}"
STATE_DIR="/root/.nradio-plugin-menu"
WORKDIR="/var/run/nradio-plugin-uninstall/work.$$"
UNINSTALL_LOG_FILE="${UNINSTALL_LOG_FILE:-$WORKDIR/uninstall-detail.log}"
OPKG_LOCK_FILE="/var/lock/opkg.lock"
GLOBAL_LOCK_DIR="/var/run/nradio-plugin-assistant.lock"
GLOBAL_LOCK_OWNER='0'
APP_ICON_DIR="/www/luci-static/nradio/images/icon"
CFG="/etc/config/appcenter"
TPL="/usr/lib/lua/luci/view/nradio_appcenter/appcenter.htm"
APPCENTER_CONTROLLER="/usr/lib/lua/luci/controller/nradio_adv/appcenter.lua"
OPENCLASH_ICON_NAME="openclash.svg"
ADGUARDHOME_ICON_NAME="adguard.svg"
ADGUARDHOME_DNS_PORT="554"
ADGUARDHOME_LEGACY_DNS_PORT="553"
MOSDNS_PORT="553"
OPENVPN_ICON_NAME="openvpn.svg"
OPENLIST_ICON_NAME="openlist.svg"
ZEROTIER_ICON_NAME="zerotier.svg"
EASYTIER_ICON_NAME="easytier.svg"
WEBSSH_ICON_NAME="webssh.svg"
WEBSSH_ROUTE="nradioadv/system/webssh"
WEBSSH_CONTROLLER="/usr/lib/lua/luci/controller/nradio_adv/webssh.lua"
WEBSSH_VIEW="/usr/lib/lua/luci/view/nradio_adv/webssh.htm"
ROUTE_STATE_FILE="$STATE_DIR/openvpn_routes.conf"
ROUTE_LIST_FILE="$STATE_DIR/openvpn_routes.list"
ROUTE_MAP_LIST_FILE="$STATE_DIR/openvpn_map_peers.list"
OPENVPN_DNSMASQ_DOMAIN_STATE_FILE="$STATE_DIR/openvpn_dnsmasq_domains.list"
OPENLIST_ROOT_DIR="/mnt/app_data/openlist"
OPENLIST_BIN_DIR="$OPENLIST_ROOT_DIR/bin"
OPENLIST_BIN_PATH="$OPENLIST_BIN_DIR/openlist"
OPENLIST_LINK_PATH="/usr/bin/openlist"
OPENLIST_DEFAULT_DATA_DIR="$OPENLIST_ROOT_DIR/data"
OPENLIST_DEFAULT_TEMP_DIR="$OPENLIST_ROOT_DIR/tmp"
OPENLIST_DEFAULT_LOG_PATH="$OPENLIST_ROOT_DIR/openlist.log"
DOCKER_PAYLOAD_MANIFEST="$STATE_DIR/docker_payload_manifest.v1"

log() {
    printf '%s\n' "$*"
}

die() {
    printf 'ERROR: %s\n' "$*" >&2
    exit 1
}

process_starttime() {
    process_pid="$1"
    case "$process_pid" in
        ''|*[!0-9]*) return 1 ;;
    esac
    [ -r "/proc/$process_pid/stat" ] || return 1
    sed 's/^[^)]*) //' "/proc/$process_pid/stat" 2>/dev/null | awk '{print $20}'
}

uninstall_lock_pid_matches_owner() {
    lock_path="$1"
    lock_process_pid="$2"
    case "$lock_process_pid" in
        ''|*[!0-9]*) return 1 ;;
    esac
    kill -0 "$lock_process_pid" 2>/dev/null || return 1

    stored_starttime="$(cat "$lock_path/starttime" 2>/dev/null || true)"
    current_starttime="$(process_starttime "$lock_process_pid" 2>/dev/null || true)"
    if [ -n "$stored_starttime" ]; then
        [ -n "$current_starttime" ] && [ "$stored_starttime" = "$current_starttime" ]
        return
    fi

    lock_cmdline="$(tr '\000' ' ' < "/proc/$lock_process_pid/cmdline" 2>/dev/null || true)"
    case "$lock_cmdline" in
        *ssh-nradio-plugin-installer.sh*|*nradio-plugin-assistant*|*nradio-plugin-uninstall*) return 0 ;;
    esac
    return 1
}

write_uninstall_lock_identity() {
    local lock_path="$1" current_starttime
    current_starttime="$(process_starttime "$$" 2>/dev/null || true)"
    [ -n "$current_starttime" ] || return 1
    printf '%s\n' "$current_starttime" > "$lock_path/starttime" &&
        printf '%s\n' "$$" > "$lock_path/pid"
}

reclaim_initialized_task_lock() {
    local path="$1" checker="$2" old_pid old_start
    [ -d "$path" ] && [ ! -L "$path" ] || return 1
    old_pid="$(cat "$path/pid" 2>/dev/null || true)"
    old_start="$(cat "$path/starttime" 2>/dev/null || true)"
    case "$old_pid" in ''|*[!0-9]*) return 1 ;; esac
    case "$old_start" in ''|*[!0-9]*) return 1 ;; esac
    mkdir "$path/reap" 2>/dev/null || return 1
    if [ "$(cat "$path/pid" 2>/dev/null || true)" = "$old_pid" ] &&
       [ "$(cat "$path/starttime" 2>/dev/null || true)" = "$old_start" ] &&
       ! "$checker" "$path" "$old_pid"; then
        rm -f "$path/pid" "$path/starttime" || { rmdir "$path/reap"; return 1; }
        rmdir "$path/reap" && rmdir "$path"
        return $?
    fi
    rmdir "$path/reap" 2>/dev/null || true
    return 1
}

release_uninstall_global_lock() {
    [ "${GLOBAL_LOCK_OWNER:-0}" = '1' ] || return 0
    if [ "$(cat "$GLOBAL_LOCK_DIR/pid" 2>/dev/null || true)" = "$$" ] &&
       uninstall_lock_pid_matches_owner "$GLOBAL_LOCK_DIR" "$$"; then
        rm -f "$GLOBAL_LOCK_DIR/pid" "$GLOBAL_LOCK_DIR/starttime"
        for release_attempt in 1 2 3; do
            rmdir "$GLOBAL_LOCK_DIR" 2>/dev/null && break
            sleep 1
        done
    fi
    GLOBAL_LOCK_OWNER='0'
}

acquire_uninstall_global_lock() {
    mkdir -p "$(dirname "$GLOBAL_LOCK_DIR")" >/dev/null 2>&1 || true

    if mkdir "$GLOBAL_LOCK_DIR" 2>/dev/null; then
        write_uninstall_lock_identity "$GLOBAL_LOCK_DIR" || die "写入全局任务锁身份失败：$GLOBAL_LOCK_DIR"
        GLOBAL_LOCK_OWNER='1'
        return 0
    fi

    lock_pid="$(cat "$GLOBAL_LOCK_DIR/pid" 2>/dev/null || true)"
    case "$lock_pid" in
        ''|*[!0-9]*) lock_pid='' ;;
    esac
    if uninstall_lock_pid_matches_owner "$GLOBAL_LOCK_DIR" "$lock_pid"; then
        die "已有安装或卸载任务正在运行（pid $lock_pid）"
    fi

    reclaim_initialized_task_lock "$GLOBAL_LOCK_DIR" uninstall_lock_pid_matches_owner ||
        die "全局锁正在初始化、回收或身份不完整，请核对后重试：$GLOBAL_LOCK_DIR"
    mkdir "$GLOBAL_LOCK_DIR" 2>/dev/null || die "获取全局任务锁失败：$GLOBAL_LOCK_DIR"
    write_uninstall_lock_identity "$GLOBAL_LOCK_DIR" || die "写入全局任务锁身份失败：$GLOBAL_LOCK_DIR"
    GLOBAL_LOCK_OWNER='1'
    log "提示: 已清除过期的安装/卸载全局锁"
}

cleanup_uninstall_helper() {
    uninstall_helper_rc="$?"
    trap - EXIT
    release_uninstall_global_lock
    rm -rf "$WORKDIR" >/dev/null 2>&1 || true

    if [ "${NRADIO_ASYNC_UNINSTALL:-0}" = '1' ] && [ -n "${UNINSTALL_TASK_STATUS_FILE:-}" ]; then
        mkdir -p "$UNINSTALL_TASK_DIR" >/dev/null 2>&1 || true
        printf '%s\n' "$uninstall_helper_rc" > "$UNINSTALL_TASK_RC_FILE" 2>/dev/null || true
        if [ "$uninstall_helper_rc" -eq 0 ] 2>/dev/null; then
            printf '%s\n' 'ok' > "$UNINSTALL_TASK_STATUS_FILE" 2>/dev/null || true
        else
            printf '%s\n' 'fail' > "$UNINSTALL_TASK_STATUS_FILE" 2>/dev/null || true
        fi
        rm -f "$UNINSTALL_TASK_PID_FILE" "$UNINSTALL_TASK_STARTED_FILE" 2>/dev/null || true
        rmdir "$UNINSTALL_TASK_LOCK_DIR" >/dev/null 2>&1 || true
    fi

    exit "$uninstall_helper_rc"
}

abort_uninstall_helper() {
    trap - INT TERM HUP QUIT
    exit 130
}

trap cleanup_uninstall_helper EXIT
trap abort_uninstall_helper INT TERM HUP QUIT

case "$plugin" in
    openclash|webssh|adguardhome|openvpn|openlist|zerotier|easytier|fanctrl|qiyou|leigod|mosdns|ddnsgo|mt5700|docker)
