UNINSTALL_TASK_RC_FILE="$UNINSTALL_TASK_DIR/$plugin.rc"
UNINSTALL_TASK_PID_FILE="$UNINSTALL_TASK_DIR/$plugin.pid"
UNINSTALL_TASK_STARTED_FILE="$UNINSTALL_TASK_DIR/$plugin.started"
