    cleanup_appcenter_entry "$LEIGOD_APP_NAME" "$LEIGOD_PACKAGE_NAME" "$LEIGOD_ROUTE"
    cleanup_appcenter_entry "$LEIGOD_PACKAGE_NAME" "$LEIGOD_PACKAGE_NAME" "$LEIGOD_ROUTE"
    [ ! -e "$LEIGOD_DIR" ] && [ ! -e "$LEIGOD_INIT" ] || die "雷神卸载后仍有核心文件残留"
    return 0
}

