.nr-c2000pro-modal{display:none;position:fixed;z-index:9999;inset:0;background:rgba(3,7,18,.76);padding:4vh 4vw;overflow-y:auto;-webkit-overflow-scrolling:touch;overscroll-behavior:contain}
