    uci set "appcenter.$ddnsgo_i18n_sec.version=$DDNSGO_I18N_VERSION"
    uci set "appcenter.$ddnsgo_i18n_sec.has_luci=0"
    uci set "appcenter.$ddnsgo_i18n_sec.type=1"
