    function nradio_app_frame_is_logout_url(value){
        value = String(value || "");
        return value.indexOf("/nradio/logout") !== -1 || value.indexOf("/admin/logout") !== -1;
    }
    function nradio_app_frame_redirect_top(url){
        var target = url || "/cgi-bin/luci/";
        try {
            if(typeof sub_dialogDeal !== "undefined" && sub_dialogDeal && typeof sub_dialogDeal.close == "function")
                sub_dialogDeal.close();
        }
        catch(e) {}

        try {
            window.top.location.href = target;
        }
        catch(e) {
            window.location.href = target;
        }
    }
    function nradio_app_frame_bind_logout_guard(frame, d){
        if(!frame || !d || !d.addEventListener)
            return;

        if(d.__nradioAppFrameLogoutGuard)
            d.removeEventListener("click", d.__nradioAppFrameLogoutGuard, true);

        d.__nradioAppFrameLogoutGuard = function(event){
            var node = event.target;
            while(node && node !== d) {
                if(node.getAttribute) {
                    var logout_hint = [
                        node.getAttribute("href") || "",
                        node.getAttribute("onclick") || "",
                        node.getAttribute("data-url") || ""
                    ].join(" ");
                    if(nradio_app_frame_is_logout_url(logout_hint)) {
                        event.preventDefault();
                        event.stopPropagation();
                        if(event.stopImmediatePropagation)
                            event.stopImmediatePropagation();
                        nradio_app_frame_redirect_top("/cgi-bin/luci/nradio/logout");
                        return;
                    }
                }
                node = node.parentNode;
            }
        };
        d.addEventListener("click", d.__nradioAppFrameLogoutGuard, true);
    }
    function nradio_app_frame_handle_session(frame, d){
        var current_url = "";
        try {
            current_url = frame.contentWindow.location.href || "";
        }
        catch(e) {}

        if(nradio_app_frame_is_logout_url(current_url)) {
            nradio_app_frame_redirect_top("/cgi-bin/luci/nradio/logout");
            return true;
        }

        if(d && d.querySelector && d.querySelector('input[name="luci_username"]') && d.querySelector('input[name="luci_password"]')) {
            nradio_app_frame_redirect_top("/cgi-bin/luci/");
            return true;
        }
        return false;
    }
    function nradio_app_frame_preserve_mobile_save_style(d){
        var mobile_style_id = 'appcenter-open-mobile-style';
        var mobile_style;

        if(!d || !d.head || d.getElementById(mobile_style_id))
            return;

        mobile_style = d.createElement('style');
        mobile_style.id = mobile_style_id;
        mobile_style.type = 'text/css';
        mobile_style.appendChild(d.createTextNode(
            '@media (min-width: 10px) and (max-width: 767px) {' +
            'html body div.cbi-page-actions > input.cbi-button-apply {' +
            'display: unset;' +
            'width: 100%;' +
            '}' +
            '}'
        ));
        d.head.appendChild(mobile_style);
    }
    function nradio_app_frame_enable_mobile_touch_scroll(frame, d){
        var touch_start_options = {passive: true};
        var touch_move_options = {passive: false};
        var last_y = 0;
        var tracking = false;

        if(!frame || !d || !d.addEventListener || frame.src.indexOf('/nradioadv/system/webssh') !== -1)
            return;

        $.each([d.documentElement, d.body], function(index, node){
            if(!node || !node.style)
                return;
            node.style.setProperty('overflow-y', 'auto', 'important');
            node.style.setProperty('-webkit-overflow-scrolling', 'touch', 'important');
            node.style.setProperty('touch-action', 'pan-y', 'important');
            node.style.setProperty('overscroll-behavior-y', 'contain', 'important');
        });

        if(d.__nradioAppFrameTouchStart)
            d.removeEventListener('touchstart', d.__nradioAppFrameTouchStart, touch_start_options);
        if(d.__nradioAppFrameTouchMove)
            d.removeEventListener('touchmove', d.__nradioAppFrameTouchMove, touch_move_options);
        if(d.__nradioAppFrameTouchEnd) {
            d.removeEventListener('touchend', d.__nradioAppFrameTouchEnd, touch_start_options);
            d.removeEventListener('touchcancel', d.__nradioAppFrameTouchEnd, touch_start_options);
        }

        function scroll_target(){
            var candidates = [
                d.scrollingElement,
                d.documentElement,
                d.body,
                d.querySelector('.main'),
                d.querySelector('.body-container'),
                d.querySelector('.main-content'),
                d.getElementById('maincontent'),
                d.getElementById('content')
            ];
            var best = null;
            var best_range = 0;
            $.each(candidates, function(index, node){
                var range;
                if(!node)
                    return;
                range = Math.max(0, (node.scrollHeight || 0) - (node.clientHeight || 0));
                if(!best || range > best_range) {
                    best = node;
                    best_range = range;
                }
            });
            return best;
        }

        d.__nradioAppFrameTouchStart = function(event){
            if(!event.touches || event.touches.length !== 1)
                return;
            tracking = true;
            last_y = event.touches[0].clientY;
        };
        d.__nradioAppFrameTouchMove = function(event){
            var current_y;
            var delta;
            var target;
            if(!tracking || !event.touches || event.touches.length !== 1)
                return;
            current_y = event.touches[0].clientY;
            delta = last_y - current_y;
            last_y = current_y;
            if(Math.abs(delta) < 1)
                return;
            target = event.target;
            while(target && target !== d.body && target !== d.documentElement) {
                var overflow = d.defaultView.getComputedStyle(target).overflowY;
                if(/auto|scroll/.test(overflow) && target.scrollHeight > target.clientHeight &&
                   (delta < 0 ? target.scrollTop > 0 : target.scrollTop + target.clientHeight < target.scrollHeight))
                    break;
                target = target.parentElement;
            }
            if(!target || target === d.body || target === d.documentElement) target = scroll_target();
            if(!target || target.scrollHeight <= target.clientHeight)
                return;
            var before = target.scrollTop;
            target.scrollTop += delta;
            if(target.scrollTop !== before) event.preventDefault();
        };
        d.__nradioAppFrameTouchEnd = function(){
            tracking = false;
        };

        try {
            d.addEventListener('touchstart', d.__nradioAppFrameTouchStart, touch_start_options);
            d.addEventListener('touchmove', d.__nradioAppFrameTouchMove, touch_move_options);
            d.addEventListener('touchend', d.__nradioAppFrameTouchEnd, touch_start_options);
            d.addEventListener('touchcancel', d.__nradioAppFrameTouchEnd, touch_start_options);
        }
        catch(e) {
            d.addEventListener('touchstart', d.__nradioAppFrameTouchStart, false);
            d.addEventListener('touchmove', d.__nradioAppFrameTouchMove, false);
            d.addEventListener('touchend', d.__nradioAppFrameTouchEnd, false);
            d.addEventListener('touchcancel', d.__nradioAppFrameTouchEnd, false);
        }
    }
    function reload_iframe(){
        try {
            ensure_app_frame_polish_css();
            $(".modal.app_frame").scrollTop(0);
            $("#sub_frame").css({
                "display": "block",
                "flex": "1 1 0",
                "width": "100%",
                "max-width": "none",
                "min-width": "0",
                "height": "auto",
                "min-height": "0",
                "border": "0",
                "background": "#101018"
            });

            var frame = document.getElementById('sub_frame');
            if (!frame || !frame.src)
                return;

            var d = frame.contentWindow.document;
            nradio_app_frame_preserve_mobile_save_style(d);
            nradio_app_frame_bind_logout_guard(frame, d);
            if(nradio_app_frame_handle_session(frame, d))
                return;

            if (frame.src.indexOf('/admin/services/openclash') === -1 && frame.src.indexOf('/admin/services/AdGuardHome') === -1 && frame.src.indexOf('/nradioadv/system/openvpnfull') === -1 && frame.src.indexOf('/nradioadv/system/openlist') === -1 && frame.src.indexOf('/nradioadv/system/zerotier') === -1 && frame.src.indexOf('/nradioadv/system/fanctrl') === -1 && frame.src.indexOf('/nradioadv/system/mosdns') === -1 && frame.src.indexOf('/admin/vpn/easytier') === -1 && frame.src.indexOf('/nradioadv/system/webssh') === -1 && frame.src.indexOf('/nradioadv/system/ddnsgo') === -1 && frame.src.indexOf('/nradioadv/system/qiyou') === -1 && frame.src.indexOf('/nradioadv/system/leigod') === -1 && frame.src.indexOf('/nradioadv/system/aibot') === -1 && frame.src.indexOf('/nradio/ai') === -1) {
                $(frame).removeClass("nr-frame-loading").addClass("nr-frame-ready").css({
                    "opacity": "1",
                    "visibility": "visible"
                });
                return;
            }

            set_openclash_fallback(false);
            if(is_openclash_frame(frame))
                ensure_openclash_wide_css(d);

            var iframe_main = $('#sub_frame').contents().find('.main');
            var iframe_container = $('#sub_frame').contents().find('.body-container');
            if(iframe_main)
                $(iframe_main).addClass("inner_main");
            if(iframe_container)
                $(iframe_container).addClass("inner_container");

            var hide_selectors = [
                'header',
                '.menu_mobile',
                '.mobile_bg_color.container.body-container.visible-xs-block',
                '.footer',
                '.tail_wave',
                '.menu-top',
                '.logo-nradio',
                '.large_banner',
                '.small_banner',
                '.main-logo-size',
                '.mobile-logo-size',
                '.qmenu',
                '.nradio-right-btn',
                '.sub_icon_list',
                '.menu-tab',
                '#mainmenu',
                '#modemenu',
                '.navbar',
                '.navbar-inner'
            ];

            $.each(hide_selectors, function(index, sel){
                $(d).find(sel).css('display', 'none');
            });

            $(d).find('.container.body-container').not('.visible-xs-block').css({
                'width': '100%',
                'max-width': 'none',
                'min-width': '0',
                'margin': '0',
                'padding': '0 10px'
            });
            $(d).find('.main').css({
                'width': '100%',
                'max-width': 'none',
                'min-width': '0',
                'margin': '0'
            });
            $(d).find('.main-content').css({
                'width': '100%',
                'max-width': 'none',
                'min-width': '0',
                'margin': '0',
                'padding': '0'
            });
            $(d).find('html, body').css({
                'width': '100%',
                'max-width': 'none',
                'min-width': '0',
                'overflow-x': 'hidden'
            });
            if(frame.src.indexOf('/nradioadv/system/webssh') === -1) {
                $(d).find('html, body').css({
                    'overflow-y': 'auto',
                    '-webkit-overflow-scrolling': 'touch',
                    'touch-action': 'pan-x pan-y',
                    'overscroll-behavior-y': 'contain'
                });
                nradio_app_frame_enable_mobile_touch_scroll(frame, d);
            }
            $(d.body).css({
                'margin-top': '0',
                'padding-top': '0'
            });
            $(frame).removeClass("nr-frame-loading").addClass("nr-frame-ready").css({
                "opacity": "1",
                "visibility": "visible"
            });
            if(is_openclash_frame(frame))
                schedule_openclash_render_check(frame);
        }
        catch(e) {
            $("#sub_frame").removeClass("nr-frame-loading").addClass("nr-frame-ready").css({
                "opacity": "1",
                "visibility": "visible"
            });
            var frame = document.getElementById('sub_frame');
            if(is_openclash_frame(frame))
                set_openclash_fallback(true);
        }
    }
    function get_app_route_url(route){
        return "<%=controller%>" + route;
    }
    function open_openclash_original_page(){
        window.top.location.href = "/cgi-bin/luci/admin/services/openclash/client";
    }
    function is_openclash_frame(frame){
        return frame && frame.src && frame.src.indexOf('/admin/services/openclash') !== -1;
    }
    function set_openclash_fallback(show){
        $(".app_frame_openclash").toggleClass("nr-openclash-fallback-on", !!show);
    }
    function reload_openclash_frame(){
        var frame = document.getElementById('sub_frame');
        if(!frame)
            return;

        set_openclash_fallback(false);
        var src = frame.getAttribute("data-src") || get_app_route_url("admin/services/openclash/client");
        $(frame).removeClass("nr-frame-ready").addClass("nr-frame-loading").attr("src", src);
    }
    function ensure_openclash_wide_css(d){
        if(!d || !d.head || d.getElementById("nr-openclash-wide-css"))
            return;

        var style = d.createElement("style");
        style.id = "nr-openclash-wide-css";
        style.type = "text/css";
        style.appendChild(d.createTextNode([
            "html,body{width:100%!important;max-width:none!important;min-width:0!important;overflow-x:auto!important;background:#2e2e38!important;}",
            ".container.body-container,.main,.main-content,#maincontent,#content{width:100%!important;max-width:none!important;min-width:0!important;margin:0!important;box-sizing:border-box!important;}",
            ".container.body-container{padding:0 10px!important;}",
            ".cbi-map,.cbi-section,.table,.table-responsive,form{max-width:none!important;box-sizing:border-box!important;}",
            ".table-responsive{overflow-x:auto!important;}"
        ].join("\n")));
        d.head.appendChild(style);
    }
    function openclash_content_visible(d){
        if(!d || !d.body)
            return false;

        var body_text = (d.body.textContent || "").replace(/\s+/g, "");
        var body_height = $(d.body).height() || d.body.scrollHeight || 0;
        if(body_text.indexOf("OpenClash") >= 0)
            return true;
        if(body_text.length > 12 && body_height > 40)
            return true;

        var visible = false;
        $(d).find(".cbi-map,.cbi-section,.table,.table-responsive,.panel,.alert-message,.alert,.main-content,.main").each(function(){
            var rect = this.getBoundingClientRect ? this.getBoundingClientRect() : null;
            if(rect && rect.width > 80 && rect.height > 24) {
                visible = true;
                return false;
            }
        });

        if(visible && body_text.length > 0)
            return true;
        return false;
    }
    function check_openclash_render(frame, allow_show){
        if(!is_openclash_frame(frame))
            return;

        try {
            var d = frame.contentWindow.document;
            ensure_openclash_wide_css(d);
            if(openclash_content_visible(d))
                set_openclash_fallback(false);
            else if(allow_show)
                set_openclash_fallback(true);
        }
        catch(e) {
            set_openclash_fallback(false);
        }
    }
    function schedule_openclash_render_check(frame){
        window.setTimeout(function(){ check_openclash_render(frame, false); }, 800);
        window.setTimeout(function(){ check_openclash_render(frame, false); }, 1800);
        window.setTimeout(function(){ check_openclash_render(frame, true); }, 3500);
        window.setTimeout(function(){ check_openclash_render(frame, true); }, 6500);
    }
    function build_app_iframe(route){
        if(route && route.length > 0)
            return "<iframe id='sub_frame' class='app_frame_page nr-frame-loading' data-src='" + get_app_route_url(route) + "' name='subpage' scrolling='auto'></iframe>";
        return "<iframe id='sub_frame' class='app_frame_page nr-frame-loading' name='subpage' scrolling='auto'></iframe>";
    }
    function is_openclash_route(route){
        return route && route.indexOf("admin/services/openclash") === 0;
    }
    function is_adguardhome_route(route){
        return route && route.indexOf("admin/services/AdGuardHome") === 0;
    }
    function get_openclash_frame(route){
        var current_route = route && route.length > 0 ? route : "admin/services/openclash/client";
        if(current_route == "admin/services/openclash")
            current_route = "admin/services/openclash/client";

        var tabs = [
            {route: "admin/services/openclash/client", title: "<%:Overviews%>"},
            {route: "admin/services/openclash/settings", title: "<%:Plugin Settings%>"},
            {route: "admin/services/openclash/config-overwrite", title: "<%:Overwrite Settings%>"},
            {route: "admin/services/openclash/config-subscribe", title: "<%:Config Subscribe%>"},
            {route: "admin/services/openclash/config", title: "<%:Config Manage%>"},
            {route: "admin/services/openclash/log", title: "<%:Server Logs%>"}
        ];

        var sub_web_ht = "<div class='app_frame_box app_frame_tabs app_frame_openclash'><nav class='app_frame_nav' aria-label='哈基米功能导航'>";
        $.each(tabs, function(index, tab){
            var active_class = "";
            if(tab.route == current_route)
                active_class = " app_frame_nav_item_active";
            sub_web_ht += "<button type='button' class='app_frame_nav_item" + active_class + "' aria-pressed='" + (tab.route == current_route ? "true" : "false") + "' data-route='" + tab.route + "' onclick='switch_app_frame_route(this)'>" + tab.title + "</button>";
        });
        sub_web_ht += "<button type='button' class='app_frame_origin_button' onclick='open_openclash_original_page()'>原版页面</button>";
        sub_web_ht += "</nav><div id='nr-openclash-fallback' class='nr-openclash-fallback'><span class='nr-openclash-fallback_badge'>!</span><span class='nr-openclash-fallback_text'><strong>OpenClash 页面未正常显示</strong><em>可重载弹窗，或在顶层打开原版页面。</em></span><span class='nr-openclash-fallback_actions'><button type='button' class='nr-openclash-fallback_btn' onclick='reload_openclash_frame()'>重载</button><button type='button' class='nr-openclash-fallback_btn' onclick='open_openclash_original_page()'>原版页面</button></span></div>" + build_app_iframe(current_route) + "</div>";

        return sub_web_ht;
    }
    function get_adguardhome_frame(route){
        var current_route = route && route.length > 0 ? route : "admin/services/AdGuardHome/base";
        if(current_route == "admin/services/AdGuardHome")
            current_route = "admin/services/AdGuardHome/base";

        var tabs = [
            {route: "admin/services/AdGuardHome/base", title: "Base Setting"},
            {route: "admin/services/AdGuardHome/manual", title: "Manual Config"},
            {route: "admin/services/AdGuardHome/log", title: "Log"}
        ];

        var sub_web_ht = "<div class='app_frame_box app_frame_tabs'><div class='app_frame_nav'>";
        $.each(tabs, function(index, tab){
            var active_class = "";
            if(tab.route == current_route)
                active_class = " app_frame_nav_item_active";
            sub_web_ht += "<span class='app_frame_nav_item" + active_class + "' data-route='" + tab.route + "' onclick='switch_app_frame_route(this)'>" + tab.title + "</span>";
        });
        sub_web_ht += "</div>" + build_app_iframe(current_route) + "</div>";

        return sub_web_ht;
    }
    function build_app_frame(route){
        if(is_openclash_route(route))
            return get_openclash_frame(route);
        if(is_adguardhome_route(route))
            return get_adguardhome_frame(route);
        return "<div class='app_frame_box app_frame_plain'>" + build_app_iframe(route) + "</div>";
    }
    function switch_app_frame_route(obj){
        var route = $(obj).data("route");
        $(".app_frame_nav_item").removeClass("app_frame_nav_item_active").filter("[aria-pressed]").attr("aria-pressed", "false");
        $(obj).addClass("app_frame_nav_item_active").filter("[aria-pressed]").attr("aria-pressed", "true");
        var frame_src = get_app_route_url(route);
        $("#sub_frame").removeClass("nr-frame-ready").addClass("nr-frame-loading").attr("data-src", frame_src).attr("src", frame_src);
    }
    function nradio_plugin_uninstall_key(app_name){
        if(app_name == "luci-app-openclash" || app_name == "openclash")
            return "openclash";
        if(app_name == "Web SSH" || app_name == "webssh" || app_name == "ttyd")
            return "webssh";
        if(app_name == "luci-app-adguardhome" || app_name == "adguardhome")
            return "adguardhome";
        if(app_name == "OpenVPN" || app_name == "openvpn" || app_name == "luci-app-openvpn")
            return "openvpn";
        if(app_name == "OpenList" || app_name == "openlist" || app_name == "luci-app-openlist")
            return "openlist";
        if(app_name == "ZeroTier" || app_name == "zerotier")
            return "zerotier";
        if(app_name == "EasyTier" || app_name == "easytier" || app_name == "luci-app-easytier")
            return "easytier";
        if(app_name == "FanControl Plus" || app_name == "fanctrl-plus" || app_name == "FanControl" || app_name == "fanctrl")
            return "fanctrl";
        if(app_name == "MosDNS" || app_name == "mosdns")
            return "mosdns";
        if(app_name == "DDNS-GO" || app_name == "DDNS-Go" || app_name == "ddns-go" || app_name == "luci-app-ddns-go" || app_name == "luci-i18n-ddns-go-zh-cn")
            return "ddnsgo";
        if(app_name == "MT5700 WebUI" || app_name == "at-webserver" || app_name == "luci-app-at-webserver" || app_name == "luci-i18n-at-webserver-zh-cn")
            return "mt5700";
        if(app_name == "Docker" || app_name == "docker" || app_name == "dockerd" || app_name == "nradio-docker")
            return "docker";
        if(app_name == "奇游联机宝" || app_name == "QiYou" || app_name == "qiyou" || app_name == "nradio-qiyou")
            return "qiyou";
        if(app_name == "雷神加速器" || app_name == "Leigod" || app_name == "LeigodAcc" || app_name == "leigod" || app_name == "nradio-leigod")
            return "leigod";
        return "";
    }
    function nradio_plugin_uninstall_result(data){
        if(data && data.result)
            return data.result;
        return data || {};
    }
    function nradio_plugin_uninstall_finish(dialogDeal, ok, msg){
        if(dialogDeal)
            dialogDeal.close();

        BootstrapDialog.show({
            type: ok ? BootstrapDialog.TYPE_SUCCESS : BootstrapDialog.TYPE_DANGER,
            title: "<%:Tips%>",
            message: msg,
            buttons: [{
                label: "<%:OK%>",
                cssClass: "btn-primary",
                action: function(dialog){
                    dialog.close();
                    if(ok) {
                        if(typeof refresh_data == "function")
                            refresh_data();
                        else
                            window.location.reload();
                    }
                }
            }]
        });
    }
    function nradio_plugin_uninstall_poll(app_name, dialogDeal){
        $.ajax({
            type: "POST",
            url: "<%=controller%>nradioadv/system/plugin_uninstall/check",
            data: { token: "<%=require('luci.dispatcher').context.authtoken%>", name: app_name },
            dataType: "json",
            success: function(data){
                var result = nradio_plugin_uninstall_result(data);
                var code = parseInt(result.code, 10);

                if(code == 2) {
                    setTimeout(function(){
                        nradio_plugin_uninstall_poll(app_name, dialogDeal);
                    }, 2000);
                    return;
                }

                if(code == 0) {
                    nradio_plugin_uninstall_finish(dialogDeal, true, result.msg || "卸载完成");
                    return;
                }

                nradio_plugin_uninstall_finish(dialogDeal, false, result.errro_detail || result.error_detail || result.msg || "卸载失败");
            },
            error: function(){
                nradio_plugin_uninstall_finish(dialogDeal, false, "卸载状态检查失败");
            }
        });
    }
    function nradio_plugin_uninstall_start(app_name, dialogDeal){
        $.ajax({
            type: "POST",
            url: "<%=controller%>nradioadv/system/plugin_uninstall/start",
            data: { token: "<%=require('luci.dispatcher').context.authtoken%>", name: app_name },
            dataType: "json",
            success: function(data){
                var result = nradio_plugin_uninstall_result(data);
                var code = parseInt(result.code, 10);

                if(code == 2) {
                    nradio_plugin_uninstall_poll(app_name, dialogDeal);
                    return;
                }

                if(code == 0) {
                    nradio_plugin_uninstall_finish(dialogDeal, true, result.msg || "卸载完成");
                    return;
                }

                nradio_plugin_uninstall_finish(dialogDeal, false, result.errro_detail || result.error_detail || result.msg || "卸载失败");
            },
            error: function(){
                nradio_plugin_uninstall_finish(dialogDeal, false, "卸载启动失败");
            }
        });
    }
    function nradio_plugin_uninstall_action(app_name){
        var msg = {};
        var dialogDeal = null;

        if(!nradio_plugin_uninstall_key(app_name))
            return false;

        msg.message = '<i class="far fa-nradio-note fa-fw icon_disable" ></i><%:AppUninstallNote%>';
        msg.confirm = "<%:Confirm%>";
        msg.confirm_keep = true;
        msg.cancel = "<%:Cancel%>";
        msg.onhide = function(){};
        msg.callback = function(){
            $(".modal-footer").css("display","none");
            dialogDeal.setMessage(loading_htm);
            nradio_plugin_uninstall_start(app_name, dialogDeal);
        };
        dialogDeal = confirm_box(msg);
        return true;
    }
    function callback(id,route){
        ensure_app_frame_polish_css();
        var sub_web_ht = build_app_frame(route);
        $(".top_menu").removeClass("top_menu_active");
        $(".top_menu").each(function(){
            var cur_index = $(this).data("index");
            if(cur_index == id){
                $(this).addClass("top_menu_active");
            }
        });

        sub_dialogDeal = BootstrapDialog.show({
            type: BootstrapDialog.TYPE_DEFAULT,
            closeByBackdrop: true,
            cssClass:'app_frame',
            title: '',
            message: sub_web_ht,
            onhide:function(){
                $(".top_menu").removeClass("top_menu_active");
                $(".top_menu").eq(0).addClass("top_menu_active");
            },
            onshown:function(){
                $(".modal.app_frame").scrollTop(0);
                var frame = $('#sub_frame');
                frame.off('load.nradioAppFrame').on('load.nradioAppFrame', function() {
                    reload_iframe();
                });
                frame.removeClass("nr-frame-ready").addClass("nr-frame-loading");
                var initial_src = frame.attr("data-src");
                if(initial_src && !frame.attr("src"))
                    frame.attr("src", initial_src);
                else
                    reload_iframe();
            }
        });
    }
EOF

    if grep -q 'app_frame_nav_item' "$TPL"; then
        cp "$TPL" "$tmp1"
    else
        awk -v css_file="$css_file" '
            {
                print
                if ($0 ~ /^    \.modal\.app_frame\.in \.modal-content\{$/) {
                    in_target = 1
                    next
                }
                if (in_target && $0 ~ /^    }$/) {
                    while ((getline extra < css_file) > 0) print extra
                    close(css_file)
                    in_target = 0
                }
            }
        ' "$TPL" > "$tmp1"
    fi

    tmp_css_fix="$WORKDIR/appcenter.iframe-css-fix"
    awk '
        BEGIN { in_box = 0; in_nav = 0; in_frame = 0 }
        /^    \.app_frame_box\{$/ { in_box = 1; print; next }
        /^    \.app_frame_nav\{$/ { in_nav = 1; print; next }
        /^    \.app_frame_box iframe\{$/ { in_frame = 1; print; next }
        /^[[:space:]]*min-height: calc\(84vh \+ 34px\);[[:space:]]*$/ { print "        min-height: 0;"; next }
        /^[[:space:]]*min-height: 690px;[[:space:]]*$/ { print "        min-height: 0;"; next }
        in_box && /^[[:space:]]*background: #2e2e38;[[:space:]]*$/ { next }
        in_nav && /^[[:space:]]*background: #2e2e38;[[:space:]]*$/ { next }
        in_nav && /^[[:space:]]*border-bottom: 1px solid #e5e5e5;[[:space:]]*$/ { print "        border-bottom: 1px solid rgba(104, 130, 166, .24);"; next }
        in_nav && /^[[:space:]]*border-bottom: 1px solid rgba\(255,255,255,\.12\);[[:space:]]*$/ { print "        border-bottom: 1px solid rgba(104, 130, 166, .24);"; next }
        in_frame && /^[[:space:]]*height: 78vh;[[:space:]]*$/ { print "        height: 100%;"; next }
        in_frame && /^[[:space:]]*display: block;[[:space:]]*$/ { next }
        in_frame && /^[[:space:]]*background: #2e2e38;[[:space:]]*$/ { next }
        in_frame && /^[[:space:]]*visibility: hidden;[[:space:]]*$/ { next }
        in_box && /^    }$/ { print "        background: #2e2e38;"; in_box = 0; print; next }
        in_nav && /^    }$/ { print "        background: #2e2e38;"; in_nav = 0; print; next }
        in_frame && /^    }$/ {
            print "        display: block;"
            print "        background: #2e2e38;"
            print "        visibility: hidden;"
            in_frame = 0
            print
            next
        }
        { print }
    ' "$tmp1" > "$tmp_css_fix"
    cp "$tmp_css_fix" "$tmp1"

    awk -v js_file="$js_file" '
        BEGIN { skip = 0; inserted = 0 }
        {
            if (!skip && !inserted && ($0 ~ /^    function ensure_app_frame_polish_css\(\)\{$/ || $0 ~ /^    function get_active_app_frame\(\)\{$/ || $0 ~ /^    function reload_iframe\([^)]*\)\{$/)) {
                while ((getline extra < js_file) > 0) print extra
                close(js_file)
                skip = 1
                inserted = 1
                next
            }

            if (skip) {
                if ($0 ~ /^    function app_action\(app_name,action,id,route\)\{$/) {
                    skip = 0
                    print
                }
                next
            }

            if (!inserted && $0 ~ /^    function app_action\(app_name,action,id,route\)\{$/) {
                while ((getline extra < js_file) > 0) print extra
                close(js_file)
                inserted = 1
                print
                next
            }

            print
        }
    ' "$tmp1" > "$tmp2"

    if [ "$appcenter_template_v3" = '1' ]; then
        cp "$tmp2" "$tmp3"
    else
        if grep -q 'db.name == "OpenVPN"' "$tmp2" && grep -q 'db.name == "luci-app-openclash"' "$tmp2" && grep -q 'db.name == "luci-app-adguardhome"' "$tmp2"; then
            cp "$tmp2" "$tmp3"
        else
            awk '
                {
                    print
                    if ($0 ~ /^            if \(db\.luci_module_route\)$/) {
                        getline
                        print
                        print "            else if (db.name == \"luci-app-openclash\")"
                        print "                open_route = \"admin/services/openclash\";"
                        print "            else if (db.name == \"luci-app-adguardhome\")"
                        print "                open_route = \"admin/services/AdGuardHome\";"
                        print "            else if (db.name == \"OpenVPN\")"
                        print "                open_route = \"nradioadv/system/openvpnfull\";"
                    }
                }
            ' "$tmp2" > "$tmp3"
        fi

        bad_openclash_route='nradioadv/system/openclash''full'
        if grep -q "open_route = \"$bad_openclash_route\";" "$tmp3"; then
            tmp_openclash_route="$WORKDIR/appcenter.openclash-route"
            sed "s#open_route = \"$bad_openclash_route\";#open_route = \"admin/services/openclash\";#g" "$tmp3" > "$tmp_openclash_route"
            cp "$tmp_openclash_route" "$tmp3"
        fi

        if ! grep -q 'db.name == "OpenVPN"' "$tmp3"; then
            log 'warn: OpenVPN fallback block not found after template patch; continue with current template'
        fi

        if grep -q 'nradioadv/system/fanctrl_plus' "$tmp3"; then
            tmp_fanctrl_route="$WORKDIR/appcenter.fanctrl-route"
            sed 's#nradioadv/system/fanctrl_plus#nradioadv/system/fanctrl#g' "$tmp3" > "$tmp_fanctrl_route"
            cp "$tmp_fanctrl_route" "$tmp3"
        fi

        need_openlist_route='1'
        need_zerotier_route='1'
        need_fanctrl_route='1'
        need_qiyou_route='1'
        need_leigod_route='1'
        need_ddnsgo_route='1'
        need_mt5700_route='1'
        grep -q 'db.name == "OpenList"' "$tmp3" && need_openlist_route='0'
        grep -q 'db.name == "ZeroTier"' "$tmp3" && need_zerotier_route='0'
        grep -q 'open_route = "nradioadv/system/fanctrl";' "$tmp3" && need_fanctrl_route='0'
        grep -q 'db.name == "奇游联机宝"' "$tmp3" && need_qiyou_route='0'
        grep -q 'db.name == "雷神加速器"' "$tmp3" && need_leigod_route='0'
        grep -q 'db.name == "DDNS-GO"' "$tmp3" && need_ddnsgo_route='0'
        grep -q 'db.name == "MT5700 WebUI"' "$tmp3" && need_mt5700_route='0'
        if [ "$need_openlist_route$need_zerotier_route$need_fanctrl_route$need_qiyou_route$need_leigod_route$need_ddnsgo_route$need_mt5700_route" != '0000000' ]; then
            tmp4="$WORKDIR/appcenter.4"
            awk -v need_openlist="$need_openlist_route" -v need_zerotier="$need_zerotier_route" -v need_fanctrl="$need_fanctrl_route" -v need_qiyou="$need_qiyou_route" -v need_leigod="$need_leigod_route" -v need_ddnsgo="$need_ddnsgo_route" -v need_mt5700="$need_mt5700_route" '
                BEGIN { inserted = 0 }
                {
                    print
                    if (!inserted && $0 ~ /^                open_route = "nradioadv\/system\/openvpnfull";$/) {
                        if (need_openlist == "1") {
                            print "            else if (db.name == \"OpenList\")"
                            print "                open_route = \"nradioadv/system/openlist/basic\";"
                        }
                        if (need_zerotier == "1") {
                            print "            else if (db.name == \"ZeroTier\" || db.name == \"zerotier\")"
                            print "                open_route = \"nradioadv/system/zerotier/basic\";"
                        }
                        if (need_fanctrl == "1") {
                            print "            else if (db.name == \"FanControl Plus\" || db.name == \"fanctrl-plus\" || db.name == \"FanControl\" || db.name == \"fanctrl\")"
                            print "                open_route = \"nradioadv/system/fanctrl\";"
                        }
                        if (need_qiyou == "1") {
                            print "            else if (db.name == \"奇游联机宝\" || db.name == \"QiYou\" || db.name == \"qiyou\" || db.name == \"nradio-qiyou\")"
                            print "                open_route = \"nradioadv/system/qiyou\";"
                        }
                        if (need_leigod == "1") {
                            print "            else if (db.name == \"雷神加速器\" || db.name == \"Leigod\" || db.name == \"LeigodAcc\" || db.name == \"leigod\" || db.name == \"nradio-leigod\")"
                            print "                open_route = \"nradioadv/system/leigod\";"
                        }
                        if (need_ddnsgo == "1") {
                            print "            else if (db.name == \"DDNS-GO\" || db.name == \"DDNS-Go\" || db.name == \"ddns-go\" || db.name == \"luci-app-ddns-go\" || db.name == \"luci-i18n-ddns-go-zh-cn\")"
                            print "                open_route = \"nradioadv/system/ddnsgo\";"
                        }
                        if (need_mt5700 == "1") {
                            print "            else if (db.name == \"MT5700 WebUI\" || db.name == \"at-webserver\" || db.name == \"luci-app-at-webserver\" || db.name == \"luci-i18n-at-webserver-zh-cn\")"
                            print "                open_route = \"nradioadv/system/mt5700\";"
                        }
                        inserted = 1
                    }
                }
            ' "$tmp3" > "$tmp4"
            cp "$tmp4" "$tmp3"
        fi
    fi

    tmp5="$WORKDIR/appcenter.5"
    awk '
        BEGIN { skip_return = 0 }
