    @media (max-width: 1180px){
        .appcontainer{
            --nr-status-rail: 100%;
            --nr-status-reserve: 0px;
            --nr-status-gap: 0px;
            --nr-status-edge: 0;
            --nr-app-card-size: clamp(190px, 30vw, 230px);
        }
        .app_btn_box{
            padding-right: 0;
            flex-wrap: wrap;
        }
        .app_btn_box .mem_track{
            flex: 1 1 260px;
        }
        .app_btn_box .app_btn_group{
            position: static;
            width: auto;
            min-width: 212px;
        }
        #app_status_mount{
            position: relative;
            right: auto;
            top: auto;
            width: 100%;
            margin: 0 0 14px;
        }
        .container_right{
            grid-template-columns: repeat(auto-fill, minmax(var(--nr-app-card-size), var(--nr-app-card-size)));
            justify-content: start;
            padding-right: 0 !important;
        }
        .container_right .app_box:nth-child(n)::after{
            background: linear-gradient(90deg, rgba(var(--nr-card-accent),0), rgba(var(--nr-card-accent),.38), rgba(var(--nr-card-accent-2),.24), rgba(var(--nr-card-accent),0));
        }
        .app_status_panel{
            min-height: 0;
        }
    }
    @media (max-width: 760px){
        #app_status_mount{
            position: relative;
            right: auto;
            top: auto;
            z-index: auto;
            flex: 1 1 100%;
            width: 100%;
            min-width: 0;
            max-width: 100%;
            margin-left: 0;
        }
        .app_btn_box{
            padding-right: 0;
            flex-wrap: wrap;
        }
        .app_btn_box .app_btn_group{
            position: static;
            right: auto;
            top: auto;
            width: auto;
            min-height: 0;
            padding: 0;
            border: 0;
            border-radius: 0;
            background: transparent;
            box-shadow: none;
        }
        .container_right{
            grid-template-columns: repeat(auto-fill, minmax(min(100%, 180px), 1fr));
            padding-right: 0 !important;
        }
        .container_right .app_box{
            aspect-ratio: 1 / 1;
            width: auto !important;
            max-width: none;
            min-height: 0;
        }
        .app_status_panel{
            position: relative;
            right: auto;
            top: auto;
            width: calc(100% - 20px);
            margin: 12px 10px 0;
        }
        .app_status_head{
            align-items: flex-start;
            flex-direction: column;
            gap: 4px;
        }
        .app_status_grid{
            grid-template-columns: 1fr;
        }
    }
