            radial-gradient(circle at 18% -6%, rgba(var(--nr-card-accent, 84,178,198),.072), transparent 42%),
            radial-gradient(circle at 82% 4%, rgba(var(--nr-card-accent-2, 58,130,112),.030), transparent 34%),
