            0 1.10em 2.22em rgba(0,0,0,.382),
            0 0 .78em rgba(var(--nr-card-accent, 78,150,166), .034);
    }
    .container_right .app_icon::before{
        box-shadow:
            inset 0 .08em 0 rgba(255,255,255,.050),
            inset 0 0 0 .0625rem rgba(var(--nr-card-accent, 78,150,166), .095),
            0 .62em 1em rgba(0,0,0,.22);
    }
    .container_right .app_icon_img{
        filter: saturate(.98) contrast(1.045);
    }
    .container_right .app_box:hover .app_icon_img,
    .container_right .app_box:focus-within .app_icon_img{
        filter: saturate(1.05) contrast(1.055);
    }
    .container_right .app_name{
        color: rgba(248,252,255,.965);
        text-shadow: 0 1px 0 rgba(0,0,0,.34);
    }
    .container_right .app_des,
    .container_right .app_version{
        color: rgba(210,221,232,.805);
    }
    .container_right .app_state_badge,
    .container_right .app_open_badge{
        background: linear-gradient(180deg, rgba(255,255,255,.030), rgba(255,255,255,.006)), rgba(5,12,22,.54);
        box-shadow: inset 0 .08em 0 rgba(255,255,255,.038);
    }
    .container_right .app_state_badge::before,
    .container_right .app_open_badge::before{
        box-shadow: 0 0 .42em currentColor;
    }
    .container_right .action_list_li{
        text-shadow: 0 1px 0 rgba(0,0,0,.22);
    }
    .container_right .action_list_li:hover,
    .container_right .action_list_li:focus-visible{
        color: #ffffff;
        filter: saturate(1.02) contrast(1.012);
    }
    .app_status_panel{
        border-color: rgba(125,211,252,.28);
        box-shadow:
            inset 0 .08em 0 rgba(255,255,255,.052),
            inset 0 0 0 .0625rem rgba(103,232,249,.052),
            0 1.04em 1.98em rgba(0,0,0,.245);
    }
    .app_status_tile,
    .app_status_metric{
        border-color: rgba(125,211,252,.18);
        box-shadow:
            inset 0 .08em 0 rgba(255,255,255,.044),
            0 .40em .76em rgba(0,0,0,.11);
    }
    .app_status_metric:nth-of-type(6){
        --nr-metric-accent: 168,85,247;
    }
    .app_status_swap_bar{
        background: linear-gradient(90deg, #a78bfa, #60a5fa 62%, #23c8e4) !important;
    }
    .app_status_metric_row strong,
    .app_status_tile strong{
        font-variant-numeric: tabular-nums;
    }
    /* NRadio appcenter final optical alignment layer */
    .container_right .app_box,
    .container_right .app_box *{
        -webkit-font-smoothing: antialiased;
        text-rendering: geometricPrecision;
    }
    .container_right .app_name,
    .container_right .app_des,
    .container_right .app_version,
    .container_right .app_state_badge,
    .container_right .app_open_badge{
        overflow-wrap: anywhere;
    }
    .container_right .action_list_li:focus-visible,
    .app_status_panel a:focus-visible,
    .app_status_panel button:focus-visible{
        outline: none;
        box-shadow: 0 0 0 .18em rgba(103,232,249,.18), inset 0 .08em 0 rgba(255,255,255,.05);
    }
    .app_status_panel,
    .app_status_tile,
    .app_status_metric{
        backdrop-filter: saturate(1.04) blur(.18em);
        -webkit-backdrop-filter: saturate(1.04) blur(.18em);
    }
EOF_APPCENTER_PREMIUM_VISUAL_FINISH

    awk -v css_file="$css_file" '
        /NRadio appcenter card polish: visual-only layer/ || /NRadio appcenter card polish V1\.60\.5 full repair layer/ {
            skip_polish_css = 1
            next
        }
        skip_polish_css && /^<\/style>$/ {
            while ((getline extra < css_file) > 0) print extra
            close(css_file)
            print
            inserted = 1
            skip_polish_css = 0
            next
        }
        skip_polish_css {
            next
        }
        /^<\/style>$/ && !inserted {
            while ((getline extra < css_file) > 0) print extra
            close(css_file)
            inserted = 1
        }
        { print }
    ' "$TPL" > "$tmp_css"
    cp "$tmp_css" "$TPL"

    awk '
        /app_status_hint/ { next }
        /刷新/ && /安装卸载/ { next }
        { print }
    ' "$TPL" > "$tmp_panel"
    cp "$tmp_panel" "$TPL"

    cat > "$status_js_file" <<'EOF_APPCENTER_STATUS_PANEL_JS'
    var APP_STATUS_LAST = null;
    var APP_STATUS_POLLING = false;
    var APP_STATUS_TIMER = null;
    var APP_STATUS_INTERVAL = 2000;

    function build_app_status_panel_from_data(data){
        var installed_count = 0;
        var open_count = 0;
        var all_count = 0;

        if(data && data.result && data.result.applist){
            $.each(data.result.applist, function(index, db){
                all_count++;
                if(db.open == 1)
                    open_count++;
                if(db.status == APP_STATUS_APP_INSTALLED || db.status == APP_STATUS_APP_UPDATEED)
                    installed_count++;
            });
        }

        return build_app_status_panel(installed_count, open_count, all_count);
    }

    function ensure_app_status_mount(){
        if(!$("#app_status_mount").length)
            $(".app_btn_box").after('<div id="app_status_mount"></div>');
    }

    function render_app_status_panel(data){
        ensure_app_status_mount();
        $("#app_status_mount").html(build_app_status_panel_from_data(data));
        if(APP_STATUS_LAST)
            update_app_status_panel(APP_STATUS_LAST);
    }

    function build_app_empty_state(title){
        return ''+
        '<div class="app_empty_state">'+
        '    <strong>'+title+'</strong>'+
        '</div>';
    }

    function build_app_status_panel(installed_count, open_count, all_count){
        return ''+
        '<aside class="app_status_panel">'+
        '    <div class="app_status_head"><span>系统状态</span><em class="app_status_time">等待刷新</em></div>'+
        '    <div class="app_status_grid">'+
        '        <div class="app_status_tile"><strong>'+installed_count+'</strong><span>已安装</span></div>'+
        '        <div class="app_status_tile"><strong>'+open_count+'</strong><span>后台</span></div>'+
        '        <div class="app_status_tile"><strong>'+all_count+'</strong><span>全部</span></div>'+
        '    </div>'+
        '    <div class="app_status_metric">'+
        '        <div class="app_status_metric_row"><span>CPU 温度</span><strong class="app_status_temp">--</strong></div>'+
        '        <div class="app_status_bar"><span class="app_status_temp_bar"></span></div>'+
        '    </div>'+
        '    <div class="app_status_metric">'+
        '        <div class="app_status_metric_row"><span>CPU 使用率</span><strong class="app_status_cpu">采样中</strong></div>'+
        '        <div class="app_status_bar"><span class="app_status_cpu_bar"></span></div>'+
        '    </div>'+
        '    <div class="app_status_metric">'+
        '        <div class="app_status_metric_row"><span>内存占用</span><strong class="app_status_mem">--</strong></div>'+
        '        <div class="app_status_bar"><span class="app_status_mem_bar"></span></div>'+
        '    </div>'+
        '    <div class="app_status_metric app_status_swap_metric" style="display:none">'+
        '        <div class="app_status_metric_row"><span>swap 虚拟内存</span><strong class="app_status_swap">--</strong></div>'+
        '        <div class="app_status_bar"><span class="app_status_swap_bar"></span></div>'+
        '    </div>'+
        '</aside>';
    }

    function format_kib(kib){
        var mb = Number(kib || 0) / 1024;
        if(mb >= 1024)
            return (mb / 1024).toFixed(1) + " G";
        return mb.toFixed(0) + " M";
    }

    function set_status_width(selector, value){
        var percent = Number(value || 0);
        percent = Math.max(0, Math.min(100, percent));
        $(selector).css("width", percent.toFixed(1) + "%");
    }

    function update_app_status_panel(data){
        if(!data) return;
        APP_STATUS_LAST = data;

        var temp = Number(data.cpu_temp || 0);
        var cpu = data.cpu_percent;
        var mem_percent = Number(data.mem_percent || 0);
        var now = new Date();

        $(".app_status_time").text(("0"+now.getHours()).slice(-2)+":"+("0"+now.getMinutes()).slice(-2)+":"+("0"+now.getSeconds()).slice(-2));
        $(".app_status_temp").text(temp > 0 ? temp.toFixed(1) + " ℃" : "--");
        set_status_width(".app_status_temp_bar", temp > 0 ? Math.min(100, temp) : 0);

        if(cpu === null || typeof cpu === "undefined" || cpu === ""){
            $(".app_status_cpu").text("采样中");
            set_status_width(".app_status_cpu_bar", 0);
        }
        else{
            cpu = Number(cpu || 0);
            $(".app_status_cpu").text(cpu.toFixed(1) + "%");
            set_status_width(".app_status_cpu_bar", cpu);
        }

        var mem_text = format_kib(data.mem_used) + " / " + format_kib(data.mem_total);
        $(".app_status_mem").text(mem_text).attr("title", mem_text + " · " + mem_percent.toFixed(1) + "%");
        set_status_width(".app_status_mem_bar", mem_percent);

        var supports_swap = data.supports_swap === true || data.supports_swap == 1 || data.is_c2000max === true || data.is_c2000max == 1 || data.model_name == "NRadio_C2000MAX" || data.model == "NRadio_C2000MAX" || data.model_name == "NRadio_C2000Ultra" || data.model == "NRadio_C2000Ultra";
        if(supports_swap){
            var swap_total = Number(data.swap_total || 0);
            var swap_used = Number(data.swap_used || 0);
            var swap_percent = Number(data.swap_percent || 0);
            var swap_text = swap_total > 0 ? (format_kib(swap_used) + " / " + format_kib(swap_total)) : "未启用";
            $(".app_status_swap_metric").show();
            $(".app_status_swap").text(swap_text).attr("title", swap_total > 0 ? (swap_text + " · " + swap_percent.toFixed(1) + "%") : "未启用 swap");
            set_status_width(".app_status_swap_bar", swap_total > 0 ? swap_percent : 0);
        }
        else{
            $(".app_status_swap_metric").hide();
            set_status_width(".app_status_swap_bar", 0);
        }
    }

    function get_system_status(){
        if(APP_STATUS_POLLING)
            return;
        APP_STATUS_POLLING = true;
        var data={};
        data['token']='<%=token%>';
        (new XHR()).post('<%=controller%>nradioadv/system/appcenter/sys_status', data, function(xhr){
            APP_STATUS_POLLING = false;
            if (xhr && xhr.getResponseHeader("Content-Type") == "application/json") {
                try {
                    var data_res = JSON.parse(xhr.responseText || '{}');
                    if(data_res && data_res.result)
                        update_app_status_panel(data_res.result);
                }
                catch(e) {
                }
            }
        });
    }

    function start_app_status_polling(){
        get_system_status();
        if(APP_STATUS_TIMER)
            window.clearInterval(APP_STATUS_TIMER);
        APP_STATUS_TIMER = window.setInterval(get_system_status, APP_STATUS_INTERVAL);
    }
EOF_APPCENTER_STATUS_PANEL_JS

    cat > "$empty_js_file" <<'EOF_APPCENTER_EMPTY_STATE_JS'
    function build_app_empty_state(title){
        return ''+
        '<div class="app_empty_state">'+
        '    <strong>'+title+'</strong>'+
        '</div>';
    }

EOF_APPCENTER_EMPTY_STATE_JS

    awk '
        /^[[:space:]]*<div id="app_status_mount"><\/div>[[:space:]]*$/ { next }
        /^[[:space:]]*get_system_status\(\);[[:space:]]*$/ { next }
        /^[[:space:]]*start_app_status_polling\(\);[[:space:]]*$/ { next }
        /^[[:space:]]*if \(typeof start_app_status_polling == "function"\) start_app_status_polling\(\);[[:space:]]*$/ { next }
        /^[[:space:]]*window\.setInterval\(get_system_status, (1000|2000|5000|6000)\);[[:space:]]*$/ { next }
        /^[[:space:]]*var APP_STATUS_LAST = null;[[:space:]]*$/ {
            skip_status = 1
            next
        }
        skip_status {
            if ($0 ~ /^[[:space:]]*var loading_htm = /) {
                skip_status = 0
                print
            }
            next
        }
        /^[[:space:]]*function build_app_empty_state\(title/ {
            skip_empty_func = 1
            next
        }
        skip_empty_func {
            if ($0 ~ /^    }$/)
                skip_empty_func = 0
            next
        }
        /var status_panel = build_app_status_panel_from_data\(data\);/ { next }
        /var status_panel = build_app_status_panel\(installed_count, open_count, all_count\);/ { next }
        /^[[:space:]]*render_app_status_panel\(data\);[[:space:]]*$/ { next }
        /^[[:space:]]*if \(typeof render_app_status_panel == "function"\) render_app_status_panel\(data\);[[:space:]]*$/ { next }
        /^[[:space:]]*\$\("\.app_all"\)\.html\(htm\);[[:space:]]*$/ { next }
        /^[[:space:]]*\$\("\.app_installed"\)\.html\(htm_installed\);[[:space:]]*$/ { next }
        /^[[:space:]]*if\(!htm_installed\)[[:space:]]*$/ {
            skip_installed_empty = 1
            next
        }
        skip_installed_empty && /htm_installed[[:space:]]*=[[:space:]]*build_app_empty_state/ {
            skip_installed_empty = 0
            next
        }
        /^[[:space:]]*if\(!htm\)[[:space:]]*$/ {
            skip_all_empty = 1
            next
        }
        skip_all_empty && /htm[[:space:]]*=[[:space:]]*build_app_empty_state/ {
            skip_all_empty = 0
            next
        }
        /\$\("\.app_all"\)\.html\(htm \+ status_panel\);/ {
            print "        $(\".app_all\").html(htm);"
            next
        }
        /\$\("\.app_installed"\)\.html\(htm_installed \+ status_panel\);/ {
            print "        $(\".app_installed\").html(htm_installed);"
            next
        }
        /^[[:space:]]*if\(APP_STATUS_LAST\)[[:space:]]*$/ {
            skip_last_update = 1
            next
        }
        skip_last_update && /update_app_status_panel\(APP_STATUS_LAST\);/ {
            skip_last_update = 0
            next
        }
        {
            if (skip_installed_empty || skip_all_empty || skip_last_update) {
                skip_installed_empty = 0
                skip_all_empty = 0
                skip_last_update = 0
            }
            print
        }
    ' "$TPL" > "$tmp_panel"
    cp "$tmp_panel" "$TPL"

    if ! grep -q 'id="app_status_mount"' "$TPL" 2>/dev/null; then
        awk '
            /<div class="app_btn_box">/ {
                in_app_btn = 1
                print
                next
            }
            in_app_btn && /^    <\/div>[[:space:]]*$/ {
                print
                print "        <div id=\"app_status_mount\"></div>"
                in_app_btn = 0
                next
            }
            { print }
        ' "$TPL" > "$tmp_mount"
        cp "$tmp_mount" "$TPL"
    fi

    if ! grep -q '<div class="app_meta_row"' "$TPL" 2>/dev/null; then
        awk '
            {
                print
                if ($0 ~ /^        '\''            <div class="app_version" title=" \{\{version\}\}">'\''\+$/) {
                    getline line2; print line2
                    getline line3; print line3
                    print "        '\''            <div class=\"app_meta_row\">'\''+"
                    print "        '\''                <span class=\"app_state_badge app_state_{{status}}\">{{status_label}}</span>'\''+"
                    print "        '\''                {{open_badge}}'\''+"
                    print "        '\''            </div>'\''+"
                }
            }
        ' "$TPL" > "$tmp_row"
        cp "$tmp_row" "$TPL"
    fi

    if ! grep -q 'db.status_label' "$TPL" 2>/dev/null; then
        awk '
            {
                print
                if ($0 ~ /^            if \(db\.status == APP_STATUS_APP_NEW\)\{$/)
                    print "                db.status_label = \"未安装\";"
                else if ($0 ~ /^            else if \(db\.status == APP_STATUS_APP_INSTALLED\)\{$/)
                    print "                db.status_label = \"已安装\";"
                else if ($0 ~ /^            else if \(db\.status == APP_STATUS_APP_UPDATEED\)\{$/)
                    print "                db.status_label = \"可更新\";"
                else if ($0 ~ /^            if \(db\.icon && db\.icon\.length\)$/) {
                    print "            if (!db.status_label)"
                    print "                db.status_label = \"未知\";"
                    print ""
                    print "            var open_badge = \"\";"
                    print "            if (db.open == 1)"
                    print "                open_badge = '\''<span class=\"app_open_badge app_open_1\">后台</span>'\'';"
                    print ""
                }
            }
        ' "$TPL" > "$tmp_status"
        cp "$tmp_status" "$TPL"
    fi

    awk '
        {
            if ($0 ~ /^            if \(db\.icon && db\.icon\.length\)$/) {
                line2 = ""
                if ((getline line2) > 0 && line2 ~ /^            if \(!db\.status_label\)$/) {
                    getline line3
                    getline line4
                    getline line5
                    getline line6
                    getline line7
                    getline line8
                    getline line9
                    print "            if (!db.status_label)"
                    print "                db.status_label = \"未知\";"
                    print ""
                    print "            var open_badge = \"\";"
                    print "            if (db.open == 1)"
                    print "                open_badge = '\''<span class=\"app_open_badge app_open_1\">后台</span>'\'';"
                    print ""
                    print "            if (db.icon && db.icon.length)"
                    print "                icon_name = db.icon;"
                    next
                }
                print
                if (line2 != "")
                    print line2
                next
            }
            print
        }
    ' "$TPL" > "$tmp_status"
    cp "$tmp_status" "$TPL"

    if ! grep -q 'status_label: db.status_label' "$TPL" 2>/dev/null; then
        awk '
            {
                print
                if ($0 ~ /^                    opt:optht,$/ || $0 ~ /^                opt:optht,$/) {
                    prefix = substr($0, 1, index($0, "opt:") - 1)
                    print prefix "status: db.status,"
                    print prefix "status_label: db.status_label,"
                    print prefix "open_badge: open_badge,"
                }
            }
        ' "$TPL" > "$tmp_compose"
        cp "$tmp_compose" "$TPL"
    fi

    if ! grep -q 'var icon_fallback = ' "$TPL" 2>/dev/null; then
        awk '
            {
                print
                if ($0 ~ /^[[:space:]]*var icon_name = "app_default.png";[[:space:]]*$/) {
                    print "            var icon_fallback = \"this.onerror=null;this.src='\''/luci-static/nradio/images/icon/app_default.png'\'';this.className += '\'' nr_app_default_icon'\'';\";"
                }
            }
        ' "$TPL" > "$tmp_icon"
        cp "$tmp_icon" "$TPL"
    fi

    if ! grep -q 'onerror="{{icon_fallback}}"' "$TPL" 2>/dev/null; then
        awk -v tag="${SCRIPT_RELEASE_DATE}-${SCRIPT_VERSION}" '
            {
                gsub(/<img class="app_icon_img" src="\/luci-static\/nradio\/images\/icon\/\{\{icon\}\}\?v=[^"]+">/, "<img class=\"app_icon_img\" src=\"/luci-static/nradio/images/icon/{{icon}}?v=" tag "\" onerror=\"{{icon_fallback}}\">")
                gsub(/<img class="app_icon_img" src="\/luci-static\/nradio\/images\/icon\/\{\{icon\}\}">/, "<img class=\"app_icon_img\" src=\"/luci-static/nradio/images/icon/{{icon}}?v=" tag "\" onerror=\"{{icon_fallback}}\">")
                print
            }
        ' "$TPL" > "$tmp_icon"
        cp "$tmp_icon" "$TPL"
    fi

    if ! grep -q 'des_class: des_class' "$TPL" 2>/dev/null; then
        awk '
            {
                print
                if ($0 ~ /^[[:space:]]*var des_info = "&nbsp;";[[:space:]]*$/)
                    print "            var des_class = \"app_des_empty\";"
                else if ($0 ~ /^[[:space:]]*des_info[[:space:]]*=[[:space:]]*db\.des;[[:space:]]*$/)
                    print "                des_class = \"\";"
            }
        ' "$TPL" > "$tmp_desc"
        cp "$tmp_desc" "$TPL"

        awk '
            {
                gsub(/<div class="app_des" title="\{\{des\}\}">/, "<div class=\"app_des {{des_class}}\" title=\"{{des}}\">")
                print
            }
        ' "$TPL" > "$tmp_desc"
        cp "$tmp_desc" "$TPL"
    fi

    awk '
        {
            if ($0 ~ /^[[:space:]]*if\(db\.des && db\.des\.length\)[[:space:]]*$/) {
                print "            if(db.des && db.des.length){"
                if ((getline line1) > 0) {
                    if (line1 ~ /^[[:space:]]*des_info[[:space:]]*=[[:space:]]*db\.des;[[:space:]]*$/)
                        print "                des_info=db.des;"
                    else
                        print line1
                }
                if ((getline line2) > 0) {
                    if (line2 ~ /^[[:space:]]*des_class[[:space:]]*=[[:space:]]*"";[[:space:]]*$/) {
                        print "                des_class = \"\";"
                        print "            }"
                    }
                    else {
                        print "                des_class = \"\";"
                        print "            }"
                        print line2
                    }
                }
                next
            }
            print
        }
    ' "$TPL" > "$tmp_desc"
    cp "$tmp_desc" "$TPL"

    if ! grep -q 'function nr_appcenter_desc_fallback' "$TPL" 2>/dev/null; then
        awk '
            {
                print
                if ($0 ~ /^[[:space:]]*var des_class = "app_des_empty";[[:space:]]*$/) {
                    print "            function nr_appcenter_desc_fallback(name){"
                    print "                var key = (name || \"\").toLowerCase();"
                    print "                if (key.indexOf(\"openclash\") >= 0) return \"代理规则与网络分流管理\";"
                    print "                if (key.indexOf(\"openvpn\") >= 0) return \"VPN 隧道连接与远程访问\";"
                    print "                if (key.indexOf(\"adguardhome\") >= 0 || key.indexOf(\"adguard\") >= 0) return \"DNS 广告过滤与查询统计\";"
                    print "                if (key.indexOf(\"web ssh\") >= 0 || key.indexOf(\"ttyd\") >= 0) return \"浏览器 SSH 终端入口\";"
                    print "                if (key.indexOf(\"openlist\") >= 0) return \"文件列表与网络存储访问\";"
                    print "                if (key.indexOf(\"zerotier\") >= 0) return \"异地组网与虚拟局域网\";"
                    print "                if (key.indexOf(\"easytier\") >= 0) return \"点对点异地组网服务\";"
                    print "                if (key.indexOf(\"fan\") >= 0) return \"风扇温控与散热策略\";"
                    print "                if (key.indexOf(\"qiyou\") >= 0 || key.indexOf(\"奇游\") >= 0) return \"游戏联机加速入口\";"
                    print "                if (key.indexOf(\"leigod\") >= 0 || key.indexOf(\"雷神\") >= 0) return \"游戏网络加速入口\";"
                    print "                if (key.indexOf(\"ddns-go\") >= 0 || key.indexOf(\"ddnsgo\") >= 0) return \"动态 DNS 解析与公网地址同步\";"
                    print "                return \"应用功能与运行入口\";"
                    print "            }"
                }
                if ($0 ~ /^[[:space:]]*if\(db\.des && db\.des\.length\)\{[[:space:]]*$/)
                    in_des = 1
                else if (in_des && $0 ~ /^[[:space:]]*}[[:space:]]*$/) {
                    print "            if (des_class == \"app_des_empty\") {"
                    print "                des_info = nr_appcenter_desc_fallback(db.name);"
                    print "                if (des_info && des_info.length)"
                    print "                    des_class = \"\";"
                    print "            }"
                    in_des = 0
                }
            }
        ' "$TPL" > "$tmp_desc"
        cp "$tmp_desc" "$TPL"
    fi

    if ! grep -q 'function nr_appcenter_display_name' "$TPL" 2>/dev/null; then
        awk '
            {
                if ($0 ~ /^[[:space:]]*function nr_appcenter_desc_fallback\(name\)\{[[:space:]]*$/) {
                    print "            function nr_appcenter_display_name(name){"
                    print "                var raw = name || \"\";"
                    print "                var key = raw.toLowerCase();"
                    print "                if (key.indexOf(\"openclash\") >= 0) return \"哈基米\";"
                    print "                if (key.indexOf(\"adguardhome\") >= 0 || key.indexOf(\"adguard\") >= 0) return \"AdGuard Home\";"
                    print "                if (key.indexOf(\"openvpn\") >= 0) return \"OpenVPN\";"
                    print "                if (key.indexOf(\"web ssh\") >= 0 || key.indexOf(\"ttyd\") >= 0) return \"Web SSH\";"
                    print "                if (key.indexOf(\"openlist\") >= 0) return \"OpenList\";"
                    print "                if (key.indexOf(\"zerotier\") >= 0) return \"ZeroTier\";"
                    print "                if (key.indexOf(\"easytier\") >= 0) return \"EasyTier\";"
                    print "                if (key.indexOf(\"fan\") >= 0) return \"FanControl Plus\";"
                    print "                if (key.indexOf(\"qiyou\") >= 0 || key.indexOf(\"奇游\") >= 0) return \"奇游联机宝\";"
                    print "                if (key.indexOf(\"leigod\") >= 0 || key.indexOf(\"雷神\") >= 0) return \"雷神加速器\";"
                    print "                if (key.indexOf(\"ddns-go\") >= 0 || key.indexOf(\"ddnsgo\") >= 0) return \"DDNS-GO\";"
                    print "                return raw;"
                    print "            }"
                }
                print
            }
        ' "$TPL" > "$tmp_name"
        cp "$tmp_name" "$TPL"
    fi

    awk '
        {
            gsub(/return "AdGuardHome";/, "return \"AdGuard Home\";")
            print
        }
    ' "$TPL" > "$tmp_name"
    cp "$tmp_name" "$TPL"

    if ! grep -q 'display_name: nr_appcenter_display_name' "$TPL" 2>/dev/null; then
        awk '
            {
                print
                if ($0 ~ /^[[:space:]]*name:[[:space:]]*db\.name,[[:space:]]*$/) {
                    prefix = substr($0, 1, index($0, "name:") - 1)
                    print prefix "display_name: nr_appcenter_display_name(db.name),"
                }
            }
        ' "$TPL" > "$tmp_name"
        cp "$tmp_name" "$TPL"
    fi

    if ! grep -q 'function nr_appcenter_display_version' "$TPL" 2>/dev/null; then
        awk '
            {
                print
                if ($0 ~ /^[[:space:]]*function nr_appcenter_desc_fallback\(name\)\{[[:space:]]*$/)
                    in_desc_fallback = 1
                else if (in_desc_fallback && $0 ~ /^[[:space:]]*}[[:space:]]*$/) {
                    print "            function nr_appcenter_display_version(name, version){"
                    print "                var raw = version || \"\";"
                    print "                var key = (name || \"\").toLowerCase();"
                    print "                var match = raw.match(/^(git-[0-9]+[.][0-9]+[.][0-9]+)-[0-9a-f]+$/i);"
                    print "                if (key.indexOf(\"openvpn\") >= 0 && match)"
                    print "                    return match[1];"
                    print "                return raw;"
                    print "            }"
                    in_desc_fallback = 0
                }
            }
        ' "$TPL" > "$tmp_name"
        cp "$tmp_name" "$TPL"
    fi

    if ! grep -q 'display_version: nr_appcenter_display_version' "$TPL" 2>/dev/null; then
        awk '
            {
                print
                if ($0 ~ /^[[:space:]]*version:[[:space:]]*db\.version,[[:space:]]*$/) {
                    prefix = substr($0, 1, index($0, "version:") - 1)
                    print prefix "display_version: nr_appcenter_display_version(db.name, db.version),"
                }
            }
        ' "$TPL" > "$tmp_name"
        cp "$tmp_name" "$TPL"
    fi

    if ! grep -q '{{display_version}}' "$TPL" 2>/dev/null; then
        awk '
            {
                if ($0 ~ /<div class="app_version"/) {
                    in_app_version = 1
                    print
                    next
                }
                if (in_app_version && $0 ~ /\{\{[[:space:]]*version[[:space:]]*\}\}/) {
                    gsub(/\{\{[[:space:]]*version[[:space:]]*\}\}/, "{{display_version}}")
                    in_app_version = 0
                }
                if (in_app_version && $0 ~ /<\/div>/)
                    in_app_version = 0
                print
            }
        ' "$TPL" > "$tmp_name"
        cp "$tmp_name" "$TPL"
    fi

    if ! grep -q '{{display_name}}' "$TPL" 2>/dev/null; then
        awk '
            {
                if ($0 ~ /<div class="app_name"/) {
                    in_app_name = 1
                    print
                    next
                }
                if (in_app_name && $0 ~ /\{\{[[:space:]]*name[[:space:]]*\}\}/) {
                    gsub(/\{\{[[:space:]]*name[[:space:]]*\}\}/, "{{display_name}}")
                    in_app_name = 0
                }
                if (in_app_name && $0 ~ /<\/div>/)
                    in_app_name = 0
                print
            }
        ' "$TPL" > "$tmp_name"
        cp "$tmp_name" "$TPL"
    fi

    awk '
        {
            if ($0 ~ /<div class="app_name"/) {
                in_app_name = 1
                print
                next
            }
            if (in_app_name && $0 ~ /\{\{[[:space:]]*name[[:space:]]*\}\}/) {
                gsub(/\{\{[[:space:]]*name[[:space:]]*\}\}/, "{{display_name}}")
                in_app_name = 0
            }
            if (in_app_name && $0 ~ /<\/div>/)
                in_app_name = 0
            print
        }
    ' "$TPL" > "$tmp_name"
    cp "$tmp_name" "$TPL"

    if ! grep -q '{{display_name}}' "$TPL" 2>/dev/null; then
        awk '
            {
                if ($0 ~ /app_name/ && $0 ~ /\{\{[[:space:]]*name[[:space:]]*\}\}/)
                    gsub(/\{\{[[:space:]]*name[[:space:]]*\}\}/, "{{display_name}}")
                print
            }
        ' "$TPL" > "$tmp_name"
        cp "$tmp_name" "$TPL"
    fi

    if grep -q 'icon_fallback: icon_fallback' "$TPL" 2>/dev/null && grep -q 'des_class: des_class' "$TPL" 2>/dev/null; then
        :
    else
        awk '
            {
                print
                if ($0 ~ /^[[:space:]]*icon: icon_name,$/) {
                    prefix = substr($0, 1, index($0, "icon:") - 1)
                    print prefix "icon_fallback: icon_fallback,"
                    print prefix "des_class: des_class,"
                }
            }
        ' "$TPL" > "$tmp_compose"
        cp "$tmp_compose" "$TPL"
    fi

    if ! grep -q 'function render_app_status_panel(data)' "$TPL" 2>/dev/null || \
       ! grep -q 'function start_app_status_polling()' "$TPL" 2>/dev/null || \
       ! grep -q 'function build_app_status_panel_from_data(data)' "$TPL" 2>/dev/null; then
        awk -v js_file="$status_js_file" '
            /^    var loading_htm = / && !inserted {
                while ((getline extra < js_file) > 0) print extra
                close(js_file)
                inserted = 1
            }
            { print }
        ' "$TPL" > "$tmp_panel"
        cp "$tmp_panel" "$TPL"
    fi

    if ! grep -q 'typeof render_app_status_panel == "function"' "$TPL" 2>/dev/null; then
        awk '
            {
                if ($0 ~ /\$\("#app_top_menu"\)\.html\(top_menu_ht\);/) {
                    print
                    print "        if(!htm_installed)"
                    print "            htm_installed = build_app_empty_state(\"暂无已安装应用\");"
                    print "        if(!htm)"
                    print "            htm = build_app_empty_state(\"暂无应用\");"
                    print "        $(\".app_all\").html(htm);"
                    print "        $(\".app_installed\").html(htm_installed);"
                    print "        if (typeof render_app_status_panel == \"function\") render_app_status_panel(data);"
                    next
                }
                print
            }
        ' "$TPL" > "$tmp_panel"
        cp "$tmp_panel" "$TPL"
    fi

    if ! grep -q 'build_app_empty_state("暂无已安装应用")' "$TPL" 2>/dev/null; then
        awk '
            {
                if ($0 ~ /render_app_status_panel\(data\);/) {
                    print "        if(!htm_installed)"
                    print "            htm_installed = build_app_empty_state(\"暂无已安装应用\");"
                    print "        if(!htm)"
                    print "            htm = build_app_empty_state(\"暂无应用\");"
                    print
                    next
                }
                print
            }
        ' "$TPL" > "$tmp_panel"
        cp "$tmp_panel" "$TPL"
    fi

    if ! grep -q 'typeof start_app_status_polling == "function"' "$TPL" 2>/dev/null; then
        awk '
            {
                print
                if ($0 ~ /^[[:space:]]*get_memory\(\);[[:space:]]*$/)
                    print "        if (typeof start_app_status_polling == \"function\") start_app_status_polling();"
            }
        ' "$TPL" > "$tmp_ready"
        cp "$tmp_ready" "$TPL"
    fi

    awk '
        {
            gsub(/window\.setInterval\(get_system_status, (1000|5000|6000)\)/, "window.setInterval(get_system_status, 2000)")
            print
        }
    ' "$TPL" > "$tmp_ready"
    cp "$tmp_ready" "$TPL"

    verify_template_marker 'NRadio appcenter card polish: visual-only layer' '应用商店卡片美化 CSS'
    verify_template_marker 'NRadio appcenter card polish V2.0.70 full repair layer' '应用商店 V2.0.70 修复美化 CSS'
    verify_template_marker 'NRadio appcenter router hot polish: user pass 2' '应用商店本轮热更精修 CSS'
    verify_template_marker 'NRadio appcenter router hot polish: user pass 3' '应用商店 pass 3 精修 CSS'
    verify_template_marker 'NRadio appcenter router hot polish: user pass 4 final' '应用商店 pass 4 final 精修 CSS'
    verify_template_marker 'NRadio appcenter router hot polish: user pass 5 deep finish' '应用商店 pass 5 deep finish 精修 CSS'
    verify_template_marker 'NRadio appcenter router hot polish: user pass 6 precision finish' '应用商店 pass 6 precision finish 精修 CSS'
    verify_template_marker 'NRadio appcenter premium frontend finish: pass 7 optical depth and motion discipline' '应用商店 pass 7 premium CSS'
    verify_template_marker 'NRadio appcenter premium frontend finish: pass 8 matte restraint override' '应用商店 pass 8 premium CSS'
    verify_template_marker 'NRadio appcenter product card refinement pass 8' '应用商店卡片逻辑 pass 8 CSS'
    verify_template_marker 'NRadio appcenter premium matte optical token matrix' '应用商店 matte token matrix 层'
    verify_template_marker 'NRadio appcenter premium matte token consumers' '应用商店 matte token consumer 层'
    verify_template_marker 'NRadio appcenter premium matte lens bank' '应用商店 matte lens 层'
    verify_template_marker 'NRadio appcenter premium stability tone bank' '应用商店 stability tone 层'
    verify_template_marker 'NRadio appcenter premium stability consumers' '应用商店 stability consumer 层'
    verify_template_marker 'NRadio appcenter premium final depth bank' '应用商店 final depth 层'
    verify_template_marker 'NRadio appcenter premium final depth consumers' '应用商店 final depth consumer 层'
    verify_template_marker 'NRadio appcenter premium final seal bank' '应用商店 final seal 层'
    verify_template_marker 'NRadio appcenter premium final seal consumers' '应用商店最终样式规则'
    verify_template_marker 'NRadio appcenter premium visual finish' '应用商店页面样式'
    verify_template_marker 'NRadio appcenter card content logic finish' '应用商店卡片内容'
    verify_template_marker '<div class="app_meta_row"' '应用商店卡片状态徽标'
    verify_template_marker 'status_label: db.status_label' '应用商店卡片状态标签数据'
    verify_template_marker 'app_open_badge app_open_1' '应用商店后台状态徽标'
    verify_template_marker 'nr_app_default_icon' '应用商店默认图标'
    verify_template_marker 'var icon_fallback = ' '应用商店默认图标变量'
    verify_template_marker 'onerror="{{icon_fallback}}"' '应用商店图片错误处理'
    verify_template_marker 'des_class: des_class' '应用商店空描述隐藏'
    verify_template_marker 'function nr_appcenter_display_name' '应用商店显示名映射'
    verify_template_marker 'display_name: nr_appcenter_display_name(db.name)' '应用商店显示名数据'
    verify_template_marker '{{display_name}}' '应用商店卡片显示名挂载'
    verify_template_marker 'function nr_appcenter_display_version' '应用商店 OpenVPN 版本号显示映射'
    verify_template_marker 'display_version: nr_appcenter_display_version(db.name, db.version)' '应用商店 OpenVPN 版本号显示数据'
    verify_template_marker '{{display_version}}' '应用商店 OpenVPN 版本号挂载'
    verify_template_marker 'app_status_mem").text(mem_text)' '应用商店系统卡片内存显示'
    verify_template_marker 'app_status_swap").text(swap_text)' '应用商店 C2000MAX / C2000Ultra swap 显示'
    verify_template_marker 'app_status_swap_bar' '应用商店 C2000MAX / C2000Ultra swap 状态条'
    verify_template_marker 'build_app_status_panel_from_data' '应用商店右侧系统状态面板'
