patch_appcenter_card_polish_v3() {
    require_nradio_oem_appcenter

    mkdir -p "$WORKDIR"
    v3_css="$WORKDIR/appcenter-v3.css"
    v3_js="$WORKDIR/appcenter-v3.js"
    v3_lua="$WORKDIR/appcenter-v3-transform.lua"

    cat > "$v3_css" <<'EOF_APPCENTER_V3_CSS'
    /* NRadio appcenter v3: begin */
    .appcontainer{
        --nr-v3-bg: #07101b;
        --nr-v3-panel: #0f1d2b;
        --nr-v3-panel-2: #0f1d2d;
        --nr-v3-line: rgba(128,157,184,.16);
        --nr-v3-line-strong: rgba(70,190,214,.42);
        --nr-v3-text: #edf5fb;
        --nr-v3-text-soft: #c5d2de;
        --nr-v3-muted: #91a5b8;
        --nr-v3-cyan: #4cc6d8;
        --nr-v3-blue: #5f9eea;
        --nr-v3-green: #50c697;
        --nr-v3-amber: #e1ad64;
        --nr-v3-red: #df7d82;
        position: relative;
        display: grid;
        grid-template-columns: 116px minmax(0,1fr);
        grid-template-areas:
            "toolbar toolbar"
            "menu content"
            "status status";
        gap: 16px;
        align-items: start;
        width: 100%;
        min-width: 0;
        padding-bottom: 18px;
        box-sizing: border-box;
        color: var(--nr-v3-text);
    }
    .appcontainer *,
    .appcontainer *::before,
    .appcontainer *::after{
        box-sizing: border-box;
    }
    body[class*="AppCenterTitle"] .footer,
    .footer.footer-{
        position: static !important;
        margin-top: 14px !important;
    }
    #app_top_menu{
        display: flex;
        align-items: center;
        gap: 6px;
        min-height: 40px;
        margin: 0 0 12px;
        padding: 0 2px 9px;
        overflow-x: auto;
        border-bottom: 1px solid rgba(128,157,184,.16);
        scrollbar-width: thin;
    }
    #app_top_menu .top_menu{
        flex: 0 0 auto;
        margin: 0;
        padding: 8px 10px;
        border: 1px solid transparent;
        border-radius: 8px;
        color: var(--nr-v3-muted);
        font-size: 13px;
        line-height: 1.2;
        white-space: nowrap;
        -webkit-background-clip: border-box !important;
        background-clip: border-box !important;
        -webkit-text-fill-color: currentColor !important;
    }
    #app_top_menu .top_menu_active{
        border-color: rgba(76,198,216,.32);
        background: rgba(76,198,216,.09);
        color: #dffaff !important;
        -webkit-text-fill-color: #dffaff !important;
    }
    #app_top_menu .top_menu_inner{
        display: inline-flex;
        align-items: center;
        flex: 0 0 auto;
        overflow: hidden;
        border: 1px solid rgba(128,157,184,.13);
        border-radius: 8px;
        background: rgba(128,157,184,.035);
        transition: border-color .16s ease, background-color .16s ease;
    }
    #app_top_menu .top_menu_inner:hover{
        border-color: rgba(76,198,216,.26);
        background: rgba(76,198,216,.055);
    }
    #app_top_menu .top_menu_inner .top_menu{
        padding: 6px 7px 6px 9px;
        border: 0;
        border-radius: 0;
        background: transparent;
    }
    #app_top_menu .top_menu_inner_icon{
        top: 0;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        width: 28px;
        height: 28px;
        margin: 0 3px 0 -2px;
        padding: 0;
        border: 0;
        border-radius: 6px;
        outline: 0;
        appearance: none;
        background: transparent;
        color: var(--nr-v3-muted);
        -webkit-text-fill-color: currentColor !important;
        font-size: 0 !important;
        opacity: .72 !important;
        cursor: pointer;
        transition: color .16s ease, opacity .16s ease, background-color .16s ease;
    }
    #app_top_menu .top_menu_inner_icon::before{
        content: "×" !important;
        font-family: Arial, sans-serif !important;
        font-size: 17px !important;
        font-weight: 400 !important;
        line-height: 1 !important;
    }
    #app_top_menu .top_menu_inner:hover .top_menu_inner_icon{
        color: var(--nr-v3-cyan);
        background: rgba(76,198,216,.08);
        opacity: 1 !important;
    }
    .app_btn_box{
        grid-area: toolbar;
        display: grid;
        grid-template-columns: minmax(210px,1fr) minmax(180px,320px) auto;
        gap: 12px;
        align-items: center;
        width: 100%;
        min-width: 0;
        padding: 11px 12px;
        border: 1px solid var(--nr-v3-line);
        border-radius: 12px;
        background: #0c1825;
        box-shadow: none;
    }
    .app_btn_box .mem_track{
        width: auto;
        max-width: 420px;
        min-width: 0;
        margin: 0;
        gap: 7px;
        color: var(--nr-v3-text-soft);
    }
    .app_btn_box .mem_header{
        font-size: 13px;
        color: var(--nr-v3-text-soft);
    }
    .app_btn_box .mem_progress{
        height: 5px;
        margin: 0;
        background: rgba(3,8,14,.72);
        box-shadow: inset 0 0 0 1px rgba(128,157,184,.12);
    }
    .app_btn_box .mem_progress_inner{
        background: linear-gradient(90deg, #4c94d8, #4cc6d8);
        box-shadow: 0 0 10px rgba(76,198,216,.24);
    }
    .app_btn_box .nr-storage-track.nr-has-storage-expand{
        display: grid;
        grid-template-columns: repeat(2,minmax(0,1fr));
        gap: 12px;
        max-width: 520px;
    }
    .app_btn_box .nr-storage-row{
        display: flex;
        flex-direction: column;
        justify-content: center;
        gap: 7px;
        min-width: 0;
    }
    .app_btn_box .nr-storage-expand-row{
        display: none;
    }
    .app_btn_box .nr-storage-track.nr-has-storage-expand .nr-storage-expand-row{
        display: flex;
    }
    .app_btn_box .nr-storage-expand-row .mem_progress_inner{
        background: linear-gradient(90deg, #50c697, #4cc6d8);
        box-shadow: 0 0 10px rgba(80,198,151,.20);
    }
    .nr_app_search{
        position: relative;
        min-width: 0;
    }
    .nr_app_search::before{
        content: "⌕";
        position: absolute;
        left: 11px;
        top: 50%;
        z-index: 1;
        transform: translateY(-50%);
        color: var(--nr-v3-muted);
        font-size: 18px;
        pointer-events: none;
    }
    #nr_app_search_input{
        display: block;
        width: 100%;
        height: 38px;
        padding: 0 86px 0 34px;
        border: 1px solid var(--nr-v3-line);
        border-radius: 9px;
        outline: none;
        background: rgba(3,9,16,.58);
        color: var(--nr-v3-text);
        font-size: 14px;
    }
    #nr_app_search_input::placeholder{
        color: #93a7ba;
    }
    #nr_app_search_input:focus{
        border-color: var(--nr-v3-line-strong);
        box-shadow: 0 0 0 3px rgba(76,198,216,.09);
    }
    .nr_app_search_count{
        position: absolute;
        right: 11px;
        top: 50%;
        min-width: 34px;
        height: auto;
        padding: 0;
        transform: translateY(-50%);
        border: 0;
        background: transparent;
        color: var(--nr-v3-muted);
        font-size: 11px;
        font-weight: 650;
        line-height: 1;
        text-align: center;
        opacity: 1;
        pointer-events: none;
    }
    .nr_app_search_clear{
        position: absolute;
        right: 48px;
        top: 50%;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        width: 28px;
        height: 28px;
        padding: 0;
        transform: translateY(-50%) scale(.88);
        border: 0;
        border-radius: 6px;
        outline: 0;
        appearance: none;
        background: transparent;
        color: var(--nr-v3-muted);
        font-size: 16px;
        line-height: 1;
        opacity: 0;
        pointer-events: none;
        cursor: pointer;
        transition: transform .16s ease, opacity .16s ease, color .16s ease, background-color .16s ease;
    }
    .nr_app_search.nr_searching .nr_app_search_clear{
        transform: translateY(-50%) scale(1);
        opacity: .78;
        pointer-events: auto;
    }
    .nr_app_search_clear:hover{
        background: rgba(76,198,216,.10);
        color: #e6fbff;
        opacity: 1 !important;
    }
    .app_btn_group{
        display: flex;
        justify-content: flex-end;
        gap: 8px;
    }
    .app_btn_group .app_btn_class{
        min-height: 38px;
        padding: 0 14px;
        border: 1px solid rgba(76,198,216,.30);
        border-radius: 9px;
        background: rgba(76,198,216,.075);
        color: #cceff5;
        font-size: 13px;
        font-weight: 700;
        line-height: 36px;
        white-space: nowrap;
        cursor: pointer;
    }
    .app_btn_group .app_btn_class:hover{
        border-color: rgba(76,198,216,.52);
        background: rgba(76,198,216,.13);
        color: #f1fdff;
        -webkit-text-fill-color: currentColor;
    }
    .container_left{
        grid-area: menu;
        position: sticky;
        top: 12px;
        align-self: start;
        float: none !important;
        width: auto !important;
        height: auto !important;
        min-height: 0 !important;
        min-width: 0;
        margin: 0 !important;
        padding: 8px;
        border: 1px solid var(--nr-v3-line);
        border-radius: 12px;
        background: rgba(8,18,30,.86);
    }
    .container_left ul{
        margin: 0;
        padding: 0;
        list-style: none;
    }
    .container_left .app_menu{
        display: flex;
        align-items: center;
        min-height: 38px;
        margin: 0 0 6px;
        justify-content: space-between;
        gap: 7px;
        padding: 0 9px;
        border: 1px solid transparent;
        border-radius: 8px;
        color: var(--nr-v3-muted);
        font-size: 13px;
        line-height: 1.2;
        white-space: nowrap;
        -webkit-background-clip: border-box !important;
        background-clip: border-box !important;
        -webkit-text-fill-color: currentColor !important;
        cursor: pointer;
    }
    .container_left .app_menu:last-child{
        margin-bottom: 0;
    }
    .container_left .app_menu:hover{
        background: rgba(255,255,255,.025);
        color: var(--nr-v3-text-soft);
    }
    .container_left .app_menu.menu_active{
        border-color: rgba(76,198,216,.28);
        background: rgba(76,198,216,.10);
        color: #e5fbff !important;
        -webkit-text-fill-color: #e5fbff !important;
        box-shadow: inset 3px 0 0 var(--nr-v3-cyan);
    }
    .container_left .nr_menu_count{
        display: inline-flex;
        align-items: center;
        justify-content: center;
        min-width: 22px;
        height: 22px;
        padding: 0 5px;
        border-radius: 999px;
        background: rgba(128,157,184,.08);
        color: var(--nr-v3-muted);
        font-size: 11px;
        font-weight: 700;
        line-height: 22px;
        font-variant-numeric: tabular-nums;
    }
    .container_left .app_menu.menu_active .nr_menu_count{
        background: rgba(76,198,216,.11);
        color: #c8f6fb;
    }
    .container_left .mem_mobile{
        display: none;
    }
    .container_right{
        grid-area: content;
        display: grid;
        grid-template-columns: repeat(3,minmax(0,1fr));
        grid-auto-rows: 1fr;
        align-items: stretch;
        gap: 16px;
        float: none !important;
        width: auto !important;
        min-width: 0;
        margin: 0 !important;
        padding: 0 !important;
    }
    .container_right.hide{
        display: none !important;
    }
    .container_right .app_box{
        position: relative;
        display: grid;
        grid-template-columns: 52px minmax(0,1fr);
        grid-template-rows: minmax(110px,1fr) auto;
        column-gap: 12px;
        min-width: 0;
        min-height: 210px;
        width: 100% !important;
        max-width: none !important;
        height: auto !important;
        margin: 0 !important;
        float: none !important;
        padding: 16px;
        overflow: hidden;
        border: 1px solid var(--nr-v3-line);
        border-radius: 12px;
        background: var(--nr-v3-panel);
        box-shadow: 0 3px 10px rgba(0,0,0,.10);
        transition: border-color .16s ease, box-shadow .16s ease, background-color .16s ease;
    }
    .container_right .app_box:hover,
    .container_right .app_box:focus-within{
        transform: none;
        border-color: var(--nr-v3-line-strong);
        background: #132334;
        box-shadow: 0 5px 14px rgba(0,0,0,.14);
    }
    .container_right .app_icon{
        grid-column: 1;
        grid-row: 1;
        display: flex;
        align-items: flex-start;
        justify-content: center;
        float: none;
        width: auto;
        margin: 0;
    }
    .container_right .app_icon_img{
        display: block;
        width: 52px;
        height: 52px;
        padding: 3px;
        border: 1px solid rgba(128,157,184,.10);
        border-radius: 12px;
        background: rgba(128,157,184,.04);
        object-fit: contain;
        box-shadow: none;
        transition: border-color .16s ease;
    }
    .container_right .app_box:hover .app_icon_img,
    .container_right .app_box:focus-within .app_icon_img{
        transform: none;
        border-color: rgba(76,198,216,.34);
    }
    .container_right .app_info{
        grid-column: 2;
        grid-row: 1;
        float: none;
        width: auto;
        min-width: 0;
        margin: 0;
    }
    .container_right .app_title{
        display: grid;
        grid-template-columns: minmax(0,1fr) auto;
        gap: 5px 8px;
        align-items: start;
        align-content: start;
        min-height: 48px;
        min-width: 0;
    }
    .container_right .app_name{
        grid-column: 1;
        float: none;
        width: auto;
        height: auto;
        min-width: 0;
        overflow: hidden;
        color: var(--nr-v3-text);
        font-size: 17px;
        font-weight: 700;
        line-height: 1.4;
        text-overflow: ellipsis;
        white-space: nowrap;
    }
    .container_right .app_version{
        grid-column: 1;
        float: none;
        width: auto;
        height: auto;
        overflow: hidden;
        color: var(--nr-v3-muted);
        font-size: 12px;
        font-weight: 400;
        font-variant-numeric: tabular-nums;
        line-height: 1.4;
        text-overflow: ellipsis;
        white-space: nowrap;
    }
    .container_right .app_meta_row{
        grid-column: 2;
        grid-row: 1 / span 2;
        display: flex;
        flex-direction: column;
        align-items: flex-end;
        gap: 4px;
    }
    .container_right .app_state_badge,
    .container_right .app_open_badge{
        display: inline-flex;
        align-items: center;
        min-height: 21px;
        padding: 0 6px;
        border: 1px solid rgba(128,157,184,.14);
        border-radius: 6px;
        background: rgba(128,157,184,.07);
        color: var(--nr-v3-text-soft);
        font-size: 11px;
        font-weight: 500;
        line-height: 19px;
        white-space: nowrap;
    }
    .container_right .app_state_0{
        border-color: rgba(95,158,234,.30);
        background: rgba(95,158,234,.09);
        color: #bcd9fb;
    }
    .container_right .app_state_1,
    .container_right .app_open_badge{
        border-color: rgba(80,198,151,.30);
        background: rgba(80,198,151,.09);
        color: #b9efd8;
    }
    .container_right .app_state_2{
        border-color: rgba(225,173,100,.32);
        background: rgba(225,173,100,.09);
        color: #f3d5a5;
    }
    .container_right .app_des{
        float: none;
        width: 100%;
        height: 44px;
        margin: 12px 0 0;
        overflow: hidden;
        color: #b5c5d4;
        font-size: 13px;
        font-weight: 400;
        line-height: 22px;
        display: -webkit-box;
        -webkit-line-clamp: 2;
        -webkit-box-orient: vertical;
    }
    .container_right .app_action{
        grid-column: 1 / -1;
        grid-row: 2;
        float: none;
        width: 100%;
        align-self: end;
        margin: 14px 0 0;
        padding-top: 12px;
        border-top: 1px solid rgba(128,157,184,.10);
    }
    .container_right .action_list{
        display: flex;
        justify-content: flex-end;
        gap: 10px;
        float: none;
        margin: 0;
        padding: 0;
        list-style: none;
        align-items: center;
    }
    .container_right .action_list_li{
        display: inline-flex;
        align-items: center;
        justify-content: center;
        min-width: 72px;
        min-height: 38px;
        padding: 0 14px;
        border: 1px solid rgba(128,157,184,.24);
        border-radius: 8px;
        background: rgba(128,157,184,.055);
        color: var(--nr-v3-text-soft);
        font-size: 13px;
        font-weight: 600;
        line-height: 36px;
        cursor: pointer;
        -webkit-text-fill-color: currentColor;
        transition: background-color .16s ease, border-color .16s ease, color .16s ease;
    }
    .container_right .action_list_li:hover,
    .container_right .action_list_li:focus-visible{
        border-color: rgba(76,198,216,.42);
        background: rgba(76,198,216,.11);
        color: #e7fbff;
        outline: none;
    }
    .container_right .nr_action_install,
    .container_right .nr_action_open{
        border-color: var(--nr-v3-cyan);
        color: #06242e;
        background: var(--nr-v3-cyan);
    }
    .container_right .nr_action_update{
        border-color: rgba(225,173,100,.28);
        color: #eed0a0;
        background: rgba(225,173,100,.10);
    }
    .container_right .nr_action_uninstall{
        margin-right: auto;
        color: #bd929b;
        background: transparent;
        border-color: transparent;
    }
    .container_right .nr_action_open:hover,
    .container_right .nr_action_open:focus-visible,
    .container_right .nr_action_install:hover,
    .container_right .nr_action_install:focus-visible{
        border-color: #79e0ea;
        background: #79e0ea;
        color: #06242e;
    }
    .container_right .nr_action_uninstall:hover,
    .container_right .nr_action_uninstall:focus-visible{
        border-color: rgba(223,125,130,.28);
        background: rgba(223,125,130,.09);
        color: #f2b8c0;
    }
    .app_empty_state{
        grid-column: 1 / -1;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        min-height: 220px;
        padding: 28px;
        border: 1px dashed rgba(128,157,184,.25);
        border-radius: 13px;
        background: rgba(8,18,30,.52);
        color: var(--nr-v3-muted);
        text-align: center;
    }
    .app_empty_state strong{
        margin-bottom: 5px;
        color: var(--nr-v3-text-soft);
        font-size: 14px;
    }
    .nr_search_empty{
        grid-column: 1 / -1;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        min-height: 165px;
        padding: 24px;
        border: 1px dashed rgba(76,198,216,.25);
        border-radius: 12px;
        background: #0c1825;
        color: var(--nr-v3-muted);
        text-align: center;
    }
    .nr_search_empty::before{
        content: "⌕";
        margin-bottom: 7px;
        color: var(--nr-v3-cyan);
        font-size: 25px;
        line-height: 1;
        opacity: .68;
    }
    .nr_search_empty strong{
        color: var(--nr-v3-text-soft);
        font-size: 13px;
    }
    .nr_search_empty span{
        margin-top: 4px;
        font-size: 12px;
    }
    #app_status_mount{
        grid-area: status;
        position: static;
        min-width: 0;
    }
    .app_status_panel{
        display: grid;
        grid-template-columns: 112px 180px repeat(auto-fit,minmax(130px,1fr));
        gap: 8px;
        align-items: stretch;
        padding: 10px 12px;
        border: 1px solid var(--nr-v3-line);
        border-radius: 10px;
        background: #0c1825;
        box-shadow: none;
    }
    .app_status_head{
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        gap: 3px;
        margin: 0;
        padding: 0 5px;
    }
    .app_status_head span{
        color: var(--nr-v3-text);
        font-size: 13px;
        font-weight: 700;
    }
    .app_status_time{
        color: var(--nr-v3-muted);
        font-size: 11px;
        font-style: normal;
        font-variant-numeric: tabular-nums;
    }
    .app_status_grid{
        display: grid;
        grid-template-columns: repeat(3,1fr);
        gap: 4px;
        margin: 0;
    }
    .app_status_tile{
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        min-height: 42px;
        padding: 5px 3px;
        border: 0;
        border-radius: 7px;
        background: transparent;
    }
    .app_status_tile strong{
        color: #f4fbff;
        font-size: 18px;
        line-height: 1.1;
        font-variant-numeric: tabular-nums;
    }
    .app_status_tile span{
        margin-top: 2px;
        color: var(--nr-v3-muted);
        font-size: 11px;
    }
    .app_status_metric{
        display: flex;
        flex-direction: column;
        justify-content: center;
        margin: 0;
        padding: 6px 8px;
        border: 0;
        border-radius: 0;
        background: transparent;
        border-left: 1px solid rgba(128,157,184,.14);
    }
    .app_status_metric_row{
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 4px 8px;
        margin-bottom: 5px;
        flex-wrap: wrap;
    }
    .app_status_metric_row span{
        color: var(--nr-v3-muted);
        font-size: 12px;
    }
    .app_status_metric_row strong{
        max-width: 100%;
        overflow: hidden;
        color: var(--nr-v3-text-soft);
        font-size: 12px;
        font-weight: 700;
        text-overflow: ellipsis;
        white-space: nowrap;
        font-variant-numeric: tabular-nums;
    }
    .app_status_bar{
        height: 4px;
        overflow: hidden;
        border-radius: 999px;
        background: rgba(2,7,12,.72);
        box-shadow: inset 0 0 0 1px rgba(128,157,184,.10);
    }
    .app_status_bar span{
        display: block;
        width: 0;
        height: 100%;
        border-radius: inherit;
        transition: width .28s ease;
    }
    .app_status_temp_bar{ background: linear-gradient(90deg,#e1ad64,#df7d82); }
    .app_status_cpu_bar{ background: linear-gradient(90deg,#5f9eea,#4cc6d8); }
    .app_status_mem_bar{ background: linear-gradient(90deg,#50c697,#4cc6d8); }
    .app_status_swap_bar{ background: linear-gradient(90deg,#9b8de3,#5f9eea); }
    .app_status_toggle{
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        gap: 3px;
        width: 100%;
        padding: 0;
        border: 0;
        outline: 0;
        background: transparent;
        color: inherit;
        font: inherit;
        cursor: pointer;
    }
    .app_status_toggle_text{
        color: var(--nr-v3-cyan);
        font-size: 11px;
        font-weight: 700;
    }
    #app_status_mount.nr_status_collapsed .app_status_panel{
        display: flex;
        justify-content: flex-end;
        padding: 0;
        border: 0;
        background: transparent;
        box-shadow: none;
    }
    #app_status_mount.nr_status_collapsed{
        margin-top: -12px;
    }
    #app_status_mount.nr_status_collapsed .app_status_grid,
    #app_status_mount.nr_status_collapsed .app_status_metric{
        display: none !important;
    }
    #app_status_mount.nr_status_collapsed .app_status_head{
        padding: 0;
    }
    #app_status_mount.nr_status_collapsed .app_status_toggle{
        flex-direction: row;
        width: auto;
        padding: 7px 12px;
        border: 1px solid rgba(76,198,216,.23);
        border-radius: 8px;
        background: #0f1d2b;
        box-shadow: none;
    }
    #app_status_mount.nr_status_collapsed .app_status_toggle::before{
        content: "";
        width: 6px;
        height: 6px;
        border-radius: 50%;
        background: var(--nr-v3-green);
        box-shadow: 0 0 8px rgba(80,198,151,.48);
    }
    #app_status_mount.nr_status_collapsed .app_status_toggle:hover{
        border-color: rgba(76,198,216,.46);
        background: #132334;
    }
    #app_top_menu .top_menu[role="button"]:focus-visible,
    #app_top_menu .top_menu_inner_icon:focus-visible,
    .nr_app_search_clear:focus-visible,
    .app_btn_group .app_btn_class:focus-visible,
    .container_left .app_menu:focus-visible,
    .container_right .action_list_li:focus-visible,
    .app_status_toggle:focus-visible{
        outline: 2px solid rgba(76,198,216,.72) !important;
        outline-offset: 2px;
        box-shadow: 0 0 0 4px rgba(76,198,216,.10);
    }
    .nr_app_filtered{
        display: none !important;
    }
    .bootstrap-dialog-message #scan_loading.nr_dialog_loading{
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        min-height: 128px;
        padding: 18px;
        color: #bdcad7;
        text-align: center;
    }
    .bootstrap-dialog-message .nr_dialog_spinner{
        width: 30px;
        height: 30px;
        margin-bottom: 12px;
        border: 3px solid rgba(128,157,184,.20);
        border-top-color: #4cc6d8;
        border-radius: 50%;
        box-shadow: 0 0 16px rgba(76,198,216,.12);
        animation: nr-dialog-spin .72s linear infinite;
    }
    .bootstrap-dialog-message .nr_dialog_loading strong{
        color: #edf5fb;
        font-size: 15px;
        line-height: 1.4;
    }
    .bootstrap-dialog-message .nr_dialog_loading small{
        margin-top: 5px;
        color: #9aaec0;
        font-size: 13px;
        line-height: 1.5;
    }
    .bootstrap-dialog-message .error_box{
        display: flex !important;
        align-items: flex-start;
        gap: 8px;
        width: 100% !important;
        margin: 0 0 8px;
        padding: 10px 12px;
        border: 1px solid rgba(223,125,130,.20);
        border-radius: 9px;
        background: rgba(223,125,130,.055);
        color: #bdcad7;
        line-height: 1.55;
        overflow-wrap: anywhere;
    }
    .bootstrap-dialog-message .error_box + br{
        display: none;
    }
    .bootstrap-dialog-message .error_detail_title{
        flex: 0 0 auto;
        float: none !important;
        color: #df9da1;
        font-weight: 700;
    }
    .bootstrap-dialog-message .error_detail_content{
        min-width: 0;
        float: none !important;
        white-space: pre-wrap;
        word-break: break-word;
    }
    .modal.bootstrap-dialog .modal-content{
        border: 1px solid rgba(128,157,184,.25);
        border-radius: 14px;
        background: #0d1a29;
        color: #edf5fb;
        box-shadow: 0 16px 44px rgba(0,0,0,.32);
    }
    .modal.bootstrap-dialog .modal-header{
        padding: 12px 16px;
        border-bottom: 1px solid rgba(128,157,184,.16);
        border-radius: 14px 14px 0 0;
        background: #112235;
    }
    .modal.bootstrap-dialog .bootstrap-dialog-title{
        color: #edf5fb;
        font-size: 15px;
        line-height: 32px;
    }
    .modal.bootstrap-dialog .modal-body{
        color: #c5d2de;
        background: #0d1a29;
        border-radius: 0 0 14px 14px;
        font-size: 14px;
    }
    .modal.bootstrap-dialog .modal-footer{
        padding: 12px 16px;
        border-top: 1px solid rgba(128,157,184,.16);
        border-radius: 0 0 14px 14px;
        background: #0d1a29;
    }
    .modal.bootstrap-dialog .bootstrap-dialog-close-button .close{
        display: inline-flex;
        align-items: center;
        justify-content: center;
        width: 32px;
        height: 32px;
        border-radius: 8px;
        color: #c5d2de;
        text-shadow: none;
        opacity: 1;
    }
    .modal.bootstrap-dialog .bootstrap-dialog-close-button .close:hover,
    .modal.bootstrap-dialog .bootstrap-dialog-close-button .close:focus-visible{
        background: rgba(76,198,216,.12);
        color: #f1fdff;
        outline: 2px solid #4cc6d8;
        outline-offset: 2px;
    }
    @keyframes nr-dialog-spin{
        to{ transform: rotate(360deg); }
    }
    @media (max-width: 1180px){
        .container_right{
            grid-template-columns: repeat(2,minmax(0,1fr));
        }
        .appcontainer{
            grid-template-columns: 110px minmax(0,1fr);
            grid-template-areas:
                "toolbar toolbar"
                "menu content"
                "status status";
        }
    }
    @media (max-width: 860px){
        .app_btn_box{
            grid-template-columns: 1fr auto;
        }
        .nr_app_search{
            grid-column: 1 / -1;
            grid-row: 2;
        }
        .container_right{
            grid-template-columns: 1fr;
        }
        .app_status_panel{
            grid-template-columns: 1fr 1fr;
        }
        .app_status_head,
        .app_status_grid{
            grid-column: span 1;
        }
    }
    @media (max-width: 680px){
        #nr_app_search_input{
            height: 42px;
            font-size: 16px;
        }
        .app_btn_group .app_btn_class,
        .container_left .app_menu{
            min-height: 42px;
        }
        .app_btn_group .app_btn_class{
            line-height: 40px;
        }
        .container_right .action_list_li{
            min-height: 44px;
            padding: 0 14px;
            font-size: 13px;
            line-height: 42px;
        }
        .app_status_metric{
            border-left: 0;
            padding: 8px;
        }
        #app_top_menu .top_menu_inner_icon,
        .modal.bootstrap-dialog .bootstrap-dialog-close-button .close{
            width: 40px;
            height: 40px;
        }
        .modal.bootstrap-dialog .bootstrap-dialog-title{
            line-height: 40px;
        }
        .appcontainer{
            grid-template-columns: 1fr;
            grid-template-areas:
                "toolbar"
                "menu"
                "content"
                "status";
            gap: 11px;
        }
        .app_btn_box{
            grid-template-columns: 1fr;
            padding: 12px;
        }
        .app_btn_box .mem_track{
            display: flex;
            max-width: none;
        }
        .app_btn_box .nr-storage-track.nr-has-storage-expand{
            display: grid;
            max-width: none;
        }
        .nr_app_search{
            grid-column: auto;
            grid-row: auto;
        }
        .app_btn_group{
            justify-content: stretch;
        }
        .app_btn_group .app_btn_class{
            flex: 1 1 0;
            padding: 0 8px;
            text-align: center;
        }
        .container_left{
            position: static;
            padding: 6px;
        }
        .container_left ul{
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 6px;
        }
        .container_left .app_menu{
            justify-content: center;
            margin: 0;
        }
        .container_left .app_menu.menu_active{
            box-shadow: inset 0 -2px 0 var(--nr-v3-cyan);
        }
        .app_status_panel{
            grid-template-columns: 1fr 1fr;
            padding: 11px;
        }
        .app_status_head,
        .app_status_grid{
            grid-column: 1 / -1;
        }
    }
    @media (max-width: 430px){
        .app_btn_box .nr-storage-track.nr-has-storage-expand{
            grid-template-columns: 1fr;
            gap: 9px;
        }
        .app_btn_box .nr-storage-expand-row{
            padding-top: 8px;
            border-top: 1px solid rgba(128,157,184,.13);
        }
        .container_right .app_box{
            grid-template-columns: 50px minmax(0,1fr);
            min-height: 140px;
            padding: 12px;
        }
        .container_right .app_icon_img{
            width: 46px;
            height: 46px;
            border-radius: 11px;
        }
        .container_right .app_name{
            font-size: 15px;
        }
        .container_right .app_meta_row{
            grid-column: 1;
            grid-row: 3;
            flex-direction: row;
            flex-wrap: wrap;
            align-items: center;
            gap: 5px;
            margin-top: 3px;
        }
        .container_right .app_title{
            grid-template-columns: 1fr;
        }
        .container_right .action_list_li{
            flex: 1 1 0;
            min-width: 0;
        }
        .app_status_panel{
            grid-template-columns: 1fr;
        }
        .app_status_head,
        .app_status_grid{
            grid-column: auto;
        }
    }
    @media (prefers-reduced-motion: reduce){
        .appcontainer *,
        .appcontainer *::before,
        .appcontainer *::after{
            scroll-behavior: auto !important;
            transition-duration: .01ms !important;
            animation-duration: .01ms !important;
        }
    }
    /* NRadio appcenter v3: end */
EOF_APPCENTER_V3_CSS

    cat > "$v3_js" <<'EOF_APPCENTER_V3_JS'
    function nr_appcenter_display_name(name){
        var key = (name || "").toLowerCase();
        if(key == "luci-app-openclash" || key == "openclash") return "哈基米";
        if(key == "luci-app-adguardhome") return "AdGuardHome";
        if(key == "luci-app-ddns-go") return "DDNS-GO";
        return name || "未命名应用";
    }

    function nr_appcenter_display_version(name, version){
        var raw = version || "";
        var key = (name || "").toLowerCase();
        var match = raw.match(/^(git-[0-9]+[.][0-9]+[.][0-9]+)-[0-9a-f]+$/i);
        if(key.indexOf("openvpn") >= 0 && match) return match[1];
        return raw;
    }

    function nr_appcenter_desc_fallback(name){
        var key = (name || "").toLowerCase();
        if(key.indexOf("openclash") >= 0) return "代理规则、节点与网络分流管理";
        if(key.indexOf("adguard") >= 0) return "DNS 广告过滤与查询统计";
        if(key.indexOf("openvpn") >= 0) return "VPN 隧道连接与远程访问";
        if(key.indexOf("zerotier") >= 0) return "异地组网与虚拟局域网";
        if(key.indexOf("ddns") >= 0) return "动态 DNS 解析与公网地址同步";
        if(key.indexOf("docker") >= 0) return "容器服务与应用运行环境";
        return "应用功能与运行入口";
    }

    function nr_appcenter_empty_state(title){
        return '<div class="app_empty_state"><strong>'+title+'</strong><span>当前没有可显示的应用</span></div>';
    }

    function nr_appcenter_search_empty(){
        return '<div class="nr_search_empty" role="status"><strong>没有找到匹配应用</strong><span>换个名称、版本或功能关键词试试</span></div>';
    }

    var NR_APP_STATUS_LAST = null;
    var NR_APP_STATUS_BUSY = false;
    var NR_APP_STATUS_TIMER = null;
    var NR_APP_STATUS_INTERVAL = 5000;
    var NR_APP_STATUS_EXPANDED = false;
    var NR_APP_STATUS_AUTO_EXPANDED = false;

    function nr_format_kib(kib){
        var mb = Number(kib || 0) / 1024;
        return mb >= 1024 ? (mb / 1024).toFixed(1) + " G" : mb.toFixed(0) + " M";
    }

    function nr_set_status_width(selector, value){
        var percent = Math.max(0, Math.min(100, Number(value || 0)));
        $(selector).css("width", percent.toFixed(1) + "%");
    }

    function nr_build_status_panel(data){
        var installed = 0, opened = 0, all = 0;
        if(data && data.result && data.result.applist){
            $.each(data.result.applist, function(index, db){
                all++;
                if(db.open == 1) opened++;
                if(db.status == APP_STATUS_APP_INSTALLED || db.status == APP_STATUS_APP_UPDATEED) installed++;
            });
        }
        return ''+
        '<aside class="app_status_panel">'+
        '  <div class="app_status_head"><button type="button" class="app_status_toggle" aria-expanded="false"><span>系统状态</span><em class="app_status_time">等待刷新</em><b class="app_status_toggle_text">展开</b></button></div>'+
        '  <div class="app_status_grid">'+
        '    <div class="app_status_tile"><strong>'+installed+'</strong><span>已安装</span></div>'+
        '    <div class="app_status_tile"><strong>'+opened+'</strong><span>后台</span></div>'+
        '    <div class="app_status_tile"><strong>'+all+'</strong><span>全部</span></div>'+
        '  </div>'+
        '  <div class="app_status_metric"><div class="app_status_metric_row"><span>CPU 温度</span><strong class="app_status_temp">--</strong></div><div class="app_status_bar"><span class="app_status_temp_bar"></span></div></div>'+
        '  <div class="app_status_metric"><div class="app_status_metric_row"><span>CPU 使用率</span><strong class="app_status_cpu">采样中</strong></div><div class="app_status_bar"><span class="app_status_cpu_bar"></span></div></div>'+
        '  <div class="app_status_metric"><div class="app_status_metric_row"><span>内存占用</span><strong class="app_status_mem">--</strong></div><div class="app_status_bar"><span class="app_status_mem_bar"></span></div></div>'+
        '  <div class="app_status_metric app_status_swap_metric" style="display:none"><div class="app_status_metric_row"><span>Swap 虚拟内存</span><strong class="app_status_swap">--</strong></div><div class="app_status_bar"><span class="app_status_swap_bar"></span></div></div>'+
        '</aside>';
    }

    function nr_sync_status_panel_state(){
        var mount = $("#app_status_mount");
        mount.toggleClass("nr_status_collapsed", !NR_APP_STATUS_EXPANDED);
        mount.find(".app_status_toggle").attr("aria-expanded", NR_APP_STATUS_EXPANDED ? "true" : "false");
        mount.find(".app_status_toggle_text").text(NR_APP_STATUS_EXPANDED ? "收起" : "展开");
    }

    function nr_render_status_panel(data){
        if(!$("#app_status_mount").length) $(".container_left").before('<div id="app_status_mount"></div>');
        $("#app_status_mount").html(nr_build_status_panel(data));
        nr_sync_status_panel_state();
        if(NR_APP_STATUS_LAST) nr_update_status_panel(NR_APP_STATUS_LAST);
    }

    function nr_update_status_panel(data){
        if(!data) return;
        NR_APP_STATUS_LAST = data;
        var now = new Date();
        var temp = Number(data.cpu_temp || 0);
        var cpu = data.cpu_percent;
        var memPercent = Number(data.mem_percent || 0);
        var memText = nr_format_kib(data.mem_used) + " / " + nr_format_kib(data.mem_total);
        $(".app_status_time").text(("0"+now.getHours()).slice(-2)+":"+("0"+now.getMinutes()).slice(-2)+":"+("0"+now.getSeconds()).slice(-2));
        $(".app_status_temp").text(temp > 0 ? temp.toFixed(1)+" ℃" : "--");
        nr_set_status_width(".app_status_temp_bar", temp > 0 ? temp : 0);
        if(cpu === null || typeof cpu === "undefined" || cpu === ""){
            $(".app_status_cpu").text("采样中");
            nr_set_status_width(".app_status_cpu_bar", 0);
        } else {
            cpu = Number(cpu || 0);
            $(".app_status_cpu").text(cpu.toFixed(1)+"%");
            nr_set_status_width(".app_status_cpu_bar", cpu);
        }
        $(".app_status_mem").text(memText).attr("title", memText+" · "+memPercent.toFixed(1)+"%");
        nr_set_status_width(".app_status_mem_bar", memPercent);
        var supportsSwap = data.supports_swap === true || data.supports_swap == 1 || data.is_c2000max === true || data.is_c2000max == 1 || data.model_name == "NRadio_C2000MAX" || data.model == "NRadio_C2000MAX" || data.model_name == "NRadio_C2000Ultra" || data.model == "NRadio_C2000Ultra";
        if(supportsSwap){
            if(!NR_APP_STATUS_AUTO_EXPANDED){
                NR_APP_STATUS_AUTO_EXPANDED = true;
                NR_APP_STATUS_EXPANDED = true;
                nr_sync_status_panel_state();
            }
            var swapTotal = Number(data.swap_total || 0);
            var swapUsed = Number(data.swap_used || 0);
            var swapPercent = Number(data.swap_percent || 0);
            $(".app_status_swap_metric").show();
            $(".app_status_swap").text(swapTotal > 0 ? nr_format_kib(swapUsed)+" / "+nr_format_kib(swapTotal) : "未启用");
            nr_set_status_width(".app_status_swap_bar", swapPercent);
        } else {
            $(".app_status_swap_metric").hide();
        }
    }

    function nr_get_system_status(){
        if(document.hidden || NR_APP_STATUS_BUSY) return;
        NR_APP_STATUS_BUSY = true;
        var data={token:'<%=token%>'};
        (new XHR()).post('<%=controller%>nradioadv/system/appcenter/sys_status', data, function(xhr){
            NR_APP_STATUS_BUSY = false;
            if(!xhr) return;
            var contentType = xhr.getResponseHeader("Content-Type") || "";
            if(contentType.indexOf("application/json") !== 0) return;
            try{
                var response = JSON.parse(xhr.responseText || '{}');
                if(response && response.result) nr_update_status_panel(response.result);
            } catch(e) {}
        });
    }

    function nr_start_status_polling(){
        nr_get_system_status();
        if(NR_APP_STATUS_TIMER) window.clearInterval(NR_APP_STATUS_TIMER);
        NR_APP_STATUS_TIMER = window.setInterval(nr_get_system_status, NR_APP_STATUS_INTERVAL);
    }

    function nr_update_app_count(){
        var active = $(".container_right:not(.hide)");
        var total = active.find(".app_box").length;
        var visible = active.find(".app_box:not(.nr_app_filtered)").length;
        $("#nr_app_search_count").text(visible+" / "+total).attr("title", "当前显示 "+visible+" 个，共 "+total+" 个应用");
        return {total:total, visible:visible};
    }

    function nr_update_menu_counts(data){
        var installed = 0;
        var all = 0;
        if(data && data.result && data.result.applist){
            $.each(data.result.applist, function(index, db){
                all++;
                if(db.status == APP_STATUS_APP_INSTALLED || db.status == APP_STATUS_APP_UPDATEED) installed++;
            });
        }
        var menus = $(".container_left .app_menu");
        menus.find(".nr_menu_count").remove();
        menus.eq(0).append('<span class="nr_menu_count">'+installed+'</span>');
        menus.eq(1).append('<span class="nr_menu_count">'+all+'</span>');
    }

    function nr_apply_app_search(){
        var query = $.trim($("#nr_app_search_input").val() || "").toLowerCase();
        var active = $(".container_right:not(.hide)");
        active.find(".nr_search_empty").remove();
        active.find(".app_box").each(function(){
            var text = $(this).text().toLowerCase();
            $(this).toggleClass("nr_app_filtered", query.length > 0 && text.indexOf(query) < 0);
        });
        $(".nr_app_search").toggleClass("nr_searching", query.length > 0);
        $("#nr_app_search_clear").attr("aria-hidden", query.length > 0 ? "false" : "true").attr("tabindex", query.length > 0 ? "0" : "-1");
        var count = nr_update_app_count();
        if(query.length > 0 && count.total > 0 && count.visible === 0) active.append(nr_appcenter_search_empty());
    }

    function show_app_data(data){
        data = data || {result:{applist:[]}};
        if(!data.result) data.result = {applist:[]};
        if(!data.result.applist) data.result.applist = [];
        var htm = "";
        var htm_installed = "";
        var top_menu_ht = "<span class='top_menu top_menu_active'><%:AppCenterTitle%></span>";
        $.each(data.result.applist, function(index, db){
            var optht = '';
            var icon_name = db.icon && db.icon.length ? db.icon : "app_default.png";
            var open_route = db.luci_module_route || "";
            var display_name = nr_appcenter_display_name(db.name);
            var display_version = nr_appcenter_display_version(db.name, db.version);
            var des_info = db.des && db.des.length ? db.des : nr_appcenter_desc_fallback(db.name);
            var status_label = "未知";
            var open_badge = "";
            var icon_fallback = "this.onerror=null;this.src='/luci-static/nradio/images/icon/app_default.png';";
            var open_ht = '<li class="action_list_li nr_action_open" role="button" tabindex="0" onclick="app_action(\''+db.name+'\',\'open\',\''+index+'\',\''+open_route+'\')"><%:AppOpen%></li>';
            if(db.open == 1){
                top_menu_ht += '<div class="top_menu_inner"><span class="top_menu" role="button" tabindex="0" data-index="'+index+'" onclick="callback(\''+index+'\',\''+open_route+'\')">'+display_name+'</span><button type="button" aria-label="关闭应用" title="关闭应用" onclick="app_action(\''+db.name+'\',\'close\')" class="top_menu_inner_icon">×</button></div>';
                open_ht = '<li class="action_list_li nr_action_open" role="button" tabindex="0" onclick="callback(\''+index+'\',\''+open_route+'\')"><%:AppOpen%></li>';
                open_badge = '<span class="app_open_badge">后台</span>';
            }
            if(db.has_luci != 1) open_ht = '';
            if(db.status == APP_STATUS_APP_NEW){
                status_label = "未安装";
                optht = '<li class="action_list_li nr_action_install" role="button" tabindex="0" onclick="app_action(\''+db.name+'\',\'install\')"><%:AppInstall%></li>';
            } else if(db.status == APP_STATUS_APP_INSTALLED){
                status_label = "已安装";
                optht = '<li class="action_list_li nr_action_uninstall" role="button" tabindex="0" onclick="app_action(\''+db.name+'\',\'uninstall\')"><%:AppUninstall%></li>'+open_ht;
            } else if(db.status == APP_STATUS_APP_UPDATEED){
                status_label = "可更新";
                optht = '<li class="action_list_li nr_action_update" role="button" tabindex="0" onclick="app_action(\''+db.name+'\',\'update\')"><%:AppUpdate%></li><li class="action_list_li nr_action_uninstall" role="button" tabindex="0" onclick="app_action(\''+db.name+'\',\'uninstall\')"><%:AppUninstall%></li>'+open_ht;
            }
            var row = APPTableRow.compose({
                name: db.name,
                display_name: display_name,
                version: db.version,
                display_version: display_version,
                des: des_info,
                icon: icon_name,
                icon_fallback: icon_fallback,
                opt: optht,
                index: index,
                status: db.status,
                status_label: status_label,
                open_badge: open_badge
            });
            if(db.status == APP_STATUS_APP_INSTALLED || db.status == APP_STATUS_APP_UPDATEED) htm_installed += row;
            htm += row;
        });
        if(!htm_installed) htm_installed = nr_appcenter_empty_state("暂无已安装应用");
        if(!htm) htm = nr_appcenter_empty_state("暂无应用");
        $("#app_top_menu").html(top_menu_ht);
        $(".app_all").html(htm);
        $(".app_installed").html(htm_installed);
        nr_update_menu_counts(data);
        $(".container_left .app_menu, .app_btn_group .app_btn_class").attr("role", "button").attr("tabindex", "0");
        nr_render_status_panel(data);
        nr_apply_app_search();
    }

    $(document).on("input", "#nr_app_search_input", nr_apply_app_search);
    $(document).on("click", "#nr_app_search_clear", function(){
        $("#nr_app_search_input").val("").focus();
        nr_apply_app_search();
    });
    $(document).on("click", ".app_menu", function(){ window.setTimeout(nr_apply_app_search, 0); });
    $(document).on("click", ".app_status_toggle", function(){
        NR_APP_STATUS_EXPANDED = !NR_APP_STATUS_EXPANDED;
        nr_sync_status_panel_state();
    });
    $(document).on("keydown", "#nr_app_search_input", function(event){
        if(event.key === "Escape"){
            $(this).val("");
            nr_apply_app_search();
            event.preventDefault();
        }
    });
    $(document).on("keydown", ".action_list_li, .app_menu, .app_btn_class, #app_top_menu .top_menu[role='button']", function(event){
        if(event.key === "Enter" || event.key === " "){
            event.preventDefault();
            $(this).trigger("click");
        }
    });
    document.addEventListener("visibilitychange", function(){ if(!document.hidden) nr_get_system_status(); });

EOF_APPCENTER_V3_JS

    cat > "$v3_lua" <<'EOF_APPCENTER_V3_LUA'
local tpl_path, css_path, js_path = arg[1], arg[2], arg[3]
assert(tpl_path and css_path and js_path, "missing transform arguments")

local function read_all(path)
    local file = assert(io.open(path, "rb"), "open failed: " .. path)
    local data = file:read("*a")
    file:close()
    return data
end

local html = read_all(tpl_path)
local css = read_all(css_path)
local renderer = read_all(js_path)

local function strip_style_from(marker)
    local start_pos = html:find(marker, 1, true)
    if not start_pos then return end
    local end_pos = assert(html:find("</style>", start_pos, true), "style close not found for " .. marker)
    html = html:sub(1, start_pos - 1) .. html:sub(end_pos)
end

strip_style_from("    /* NRadio appcenter v3: begin */")
strip_style_from("    /* NRadio appcenter card polish: visual-only layer */")

html = html:gsub("[ \t]*<div id=\"app_status_mount\"></div>\r\n", "")
html = html:gsub("[ \t]*<div id=\"app_status_mount\"></div>\n", "")
html = html:gsub("[ \t]*<div class=\"nr_app_search\">.-</div>\r\n", "")
html = html:gsub("[ \t]*<div class=\"nr_app_search\">.-</div>\n", "")

local style_close = assert(html:find("</style>", 1, true), "style close not found")
html = html:sub(1, style_close - 1) .. css .. "\n" .. html:sub(style_close)

local toolbar_anchor = '        <div class="app_btn_group">'
local toolbar_pos = assert(html:find(toolbar_anchor, 1, true), "toolbar anchor not found")
local storage_anchor = '        <div class="mem_track'
local storage_pos = assert(html:find(storage_anchor, 1, true), "storage anchor not found")
local storage_markup = [[        <div class="mem_track nr-storage-track">
            <div class="nr-storage-row nr-storage-system-row">
                <div class="mem_header">
                    <span>系统空间</span>
                    <span id="memory_detail">9.9 G / 99.9 G</span>
                </div>
                <div class="mem_progress">
                    <div class="mem_progress_inner" id="memory_progress_inner"></div>
                </div>
            </div>
            <div class="nr-storage-row nr-storage-expand-row" id="storage_expand_memory_row">
                <div class="mem_header">
                    <span>存储扩展</span>
                    <span id="storage_expand_memory_detail">0.0 G / 0.0 G</span>
                </div>
                <div class="mem_progress">
                    <div class="mem_progress_inner" id="storage_expand_memory_progress_inner"></div>
                </div>
            </div>
        </div>
]]
html = html:sub(1, storage_pos - 1) .. storage_markup .. html:sub(toolbar_pos)
toolbar_pos = assert(html:find(toolbar_anchor, storage_pos, true), "toolbar anchor not found after storage rebuild")
local search_markup = '        <div class="nr_app_search"><input id="nr_app_search_input" type="search" autocomplete="off" aria-label="搜索应用" placeholder="搜索应用、版本或功能"><button id="nr_app_search_clear" class="nr_app_search_clear" type="button" aria-label="清除搜索" aria-hidden="true" tabindex="-1" title="清除搜索">×</button><span id="nr_app_search_count" class="nr_app_search_count" aria-live="polite">0 / 0</span></div>\n'
html = html:sub(1, toolbar_pos - 1) .. search_markup .. html:sub(toolbar_pos)

local menu_anchor = '    <div class="container_left">'
local menu_pos = assert(html:find(menu_anchor, 1, true), "menu anchor not found")
html = html:sub(1, menu_pos - 1) .. '    <div id="app_status_mount"></div>\n' .. html:sub(menu_pos)

local row_start = assert(html:find("    var APPTableRow = ''+", 1, true), "APPTableRow start not found")
local error_start = assert(html:find("    var APPErrorRow = ''+", row_start, true), "APPErrorRow start not found")
local row = [[    var APPTableRow = ''+
    '<div class="app_box app_item{{index}}" data-status="{{status}}">'+
        '    <div class="app_icon"><img class="app_icon_img" src="/luci-static/nradio/images/icon/{{icon}}" alt="{{display_name}}" onerror="{{icon_fallback}}"></div>'+
        '    <div class="app_info">'+
        '        <div class="app_title">'+
        '            <div class="app_name" title="{{display_name}}">{{display_name}}</div>'+
        '            <div class="app_version" title="{{version}}">{{display_version}}</div>'+
        '            <div class="app_meta_row"><span class="app_state_badge app_state_{{status}}">{{status_label}}</span>{{open_badge}}</div>'+
        '        </div>'+
        '        <div class="app_des" title="{{des}}">{{des}}</div>'+
        '    </div>'+
        '    <div class="app_action"><ul class="action_list">{{opt}}</ul></div>'+
        '</div>';

]]
html = html:sub(1, row_start - 1) .. row .. html:sub(error_start)

local show_start = assert(html:find("    function show_app_data(data){", 1, true), "show_app_data start not found")
local loading_start = assert(html:find("    var loading_htm = ", show_start, true), "loading_htm start not found")
html = html:sub(1, show_start - 1) .. renderer .. html:sub(loading_start)

loading_start = assert(html:find("    var loading_htm = ", 1, true), "loading_htm start not found after renderer")
local loading_end = assert(html:find("\n", loading_start, true), "loading_htm end not found")
local loading_markup = [[    var loading_htm = '<div id="scan_loading" class="nr_dialog_loading" role="status" aria-live="polite"><span class="nr_dialog_spinner" aria-hidden="true"></span><strong>正在处理</strong><small>请稍候，不要关闭页面</small></div>';]]
html = html:sub(1, loading_start - 1) .. loading_markup .. html:sub(loading_end)

local ready_count
html, ready_count = html:gsub("        get_memory%(%)%;", "        get_memory();\n        nr_start_status_polling();", 1)
assert(ready_count == 1, "document ready hook not found")

local tmp_path = tpl_path .. ".nradio-v3.tmp"
local output = assert(io.open(tmp_path, "wb"), "create failed: " .. tmp_path)
output:write(html)
output:close()
assert(os.rename(tmp_path, tpl_path), "atomic template replace failed")
EOF_APPCENTER_V3_LUA

    lua "$v3_lua" "$TPL" "$v3_css" "$v3_js" || die "应用商店 V3 模板重构失败"
    chmod 644 "$TPL" 2>/dev/null || true

    grep -Fq 'NRadio appcenter v3: begin' "$TPL" 2>/dev/null || die "应用商店 V3 CSS 校验失败"
    grep -Fq 'id="nr_app_search_input"' "$TPL" 2>/dev/null || die "应用商店 V3 搜索框校验失败"
    grep -Fq 'function nr_start_status_polling()' "$TPL" 2>/dev/null || die "应用商店 V3 状态刷新校验失败"
    grep -Fq 'NR_APP_STATUS_INTERVAL = 5000' "$TPL" 2>/dev/null || die "应用商店 V3 采样间隔校验失败"
    grep -Fq 'NR_APP_STATUS_AUTO_EXPANDED = true' "$TPL" 2>/dev/null || die "应用商店 V3 C2000MAX / C2000Ultra 状态自动展开校验失败"
    grep -Fq '<span>Swap 虚拟内存</span>' "$TPL" 2>/dev/null || die "应用商店 V3 C2000MAX / C2000Ultra Swap 标签校验失败"
    grep -Fq 'app_state_badge app_state_{{status}}' "$TPL" 2>/dev/null || die "应用商店 V3 状态徽标校验失败"
    grep -Fq 'function nr_apply_app_search()' "$TPL" 2>/dev/null || die "应用商店 V3 搜索逻辑校验失败"
    grep -Fq 'id="nr_app_search_clear"' "$TPL" 2>/dev/null || die "应用商店 V3 搜索清除按钮校验失败"
    grep -Fq 'class="nr_search_empty"' "$TPL" 2>/dev/null || die "应用商店 V3 搜索空状态校验失败"
    grep -Fq 'class="top_menu_inner_icon">×</button>' "$TPL" 2>/dev/null || die "应用商店 V3 顶部关闭按钮校验失败"
    grep -Fq 'class="mem_track nr-storage-track"' "$TPL" 2>/dev/null || die "应用商店 V3 双空间容器校验失败"
    grep -Fq 'id="storage_expand_memory_row"' "$TPL" 2>/dev/null || die "应用商店 V3 存储扩展条校验失败"
}

lightweight_appcenter_model_supported() {
    case "$(detect_current_nradio_model_quiet 2>/dev/null || true)" in
        NRadio_C2000Pro|NRadio_AK68-798) return 0 ;;
    esac
    return 1
}

install_lightweight_appcenter() {
    lightweight_appcenter_model_supported || die "轻量应用商店当前仅支持 C2000Pro / AK68-798"
    if is_current_model_ak798; then
        ensure_ak798_compat_appcenter
        return 0
    fi
    if is_c2000pro_appcenter_environment; then
        log_stage 1 5 "检查 C2000Pro 兼容应用商店环境"
        ensure_c2000pro_compat_appcenter
        log "说明: 轻量商店管理已登记插件，不提供原厂软件下载服务"

        log_stage 2 5 "写入应用商店异步卸载接口"
        write_plugin_uninstall_assets

        log_stage 3 5 "统一刷新插件图标"
        install_unified_appcenter_icons || die "应用商店统一图标写入失败"

        log_stage 4 5 "刷新 LuCI 与应用商店缓存"
        refresh_luci_appcenter
        /etc/init.d/uhttpd reload >/dev/null 2>&1 || true

        log_stage 5 5 "校验 C2000Pro 兼容应用商店入口"
        verify_c2000pro_compat_appcenter
        verify_luci_route "nradioadv/system/appcenter" "C2000Pro 兼容应用商店"

        log "C2000Pro 兼容应用商店层已创建/刷新"
        log "入口: nradioadv/system/appcenter"
        log "说明: 保留 /etc/config/appcenter 插件记录；不修改原厂 nradio/app.lua 手机 API"
        return 0
    fi
    die "未检测到 C2000Pro / AK68-798 轻量应用商店环境"
}

install_appcenter_polish() {
    if lightweight_appcenter_model_supported; then
        die "完整应用商店美化适用于原厂完整商店；C2000Pro / AK68-798 请使用 4 > 4 > 1"
    fi

    log_stage 1 5 "检查 NRadio 应用商店模板"
    require_nradio_oem_appcenter
    verify_file_exists "$TPL" "NRadio 应用商店模板"
    log "说明: 直接美化应用商店，不创建事务备份或文件备份"

    log_stage 2 5 "更新应用商店 V3、系统状态与鲲鹏智能体兼容"
    if nros_revision_at_least 2 2 12 && appcenter_has_native_mobile_save_support; then
        log "检测:   NROS 2.2.12+ 已有手机保存应用按钮，保留原有规则"
    else
        log "检测:   原厂模板没有手机保存应用按钮规则，已添加"
    fi
    write_plugin_uninstall_assets
    write_original_appcenter_template
    patch_common_template
    patch_appcenter_status_controller
    patch_appcenter_card_polish_v3
    case "${CURRENT_DETECTED_MODEL:-}" in
        NRadio_C8-688|NRadio_C5800-650|NRadio_C5800-688|NRadio_NBCPE)
            log "当前机型支持 rootfs_2nd，正在接入应用商店双空间数据"
            patch_appcenter_storage_expand_display
            ;;
    esac

    log_stage 3 5 "统一刷新插件图标"
    install_unified_appcenter_icons || die "应用商店统一图标写入失败"

    log_stage 4 5 "刷新 LuCI 与应用商店缓存"
    refresh_luci_appcenter
    /etc/init.d/uhttpd reload >/dev/null 2>&1 || true

    log_stage 5 5 "校验应用商店页面"
    verify_file_exists "/usr/libexec/nradio-ai-compat.sh" "鲲鹏智能体兼容助手"
    grep -Fq 'NRadio appcenter AI post-install compatibility v1' "$APPCENTER_CONTROLLER" || die "鲲鹏智能体安装后兼容钩子校验失败"
    grep -Fq 'AI_ROUTE_DYNAMIC_V1' "$APPCENTER_CONTROLLER" || die "鲲鹏智能体应用商店动态路由回退校验失败"
    verify_luci_route "nradioadv/system/appcenter" "应用商店美化"

    log "应用商店 V3 更新完成"
    log "存储: C8-688/C5800/NBCPE 显示系统空间和 rootfs_2nd 空间"
    log "内容: 搜索、卡片、状态、系统信息、响应式布局、按钮、图标和弹窗"
    log "兼容: 鲲鹏智能体 0.0.2 / ZeroClaw 缺少的接口，安装后检查控制器与 OAF 技能"
    log "说明: 不改插件下载、安装和卸载；安装或更新成功后写入兼容配置，重复执行不会重复写入"
}

copy_factory_appcenter_file() {
    factory_src="$1"
    factory_dst="$2"
    factory_label="$3"
    factory_tmp_dst="${factory_dst}.factory.$$"

    [ -f "$factory_src" ] || die "${factory_label}原厂源文件不存在: $factory_src"
    [ -s "$factory_src" ] || die "${factory_label}原厂源文件为空: $factory_src"

    mkdir -p "$(dirname "$factory_dst")" || die "创建${factory_label}目录失败"
    rm -f "$factory_tmp_dst" 2>/dev/null || true
    cp "$factory_src" "$factory_tmp_dst" || {
        rm -f "$factory_tmp_dst" 2>/dev/null || true
        die "暂存${factory_label}失败"
    }
    chmod 644 "$factory_tmp_dst" 2>/dev/null || true
    mv -f "$factory_tmp_dst" "$factory_dst" || {
        rm -f "$factory_tmp_dst" 2>/dev/null || true
        die "写入${factory_label}失败"
    }
}

write_original_appcenter_template() {
    copy_factory_appcenter_file \
        "/rom/usr/lib/lua/luci/view/nradio_appcenter/appcenter.htm" \
        "$TPL" \
        "原厂应用商店模板"
}

write_original_appcenter_controller() {
    copy_factory_appcenter_file \
        "/rom/usr/lib/lua/luci/controller/nradio_adv/appcenter.lua" \
        "$APPCENTER_CONTROLLER" \
        "原厂应用商店控制器"
}

remove_lightweight_appcenter() {
    lightweight_appcenter_model_supported || die "轻量应用商店当前仅支持 C2000Pro / AK68-798"
    if is_current_model_ak798; then
        remove_ak798_compat_appcenter
        return 0
    fi
    if is_c2000pro_appcenter_environment; then
        log_stage 1 4 "检查 C2000Pro 兼容应用商店层"
        log "说明: C2000Pro 无旧版 /rom 应用商店模板；直接移除脚本生成的兼容 controller/template，不创建备份"

        log_stage 2 4 "移除脚本生成的 C2000Pro 兼容文件"
        remove_c2000pro_compat_appcenter

        log_stage 3 4 "刷新 LuCI 与应用商店缓存"
        refresh_luci_appcenter
        rm -f /usr/libexec/nradio-ai-compat.sh 2>/dev/null || true
        /etc/init.d/uhttpd reload >/dev/null 2>&1 || true

        log_stage 4 4 "确认插件记录保留"
        if [ -f "$CFG" ]; then
            log "保留: $CFG"
        else
            log "提示: 当前没有 $CFG，未发现可保留的插件记录"
        fi
        log "C2000Pro 兼容应用商店层已移除"
        return 0
    fi
    die "未检测到 C2000Pro / AK68-798 轻量应用商店环境"
}

restore_appcenter_original() {
    if lightweight_appcenter_model_supported; then
        die "完整应用商店还原适用于原厂完整商店；C2000Pro / AK68-798 请使用 4 > 4 > 2"
    fi

    log_stage 1 4 "检查 NRadio 应用商店原厂还原环境"
    require_nradio_oem_appcenter
    log "说明: 直接使用 /rom 只读原厂应用商店模板和控制器；不创建备份，不覆盖 /etc/config/appcenter"

    log_stage 2 4 "直接回写原厂应用商店文件"
    write_original_appcenter_template
    write_original_appcenter_controller

    log_stage 3 4 "刷新 LuCI 与应用商店缓存"
    refresh_luci_appcenter
    rm -f /usr/libexec/nradio-ai-compat.sh 2>/dev/null || true
    /etc/init.d/uhttpd reload >/dev/null 2>&1 || true

    log_stage 4 4 "校验应用商店入口"
    verify_file_exists "$TPL" "NRadio 应用商店模板"
    verify_file_exists "$APPCENTER_CONTROLLER" "NRadio 应用商店控制器"
    verify_luci_route "nradioadv/system/appcenter" "应用商店还原"

    log "应用商店已还原为 /rom 原厂模板和控制器"
    log "入口: nradioadv/system/appcenter"
}

refresh_luci_appcenter() {
    # Third-party app updates may restore ai.lua and reintroduce a missing has_ai() crash.
    # Re-apply the guarded call before rebuilding the LuCI dispatcher cache.
    fix_nradio_ai_has_ai_compat
    rm -f /tmp/luci-indexcache /tmp/infocd/cache/appcenter 2>/dev/null || true
    rm -f /tmp/luci-modulecache/* 2>/dev/null || true
    /etc/init.d/infocd restart >/dev/null 2>&1 || true
    /etc/init.d/appcenter restart >/dev/null 2>&1 || true
    sleep 2
}

quiesce_service() {
    init_script="$1"
    [ -f "$init_script" ] || return 0
    "$init_script" stop >/dev/null 2>&1 || true
    "$init_script" disable >/dev/null 2>&1 || true
}

enable_init_service_strict() {
    init_script="$1"
    service_label="${2:-$(basename "$init_script")}"
    [ -x "$init_script" ] || {
        log "错误: 缺少 $service_label 启动脚本: $init_script"
        return 1
    }

    "$init_script" disable >/dev/null 2>&1 || true
    "$init_script" enable >/dev/null 2>&1 || {
        log "错误: $service_label 设置开机启动失败"
        return 1
    }

    service_name="$(basename "$init_script")"
    for service_link in /etc/rc.d/S[0-9][0-9]"$service_name"; do
        [ -L "$service_link" ] && return 0
    done
    log "错误: $service_label 未生成有效的 /etc/rc.d 启动链接"
    return 1
}

restart_init_service_strict() {
    init_script="$1"
    service_label="${2:-$(basename "$init_script")}"
    "$init_script" restart >/dev/null 2>&1 || {
        log "错误: $service_label 重启失败"
        return 1
    }
    return 0
}

procfs_hides_other_users() {
    awk '$2 == "/proc" {
        found = 1
        count = split($4, opts, ",")
        for (i = 1; i <= count; i++) {
            if (opts[i] == "hidepid=1" || opts[i] == "hidepid=2" || opts[i] == "hidepid=invisible") exit 0
        }
        exit 1
    }
    END { if (!found) exit 1 }' /proc/mounts 2>/dev/null
}

require_private_procfs_for_secret_argv() {
    secret_label="${1:-敏感参数}"
    procfs_hides_other_users && return 0
    mount -o remount,hidepid=2 /proc >/dev/null 2>&1 || {
        log "错误: 无法为 $secret_label 启用 /proc hidepid=2，拒绝把密钥放入进程参数"
        return 1
    }
    procfs_hides_other_users || {
        log "错误: $secret_label 的 /proc 进程参数保护校验失败"
        return 1
    }
}

verify_luci_route() {
    route="$1"
    expect="$2"
    out="$WORKDIR/verify.$(echo "$route" | tr '/.' '__').html"
    code=''
    route_probe_attempt=1

    while [ "$route_probe_attempt" -le 3 ]; do
        code="$(curl -m 8 -s -o "$out" -w '%{http_code}' "http://127.0.0.1/cgi-bin/luci/$route" 2>/dev/null || true)"
        case "$code" in
            200|302|403)
                break
                ;;
            502|503|504|000|'')
                if [ "$route_probe_attempt" -lt 3 ]; then
                    sleep 2
                fi
                ;;
            *)
                break
                ;;
        esac
        route_probe_attempt=$((route_probe_attempt + 1))
    done

    case "$code" in
        200|302|403)
            ;;
        *)
            log "错误: $expect LuCI 路由不可用，HTTP ${code:-000}: $route"
            return 1
            ;;
    esac

    if grep -Eq 'Failed to execute|error500|Runtime error|not found!|has no parent node|No page is registered at' "$out" 2>/dev/null; then
        log "错误: $expect LuCI 路由返回错误页: $route"
        return 1
    fi

    return 0
}

verify_file_exists() {
    path="$1"
    label="$2"
    [ -f "$path" ] || die "$label verify failed: missing $path"
}

verify_template_marker() {
    pattern="$1"
    label="$2"
    if grep -Fq -- "$pattern" "$TPL" 2>/dev/null; then
        return 0
    fi

    die "appcenter template verify failed: missing $label"
}

get_installed_package_version() {
    pkg_name="$1"
    opkg status "$pkg_name" 2>/dev/null | awk -F': ' '/^Version: /{print $2; exit}'
}

delete_iptables_rule_loop() {
    table_name="$1"
    chain_name="$2"
    shift 2

    command -v iptables >/dev/null 2>&1 || return 0
    while iptables -t "$table_name" -C "$chain_name" "$@" >/dev/null 2>&1; do
        iptables -t "$table_name" -D "$chain_name" "$@" >/dev/null 2>&1 || break
    done
}

cleanup_openvpn_target_policy_rules() {
    target="$1"
    lan_if="$2"
    pri=60
    while [ "$pri" -le 119 ]; do
        ip rule del to "$target" lookup main priority "$pri" 2>/dev/null || true
        ip rule del iif "$lan_if" to "$target" lookup main priority "$pri" 2>/dev/null || true
        pri=$((pri + 1))
    done
}

cleanup_openvpn_target_runtime_rules() {
    target="$1"
    lan_if="$2"
    tun_if="$3"
    lan_subnet="$4"
    nat_flag="$5"
    forward_flag="$6"

    [ -n "$target" ] || return 0
    cleanup_openvpn_target_policy_rules "$target" "$lan_if"
    ip route del "$target" 2>/dev/null || true

    case "$nat_flag" in
        1|y|Y|yes|YES|true|TRUE)
            [ -n "$lan_subnet" ] && [ -n "$tun_if" ] && delete_iptables_rule_loop nat POSTROUTING -s "$lan_subnet" -d "$target" -o "$tun_if" -j MASQUERADE
            ;;
    esac

    case "$forward_flag" in
        1|y|Y|yes|YES|true|TRUE)
            [ -n "$lan_if" ] && [ -n "$tun_if" ] && delete_iptables_rule_loop filter FORWARD -d "$target" -i "$lan_if" -o "$tun_if" -j ACCEPT
            [ -n "$lan_if" ] && [ -n "$tun_if" ] && [ -n "$lan_subnet" ] && delete_iptables_rule_loop filter FORWARD -s "$lan_subnet" -d "$target" -i "$lan_if" -o "$tun_if" -j ACCEPT
            [ -n "$lan_if" ] && [ -n "$tun_if" ] && [ -n "$lan_subnet" ] && delete_iptables_rule_loop filter FORWARD -s "$target" -d "$lan_subnet" -i "$tun_if" -o "$lan_if" -j ACCEPT
            ;;
    esac
}

cleanup_saved_openvpn_runtime_state() {
    [ -n "${OLD_ROUTE_TUN_IF:-}" ] || return 0

    old_lan_if="${OLD_ROUTE_LAN_IF:-br-lan}"
    old_tun_if="${OLD_ROUTE_TUN_IF:-}"
    old_lan_subnet="${OLD_ROUTE_LAN_SUBNET:-}"
    old_route_nat="${OLD_ROUTE_NAT:-n}"
    old_route_forward="${OLD_ROUTE_FORWARD:-n}"

    if [ -s "$ROUTE_MAP_LIST_FILE" ]; then
        while IFS='|' read -r old_peer_target old_peer_gw old_peer_kind_saved; do
            [ -n "$old_peer_target" ] || continue
            [ -n "$old_peer_kind_saved" ] || old_peer_kind_saved="$(infer_map_target_kind "$old_peer_target")"
            if [ "$old_peer_kind_saved" = 'host' ]; then
                old_peer_target="${old_peer_target%/*}"
                ip neigh del proxy "$old_peer_target" dev "$old_lan_if" 2>/dev/null || true
            fi
            cleanup_openvpn_target_runtime_rules "$old_peer_target" "$old_lan_if" "$old_tun_if" "$old_lan_subnet" "$old_route_nat" "$old_route_forward"
        done < "$ROUTE_MAP_LIST_FILE"
    fi

    old_enhanced_pri=196
    if [ -s "$ROUTE_LIST_FILE" ]; then
        while IFS='|' read -r old_subnet old_gw; do
            [ -n "$old_subnet" ] || continue
            cleanup_openvpn_target_runtime_rules "$old_subnet" "$old_lan_if" "$old_tun_if" "$old_lan_subnet" "$old_route_nat" "$old_route_forward"
            case "${OLD_ROUTE_ENHANCED:-n}" in
                1|y|Y|yes|YES|true|TRUE)
                    [ -n "$old_lan_subnet" ] && ip rule del from "$old_lan_subnet" to "$old_subnet" lookup main priority "$old_enhanced_pri" 2>/dev/null || true
                    old_enhanced_pri=$((old_enhanced_pri + 1))
                    ;;
            esac
        done < "$ROUTE_LIST_FILE"
    fi

    case "${OLD_ROUTE_MAP_ENABLE:-n}" in
        1|y|Y|yes|YES|true|TRUE)
            case "${OLD_ROUTE_MAP_KIND:-}" in
                host)
                    if [ -n "${OLD_ROUTE_MAP_HOST:-}" ]; then
                        old_lan_host_ip="${OLD_ROUTE_LAN_HOST_IP:-}"
                        [ -n "$old_lan_host_ip" ] || old_lan_host_ip="$(get_interface_subnet "$old_lan_if" 2>/dev/null | cut -d/ -f1 || true)"
                        [ -n "$old_lan_host_ip" ] || old_lan_host_ip="$(uci -q get network.lan.ipaddr 2>/dev/null || true)"
                        old_lan_host_ip="$(normalize_ipv4_host "$old_lan_host_ip" 2>/dev/null || true)"
                        [ -n "$old_lan_host_ip" ] && delete_iptables_rule_loop nat PREROUTING -i "$old_tun_if" -d "${OLD_ROUTE_MAP_HOST}" -j DNAT --to-destination "$old_lan_host_ip"
                        [ -n "$old_lan_host_ip" ] && delete_iptables_rule_loop nat OUTPUT -d "${OLD_ROUTE_MAP_HOST}" -j DNAT --to-destination "$old_lan_host_ip"
                    fi
                    [ -n "${OLD_ROUTE_MAP_IP:-}" ] && ip addr del "${OLD_ROUTE_MAP_IP}" dev "$old_lan_if" 2>/dev/null || true
                    ;;
                subnet)
                    [ -n "${OLD_ROUTE_MAP_SUBNET:-}" ] && [ -n "$old_lan_subnet" ] && delete_iptables_rule_loop nat PREROUTING -i "$old_tun_if" -d "${OLD_ROUTE_MAP_SUBNET}" -j NETMAP --to "$old_lan_subnet"
                    [ -n "${OLD_ROUTE_MAP_SUBNET:-}" ] && [ -n "$old_lan_subnet" ] && delete_iptables_rule_loop nat OUTPUT -d "${OLD_ROUTE_MAP_SUBNET}" -j NETMAP --to "$old_lan_subnet"
                    ;;
            esac
            ;;
    esac
}

is_adguardhome_luci_ready() {
    current_adg_ver="$(get_installed_package_version luci-app-adguardhome 2>/dev/null || true)"
    [ "$current_adg_ver" = "$ADGUARDHOME_VERSION" ] || return 1

    for needed in \
        /usr/lib/lua/luci/controller/AdGuardHome.lua \
        /usr/lib/lua/luci/model/cbi/AdGuardHome/base.lua \
        /usr/lib/lua/luci/model/cbi/AdGuardHome/manual.lua \
        /usr/lib/lua/luci/model/cbi/AdGuardHome/log.lua \
        /usr/share/AdGuardHome/AdGuardHome_template.yaml; do
        [ -f "$needed" ] || return 1
    done

    return 0
}

print_openvpn_runtime_debug() {
    log "debug: openvpn service status"
    /etc/init.d/openvpn status 2>/dev/null || true
    log "debug: /var/log/nradio-openvpn-client.log"
    sed -n '1,120p' /var/log/nradio-openvpn-client.log 2>/dev/null || true
    log "debug: $WORKDIR/openvpn-runtime-fix.log"
    sed -n '1,120p' "$WORKDIR/openvpn-runtime-fix.log" 2>/dev/null || true
    log "debug: /var/run/openvpn.custom_config.status"
    sed -n '1,120p' /var/run/openvpn.custom_config.status 2>/dev/null || true
    log "debug: recent logread openvpn"
    logread 2>/dev/null | grep -i openvpn | tail -40 || true
}

print_openvpn_runtime_hints() {
    cert_auth="$1"
    tls_mode="$2"
    proto="$3"
    runtime_log="$4"

    case "$runtime_log" in
        *VERIFY\ KU\ ERROR*|*certificate\ verify\ failed*)
            log "hint: server certificate verification failed; rerun option 9 and choose server verify mode 1 (compat mode)"
            return 0
            ;;
        *'/dev/net/tun'*|*'Cannot open TUN/TAP dev'*|*'TUNSETIFF'*|*'No such device'*)
            log "hint: tun driver is missing or unusable; run option 8 to install/fix tun support first"
            return 0
            ;;
        *liblzo2.so.2*|*lzo1x_*|*__lzo_init_v2*)
            log "hint: OpenVPN runtime dependency liblzo2 is missing or broken; run option 8 again after fixing package installation"
            return 0
            ;;
    esac

    log "hint: check whether your server really requires client certificate/private key"
    [ "$cert_auth" = '1' ] && log "hint: if your server only uses username/password, rerun option 9 and choose n for client certificate/private key"
    [ "$tls_mode" = '0' ] && log "hint: if your server uses tls-auth or tls-crypt, rerun option 9 and choose the correct mode"
    case "$proto" in
        udp6|tcp6-client)
            log "hint: if your server or network does not support IPv6 transport well, rerun option 9 and choose ipv4"
            ;;
    esac
}

openvpn_selfcheck_bool() {
    case "$1" in
        1|y|Y|yes|YES|true|TRUE) printf '%s\n' 'yes' ;;
        *) printf '%s\n' 'no' ;;
    esac
}

openvpn_route_via_dev_exists() {
    route_target="$1"
    route_gw="$2"
    route_dev="$3"
    route_target_alt=""
    case "$route_target" in
        */32) route_target_alt="${route_target%/*}" ;;
        */*) ;;
        *) route_target_alt="${route_target}/32" ;;
    esac

    ip route 2>/dev/null | awk -v target="$route_target" -v alt="$route_target_alt" -v gw="$route_gw" -v dev="$route_dev" '
        $2 == "via" && $3 == gw && $4 == "dev" && $5 == dev && ($1 == target || (alt != "" && $1 == alt)) { found = 1 }
        END { exit found ? 0 : 1 }
    '
}

openvpn_ip_rule_to_exists() {
    rule_target="$1"
    rule_target_alt=""
    case "$rule_target" in
        */32) rule_target_alt="${rule_target%/*}" ;;
        */*) ;;
        *) rule_target_alt="${rule_target}/32" ;;
    esac

    ip rule 2>/dev/null | awk -v target="$rule_target" -v alt="$rule_target_alt" '
        {
            has_to = 0
            has_lookup = 0
            for (i = 1; i <= NF; i++) {
                if ($i == "to" && ($(i + 1) == target || (alt != "" && $(i + 1) == alt)))
                    has_to = 1
                if ($i == "lookup" && $(i + 1) == "main")
                    has_lookup = 1
            }
            if (has_to && has_lookup)
                found = 1
        }
        END { exit found ? 0 : 1 }
    '
}

openvpn_ip_rule_iif_to_exists() {
    rule_target="$1"
    rule_iface="$2"
    rule_target_alt=""
    case "$rule_target" in
        */32) rule_target_alt="${rule_target%/*}" ;;
        */*) ;;
        *) rule_target_alt="${rule_target}/32" ;;
    esac

    ip rule 2>/dev/null | awk -v target="$rule_target" -v alt="$rule_target_alt" -v iface="$rule_iface" '
        {
            has_iif = 0
            has_to = 0
            has_lookup = 0
            for (i = 1; i <= NF; i++) {
                if ($i == "iif" && $(i + 1) == iface)
                    has_iif = 1
                if ($i == "to" && ($(i + 1) == target || (alt != "" && $(i + 1) == alt)))
                    has_to = 1
                if ($i == "lookup" && $(i + 1) == "main")
                    has_lookup = 1
            }
            if (has_iif && has_to && has_lookup)
                found = 1
        }
        END { exit found ? 0 : 1 }
    '
}

selfcheck_print_header() {
    log "$1"
    log "------"
}

selfcheck_print_file_state() {
    label="$1"
    path="$2"
    if [ -s "$path" ]; then
        size="$(wc -c < "$path" 2>/dev/null | tr -d ' ' || true)"
        [ -n "$size" ] || size='?'
        log "file:     $label = present ($path, ${size} bytes)"
    elif [ -e "$path" ]; then
        log "file:     $label = present but empty ($path)"
    else
        log "file:     $label = missing ($path)"
    fi
}

openvpn_selfcheck_print_file_state() {
    label="$1"
    path="$2"

    case "$label" in
        "runtime state")
            if [ ! -e "$path" ] && [ "${OVPN_SELFCHECK_RUNTIME_SOURCE:-saved}" = 'profile' ]; then
                log "file:     $label = synthesized from current profile ($path)"
                return 0
            fi
            ;;
        "route state")
            if [ ! -e "$path" ] && [ "${OVPN_SELFCHECK_ROUTE_STATE_SOURCE:-saved}" = 'hotplug' ]; then
                log "file:     $label = synthesized from route hotplug ($path)"
                return 0
            fi
            ;;
        "saved route list")
            if [ ! -e "$path" ] && [ "${OVPN_SELFCHECK_ROUTE_LIST_SOURCE:-saved}" = 'runtime' ]; then
                log "file:     $label = synthesized from active tun routes ($path)"
                return 0
            fi
            ;;
        "saved mapped peers")
            if [ ! -e "$path" ] && [ "${OVPN_SELFCHECK_MAP_LIST_SOURCE:-saved}" = 'runtime' ]; then
                log "file:     $label = synthesized from proxy neighbors ($path)"
                return 0
            fi
            ;;
    esac

    selfcheck_print_file_state "$label" "$path"
}

selfcheck_print_service_state() {
    label="$1"
    init_script="$2"

    if [ ! -x "$init_script" ]; then
        log "service:  $label missing ($init_script)"
        return 0
    fi

    if "$init_script" enabled >/dev/null 2>&1; then
        service_enabled='1'
    else
        service_enabled='0'
    fi
    service_status="$( ( "$init_script" status 2>/dev/null || true ) | tr '\n' ' ' | sed 's/[[:space:]]\+/ /g; s/^ //; s/ $//' )"
    [ -n "$service_status" ] || service_status='stopped'
    log "service:  $label enabled=$(openvpn_selfcheck_bool "$service_enabled") status=$service_status"
}

selfcheck_luci_route_ok() {
    route="$1"
    out="$WORKDIR/selfcheck.$(printf '%s' "$route" | tr '/.' '__').probe"
    code="$(curl -m 8 -s -o "$out" -w '%{http_code}' "http://127.0.0.1/cgi-bin/luci/$route" 2>/dev/null || true)"

    case "$code" in
        200|302|403)
            if grep -Eq 'Failed to execute|error500|Runtime error|not found!|has no parent node|No page is registered at' "$out" 2>/dev/null; then
                return 1
            fi
            return 0
            ;;
    esac

    return 1
}

selfcheck_print_luci_route_state() {
    label="$1"
    route="$2"
    out="$WORKDIR/selfcheck.$(printf '%s' "$route" | tr '/.' '__').html"
    code="$(curl -m 8 -s -o "$out" -w '%{http_code}' "http://127.0.0.1/cgi-bin/luci/$route" 2>/dev/null || true)"

    if selfcheck_luci_route_ok "$route"; then
        log "路由:    $label = 正常 (HTTP ${code:-000})"
        return 0
    fi

    case "$code" in
        200|302|403)
            log "路由:    $label = LuCI 错误页 (HTTP $code)"
            ;;
        *)
            log "路由:    $label = 缺失 (HTTP ${code:-000})"
            ;;
    esac
}

selfcheck_required_paths_present() {
    for needed_path in "$@"; do
        [ -e "$needed_path" ] || return 1
    done
    return 0
}

selfcheck_print_luci_route_state_when_ready() {
    label="$1"
    route="$2"
    shift 2

    for needed_path in "$@"; do
        if [ ! -e "$needed_path" ]; then
            log "路由:    $label = 跳过 (缺少 $needed_path)"
            return 0
        fi
    done

    selfcheck_print_luci_route_state "$label" "$route"
}

selfcheck_luci_route_ok_when_ready() {
    route="$1"
    shift

    selfcheck_required_paths_present "$@" || return 2
    selfcheck_luci_route_ok "$route"
}

selfcheck_appcenter_controller_fallback_matches() {
    plugin_name="$1"
    actual_controller="$2"

    case "$plugin_name" in
        luci-app-openclash) [ "$actual_controller" = "/usr/lib/lua/luci/controller/openclash.lua" ] && return 0 ;;
        luci-app-adguardhome) [ "$actual_controller" = "/usr/lib/lua/luci/controller/AdGuardHome.lua" ] && return 0 ;;
        OpenVPN) [ "$actual_controller" = "/usr/lib/lua/luci/controller/nradio_adv/openvpn_full.lua" ] && return 0 ;;
        DDNS-GO) [ "$actual_controller" = "$DDNSGO_CONTROLLER" ] && return 0 ;;
        MosDNS) [ "$actual_controller" = "$MOSDNS_CONTROLLER" ] && return 0 ;;
        FanControl) [ "$actual_controller" = "$FANCTRL_CONTROLLER" ] && return 0 ;;
        奇游联机宝) [ "$actual_controller" = "/usr/lib/lua/luci/controller/nradio_adv/qiyou.lua" ] && return 0 ;;
        雷神加速器) [ "$actual_controller" = "/usr/lib/lua/luci/controller/nradio_adv/leigod.lua" ] && return 0 ;;
    esac

    return 1
}

selfcheck_appcenter_route_matches() {
    plugin_name="$1"
    expect_route="$2"
    sec_list="$(uci show appcenter 2>/dev/null | while IFS= read -r line; do
        case "$line" in
            "appcenter.@package_list"*".name='${plugin_name}'"|"appcenter.cfg"*".name='${plugin_name}'")
                sec="${line#appcenter.}"
                sec="${sec%%.*}"
                printf '%s\n' "$sec"
                ;;
        esac
    done)"

    if [ "$plugin_name" = "${DDNSGO_APP_NAME:-DDNS-GO}" ]; then
        parent_sec_list="$(uci show appcenter 2>/dev/null | while IFS= read -r line; do
            case "$line" in
                "appcenter.@package_list"*".parent='${plugin_name}'"|"appcenter.cfg"*".parent='${plugin_name}'")
                    sec="${line#appcenter.}"
                    sec="${sec%%.*}"
                    printf '%s\n' "$sec"
                    ;;
            esac
        done)"
        if [ -n "$parent_sec_list" ]; then
            sec_list="$(printf '%s\n%s\n' "$sec_list" "$parent_sec_list" | sed '/^$/d' | sort -u)"
        fi
    fi

    [ -n "$sec_list" ] || return 1

    for sec in $sec_list; do
        [ -n "$sec" ] || continue
        [ "$(uci -q get "appcenter.$sec" 2>/dev/null || true)" = "package_list" ] || continue
        actual_route="$(uci -q get appcenter.$sec.luci_module_route 2>/dev/null || true)"
        [ "$actual_route" = "$expect_route" ] && return 0
        actual_controller="$(uci -q get appcenter.$sec.luci_module_file 2>/dev/null || true)"
        selfcheck_appcenter_controller_fallback_matches "$plugin_name" "$actual_controller" && return 0
    done
    return 1
}

selfcheck_print_appcenter_route_state() {
    label="$1"
    plugin_name="$2"
    expect_route="$3"

    sec="$(find_uci_section package_list "$plugin_name")"
    if [ -z "$sec" ] && [ "$plugin_name" = "${DDNSGO_APP_NAME:-DDNS-GO}" ]; then
        sec="$(uci show appcenter 2>/dev/null | while IFS= read -r line; do
            case "$line" in
                "appcenter.@package_list"*".parent='${plugin_name}'"|"appcenter.cfg"*".parent='${plugin_name}'")
                    candidate="${line#appcenter.}"
                    candidate="${candidate%%.*}"
                    if [ "$(uci -q get "appcenter.$candidate" 2>/dev/null || true)" = "package_list" ]; then
                        printf '%s\n' "$candidate"
                        break
                    fi
                    ;;
            esac
        done)"
    fi
    if [ -z "$sec" ]; then
        log "应用商店: $label = 缺失"
        return 0
    fi

    actual_route="$(uci -q get appcenter.$sec.luci_module_route 2>/dev/null || true)"
    if [ "$actual_route" = "$expect_route" ]; then
        log "应用商店: $label = 正常 ($actual_route)"
    else
        actual_controller="$(uci -q get appcenter.$sec.luci_module_file 2>/dev/null || true)"
        selfcheck_appcenter_controller_fallback_matches "$plugin_name" "$actual_controller" && {
            log "应用商店: $label = 正常 (controller fallback)"
            return 0
        }
        log "应用商店: $label = 不匹配 (${actual_route:-缺失})"
    fi
}

selfcheck_print_process_state() {
    label="$1"
    pattern="$2"
    ps_text="$(pgrep -af "$pattern" 2>/dev/null || true)"
    if [ -n "$ps_text" ]; then
        first_line="$(printf '%s\n' "$ps_text" | sed -n '1p')"
        log "runtime:  $label process present ($first_line)"
    else
        log "runtime:  $label process missing"
    fi
}

selfcheck_finalize_summary() {
    failures="$1"
    warnings="$2"

    NRADIO_LAST_SELFCHECK_ERRORS="$failures"
    NRADIO_LAST_SELFCHECK_WARNINGS="$warnings"

    if [ "$failures" -gt 0 ]; then
        NRADIO_LAST_SELFCHECK_STATUS='FAIL'
        log "summary:  FAIL (errors=$failures warnings=$warnings)"
    elif [ "$warnings" -gt 0 ]; then
        NRADIO_LAST_SELFCHECK_STATUS='WARN'
        log "summary:  WARN (errors=0 warnings=$warnings)"
    else
        NRADIO_LAST_SELFCHECK_STATUS='PASS'
        log "summary:  PASS"
    fi
}

set_last_selfcheck_status() {
    status="$1"
    errors="${2:-0}"
    warnings="${3:-0}"

    NRADIO_LAST_SELFCHECK_ERRORS="$errors"
    NRADIO_LAST_SELFCHECK_WARNINGS="$warnings"
    case "$status" in
        FAIL|PASS|WARN|SKIP)
            NRADIO_LAST_SELFCHECK_STATUS="$status"
            ;;
        *)
            NRADIO_LAST_SELFCHECK_STATUS='WARN'
            ;;
    esac
}

unified_now_s() {
    date +%s 2>/dev/null || printf '%s\n' '0'
}

record_unified_selfcheck_summary() {
    label="$1"
    now_s="$(unified_now_s)"
    elapsed_text=''

    case "${NRADIO_UNIFIED_SECTION_START:-}" in
        ''|*[!0-9]*)
            ;;
        *)
            case "$now_s" in
                ''|*[!0-9]*)
                    ;;
                *)
                    elapsed_s=$((now_s - NRADIO_UNIFIED_SECTION_START))
                    [ "$elapsed_s" -ge 0 ] 2>/dev/null && elapsed_text=" 耗时=${elapsed_s}s"
                    ;;
            esac
            ;;
    esac

    case "${NRADIO_LAST_SELFCHECK_STATUS:-WARN}" in
        FAIL)
            NRADIO_UNIFIED_FAILS=$((NRADIO_UNIFIED_FAILS + 1))
            ;;
        PASS)
            NRADIO_UNIFIED_PASSES=$((NRADIO_UNIFIED_PASSES + 1))
            ;;
        SKIP)
            NRADIO_UNIFIED_SKIPS=$((NRADIO_UNIFIED_SKIPS + 1))
            ;;
        *)
            NRADIO_UNIFIED_WARNS=$((NRADIO_UNIFIED_WARNS + 1))
            NRADIO_LAST_SELFCHECK_STATUS='WARN'
            ;;
    esac
    log "overall:  $label = ${NRADIO_LAST_SELFCHECK_STATUS}${elapsed_text}"
    NRADIO_UNIFIED_SECTION_START="$now_s"
}

run_openclash_cdn_selfcheck() {
    optimize_openclash_cdn_order
    if [ "${OPENCLASH_CDN_RANKED:-0}" = '1' ] && [ -n "${OPENCLASH_MIRRORS:-}" ]; then
        set_last_selfcheck_status PASS 0 0
    else
        log "CDN:      $OPENCLASH_DISPLAY_NAME = 未得出排序"
        set_last_selfcheck_status WARN 0 1
    fi
}

run_adguardhome_cdn_selfcheck() {
    optimize_adguardhome_cdn_order
    if [ "${ADGUARDHOME_CDN_RANKED:-0}" = '1' ] && [ -n "${ADGUARDHOME_IPK_URLS:-}" ]; then
        set_last_selfcheck_status PASS 0 0
    else
        log "CDN:      AdGuardHome = 未得出排序"
        set_last_selfcheck_status WARN 0 1
    fi
}

get_ttyd_bind_value() {
    opt_name="$1"
    value="$(uci -q show ttyd 2>/dev/null | awk -F"='" -v opt="$opt_name" '
        $1 ~ ("\\.(" opt ")$") {
            val=$2
            sub(/\047$/, "", val)
            print val
            exit
        }
    ' || true)"
    printf '%s\n' "$value"
}

run_openclash_selfcheck() {
    require_root
    oc_selfcheck_failures=0
    oc_selfcheck_warnings=0
    oc_present='0'
    openclash_core_path="/etc/openclash/core/clash"
    [ -x "$openclash_core_path" ] || [ ! -x /etc/openclash/clash ] || openclash_core_path="/etc/openclash/clash"
    selfcheck_print_header "$OPENCLASH_DISPLAY_NAME 自检"

    for oc_path in \
        /etc/init.d/openclash \
        /usr/lib/lua/luci/controller/openclash.lua \
        /etc/config/openclash \
        /etc/openclash/core_version \
        "$openclash_core_path" \
        /etc/openclash/core/clash_meta; do
        [ -e "$oc_path" ] && oc_present='1'
    done
    if [ "$oc_present" != '1' ]; then
        log "插件:   $OPENCLASH_DISPLAY_NAME = 未安装，跳过可选插件自检"
        log "summary:  SKIP (optional plugin not installed)"
        set_last_selfcheck_status SKIP 0 0
        return 0
    fi

    selfcheck_print_service_state "openclash" "/etc/init.d/openclash"
    selfcheck_print_file_state "controller" "/usr/lib/lua/luci/controller/openclash.lua"
    selfcheck_print_file_state "uci config" "/etc/config/openclash"
    selfcheck_print_file_state "core version" "/etc/openclash/core_version"
    selfcheck_print_file_state "smart core clash" "$openclash_core_path"
    selfcheck_print_file_state "smart core clash_meta" "/etc/openclash/core/clash_meta"
    selfcheck_print_file_state "ASN.mmdb" "/etc/openclash/ASN.mmdb"
    selfcheck_print_appcenter_route_state "$OPENCLASH_DISPLAY_NAME" "luci-app-openclash" "admin/services/openclash"
    selfcheck_print_luci_route_state_when_ready "$OPENCLASH_DISPLAY_NAME overview" "admin/services/openclash" /usr/lib/lua/luci/controller/openclash.lua
    selfcheck_print_luci_route_state_when_ready "$OPENCLASH_DISPLAY_NAME settings" "admin/services/openclash/settings" /usr/lib/lua/luci/controller/openclash.lua
    [ -x /etc/init.d/openclash ] || oc_selfcheck_failures=$((oc_selfcheck_failures + 1))
    if [ -x /etc/init.d/openclash ]; then
        openclash_enabled='0'
        /etc/init.d/openclash enabled >/dev/null 2>&1 && openclash_enabled='1'
        openclash_service_status="$( ( /etc/init.d/openclash status 2>/dev/null || true ) | tr '\n' ' ' | sed 's/[[:space:]]\+/ /g; s/^ //; s/ $//' )"
        openclash_running='0'
        case "$openclash_service_status" in
            *running*|1) openclash_running='1' ;;
            *) oc_selfcheck_warnings=$((oc_selfcheck_warnings + 1)) ;;
        esac
        if [ "$openclash_enabled" = '0' ]; then
            if [ "$openclash_running" = '1' ]; then
                log "备注:     $OPENCLASH_DISPLAY_NAME autostart disabled, but runtime is active"
            else
                oc_selfcheck_warnings=$((oc_selfcheck_warnings + 1))
            fi
        fi
    fi
    [ -f /usr/lib/lua/luci/controller/openclash.lua ] || oc_selfcheck_failures=$((oc_selfcheck_failures + 1))
    [ -f /etc/config/openclash ] || oc_selfcheck_failures=$((oc_selfcheck_failures + 1))
    [ -s /etc/openclash/core_version ] || oc_selfcheck_warnings=$((oc_selfcheck_warnings + 1))
    [ -x "$openclash_core_path" ] || oc_selfcheck_warnings=$((oc_selfcheck_warnings + 1))
    [ -x /etc/openclash/core/clash_meta ] || oc_selfcheck_warnings=$((oc_selfcheck_warnings + 1))
    if ! openclash_asn_mmdb_valid; then
        log "runtime:  $OPENCLASH_DISPLAY_NAME ASN.mmdb missing or invalid"
        oc_selfcheck_warnings=$((oc_selfcheck_warnings + 1))
    fi
    selfcheck_appcenter_route_matches "luci-app-openclash" "admin/services/openclash" || oc_selfcheck_failures=$((oc_selfcheck_failures + 1))
    if selfcheck_luci_route_ok_when_ready "admin/services/openclash" /usr/lib/lua/luci/controller/openclash.lua; then
        route_rc='0'
    else
        route_rc="$?"
    fi
    [ "$route_rc" = '0' ] || [ "$route_rc" = '2' ] || oc_selfcheck_failures=$((oc_selfcheck_failures + 1))
    if selfcheck_luci_route_ok_when_ready "admin/services/openclash/settings" /usr/lib/lua/luci/controller/openclash.lua; then
        route_rc='0'
    else
        route_rc="$?"
    fi
    [ "$route_rc" = '0' ] || [ "$route_rc" = '2' ] || oc_selfcheck_failures=$((oc_selfcheck_failures + 1))

    if [ -s /etc/openclash/core_version ]; then
        core_version_text="$(tr '\n' ' ' < /etc/openclash/core_version 2>/dev/null | sed 's/[[:space:]]\+/ /g; s/^ //; s/ $//' || true)"
        [ -n "$core_version_text" ] && log "核心:     $core_version_text"
    fi

    active_clash_ps="$(pgrep -af '/etc/openclash/|openclash_watchdog|/etc/openclash/core/clash' 2>/dev/null || true)"
    if [ -n "$active_clash_ps" ]; then
        active_clash_line="$(printf '%s\n' "$active_clash_ps" | sed -n '1p')"
        log "runtime:  $OPENCLASH_DISPLAY_NAME process present ($active_clash_line)"
    else
        log "runtime:  $OPENCLASH_DISPLAY_NAME process missing"
        oc_selfcheck_warnings=$((oc_selfcheck_warnings + 1))
    fi
    selfcheck_finalize_summary "$oc_selfcheck_failures" "$oc_selfcheck_warnings"
}

run_adguardhome_selfcheck() {
    require_root
    selfcheck_print_header "AdGuardHome 自检"

    adg_selfcheck_failures=0
    adg_selfcheck_warnings=0
    adg_binpath="$(uci -q get AdGuardHome.AdGuardHome.binpath 2>/dev/null || true)"
    [ -n "$adg_binpath" ] || adg_binpath="/usr/bin/AdGuardHome/AdGuardHome"
    adg_configpath="$(get_adguard_configpath)"
    adg_core_present='0'
    adg_present='0'
    [ -x "$adg_binpath" ] && adg_core_present='1'

    for adg_path in \
        /etc/init.d/AdGuardHome \
        /usr/lib/lua/luci/controller/AdGuardHome.lua \
        /usr/lib/lua/luci/model/cbi/AdGuardHome/base.lua \
        /usr/lib/lua/luci/model/cbi/AdGuardHome/manual.lua \
        /usr/lib/lua/luci/model/cbi/AdGuardHome/log.lua \
        /usr/lib/lua/luci/view/AdGuardHome/oem_wrapper.htm \
        "$adg_binpath" \
        "$adg_configpath"; do
        [ -e "$adg_path" ] && adg_present='1'
    done
    if [ "$adg_present" != '1' ]; then
        log "插件:   AdGuardHome = 未安装，跳过可选插件自检"
        log "summary:  SKIP (optional plugin not installed)"
        set_last_selfcheck_status SKIP 0 0
        return 0
    fi

    selfcheck_print_service_state "AdGuardHome" "/etc/init.d/AdGuardHome"
    selfcheck_print_file_state "controller" "/usr/lib/lua/luci/controller/AdGuardHome.lua"
    selfcheck_print_file_state "base page" "/usr/lib/lua/luci/model/cbi/AdGuardHome/base.lua"
    selfcheck_print_file_state "manual page" "/usr/lib/lua/luci/model/cbi/AdGuardHome/manual.lua"
    selfcheck_print_file_state "log page" "/usr/lib/lua/luci/model/cbi/AdGuardHome/log.lua"
    selfcheck_print_file_state "wrapper page" "/usr/lib/lua/luci/view/AdGuardHome/oem_wrapper.htm"
    selfcheck_print_file_state "core binary" "$adg_binpath"
    selfcheck_print_file_state "config" "$adg_configpath"
    selfcheck_print_appcenter_route_state "AdGuardHome" "luci-app-adguardhome" "admin/services/AdGuardHome"
    selfcheck_print_luci_route_state_when_ready "AdGuardHome overview" "admin/services/AdGuardHome" /usr/lib/lua/luci/controller/AdGuardHome.lua
    selfcheck_print_luci_route_state_when_ready "AdGuardHome base" "admin/services/AdGuardHome/base" /usr/lib/lua/luci/controller/AdGuardHome.lua /usr/lib/lua/luci/model/cbi/AdGuardHome/base.lua
    selfcheck_print_luci_route_state_when_ready "AdGuardHome manual" "admin/services/AdGuardHome/manual" /usr/lib/lua/luci/controller/AdGuardHome.lua /usr/lib/lua/luci/model/cbi/AdGuardHome/manual.lua
    selfcheck_print_luci_route_state_when_ready "AdGuardHome log" "admin/services/AdGuardHome/log" /usr/lib/lua/luci/controller/AdGuardHome.lua /usr/lib/lua/luci/model/cbi/AdGuardHome/log.lua
    [ -x /etc/init.d/AdGuardHome ] || adg_selfcheck_failures=$((adg_selfcheck_failures + 1))
    if [ "$adg_core_present" = '1' ]; then
        if ! /etc/init.d/AdGuardHome enabled >/dev/null 2>&1; then
            adg_selfcheck_warnings=$((adg_selfcheck_warnings + 1))
        fi
        adg_service_status="$( ( /etc/init.d/AdGuardHome status 2>/dev/null || true ) | tr '\n' ' ' | sed 's/[[:space:]]\+/ /g; s/^ //; s/ $//' )"
        case "$adg_service_status" in
            *running*|1) ;;
            *) adg_selfcheck_failures=$((adg_selfcheck_failures + 1)) ;;
        esac
    else
        log "备注:     AdGuardHome 核心未安装，当前按 LuCI-only 状态检查"
        adg_selfcheck_warnings=$((adg_selfcheck_warnings + 1))
    fi
    for needed in \
        /usr/lib/lua/luci/controller/AdGuardHome.lua \
        /usr/lib/lua/luci/model/cbi/AdGuardHome/base.lua \
        /usr/lib/lua/luci/model/cbi/AdGuardHome/manual.lua \
        /usr/lib/lua/luci/model/cbi/AdGuardHome/log.lua \
        /usr/lib/lua/luci/view/AdGuardHome/oem_wrapper.htm; do
        [ -f "$needed" ] || adg_selfcheck_failures=$((adg_selfcheck_failures + 1))
    done
    selfcheck_appcenter_route_matches "luci-app-adguardhome" "admin/services/AdGuardHome" || adg_selfcheck_failures=$((adg_selfcheck_failures + 1))
    if selfcheck_luci_route_ok_when_ready "admin/services/AdGuardHome" /usr/lib/lua/luci/controller/AdGuardHome.lua; then
        route_rc='0'
    else
        route_rc="$?"
    fi
    [ "$route_rc" = '0' ] || [ "$route_rc" = '2' ] || adg_selfcheck_failures=$((adg_selfcheck_failures + 1))
    if selfcheck_luci_route_ok_when_ready "admin/services/AdGuardHome/base" /usr/lib/lua/luci/controller/AdGuardHome.lua /usr/lib/lua/luci/model/cbi/AdGuardHome/base.lua; then
        route_rc='0'
    else
        route_rc="$?"
    fi
    [ "$route_rc" = '0' ] || [ "$route_rc" = '2' ] || adg_selfcheck_failures=$((adg_selfcheck_failures + 1))
    if selfcheck_luci_route_ok_when_ready "admin/services/AdGuardHome/manual" /usr/lib/lua/luci/controller/AdGuardHome.lua /usr/lib/lua/luci/model/cbi/AdGuardHome/manual.lua; then
        route_rc='0'
    else
        route_rc="$?"
    fi
    [ "$route_rc" = '0' ] || [ "$route_rc" = '2' ] || adg_selfcheck_failures=$((adg_selfcheck_failures + 1))
    if selfcheck_luci_route_ok_when_ready "admin/services/AdGuardHome/log" /usr/lib/lua/luci/controller/AdGuardHome.lua /usr/lib/lua/luci/model/cbi/AdGuardHome/log.lua; then
        route_rc='0'
    else
        route_rc="$?"
    fi
    [ "$route_rc" = '0' ] || [ "$route_rc" = '2' ] || adg_selfcheck_failures=$((adg_selfcheck_failures + 1))

    if [ "$adg_core_present" = '1' ]; then
        adg_version="$("$adg_binpath" --version 2>/dev/null | sed -n '1p' | tr -d '\r' || true)"
        [ -n "$adg_version" ] && log "核心:     $adg_version"
    else
        log "核心:     missing (LuCI-only install)"
    fi

    if [ -s "$adg_configpath" ]; then
        if is_adguard_placeholder_config "$adg_configpath"; then
            log "config:   placeholder config detected"
            adg_selfcheck_warnings=$((adg_selfcheck_warnings + 1))
        else
            log "config:   initialized config detected"
        fi
    else
        log "config:   config missing, first-run setup pending"
        adg_selfcheck_warnings=$((adg_selfcheck_warnings + 1))
    fi

    if [ "$adg_core_present" = '1' ]; then
        adg_ps="$(pgrep -af 'AdGuardHome' 2>/dev/null || true)"
        selfcheck_print_process_state "AdGuardHome" 'AdGuardHome'
        [ -n "$adg_ps" ] || adg_selfcheck_failures=$((adg_selfcheck_failures + 1))
    else
        log "runtime:  AdGuardHome core not installed"
    fi

    selfcheck_finalize_summary "$adg_selfcheck_failures" "$adg_selfcheck_warnings"
}

run_ttyd_webssh_selfcheck() {
    require_root
    selfcheck_print_header "Web SSH / ttyd 自检"

    ttyd_selfcheck_failures=0
    ttyd_selfcheck_warnings=0
    ttyd_present='0'
    ttyd_port="$(get_ttyd_bind_value "port")"
    [ -n "$ttyd_port" ] || ttyd_port='7681'
    ttyd_iface="$(get_ttyd_bind_value "interface")"
    [ -n "$ttyd_iface" ] || ttyd_iface='all'

    for ttyd_path in \
        /usr/bin/ttyd \
        /etc/init.d/ttyd \
        /etc/config/ttyd \
        /usr/lib/lua/luci/controller/ttyd.lua \
        /usr/lib/lua/luci/view/ttyd/overview.htm \
        /usr/lib/lua/luci/controller/nradio_adv/webssh.lua \
        /usr/lib/lua/luci/view/nradio_adv/webssh.htm; do
        [ -e "$ttyd_path" ] && ttyd_present='1'
    done
    if [ "$ttyd_present" != '1' ]; then
        log "插件:   Web SSH / ttyd = 未安装，跳过可选插件自检"
        log "summary:  SKIP (optional plugin not installed)"
        set_last_selfcheck_status SKIP 0 0
        return 0
    fi

    selfcheck_print_service_state "ttyd" "/etc/init.d/ttyd"
    selfcheck_print_file_state "ttyd binary" "/usr/bin/ttyd"
    selfcheck_print_file_state "ttyd init" "/etc/init.d/ttyd"
    selfcheck_print_file_state "ttyd config" "/etc/config/ttyd"
    selfcheck_print_file_state "ttyd controller" "/usr/lib/lua/luci/controller/ttyd.lua"
    selfcheck_print_file_state "ttyd overview" "/usr/lib/lua/luci/view/ttyd/overview.htm"
    selfcheck_print_file_state "Web SSH controller" "/usr/lib/lua/luci/controller/nradio_adv/webssh.lua"
    selfcheck_print_file_state "Web SSH view" "/usr/lib/lua/luci/view/nradio_adv/webssh.htm"
    selfcheck_print_file_state "Web SSH icon" "/www/luci-static/nradio/images/icon/webssh.svg"
    selfcheck_print_luci_route_state_when_ready "ttyd overview" "admin/system/ttyd/overview" /usr/lib/lua/luci/controller/ttyd.lua /usr/lib/lua/luci/view/ttyd/overview.htm
    selfcheck_print_luci_route_state_when_ready "Web SSH wrapper" "nradioadv/system/webssh" /usr/lib/lua/luci/controller/nradio_adv/webssh.lua /usr/lib/lua/luci/view/nradio_adv/webssh.htm
    [ -x /etc/init.d/ttyd ] || ttyd_selfcheck_failures=$((ttyd_selfcheck_failures + 1))
    if ! /etc/init.d/ttyd enabled >/dev/null 2>&1; then
        ttyd_selfcheck_warnings=$((ttyd_selfcheck_warnings + 1))
    fi
    ttyd_service_status="$( ( /etc/init.d/ttyd status 2>/dev/null || true ) | tr '\n' ' ' | sed 's/[[:space:]]\+/ /g; s/^ //; s/ $//' )"
    case "$ttyd_service_status" in
        *running*|1) ;;
        *) ttyd_selfcheck_failures=$((ttyd_selfcheck_failures + 1)) ;;
    esac
    for needed in \
        /usr/bin/ttyd \
        /etc/init.d/ttyd \
        /etc/config/ttyd \
        /usr/lib/lua/luci/controller/ttyd.lua \
        /usr/lib/lua/luci/view/ttyd/overview.htm \
        /usr/lib/lua/luci/controller/nradio_adv/webssh.lua \
        /usr/lib/lua/luci/view/nradio_adv/webssh.htm; do
        [ -f "$needed" ] || ttyd_selfcheck_failures=$((ttyd_selfcheck_failures + 1))
    done
    if selfcheck_luci_route_ok_when_ready "admin/system/ttyd/overview" /usr/lib/lua/luci/controller/ttyd.lua /usr/lib/lua/luci/view/ttyd/overview.htm; then
        route_rc='0'
    else
        route_rc="$?"
    fi
    [ "$route_rc" = '0' ] || [ "$route_rc" = '2' ] || ttyd_selfcheck_failures=$((ttyd_selfcheck_failures + 1))
    if selfcheck_luci_route_ok_when_ready "nradioadv/system/webssh" /usr/lib/lua/luci/controller/nradio_adv/webssh.lua /usr/lib/lua/luci/view/nradio_adv/webssh.htm; then
        route_rc='0'
    else
        route_rc="$?"
    fi
    [ "$route_rc" = '0' ] || [ "$route_rc" = '2' ] || ttyd_selfcheck_failures=$((ttyd_selfcheck_failures + 1))

    if grep -q 'name:"Web SSH"' "$TPL" 2>/dev/null && grep -q 'nradioadv/system/webssh' "$TPL" 2>/dev/null; then
        log "应用商店: Web SSH 快捷入口 = 正常"
    else
        log "应用商店: Web SSH 快捷入口 = 缺失"
        ttyd_selfcheck_failures=$((ttyd_selfcheck_failures + 1))
    fi

    if grep -q "frame.src.indexOf('/admin/vpn/easytier') === -1" "$TPL" 2>/dev/null \
        && grep -q "frame.src.indexOf('/nradioadv/system/webssh') === -1" "$TPL" 2>/dev/null \
        && grep -q "frame.src.indexOf('/nradioadv/system/ddnsgo') === -1" "$TPL" 2>/dev/null; then
        log "应用商店: Web SSH iframe 白名单 = 正常"
    else
        log "应用商店: Web SSH iframe 白名单 = 缺失"
        ttyd_selfcheck_failures=$((ttyd_selfcheck_failures + 1))
    fi

    if grep -q 'WEBSSH_EMBED_MODE' /usr/lib/lua/luci/view/nradio_adv/webssh.htm 2>/dev/null \
        && grep -q 'data-focus-toggle' /usr/lib/lua/luci/view/nradio_adv/webssh.htm 2>/dev/null; then
        log "Web SSH 页面: embed/focus 标记 = 正常"
    else
        log "Web SSH 页面: embed/focus 标记 = 缺失"
        ttyd_selfcheck_failures=$((ttyd_selfcheck_failures + 1))
    fi

    if grep -q 'function normalize_app_route(app_name, route)' "$TPL" 2>/dev/null \
        && grep -q 'embed=1' "$TPL" 2>/dev/null \
        && grep -q "app_name == 'Web SSH' && action == 'open' && route" "$TPL" 2>/dev/null; then
        log "应用商店: Web SSH embed/open 逻辑 = 正常"
    else
        log "应用商店: Web SSH embed/open 逻辑 = 缺失"
        ttyd_selfcheck_failures=$((ttyd_selfcheck_failures + 1))
    fi

    if grep -q "action == 'uninstall' && nradio_plugin_uninstall_action(app_name)" "$TPL" 2>/dev/null \
        && grep -q 'plugin_uninstall/start' "$TPL" 2>/dev/null \
        && grep -q 'plugin_uninstall/check' "$TPL" 2>/dev/null; then
        log "应用商店: Web SSH 异步卸载逻辑 = 正常"
    else
        log "应用商店: Web SSH 异步卸载逻辑 = 缺失"
        ttyd_selfcheck_warnings=$((ttyd_selfcheck_warnings + 1))
    fi

    if [ -f /www/luci-static/nradio/images/icon/webssh.svg ]; then
        log "图标:     Web SSH SVG = 正常"
    else
        log "图标:     Web SSH SVG = 缺失"
        ttyd_selfcheck_warnings=$((ttyd_selfcheck_warnings + 1))
    fi

    if [ -x /usr/bin/ttyd ]; then
        ttyd_version="$(/usr/bin/ttyd -v 2>/dev/null | sed -n '1p' | tr -d '\r' || true)"
        [ -n "$ttyd_version" ] && log "核心:     $ttyd_version"
    fi

    if command -v ss >/dev/null 2>&1; then
        if ss -lnt 2>/dev/null | grep -q ":$ttyd_port[[:space:]]"; then
            log "listen:   port $ttyd_port is listening"
        else
            log "listen:   port $ttyd_port is not listening"
            ttyd_selfcheck_failures=$((ttyd_selfcheck_failures + 1))
        fi
    elif command -v netstat >/dev/null 2>&1; then
        if netstat -lnt 2>/dev/null | grep -q ":$ttyd_port[[:space:]]"; then
            log "listen:   port $ttyd_port is listening"
        else
            log "listen:   port $ttyd_port is not listening"
            ttyd_selfcheck_failures=$((ttyd_selfcheck_failures + 1))
        fi
    else
        log "listen:   socket probe unavailable"
        ttyd_selfcheck_warnings=$((ttyd_selfcheck_warnings + 1))
    fi

    if [ "$ttyd_iface" != 'all' ] && [ -n "$ttyd_iface" ] && ! ip link show "$ttyd_iface" >/dev/null 2>&1; then
        ttyd_selfcheck_failures=$((ttyd_selfcheck_failures + 1))
    fi

    log "bind:     interface=$ttyd_iface port=$ttyd_port"
    ttyd_ps="$(pgrep -af 'ttyd' 2>/dev/null || true)"
    selfcheck_print_process_state "ttyd" 'ttyd'
    [ -n "$ttyd_ps" ] || ttyd_selfcheck_failures=$((ttyd_selfcheck_failures + 1))

    selfcheck_finalize_summary "$ttyd_selfcheck_failures" "$ttyd_selfcheck_warnings"
}

