    if [ -x /etc/init.d/zerotier ]; then
        /etc/init.d/zerotier enabled >/dev/null 2>&1 || zerotier_selfcheck_warnings=$((zerotier_selfcheck_warnings + 1))
        zerotier_service_status="$( ( /etc/init.d/zerotier status 2>/dev/null || true ) | tr '\n' ' ' | sed 's/[[:space:]]\+/ /g; s/^ //; s/ $//' )"
        case "$zerotier_service_status" in
            *running*|1) ;;
            *) zerotier_selfcheck_warnings=$((zerotier_selfcheck_warnings + 1)) ;;
        esac
    fi

    if command -v zerotier-cli >/dev/null 2>&1; then
        zerotier_info="$(zerotier-cli info 2>/dev/null | sed -n '1p' | tr -d '\r' || true)"
        [ -n "$zerotier_info" ] && log "核心:     $zerotier_info"
    fi

    selfcheck_print_process_state "ZeroTier" 'zerotier-one'
    pgrep -af 'zerotier-one' >/dev/null 2>&1 || zerotier_selfcheck_warnings=$((zerotier_selfcheck_warnings + 1))

    selfcheck_finalize_summary "$zerotier_selfcheck_failures" "$zerotier_selfcheck_warnings"
}

run_easytier_selfcheck() {
    require_root
    selfcheck_print_header "$EASYTIER_DISPLAY_NAME 自检"

    easytier_selfcheck_failures=0
    easytier_selfcheck_warnings=0
    easytier_core_bin="$(uci -q get easytier.@easytier[0].easytierbin 2>/dev/null || true)"
    [ -n "$easytier_core_bin" ] || easytier_core_bin="/usr/bin/easytier-core"
    easytier_present='0'

    for easytier_path in \
        /etc/init.d/easytier \
        /etc/config/easytier \
        "$EASYTIER_CONTROLLER" \
        /usr/lib/lua/luci/model/cbi/easytier.lua \
        /usr/lib/lua/luci/view/easytier/easytier_status.htm \
        /usr/bin/easytier-core \
        /usr/bin/easytier-cli \
        /usr/bin/easytier-web; do
        [ -e "$easytier_path" ] && easytier_present='1'
    done
    if [ "$easytier_present" != '1' ]; then
        log "插件:   $EASYTIER_DISPLAY_NAME = 未安装，跳过可选插件自检"
        log "summary:  SKIP (optional plugin not installed)"
        set_last_selfcheck_status SKIP 0 0
        return 0
    fi

    selfcheck_print_service_state "easytier" "/etc/init.d/easytier"
    selfcheck_print_file_state "easytier config" "/etc/config/easytier"
    selfcheck_print_file_state "easytier controller" "$EASYTIER_CONTROLLER"
    selfcheck_print_file_state "easytier cbi" "/usr/lib/lua/luci/model/cbi/easytier.lua"
    selfcheck_print_file_state "easytier status view" "/usr/lib/lua/luci/view/easytier/easytier_status.htm"
    selfcheck_print_file_state "easytier core" "$easytier_core_bin"
    selfcheck_print_file_state "easytier cli" "/usr/bin/easytier-cli"
    selfcheck_print_file_state "easytier web" "/usr/bin/easytier-web"
    selfcheck_print_appcenter_route_state "$EASYTIER_DISPLAY_NAME" "$EASYTIER_DISPLAY_NAME" "$EASYTIER_ROUTE"
    selfcheck_print_luci_route_state_when_ready "$EASYTIER_DISPLAY_NAME page" "$EASYTIER_ROUTE" "$EASYTIER_CONTROLLER"

    [ -x /etc/init.d/easytier ] || easytier_selfcheck_failures=$((easytier_selfcheck_failures + 1))
    for needed in \
        /etc/config/easytier \
        "$EASYTIER_CONTROLLER" \
        /usr/lib/lua/luci/model/cbi/easytier.lua \
        /usr/lib/lua/luci/view/easytier/easytier_status.htm \
        /usr/bin/easytier-core \
        /usr/bin/easytier-cli \
        /usr/bin/easytier-web; do
        [ -f "$needed" ] || easytier_selfcheck_failures=$((easytier_selfcheck_failures + 1))
    done
    selfcheck_appcenter_route_matches "$EASYTIER_DISPLAY_NAME" "$EASYTIER_ROUTE" || easytier_selfcheck_failures=$((easytier_selfcheck_failures + 1))
    if selfcheck_luci_route_ok_when_ready "$EASYTIER_ROUTE" "$EASYTIER_CONTROLLER"; then
        route_rc='0'
    else
        route_rc="$?"
    fi
    [ "$route_rc" = '0' ] || [ "$route_rc" = '2' ] || easytier_selfcheck_failures=$((easytier_selfcheck_failures + 1))

    if [ -x /etc/init.d/easytier ]; then
        /etc/init.d/easytier enabled >/dev/null 2>&1 || easytier_selfcheck_warnings=$((easytier_selfcheck_warnings + 1))
        easytier_service_status="$( ( /etc/init.d/easytier status 2>/dev/null || true ) | tr '\n' ' ' | sed 's/[[:space:]]\+/ /g; s/^ //; s/ $//' )"
        case "$easytier_service_status" in
            *running*|1) ;;
            *) easytier_selfcheck_warnings=$((easytier_selfcheck_warnings + 1)) ;;
        esac
    fi

    if [ -x "$easytier_core_bin" ]; then
        easytier_version_text="$("$easytier_core_bin" -V 2>/dev/null | sed -n '1p' | tr -d '\r' || true)"
        [ -n "$easytier_version_text" ] || easytier_version_text="$("$easytier_core_bin" --version 2>/dev/null | sed -n '1p' | tr -d '\r' || true)"
        [ -n "$easytier_version_text" ] && log "核心:     $easytier_version_text"
    fi

    selfcheck_print_process_state "$EASYTIER_DISPLAY_NAME core" 'easytier-core'
    selfcheck_print_process_state "$EASYTIER_DISPLAY_NAME web" 'easytier-web'
    pgrep -af 'easytier-core' >/dev/null 2>&1 || easytier_selfcheck_warnings=$((easytier_selfcheck_warnings + 1))
    pgrep -af 'easytier-web' >/dev/null 2>&1 || easytier_selfcheck_warnings=$((easytier_selfcheck_warnings + 1))

    selfcheck_finalize_summary "$easytier_selfcheck_failures" "$easytier_selfcheck_warnings"
}

run_openlist_cdn_selfcheck() {
    openlist_probe_urls="$(build_openlist_download_urls 2>/dev/null || true)"
    if [ -z "$openlist_probe_urls" ]; then
        log "CDN:      OpenList = 下载地址解析失败"
        set_last_selfcheck_status FAIL 1 0
        return 0
    fi

    rank_url_list_hosts "openlist-unified" "OpenList GitHub 下载源" "$OPENLIST_GITHUB_OFFICIAL_PROBE_URLS" "$openlist_probe_urls"
    if [ -n "${RANKED_URL_HOSTS:-}" ]; then
        log "CDN:      OpenList = $RANKED_URL_HOSTS"
        set_last_selfcheck_status PASS 0 0
    else
        log "CDN:      OpenList = 未得出排序"
        set_last_selfcheck_status WARN 0 1
    fi
}

run_easytier_cdn_selfcheck() {
    easytier_probe_urls="$(build_easytier_download_urls 2>/dev/null || true)"
    if [ -z "$easytier_probe_urls" ]; then
        log "CDN:      $EASYTIER_DISPLAY_NAME = 下载地址解析失败"
        set_last_selfcheck_status FAIL 1 0
        return 0
    fi

    rank_url_list_hosts "easytier-unified" "$EASYTIER_DISPLAY_NAME GitHub 下载源" "$EASYTIER_GITHUB_OFFICIAL_PROBE_URLS" "$easytier_probe_urls"
    if [ -n "${RANKED_URL_HOSTS:-}" ]; then
        log "CDN:      $EASYTIER_DISPLAY_NAME = $RANKED_URL_HOSTS"
        set_last_selfcheck_status PASS 0 0
    else
        log "CDN:      $EASYTIER_DISPLAY_NAME = 未得出排序"
        set_last_selfcheck_status WARN 0 1
    fi
}

run_feed_package_cdn_selfcheck() {
    probe_label="$1"
    probe_package="$2"
    probe_prefix="$3"

    if [ ! -f "$FEEDS" ]; then
        log "CDN:      $probe_label = 软件源文件缺失"
        set_last_selfcheck_status FAIL 1 0
        return 0
    fi

    probe_meta="$(resolve_package_meta_any_feed "$probe_package" 2>/dev/null || true)"
    if [ -z "$probe_meta" ]; then
        log "CDN:      $probe_label = 无法从当前软件源解析"
        set_last_selfcheck_status FAIL 1 0
        return 0
    fi

    probe_feed_name="${probe_meta%%|*}"
    probe_meta_rest="${probe_meta#*|}"
    probe_feed_url="${probe_meta_rest%%|*}"
    probe_meta_rest="${probe_meta_rest#*|}"
    probe_filename="${probe_meta_rest%%|*}"
    probe_urls="$(build_package_download_urls_from_meta "$probe_feed_url" "$probe_filename" 2>/dev/null || true)"
    if [ -z "$probe_urls" ]; then
        log "CDN:      $probe_label = 下载地址生成失败（$probe_feed_name）"
        set_last_selfcheck_status FAIL 1 0
        return 0
    fi

    rank_url_list_hosts "$probe_prefix" "$probe_label" "$probe_urls"
    if [ -n "${RANKED_URL_HOSTS:-}" ]; then
        refine_ranked_hosts_by_http_probe "$probe_prefix" "$probe_label" "$RANKED_URL_HOSTS" "$probe_urls"
        log "CDN:      $probe_label = $RANKED_URL_HOSTS (feed=$probe_feed_name)"
        set_last_selfcheck_status PASS 0 0
    else
        log "CDN:      $probe_label = 未得出排序（feed=$probe_feed_name)"
        set_last_selfcheck_status WARN 0 1
    fi
}

unified_num_or_zero() {
    case "${1:-}" in
        ''|*[!0-9]*)
            printf '%s\n' '0'
            ;;
        *)
            printf '%s\n' "$1"
            ;;
    esac
}

unified_health_mem_kib() {
    mem_key="$1"
    awk -v key="$mem_key" '$1 == key ":" { print $2; exit }' /proc/meminfo 2>/dev/null || true
}

unified_health_kib_display() {
    kib_value="$(unified_num_or_zero "${1:-}")"
    mib_value="$(( (kib_value + 1023) / 1024 ))"
    format_mib_or_gib "$mib_value" 2>/dev/null || printf '%sM' "$mib_value"
}

unified_health_path_free_kib() {
    target_path="$1"
    [ -e "$target_path" ] || return 1
    df -kP "$target_path" 2>/dev/null | awk 'NR == 2 { print $4; exit }'
}

unified_health_mount_type() {
    mount_path="$1"
    awk -v path="$mount_path" '$2 == path { print $3; exit }' /proc/mounts 2>/dev/null || true
}

unified_health_print_path_usage() {
    path_label="$1"
    target_path="$2"
    [ -e "$target_path" ] || {
        log "存储:   $path_label = 不存在 ($target_path)"
        return 1
    }

    df_line="$(df -kP "$target_path" 2>/dev/null | awk 'NR == 2 { print $2 "|" $3 "|" $4 "|" $5 "|" $6; exit }' || true)"
    [ -n "$df_line" ] || {
        log "存储:   $path_label = 无法读取 ($target_path)"
        return 1
    }

    df_total_kib="${df_line%%|*}"
    df_rest="${df_line#*|}"
    df_used_kib="${df_rest%%|*}"
    df_rest="${df_rest#*|}"
    df_avail_kib="${df_rest%%|*}"
    df_rest="${df_rest#*|}"
    df_used_pct="${df_rest%%|*}"
    df_mount="${df_rest#*|}"
    df_type="$(unified_health_mount_type "$df_mount")"
    [ -n "$df_type" ] || df_type='未知'

    if [ -w "$target_path" ]; then
        writable_state='可写'
    else
        writable_state='不可写'
    fi

    log "存储:   $path_label = 可用 $(unified_health_kib_display "$df_avail_kib") / 总 $(unified_health_kib_display "$df_total_kib") (${df_used_pct:-?} 已用, mount=$df_mount, type=$df_type, $writable_state)"
}

unified_detect_model_name() {
    if [ -n "${CURRENT_DETECTED_MODEL:-}" ]; then
        printf '%s\n' "$CURRENT_DETECTED_MODEL"
        return 0
    fi
    normalize_nradio_model "$(detect_board_model_raw)" "$(detect_board_name_raw)" "$(detect_board_compatible_raw)"
}

unified_detect_arch_name() {
    arch_name="$(opkg print-architecture 2>/dev/null | awk '$1 == "arch" && $2 != "all" { print $2; exit }' || true)"
    [ -n "$arch_name" ] || arch_name="$(uname -m 2>/dev/null || true)"
    printf '%s\n' "${arch_name:-未知}"
}

unified_first_dns_servers() {
    for dns_file in /tmp/resolv.conf.d/resolv.conf.auto /tmp/resolv.conf.auto /etc/resolv.conf; do
        [ -f "$dns_file" ] || continue
        dns_text="$(awk '$1 == "nameserver" && $2 != "" { print $2 }' "$dns_file" 2>/dev/null | sed -n '1,3p' | tr '\n' ' ' | sed 's/[[:space:]]\+/ /g; s/^ //; s/ $//' || true)"
        [ -n "$dns_text" ] && {
            printf '%s\n' "$dns_text"
            return 0
        }
    done
    printf '%s\n' ''
}

unified_default_gateway_summary() {
    ip route show default 2>/dev/null | sed -n '1,3p' | tr '\n' ';' | sed 's/;$/ /; s/[[:space:]]\+/ /g; s/^ //; s/ $//' || true
}

unified_default_gateway_ip() {
    ip route show default 2>/dev/null | awk '
        /^default / {
            for (i = 1; i <= NF; i++) {
                if ($i == "via" && (i + 1) <= NF) {
                    print $(i + 1)
                    exit
                }
            }
        }
    ' || true
}

unified_first_enabled_feed_url() {
    awk '$1 == "src/gz" && $3 != "" { print $3; exit }' "$FEEDS" 2>/dev/null || true
}

unified_network_warn() {
    log "$1"
    UNIFIED_NETWORK_WARNINGS=$((UNIFIED_NETWORK_WARNINGS + 1))
}

unified_ping_probe() {
    ping_label="$1"
    ping_host="$2"
    ping_warn="${3:-warn}"

    [ -n "$ping_host" ] || {
        if [ "$ping_warn" = 'warn' ]; then
            unified_network_warn "网络:   $ping_label ping = 无目标"
        else
            log "网络:   $ping_label ping = 无目标"
        fi
        return 0
    }
    if ! command -v ping >/dev/null 2>&1; then
        if [ "$ping_warn" = 'warn' ]; then
            unified_network_warn "网络:   $ping_label ping = 缺少 ping"
        else
            log "网络:   $ping_label ping = 缺少 ping"
        fi
        return 0
    fi
    if ping -c 1 -W 2 "$ping_host" >/dev/null 2>&1; then
        log "网络:   $ping_label ping = 可达 ($ping_host)"
    else
        if [ "$ping_warn" = 'warn' ]; then
            unified_network_warn "网络:   $ping_label ping = 不通 ($ping_host)"
        else
            log "网络:   $ping_label ping = 不通或禁 ICMP ($ping_host)"
        fi
    fi
}

unified_dns_probe() {
    dns_label="$1"
    dns_host="$2"
    dns_addr=""

    if command -v nslookup >/dev/null 2>&1; then
        dns_addr="$(nslookup "$dns_host" 2>/dev/null | awk '
            /^Name:/ { seen = 1; next }
            seen && /^Address[[:space:]]+[0-9]+:/ { print $3; exit }
            seen && /^Address[[:space:]]/ { print $2; exit }
        ' || true)"
    fi
    if [ -z "$dns_addr" ] && command -v ping >/dev/null 2>&1; then
        dns_addr="$(ping -c 1 -W 2 "$dns_host" 2>/dev/null | awk -F'[()]' '/^PING / { print $2; exit }' || true)"
    fi

    if [ -n "$dns_addr" ]; then
        log "DNS:    $dns_label = $dns_addr"
    else
        unified_network_warn "DNS:    $dns_label = 解析失败"
    fi
}

unified_http_probe() {
    http_label="$1"
    http_url="$2"
    http_warn="${3:-warn}"
    http_host="$(extract_url_host "$http_url" 2>/dev/null || true)"

    [ -n "$http_url" ] || {
        if [ "$http_warn" = 'warn' ]; then
            unified_network_warn "HTTP:   $http_label = 无目标"
        else
            log "HTTP:   $http_label = 无目标"
        fi
        return 0
    }
    if ! command -v curl >/dev/null 2>&1; then
        if [ "$http_warn" = 'warn' ]; then
            unified_network_warn "HTTP:   $http_label = 缺少 curl"
        else
            log "HTTP:   $http_label = 缺少 curl"
        fi
        return 0
    fi

    http_out="$(curl -L -I -o /dev/null -sS --connect-timeout 5 --max-time 8 -w '%{http_code}|%{time_starttransfer}' "$http_url" 2>/dev/null || true)"
    http_code="${http_out%%|*}"
    http_time="${http_out#*|}"
    if [ -z "$http_code" ] || [ "$http_code" = '000' ] || [ "$http_code" = "$http_out" ]; then
        http_out="$(curl -L -o /dev/null -sS --connect-timeout 5 --max-time 8 -w '%{http_code}|%{time_starttransfer}' "$http_url" 2>/dev/null || true)"
        http_code="${http_out%%|*}"
        http_time="${http_out#*|}"
    fi
    http_ms="$(printf '%s\n' "$http_time" | awk '$1 ~ /^[0-9.]+$/ { printf "%dms\n", ($1 * 1000) + 0.5 }' 2>/dev/null || true)"
    [ -n "$http_ms" ] || http_ms='?'

    case "$http_code" in
        200|204|301|302|307|308|403)
            log "HTTP:   $http_label = HTTP $http_code ${http_ms} host=${http_host:-未知}"
            ;;
        *)
            if [ "$http_warn" = 'warn' ]; then
                unified_network_warn "HTTP:   $http_label = 异常或超时 HTTP ${http_code:-000} host=${http_host:-未知}"
            else
                log "HTTP:   $http_label = 旁路探测异常 HTTP ${http_code:-000} host=${http_host:-未知}"
            fi
            ;;
    esac
}

run_unified_network_path_check() {
    UNIFIED_NETWORK_WARNINGS=0
    gateway_ip="$(unified_default_gateway_ip)"
    feed_url="$(unified_first_enabled_feed_url)"

    selfcheck_print_header "网络出口快测"
    unified_ping_probe "默认网关" "$gateway_ip" "info"
    unified_dns_probe "github.com" "github.com"
    unified_dns_probe "阿里云镜像" "mirrors.aliyun.com"
    unified_http_probe "GitHub" "https://github.com/"
    if [ -n "$feed_url" ]; then
        unified_http_probe "当前首个软件源" "$feed_url/Packages"
    else
        unified_network_warn "HTTP:   当前首个软件源 = 未找到启用源"
    fi
    unified_http_probe "OpenWrt 官方" "https://downloads.openwrt.org/" "info"

    if [ "$UNIFIED_NETWORK_WARNINGS" -gt 0 ]; then
        set_last_selfcheck_status WARN 0 "$UNIFIED_NETWORK_WARNINGS"
    else
        set_last_selfcheck_status PASS 0 0
    fi
}

unified_outlet_iface_summary() {
    outlet_dev="$1"
    [ -n "$outlet_dev" ] || return 0
    [ -d "/sys/class/net/$outlet_dev" ] || return 0

    outlet_state="$(cat "/sys/class/net/$outlet_dev/operstate" 2>/dev/null || true)"
    [ -n "$outlet_state" ] || outlet_state='unknown'
    outlet_ipv4="$(ip -4 addr show dev "$outlet_dev" 2>/dev/null | awk '/inet / { print $2; exit }' || true)"
    outlet_ipv6_global="$(ip -6 addr show dev "$outlet_dev" 2>/dev/null | awk '/inet6 / && $0 !~ / scope link / { print $2; exit }' || true)"
    outlet_ipv6_link="$(ip -6 addr show dev "$outlet_dev" 2>/dev/null | awk '/inet6 / && $0 ~ / scope link / { print $2; exit }' || true)"

    log "出口:   dev=$outlet_dev state=$outlet_state ipv4=${outlet_ipv4:-无} ipv6_global=${outlet_ipv6_global:-无} ipv6_link=${outlet_ipv6_link:-无}"
}

unified_ifstatus_summary() {
    outlet_iface="$1"
    [ -n "$outlet_iface" ] || return 0
    command -v ifstatus >/dev/null 2>&1 || return 0

    ifstatus_text="$(ifstatus "$outlet_iface" 2>/dev/null || true)"
    [ -n "$ifstatus_text" ] || return 0
    iface_up="$(printf '%s\n' "$ifstatus_text" | sed -n 's/^[[:space:]]*"up":[[:space:]]*\(true\|false\).*/\1/p' | sed -n '1p')"
    iface_pending="$(printf '%s\n' "$ifstatus_text" | sed -n 's/^[[:space:]]*"pending":[[:space:]]*\(true\|false\).*/\1/p' | sed -n '1p')"
    iface_proto="$(printf '%s\n' "$ifstatus_text" | sed -n 's/^[[:space:]]*"proto":[[:space:]]*"\([^"]*\)".*/\1/p' | sed -n '1p')"
    iface_device="$(printf '%s\n' "$ifstatus_text" | sed -n 's/^[[:space:]]*"device":[[:space:]]*"\([^"]*\)".*/\1/p' | sed -n '1p')"
    log "ifstatus: $outlet_iface up=${iface_up:-?} pending=${iface_pending:-?} proto=${iface_proto:-?} device=${iface_device:-?}"
}

run_unified_nros_outlet_health_check() {
    outlet_warnings=0
    outlet_v4_defaults="$(ip -4 route show default 2>/dev/null | sed -n '1,3p' || true)"
    outlet_v6_defaults="$(ip -6 route show default 2>/dev/null | sed -n '1,3p' || true)"
    outlet_devs="$( { ip -4 route show default 2>/dev/null; ip -6 route show default 2>/dev/null; } | awk '{ for (i = 1; i <= NF; i++) if ($i == "dev" && (i + 1) <= NF) print $(i + 1) }' | awk '!seen[$0]++' || true )"
    outlet_need_v6='0'
    outlet_global_v6="$(ip -6 addr show 2>/dev/null | awk '/inet6 / && $0 !~ / scope link / && $0 !~ / ::1/ { print $2; exit }' || true)"

    selfcheck_print_header "NROS 网络与 IPv6 检查"
    if [ -n "$outlet_v4_defaults" ]; then
        printf '%s\n' "$outlet_v4_defaults" | sed 's/^/IPv4默认: /'
    else
        log "IPv4默认: 缺失"
        outlet_warnings=$((outlet_warnings + 1))
    fi

    if [ -n "$outlet_v6_defaults" ]; then
        printf '%s\n' "$outlet_v6_defaults" | sed 's/^/IPv6默认: /'
    else
        log "IPv6默认: 缺失"
    fi

    if awk '$1=="proto" && ($2=="udp6" || $2=="tcp6" || $2=="tcp6-client") { found=1 } END { exit found ? 0 : 1 }' /etc/openvpn/client.ovpn 2>/dev/null; then
        outlet_need_v6='1'
    fi
    if [ "$outlet_need_v6" = '1' ] && [ -z "$outlet_v6_defaults" ]; then
        log "IPv6诊断: OpenVPN 当前使用 IPv6 transport，但系统无 IPv6 default route"
        outlet_warnings=$((outlet_warnings + 1))
    elif [ -n "$outlet_global_v6" ] && [ -z "$outlet_v6_defaults" ]; then
        log "IPv6诊断: 存在全局 IPv6 地址但无 IPv6 default route"
        outlet_warnings=$((outlet_warnings + 1))
    fi

    for candidate_dev in cpe1 cpe1_4 cpe1_6 port5 eth1 wwan0 usb0; do
        [ -d "/sys/class/net/$candidate_dev" ] || continue
        printf '%s\n' "$outlet_devs" | grep -Fx "$candidate_dev" >/dev/null 2>&1 && continue
        outlet_devs="$(printf '%s\n%s\n' "$outlet_devs" "$candidate_dev" | sed '/^$/d' | awk '!seen[$0]++')"
    done
    if [ -n "$outlet_devs" ]; then
        for outlet_dev in $outlet_devs; do
            unified_outlet_iface_summary "$outlet_dev"
        done
    else
        log "出口:   未发现默认路由接口"
        outlet_warnings=$((outlet_warnings + 1))
    fi

    for outlet_iface in wan wan6 cpe1 cpe1_4 cpe1_6; do
        unified_ifstatus_summary "$outlet_iface"
    done

    if [ "$outlet_warnings" -gt 0 ]; then
        set_last_selfcheck_status WARN 0 "$outlet_warnings"
    else
        set_last_selfcheck_status PASS 0 0
    fi
}

nradio_5g_aggregation_current_model() {
    if [ -n "${CURRENT_DETECTED_MODEL:-}" ]; then
        printf '%s\n' "$CURRENT_DETECTED_MODEL"
        return 0
    fi

    normalize_nradio_model "$(detect_board_model_raw)" "$(detect_board_name_raw)" "$(detect_board_compatible_raw)" 2>/dev/null || true
}

nradio_5g_aggregation_model_supported() {
    case "$(nradio_5g_aggregation_current_model 2>/dev/null || true)" in
        NRadio_C5800-650|NRadio_C5800-688|NRadio_C8-688)
            return 0
            ;;
        *)
            return 1
            ;;
    esac
}

nradio_5g_aggregation_ifstatus_field() {
    agg_text="$1"
    agg_field="$2"

    printf '%s\n' "$agg_text" | sed -n "s/^[[:space:]]*\"$agg_field\":[[:space:]]*\"\([^\"]*\)\".*/\1/p" | sed -n '1p'
}

nradio_5g_aggregation_ifstatus_bool() {
    agg_text="$1"
    agg_field="$2"

    printf '%s\n' "$agg_text" | sed -n "s/^[[:space:]]*\"$agg_field\":[[:space:]]*\(true\|false\).*/\1/p" | sed -n '1p'
}

nradio_5g_aggregation_ifstatus_summary() {
    agg_iface="$1"
    agg_ifstatus_text=''
    agg_up=''
    agg_pending=''
    agg_proto=''
    agg_device=''

    command -v ifstatus >/dev/null 2>&1 || {
        log "ifstatus: 缺少 ifstatus 命令"
        return 1
    }

    agg_ifstatus_text="$(ifstatus "$agg_iface" 2>/dev/null || true)"
    if [ -z "$agg_ifstatus_text" ]; then
        log "ifstatus: $agg_iface = 无返回"
        return 1
    fi

    agg_up="$(nradio_5g_aggregation_ifstatus_bool "$agg_ifstatus_text" up)"
    agg_pending="$(nradio_5g_aggregation_ifstatus_bool "$agg_ifstatus_text" pending)"
    agg_proto="$(nradio_5g_aggregation_ifstatus_field "$agg_ifstatus_text" proto)"
    agg_device="$(nradio_5g_aggregation_ifstatus_field "$agg_ifstatus_text" device)"
    log "ifstatus: $agg_iface up=${agg_up:-?} pending=${agg_pending:-?} proto=${agg_proto:-?} device=${agg_device:-?}"
}

nradio_5g_aggregation_iface_abnormal() {
    agg_iface="$1"
    agg_ifstatus_text="$(ifstatus "$agg_iface" 2>/dev/null || true)"
    [ -n "$agg_ifstatus_text" ] || return 1

    agg_up="$(nradio_5g_aggregation_ifstatus_bool "$agg_ifstatus_text" up)"
    agg_pending="$(nradio_5g_aggregation_ifstatus_bool "$agg_ifstatus_text" pending)"
    [ "$agg_up" = 'true' ] && [ "$agg_pending" != 'true' ] && return 1
    return 0
}

nradio_5g_aggregation_dev_summary() {
    agg_dev="$1"
    [ -d "/sys/class/net/$agg_dev" ] || {
        log "网口:   $agg_dev = 不存在"
        return 1
    }

    agg_state="$(cat "/sys/class/net/$agg_dev/operstate" 2>/dev/null || true)"
    agg_ipv4="$(ip -4 addr show dev "$agg_dev" 2>/dev/null | awk '/inet / { print $2; exit }' || true)"
    agg_ipv6_global="$(ip -6 addr show dev "$agg_dev" 2>/dev/null | awk '/inet6 / && $0 !~ / scope link / { print $2; exit }' || true)"
    agg_ipv6_link="$(ip -6 addr show dev "$agg_dev" 2>/dev/null | awk '/inet6 / && $0 ~ / scope link / { print $2; exit }' || true)"
    log "网口:   $agg_dev state=${agg_state:-unknown} ipv4=${agg_ipv4:-无} ipv6_global=${agg_ipv6_global:-无} ipv6_link=${agg_ipv6_link:-无}"
}

nradio_5g_aggregation_service_summary() {
    agg_label="$1"
    agg_init="$2"
    agg_config="$3"

    if [ -x "$agg_init" ]; then
        agg_status="$( ( "$agg_init" status 2>/dev/null || true ) | tr '\n' ' ' | sed 's/[[:space:]]\+/ /g; s/^ //; s/ $//' || true)"
        log "服务:   $agg_label = ${agg_status:-已安装，状态未知}"
        return 0
    fi

    if [ -n "$agg_config" ] && [ -e "$agg_config" ]; then
        log "服务:   $agg_label = 有配置，未发现 init 脚本"
        return 0
    fi

    log "服务:   $agg_label = 未安装"
}

nradio_5g_aggregation_mwan_members_for_iface() {
    agg_iface="$1"
    command -v uci >/dev/null 2>&1 || return 1
    uci -q show mwan3 2>/dev/null | sed -n "s/^mwan3\.\([^.=]*\)\.interface='$agg_iface'$/\1/p"
}

nradio_5g_aggregation_print_mwan_weight() {
    agg_iface="$1"
    agg_members="$(nradio_5g_aggregation_mwan_members_for_iface "$agg_iface" 2>/dev/null || true)"

    if [ -z "$agg_members" ]; then
        log "mwan3权重: $agg_iface = 未找到 member"
        return 1
    fi

    for agg_member in $agg_members; do
        agg_weight="$(uci -q get "mwan3.${agg_member}.weight" 2>/dev/null || true)"
        agg_metric="$(uci -q get "mwan3.${agg_member}.metric" 2>/dev/null || true)"
        log "mwan3权重: $agg_iface member=$agg_member metric=${agg_metric:-?} weight=${agg_weight:-?}"
    done
}

nradio_5g_aggregation_print_mwan_status() {
    if ! command -v mwan3 >/dev/null 2>&1; then
        log "mwan3:  未安装或命令不可用"
        return 1
    fi

    agg_mwan_status="$(mwan3 status 2>/dev/null || true)"
    if [ -z "$agg_mwan_status" ]; then
        log "mwan3:  status 无返回"
        return 1
    fi

    printf '%s\n' "$agg_mwan_status" | sed -n '1,120p' | sed 's/^/mwan3:  /'

    if printf '%s\n' "$agg_mwan_status" | grep -F 'cpe_4 (' >/dev/null 2>&1 && printf '%s\n' "$agg_mwan_status" | grep -F 'cpe1_4 (' >/dev/null 2>&1; then
        log "IPv4聚合: 检测到 cpe_4 + cpe1_4，mwan3 多线策略存在"
    else
        log "IPv4聚合: 未同时检测到 cpe_4 + cpe1_4，IPv4 可能未按双线分流"
    fi

    if printf '%s\n' "$agg_mwan_status" | grep -F 'cpe_6 (' >/dev/null 2>&1 && printf '%s\n' "$agg_mwan_status" | grep -F 'cpe1_6 (' >/dev/null 2>&1; then
        log "IPv6聚合: 检测到 cpe_6 + cpe1_6"
    elif printf '%s\n' "$agg_mwan_status" | grep -F 'cpe_6 (' >/dev/null 2>&1 || printf '%s\n' "$agg_mwan_status" | grep -F 'cpe1_6 (' >/dev/null 2>&1; then
        log "IPv6聚合: 仅检测到一条 IPv6 线路，IPv6 不会双线叠加"
    else
        log "IPv6聚合: 未检测到 IPv6 聚合策略"
    fi
}

nradio_5g_aggregation_print_accelerator_state() {
    agg_flow="$(uci -q get firewall.@defaults[0].flow_offloading 2>/dev/null || true)"
    agg_hw_flow="$(uci -q get firewall.@defaults[0].flow_offloading_hw 2>/dev/null || true)"
    agg_sfe="$(uci -q get shortcut-fe.@shortcut-fe[0].enabled 2>/dev/null || true)"

    nradio_5g_aggregation_service_summary "$OPENCLASH_DISPLAY_NAME" /etc/init.d/openclash /etc/config/openclash
    nradio_5g_aggregation_service_summary "AdGuardHome" /etc/init.d/AdGuardHome /etc/config/AdGuardHome
    nradio_5g_aggregation_service_summary "QoS" /etc/init.d/qos /etc/config/qos
    nradio_5g_aggregation_service_summary "SQM" /etc/init.d/sqm /etc/config/sqm
    log "硬件加速: firewall.flow_offloading=${agg_flow:-未配置} flow_offloading_hw=${agg_hw_flow:-未配置} shortcut-fe=${agg_sfe:-未配置}"
}

nradio_5g_aggregation_restart_mwan() {
    if [ -x /etc/init.d/mwan3 ]; then
        log "mwan3:  重启 /etc/init.d/mwan3"
        /etc/init.d/mwan3 restart >/dev/null 2>&1 || return 1
    elif command -v mwan3 >/dev/null 2>&1; then
        log "mwan3:  重启 /usr/sbin/mwan3"
        mwan3 restart >/dev/null 2>&1 || return 1
    else
        log "mwan3:  未发现可用重启入口"
        return 1
    fi
}

nradio_5g_aggregation_print_diagnostics() {
    agg_model="$(nradio_5g_aggregation_current_model 2>/dev/null || true)"

    selfcheck_print_header "5G聚合修复检查"
    log "机型:   ${agg_model:-未知}"
    log "说明:   mwan3 是多连接负载均衡，不是单连接 bonding；测速建议使用 IPv4 多线程"

    if ! nradio_5g_aggregation_model_supported; then
        log "结果:   当前机型无 5G 聚合功能入口"
        return 0
    fi

    for agg_iface in cpe_4 cpe1_4 cpe_6 cpe1_6; do
        nradio_5g_aggregation_ifstatus_summary "$agg_iface"
    done

    for agg_dev in eth1 port5; do
        nradio_5g_aggregation_dev_summary "$agg_dev"
    done

    agg_v4_defaults="$(ip -4 route show default 2>/dev/null | sed -n '1,3p' || true)"
    agg_v6_defaults="$(ip -6 route show default 2>/dev/null | sed -n '1,3p' || true)"
    if [ -n "$agg_v4_defaults" ]; then
        printf '%s\n' "$agg_v4_defaults" | sed 's/^/IPv4默认: /'
    else
        log "IPv4默认: 缺失"
    fi
    if [ -n "$agg_v6_defaults" ]; then
        printf '%s\n' "$agg_v6_defaults" | sed 's/^/IPv6默认: /'
    else
        log "IPv6默认: 缺失"
    fi

    nradio_5g_aggregation_print_mwan_status
    nradio_5g_aggregation_print_mwan_weight cpe_4
    nradio_5g_aggregation_print_mwan_weight cpe1_4
    nradio_5g_aggregation_print_accelerator_state
}

nradio_5g_aggregation_restart_abnormal_ifaces() {
    agg_restarted='0'

    command -v ifdown >/dev/null 2>&1 || return 0
    command -v ifup >/dev/null 2>&1 || return 0
    command -v ifstatus >/dev/null 2>&1 || return 0

    for agg_iface in cpe_4 cpe1_4 cpe_6 cpe1_6; do
        if nradio_5g_aggregation_iface_abnormal "$agg_iface"; then
            log "修复:   重拉异常接口 $agg_iface"
            ifdown "$agg_iface" >/dev/null 2>&1 || true
            sleep 2
            ifup "$agg_iface" >/dev/null 2>&1 || true
            agg_restarted='1'
        fi
    done

    [ "$agg_restarted" = '1' ] || log "修复:   未发现需要重拉的异常接口"
}

nradio_5g_aggregation_light_repair() {
    selfcheck_print_header "5G聚合轻量修复"
    if ! nradio_5g_aggregation_model_supported; then
        log "结果:   当前机型无 5G 聚合修复动作"
        return 0
    fi

    if [ -x /etc/init.d/net_switch ]; then
        log "修复:   重新应用 net_switch"
        /etc/init.d/net_switch restart >/dev/null 2>&1 || true
        sleep 2
    else
        log "修复:   未发现 net_switch init"
    fi

    if [ -x /etc/init.d/net6_switch ]; then
        log "修复:   重新应用 net6_switch"
        /etc/init.d/net6_switch restart >/dev/null 2>&1 || true
        sleep 2
    else
        log "修复:   未发现 net6_switch init"
    fi

    nradio_5g_aggregation_restart_abnormal_ifaces

    if [ -x /etc/init.d/mwan3 ]; then
        log "修复:   重启 mwan3"
        /etc/init.d/mwan3 restart >/dev/null 2>&1 || true
    elif command -v mwan3 >/dev/null 2>&1; then
        log "修复:   reload mwan3"
        mwan3 restart >/dev/null 2>&1 || true
    else
        log "修复:   未发现 mwan3"
    fi

    sleep 5
}

nradio_5g_aggregation_fix_mwan_weight() {
    agg_changed='0'

    selfcheck_print_header "负载均衡"
    if ! nradio_5g_aggregation_model_supported; then
        log "结果:   当前机型无 5G 聚合权重修复动作"
        return 0
    fi
    command -v uci >/dev/null 2>&1 || {
        log "mwan3权重: 缺少 uci，无法修复"
        return 1
    }

    printf '请输入副5G权重 [2]: '
    if ui_read_line; then
        agg_cpe1_weight="$UI_READ_RESULT"
    else
        agg_cpe1_weight=''
    fi
    [ -n "$agg_cpe1_weight" ] || agg_cpe1_weight='2'
    case "$agg_cpe1_weight" in
        *[!0-9]*|0)
            log "mwan3权重: 副5G(cpe1_4)权重无效"
            return 1
            ;;
    esac

    printf '请输入蜂窝权重 [1]: '
    if ui_read_line; then
        agg_cpe_weight="$UI_READ_RESULT"
    else
        agg_cpe_weight=''
    fi
    [ -n "$agg_cpe_weight" ] || agg_cpe_weight='1'
    case "$agg_cpe_weight" in
        *[!0-9]*|0)
            log "mwan3权重: 蜂窝(cpe_4)权重无效"
            return 1
            ;;
    esac

    log "负载均衡: 副5G:蜂窝 = ${agg_cpe1_weight}:${agg_cpe_weight}"

    for agg_iface in cpe_4 cpe1_4; do
        case "$agg_iface" in
            cpe1_4)
                agg_target_weight="$agg_cpe1_weight"
                ;;
            cpe_4)
                agg_target_weight="$agg_cpe_weight"
                ;;
            *)
                agg_target_weight='1'
                ;;
        esac
        agg_members="$(nradio_5g_aggregation_mwan_members_for_iface "$agg_iface" 2>/dev/null || true)"
        if [ -z "$agg_members" ]; then
            log "mwan3权重: $agg_iface = 未找到 member"
            continue
        fi
        for agg_member in $agg_members; do
            log "mwan3权重: 设置 $agg_member ($agg_iface) weight=${agg_target_weight}"
            uci set "mwan3.${agg_member}.weight=${agg_target_weight}" >/dev/null 2>&1 && agg_changed='1'
        done
    done

    if [ "$agg_changed" = '1' ]; then
        uci commit mwan3 >/dev/null 2>&1 || true
        nradio_5g_aggregation_restart_mwan || true
        sleep 3
    else
        log "mwan3权重: 未产生变更"
    fi
}

nradio_5g_aggregation_print_hw_offload_state() {
    agg_flow="$(uci -q get firewall.@defaults[0].flow_offloading 2>/dev/null || true)"
    agg_hw_flow="$(uci -q get firewall.@defaults[0].flow_offloading_hw 2>/dev/null || true)"
    log "硬件加速: firewall.flow_offloading=${agg_flow:-未配置} flow_offloading_hw=${agg_hw_flow:-未配置}"

    if iptables -j FLOWOFFLOAD -h 2>&1 | grep -F -- '--hw' >/dev/null 2>&1; then
        log "硬件加速: FLOWOFFLOAD 支持 --hw"
    else
        log "硬件加速: FLOWOFFLOAD 未显示 --hw 支持"
    fi

    agg_rule_text="$(iptables -t filter -S FORWARD 2>/dev/null | grep -F 'FLOWOFFLOAD' | sed -n '1,3p' || true)"
    if [ -n "$agg_rule_text" ]; then
        printf '%s\n' "$agg_rule_text" | sed 's/^/规则:   /'
    else
        log "规则:   未发现 FLOWOFFLOAD FORWARD 规则"
    fi

    agg_rule_hit="$(iptables -t filter -L FORWARD -v -n 2>/dev/null | grep -F 'FLOWOFFLOAD' | sed -n '1,3p' || true)"
    if [ -n "$agg_rule_hit" ]; then
        printf '%s\n' "$agg_rule_hit" | sed 's/^/计数:   /'
    else
        log "计数:   未发现 FLOWOFFLOAD 命中行"
    fi

    if [ -r /sys/kernel/debug/hnat/hnat_entry ]; then
        sed -n '1,8p' /sys/kernel/debug/hnat/hnat_entry 2>/dev/null | sed 's/^/HNAT:   /'
    fi
}

nradio_5g_aggregation_enable_hw_offload() {
    selfcheck_print_header "硬件 offload 开启验证"
    if ! nradio_5g_aggregation_model_supported; then
        log "结果:   当前机型无 5G 聚合硬件 offload 修复动作"
        return 0
    fi
    command -v uci >/dev/null 2>&1 || {
        log "硬件加速: 缺少 uci，无法写入"
        return 1
    }
    command -v fw3 >/dev/null 2>&1 || {
        log "硬件加速: 缺少 fw3，无法重载防火墙"
        return 1
    }

    log "写入:   flow_offloading=1 flow_offloading_hw=1"
    uci set firewall.@defaults[0].flow_offloading='1' >/dev/null 2>&1 || return 1
    uci set firewall.@defaults[0].flow_offloading_hw='1' >/dev/null 2>&1 || return 1
    uci commit firewall >/dev/null 2>&1 || return 1

    log "重载:   fw3 reload"
    fw3 reload >"$WORKDIR/nradio-hwoffload-fw3.log" 2>&1 || log "提示:   fw3 reload 返回非 0：$WORKDIR/nradio-hwoffload-fw3.log"
    if [ -x /etc/init.d/mtkhnat ]; then
        log "重启:   mtkhnat"
        /etc/init.d/mtkhnat restart >/dev/null 2>&1 || true
    fi
    sleep 2
    nradio_5g_aggregation_print_hw_offload_state
}

nradio_5g_aggregation_restore_hw_offload() {
    selfcheck_print_header "硬件 offload 直接还原"
    if ! nradio_5g_aggregation_model_supported; then
        log "结果:   当前机型无 5G 聚合硬件 offload 还原动作"
        return 0
    fi
    command -v fw3 >/dev/null 2>&1 || {
        log "硬件加速: 缺少 fw3，无法重载防火墙"
        return 1
    }

    log "写入:   flow_offloading=1，删除 flow_offloading_hw"
    uci set firewall.@defaults[0].flow_offloading='1' >/dev/null 2>&1 || return 1
    uci -q delete firewall.@defaults[0].flow_offloading_hw >/dev/null 2>&1 || true
    uci commit firewall >/dev/null 2>&1 || return 1

    log "重载:   fw3 reload"
    fw3 reload >"$WORKDIR/nradio-hwoffload-restore-fw3.log" 2>&1 || log "提示:   fw3 reload 返回非 0：$WORKDIR/nradio-hwoffload-restore-fw3.log"
    if [ -x /etc/init.d/mtkhnat ]; then
        log "重启:   mtkhnat"
        /etc/init.d/mtkhnat restart >/dev/null 2>&1 || true
    fi
    sleep 2
    nradio_5g_aggregation_print_hw_offload_state
}

nradio_5g_aggregation_counter_value() {
    agg_dev="$1"
    agg_name="$2"

    cat "/sys/class/net/$agg_dev/statistics/$agg_name" 2>/dev/null | sed -n '1p'
}

nradio_5g_aggregation_traffic_monitor() {
    agg_seconds="${1:-30}"
    agg_eth1_rx_start="$(nradio_5g_aggregation_counter_value eth1 rx_bytes)"
    agg_eth1_tx_start="$(nradio_5g_aggregation_counter_value eth1 tx_bytes)"
    agg_port5_rx_start="$(nradio_5g_aggregation_counter_value port5 rx_bytes)"
    agg_port5_tx_start="$(nradio_5g_aggregation_counter_value port5 tx_bytes)"

    selfcheck_print_header "5G聚合测速流量监控"
    if ! nradio_5g_aggregation_model_supported; then
        log "结果:   当前机型无 5G 聚合流量监控"
        return 0
    fi

    log "提示:   接下来 ${agg_seconds} 秒请用 IPv4 多线程测速"
    ip -4 route show default 2>/dev/null | sed -n '1,3p' | sed 's/^/IPv4默认: /'
    ip -6 route show default 2>/dev/null | sed -n '1,3p' | sed 's/^/IPv6默认: /'
    sleep "$agg_seconds"

    agg_eth1_rx_end="$(nradio_5g_aggregation_counter_value eth1 rx_bytes)"
    agg_eth1_tx_end="$(nradio_5g_aggregation_counter_value eth1 tx_bytes)"
    agg_port5_rx_end="$(nradio_5g_aggregation_counter_value port5 rx_bytes)"
    agg_port5_tx_end="$(nradio_5g_aggregation_counter_value port5 tx_bytes)"

    agg_eth1_rx_delta=$(( ${agg_eth1_rx_end:-0} - ${agg_eth1_rx_start:-0} ))
    agg_eth1_tx_delta=$(( ${agg_eth1_tx_end:-0} - ${agg_eth1_tx_start:-0} ))
    agg_port5_rx_delta=$(( ${agg_port5_rx_end:-0} - ${agg_port5_rx_start:-0} ))
    agg_port5_tx_delta=$(( ${agg_port5_tx_end:-0} - ${agg_port5_tx_start:-0} ))
    agg_eth1_total_delta=$((agg_eth1_rx_delta + agg_eth1_tx_delta))
    agg_port5_total_delta=$((agg_port5_rx_delta + agg_port5_tx_delta))
    log "流量:   eth1  RX=${agg_eth1_rx_delta} TX=${agg_eth1_tx_delta} TOTAL=${agg_eth1_total_delta} bytes / ${agg_seconds}s"
    log "流量:   port5 RX=${agg_port5_rx_delta} TX=${agg_port5_tx_delta} TOTAL=${agg_port5_total_delta} bytes / ${agg_seconds}s"

    if [ "$agg_eth1_rx_delta" -gt 1048576 ] 2>/dev/null && [ "$agg_port5_rx_delta" -gt 1048576 ] 2>/dev/null; then
        log "下载判断: eth1 与 port5 均有明显 RX，下行已双线分流"
    elif [ "$agg_eth1_rx_delta" -gt 1048576 ] 2>/dev/null || [ "$agg_port5_rx_delta" -gt 1048576 ] 2>/dev/null; then
        log "下载判断: 主要只有一条线路 RX 明显，下行偏单线"
    else
        log "下载判断: RX 流量不足，无法判断下行聚合"
    fi

    if [ "$agg_eth1_tx_delta" -gt 1048576 ] 2>/dev/null && [ "$agg_port5_tx_delta" -gt 1048576 ] 2>/dev/null; then
        log "上传判断: eth1 与 port5 均有明显 TX，上行已双线分流"
    elif [ "$agg_eth1_tx_delta" -gt 1048576 ] 2>/dev/null || [ "$agg_port5_tx_delta" -gt 1048576 ] 2>/dev/null; then
        log "上传判断: 主要只有一条线路 TX 明显，上行偏单线"
    else
        log "上传判断: TX 流量不足，无法判断上行聚合"
    fi
}

nradio_5g_aggregation_ipv6_ping_public_quiet() {
    agg_dev="${1:-}"

    if ! command -v ping >/dev/null 2>&1; then
        return 1
    fi

    if [ -n "$agg_dev" ]; then
        ping -6 -I "$agg_dev" -c 1 -W 2 2408:8000::8 >/dev/null 2>&1 && return 0
        ping -6 -I "$agg_dev" -c 1 -W 2 240c::6666 >/dev/null 2>&1 && return 0
    else
        ping -6 -c 1 -W 2 2408:8000::8 >/dev/null 2>&1 && return 0
        ping -6 -c 1 -W 2 240c::6666 >/dev/null 2>&1 && return 0
    fi

    return 1
}

nradio_5g_aggregation_ipv6_ping_probe() {
    agg_dev="${1:-}"

    if ! command -v ping >/dev/null 2>&1; then
        log "IPv6探测: 缺少 ping 命令"
        return 1
    fi

    if [ -n "$agg_dev" ]; then
        if ping -6 -I "$agg_dev" -c 2 -W 2 2408:8000::8 >/dev/null 2>&1; then
            log "IPv6探测: $agg_dev -> 2408:8000::8 = 通"
            return 0
        fi
        if ping -6 -I "$agg_dev" -c 2 -W 2 240c::6666 >/dev/null 2>&1; then
            log "IPv6探测: $agg_dev -> 240c::6666 = 通"
            return 0
        fi
    else
        if ping -6 -c 2 -W 2 2408:8000::8 >/dev/null 2>&1; then
            log "IPv6探测: 2408:8000::8 = 通"
            return 0
        fi
        if ping -6 -c 2 -W 2 240c::6666 >/dev/null 2>&1; then
            log "IPv6探测: 240c::6666 = 通"
            return 0
        fi
    fi

    log "IPv6探测: 公网 IPv6 暂不通"
    return 1
}

nradio_5g_aggregation_ipv6_default_gateway() {
    agg_dev="${1:-}"
    [ -n "$agg_dev" ] || return 1

    ip -6 route show default 2>/dev/null | awk -v dev="$agg_dev" '
        {
            matched = 0
            gw = ""
            for (i = 1; i <= NF; i++) {
                if ($i == "dev" && (i + 1) <= NF && $(i + 1) == dev) matched = 1
                if ($i == "via" && (i + 1) <= NF) gw = $(i + 1)
            }
            if (matched && gw != "") {
                print gw
                exit
            }
        }
    '
}

nradio_5g_aggregation_ipv6_gateway_reachable() {
    agg_dev="${1:-}"
    agg_gw="$(nradio_5g_aggregation_ipv6_default_gateway "$agg_dev" 2>/dev/null || true)"
    [ -n "$agg_dev" ] || return 1
    [ -n "$agg_gw" ] || return 1

    if command -v ping >/dev/null 2>&1 && ping -6 -I "$agg_dev" -c 1 -W 2 "$agg_gw" >/dev/null 2>&1; then
        return 0
    fi

    if ip -6 neigh show dev "$agg_dev" 2>/dev/null | awk -v gw="$agg_gw" '
        $1 == gw && $0 !~ /FAILED/ && $0 !~ /INCOMPLETE/ { ok = 1 }
        END { exit ok ? 0 : 1 }
    '; then
        return 0
    fi

    return 1
}

nradio_5g_aggregation_ipv6_iface_has_default_route() {
    agg_dev="${1:-}"
    [ -n "$agg_dev" ] || return 1
    ip -6 route show default 2>/dev/null | grep -F " dev $agg_dev " >/dev/null 2>&1
}

nradio_5g_aggregation_ipv6_dev_has_link_local() {
    agg_dev="${1:-}"
    [ -n "$agg_dev" ] || return 1
    command -v ip >/dev/null 2>&1 || return 1

    ip -6 addr show dev "$agg_dev" 2>/dev/null | grep -F ' scope link ' | grep -F 'inet6 fe80:' >/dev/null 2>&1
}

nradio_5g_aggregation_ipv6_dev_eui64_link_local() {
    agg_dev="${1:-}"
    [ -n "$agg_dev" ] || return 1

    if [ -r "/sys/class/net/$agg_dev/address" ]; then
        agg_mac="$(cat "/sys/class/net/$agg_dev/address" 2>/dev/null | tr 'A-F' 'a-f' || true)"
    else
        agg_mac="$(ip link show dev "$agg_dev" 2>/dev/null | awk '/link\/ether/ { print $2; exit }' | tr 'A-F' 'a-f' || true)"
    fi

    case "$agg_mac" in
        [0-9a-f][0-9a-f]:[0-9a-f][0-9a-f]:[0-9a-f][0-9a-f]:[0-9a-f][0-9a-f]:[0-9a-f][0-9a-f]:[0-9a-f][0-9a-f]) ;;
        *) return 1 ;;
    esac

    agg_b1="$(printf '%s\n' "$agg_mac" | cut -d: -f1)"
    agg_b2="$(printf '%s\n' "$agg_mac" | cut -d: -f2)"
    agg_b3="$(printf '%s\n' "$agg_mac" | cut -d: -f3)"
    agg_b4="$(printf '%s\n' "$agg_mac" | cut -d: -f4)"
    agg_b5="$(printf '%s\n' "$agg_mac" | cut -d: -f5)"
    agg_b6="$(printf '%s\n' "$agg_mac" | cut -d: -f6)"

    printf 'fe80::%02x%02x:%02xff:fe%02x:%02x%02x\n' \
        "$((0x$agg_b1 ^ 2))" "$((0x$agg_b2))" "$((0x$agg_b3))" \
        "$((0x$agg_b4))" "$((0x$agg_b5))" "$((0x$agg_b6))"
}

nradio_5g_aggregation_ipv6_ensure_dev_link_local() {
    agg_dev="${1:-}"
    [ -n "$agg_dev" ] || return 1
    command -v ip >/dev/null 2>&1 || return 1

    nradio_5g_aggregation_ipv6_dev_has_link_local "$agg_dev" && return 0

    agg_ll="$(nradio_5g_aggregation_ipv6_dev_eui64_link_local "$agg_dev" 2>/dev/null || true)"
    [ -n "$agg_ll" ] || return 1

    log "IPv6卡死恢复: $agg_dev 缺少 link-local，补 $agg_ll/64"
    ip -6 addr add "$agg_ll/64" dev "$agg_dev" 2>/dev/null || true
    nradio_5g_aggregation_ipv6_dev_has_link_local "$agg_dev"
}

nradio_5g_aggregation_ipv6_iface_ready_check() {
    agg_iface="${1:-}"
    agg_prefix="${2:-}"
    [ -n "$agg_prefix" ] || agg_prefix="IPv6检查"

    agg_ifstatus_text="$(ifstatus "$agg_iface" 2>/dev/null || true)"
    [ -n "$agg_ifstatus_text" ] || {
        log "$agg_prefix: $agg_iface = 不存在"
        return 1
    }

    agg_up="$(nradio_5g_aggregation_ifstatus_bool "$agg_ifstatus_text" up)"
    agg_pending="$(nradio_5g_aggregation_ifstatus_bool "$agg_ifstatus_text" pending)"
    agg_proto="$(nradio_5g_aggregation_ifstatus_field "$agg_ifstatus_text" proto)"
    agg_dev="$(nradio_5g_aggregation_ifstatus_field "$agg_ifstatus_text" l3_device)"
    [ -n "$agg_dev" ] || agg_dev="$(nradio_5g_aggregation_ifstatus_field "$agg_ifstatus_text" device)"
    if printf '%s\n' "$agg_ifstatus_text" | grep -F '"address": "' >/dev/null 2>&1; then
        agg_has_addr='1'
    else
        agg_has_addr='0'
    fi
    if nradio_5g_aggregation_ipv6_iface_has_default_route "$agg_dev"; then
        agg_has_route='1'
    else
        agg_has_route='0'
    fi
    agg_gw="$(nradio_5g_aggregation_ipv6_default_gateway "$agg_dev" 2>/dev/null || true)"
    if nradio_5g_aggregation_ipv6_gateway_reachable "$agg_dev"; then
        agg_gw_ok='1'
    else
        agg_gw_ok='0'
    fi
    if nradio_5g_aggregation_ipv6_ping_public_quiet "$agg_dev"; then
        agg_public_ok='1'
    else
        agg_public_ok='0'
    fi

    log "$agg_prefix: $agg_iface up=${agg_up:-?} pending=${agg_pending:-?} proto=${agg_proto:-?} dev=${agg_dev:-?} addr=$agg_has_addr default=$agg_has_route gw=${agg_gw:-无} gw_ok=$agg_gw_ok public=$agg_public_ok"
    [ "$agg_up" = 'true' ] && [ "$agg_pending" != 'true' ] && [ "$agg_has_addr" = '1' ] && [ "$agg_has_route" = '1' ] && [ "$agg_gw_ok" = '1' ] && [ "$agg_public_ok" = '1' ]
}

nradio_5g_aggregation_ipv6_wait_iface_ready() {
    agg_iface="${1:-}"
    agg_wait_total="${2:-120}"
    agg_wait_step="${3:-10}"
    agg_wait_elapsed='0'

    case "$agg_wait_total" in *[!0-9]*|'') agg_wait_total='120' ;; esac
    case "$agg_wait_step" in *[!0-9]*|''|0) agg_wait_step='10' ;; esac

    while :; do
        if nradio_5g_aggregation_ipv6_iface_ready_check "$agg_iface" "IPv6等待(${agg_wait_elapsed}s)"; then
            log "IPv6恢复: $agg_iface 已确认公网 IPv6 可用"
            return 0
        fi
        [ "$agg_wait_elapsed" -ge "$agg_wait_total" ] 2>/dev/null && break
        sleep "$agg_wait_step"
        agg_wait_elapsed=$((agg_wait_elapsed + agg_wait_step))
    done

    log "IPv6恢复: $agg_iface 等待 ${agg_wait_total}s 后仍未确认公网 IPv6 可用"
    return 1
}

nradio_5g_aggregation_ipv6_collect_recent_logs() {
    if command -v logread >/dev/null 2>&1; then
        logread 2>/dev/null | tail -n 260 || true
    elif [ -r /var/log/messages ]; then
        tail -n 260 /var/log/messages 2>/dev/null || true
    fi
}

nradio_5g_aggregation_ipv6_recent_log_summary() {
    agg_recent_logs=''
    agg_recent_hits=''

    agg_recent_logs="$(nradio_5g_aggregation_ipv6_collect_recent_logs)"

    [ -n "$agg_recent_logs" ] || {
        log "IPv6日志: 未找到 logread 或 /var/log/messages"
        return 0
    }

    agg_recent_hits="$(printf '%s\n' "$agg_recent_logs" | grep -Ei 'odhcp6c|cpe1_6|cpe_6|wan6|mwan3track|wanchk: cpe|Address not available|SOLICIT|RS|Interface .* now (up|down)' | tail -n 18 || true)"
    if [ -n "$agg_recent_hits" ]; then
        printf '%s\n' "$agg_recent_hits" | sed 's/^/IPv6日志: /'
    else
        log "IPv6日志: 最近日志未命中 IPv6 关键行"
    fi
}

nradio_5g_aggregation_ipv6_recent_stuck_logs() {
    agg_iface="${1:-}"
    agg_recent_logs="$(nradio_5g_aggregation_ipv6_collect_recent_logs)"
    [ -n "$agg_recent_logs" ] || return 1

    printf '%s\n' "$agg_recent_logs" | grep -Ei 'Address not available|Failed to send RS|Failed to send SOLICIT' >/dev/null 2>&1 || return 1
    printf '%s\n' "$agg_recent_logs" | grep -F "$agg_iface" >/dev/null 2>&1 && return 0

    case "$agg_iface" in
        cpe1_6)
            printf '%s\n' "$agg_recent_logs" | grep -F 'wanchk: cpe1: v6 dhcp renew' >/dev/null 2>&1 && return 0
            ;;
        cpe_6)
            printf '%s\n' "$agg_recent_logs" | grep -F 'wanchk: cpe: v6 dhcp renew' >/dev/null 2>&1 && return 0
            ;;
        wan6)
            printf '%s\n' "$agg_recent_logs" | grep -F "Interface 'wan6' is setting up now" >/dev/null 2>&1 && return 0
            ;;
    esac

    return 1
}

nradio_5g_aggregation_ipv6_gateway_failed() {
    agg_dev="${1:-}"
    agg_gw="$(nradio_5g_aggregation_ipv6_default_gateway "$agg_dev" 2>/dev/null || true)"
    [ -n "$agg_dev" ] || return 1
    [ -n "$agg_gw" ] || return 1

    ip -6 neigh show dev "$agg_dev" 2>/dev/null | awk -v gw="$agg_gw" '
        $1 == gw && ($0 ~ /FAILED/ || $0 ~ /INCOMPLETE/) { bad = 1 }
        END { exit bad ? 0 : 1 }
    '
}

nradio_5g_aggregation_ipv6_iface_pending_stuck() {
    agg_iface="${1:-}"
    agg_ifstatus_text="$(ifstatus "$agg_iface" 2>/dev/null || true)"
    [ -n "$agg_ifstatus_text" ] || return 1

    agg_up="$(nradio_5g_aggregation_ifstatus_bool "$agg_ifstatus_text" up)"
    agg_pending="$(nradio_5g_aggregation_ifstatus_bool "$agg_ifstatus_text" pending)"
    agg_proto="$(nradio_5g_aggregation_ifstatus_field "$agg_ifstatus_text" proto)"
    agg_dev="$(nradio_5g_aggregation_ifstatus_field "$agg_ifstatus_text" l3_device)"
    [ -n "$agg_dev" ] || agg_dev="$(nradio_5g_aggregation_ifstatus_field "$agg_ifstatus_text" device)"
    [ "$agg_pending" = 'true' ] || return 1

    agg_has_addr='0'
    printf '%s\n' "$agg_ifstatus_text" | grep -F '"address": "' >/dev/null 2>&1 && agg_has_addr='1'
    if nradio_5g_aggregation_ipv6_gateway_failed "$agg_dev"; then
        agg_gw_failed='1'
    else
        agg_gw_failed='0'
    fi
    if nradio_5g_aggregation_ipv6_recent_stuck_logs "$agg_iface"; then
        agg_log_stuck='1'
    else
        agg_log_stuck='0'
    fi

    log "IPv6卡死检查: $agg_iface up=${agg_up:-?} pending=${agg_pending:-?} proto=${agg_proto:-?} dev=${agg_dev:-?} addr=$agg_has_addr gw_failed=$agg_gw_failed log_stuck=$agg_log_stuck"
    [ "$agg_log_stuck" = '1' ] && { [ "$agg_up" != 'true' ] || [ "$agg_has_addr" != '1' ] || [ "$agg_gw_failed" = '1' ]; }
}

nradio_5g_aggregation_ipv6_cleanup_iface_helpers() {
    agg_iface="${1:-}"
    agg_cleaned='0'
    agg_helper_pids=''

    agg_helper_pids="$(ps w 2>/dev/null | awk -v iface="$agg_iface" '
        /dhcpv6\.sh/ && $0 ~ iface { print $1 }
    ' || true)"
    for agg_pid in $agg_helper_pids; do
        case "$agg_pid" in
            ''|*[!0-9]*)
                continue
                ;;
        esac
        [ "$agg_pid" = "$$" ] && continue
        log "IPv6卡死恢复: 结束残留 dhcpv6.sh pid=$agg_pid iface=$agg_iface"
        kill "$agg_pid" >/dev/null 2>&1 || true
        agg_cleaned='1'
    done

    for agg_pidfile in "/var/run/odhcp6c-$agg_iface.pid" "/var/run/odhcp6c.$agg_iface.pid" "/tmp/odhcp6c-$agg_iface.pid" "/tmp/odhcp6c.$agg_iface.pid"; do
        [ -r "$agg_pidfile" ] || continue
        agg_pid="$(sed -n '1p' "$agg_pidfile" 2>/dev/null || true)"
        case "$agg_pid" in
            ''|*[!0-9]*)
                continue
                ;;
        esac
        log "IPv6卡死恢复: 结束 odhcp6c pid=$agg_pid iface=$agg_iface"
        kill "$agg_pid" >/dev/null 2>&1 || true
        agg_cleaned='1'
    done

    [ "$agg_cleaned" = '1' ] && sleep 1
    return 0
}

nradio_5g_aggregation_ipv6_flush_dev_neigh() {
    agg_dev="${1:-}"
    [ -n "$agg_dev" ] || return 1
    command -v ip >/dev/null 2>&1 || return 1

    log "IPv6卡死恢复: 清理 $agg_dev IPv6 邻居缓存"
    ip -6 neigh flush dev "$agg_dev" >/dev/null 2>&1 || true
}

nradio_5g_aggregation_ipv6_recover_pending_stuck_iface() {
    agg_iface="${1:-}"
    agg_ifstatus_text="$(ifstatus "$agg_iface" 2>/dev/null || true)"
    [ -n "$agg_ifstatus_text" ] || return 1

    agg_dev="$(nradio_5g_aggregation_ifstatus_field "$agg_ifstatus_text" l3_device)"
    [ -n "$agg_dev" ] || agg_dev="$(nradio_5g_aggregation_ifstatus_field "$agg_ifstatus_text" device)"
    nradio_5g_aggregation_ipv6_iface_pending_stuck "$agg_iface" || return 1

    command -v ifdown >/dev/null 2>&1 || return 1
    command -v ifup >/dev/null 2>&1 || return 1
    log "IPv6卡死恢复: $agg_iface 命中 pending/odhcp6c/NDP 异常，执行二段恢复"
    nradio_5g_aggregation_ipv6_cleanup_iface_helpers "$agg_iface"
    nradio_5g_aggregation_ipv6_ensure_dev_link_local "$agg_dev" || true
    nradio_5g_aggregation_ipv6_flush_dev_neigh "$agg_dev" || true
    ifdown "$agg_iface" >/dev/null 2>&1 || true
    sleep 2
    nradio_5g_aggregation_ipv6_ensure_dev_link_local "$agg_dev" || true
    nradio_5g_aggregation_ipv6_flush_dev_neigh "$agg_dev" || true
    ifup "$agg_iface" >/dev/null 2>&1 || true
    return 0
}

nradio_5g_aggregation_ipv6_recover_iface() {
    agg_iface="${1:-}"
    agg_ifstatus_text="$(ifstatus "$agg_iface" 2>/dev/null || true)"
    [ -n "$agg_ifstatus_text" ] || {
        log "IPv6接口: $agg_iface = 不存在，跳过"
        return 1
    }

    agg_up="$(nradio_5g_aggregation_ifstatus_bool "$agg_ifstatus_text" up)"
    agg_pending="$(nradio_5g_aggregation_ifstatus_bool "$agg_ifstatus_text" pending)"
    agg_proto="$(nradio_5g_aggregation_ifstatus_field "$agg_ifstatus_text" proto)"
    agg_dev="$(nradio_5g_aggregation_ifstatus_field "$agg_ifstatus_text" l3_device)"
    [ -n "$agg_dev" ] || agg_dev="$(nradio_5g_aggregation_ifstatus_field "$agg_ifstatus_text" device)"
    if printf '%s\n' "$agg_ifstatus_text" | grep -F '"address": "' >/dev/null 2>&1; then
        agg_has_addr='1'
    else
        agg_has_addr='0'
    fi
    if nradio_5g_aggregation_ipv6_iface_has_default_route "$agg_dev"; then
        agg_has_route='1'
    else
        agg_has_route='0'
    fi
    agg_gw="$(nradio_5g_aggregation_ipv6_default_gateway "$agg_dev" 2>/dev/null || true)"
    if nradio_5g_aggregation_ipv6_gateway_reachable "$agg_dev"; then
        agg_gw_ok='1'
    else
        agg_gw_ok='0'
    fi
    if nradio_5g_aggregation_ipv6_ping_public_quiet "$agg_dev"; then
        agg_public_ok='1'
    else
        agg_public_ok='0'
    fi

    log "IPv6接口: $agg_iface up=${agg_up:-?} pending=${agg_pending:-?} proto=${agg_proto:-?} dev=${agg_dev:-?} addr=$agg_has_addr default=$agg_has_route gw=${agg_gw:-无} gw_ok=$agg_gw_ok public=$agg_public_ok"
    if [ "$agg_up" = 'true' ] && [ "$agg_pending" != 'true' ] && [ "$agg_has_addr" = '1' ] && [ "$agg_has_route" = '1' ] && [ "$agg_gw_ok" = '1' ] && [ "$agg_public_ok" = '1' ]; then
        return 1
    fi

    command -v ifdown >/dev/null 2>&1 || return 1
    command -v ifup >/dev/null 2>&1 || return 1
    log "IPv6恢复: 重拉 $agg_iface"
    nradio_5g_aggregation_ipv6_ensure_dev_link_local "$agg_dev" || true
    ifdown "$agg_iface" >/dev/null 2>&1 || true
    sleep 2
    nradio_5g_aggregation_ipv6_ensure_dev_link_local "$agg_dev" || true
    ifup "$agg_iface" >/dev/null 2>&1 || true
    return 0
}

nradio_5g_aggregation_ipv6_light_recovery() {
    agg_changed='0'
    agg_seen='0'

    selfcheck_print_header "IPv6 轻量恢复"
    if ! nradio_5g_aggregation_model_supported; then
        log "结果:   当前机型无 5G IPv6 轻量恢复动作"
        return 0
    fi
    command -v ifstatus >/dev/null 2>&1 || {
        log "IPv6恢复: 缺少 ifstatus，无法自动检测"
        return 1
    }

    log "说明:   自动检测 cpe_6 / cpe1_6 / wan6，只重拉异常 IPv6 接口"
    ip -6 route show default 2>/dev/null | sed -n '1,3p' | sed 's/^/IPv6默认: /' || true
    for agg_iface in cpe_6 cpe1_6 wan6; do
        if ifstatus "$agg_iface" >/dev/null 2>&1; then
            agg_seen='1'
            if nradio_5g_aggregation_ipv6_recover_iface "$agg_iface"; then
                agg_changed='1'
            fi
        else
            log "IPv6接口: $agg_iface = 不存在，跳过"
        fi
    done

    [ "$agg_seen" = '1' ] || {
        log "IPv6恢复: 未发现 cpe_6 / cpe1_6 / wan6"
        return 1
    }

    if [ "$agg_changed" = '1' ]; then
        sleep 8
        if [ -x /etc/init.d/odhcpd ]; then
            log "IPv6恢复: 重启 odhcpd，刷新 LAN 前缀下发"
            /etc/init.d/odhcpd restart >/dev/null 2>&1 || true
        fi
        if command -v mwan3 >/dev/null 2>&1; then
            for agg_iface in cpe_6 cpe1_6 wan6; do
                if ifstatus "$agg_iface" >/dev/null 2>&1; then
                    mwan3 ifup "$agg_iface" >/dev/null 2>&1 || true
                fi
            done
            nradio_5g_aggregation_restart_mwan || true
        fi
    else
        log "IPv6恢复: 未发现需要重拉的异常 IPv6 接口"
    fi

    agg_ready='1'
    agg_pending_ifaces=''
    for agg_iface in cpe_6 cpe1_6 wan6; do
        if ifstatus "$agg_iface" >/dev/null 2>&1; then
            if ! nradio_5g_aggregation_ipv6_wait_iface_ready "$agg_iface" 120 10; then
                agg_ready='0'
                agg_pending_ifaces="$agg_pending_ifaces $agg_iface"
            fi
        fi
    done

    if [ "$agg_ready" != '1' ]; then
        agg_stuck_changed='0'
        for agg_iface in $agg_pending_ifaces; do
            if ifstatus "$agg_iface" >/dev/null 2>&1; then
                if nradio_5g_aggregation_ipv6_recover_pending_stuck_iface "$agg_iface"; then
                    agg_stuck_changed='1'
                fi
            fi
        done

        if [ "$agg_stuck_changed" = '1' ]; then
            sleep 8
            if [ -x /etc/init.d/odhcpd ]; then
                log "IPv6卡死恢复: 重启 odhcpd，刷新 LAN 前缀下发"
                /etc/init.d/odhcpd restart >/dev/null 2>&1 || true
            fi
            if command -v mwan3 >/dev/null 2>&1; then
                for agg_iface in cpe_6 cpe1_6 wan6; do
                    if ifstatus "$agg_iface" >/dev/null 2>&1; then
                        mwan3 ifup "$agg_iface" >/dev/null 2>&1 || true
                    fi
                done
                nradio_5g_aggregation_restart_mwan || true
            fi

            agg_ready='1'
            for agg_iface in $agg_pending_ifaces; do
                if ifstatus "$agg_iface" >/dev/null 2>&1; then
                    if ! nradio_5g_aggregation_ipv6_wait_iface_ready "$agg_iface" 120 10; then
                        agg_ready='0'
                    fi
                else
                    agg_ready='0'
                fi
            done
        else
            log "IPv6卡死恢复: 未命中 pending/odhcp6c/NDP 二段恢复条件"
        fi
    fi

    nradio_5g_aggregation_print_diagnostics
    if [ "$agg_ready" = '1' ]; then
        nradio_5g_aggregation_ipv6_ping_probe || true
    else
        log "IPv6恢复: 地址、默认路由、下一跳或公网探测未全部恢复"
        nradio_5g_aggregation_ipv6_recent_log_summary
        nradio_5g_aggregation_ipv6_ping_probe || true
    fi
}

run_5g_aggregation_repair_check() {
    nradio_5g_aggregation_print_diagnostics

    if ! nradio_5g_aggregation_model_supported; then
        return 0
    fi

    printf '\n5G聚合修复检查:\n'
    printf '1. 轻量修复后复查\n'
    printf '2. 负载均衡（副5G:蜂窝）\n'
    printf '3. 30秒测速流量监控\n'
    printf '4. 开启硬件 offload 并验证\n'
    printf '5. 还原为软件 offload 并验证\n'
    printf '6. IPv6 轻量恢复（自动检测双接口）\n'
    printf '0. 结束\n'
    printf '请选择 0、1、2、3、4、5 或 6: '
    if ! ui_read_line; then
        log "提示:   诊断完成；需要修复或监控时请选择 1/2/3/4/5/6"
        return 0
    fi

    case "$UI_READ_RESULT" in
        0|'')
            return 0
            ;;
        1)
            nradio_5g_aggregation_light_repair
            nradio_5g_aggregation_print_diagnostics
            record_action_history "5 > 5 > 1" "5G聚合轻量修复后复查" "PASS" "$BACKUP_DIR"
            ;;
        2)
            confirm_or_exit "确认直接设置负载均衡（副5G:蜂窝）吗？"
            nradio_5g_aggregation_fix_mwan_weight
            nradio_5g_aggregation_print_diagnostics
            record_action_history "5 > 5 > 2" "5G聚合负载均衡设置" "PASS" "$BACKUP_DIR"
            ;;
        3)
            nradio_5g_aggregation_traffic_monitor 30
            ;;
        4)
            confirm_or_exit "确认直接开启硬件 offload 吗？"
            nradio_5g_aggregation_enable_hw_offload
            record_action_history "5 > 5 > 4" "5G聚合开启硬件 offload" "PASS" "$BACKUP_DIR"
            ;;
        5)
            confirm_or_exit "确认直接还原为软件 offload 吗？"
            nradio_5g_aggregation_restore_hw_offload
            record_action_history "5 > 5 > 5" "5G聚合还原软件 offload" "PASS" "$BACKUP_DIR"
            ;;
        6)
            nradio_5g_aggregation_ipv6_light_recovery
            record_action_history "5 > 5 > 6" "5G聚合 IPv6 轻量恢复" "PASS" "$BACKUP_DIR"
            ;;
        *)
            die_menu_input_issue "$UI_READ_RESULT"
            ;;
    esac
    case "$UI_READ_RESULT" in
        1|2|3|4|5|6) MENU_ACTION_COMPLETED='1' ;;
    esac
}

run_unified_system_health_summary() {
    health_warnings=0
    detected_model="$(unified_detect_model_name 2>/dev/null || true)"
    [ -n "$detected_model" ] || detected_model='未知'
    nros_revision="$(detect_nros_revision 2>/dev/null || true)"
    arch_name="$(unified_detect_arch_name)"
    kernel_name="$(uname -r 2>/dev/null || true)"
    mem_total_kib="$(unified_num_or_zero "$(unified_health_mem_kib MemTotal)")"
    mem_available_kib="$(unified_num_or_zero "$(unified_health_mem_kib MemAvailable)")"
    [ "$mem_available_kib" -gt 0 ] 2>/dev/null || mem_available_kib="$(unified_num_or_zero "$(unified_health_mem_kib MemFree)")"
    swap_total_kib="$(unified_num_or_zero "$(unified_health_mem_kib SwapTotal)")"
    swap_free_kib="$(unified_num_or_zero "$(unified_health_mem_kib SwapFree)")"
    dns_servers="$(unified_first_dns_servers)"
    gateway_text="$(unified_default_gateway_summary)"

    selfcheck_print_header "系统体检汇总"
    log "系统:   机型=${detected_model} NROS=${nros_revision:-未知} 架构=${arch_name} kernel=${kernel_name:-未知}"
    log "内存:   total=$(unified_health_kib_display "$mem_total_kib") available=$(unified_health_kib_display "$mem_available_kib") swap_total=$(unified_health_kib_display "$swap_total_kib") swap_free=$(unified_health_kib_display "$swap_free_kib")"
    swap_lines="$(awk 'NR > 1 { print $1 "(" $4 "K used/" ($3 - $4) "K free)" }' /proc/swaps 2>/dev/null | tr '\n' ' ' | sed 's/[[:space:]]\+/ /g; s/^ //; s/ $//' || true)"
    if [ -n "$swap_lines" ]; then
        log "swap:   ${swap_lines:-未启用}"
    else
        log "swap:   未启用"
    fi

    unified_health_print_path_usage "/tmp" "/tmp" || health_warnings=$((health_warnings + 1))
    unified_health_print_path_usage "/overlay" "/overlay" || health_warnings=$((health_warnings + 1))
    if [ -d /mnt/app_data ]; then
        unified_health_print_path_usage "/mnt/app_data" "/mnt/app_data" || health_warnings=$((health_warnings + 1))
    else
        log "存储:   /mnt/app_data = 不存在"
    fi

    if c2000_storage_swap_model_supported "$detected_model"; then
        storage_mount="$(detect_c2000max_storage_mount 2>/dev/null || true)"
        if [ -n "$storage_mount" ]; then
            unified_health_print_path_usage "存储卡" "$storage_mount" || health_warnings=$((health_warnings + 1))
        else
            log "存储:   存储卡 = 未检测到"
        fi
    fi

    log "网络:   DNS=${dns_servers:-未检测到} 默认网关=${gateway_text:-未检测到}"
    [ -n "$dns_servers" ] || health_warnings=$((health_warnings + 1))
    [ -n "$gateway_text" ] || health_warnings=$((health_warnings + 1))
    [ "$mem_available_kib" -ge 65536 ] 2>/dev/null || health_warnings=$((health_warnings + 1))

    if [ "$health_warnings" -gt 0 ]; then
        set_last_selfcheck_status WARN 0 "$health_warnings"
    else
        set_last_selfcheck_status PASS 0 0
    fi
}

run_unified_clock_tls_health_check() {
    clock_warnings=0
    clock_epoch="$(date +%s 2>/dev/null || printf '')"
    clock_text="$(date -R 2>/dev/null || date 2>/dev/null || true)"
    tls_err_file="$WORKDIR/unified-clock-tls.err"

    selfcheck_print_header "系统时间与 HTTPS 证书体检"
    log "时间:   当前系统时间 = ${clock_text:-未知}"

    case "$clock_epoch" in
        ''|*[!0-9]*)
            log "时间:   无法读取 Unix 时间戳"
            clock_warnings=$((clock_warnings + 1))
            ;;
        *)
            if [ "$clock_epoch" -lt 1704067200 ] 2>/dev/null; then
                log "时间:   早于 2024-01-01，HTTPS 证书校验和软件源访问可能异常"
                clock_warnings=$((clock_warnings + 1))
            elif [ "$clock_epoch" -gt 1893456000 ] 2>/dev/null; then
                log "时间:   晚于 2030-01-01，HTTPS 证书校验可能异常"
                clock_warnings=$((clock_warnings + 1))
            else
                log "时间:   时间范围 = 正常"
            fi
            ;;
    esac

    if command -v curl >/dev/null 2>&1; then
        tls_code="$(curl -L -I -o /dev/null -sS --connect-timeout 5 --max-time 8 -w '%{http_code}' https://github.com/ 2>"$tls_err_file" || true)"
        tls_err="$(sed -n '1p' "$tls_err_file" 2>/dev/null | sed 's/[[:space:]]\+/ /g; s/^ //; s/ $//' || true)"
        case "$tls_code" in
            200|204|301|302|307|308|403)
                log "HTTPS: github.com = 证书校验正常 (HTTP $tls_code)"
                ;;
            *)
                if printf '%s\n' "$tls_err" | grep -qiE 'certificate|SSL|TLS|x509|CAfile|issuer|handshake'; then
                    log "HTTPS: github.com = 证书/时间校验异常 (${tls_err:-HTTP ${tls_code:-000}})"
                    clock_warnings=$((clock_warnings + 1))
                else
                    log "HTTPS: github.com = 探测异常或超时 HTTP ${tls_code:-000}"
                fi
                ;;
        esac
    else
        log "HTTPS: github.com = 缺少 curl，跳过证书校验"
    fi

    if [ "$clock_warnings" -gt 0 ]; then
        set_last_selfcheck_status WARN 0 "$clock_warnings"
    else
        set_last_selfcheck_status PASS 0 0
    fi
}

run_unified_storage_expand_health_check() {
    storage_warnings=0
    detected_model="$(unified_detect_model_name 2>/dev/null || true)"
    rootfs_device="$(storage_expand_find_rootfs_2nd_device 2>/dev/null || true)"
    rootfs_mount_source=''
    rootfs_mount_point=''

    selfcheck_print_header "eMMC 存储扩展体检"
    log "环境:   机型=${detected_model:-未知} 扩展挂载点=$ROOTFS_2ND_STORAGE_MOUNT_POINT"

    if [ -z "$rootfs_device" ]; then
        log "rootfs_2nd: 未发现 PARTLABEL=rootfs_2nd 分区，跳过 eMMC 存储扩展体检"
        log "summary:  SKIP (rootfs_2nd not present)"
        set_last_selfcheck_status SKIP 0 0
        return 0
    fi

    log "rootfs_2nd: 分区=$rootfs_device"
    if storage_expand_is_booted_from_rootfs_2nd; then
        log "启动:   当前疑似从 rootfs_2nd 启动，禁止把该分区作为扩展盘"
        storage_warnings=$((storage_warnings + 1))
    else
        log "启动:   当前未从 rootfs_2nd 启动"
    fi

    if [ -f "$ROOTFS_2ND_STORAGE_MARKER" ]; then
        log "标记:   $ROOTFS_2ND_STORAGE_MARKER = 存在"
    else
        log "标记:   $ROOTFS_2ND_STORAGE_MARKER = 未启用"
    fi

    rootfs_mount_source="$(storage_expand_mount_source_for_mountpoint 2>/dev/null || true)"
    rootfs_mount_point="$(storage_expand_device_mountpoint "$rootfs_device" 2>/dev/null || true)"
    if [ -n "$rootfs_mount_source" ]; then
        if storage_expand_mount_source_matches_device "$rootfs_mount_source" "$rootfs_device"; then
            log "挂载:   $ROOTFS_2ND_STORAGE_MOUNT_POINT <- $rootfs_mount_source = 正常"
            unified_health_print_path_usage "eMMC 存储扩展" "$ROOTFS_2ND_STORAGE_MOUNT_POINT" || storage_warnings=$((storage_warnings + 1))
        else
            log "挂载:   $ROOTFS_2ND_STORAGE_MOUNT_POINT <- $rootfs_mount_source = 异常，来源不是 rootfs_2nd"
            storage_warnings=$((storage_warnings + 1))
        fi
    elif [ -n "$rootfs_mount_point" ]; then
        log "挂载:   rootfs_2nd 当前挂载在 $rootfs_mount_point，未接入 $ROOTFS_2ND_STORAGE_MOUNT_POINT"
        [ -f "$ROOTFS_2ND_STORAGE_MARKER" ] && storage_warnings=$((storage_warnings + 1))
    else
        log "挂载:   rootfs_2nd 当前未挂载"
        [ -f "$ROOTFS_2ND_STORAGE_MARKER" ] && storage_warnings=$((storage_warnings + 1))
    fi

    if [ -s "$ROOTFS_2ND_STORAGE_MIGRATE_LIST" ]; then
        migrated_count="$(wc -l < "$ROOTFS_2ND_STORAGE_MIGRATE_LIST" 2>/dev/null | tr -d ' ' || printf '0')"
        log "迁移:   记录=$migrated_count file=$ROOTFS_2ND_STORAGE_MIGRATE_LIST"
        sed -n '1,10p' "$ROOTFS_2ND_STORAGE_MIGRATE_LIST" 2>/dev/null | sed 's/^/迁移项: /'
    else
        log "迁移:   未发现迁移记录"
    fi

    if [ "$storage_warnings" -gt 0 ]; then
        set_last_selfcheck_status WARN 0 "$storage_warnings"
    else
        set_last_selfcheck_status PASS 0 0
    fi
}

run_unified_storage_migration_integrity_check() {
    migration_warnings=0
    migration_count=0
    migration_rows="$WORKDIR/storage-migration.rows"
    rootfs_device="$(storage_expand_find_rootfs_2nd_device 2>/dev/null || true)"

    selfcheck_print_header "eMMC 迁移链一致性"
    if [ -z "$rootfs_device" ]; then
        log "迁移链: 未发现 PARTLABEL=rootfs_2nd 分区，跳过迁移链检查"
        log "summary:  SKIP (rootfs_2nd not present)"
        set_last_selfcheck_status SKIP 0 0
        return 0
    fi
    if [ ! -s "$ROOTFS_2ND_STORAGE_MIGRATE_LIST" ]; then
        log "迁移链: 未发现迁移记录，跳过迁移链检查"
        log "summary:  SKIP (no migrated apps)"
        set_last_selfcheck_status SKIP 0 0
        return 0
    fi

    awk -F '\t' 'NF >= 4 { gsub(/\|/, "/", $1); gsub(/\|/, "/", $3); gsub(/\|/, "/", $4); gsub(/\|/, "/", $5); printf "%s|%s|%s|%s|%s\n", NR, $1, $3, $4, $5 }' "$ROOTFS_2ND_STORAGE_MIGRATE_LIST" > "$migration_rows" 2>/dev/null || true
    while IFS='|' read -r mig_line mig_label mig_src mig_target mig_kind; do
        [ -n "$mig_line" ] || continue
        migration_count=$((migration_count + 1))
        if [ -z "$mig_src" ] || [ -z "$mig_target" ]; then
            log "迁移链: line=$mig_line 字段不完整"
            migration_warnings=$((migration_warnings + 1))
            continue
        fi

        if [ ! -e "$mig_target" ]; then
            log "迁移链: ${mig_label:-line $mig_line} = 目标缺失 ($mig_target)"
            migration_warnings=$((migration_warnings + 1))
        fi

        if [ -L "$mig_src" ]; then
            mig_src_real="$(storage_expand_canonical_path "$mig_src" 2>/dev/null || true)"
            mig_target_real="$(storage_expand_canonical_path "$mig_target" 2>/dev/null || true)"
            if [ -n "$mig_src_real" ] && [ "$mig_src_real" = "$mig_target_real" ]; then
                log "迁移链: ${mig_label:-line $mig_line} = 正常 ($mig_src -> $mig_target, kind=${mig_kind:-?})"
            else
                log "迁移链: ${mig_label:-line $mig_line} = 源软链接目标不匹配 ($mig_src -> ${mig_src_real:-未知}, expect=$mig_target)"
                migration_warnings=$((migration_warnings + 1))
            fi
        elif storage_expand_path_has_child_links_to_target "$mig_src" "$mig_target"; then
            log "迁移链: ${mig_label:-line $mig_line} = 混合迁移正常 ($mig_src => $mig_target, kind=${mig_kind:-?})"
        else
            log "迁移链: ${mig_label:-line $mig_line} = 源路径未指向扩展盘 ($mig_src -> $mig_target)"
            migration_warnings=$((migration_warnings + 1))
        fi

        if storage_expand_path_has_self_loop_child_links "$mig_target"; then
            log "迁移链: ${mig_label:-line $mig_line} = 目标目录存在自指软链接风险 ($mig_target)"
            migration_warnings=$((migration_warnings + 1))
        fi
    done < "$migration_rows"

    if [ "$migration_count" -eq 0 ]; then
        log "迁移链: 迁移记录格式异常，未解析到有效条目"
        migration_warnings=$((migration_warnings + 1))
    else
        log "迁移链: 已检查 $migration_count 条迁移记录"
    fi

    if [ "$migration_warnings" -gt 0 ]; then
        set_last_selfcheck_status WARN 0 "$migration_warnings"
    else
        set_last_selfcheck_status PASS 0 0
    fi
}

run_unified_c2000max_storage_card_health_check() {
    local c2k_model="${1:-$(unified_detect_model_name 2>/dev/null || true)}"
    c2k_warnings=0
    c2k_storage_mount="$(detect_c2000max_storage_mount 2>/dev/null || true)"

    selfcheck_print_header "${c2k_model#NRadio_} 存储卡健康"
    if [ -z "$c2k_storage_mount" ]; then
        log "存储卡: 未检测到 ${c2k_model#NRadio_} 存储卡挂载"
        set_last_selfcheck_status WARN 0 1
        return 0
    fi

    log "存储卡: 挂载点=$c2k_storage_mount"
    unified_health_print_path_usage "${c2k_model#NRadio_} 存储卡" "$c2k_storage_mount" || c2k_warnings=$((c2k_warnings + 1))
    if openlist_dir_is_writable "$c2k_storage_mount"; then
        log "存储卡: 写入测试 = 正常"
    else
        log "存储卡: 写入测试 = 失败"
        c2k_warnings=$((c2k_warnings + 1))
    fi

    c2k_tmp_free="$(unified_num_or_zero "$(unified_health_path_free_kib /tmp 2>/dev/null || true)")"
    c2k_storage_free="$(unified_num_or_zero "$(unified_health_path_free_kib "$c2k_storage_mount" 2>/dev/null || true)")"
    log "OpenList: /tmp 可用=$(unified_health_kib_display "$c2k_tmp_free") 存储卡可用=$(unified_health_kib_display "$c2k_storage_free")"
    if [ "$c2k_storage_free" -lt 262144 ] 2>/dev/null; then
        log "OpenList: 存储卡可用空间低于 256M，大包下载或解压风险偏高"
        c2k_warnings=$((c2k_warnings + 1))
    fi

    if [ "$c2k_warnings" -gt 0 ]; then
        set_last_selfcheck_status WARN 0 "$c2k_warnings"
    else
        set_last_selfcheck_status PASS 0 0
    fi
}

run_unified_big_package_risk_check() {
    risk_warnings=0
    detected_model="$(unified_detect_model_name 2>/dev/null || true)"
    mem_available_kib="$(unified_num_or_zero "$(unified_health_mem_kib MemAvailable)")"
    [ "$mem_available_kib" -gt 0 ] 2>/dev/null || mem_available_kib="$(unified_num_or_zero "$(unified_health_mem_kib MemFree)")"
    swap_free_kib="$(unified_num_or_zero "$(unified_health_mem_kib SwapFree)")"
    work_mem_kib="$((mem_available_kib + swap_free_kib))"
    tmp_free_kib="$(unified_num_or_zero "$(unified_health_path_free_kib /tmp 2>/dev/null || true)")"
    overlay_free_kib="$(unified_num_or_zero "$(unified_health_path_free_kib /overlay 2>/dev/null || true)")"
    storage_mount=''
    github_code="$(curl -L -m 8 -s -o /dev/null -w '%{http_code}' https://github.com/ 2>/dev/null || true)"

    selfcheck_print_header "大包安装风险检查"
    log "资源:   可用内存+swap=$(unified_health_kib_display "$work_mem_kib") /tmp 可用=$(unified_health_kib_display "$tmp_free_kib") /overlay 可用=$(unified_health_kib_display "$overlay_free_kib")"

    case "$github_code" in
        200|301|302|403)
            log "网络:   GitHub 连通性 = 可达 (HTTP $github_code)"
            ;;
        *)
            log "网络:   GitHub 连通性 = 异常或超时 (HTTP ${github_code:-000})"
            risk_warnings=$((risk_warnings + 1))
            ;;
    esac

    if [ "$work_mem_kib" -lt 262144 ] 2>/dev/null; then
        log "风险:   可用内存+swap 低于 256M，文件过大时可能下载、校验或解压失败，甚至被系统 Killed"
        risk_warnings=$((risk_warnings + 1))
    fi
    if [ "$tmp_free_kib" -lt 98304 ] 2>/dev/null; then
        log "风险:   /tmp 可用空间低于 96M，大包落在 /tmp 时容易失败"
        risk_warnings=$((risk_warnings + 1))
    fi
    if [ "$overlay_free_kib" -lt 65536 ] 2>/dev/null; then
        log "风险:   /overlay 可用空间低于 64M，插件文件写入空间偏紧"
        risk_warnings=$((risk_warnings + 1))
    fi

    if [ "$detected_model" = 'NRadio_C2000MAX' ]; then
        storage_mount="$(detect_c2000max_storage_mount 2>/dev/null || true)"
        if [ -n "$storage_mount" ] && [ -w "$storage_mount" ]; then
            log "OpenList: C2000MAX 文件过大风险已降级：安装链会使用 lite 包，并把下载包与解压目录放到存储卡 ($storage_mount)"
        else
            log "OpenList: 高风险：C2000MAX 未检测到可写存储卡，文件过大时可能下载失败、解压失败或被系统 Killed"
            risk_warnings=$((risk_warnings + 1))
        fi
    else
        log "OpenList: 常规安装路径"
    fi

    [ -f "$FEEDS" ] && log "OpenVPN: 软件源文件存在 ($FEEDS)" || {
        log "OpenVPN: 软件源文件缺失，后续依赖解析可能失败"
        risk_warnings=$((risk_warnings + 1))
    }
    log "AdGuardHome: 将重点受 GitHub/CDN、/overlay 空间和运行内存影响"

    if [ "$risk_warnings" -gt 0 ]; then
        set_last_selfcheck_status WARN 0 "$risk_warnings"
    else
        set_last_selfcheck_status PASS 0 0
    fi
}

unified_preflight_warn() {
    log "$1"
    UNIFIED_PREFLIGHT_WARNINGS=$((UNIFIED_PREFLIGHT_WARNINGS + 1))
}

unified_preflight_check_tool() {
    tool_name="$1"
    if command -v "$tool_name" >/dev/null 2>&1; then
        log "预检:   tool $tool_name = 存在"
    else
        unified_preflight_warn "预检:   tool $tool_name = 缺失，部分安装或诊断步骤可能失败"
    fi
}

unified_preflight_check_space() {
    space_label="$1"
    space_path="$2"
    min_mib="$3"

    free_kib="$(unified_num_or_zero "$(unified_health_path_free_kib "$space_path" 2>/dev/null || true)")"
    need_kib=$((min_mib * 1024))
    if [ "$free_kib" -ge "$need_kib" ] 2>/dev/null; then
        log "预检:   $space_label = 可用 $(unified_health_kib_display "$free_kib")，满足建议值 ${min_mib}M"
    else
        unified_preflight_warn "预检:   $space_label = 可用 $(unified_health_kib_display "$free_kib")，低于建议值 ${min_mib}M，文件过大时可能失败"
    fi
}

unified_preflight_check_urls() {
    source_label="$1"
    source_urls="$2"

    if [ -n "$source_urls" ]; then
        log "预检:   $source_label 下载源 = $(summarize_url_hosts $source_urls)"
    else
        unified_preflight_warn "预检:   $source_label 下载源 = 未解析"
    fi
}

unified_preflight_check_feed_package() {
    package_label="$1"
    package_name="$2"

    installed_version="$(get_installed_package_version "$package_name" 2>/dev/null || true)"
    if [ -n "$installed_version" ]; then
        log "预检:   $package_label = 已安装 ($package_name $installed_version)"
        return 0
    fi

    if [ ! -f "$FEEDS" ]; then
        unified_preflight_warn "预检:   $package_label = 软件源文件缺失，无法解析 $package_name"
        return 0
    fi

    package_meta="$(resolve_package_meta_any_feed "$package_name" 2>/dev/null || true)"
    if [ -n "$package_meta" ]; then
        package_feed="${package_meta%%|*}"
        package_rest="${package_meta#*|}"
        package_rest="${package_rest#*|}"
        package_file="${package_rest%%|*}"
        package_version="${package_meta##*|}"
        log "预检:   $package_label = 可解析 ($package_name ${package_version:-unknown}, feed=$package_feed, file=$package_file)"
    else
        unified_preflight_warn "预检:   $package_label = 当前软件源无法解析 $package_name"
    fi
}

run_unified_install_preflight_check() {
    UNIFIED_PREFLIGHT_WARNINGS=0
    detected_model="$(unified_detect_model_name 2>/dev/null || true)"
    target_arch="$(get_primary_arch 2>/dev/null || true)"
    [ -n "$target_arch" ] || target_arch="$(unified_detect_arch_name)"
    storage_mount=''
    openlist_preflight_asset="$OPENLIST_ASSET_NAME"

    selfcheck_print_header "安装前一键预检"
    log "环境:   机型=${detected_model:-未知} 架构=${target_arch:-未知}"

    for tool_name in uci opkg curl tar awk df; do
        unified_preflight_check_tool "$tool_name"
    done

    unified_preflight_check_space "/tmp" "/tmp" 128
    unified_preflight_check_space "/overlay" "/overlay" 64
    if [ "${detected_model:-}" = 'NRadio_C2000MAX' ]; then
        storage_mount="$(detect_c2000max_storage_mount 2>/dev/null || true)"
        if [ -n "$storage_mount" ]; then
            unified_preflight_check_space "C2000MAX 存储卡" "$storage_mount" 256
            openlist_preflight_asset="openlist-linux-musl-arm64-lite.tar.gz"
            log "预检:   OpenList = C2000MAX 将使用 lite 包并落到存储卡，降低文件过大和 OOM 风险"
        else
            unified_preflight_warn "预检:   OpenList = C2000MAX 未检测到存储卡，文件过大时可能下载失败、解压失败或被系统 Killed"
        fi
    fi

    unified_preflight_check_urls "OpenList" "https://gh-proxy.com/https://github.com/OpenListTeam/OpenList/releases/latest/download/${openlist_preflight_asset} https://github.com/OpenListTeam/OpenList/releases/latest/download/${openlist_preflight_asset} https://api.github.com/repos/OpenListTeam/OpenList/releases/latest https://release-assets.githubusercontent.com/"
    unified_preflight_check_urls "AdGuardHome" "$ADGUARDHOME_IPK_URLS"
    unified_preflight_check_urls "DDNS-GO" "$DDNSGO_DOWNLOAD_URLS"
    unified_preflight_check_urls "MosDNS" "$MOSDNS_DOWNLOAD_URLS"

    unified_preflight_check_feed_package "OpenVPN LuCI" "luci-app-openvpn"
    unified_preflight_check_feed_package "OpenVPN 核心" "openvpn-openssl"
    unified_preflight_check_feed_package "OpenVPN LZO" "liblzo2"
    unified_preflight_check_feed_package "ZeroTier" "$ZEROTIER_PACKAGE_NAME"

    if [ "$target_arch" = "$DDNSGO_PACKAGE_ARCH" ]; then
        log "预检:   DDNS-GO 架构 = 匹配 ($target_arch)"
    else
        unified_preflight_warn "预检:   DDNS-GO 架构 = 当前 $target_arch，内置包要求 $DDNSGO_PACKAGE_ARCH"
    fi

    if [ "$UNIFIED_PREFLIGHT_WARNINGS" -gt 0 ]; then
        set_last_selfcheck_status WARN 0 "$UNIFIED_PREFLIGHT_WARNINGS"
    else
        set_last_selfcheck_status PASS 0 0
    fi
}

unified_install_log_filter_noise() {
    sed "/opkg_conf_deinit: Couldn't unlink \/var\/lock\/opkg\.lock: No such file or directory/d; /Updated list of available packages in Collected errors:/d; /^uci: Entry not found$/d; /^[0-9][0-9]*:uci: Entry not found$/d; /^uci: Invalid argument$/d; /^[0-9][0-9]*:uci: Invalid argument$/d; /^Command failed: Not found$/d; /^[0-9][0-9]*:Command failed: Not found$/d"
}

unified_install_log_without_noise() {
    log_file="$1"
    unified_install_log_filter_noise < "$log_file" 2>/dev/null || true
}

unified_install_log_noise_note() {
    log_file="$1"
    log_label="$2"

    if grep -Fq "opkg_conf_deinit: Couldn't unlink /var/lock/opkg.lock: No such file or directory." "$log_file" 2>/dev/null; then
        log "噪声:   $log_label = opkg lock 清理残留，已从失败判定中忽略"
    fi
    if grep -Fq "Updated list of available packages in Collected errors:" "$log_file" 2>/dev/null; then
        log "噪声:   $log_label = opkg 输出混行，已从失败判定中忽略"
    fi
    if grep -Eq '^(uci: Entry not found|uci: Invalid argument|Command failed: Not found)$' "$log_file" 2>/dev/null; then
        log "噪声:   $log_label = UCI 清理残留，已从失败判定中忽略"
    fi
}

unified_install_stage_error_line() {
    stage_log_file="$1"
    grep -Ein 'error|failed|fail|cannot|missing|not found|No space|parse_from_stream|Missing new line|Collected errors|incompatible|architecture|dependency|depends|timeout|invalid|corrupt|Unknown package' "$stage_log_file" 2>/dev/null | unified_install_log_filter_noise | sed -n '1p' || true
}

unified_install_stage_check() {
    stage_label="$1"
    stage_log_file="$2"

    if [ ! -f "$stage_log_file" ]; then
        log "阶段:   $stage_label = NOLOG log=$stage_log_file"
        return 0
    fi

    if [ ! -s "$stage_log_file" ]; then
        log "阶段:   $stage_label = EMPTY log=$stage_log_file"
        return 0
    fi

    stage_error_line="$(unified_install_stage_error_line "$stage_log_file")"
    if [ -n "$stage_error_line" ]; then
        stage_error_lineno="${stage_error_line%%:*}"
        log "阶段:   $stage_label = FAIL log=$stage_log_file line=$stage_error_lineno"
        printf '%s\n' "$stage_error_line" | sed 's/^/命中:   /'
        UNIFIED_INSTALL_STAGE_WARNINGS=$((UNIFIED_INSTALL_STAGE_WARNINGS + 1))
        if [ -z "$UNIFIED_LAST_FAILED_STAGE" ]; then
            UNIFIED_LAST_FAILED_STAGE="$stage_label"
            UNIFIED_LAST_FAILED_LOG="$stage_log_file"
            UNIFIED_LAST_FAILED_LINE="$stage_error_lineno"
        fi
    else
        log "阶段:   $stage_label = PASS log=$stage_log_file"
    fi
}

run_unified_install_failure_stage_summary() {
    UNIFIED_INSTALL_STAGE_WARNINGS=0
    UNIFIED_LAST_FAILED_STAGE=''
    UNIFIED_LAST_FAILED_LOG=''
    UNIFIED_LAST_FAILED_LINE=''

    selfcheck_print_header "安装失败阶段"
    unified_install_stage_check "opkg update" "$WORKDIR/nradio-plugin-opkg.update.log"
    unified_install_stage_check "opkg 依赖" "$WORKDIR/nradio-plugin-opkg.install.log"
    unified_install_stage_check "通用 ipk" "$WORKDIR/nradio-plugin-ipk.install.log"
    unified_install_stage_check "$OPENCLASH_DISPLAY_NAME 安装" "$WORKDIR/openclash-install.log"

    if [ -n "$UNIFIED_LAST_FAILED_STAGE" ]; then
        log "last_install=$UNIFIED_LAST_FAILED_STAGE status=FAIL log=$UNIFIED_LAST_FAILED_LOG line=$UNIFIED_LAST_FAILED_LINE"
    else
        log "last_install=none status=PASS"
    fi

    if [ "$UNIFIED_INSTALL_STAGE_WARNINGS" -gt 0 ]; then
        set_last_selfcheck_status WARN 0 "$UNIFIED_INSTALL_STAGE_WARNINGS"
    else
        set_last_selfcheck_status PASS 0 0
    fi
}

unified_install_log_match() {
    log_file="$1"
    match_label="$2"
    match_pattern="$3"

    if unified_install_log_without_noise "$log_file" | grep -Eiq "$match_pattern" 2>/dev/null; then
        log "命中:   $match_label"
        UNIFIED_INSTALL_LOG_WARNINGS=$((UNIFIED_INSTALL_LOG_WARNINGS + 1))
    fi
}

unified_install_log_summary_one() {
    log_label="$1"
    log_file="$2"

    if [ ! -f "$log_file" ]; then
        log "日志:   $log_label = 未找到 ($log_file)"
        return 0
    fi

    log_size="$(wc -c < "$log_file" 2>/dev/null | tr -d ' ' || printf '0')"
    [ -n "$log_size" ] || log_size='0'
    log "日志:   $log_label = $log_file (${log_size} bytes)"
    if [ ! -s "$log_file" ]; then
        log "摘要:   $log_label = 空日志"
        return 0
    fi

    unified_install_log_noise_note "$log_file" "$log_label"
    unified_install_log_match "$log_file" "空间不足" 'No space left|not enough space|insufficient space'
    unified_install_log_match "$log_file" "文件或路径缺失" 'No such file or directory'
    unified_install_log_match "$log_file" "依赖缺失" 'Cannot satisfy|dependency|depends|missing|not found|Unknown package'
    unified_install_log_match "$log_file" "opkg 数据解析" 'parse_from_stream|Missing new line|status file|Collected errors'
    unified_install_log_match "$log_file" "下载/网络" 'wget|curl|timeout|Failed to download|Connection|SSL|TLS|resolve'
    unified_install_log_match "$log_file" "架构/包格式" 'architecture|incompatible|invalid|corrupt|control.tar|data.tar|debian-binary'

    key_lines="$(grep -Ein 'error|failed|fail|cannot|missing|not found|No space|parse_from_stream|Missing new line|Collected errors|incompatible|architecture|dependency|depends|timeout|invalid|corrupt' "$log_file" 2>/dev/null | unified_install_log_filter_noise | sed -n '1,20p' || true)"
    if [ -n "$key_lines" ]; then
        log "摘要:   $log_label 关键行:"
        printf '%s\n' "$key_lines"
    fi

    log "尾部:   $log_label 最近 30 行:"
    tail -n 30 "$log_file" 2>/dev/null || true
}

run_unified_install_log_summary() {
    UNIFIED_INSTALL_LOG_WARNINGS=0

    selfcheck_print_header "安装日志摘要"
    unified_install_log_summary_one "$OPENCLASH_DISPLAY_NAME 安装" "$WORKDIR/openclash-install.log"
    unified_install_log_summary_one "opkg update" "$WORKDIR/nradio-plugin-opkg.update.log"
    unified_install_log_summary_one "opkg 依赖安装" "$WORKDIR/nradio-plugin-opkg.install.log"
    unified_install_log_summary_one "通用 ipk 安装" "$WORKDIR/nradio-plugin-ipk.install.log"

    if [ "$UNIFIED_INSTALL_LOG_WARNINGS" -gt 0 ]; then
        set_last_selfcheck_status WARN 0 "$UNIFIED_INSTALL_LOG_WARNINGS"
    else
        set_last_selfcheck_status PASS 0 0
    fi
}

unified_opkg_hakimi_warn() {
    log "$1"
    UNIFIED_OPKG_HAKIMI_WARNINGS=$((UNIFIED_OPKG_HAKIMI_WARNINGS + 1))
}

unified_opkg_hakimi_package_check() {
    package_name="$1"

    if opkg status "$package_name" 2>/dev/null | grep -q '^Status: .* installed'; then
        log "依赖:   $package_name = 已安装"
        return 0
    fi

    package_meta="$(resolve_package_meta_any_feed "$package_name" 2>/dev/null || true)"
    if [ -n "$package_meta" ]; then
        package_feed="${package_meta%%|*}"
        package_version="${package_meta##*|}"
        [ -n "$package_version" ] || package_version='unknown'
        log "依赖:   $package_name = 可解析 (feed=$package_feed version=$package_version)"
        return 0
    fi

    unified_opkg_hakimi_warn "依赖:   $package_name = 当前软件源无法解析"
}

run_unified_opkg_openclash_readiness_check() {
    UNIFIED_OPKG_HAKIMI_WARNINGS=0

    selfcheck_print_header "opkg 与 $OPENCLASH_DISPLAY_NAME 安装就绪"

    if command -v opkg >/dev/null 2>&1; then
        log "工具:   opkg = 可用"
    else
        unified_opkg_hakimi_warn "工具:   opkg = 缺失"
    fi

    if [ -e "$OPKG_LOCK_FILE" ]; then
        unified_opkg_hakimi_warn "opkg锁: $OPKG_LOCK_FILE = 存在"
    else
        log "opkg锁: $OPKG_LOCK_FILE = 未占用"
    fi

    if [ -f "$FEEDS" ]; then
        enabled_feed_count="$(awk '$1=="src/gz" {c++} END{print c+0}' "$FEEDS" 2>/dev/null || printf '0')"
        log "opkg源: $FEEDS = ${enabled_feed_count} 个启用源"
        if awk '$1 == "src/gz" && $3 ~ /^https?:\/\// { found = 1 } END { exit(found ? 0 : 1) }' "$FEEDS" 2>/dev/null; then
            log "opkg源: 已保留固件现有源，HTTP(S) 地址校验通过"
        else
            unified_opkg_hakimi_warn "opkg源: 未发现有效的 HTTP(S) src/gz 条目"
        fi
    else
        unified_opkg_hakimi_warn "opkg源: $FEEDS = 缺失"
    fi

    opkg_status_file="/usr/lib/opkg/status"
    if [ -s "$opkg_status_file" ]; then
        opkg_status_size="$(wc -c < "$opkg_status_file" 2>/dev/null | tr -d ' ' || printf '0')"
        [ -n "$opkg_status_size" ] || opkg_status_size='0'
        log "opkg库: $opkg_status_file = ${opkg_status_size} bytes"
        if command -v tail >/dev/null 2>&1 && command -v od >/dev/null 2>&1; then
            status_last_byte="$(tail -c 1 "$opkg_status_file" 2>/dev/null | od -An -tx1 2>/dev/null | tr -d ' \n' || true)"
            if [ "$status_last_byte" = '0a' ]; then
                log "opkg库: status 末尾换行 = 正常"
            else
                unified_opkg_hakimi_warn "opkg库: status 末尾换行 = 异常 (Missing new line character)"
            fi
        else
            log "opkg库: status 末尾换行 = 缺少 tail/od，跳过"
        fi
    else
        unified_opkg_hakimi_warn "opkg库: $opkg_status_file = 缺失或为空"
    fi

    if opkg status >/dev/null 2>&1; then
        log "opkg库: status 读取 = 正常"
    else
        unified_opkg_hakimi_warn "opkg库: status 读取 = 异常"
    fi

    for package_name in dnsmasq-full bash curl ca-bundle ip-full ruby ruby-yaml kmod-tun unzip; do
        unified_opkg_hakimi_package_check "$package_name"
    done

    if [ -f /etc/config/openclash ]; then
        log "$OPENCLASH_DISPLAY_NAME: 配置文件 = 存在"
    else
        log "$OPENCLASH_DISPLAY_NAME: 配置文件 = 未安装"
    fi
    if [ -f /usr/lib/lua/luci/controller/openclash.lua ]; then
        log "$OPENCLASH_DISPLAY_NAME: LuCI 控制器 = 存在"
    else
        log "$OPENCLASH_DISPLAY_NAME: LuCI 控制器 = 未安装"
    fi
    if [ -x /etc/init.d/openclash ]; then
        log "$OPENCLASH_DISPLAY_NAME: 服务脚本 = 存在"
    else
        log "$OPENCLASH_DISPLAY_NAME: 服务脚本 = 未安装"
    fi
    if openclash_asn_mmdb_valid; then
        log "$OPENCLASH_DISPLAY_NAME: ASN.mmdb = 正常"
    else
        unified_opkg_hakimi_warn "$OPENCLASH_DISPLAY_NAME: ASN.mmdb = 缺失或异常"
    fi

    if [ "$UNIFIED_OPKG_HAKIMI_WARNINGS" -gt 0 ]; then
        set_last_selfcheck_status WARN 0 "$UNIFIED_OPKG_HAKIMI_WARNINGS"
    else
        set_last_selfcheck_status PASS 0 0
    fi
}

unified_feed_index_warn() {
    log "$1"
    UNIFIED_FEED_INDEX_WARNINGS=$((UNIFIED_FEED_INDEX_WARNINGS + 1))
}

unified_feed_index_candidate_state() {
    feed_name="$1"
    feed_url="$2"
    found_candidate='0'

    for feed_idx in "/var/opkg-lists/$feed_name" "/tmp/opkg-lists/$feed_name"; do
        [ -s "$feed_idx" ] || continue
        found_candidate='1'
        if feed_index_is_plain_packages "$feed_idx"; then
            pkg_count="$(awk '/^Package: / { c++ } END { print c + 0 }' "$feed_idx" 2>/dev/null || printf '0')"
            log "feed:    $feed_name = 明文索引 OK packages=${pkg_count:-0} path=$feed_idx"
            return 0
        fi
        if [ -n "$feed_url" ]; then
            remote_feed_idx="$(download_feed_index_file "$feed_name" "$feed_url" 2>/dev/null || true)"
            if [ -n "$remote_feed_idx" ] && [ -s "$remote_feed_idx" ]; then
                pkg_count="$(awk '/^Package: / { c++ } END { print c + 0 }' "$remote_feed_idx" 2>/dev/null || printf '0')"
                log "feed:    $feed_name = 本地索引不可直读，远端明文 OK packages=${pkg_count:-0}"
                return 0
            fi
        fi
        unified_feed_index_warn "feed:    $feed_name = 本地索引不可直读，远端明文也不可用 path=$feed_idx"
        return 0
    done

    if [ "$found_candidate" != '1' ]; then
        if [ -n "$feed_url" ]; then
            remote_feed_idx="$(download_feed_index_file "$feed_name" "$feed_url" 2>/dev/null || true)"
            if [ -n "$remote_feed_idx" ] && [ -s "$remote_feed_idx" ]; then
                pkg_count="$(awk '/^Package: / { c++ } END { print c + 0 }' "$remote_feed_idx" 2>/dev/null || printf '0')"
                log "feed:    $feed_name = 本地索引缺失，远端明文 OK packages=${pkg_count:-0}"
                return 0
            fi
        fi
        unified_feed_index_warn "feed:    $feed_name = 本地索引缺失，远端明文不可用"
    fi
}

run_unified_feed_index_health_check() {
    UNIFIED_FEED_INDEX_WARNINGS=0
    selfcheck_print_header "opkg feed 明文索引体检"

    if [ ! -f "$FEEDS" ]; then
        unified_feed_index_warn "feed:    $FEEDS = 缺失"
        set_last_selfcheck_status WARN 0 "$UNIFIED_FEED_INDEX_WARNINGS"
        return 0
    fi

    feed_lines="$(awk '$1=="src/gz" { print $2 "|" $3 }' "$FEEDS" 2>/dev/null || true)"
    if [ -z "$feed_lines" ]; then
        unified_feed_index_warn "feed:    $FEEDS = 没有启用 src/gz 源"
        set_last_selfcheck_status WARN 0 "$UNIFIED_FEED_INDEX_WARNINGS"
        return 0
    fi

    old_ifs="$IFS"
    IFS='
'
    for feed_line in $feed_lines; do
        IFS="$old_ifs"
        feed_name="${feed_line%%|*}"
        feed_url="${feed_line#*|}"
        [ -n "$feed_name" ] || continue
        if [ -n "$feed_url" ]; then
            log "feed:    $feed_name url=$(extract_url_host "$feed_url" 2>/dev/null || printf '%s' "$feed_url")"
        else
            unified_feed_index_warn "feed:    $feed_name = URL 为空"
        fi
        unified_feed_index_candidate_state "$feed_name" "$feed_url"
        IFS='
'
    done
    IFS="$old_ifs"

    if [ "$UNIFIED_FEED_INDEX_WARNINGS" -gt 0 ]; then
        set_last_selfcheck_status WARN 0 "$UNIFIED_FEED_INDEX_WARNINGS"
    else
        set_last_selfcheck_status PASS 0 0
    fi
}

unified_runtime_warn() {
    log "$1"
    UNIFIED_RUNTIME_WARNINGS=$((UNIFIED_RUNTIME_WARNINGS + 1))
}

unified_path_inode_usage() {
    path_label="$1"
    target_path="$2"

    [ -e "$target_path" ] || {
        unified_runtime_warn "inode:  $path_label = 不存在 ($target_path)"
        return 0
    }

    inode_line="$(df -iP "$target_path" 2>/dev/null | awk 'NR == 2 { print $2 "|" $3 "|" $4 "|" $5 "|" $6; exit }' || true)"
    if [ -z "$inode_line" ]; then
        log "inode:  $path_label = 系统不支持 inode 统计"
        return 0
    fi

    inode_total="${inode_line%%|*}"
    inode_rest="${inode_line#*|}"
    inode_used="${inode_rest%%|*}"
    inode_rest="${inode_rest#*|}"
    inode_free="${inode_rest%%|*}"
    inode_rest="${inode_rest#*|}"
    inode_pct="${inode_rest%%|*}"
    inode_mount="${inode_rest#*|}"
    log "inode:  $path_label = 可用 ${inode_free:-?} / 总 ${inode_total:-?} (${inode_pct:-?} 已用, mount=${inode_mount:-?})"
    inode_pct_num="$(printf '%s\n' "${inode_pct:-0}" | tr -d '%' 2>/dev/null || printf '0')"
    case "$inode_pct_num" in
        ''|*[!0-9]*)
            ;;
        *)
            [ "$inode_pct_num" -ge 90 ] 2>/dev/null && unified_runtime_warn "inode:  $path_label = inode 使用率过高 (${inode_pct})"
            ;;
    esac
    return 0
}

run_unified_runtime_pressure_check() {
    UNIFIED_RUNTIME_WARNINGS=0
    selfcheck_print_header "运行负载与锁"

    load_line="$(cat /proc/loadavg 2>/dev/null | sed -n '1p' || true)"
    cpu_count="$(grep -c '^processor' /proc/cpuinfo 2>/dev/null || printf '1')"
    case "$cpu_count" in
        ''|*[!0-9]*|0) cpu_count='1' ;;
    esac
    if [ -n "$load_line" ]; then
        load1="${load_line%% *}"
        log "负载:   loadavg=$load_line cpu=$cpu_count"
        load_warn="$(awk -v load="$load1" -v cpu="$cpu_count" 'BEGIN { if ((load + 0) > (cpu * 2.5)) print 1; else print 0 }' 2>/dev/null || printf '0')"
        [ "$load_warn" = '1' ] && unified_runtime_warn "负载:   1分钟负载偏高，当前 ${load1} / CPU ${cpu_count}"
    else
        unified_runtime_warn "负载:   无法读取 /proc/loadavg"
    fi

    if [ -d "$LOCK_DIR" ]; then
        lock_pid="$(cat "$LOCK_DIR/pid" 2>/dev/null || true)"
        if [ -n "$lock_pid" ] && [ "$lock_pid" != "$$" ] && kill -0 "$lock_pid" 2>/dev/null; then
            unified_runtime_warn "脚本锁: 被其它进程占用 pid=$lock_pid dir=$LOCK_DIR"
        else
            log "脚本锁: 当前脚本持有或残留无活动进程 dir=$LOCK_DIR pid=${lock_pid:-未知}"
        fi
    else
        log "脚本锁: 未发现 $LOCK_DIR"
    fi

    if [ -e "$OPKG_LOCK_FILE" ]; then
        unified_runtime_warn "opkg锁: 存在 $OPKG_LOCK_FILE"
    else
        log "opkg锁: 未占用"
    fi

    process_count="$(ps 2>/dev/null | wc -l | tr -d ' ' || printf '0')"
    log "进程:   当前进程数=${process_count:-0}"

    unified_path_inode_usage "/tmp" "/tmp"
    unified_path_inode_usage "/overlay" "/overlay"

    if [ "$UNIFIED_RUNTIME_WARNINGS" -gt 0 ]; then
        set_last_selfcheck_status WARN 0 "$UNIFIED_RUNTIME_WARNINGS"
    else
        set_last_selfcheck_status PASS 0 0
    fi
}

run_unified_kernel_storage_log_check() {
    kernel_log_warnings=0
    kernel_log_hits="$WORKDIR/kernel-storage-errors.log"
    kernel_log_pattern='out of memory|killed process|I/O error|Buffer I/O error|read-only file system|read-only filesystem|EXT4-fs error|F2FS-fs.*error|mmc.*error|blk_update_request|segfault|kernel panic|Call Trace|watchdog.*BUG|UBI error'
    : > "$kernel_log_hits"

    selfcheck_print_header "内核与存储错误摘要"
    if command -v dmesg >/dev/null 2>&1; then
        dmesg 2>/dev/null | grep -Ei "$kernel_log_pattern" | tail -n 8 >> "$kernel_log_hits" 2>/dev/null || true
    else
        log "日志:   dmesg 不可用"
    fi
    if command -v logread >/dev/null 2>&1; then
        logread 2>/dev/null | grep -Ei "$kernel_log_pattern" | tail -n 8 >> "$kernel_log_hits" 2>/dev/null || true
    else
        log "日志:   logread 不可用"
    fi

    if [ -s "$kernel_log_hits" ]; then
        log "日志:   发现 OOM/I/O/F2FS/mmc/只读文件系统等关键标记"
        sed -n '1,12p' "$kernel_log_hits" 2>/dev/null | sed 's/^/日志:   /'
        kernel_log_warnings=1
    else
        log "日志:   未发现 OOM/I/O/F2FS/mmc/只读文件系统等关键标记"
    fi

    if [ "$kernel_log_warnings" -gt 0 ]; then
        set_last_selfcheck_status WARN 0 "$kernel_log_warnings"
    else
        set_last_selfcheck_status PASS 0 0
    fi
}

unified_any_path_present() {
    for present_path in "$@"; do
        [ -e "$present_path" ] && return 0
    done
    return 1
}

unified_matrix_service_state() {
    init_script="$1"
    [ -n "$init_script" ] || {
        printf '%s\n' '-'
        return 0
    }
    [ -x "$init_script" ] || {
        printf '%s\n' '缺失'
        return 0
    }

    if "$init_script" enabled >/dev/null 2>&1; then
        enabled_state='开机=yes'
    else
        enabled_state='开机=no'
    fi
    service_status="$( ( "$init_script" status 2>/dev/null || true ) | tr '\n' ' ' | sed 's/[[:space:]]\+/ /g; s/^ //; s/ $//' )"
    case "$service_status" in
        *running*|1)
            run_state='运行'
            ;;
        *)
            run_state='停止'
            ;;
    esac
    printf '%s\n' "$run_state/$enabled_state"
}

unified_matrix_appcenter_state() {
    app_name="$1"
    app_route="$2"

    case "$app_name" in
        '')
            printf '%s\n' '-'
            return 0
            ;;
        __webssh_template)
            if grep -q 'name:"Web SSH"' "$TPL" 2>/dev/null && grep -q 'nradioadv/system/webssh' "$TPL" 2>/dev/null; then
                printf '%s\n' '正常'
            else
                printf '%s\n' '异常'
            fi
            return 0
            ;;
    esac

    if selfcheck_appcenter_route_matches "$app_name" "$app_route"; then
        printf '%s\n' '正常'
    else
        printf '%s\n' '异常'
    fi
}

unified_matrix_print_plugin() {
    plugin_label="$1"
    install_paths="$2"
    init_script="$3"
    route_path="$4"
    app_name="$5"
    app_route="$6"
    installed_state='未安装'
    installed_flag='0'

    for install_path in $install_paths; do
        if unified_any_path_present "$install_path"; then
            installed_state='已安装'
            installed_flag='1'
            break
        fi
    done

    service_state='-'
    route_state='-'
    app_state='-'

    if [ "$installed_flag" = '1' ]; then
        service_state="$(unified_matrix_service_state "$init_script")"
        if [ -n "$route_path" ]; then
            if selfcheck_luci_route_ok "$route_path"; then
                route_state='正常'
            else
                route_state='异常'
                UNIFIED_MATRIX_WARNINGS=$((UNIFIED_MATRIX_WARNINGS + 1))
            fi
        fi
        app_state="$(unified_matrix_appcenter_state "$app_name" "$app_route")"
        [ "$app_state" = '异常' ] && UNIFIED_MATRIX_WARNINGS=$((UNIFIED_MATRIX_WARNINGS + 1))
        [ "$service_state" = '缺失' ] && UNIFIED_MATRIX_WARNINGS=$((UNIFIED_MATRIX_WARNINGS + 1))
    fi

    log "插件:   $plugin_label | 安装=$installed_state | 服务=$service_state | LuCI=$route_state | 应用商店=$app_state"
}

run_unified_plugin_health_matrix() {
    UNIFIED_MATRIX_WARNINGS=0
    selfcheck_print_header "插件健康矩阵"

    unified_matrix_print_plugin "$OPENCLASH_DISPLAY_NAME" "/usr/lib/lua/luci/controller/openclash.lua /etc/config/openclash" "/etc/init.d/openclash" "admin/services/openclash" "luci-app-openclash" "admin/services/openclash"
    unified_matrix_print_plugin "AdGuardHome" "/usr/lib/lua/luci/controller/AdGuardHome.lua /usr/bin/AdGuardHome/AdGuardHome" "/etc/init.d/AdGuardHome" "admin/services/AdGuardHome" "luci-app-adguardhome" "admin/services/AdGuardHome"
    unified_matrix_print_plugin "OpenList" "$OPENLIST_BIN_PATH /usr/lib/lua/luci/controller/nradio_adv/openlist.lua" "/etc/init.d/openlist" "nradioadv/system/openlist/basic" "OpenList" "nradioadv/system/openlist/basic"
    unified_matrix_print_plugin "MosDNS" "$MOSDNS_BIN $MOSDNS_CONTROLLER" "$MOSDNS_INIT" "nradioadv/system/mosdns/basic" "$MOSDNS_APP_NAME" "nradioadv/system/mosdns/basic"
    unified_matrix_print_plugin "$DDNSGO_APP_NAME" "$DDNSGO_BIN_PATH $DDNSGO_CONTROLLER" "$DDNSGO_INIT_FILE" "$DDNSGO_ROUTE" "$DDNSGO_APP_NAME" "$DDNSGO_ROUTE"
    unified_matrix_print_plugin "Web SSH / ttyd" "/usr/bin/ttyd /usr/lib/lua/luci/controller/nradio_adv/webssh.lua" "/etc/init.d/ttyd" "nradioadv/system/webssh" "__webssh_template" "nradioadv/system/webssh"
    unified_matrix_print_plugin "OpenVPN" "/usr/sbin/openvpn /usr/lib/lua/luci/controller/nradio_adv/openvpn_full.lua" "/etc/init.d/openvpn" "nradioadv/system/openvpnfull" "OpenVPN" "nradioadv/system/openvpnfull"
    unified_matrix_print_plugin "$EASYTIER_DISPLAY_NAME" "/usr/bin/easytier-core $EASYTIER_CONTROLLER" "/etc/init.d/easytier" "$EASYTIER_ROUTE" "$EASYTIER_DISPLAY_NAME" "$EASYTIER_ROUTE"
    unified_matrix_print_plugin "ZeroTier" "/usr/sbin/zerotier-one $ZEROTIER_CONTROLLER" "/etc/init.d/zerotier" "$ZEROTIER_ROUTE" "ZeroTier" "$ZEROTIER_ROUTE"

    if [ "$UNIFIED_MATRIX_WARNINGS" -gt 0 ]; then
        set_last_selfcheck_status WARN 0 "$UNIFIED_MATRIX_WARNINGS"
    else
        set_last_selfcheck_status PASS 0 0
    fi
}

unified_appcenter_warn() {
    log "$1"
    UNIFIED_APPCENTER_WARNINGS=$((UNIFIED_APPCENTER_WARNINGS + 1))
}

run_unified_appcenter_consistency_scan() {
    UNIFIED_APPCENTER_WARNINGS=0
    appcenter_dump="$WORKDIR/appcenter.unified.dump"
    appcenter_routes="$WORKDIR/appcenter.unified.routes"
    appcenter_names="$WORKDIR/appcenter.unified.names"
    appcenter_dup_routes="$WORKDIR/appcenter.unified.dup_routes"
    appcenter_dup_names="$WORKDIR/appcenter.unified.dup_names"
    : > "$appcenter_routes"
    : > "$appcenter_names"

    selfcheck_print_header "应用商店一致性扫描"
    if ! uci show appcenter > "$appcenter_dump" 2>/dev/null; then
        unified_appcenter_warn "应用商店: 无法读取 /etc/config/appcenter"
        set_last_selfcheck_status WARN 0 "$UNIFIED_APPCENTER_WARNINGS"
        return 0
    fi

    package_sections="$(awk -F= '$2 == "package_list" { sub(/^appcenter\./, "", $1); print $1 }' "$appcenter_dump" 2>/dev/null || true)"
    package_count="$(awk -F= '$2 == "package" { count++ } END { print count + 0 }' "$appcenter_dump" 2>/dev/null || printf '0')"
    list_count=0
    route_count=0
    controller_fallback_count=0

    for app_sec in $package_sections; do
        list_count=$((list_count + 1))
        app_name="$(uci -q get "appcenter.$app_sec.name" 2>/dev/null || true)"
        app_pkg="$(uci -q get "appcenter.$app_sec.pkg_name" 2>/dev/null || true)"
        app_parent="$(uci -q get "appcenter.$app_sec.parent" 2>/dev/null || true)"
        app_route="$(uci -q get "appcenter.$app_sec.luci_module_route" 2>/dev/null || true)"
        app_controller="$(uci -q get "appcenter.$app_sec.luci_module_file" 2>/dev/null || true)"

        [ -n "$app_name" ] || unified_appcenter_warn "应用商店: $app_sec name 为空"
        [ -n "$app_name" ] && printf '%s|%s\n' "$app_name" "$app_sec" >> "$appcenter_names"
        if [ -n "$app_route" ]; then
            route_count=$((route_count + 1))
            printf '%s|%s\n' "$app_route" "$app_sec" >> "$appcenter_routes"
        fi
        if [ -n "$app_controller" ] && [ -z "$app_route" ]; then
            if selfcheck_appcenter_controller_fallback_matches "$app_name" "$app_controller"; then
                controller_fallback_count=$((controller_fallback_count + 1))
                log "应用商店: $app_sec controller fallback 正常 ($app_name)"
            else
                unified_appcenter_warn "应用商店: $app_sec controller 存在但 route 为空 ($app_name)"
            fi
        fi
        [ -n "$app_route" ] && [ -z "$app_controller" ] && unified_appcenter_warn "应用商店: $app_sec route 存在但 controller 为空 ($app_name -> $app_route)"
        if [ -n "$app_parent" ] && [ -z "$(find_uci_section package "$app_parent" 2>/dev/null || true)" ]; then
            unified_appcenter_warn "应用商店: $app_sec parent=$app_parent 但缺少对应 package 主条目"
        fi
        [ -n "$app_pkg" ] || [ -n "$app_parent" ] || unified_appcenter_warn "应用商店: $app_sec pkg_name 与 parent 同时为空 ($app_name)"
    done

    if [ "$list_count" -eq 0 ]; then
        unified_appcenter_warn "应用商店: 未发现 package_list 条目"
    fi

    cut -d'|' -f1 "$appcenter_routes" 2>/dev/null | sed '/^$/d' | sort | uniq -d > "$appcenter_dup_routes" || true
    while IFS= read -r dup_route; do
        [ -n "$dup_route" ] || continue
        dup_secs="$(awk -F'|' -v route="$dup_route" '$1 == route { print $2 }' "$appcenter_routes" 2>/dev/null | tr '\n' ' ' | sed 's/[[:space:]]\+/ /g; s/^ //; s/ $//' || true)"
        unified_appcenter_warn "应用商店: route 重复 ($dup_route) sections=${dup_secs:-未知}"
    done < "$appcenter_dup_routes"

    cut -d'|' -f1 "$appcenter_names" 2>/dev/null | sed '/^$/d' | sort | uniq -d > "$appcenter_dup_names" || true
    while IFS= read -r dup_name; do
        [ -n "$dup_name" ] || continue
        dup_secs="$(awk -F'|' -v name="$dup_name" '$1 == name { print $2 }' "$appcenter_names" 2>/dev/null | tr '\n' ' ' | sed 's/[[:space:]]\+/ /g; s/^ //; s/ $//' || true)"
        unified_appcenter_warn "应用商店: name 重复 ($dup_name) sections=${dup_secs:-未知}"
    done < "$appcenter_dup_names"

    log "应用商店: package=${package_count:-0} package_list=$list_count route=$route_count fallback=$controller_fallback_count warnings=$UNIFIED_APPCENTER_WARNINGS"
    if [ "$UNIFIED_APPCENTER_WARNINGS" -gt 0 ]; then
        set_last_selfcheck_status WARN 0 "$UNIFIED_APPCENTER_WARNINGS"
    else
        set_last_selfcheck_status PASS 0 0
    fi
}

unified_port_warn() {
    log "$1"
    UNIFIED_PORT_WARNINGS=$((UNIFIED_PORT_WARNINGS + 1))
}

unified_listen_lines_for_port() {
    listen_port="$1"
    if command -v ss >/dev/null 2>&1; then
        ss -lntup 2>/dev/null | awk -v port="$listen_port" '$0 ~ (":" port "[[:space:]]") { print }'
    elif command -v netstat >/dev/null 2>&1; then
        netstat -lntup 2>/dev/null | awk -v port="$listen_port" '$0 ~ (":" port "[[:space:]]") { print }'
    else
        return 1
    fi
}

unified_port_has_process_detail() {
    grep -Eq 'users:|/[[:alnum:]_.-]+'
}

unified_check_port_owner() {
    port_label="$1"
    port_number="$2"
    expected_text="$3"
    installed_paths="$4"
    require_listen="$5"

    [ -n "$port_number" ] || return 0
    case "$port_number" in
        ''|*[!0-9]*)
            unified_port_warn "端口:   $port_label = 端口值异常 ($port_number)"
            return 0
            ;;
    esac

    installed_flag='0'
    for installed_path in $installed_paths; do
        [ -e "$installed_path" ] && installed_flag='1'
    done

    listen_lines="$(unified_listen_lines_for_port "$port_number" 2>/dev/null | sed -n '1,3p' || true)"
    if [ -z "$listen_lines" ]; then
        if [ "$installed_flag" = '1' ] && [ "$require_listen" = '1' ]; then
            unified_port_warn "端口:   $port_label:$port_number = 未监听，插件已安装但服务可能未启动"
        else
            log "端口:   $port_label:$port_number = 空闲或未监听"
        fi
        return 0
    fi

    if [ "$installed_flag" = '0' ]; then
        unified_port_warn "端口:   $port_label:$port_number = 已被占用，但未检测到对应插件，可能存在冲突: $(printf '%s\n' "$listen_lines" | sed -n '1p')"
        return 0
    fi

    if [ -n "$expected_text" ] && ! printf '%s\n' "$listen_lines" | grep -F "$expected_text" >/dev/null 2>&1; then
        if printf '%s\n' "$listen_lines" | unified_port_has_process_detail >/dev/null 2>&1; then
            unified_port_warn "端口:   $port_label:$port_number = 被非预期进程占用，可能冲突: $(printf '%s\n' "$listen_lines" | sed -n '1p')"
        else
            log "端口:   $port_label:$port_number = 已监听，但系统未返回进程名"
        fi
        return 0
    fi

    log "端口:   $port_label:$port_number = 正常: $(printf '%s\n' "$listen_lines" | sed -n '1p')"
}

run_unified_port_conflict_check() {
    UNIFIED_PORT_WARNINGS=0
    adg_port="$(uci -q get AdGuardHome.AdGuardHome.httpport 2>/dev/null || true)"
    [ -n "$adg_port" ] || adg_port='3000'
    adg_dns_port="$(uci -q get AdGuardHome.AdGuardHome.dns_port 2>/dev/null || true)"
    [ -n "$adg_dns_port" ] || adg_dns_port="$ADGUARDHOME_DNS_PORT"
    openlist_port="$(uci -q get openlist.main.port 2>/dev/null || true)"
    [ -n "$openlist_port" ] || openlist_port='5244'
    ttyd_port="$(get_ttyd_bind_value port 2>/dev/null || true)"
    [ -n "$ttyd_port" ] || ttyd_port='7681'
    ddnsgo_port="$(uci -q get ddns-go.config.port 2>/dev/null || true)"
    [ -n "$ddnsgo_port" ] || ddnsgo_port='9876'
    mosdns_port="$(uci -q get mosdns.main.listen_port 2>/dev/null || true)"
    [ -n "$mosdns_port" ] || mosdns_port="$MOSDNS_PORT"

    selfcheck_print_header "端口与服务冲突检查"
    unified_check_port_owner "AdGuardHome" "$adg_port" "AdGuardHome" "/usr/bin/AdGuardHome/AdGuardHome /usr/lib/lua/luci/controller/AdGuardHome.lua" 0
    unified_check_port_owner "AdGuardHome DNS" "$adg_dns_port" "AdGuardHome" "/usr/bin/AdGuardHome/AdGuardHome /etc/init.d/AdGuardHome" 0
    unified_check_port_owner "OpenList" "$openlist_port" "openlist" "$OPENLIST_BIN_PATH /usr/lib/lua/luci/controller/nradio_adv/openlist.lua" 0
    unified_check_port_owner "Web SSH / ttyd" "$ttyd_port" "ttyd" "/usr/bin/ttyd /usr/lib/lua/luci/controller/nradio_adv/webssh.lua" 1
    unified_check_port_owner "$DDNSGO_APP_NAME" "$ddnsgo_port" "ddns-go" "$DDNSGO_BIN_PATH $DDNSGO_CONTROLLER" 1
    unified_check_port_owner "MosDNS" "$mosdns_port" "mosdns" "$MOSDNS_BIN $MOSDNS_CONTROLLER" 1
    unified_check_port_owner "LuCI HTTP" "80" "uhttpd" "/etc/init.d/uhttpd" 0
    unified_check_port_owner "LuCI HTTPS" "443" "uhttpd" "/etc/init.d/uhttpd" 0
    unified_check_port_owner "SSH" "22" "dropbear" "/etc/init.d/dropbear /usr/sbin/sshd" 0
    unified_check_port_owner "DNS" "53" "" "/etc/init.d/dnsmasq /usr/sbin/dnsmasq" 0

    if [ "$UNIFIED_PORT_WARNINGS" -gt 0 ]; then
        set_last_selfcheck_status WARN 0 "$UNIFIED_PORT_WARNINGS"
    else
        set_last_selfcheck_status PASS 0 0
    fi
}

unified_get_openclash_config_path() {
    config_path="$(uci -q show openclash 2>/dev/null | awk -F"='" '$1 ~ /\.config_path$/ { value=$2; sub(/\047$/, "", value); print value; exit }' || true)"
    if [ -n "$config_path" ] && [ -f "$config_path" ]; then
        printf '%s\n' "$config_path"
        return 0
    fi

    for candidate_path in /etc/openclash/config/*.yaml /etc/openclash/config/*.yml; do
        [ -f "$candidate_path" ] || continue
        printf '%s\n' "$candidate_path"
        return 0
    done
    return 1
}

run_unified_openclash_rule_check() {
    rule_warnings=0
    openclash_config_path="$(unified_get_openclash_config_path 2>/dev/null || true)"
    direct_provider_path="/etc/openclash/rule_provider/Direct / Domain"
    custom_count=0
    custom_codex_hit=0

    selfcheck_print_header "$OPENCLASH_DISPLAY_NAME 规则检查"
    if [ ! -f /etc/config/openclash ] && [ ! -d /etc/openclash ]; then
        log "$OPENCLASH_DISPLAY_NAME: 未检测到配置目录，跳过规则检查"
        set_last_selfcheck_status PASS 0 0
        return 0
    fi

    if [ -n "$openclash_config_path" ]; then
        log "配置:   当前配置文件 = $openclash_config_path"
        if grep -F "Direct / Domain" "$openclash_config_path" >/dev/null 2>&1; then
            log "规则:   当前配置已引用 Direct / Domain"
        else
            log "规则:   当前配置未发现 Direct / Domain 引用"
            rule_warnings=$((rule_warnings + 1))
        fi
    else
        log "配置:   未找到当前 $OPENCLASH_DISPLAY_NAME 配置文件"
        rule_warnings=$((rule_warnings + 1))
    fi

    if [ -f "$direct_provider_path" ]; then
        provider_size="$(wc -c < "$direct_provider_path" 2>/dev/null | tr -d ' ' || true)"
        provider_lines="$(wc -l < "$direct_provider_path" 2>/dev/null | tr -d ' ' || true)"
        log "Provider: Direct / Domain = 存在 (${provider_lines:-?} 行, ${provider_size:-?} bytes)"
    else
        log "Provider: Direct / Domain = 缺失 ($direct_provider_path)"
        rule_warnings=$((rule_warnings + 1))
    fi

    for custom_file in /etc/openclash/custom/*; do
        [ -f "$custom_file" ] || continue
        custom_count=$((custom_count + 1))
        grep -F 'codex.597995.xyz' "$custom_file" >/dev/null 2>&1 && custom_codex_hit=1
    done
    log "自定义: custom 规则文件数 = $custom_count"

    codex_hit=0
    [ -n "$openclash_config_path" ] && grep -F 'codex.597995.xyz' "$openclash_config_path" >/dev/null 2>&1 && codex_hit=1
    [ -f "$direct_provider_path" ] && grep -F 'codex.597995.xyz' "$direct_provider_path" >/dev/null 2>&1 && codex_hit=1
    [ "$custom_codex_hit" = '1' ] && codex_hit=1
    if [ "$codex_hit" = '1' ]; then
        log "关键域名: codex.597995.xyz = 已命中规则"
    else
        log "关键域名: codex.597995.xyz = 未命中；如需直连，请加入 Direct / Domain 或自定义直连规则"
        rule_warnings=$((rule_warnings + 1))
    fi

    if [ "$rule_warnings" -gt 0 ]; then
        set_last_selfcheck_status WARN 0 "$rule_warnings"
    else
        set_last_selfcheck_status PASS 0 0
    fi
}

hakimi_policy_label() {
    case "$1" in
        DIRECT)
            printf '%s\n' 'DIRECT（直连）'
            ;;
        REJECT)
            printf '%s\n' 'REJECT（拦截）'
            ;;
        *)
            printf '%s\n' "$1"
            ;;
    esac
}

hakimi_build_policy_menu() {
    config_path="$1"
    out_file="$2"
    raw_file="$WORKDIR/hakimi-policy-targets.raw"

    : > "$raw_file"
    printf '%s\n' 'DIRECT' 'REJECT' >> "$raw_file"
    if [ -f "$config_path" ]; then
        awk '
            function trim(s) {
                gsub(/^[[:space:]]+|[[:space:]]+$/, "", s)
                sq = sprintf("%c", 39)
                if (substr(s, 1, 1) == sq && substr(s, length(s), 1) == sq) {
                    s = substr(s, 2, length(s) - 2)
                    gsub(sq sq, sq, s)
                } else {
                    gsub(/^"|"$/, "", s)
                }
                return s
            }
            /^proxy-groups:[[:space:]]*$/ { in_pg = 1; next }
            /^rules:[[:space:]]*$/ { in_rules = 1; in_pg = 0; next }
            in_pg && /^[^[:space:]#][^:]*:/ { in_pg = 0 }
            in_rules && /^[^[:space:]#][^:]*:/ { in_rules = 0 }
            in_pg && /^[[:space:]]*-[[:space:]]*\{[[:space:]]*name:[[:space:]]*/ {
                line = $0
                sub(/^.*name:[[:space:]]*/, "", line)
                sub(/,.*/, "", line)
                gsub(/[{}]/, "", line)
                line = trim(line)
                if (line != "") print line
                next
            }
            in_pg && /^[[:space:]]*-[[:space:]]*name:[[:space:]]*/ {
                line = $0
                sub(/^[[:space:]]*-[[:space:]]*name:[[:space:]]*/, "", line)
                line = trim(line)
                if (line != "") print line
                next
            }
            in_rules && /^[[:space:]]*-[[:space:]]*/ {
                line = $0
                sub(/^[[:space:]]*-[[:space:]]*/, "", line)
                sub(/[[:space:]]+#.*/, "", line)
                line = trim(line)
                n = split(line, part, ",")
                if (n < 2) next
                target = trim(part[n])
                if (target == "no-resolve" && n >= 3) target = trim(part[n - 1])
                if (target != "" && target !~ /^\(/) print target
            }
        ' "$config_path" >> "$raw_file"
    fi

    awk 'NF && !seen[$0]++ { print }' "$raw_file" > "$out_file"
}

hakimi_print_policy_menu() {
    list_file="$1"
    idx=1

    while IFS= read -r target_name; do
        [ -n "$target_name" ] || continue
        printf '%s. %s\n' "$idx" "$(hakimi_policy_label "$target_name")"
        idx=$((idx + 1))
    done < "$list_file"
    printf '99. 手动输入策略名\n'
    printf '0. 返回\n'
}

hakimi_select_policy_target() {
    list_file="$1"
    count="$(wc -l < "$list_file" 2>/dev/null | tr -d ' ' || printf 0)"

    while :; do
        printf '请选择要加入的分流目标数字: '
        ui_read_line || die "input cancelled"
        choice="$UI_READ_RESULT"
        case "$choice" in
            0)
                return 1
                ;;
            99)
                prompt_with_default "请输入策略名" ""
                target_name="$PROMPT_RESULT"
                case "$target_name" in
                    ''|*,*)
                        log "策略名为空或包含逗号，无法使用"
                        continue
                        ;;
                esac
                HAKIMI_SELECTED_TARGET="$target_name"
                return 0
                ;;
            ''|*[!0-9]*)
                log "请输入菜单中的数字"
                ;;
            *)
                if [ "$choice" -ge 1 ] 2>/dev/null && [ "$choice" -le "$count" ] 2>/dev/null; then
                    HAKIMI_SELECTED_TARGET="$(sed -n "${choice}p" "$list_file")"
                    [ -n "$HAKIMI_SELECTED_TARGET" ] && return 0
                fi
                log "数字超出菜单范围"
                ;;
        esac
    done
}

hakimi_is_ipv4() {
    printf '%s\n' "$1" | awk -F. '
        NF != 4 { exit 1 }
        {
            for (i = 1; i <= 4; i++) {
                if ($i !~ /^[0-9]+$/ || $i < 0 || $i > 255) exit 1
            }
            exit 0
        }'
}

hakimi_is_ipv4_cidr() {
    value="$1"
    addr="${value%/*}"
    bits="${value#*/}"
    [ "$addr" != "$value" ] || return 1
    hakimi_is_ipv4 "$addr" || return 1
    case "$bits" in
        ''|*[!0-9]*)
            return 1
            ;;
    esac
    [ "$bits" -ge 0 ] 2>/dev/null && [ "$bits" -le 32 ] 2>/dev/null
}

hakimi_is_domain_name() {
    value="$1"
    case "$value" in
        ''|*','*|*' '*|*'/'*|*'?'*|*'#'*|*'@'*|*':'*)
            return 1
            ;;
        *.*)
            ;;
        *)
            return 1
            ;;
    esac
    printf '%s\n' "$value" | grep -Eq '^[A-Za-z0-9._-]+$'
}

hakimi_clean_rule_value() {
    value="$1"
    value="$(printf '%s\n' "$value" | sed 's/[[:space:]]//g; s/^https:\/\///; s/^http:\/\///; s/^\.//')"
    case "$value" in
        *:*)
            ;;
        *.*.*.*/*)
            ;;
        *'/'*)
            value="${value%%/*}"
            ;;
    esac
    printf '%s\n' "$value"
}

hakimi_is_ipv6_cidr_value() {
    awk -v input="$1" '
        function groups(s, a, n, i) {
            if (s == "") return 0
            n = split(s, a, ":")
            for (i = 1; i <= n; i++)
                if (a[i] !~ /^[0-9A-Fa-f]+$/ || length(a[i]) > 4) return -100
            return n
        }
        BEGIN {
            n = split(input, cidr, "/")
            if (n > 2 || (n == 2 && (cidr[2] !~ /^[0-9]+$/ || cidr[2] + 0 > 128))) exit 1
            address = cidr[1]
            if (index(address, ":") == 0) exit 1
            if (index(address, ".") > 0) {
                tail = address
                sub(/^.*:/, "", tail)
                if (split(tail, octets, /[.]/) != 4) exit 1
                for (i = 1; i <= 4; i++)
                    if (octets[i] !~ /^[0-9]+$/ || octets[i] + 0 > 255 ||
                        (length(octets[i]) > 1 && substr(octets[i], 1, 1) == "0")) exit 1
                address = substr(address, 1, length(address) - length(tail)) "0:0"
            }
            n = split(address, halves, "::")
            if (n > 2) exit 1
            left = groups(halves[1])
            right = (n == 2 ? groups(halves[2]) : 0)
            if (left < 0 || right < 0) exit 1
            exit (n == 2 ? left + right < 8 : left == 8) ? 0 : 1
        }'
}

hakimi_build_rule_line() {
    raw_value="$1"
    target_name="$2"
    rule_value="$(hakimi_clean_rule_value "$raw_value")"

    case "$rule_value" in
        '')
            return 1
            ;;
        keyword:*)
            keyword_value="${rule_value#keyword:}"
            [ -n "$keyword_value" ] || return 1
            HAKIMI_RULE_LINE="DOMAIN-KEYWORD,$keyword_value,$target_name"
            HAKIMI_RULE_KEY="DOMAIN-KEYWORD,$keyword_value"
            return 0
            ;;
        =*)
            domain_value="${rule_value#=}"
            hakimi_is_domain_name "$domain_value" || return 1
            HAKIMI_RULE_LINE="DOMAIN,$domain_value,$target_name"
            HAKIMI_RULE_KEY="DOMAIN,$domain_value"
            return 0
            ;;
    esac

    if hakimi_is_ipv4_cidr "$rule_value"; then
        HAKIMI_RULE_LINE="IP-CIDR,$rule_value,$target_name,no-resolve"
        HAKIMI_RULE_KEY="IP-CIDR,$rule_value"
        return 0
    fi
    if hakimi_is_ipv4 "$rule_value"; then
        HAKIMI_RULE_LINE="IP-CIDR,$rule_value/32,$target_name,no-resolve"
        HAKIMI_RULE_KEY="IP-CIDR,$rule_value/32"
        return 0
    fi
    case "$rule_value" in
        *:*)
            hakimi_is_ipv6_cidr_value "$rule_value" || return 1
            case "$rule_value" in
                */*) ipv6_value="$rule_value" ;;
                *) ipv6_value="$rule_value/128" ;;
            esac
            HAKIMI_RULE_LINE="IP-CIDR6,$ipv6_value,$target_name,no-resolve"
            HAKIMI_RULE_KEY="IP-CIDR6,$ipv6_value"
            return 0
            ;;
    esac
    if hakimi_is_domain_name "$rule_value"; then
        HAKIMI_RULE_LINE="DOMAIN-SUFFIX,$rule_value,$target_name"
        HAKIMI_RULE_KEY="DOMAIN-SUFFIX,$rule_value"
        return 0
    fi

    return 1
}

hakimi_rule_exact_exists() {
    rule_file="$1"
    rule_line="$2"
    [ -f "$rule_file" ] || return 1
    grep -F -x -e "- $rule_line" -e "$rule_line" "$rule_file" >/dev/null 2>&1
}

hakimi_rule_conflicts() {
    rule_file="$1"
    rule_key="$2"
    rule_line="$3"
    [ -f "$rule_file" ] || return 1
    awk -v key="$rule_key" -v exact1="- $rule_line" -v exact2="$rule_line" '
        {
            line = $0
            sub(/^[[:space:]]*-[[:space:]]*/, "", line)
            sub(/[[:space:]]+#.*/, "", line)
            split(line, part, ",")
            k = part[1] "," part[2]
            if (k == key && $0 != exact1 && line != exact2) print $0
        }
    ' "$rule_file"
}

hakimi_insert_custom_rule() {
    rule_file="$1"
    rule_line="$2"
    tmp_file="$WORKDIR/hakimi-custom-rules.tmp"
    mkdir -p "$(dirname "$rule_file")" || die "创建哈基米自定义规则目录失败"
    if [ ! -f "$rule_file" ]; then
        printf '%s\n' 'rule-providers:' '' 'rules:' > "$rule_file" || die "创建哈基米自定义规则文件失败"
    fi

    awk -v rule="$rule_line" '
        BEGIN { inserted = 0 }
        /^rules:[[:space:]]*$/ {
            print
            if (!inserted) {
                print "- " rule
                inserted = 1
            }
            next
        }
        { print }
        END {
            if (!inserted) {
                print ""
                print "rules:"
                print "- " rule
            }
        }
    ' "$rule_file" > "$tmp_file" || die "写入哈基米自定义规则临时文件失败"
    mv "$tmp_file" "$rule_file" || die "更新哈基米自定义规则文件失败"
}

hakimi_enable_custom_rules() {
    uci set openclash.config.enable_custom_clash_rules='1' >/dev/null 2>&1 || die "启用哈基米自定义规则失败"
    uci commit openclash >/dev/null 2>&1 || die "保存哈基米自定义规则开关失败"
}

openclash_asn_mmdb_valid() {
    asn_file="/etc/openclash/ASN.mmdb"
    [ -f "$asn_file" ] || return 1
    asn_size="$(wc -c < "$asn_file" 2>/dev/null | tr -d ' ')"
    case "$asn_size" in
        ''|*[!0-9]*)
            return 1
            ;;
    esac
    [ "$asn_size" -ge 1048576 ] 2>/dev/null
}

openclash_require_asn_mmdb() {
    openclash_asn_mmdb_valid && return 0
    if [ -L /etc/openclash ]; then
        openclash_real_path="$(readlink /etc/openclash 2>/dev/null || true)"
    else
        openclash_real_path="/etc/openclash"
    fi
    die "$OPENCLASH_DISPLAY_NAME ASN.mmdb 缺失或异常：/etc/openclash/ASN.mmdb（实际目录：${openclash_real_path:-/etc/openclash}）。请先下载 ASN.mmdb，再迁移或重载 $OPENCLASH_DISPLAY_NAME"
}

openclash_dependency_packages() {
    printf '%s\n' dnsmasq-full bash curl ca-bundle ip-full ruby ruby-yaml kmod-tun unzip
}

openclash_package_installed() {
    pkg_name="$1"
    command -v opkg >/dev/null 2>&1 || return 1
    opkg status "$pkg_name" 2>/dev/null | grep -q '^Status: .* installed'
}

openclash_dependency_status() {
    pkg_name="$1"

    if openclash_package_installed "$pkg_name"; then
        printf '%s\n' 'ok|已安装'
        return 0
    fi

    printf '%s\n' 'missing|缺失'
}

openclash_file_min_size() {
    file_path="$1"
    min_bytes="$2"
    [ -f "$file_path" ] || return 1
    file_size="$(wc -c < "$file_path" 2>/dev/null | tr -d ' ' || printf '0')"
    case "$file_size" in
        ''|*[!0-9]*)
            return 1
            ;;
    esac
    [ "$file_size" -ge "$min_bytes" ] 2>/dev/null
}

openclash_model_file_valid() {
    model_file="${1:-/etc/openclash/Model.bin}"
    openclash_file_min_size "$model_file" 1048576
}

openclash_core_runtime_valid() {
    [ -s /etc/openclash/core_version ] || return 1
    [ -x /etc/openclash/core/clash_meta ] || return 1
    [ -x /etc/openclash/core/clash ] || [ -x /etc/openclash/clash ] || return 1
}

openclash_resolve_storage_path() {
    target_path="$1"
    target_dir=""
    target_base=""
    target_dir_real=""

    if [ -e "$target_path" ] || [ -L "$target_path" ]; then
        readlink -f "$target_path" 2>/dev/null || printf '%s\n' "$target_path"
        return 0
    fi

    target_dir="$(dirname "$target_path")"
    target_base="$(basename "$target_path")"
    if [ -e "$target_dir" ] || [ -L "$target_dir" ]; then
        target_dir_real="$(readlink -f "$target_dir" 2>/dev/null || printf '%s\n' "$target_dir")"
        printf '%s/%s\n' "$target_dir_real" "$target_base"
        return 0
    fi

    printf '%s\n' "$target_path"
}

openclash_report_storage_location() {
    label="$1"
    target_path="$2"
    real_path=""
    df_target=""
    df_info=""

    real_path="$(openclash_resolve_storage_path "$target_path")"
    df_target="$target_path"
    if [ ! -e "$df_target" ]; then
        df_target="$(dirname "$target_path")"
    fi
    if [ ! -e "$df_target" ]; then
        df_target="/"
    fi
    df_info="$(df -kP "$df_target" 2>/dev/null | awk 'NR==2 { printf "%s total=%sK used=%sK avail=%sK mount=%s", $1, $2, $3, $4, $6; exit }' || true)"
    [ -n "$df_info" ] || df_info="df=unknown"
    log "分区:   $label = $target_path -> $real_path ($df_info)"
}

openclash_ensure_storage_dir() {
    target_dir="$1"
    target_label="${2:-$target_dir}"
    real_dir=""
    mount_source=""

    if [ -L "$target_dir" ] && [ ! -e "$target_dir" ]; then
        die "$target_label 是失效软链：$target_dir -> $(readlink "$target_dir" 2>/dev/null || true)"
    fi

    mkdir -p "$target_dir" || die "创建 $target_label 失败：$target_dir"
    real_dir="$(openclash_resolve_storage_path "$target_dir")"
    case "$real_dir" in
        "$ROOTFS_2ND_STORAGE_MOUNT_POINT"|"$ROOTFS_2ND_STORAGE_MOUNT_POINT"/*)
            mount_source="$(storage_expand_mount_source_for_mountpoint 2>/dev/null || true)"
            [ -n "$mount_source" ] || die "$target_label 实际落在 $ROOTFS_2ND_STORAGE_MOUNT_POINT，但扩展盘未挂载；已停止，避免写入 overlay。请先使用 5 > 4 > 5 接入扩展盘"
            ;;
    esac
    ensure_dir_writable "$target_dir" "$target_label"
}

openclash_find_model_source_candidate() {
    for candidate in \
        /etc/openclash/model.bin \
        /etc/openclash/mobel.bin \
        /tmp/etc/openclash/Model.bin \
        /tmp/etc/openclash/model.bin \
        /tmp/etc/openclash/mobel.bin; do
        [ -f "$candidate" ] || continue
        if openclash_model_file_valid "$candidate"; then
            printf '%s\n' "$candidate"
            return 0
        fi
    done
    return 1
}

openclash_copy_model_to_persistent() {
    source_model="$1"
    [ -f "$source_model" ] || die "模型来源不存在：$source_model"
    openclash_model_file_valid "$source_model" || die "模型来源文件过小或异常：$source_model"
    openclash_ensure_storage_dir /etc/openclash "$OPENCLASH_DISPLAY_NAME 目录"
    backup_file /etc/openclash/Model.bin
    cp -f "$source_model" /etc/openclash/Model.bin || die "写入 /etc/openclash/Model.bin 失败"
    chmod 644 /etc/openclash/Model.bin 2>/dev/null || true
    log "修复:   Model.bin 已写入 /etc/openclash/Model.bin"
}

openclash_download_model_bin() {
    model_tmp="$WORKDIR/openclash-repair/Model.bin"
    mkdir -p "$WORKDIR/openclash-repair"
    log "提示: 正在下载 $OPENCLASH_DISPLAY_NAME smart 模型 Model.bin..."
    download_from_urls "$model_tmp" $OPENCLASH_MODEL_URLS || die "无法下载 $OPENCLASH_DISPLAY_NAME smart 模型 Model.bin"
    openclash_model_file_valid "$model_tmp" || die "$OPENCLASH_DISPLAY_NAME smart 模型下载后大小异常"
    openclash_copy_model_to_persistent "$model_tmp"
}

openclash_download_asn_mmdb() {
    asn_tmp="$WORKDIR/openclash-repair/GeoLite2-ASN.mmdb"
    mkdir -p "$WORKDIR/openclash-repair"
    log "提示: 正在下载 $OPENCLASH_DISPLAY_NAME ASN.mmdb..."
    download_from_mirrors "GeoLite2-ASN.mmdb" "$asn_tmp" "$OPENCLASH_GEOASN_MIRRORS" || die "无法下载 $OPENCLASH_DISPLAY_NAME ASN.mmdb"
    openclash_file_min_size "$asn_tmp" 1048576 || die "$OPENCLASH_DISPLAY_NAME ASN.mmdb 下载后大小异常"
    openclash_ensure_storage_dir /etc/openclash "$OPENCLASH_DISPLAY_NAME 目录"
    backup_file /etc/openclash/ASN.mmdb
    cp -f "$asn_tmp" /etc/openclash/ASN.mmdb || die "写入 /etc/openclash/ASN.mmdb 失败"
    chmod 644 /etc/openclash/ASN.mmdb 2>/dev/null || true
    log "修复:   ASN.mmdb 已写入 /etc/openclash/ASN.mmdb"
}

run_openclash_dependency_repair_check() {
    require_root
    mkdir -p "$WORKDIR/openclash-repair"
    repair_changed=0

    selfcheck_print_header "$OPENCLASH_DISPLAY_NAME 依赖检查修复"
    openclash_report_storage_location "$OPENCLASH_DISPLAY_NAME 目录" /etc/openclash
    openclash_report_storage_location "$OPENCLASH_DISPLAY_NAME 核心目录" /etc/openclash/core

    missing_pkgs=""
    if command -v opkg >/dev/null 2>&1; then
        log "工具:   opkg = 可用"
    else
        log "工具:   opkg = 缺失"
    fi

    if [ -e "$OPKG_LOCK_FILE" ]; then
        log "opkg锁: $OPKG_LOCK_FILE = 存在，安装依赖前请确认没有其它安装任务"
    else
        log "opkg锁: $OPKG_LOCK_FILE = 未占用"
    fi

    for package_name in $(openclash_dependency_packages); do
        dependency_status="$(openclash_dependency_status "$package_name")"
        dependency_state="${dependency_status%%|*}"
        dependency_text="${dependency_status#*|}"
        if [ "$dependency_state" = 'ok' ]; then
            log "依赖:   $package_name = $dependency_text"
        else
            log "依赖:   $package_name = $dependency_text"
            missing_pkgs="$missing_pkgs $package_name"
        fi
    done

    if [ -n "$missing_pkgs" ]; then
        if confirm_default_yes "检测到 $OPENCLASH_DISPLAY_NAME 依赖缺失:${missing_pkgs}，是否现在更新软件源并安装？"; then
            ensure_opkg_update || die "opkg update 失败，已停止依赖修复"
            ensure_packages $missing_pkgs || die "$OPENCLASH_DISPLAY_NAME 依赖修复失败，仍有软件包缺失"
            repair_changed=1
        else
            log "跳过:   依赖安装"
        fi
    fi

    if openclash_package_installed luci-app-openclash; then
        oc_ver="$(opkg status luci-app-openclash 2>/dev/null | awk -F': ' '/^Version: /{print $2; exit}' || true)"
        log "插件:   luci-app-openclash = 已安装 ${oc_ver:-unknown}"
    else
        log "插件:   luci-app-openclash = 未安装；如需安装本体，请使用 1 > 2"
    fi
    [ -f /usr/lib/lua/luci/controller/openclash.lua ] && log "LuCI:   controller = 存在" || log "LuCI:   controller = 缺失"
    [ -f /etc/config/openclash ] && log "配置:   /etc/config/openclash = 存在" || log "配置:   /etc/config/openclash = 缺失"
    [ -x /etc/init.d/openclash ] && log "服务:   /etc/init.d/openclash = 存在" || log "服务:   /etc/init.d/openclash = 缺失"

    if openclash_core_runtime_valid; then
        log "核心:   smart/meta = 正常"
    else
        log "核心:   smart/meta = 缺失或异常"
        if confirm_default_yes "是否现在下载/修复 $OPENCLASH_SMART_DISPLAY_NAME 核心？"; then
            openclash_ensure_storage_dir /etc/openclash "$OPENCLASH_DISPLAY_NAME 目录"
            openclash_ensure_storage_dir /etc/openclash/core "$OPENCLASH_DISPLAY_NAME 核心目录"
            install_openclash_smart_core
            repair_changed=1
        else
            log "跳过:   smart/meta 核心修复"
        fi
    fi

    if openclash_asn_mmdb_valid; then
        log "ASN:    /etc/openclash/ASN.mmdb = 正常"
    else
        log "ASN:    /etc/openclash/ASN.mmdb = 缺失或异常"
        if confirm_default_yes "是否现在下载 ASN.mmdb 到 $OPENCLASH_DISPLAY_NAME 实际所在分区？"; then
            openclash_download_asn_mmdb
            repair_changed=1
        else
            log "跳过:   ASN.mmdb 下载"
        fi
    fi

    if openclash_model_file_valid /etc/openclash/Model.bin; then
        log "模型:   /etc/openclash/Model.bin = 正常"
    else
        log "模型:   /etc/openclash/Model.bin = 缺失或异常"
        model_candidate="$(openclash_find_model_source_candidate 2>/dev/null || true)"
        if [ -n "$model_candidate" ]; then
            if confirm_default_yes "检测到模型候选 $model_candidate，是否复制修复为 /etc/openclash/Model.bin？"; then
                openclash_copy_model_to_persistent "$model_candidate"
                repair_changed=1
            else
                log "跳过:   模型候选复制"
            fi
        fi
        if ! openclash_model_file_valid /etc/openclash/Model.bin; then
            if confirm_default_yes "是否现在下载 smart 模型 Model.bin 到 $OPENCLASH_DISPLAY_NAME 实际所在分区？"; then
                openclash_download_model_bin
                repair_changed=1
            else
                log "跳过:   Model.bin 下载"
            fi
        fi
    fi

    if command -v uci >/dev/null 2>&1 && [ -f /etc/config/openclash ]; then
        smart_lgbm_enabled="$(uci -q get openclash.config.smart_enable_lgbm 2>/dev/null || true)"
        lgbm_auto_update="$(uci -q get openclash.config.lgbm_auto_update 2>/dev/null || true)"
        log "配置:   smart_enable_lgbm=${smart_lgbm_enabled:-未设置} lgbm_auto_update=${lgbm_auto_update:-未设置}"
    fi

    selfcheck_print_header "$OPENCLASH_DISPLAY_NAME 修复后复查"
    repair_warnings=0
    missing_after=""
    for package_name in $(openclash_dependency_packages); do
        dependency_status="$(openclash_dependency_status "$package_name")"
        dependency_state="${dependency_status%%|*}"
        [ "$dependency_state" = 'ok' ] || missing_after="$missing_after $package_name"
    done
    if [ -n "$missing_after" ]; then
        log "依赖:   仍缺失:${missing_after}"
        repair_warnings=$((repair_warnings + 1))
    else
        log "依赖:   全部满足"
    fi
    if openclash_core_runtime_valid; then
        log "核心:   smart/meta = 正常"
    else
        log "核心:   smart/meta = 仍缺失或异常"
        repair_warnings=$((repair_warnings + 1))
    fi
    if openclash_asn_mmdb_valid; then
        log "ASN:    ASN.mmdb = 正常"
    else
        log "ASN:    ASN.mmdb = 仍缺失或异常"
        repair_warnings=$((repair_warnings + 1))
    fi
    if openclash_model_file_valid /etc/openclash/Model.bin; then
        log "模型:   Model.bin = 正常"
    else
        log "模型:   Model.bin = 仍缺失或异常"
        repair_warnings=$((repair_warnings + 1))
    fi
    if [ -x /etc/init.d/openclash ]; then
        oc_service_status="$(/etc/init.d/openclash status 2>/dev/null | tr '\n' ' ' | sed 's/[[:space:]]\+/ /g; s/^ //; s/ $//' || true)"
        log "服务:   openclash status = ${oc_service_status:-unknown}"
    else
        log "服务:   openclash = 未安装"
    fi
    if [ "$repair_warnings" -gt 0 ]; then
        log "summary: WARN ($repair_warnings)"
        [ "$repair_changed" = '1' ] && record_action_history "5 > 6" "$OPENCLASH_DISPLAY_NAME 依赖检查修复" "WARN" "$BACKUP_DIR"
    else
        log "summary: PASS"
        [ "$repair_changed" = '1' ] && record_action_history "5 > 6" "$OPENCLASH_DISPLAY_NAME 依赖检查修复" "PASS" "$BACKUP_DIR"
    fi
    return 0
}

run_hakimi_easy_rule_helper() {
    require_root
    mkdir -p "$WORKDIR"

    config_path="$(unified_get_openclash_config_path 2>/dev/null || true)"
    [ -n "$config_path" ] || die "$OPENCLASH_DISPLAY_NAME 未找到当前 YAML 配置文件"
    [ -f "$config_path" ] || die "$OPENCLASH_DISPLAY_NAME 当前 YAML 配置不存在: $config_path"

    policy_file="$WORKDIR/hakimi-policy-targets.list"
    hakimi_build_policy_menu "$config_path" "$policy_file"
    [ -s "$policy_file" ] || die "$OPENCLASH_DISPLAY_NAME 未能从 YAML 解析出可用分流目标"

    log "$OPENCLASH_DISPLAY_NAME 傻瓜分流助手"
    log "配置:   $config_path"
    log "说明:   机场订阅或在线订阅生成的 YAML 可能被更新覆盖，本助手只写入哈基米自定义规则文件"
    log "说明:   默认域名使用 DOMAIN-SUFFIX；精确域名前加 =，关键词前加 keyword:"
    log ""
    log "可用分流目标:"
    hakimi_print_policy_menu "$policy_file"
    log ""

    if ! hakimi_select_policy_target "$policy_file"; then
        log "已返回"
        return 0
    fi

    prompt_with_default "请输入域名、IP 或网段" ""
    user_value="$PROMPT_RESULT"
    if ! hakimi_build_rule_line "$user_value" "$HAKIMI_SELECTED_TARGET"; then
        die "输入格式无法识别；示例：example.com、=www.example.com、keyword:google、1.2.3.4、1.2.3.0/24"
    fi

    log ""
    log "准备添加规则:"
    log "  $HAKIMI_RULE_LINE"
    log "写入:   $OPENCLASH_CUSTOM_RULES_FILE"

    if hakimi_rule_exact_exists "$OPENCLASH_CUSTOM_RULES_FILE" "$HAKIMI_RULE_LINE"; then
        hakimi_enable_custom_rules
        log "结果:   相同规则已存在，未重复写入；已启用哈基米自定义规则"
        record_action_history "5 > 3" "$OPENCLASH_DISPLAY_NAME 自定义规则启用" "PASS" "disabled"
        MENU_ACTION_COMPLETED='1'
        return 0
    fi

    conflicts="$(hakimi_rule_conflicts "$OPENCLASH_CUSTOM_RULES_FILE" "$HAKIMI_RULE_KEY" "$HAKIMI_RULE_LINE" 2>/dev/null || true)"
    if [ -n "$conflicts" ]; then
        log "冲突:   已存在同对象的其他分流规则:"
        printf '%s\n' "$conflicts"
        printf '是否仍然追加新规则？[y/N]: '
        ui_read_line || die "input cancelled"
        case "$UI_READ_RESULT" in
            y|Y|yes|YES) ;;
            *) log "已取消"; return 0 ;;
        esac
    fi

    confirm_or_exit "确认写入 $OPENCLASH_DISPLAY_NAME 自定义规则吗？"
    hakimi_insert_custom_rule "$OPENCLASH_CUSTOM_RULES_FILE" "$HAKIMI_RULE_LINE"
    hakimi_enable_custom_rules
    log "结果:   已写入并启用哈基米自定义规则"
    record_action_history "5 > 3" "$OPENCLASH_DISPLAY_NAME 自定义规则写入" "PASS" "disabled"
    MENU_ACTION_COMPLETED='1'

    printf '是否现在重载 %s 使规则生效？[y/N]: ' "$OPENCLASH_DISPLAY_NAME"
    ui_read_line || die "input cancelled"
    case "$UI_READ_RESULT" in
        y|Y|yes|YES)
            [ -x /etc/init.d/openclash ] || die "$OPENCLASH_DISPLAY_NAME 服务脚本不存在"
            openclash_require_asn_mmdb
            /etc/init.d/openclash restart >/dev/null 2>&1 || die "$OPENCLASH_DISPLAY_NAME 重载失败"
            log "结果:   $OPENCLASH_DISPLAY_NAME 已重载"
            ;;
        *)
            log "提示:   写入完成；稍后可在哈基米页面手动重载"
            ;;
    esac
}

run_unified_sanitized_diagnostic_summary() {
    detected_model="$(unified_detect_model_name 2>/dev/null || true)"
    nros_revision="$(detect_nros_revision 2>/dev/null || true)"
    arch_name="$(unified_detect_arch_name)"
    mem_available_kib="$(unified_num_or_zero "$(unified_health_mem_kib MemAvailable)")"
    swap_free_kib="$(unified_num_or_zero "$(unified_health_mem_kib SwapFree)")"
    tmp_free_kib="$(unified_num_or_zero "$(unified_health_path_free_kib /tmp 2>/dev/null || true)")"
    overlay_free_kib="$(unified_num_or_zero "$(unified_health_path_free_kib /overlay 2>/dev/null || true)")"
    storage_mount=''
    if c2000_storage_swap_model_supported "$detected_model"; then
        storage_mount="$(detect_c2000max_storage_mount 2>/dev/null || true)"
    fi
    openclash_config_path="$(unified_get_openclash_config_path 2>/dev/null || true)"

    selfcheck_print_header "脱敏诊断摘要"
    log "===== NRadio 脱敏诊断摘要开始 ====="
    log "script=${SCRIPT_VERSION} date=${SCRIPT_RELEASE_DATE}"
    log "model=${detected_model:-未知} nros=${nros_revision:-未知} arch=${arch_name}"
    log "mem_available=$(unified_health_kib_display "$mem_available_kib") swap_free=$(unified_health_kib_display "$swap_free_kib")"
    if c2000_storage_swap_model_supported "$detected_model"; then
        log "tmp_free=$(unified_health_kib_display "$tmp_free_kib") overlay_free=$(unified_health_kib_display "$overlay_free_kib") storage=${storage_mount:-未检测到}"
    else
        log "tmp_free=$(unified_health_kib_display "$tmp_free_kib") overlay_free=$(unified_health_kib_display "$overlay_free_kib")"
    fi
    log "hakimi_config=${openclash_config_path:-未检测到}"
    log "===== NRadio 脱敏诊断摘要结束 ====="
    set_last_selfcheck_status PASS 0 0
}

