<script type="text/javascript">//<![CDATA[
(function(){
	var hideSelectors = [
		'header',
		'.menu_mobile',
		'.mobile_bg_color.container.body-container.visible-xs-block',
		'.tail_wave',
		'.footer',
		'footer',
		'.footer_container',
		'.footer_container_body',
		'.menu-top',
		'.logo-nradio',
		'.large_banner',
		'.small_banner',
		'.main-logo-size',
		'.mobile-logo-size',
		'.qmenu',
		'.nradio-right-btn',
		'.sub_icon_list',
		'.menu-tab',
		'#mainmenu',
		'#modemenu',
		'.navbar',
		'.navbar-inner'
	];
	function hideOemHeader(){
		if (document.documentElement.className.indexOf("nr-openclash-oem-hidden") === -1)
			document.documentElement.className += " nr-openclash-oem-hidden";
		for (var i = 0; i < hideSelectors.length; i++) {
			var nodes = document.querySelectorAll(hideSelectors[i]);
			for (var j = 0; j < nodes.length; j++)
				nodes[j].style.display = 'none';
		}
	}
	function expandOpenClashPage(){
		var html = document.documentElement;
		var body = document.body;
		var targets = [
			html,
			body
		];
		var selectors = [
			'.container.body-container:not(.visible-xs-block)',
			'.main',
			'.main-content',
			'#maincontent',
			'#content'
		];
		for (var i = 0; i < selectors.length; i++) {
			var nodes = document.querySelectorAll(selectors[i]);
			for (var j = 0; j < nodes.length; j++)
				targets.push(nodes[j]);
		}
		for (var k = 0; k < targets.length; k++) {
			if (!targets[k])
				continue;
			targets[k].style.height = 'auto';
			targets[k].style.minHeight = '100vh';
			targets[k].style.overflowY = 'visible';
		}
	}
	try {
		if (window.self !== window.top)
			document.documentElement.className += " nr-openclash-embedded";
	}
	catch(e) {
		document.documentElement.className += " nr-openclash-embedded";
	}
	if (document.readyState === 'loading')
		document.addEventListener('DOMContentLoaded', function(){
			hideOemHeader();
			expandOpenClashPage();
		});
	else {
		hideOemHeader();
		expandOpenClashPage();
	}
	setTimeout(hideOemHeader, 300);
	setTimeout(hideOemHeader, 1200);
	setTimeout(expandOpenClashPage, 300);
	setTimeout(expandOpenClashPage, 1200);
})();

(function initDebugLogAdapter(){
	function updateDebugHint(){
		var rendered = document.getElementById('debug-rendered');
		var debugLog = document.getElementById('debug_log');
		if (!rendered) return;
		var hasContent = rendered.innerHTML.replace(/\s/g,'') !== ''
			|| (debugLog && debugLog.value && debugLog.value.replace(/\s/g,'') !== '');
		var existing = document.getElementById('nr-debug-empty-hint');
		if (!hasContent) {
			if (!existing) {
				var hint = document.createElement('div');
				hint.id = 'nr-debug-empty-hint';
				hint.innerHTML = 'No debug log generated yet.<br>Click <strong>Generate Logs</strong> below to create a diagnostic report.';
				var wrapper = document.getElementById('debug-render-wrapper');
				if (wrapper) {
					wrapper.insertBefore(hint, rendered);
				}
			}
		} else {
			if (existing) {
				existing.style.display = 'none';
			}
		}
	}
	setTimeout(updateDebugHint, 1000);
	setTimeout(updateDebugHint, 3000);
	var genBtn = document.getElementById('gen_debug_button');
	if (genBtn) {
		genBtn.addEventListener('click', function(){
			setTimeout(updateDebugHint, 3000);
		});
	}
	var checkCount = 0;
	var intervalId = setInterval(function(){
		updateDebugHint();
		if (++checkCount >= 5) clearInterval(intervalId);
	}, 1500);
})();
//]]></script>
<div class="nr-openclash-original-tabs">
	<% for _, tab in ipairs(tabs) do %>
		<% local route = table.concat(tab[1], "/") %>
		<a class="<%=current == route and "nr-openclash-original-tab-active" or ""%>" href="<%=dispatcher.build_url(unpack(tab[1]))%>"><%=translate(tab[2])%></a>
	<% end %>
</div>
EOF
}

patch_openclash_model_tabs_file() {
    model_file="$1"
    [ -f "$model_file" ] || return 0
    grep -q 'openclash/nradio_tabs' "$model_file" && return 0

    backup_file "$model_file"
    tmp_model_tabs="$WORKDIR/openclash-tabs.$(basename "$model_file")"
    awk '
        BEGIN { inserted = 0 }
        {
            print
            if (!inserted && $0 ~ /^[[:space:]]*m[[:space:]]*=[[:space:]]*(Map|SimpleForm)\(/) {
                print "local nradio_tabs = m:section(SimpleSection)"
                print "nradio_tabs.template = \"openclash/nradio_tabs\""
                print "nradio_tabs.anonymous = true"
                inserted = 1
            }
        }
    ' "$model_file" > "$tmp_model_tabs"
    cp "$tmp_model_tabs" "$model_file"

    grep -q 'openclash/nradio_tabs' "$model_file" || die "OpenClash 原版页面标签注入失败: $model_file"
}

patch_openclash_original_page_tabs() {
    write_openclash_original_tabs_template
    tabs_model_count='0'
    for model_file in \
        /usr/lib/lua/luci/model/cbi/openclash/client.lua \
        /usr/lib/lua/luci/model/cbi/openclash/settings.lua \
        /usr/lib/lua/luci/model/cbi/openclash/config-overwrite.lua \
        /usr/lib/lua/luci/model/cbi/openclash/config-subscribe.lua \
        /usr/lib/lua/luci/model/cbi/openclash/config.lua \
        /usr/lib/lua/luci/model/cbi/openclash/log.lua; do
        [ -f "$model_file" ] || continue
        patch_openclash_model_tabs_file "$model_file"
        if grep -q 'openclash/nradio_tabs' "$model_file"; then
            tabs_model_count=$((tabs_model_count + 1))
        fi
    done

    [ "$tabs_model_count" -gt 0 ] || die "OpenClash 原版页面标签注入失败: 未找到可 patch 的页面模型"
}

cleanup_c8_luci_compat_pollution() {
    cleanup_model="$(detect_current_nradio_model_quiet 2>/dev/null || true)"
    [ "$cleanup_model" = 'NRadio_C8-688' ] || return 0

    compat_list="$WORKDIR/luci-compat.files"
    if [ -f /usr/lib/opkg/info/luci-compat.list ]; then
        cp /usr/lib/opkg/info/luci-compat.list "$compat_list" || return 1
    elif opkg status luci-compat 2>/dev/null | grep -q '^Status: .* installed'; then
        opkg files luci-compat 2>/dev/null | sed -n 's#^/\+#/#p' > "$compat_list" || return 1
    else
        return 0
    fi

    log "检测:   C8-688 已安装 luci-compat，正在清理 NROS LuCI 污染"
    opkg remove luci-compat --force-depends >"$WORKDIR/luci-compat-remove.log" 2>&1 || {
        sed -n '1,120p' "$WORKDIR/luci-compat-remove.log" >&2
        return 1
    }

    while IFS= read -r compat_path; do
        case "$compat_path" in
            /usr/lib/lua/luci/*)
                if [ -f "/rom$compat_path" ]; then
                    mkdir -p "$(dirname "$compat_path")" || return 1
                    cp -f "/rom$compat_path" "$compat_path" || return 1
                    cmp -s "/rom$compat_path" "$compat_path" || return 1
                else
                    case "$compat_path" in
                        /usr/lib/lua/luci/model/network/proto_*.lua)
                            rm -f "$compat_path" || return 1
                            ;;
                    esac
                fi
                ;;
        esac
    done < "$compat_list"

    rm -f /tmp/luci-indexcache /tmp/luci-modulecache/* >/dev/null 2>&1 || true
    [ -x /etc/init.d/uhttpd ] && /etc/init.d/uhttpd reload >/dev/null 2>&1 || true
    log "修复:   C8-688 luci-compat 污染已清理，ROM LuCI 文件已恢复"
    return 0
}

install_openclash() {
    require_nradio_oem_appcenter
    cleanup_c8_luci_compat_pollution || die "C8-688 luci-compat 污染清理失败，已停止安装"

    mkdir -p "$WORKDIR/openclash/pkg" "$WORKDIR/openclash/control"
    log_stage 1 7 "$OPENCLASH_DISPLAY_NAME 镜像探测与安装规划"
    optimize_openclash_cdn_order
    log "下一步将下载 $OPENCLASH_DISPLAY_NAME 安装包并修改系统文件: /etc/config/appcenter 和 $TPL"
    confirm_or_exit "确认继续安装 $OPENCLASH_DISPLAY_NAME 并修改系统吗？"
    version_file="$WORKDIR/openclash/version"
    raw_ipk="$WORKDIR/openclash/openclash.ipk"
    fixed_ipk="$WORKDIR/openclash/openclash-fixed.ipk"

    log_stage 2 7 "下载 $OPENCLASH_DISPLAY_NAME 元数据与安装包"
    log "提示: 正在下载 $OPENCLASH_DISPLAY_NAME 版本文件..."
    download_from_mirrors "version" "$version_file" || die "无法从全部镜像获取 $OPENCLASH_DISPLAY_NAME 版本文件"
    mirror_base="$LAST_DOWNLOAD_SOURCE"
    last_ver="$(sed -n '1p' "$version_file" | sed 's/^v//g' | tr -d '\r\n')"
    [ -n "$last_ver" ] || die "无法解析 $OPENCLASH_DISPLAY_NAME 版本号"

    log "提示: 正在下载 $OPENCLASH_DISPLAY_NAME v$last_ver 安装包..."
    package_rel="luci-app-openclash_${last_ver}_all.ipk"
    package_urls="$(build_urls_from_base_list "$package_rel" "$OPENCLASH_MIRRORS")"
    package_probe_min_bytes="$(( (OPENCLASH_PACKAGE_PROBE_BYTES + 1) / 2 ))"
    rank_hosts_by_partial_download_probe "openclash-package" "$OPENCLASH_DISPLAY_NAME 安装包" "$package_urls" "$OPENCLASH_PACKAGE_PROBE_BYTES" "$package_probe_min_bytes"
    package_mirrors="$OPENCLASH_MIRRORS"
    if [ -n "$RANKED_URL_HOSTS" ]; then
        package_mirrors="$(reorder_urls_by_host_rank "$OPENCLASH_MIRRORS" "$RANKED_URL_HOSTS")"
        log "提示: $OPENCLASH_DISPLAY_NAME 安装包镜像优先级: $RANKED_URL_HOSTS"
    fi
    log "提示: $OPENCLASH_DISPLAY_NAME 安装包下载已放宽慢速判定与总时长限制，慢速网络下可能持续较久，请耐心等待"
    package_download_max_time_saved="$DOWNLOAD_MAX_TIME"
    package_download_stall_time_saved="$DOWNLOAD_STALL_TIME"
    package_download_stall_speed_saved="$DOWNLOAD_STALL_SPEED"
    package_download_keep_partial_saved="${DOWNLOAD_KEEP_PARTIAL:-0}"
    DOWNLOAD_MAX_TIME="$OPENCLASH_PACKAGE_MAX_TIME"
    DOWNLOAD_STALL_TIME="$OPENCLASH_PACKAGE_STALL_TIME"
    DOWNLOAD_STALL_SPEED="$OPENCLASH_PACKAGE_STALL_SPEED"
    DOWNLOAD_KEEP_PARTIAL=1
    package_mirror_base=""
    if download_from_mirrors "$package_rel" "$raw_ipk" "$package_mirrors"; then
        package_mirror_base="$LAST_DOWNLOAD_SOURCE"
    fi
    if [ -z "$package_mirror_base" ]; then
        log "提示: 首轮 $OPENCLASH_DISPLAY_NAME 安装包下载未完成，正在以更宽松的速度阈值继续重试..."
        DOWNLOAD_STALL_TIME="$OPENCLASH_PACKAGE_RETRY_STALL_TIME"
        DOWNLOAD_STALL_SPEED="$OPENCLASH_PACKAGE_RETRY_STALL_SPEED"
        if download_from_mirrors "$package_rel" "$raw_ipk" "$package_mirrors"; then
            package_mirror_base="$LAST_DOWNLOAD_SOURCE"
        else
            package_mirror_base=""
        fi
    fi
    DOWNLOAD_MAX_TIME="$package_download_max_time_saved"
    DOWNLOAD_KEEP_PARTIAL="$package_download_keep_partial_saved"
    if [ -z "$package_mirror_base" ]; then
        DOWNLOAD_MAX_TIME="$package_download_max_time_saved"
        DOWNLOAD_STALL_TIME="$package_download_stall_time_saved"
        DOWNLOAD_STALL_SPEED="$package_download_stall_speed_saved"
        rm -f "$raw_ipk.tmp"
        die "$OPENCLASH_DISPLAY_NAME 安装包下载失败"
    fi
    DOWNLOAD_MAX_TIME="$package_download_max_time_saved"
    DOWNLOAD_STALL_TIME="$package_download_stall_time_saved"
    DOWNLOAD_STALL_SPEED="$package_download_stall_speed_saved"
    [ -s "$raw_ipk" ] || die "$OPENCLASH_DISPLAY_NAME 安装包下载失败"
    oc_download_size="$(wc -c < "$raw_ipk" | tr -d ' ')"
    log "已下载: $OPENCLASH_DISPLAY_NAME v$last_ver ($oc_download_size bytes)"
    [ -n "${package_mirror_base:-}" ] && log "安装包来源: $package_mirror_base"

    log_stage 3 7 "刷新 opkg 软件源并检查依赖"
    ensure_opkg_update || die "opkg update 失败，已停止 $OPENCLASH_DISPLAY_NAME 安装"
    ensure_packages dnsmasq-full bash curl ca-bundle ip-full ruby ruby-yaml kmod-tun unzip || die "$OPENCLASH_DISPLAY_NAME 依赖安装失败，已停止安装本体"

    log_stage 4 7 "重打包并安装 $OPENCLASH_DISPLAY_NAME"
    extract_ipk_archive "$raw_ipk" "$WORKDIR/openclash/pkg"
    [ -f "$WORKDIR/openclash/pkg/control.tar.gz" ] || die "$OPENCLASH_DISPLAY_NAME 安装包缺少 control.tar.gz"
    [ -f "$WORKDIR/openclash/pkg/data.tar.gz" ] || die "$OPENCLASH_DISPLAY_NAME 安装包缺少 data.tar.gz"
    [ -f "$WORKDIR/openclash/pkg/debian-binary" ] || die "$OPENCLASH_DISPLAY_NAME 安装包缺少 debian-binary"
    tar -xzf "$WORKDIR/openclash/pkg/control.tar.gz" -C "$WORKDIR/openclash/control"
    sed -i \
        -e 's/, *luci-compat//g' \
        -e 's/luci-compat, *//g' \
        -e 's/luci-compat//g' \
        "$WORKDIR/openclash/control/control"
    tar -czf "$WORKDIR/openclash/pkg/control.tar.gz" -C "$WORKDIR/openclash/control" .
    (cd "$WORKDIR/openclash/pkg" && tar -czf "$fixed_ipk" ./debian-binary ./data.tar.gz ./control.tar.gz)
    [ -s "$fixed_ipk" ] || die "无法重新打包 $OPENCLASH_DISPLAY_NAME 安装包"

    backup_file "$CFG"
    if ! opkg install "$fixed_ipk" --force-reinstall >"$WORKDIR/openclash-install.log" 2>&1; then
        if ! opkg install "$fixed_ipk" --force-reinstall --force-maintainer >"$WORKDIR/openclash-install.log" 2>&1; then
            sed -n '1,200p' "$WORKDIR/openclash-install.log" >&2
            log "提示: 使用脚本 5 > 1 查看日志"
            log "日志: $WORKDIR/openclash-install.log"
            log "日志: $WORKDIR/nradio-plugin-opkg.update.log"
            log "日志: $WORKDIR/nradio-plugin-opkg.install.log"
            die "$OPENCLASH_DISPLAY_NAME 安装失败"
        fi
    fi

    oc_ver="$(opkg status luci-app-openclash 2>/dev/null | awk -F': ' '/Version: /{print $2; exit}')"
    [ -n "$oc_ver" ] || oc_ver="$last_ver"
    oc_size="$(wc -c < "$fixed_ipk" | tr -d ' ')"
    log_stage 5 7 "写入 LuCI、图标与应用商店接入"
    oc_icon_name=""
    if install_openclash_embedded_icon; then
        oc_icon_name="$OPENCLASH_ICON_NAME"
    fi
    set_appcenter_entry "luci-app-openclash" "luci-app-openclash" "$oc_ver" "$oc_size" "/usr/lib/lua/luci/controller/openclash.lua" "admin/services/openclash" "$oc_icon_name"
    uci commit appcenter

    fix_openclash_luci_compat
    write_openclash_switch_dashboard_template
    patch_openclash_switch_mode_template
    patch_openclash_dashboard_settings
    patch_openclash_cidr6_compat
    patch_openclash_original_page_tabs
    write_plugin_uninstall_assets
    patch_common_template
    refresh_luci_appcenter
    ensure_plugin_autostart_order
    log_stage 6 7 "检查并写入虚拟内存（swap）配置"
    ensure_openclash_swap_setup
    reduce_openclash_memory_pressure
    verify_appcenter_route "luci-app-openclash" "admin/services/openclash"
    verify_file_exists /usr/lib/lua/luci/controller/openclash.lua "$OPENCLASH_DISPLAY_NAME"
    verify_luci_route admin/services/openclash "$OPENCLASH_DISPLAY_NAME"
    verify_luci_route admin/services/openclash/settings "$OPENCLASH_DISPLAY_NAME"
    verify_luci_route admin/services/openclash/config-overwrite "$OPENCLASH_DISPLAY_NAME"
    verify_luci_route admin/services/openclash/config-subscribe "$OPENCLASH_DISPLAY_NAME"
    verify_luci_route admin/services/openclash/config "$OPENCLASH_DISPLAY_NAME"
    verify_luci_route admin/services/openclash/log "$OPENCLASH_DISPLAY_NAME"
    verify_file_exists /usr/lib/lua/luci/view/openclash/nradio_tabs.htm "$OPENCLASH_DISPLAY_NAME 原版页面标签"

    log_stage 7 7 "可选下载 smart 内核并完成最终校验"
    smart_core_downloaded='0'
    if confirm_default_yes "是否现在下载 $OPENCLASH_SMART_DISPLAY_NAME？"; then
        install_openclash_smart_core
        smart_core_downloaded='1'
        verify_file_exists /etc/openclash/core/clash_meta "$OPENCLASH_SMART_DISPLAY_NAME"
        verify_file_exists /etc/openclash/core/clash "$OPENCLASH_SMART_DISPLAY_NAME"
        log "备注:     smart core 已安装到 /etc/openclash/core"
    else
        log "备注:     已跳过 smart core 下载"
    fi

    log "安装完成"
    log "插件:   $OPENCLASH_DISPLAY_NAME"
    log "版本:  $oc_ver"
    log "路由:    admin/services/openclash"
    if [ "$smart_core_downloaded" = '1' ]; then
        log "核心:     $OPENCLASH_SMART_DISPLAY_NAME"
        log "核心版本: $smart_core_ver"
        log "核心路径: /etc/openclash/core"
    else
        log "核心:     未下载"
    fi
    log "下一步: 关闭应用商店弹窗后按 Ctrl+F5，再重新打开 $OPENCLASH_DISPLAY_NAME"
}

write_adguard_wrapper_files() {
    mkdir -p /usr/lib/lua/luci/controller /usr/lib/lua/luci/view/AdGuardHome /usr/lib/lua/luci/model/cbi/AdGuardHome
    cat > /usr/lib/lua/luci/controller/AdGuardHome.lua <<'EOF_ADG_CONTROLLER'
module("luci.controller.AdGuardHome",package.seeall)
local fs=require"nixio.fs"
local http=require"luci.http"
local sys=require"luci.sys"
local uci=require"luci.model.uci".cursor()
function index()
entry({"admin", "services", "AdGuardHome"},alias("admin", "services", "AdGuardHome", "oem"),_("AdGuardHome"), 10).dependent = true
entry({"admin","services","AdGuardHome","oem"},template("AdGuardHome/oem_wrapper"),_("总览"),0).leaf = true
entry({"admin","services","AdGuardHome","base"},cbi("AdGuardHome/base"),_("基础设置"),1).leaf = true
entry({"admin","services","AdGuardHome","log"},form("AdGuardHome/log"),_("运行日志"),2).leaf = true
entry({"admin","services","AdGuardHome","manual"},cbi("AdGuardHome/manual"),_("手动配置"),3).leaf = true
entry({"admin", "services", "AdGuardHome", "status"},call("act_status")).leaf=true
entry({"admin", "services", "AdGuardHome", "dashboard_stats"},call("act_dashboard_stats")).leaf=true
entry({"admin", "services", "AdGuardHome", "dashboard_runtime"},call("act_dashboard_runtime")).leaf=true
entry({"admin", "services", "AdGuardHome", "check"}, call("check_update"))
local doupdate=entry({"admin", "services", "AdGuardHome", "doupdate"}, call("do_update"))
doupdate.post=true
