local function adg_json_escape(value)
value = tostring(value or "")
value = value:gsub("\\", "\\\\")
value = value:gsub('"', '\\"')
value = value:gsub("\r", "\\r")
value = value:gsub("\n", "\\n")
value = value:gsub("\t", "\\t")
return value
end

local function adg_shell_quote(value)
value = tostring(value or "")
return "'" .. value:gsub("'", "'\\''") .. "'"
end

local function adg_read_primary_user(configpath)
local f = io.open(configpath, "r")
local in_users = false
if not f then
return ""
end
for line in f:lines() do
if line:match("^users:%s*$") then
in_users = true
elseif in_users and line:match("^[^%s%-#][^:]*:") then
break
elseif in_users then
local name = line:match("^%s*%-%s*name:%s*(.-)%s*$") or line:match("^%s*name:%s*(.-)%s*$")
if name and name ~= "" then
f:close()
return name
end
end
end
f:close()
return ""
end

local function adg_read_local_dns_runtime(configpath)
local hosts = {}
local port = ""
local f = io.open(configpath, "r")
local in_dns = false
local in_bind_hosts = false
if not f then
return hosts, port
end
for line in f:lines() do
if line:match("^dns:%s*$") then
in_dns = true
in_bind_hosts = false
elseif in_dns and line:match("^[^%s]") then
break
elseif in_dns then
if line:match("^%s*bind_hosts:%s*$") then
in_bind_hosts = true
else
local found_port = line:match("^%s*port:%s*(%S+)")
local host = line:match("^%s*%-%s*(.-)%s*$")
if found_port then
port = found_port
in_bind_hosts = false
elseif in_bind_hosts and host and host ~= "" then
table.insert(hosts, host)
elseif line:match("^%s*[A-Za-z0-9_]+:%s*") then
in_bind_hosts = false
end
end
end
end
f:close()
return hosts, port
end

local function adg_fetch_dashboard_json(path)
local configpath = uci:get("AdGuardHome", "AdGuardHome", "configpath") or "/etc/AdGuardHome.yaml"
local httpport = uci:get("AdGuardHome", "AdGuardHome", "httpport") or "3000"
local user = uci:get("AdGuardHome", "AdGuardHome", "dashboard_user") or ""
local pass = uci:get("AdGuardHome", "AdGuardHome", "dashboard_password") or ""
local dashboard_base
local cookiefile
local login_body
local login_body_file
local login_cmd
local login_out
local data

if not tostring(httpport):match("^%d+$") then
httpport = "3000"
end
dashboard_base = "http://127.0.0.1:" .. httpport

if user == "" then
user = adg_read_primary_user(configpath)
end
if user == "" then
user = "admin"
end
if pass == "" then
return nil, "未填写仪表盘认证密码"
end
cookiefile = sys.exec("mktemp /tmp/adg_dashboard_cookie.XXXXXX 2>/dev/null"):gsub("%s+$", "")
if cookiefile == "" then
return nil, "无法安全创建仪表盘会话文件"
end

login_body = '{"name":"' .. adg_json_escape(user) .. '","password":"' .. adg_json_escape(pass) .. '"}'
login_body_file = sys.exec("mktemp /tmp/adg_dashboard_login.XXXXXX 2>/dev/null"):gsub("%s+$", "")
if login_body_file == "" then
sys.exec("rm -f " .. adg_shell_quote(cookiefile))
return nil, "无法安全创建仪表盘登录请求"
end
if not fs.writefile(login_body_file, login_body) then
sys.exec("rm -f " .. adg_shell_quote(cookiefile) .. " " .. adg_shell_quote(login_body_file))
return nil, "无法创建仪表盘登录请求"
end
fs.chmod(login_body_file, "0600")
login_cmd = "rm -f " .. adg_shell_quote(cookiefile) ..
	" ; wget -q --save-cookies=" .. adg_shell_quote(cookiefile) ..
	" --keep-session-cookies --header=" .. adg_shell_quote("Content-Type: application/json") ..
	" --post-file=" .. adg_shell_quote(login_body_file) ..
	" -O - " .. adg_shell_quote(dashboard_base .. "/control/login") .. " 2>/dev/null"
login_out = sys.exec(login_cmd)
sys.exec("rm -f " .. adg_shell_quote(login_body_file))
if not login_out:find("OK", 1, true) then
sys.exec("rm -f " .. adg_shell_quote(cookiefile))
return nil, "仪表盘登录失败"
end

data = sys.exec(
	"wget -q --load-cookies=" .. adg_shell_quote(cookiefile) ..
	" -O - " .. adg_shell_quote(dashboard_base .. path) .. " 2>/dev/null"
)
sys.exec("rm -f " .. adg_shell_quote(cookiefile))

if data == nil or data == "" then
return nil, "仪表盘数据读取失败"
end

return data
end
function get_template_config()
local b
local d=""
local rf=io.open("/tmp/resolv.conf.auto", "r")
if rf then
local lan_ip = uci:get("network", "lan", "ipaddr") or ""
for cnt in rf:lines() do
b=string.match (cnt,"^[^#]*nameserver%s+([^%s]+)$")
if (b~=nil) and not b:match("^127%.") and b ~= "0.0.0.0" and b ~= "::1" and b ~= lan_ip then
d=d.."  - "..b.."\n"
end
end
rf:close()
end
local f=io.open("/usr/share/AdGuardHome/AdGuardHome_template.yaml", "r+")
if not f then
http.prepare_content("text/plain; charset=utf-8")
http.write("")
return
end
local tbl = {}
local a=""
while (1) do
a=f:read("*l")
if (a=="#bootstrap_dns") then
a=d
elseif (a=="#upstream_dns") then
a=d
elseif (a==nil) then
break
end
table.insert(tbl, a)
end
f:close()
http.prepare_content("text/plain; charset=utf-8")
http.write(table.concat(tbl, "\n"))
end
function reload_config()
fs.remove("/tmp/AdGuardHometmpconfig.yaml")
http.prepare_content("application/json")
http.write('')
end
function act_status()
local e={}
local binpath=uci:get("AdGuardHome","AdGuardHome","binpath") or "/usr/bin/AdGuardHome/AdGuardHome"
local configpath=uci:get("AdGuardHome","AdGuardHome","configpath") or "/etc/AdGuardHome.yaml"
local httpport=uci:get("AdGuardHome","AdGuardHome","httpport") or "3000"
local redirect=uci:get("AdGuardHome","AdGuardHome","redirect") or "none"
local version=uci:get("AdGuardHome","AdGuardHome","version") or ""
local coreversion=uci:get("AdGuardHome","AdGuardHome","coreversion") or ""
local listen_hosts, dnsport = adg_read_local_dns_runtime(configpath)
if dnsport == "" then
dnsport="?"
end
e.running=(binpath ~= "" and sys.call("pgrep -f " .. adg_shell_quote(binpath) .. " >/dev/null")==0) or false
e.redirect=(fs.readfile("/var/run/AdGredir")=="1")
e.redirect_mode=redirect
e.httpport=httpport
e.dnsport=dnsport
e.listen_hosts=listen_hosts
e.listen_text=table.concat(listen_hosts, " / ")
e.version=version
e.coreversion=coreversion
e.config_ok=fs.access(configpath) and true or false
e.bin_ok=fs.access(binpath) and true or false
e.dashboard_auth_ready=((uci:get("AdGuardHome","AdGuardHome","dashboard_password") or "") ~= "")
http.prepare_content("application/json")
http.write_json(e)
end

function act_dashboard_stats()
local data, err = adg_fetch_dashboard_json("/control/stats")
http.prepare_content("application/json")
if not data then
http.write_json({ ok = false, error = err })
return
end
http.write(data)
end

function act_dashboard_runtime()
local data, err = adg_fetch_dashboard_json("/control/status")
http.prepare_content("application/json")
if not data then
http.write_json({ ok = false, error = err })
return
end
http.write(data)
end
function do_update()
http.prepare_content("application/json")
local update_script="/usr/share/AdGuardHome/update_core.sh"
if not fs.access(update_script) then
http.write_json({ok=false, error="核心更新脚本缺失"})
return
end
if fs.access("/var/run/update_core") then
http.write_json({ok=false, error="已有核心更新正在运行，请等待完成"})
return
end
local base="/var/run/nradio-adg-update"
local prior_pid=(fs.readfile(base..".pid") or ""):match("^%s*(%d+)%s*$")
if prior_pid and sys.call("kill -0 "..prior_pid.." 2>/dev/null")==0 then
http.write_json({ok=true, state="running"})
return
end
fs.unlink(base..".rc")
fs.unlink(base..".pid")
if not fs.writefile(base..".started",tostring(os.time())) or not fs.writefile(base..".state","running") then
http.write_json({ok=false, error="无法写入更新任务状态"})
return
end
local finish="rc=$?; echo \"$rc\" > "..base..".rc; if [ \"$rc\" -eq 0 ]; then echo ok > "..base..".state; else echo fail > "..base..".state; fi; rm -f "..base..".pid"
local body="echo $$ > "..base..".pid; trap "..adg_shell_quote(finish).." EXIT; trap 'exit 1' HUP INT TERM; sh "..adg_shell_quote(update_script)
if http.formvalue("force")=="1" then body=body.." force" end
local rc=sys.call("sh -c "..adg_shell_quote(body).." >/var/log/AdGuardHome_update.log 2>&1 </dev/null &")
if rc~=0 then fs.writefile(base..".state","fail") end
http.write_json({ok=rc==0, state=rc==0 and "running" or "fail", error=rc~=0 and "无法启动核心更新" or nil})
end
local function adg_safe_logfile(path, allow_missing)
if type(path) ~= "string" or path == "" or path:sub(1, 1) ~= "/" or path:find("/../", 1, true) or path:match("/%.%.$") then
return nil
end
if not (path == "/tmp/AdGuardHome.log" or path:match("^/tmp/AdGuardHome/[%w%._/-]+$") or path == "/var/log/AdGuardHome.log" or path:match("^/var/log/AdGuardHome/[%w%._/-]+$") or path:match("^/usr/bin/AdGuardHome/[%w%._/-]+$")) then
return nil
end
local st = fs.lstat(path)
if st == nil and allow_missing then
return path
end
if not st or st.type ~= "reg" then
return nil
end
if path:match("^/tmp/") and tonumber(st.uid or -1) ~= 0 then
return nil
end
return path
end

function get_log()
local logfile=uci:get("AdGuardHome","AdGuardHome","logfile")
logfile=adg_safe_logfile(logfile, false)
if logfile==nil then
http.write("no log available\n")
return
end
local stat=fs.stat(logfile)
if not stat or tonumber(stat.size or 0) > 1048576 then
http.write("log unavailable or larger than 1 MiB\n")
return
end
local handle=io.open(logfile,"rb")
if not handle then http.write("can't open log file\n"); return end
local data=handle:read(1048576) or ""
handle:close()
http.write(data)
end
function do_dellog()
local logfile=uci:get("AdGuardHome","AdGuardHome","logfile")
logfile=adg_safe_logfile(logfile, false)
if logfile then
local handle=io.open(logfile,"wb")
if handle then handle:close() end
end
http.prepare_content("application/json")
http.write('')
end
function check_update()
local e={}
local makefile=fs.readfile("/usr/share/AdGuardHome/Makefile") or ""
local pkg_ver=makefile:match("PKG_VERSION%s*:?=%s*([^\r\n]+)") or ""
pkg_ver=pkg_ver:gsub("^%s+",""):gsub("%s+$","")
e.luciversion=pkg_ver
e.coreversion=uci:get("AdGuardHome","AdGuardHome","coreversion") or ""
local base="/var/run/nradio-adg-update"
e.state=(fs.readfile(base..".state") or "idle"):gsub("%s+","")
e.rc=tonumber(fs.readfile(base..".rc") or "")
e.log=sys.exec("tail -c 8192 /var/log/AdGuardHome_update.log 2>/dev/null") or ""
if e.state=="running" then
local pid=(fs.readfile(base..".pid") or ""):match("^%s*(%d+)%s*$")
local started=tonumber(fs.readfile(base..".started") or "") or 0
if os.time()-started>10 and (not pid or sys.call("kill -0 "..pid.." 2>/dev/null")~=0) then
e.state="fail"
e.error="核心更新进程已退出，未记录完成结果"
end
end
http.prepare_content("application/json")
http.write_json(e)
end
