<script>
function adgMarkFrameLoaded() {
    var wrap = document.querySelector('.adg-frame-wrap');
    if (!wrap) return;
    wrap.className = wrap.className.replace(/\s*adg-frame-loading\b/g, '');
}
function adgResizeFrame() {
    var frame = document.getElementById('adg_frame');
    if (!frame) return;
    try {
        var d = frame.contentWindow.document;
        var h1 = d.body ? d.body.scrollHeight : 0;
        var h2 = d.documentElement ? d.documentElement.scrollHeight : 0;
        var height = Math.max(h1, h2, 760);
        frame.style.height = height + 'px';
    } catch (e) {}
}
function adgEnableTouchScroll(d) {
    var lastY = 0;
    var tracking = false;
    var startOptions = {passive: true};
    var moveOptions = {passive: false};
    if (!d || !d.addEventListener) return;
    if (d.__adgTouchStart) d.removeEventListener('touchstart', d.__adgTouchStart, startOptions);
    if (d.__adgTouchMove) d.removeEventListener('touchmove', d.__adgTouchMove, moveOptions);
    if (d.__adgTouchEnd) {
        d.removeEventListener('touchend', d.__adgTouchEnd, startOptions);
        d.removeEventListener('touchcancel', d.__adgTouchEnd, startOptions);
    }
    d.__adgTouchStart = function(event) {
        if (!event.touches || event.touches.length !== 1) return;
        tracking = true;
        lastY = event.touches[0].clientY;
    };
    d.__adgTouchMove = function(event) {
        var currentY;
        var delta;
        var target;
        if (!tracking || !event.touches || event.touches.length !== 1) return;
        currentY = event.touches[0].clientY;
        delta = lastY - currentY;
        lastY = currentY;
        target = event.target;
        while (target && target !== d.body && target !== d.documentElement) {
            var overflow = d.defaultView.getComputedStyle(target).overflowY;
            if (/auto|scroll/.test(overflow) && target.scrollHeight > target.clientHeight &&
                (delta < 0 ? target.scrollTop > 0 : target.scrollTop + target.clientHeight < target.scrollHeight)) break;
            target = target.parentElement;
        }
        if (!target || target === d.body || target === d.documentElement)
            target = document.scrollingElement || document.documentElement || document.body;
        if (Math.abs(delta) < 1 || !target || target.scrollHeight <= target.clientHeight) return;
        var before = target.scrollTop;
        target.scrollTop += delta;
        if (target.scrollTop !== before) event.preventDefault();
    };
    d.__adgTouchEnd = function() { tracking = false; };
    d.addEventListener('touchstart', d.__adgTouchStart, startOptions);
    d.addEventListener('touchmove', d.__adgTouchMove, moveOptions);
    d.addEventListener('touchend', d.__adgTouchEnd, startOptions);
    d.addEventListener('touchcancel', d.__adgTouchEnd, startOptions);
}
function adgInstallInnerSkin(d) {
    var style;
    if (!d || !d.head) return;
    if (d.body && (' ' + d.body.className + ' ').indexOf(' adg-embedded-page ') < 0) {
        d.body.className += (d.body.className ? ' ' : '') + 'adg-embedded-page';
    }
    if (d.getElementById('adg-wrapper-inner-skin')) return;
    style = d.createElement('style');
    style.id = 'adg-wrapper-inner-skin';
    style.appendChild(d.createTextNode(
        'html,body{background:#2e2e38!important;}' +
        '.adg-embedded-page *{box-sizing:border-box!important;min-width:0;}' +
        '.adg-embedded-page .container.body-container{max-width:none!important;}' +
        '.adg-embedded-page .cbi-map{margin:0!important;border:0!important;background:transparent!important;box-shadow:none!important;}' +
        '.adg-embedded-page .cbi-map>h2,.adg-embedded-page .cbi-map>.cbi-map-descr{display:none!important;}' +
        '.adg-embedded-page .cbi-section{position:relative!important;overflow:hidden!important;margin:0 0 12px!important;padding:16px 18px 15px!important;border:1px solid rgba(78,96,131,.72)!important;border-radius:14px!important;background:radial-gradient(circle at 100% 0%,rgba(34,211,238,.08),transparent 26%),linear-gradient(180deg,rgba(34,40,55,.985),rgba(23,28,40,.985))!important;box-shadow:inset 0 1px 0 rgba(255,255,255,.04),0 14px 30px rgba(0,0,0,.18)!important;}' +
        '.adg-embedded-page .cbi-section legend,.adg-embedded-page .cbi-section h3{display:flex!important;align-items:center!important;gap:8px!important;padding:0 0 9px!important;color:#f3f7ff!important;font-size:16px!important;font-weight:800!important;line-height:1.25!important;letter-spacing:0!important;overflow-wrap:anywhere!important;}' +
        '.adg-embedded-page .cbi-section legend:before,.adg-embedded-page .cbi-section h3:before{content:"";width:15px;height:15px;border-radius:6px;background:linear-gradient(135deg,rgba(47,211,238,.88),rgba(108,162,255,.68));box-shadow:inset 0 1px 0 rgba(255,255,255,.22);flex:0 0 auto;}' +
        '.adg-embedded-page .cbi-value{display:grid!important;grid-template-columns:minmax(160px,230px) minmax(0,1fr)!important;gap:7px 16px!important;align-items:start!important;padding:11px 0!important;border-top:1px solid rgba(255,255,255,.055)!important;}' +
        '.adg-embedded-page .cbi-value-title{float:none!important;width:auto!important;max-width:none!important;margin:0!important;color:#dce9fd!important;font-size:13px!important;font-weight:800!important;line-height:1.34!important;letter-spacing:0!important;overflow-wrap:anywhere!important;}' +
        '.adg-embedded-page .cbi-value-field{float:none!important;width:100%!important;max-width:680px!important;margin:0!important;padding:0!important;display:grid!important;gap:8px!important;}' +
        '.adg-embedded-page input[type=text],.adg-embedded-page input[type=password],.adg-embedded-page select,.adg-embedded-page textarea{width:100%!important;min-height:42px!important;border:1px solid rgba(84,100,134,.9)!important;border-radius:12px!important;background:linear-gradient(180deg,rgba(34,39,54,.985),rgba(22,27,38,.985))!important;color:#eef4ff!important;box-shadow:inset 0 1px 0 rgba(255,255,255,.04),0 8px 18px rgba(0,0,0,.12)!important;box-sizing:border-box!important;}' +
        '.adg-embedded-page input[type=text]:focus-visible,.adg-embedded-page input[type=password]:focus-visible,.adg-embedded-page select:focus-visible,.adg-embedded-page textarea:focus-visible{outline:2px solid rgba(194,248,255,.72)!important;outline-offset:2px!important;border-color:rgba(194,248,255,.46)!important;}' +
        '.adg-embedded-page textarea{min-height:220px!important;font-family:Consolas,"Courier New",monospace!important;line-height:1.52!important;white-space:pre-wrap!important;overflow:auto!important;tab-size:4!important;}' +
        '.adg-embedded-page input[type=submit],.adg-embedded-page input[type=button],.adg-embedded-page .cbi-button{min-height:40px!important;padding:0 16px!important;border:1px solid #39a0ff!important;border-radius:12px!important;background:linear-gradient(180deg,#2a9cff,#1177de)!important;color:#f0faff!important;font-weight:800!important;line-height:38px!important;box-shadow:inset 0 1px 0 rgba(255,255,255,.16),0 9px 18px rgba(26,124,215,.18)!important;}' +
        '.adg-embedded-page input[type=submit],.adg-embedded-page input[type=button],.adg-embedded-page .cbi-button{max-width:100%!important;overflow:hidden!important;text-overflow:ellipsis!important;white-space:nowrap!important;}' +
        '.adg-embedded-page input[type=submit]:hover,.adg-embedded-page input[type=button]:hover,.adg-embedded-page .cbi-button:hover{filter:brightness(1.05)!important;}' +
        '.adg-embedded-page input[disabled],.adg-embedded-page select[disabled],.adg-embedded-page textarea[disabled],.adg-embedded-page .cbi-button[disabled]{cursor:not-allowed!important;opacity:.60!important;filter:saturate(.72)!important;}' +
        '.adg-embedded-page .cbi-value-description{margin-top:3px!important;color:#9fb1cf!important;font-size:12px!important;line-height:1.52!important;overflow-wrap:anywhere!important;}' +
        '.adg-embedded-page .cbi-page-actions{display:flex!important;justify-content:flex-end!important;gap:8px!important;flex-wrap:wrap!important;padding:12px 0 0!important;}' +
        '.adg-embedded-page textarea::-webkit-scrollbar{width:9px!important;height:9px!important}.adg-embedded-page textarea::-webkit-scrollbar-track{background:rgba(255,255,255,.035)!important}.adg-embedded-page textarea::-webkit-scrollbar-thumb{border-radius:999px!important;background:rgba(143,164,199,.42)!important}' +
        '@media(max-width:720px){.adg-embedded-page .cbi-section{padding:14px 12px!important;border-radius:12px!important}.adg-embedded-page .cbi-value{grid-template-columns:1fr!important}.adg-embedded-page .cbi-value-field{max-width:none!important}.adg-embedded-page input[type=submit],.adg-embedded-page input[type=button],.adg-embedded-page .cbi-button{width:100%!important;min-width:0!important}}'
    ));
    d.head.appendChild(style);
}
function adgHideInnerChrome() {
    var frame = document.getElementById('adg_frame');
    if (!frame) return;
    try {
        var d = frame.contentWindow.document;
        var hideSelectors = ['header', '.menu_mobile', '.mobile_bg_color.container.body-container.visible-xs-block', '.footer', '.tail_wave'];
        for (var i = 0; i < hideSelectors.length; i++) {
            var nodes = d.querySelectorAll(hideSelectors[i]);
            for (var j = 0; j < nodes.length; j++) nodes[j].style.display = 'none';
        }
        var containers = d.querySelectorAll('.container.body-container');
        for (var k = 0; k < containers.length; k++) {
            if (!containers[k].classList.contains('visible-xs-block')) {
                containers[k].style.width = '100%';
                containers[k].style.margin = '0';
                containers[k].style.padding = '0 10px';
            }
        }
        var main = d.querySelector('.main');
        if (main) { main.style.width = '100%'; main.style.margin = '0'; }
        var content = d.querySelector('.main-content');
        if (content) { content.style.width = '100%'; content.style.margin = '0'; content.style.padding = '0'; }
        if (d.body) { d.body.style.marginTop = '0'; d.body.style.paddingTop = '0'; }
        adgInstallInnerSkin(d);
        adgEnableTouchScroll(d);
    } catch (e) {}
}
function adgAfterLoad() {
    adgHideInnerChrome();
    adgResizeFrame();
    adgMarkFrameLoaded();
    setTimeout(function() { adgHideInnerChrome(); adgResizeFrame(); }, 300);
    setTimeout(function() { adgHideInnerChrome(); adgResizeFrame(); }, 900);
    setTimeout(function() { adgHideInnerChrome(); adgResizeFrame(); }, 1800);
}
(function() {
    var frame = document.getElementById('adg_frame');
    if (frame) {
        frame.onload = adgAfterLoad;
    }
    setTimeout(adgAfterLoad, 80);
})();
window.addEventListener('resize', function() {
    setTimeout(adgResizeFrame, 120);
});
</script>
<%+footer%>
EOF

    cat > /usr/lib/lua/luci/view/AdGuardHome/AdGuardHome_status.htm <<'EOF_ADG_STATUS'
<script type="text/javascript">//<![CDATA[
function adgFormatNumber(value) {
	var text = String(value || 0);
	return text.replace(/\B(?=(\d{3})+(?!\d))/g, ",");
}

function adgStatusText(running) {
	return running ? "运行中" : "未运行";
}

function adgProtectText(enabled) {
	return enabled ? "已启用" : "已暂停";
}

function adgRedirectText(mode, redirected) {
	if (redirected) {
		switch (mode || "") {
		case "dnsmasq-upstream":
			return "dnsmasq 上游";
		case "redirect":
			return "53 重定向";
		case "exchange":
			return "替换 53 端口";
		default:
			return "已接管";
		}
	}
	if (mode && mode !== "none") {
		return mode;
	}
	return "未启用";
}

function adgListenText(addresses) {
	if (!addresses || !addresses.length) {
		return "未读取";
	}
	if (addresses.length <= 2) {
		return addresses.join(" / ");
	}
	return addresses[0] + " / " + addresses[1] + " +" + (addresses.length - 2);
}

function adgHasRuntimePayload(runtime) {
	return !!(runtime && runtime.ok !== false && (
		typeof runtime.running !== "undefined" ||
		typeof runtime.protection_enabled !== "undefined" ||
		typeof runtime.http_port !== "undefined" ||
		typeof runtime.dns_port !== "undefined" ||
		(runtime.dns_addresses && runtime.dns_addresses.length)
	));
}

function adgHasStatsPayload(data) {
	return !!(data && data.ok !== false && (
		typeof data.num_dns_queries !== "undefined" ||
		typeof data.num_blocked_filtering !== "undefined" ||
		(data.dns_queries && data.dns_queries.length) ||
		(data.blocked_filtering && data.blocked_filtering.length)
	));
}

function adgSetRefreshState(loading) {
	var button = document.getElementById("adg-stats-refresh");
	if (!button) {
		return;
	}
	button.className = button.className.replace(/\s*adg-button-loading\b/g, "");
	if (loading) {
		button.className += " adg-button-loading";
	}
	button.disabled = !!loading;
	button.value = loading ? "刷新中..." : "刷新统计数据";
	button.setAttribute("aria-busy", loading ? "true" : "false");
	button.setAttribute("title", loading ? "正在刷新统计数据" : "刷新仪表盘统计数据");
}

window.adgDashboardHttpPort = "";

function adgHostForPort() {
	var host = window.location.hostname || "127.0.0.1";
	if (host.indexOf(":") >= 0 && host.charAt(0) !== "[") {
		host = "[" + host + "]";
	}
	return host;
}

function adgOpenOriginalDashboard() {
	var port = window.adgDashboardHttpPort || "";
	if (!port) {
		return;
	}
	window.open("http://" + adgHostForPort() + ":" + port + "/", "_blank");
}

function adgBuildLinePath(values, width, height, padding) {
	var i;
	var max = 0;
	var min = null;
	var step;
	var x;
	var y;
	var path = "";

	if (!values || !values.length) {
		return "";
	}

	for (i = 0; i < values.length; i++) {
		values[i] = Number(values[i] || 0);
		if (values[i] > max) {
			max = values[i];
		}
		if (min === null || values[i] < min) {
			min = values[i];
		}
	}

	if (max === 0) {
		max = 1;
	}
	if (min === null) {
		min = 0;
	}

	step = values.length > 1 ? (width - padding * 2) / (values.length - 1) : 0;

	for (i = 0; i < values.length; i++) {
		x = padding + step * i;
		y = height - padding - ((values[i] - min) / (max - min || 1)) * (height - padding * 2);
		path += (i === 0 ? "M" : " L") + x.toFixed(2) + " " + y.toFixed(2);
	}

	return path;
}

function adgBuildAreaPath(values, width, height, padding) {
	var line = adgBuildLinePath(values, width, height, padding);
	if (!line) {
		return "";
	}
	return line + " L" + (width - padding).toFixed(2) + " " + (height - padding).toFixed(2) + " L" + padding.toFixed(2) + " " + (height - padding).toFixed(2) + " Z";
}

function adgApplyChart(lineId, areaId, values) {
	var lineNode = document.getElementById(lineId);
	var areaNode = document.getElementById(areaId);
	var chartNode = lineNode ? lineNode.parentNode : null;
	var shellNode = chartNode && chartNode.parentNode ? chartNode.parentNode : null;
	var width = 360;
	var height = 110;
	var padding = 8;
	var line = adgBuildLinePath(values, width, height, padding);
	var area = adgBuildAreaPath(values, width, height, padding);

	if (lineNode) {
		lineNode.setAttribute("d", line || "");
	}
	if (areaNode) {
		areaNode.setAttribute("d", area || "");
	}
	if (chartNode && chartNode.className && typeof chartNode.className.baseVal === "string") {
		chartNode.className.baseVal = chartNode.className.baseVal.replace(/\s*adg-chart-empty\b/g, "");
	}
	if (shellNode && typeof shellNode.className === "string") {
		shellNode.className = shellNode.className.replace(/\s*adg-chart-empty\b/g, "");
		if (!values || !values.length) {
			adgAddClass(shellNode, "adg-chart-empty");
		}
	}
}

function adgSetInlineNote(message, tone) {
	var note = document.getElementById("adg-inline-note");
	if (!note) {
		return;
	}
	note.className = "adg-inline-note adg-inline-note-" + (tone || "soft");
	note.textContent = message;
}

function adgHasClass(node, className) {
	return !!(node && (" " + node.className + " ").indexOf(" " + className + " ") !== -1);
}

function adgAddClass(node, className) {
	if (!node || adgHasClass(node, className)) {
		return;
	}
	node.className += (node.className ? " " : "") + className;
}

function adgLocalizeOuterTabs(root) {
	root = root || document;
	var nodes = root.querySelectorAll("a, span, li");
	var map = {
		"Overview": "总览",
		"Base Setting": "基础设置",
		"Manual Config": "手动配置",
		"Log": "运行日志"
	};
	var text;
	var i;
	for (i = 0; i < nodes.length; i++) {
		text = (nodes[i].textContent || "").replace(/^\s+|\s+$/g, "");
		if (map[text]) {
			nodes[i].textContent = map[text];
		}
	}
}

function adgPolishParentShell() {
	var doc;
	var style;
	var css;
	try {
		if (!window.parent || !window.parent.document || window.parent === window) {
			return;
		}
		doc = window.parent.document;
		adgLocalizeOuterTabs(doc);
		css = [
			".modal.app_frame .modal-body,.modal.app_frame .bootstrap-dialog-message,.modal.app_frame .app_frame_box{background:#2e2e38!important;}",
			".modal.app_frame{overflow-y:auto!important;-webkit-overflow-scrolling:touch!important;overscroll-behavior-y:contain!important;}",
			".modal.app_frame .modal-body,.modal.app_frame .bootstrap-dialog-message{scrollbar-color:rgba(111,202,255,.55) rgba(255,255,255,.08)!important;scrollbar-width:thin!important;}",
			".modal.app_frame .app_frame_nav{border-bottom-color:rgba(255,255,255,.12)!important;}",
			".modal.app_frame iframe,.modal.app_frame #sub_frame,.modal.app_frame iframe[name='subpage']{display:block!important;border:0!important;background:#2e2e38!important;}",
			".modal-backdrop,.bootstrap-dialog-backdrop{background:rgba(3,6,12,.82)!important;}"
		].join(" ");
		style = doc.getElementById("adg-parent-shell-polish");
		if (!style) {
			style = doc.createElement("style");
			style.id = "adg-parent-shell-polish";
			(doc.head || doc.documentElement).appendChild(style);
		}
		style.textContent = css;
	} catch (e) {}
}

function adgUpdateLogNode() {
	return document.getElementById("cbid.logview.1.conf") || document.querySelector("textarea[id*='logview']");
}

function adgUpdateLooksLikePageSource(text) {
	text = String(text || "");
	return text.indexOf("<![CDATA[") >= 0 ||
		text.indexOf("document.getElementById") >= 0 ||
		text.indexOf("AdGuardHome/AdGuardHome_check") >= 0 ||
		text.indexOf("Dashboard API user") >= 0 ||
		text.indexOf("仪表盘 API 用户") >= 0 ||
		text.indexOf("<script") >= 0 ||
		text.indexOf("cbi-map") >= 0;
}

function adgParseUpdateStatusText(text) {
	var lines = String(text || "").split(/\r?\n/);
	var last = null;
	var item;
	var i;
	for (i = 0; i < lines.length; i++) {
		item = lines[i].replace(/^\s+|\s+$/g, "");
		if (!item) {
			continue;
		}
		if (!/^\{[\s\S]*\}$/.test(item)) {
			return null;
		}
		try {
			last = JSON.parse(item);
		} catch (e) {
			return null;
		}
	}
	return last && (typeof last.luciversion !== "undefined" || typeof last.coreversion !== "undefined") ? last : null;
}

function adgSetUpdateLog(text) {
	var logNode = adgUpdateLogNode();
	if (!logNode) {
		return;
	}
	if ("value" in logNode) {
		logNode.value = text;
	}
	logNode.textContent = text;
	logNode.scrollTop = logNode.scrollHeight;
}

function adgAppendUpdateLog(text) {
	var logNode = adgUpdateLogNode();
	var current;
	var next;
	var status;
	if (!logNode || text === null || typeof text === "undefined") {
		return;
	}
	text = String(text);
	if (adgUpdateLooksLikePageSource(text)) {
		adgSetUpdateLog("更新接口返回了 LuCI 页面源码，已拦截异常输出。");
		return;
	}
	status = adgParseUpdateStatusText(text);
	if (status) {
		adgSetUpdateLog("当前核心版本：" + (status.coreversion || "latest"));
		return;
	}
	current = "value" in logNode ? logNode.value : logNode.textContent;
	next = window.islogreverse ? text.split("\n").reverse().join("\n") + current : current + text;
	adgSetUpdateLog(next);
}

function adgPollUpdateCheck() {
	var tag = document.getElementById("logview");
	if (tag) {
		tag.style.display = "block";
	}
	if (window.adgUpdatePollActive) {
		return;
	}
	window.adgUpdatePollActive = true;
    function poll() {
        XHR.get('<%=url([[admin]], [[services]], [[AdGuardHome]], [[check]])%>', {_:Date.now()}, function(x, status) {
            if (!x || x.status !== 200 || !status || !status.state) {
                adgFinishUpdate(false, "更新状态读取失败，可重新检查");
                return;
            }
            adgSetUpdateLog((status.log || "") + (status.error ? "\n" + status.error : ""));
            if (status.state === "running") {
                window.setTimeout(poll, 3000);
                return;
            }
            adgFinishUpdate(status.state === "ok", status.state === "ok" ? "已更新" : "更新未完成");
        });
    }
    poll();
}

function adgFinishUpdate(ok, message) {
    window.adgUpdatePollActive = false;
    var btn = document.getElementById("apply_update_button");
    if (btn) { btn.disabled = false; btn.value = message || (ok ? "已更新" : "更新失败"); }
}
function adgRequestUpdate(force) {
    var btn = document.getElementById("apply_update_button");
    if (window.adgUpdatePollActive || (btn && btn.disabled)) return;
    if (btn) { btn.disabled = true; btn.value = "检查中..."; }
    adgSetUpdateLog("");
    XHR.post('<%=url([[admin]], [[services]], [[AdGuardHome]], [[doupdate]])%>',
        {token:'<%=require("luci.dispatcher").context.authtoken%>',force:force ? 1 : 0},
        function(x, data) {
            if (!x || x.status !== 200 || !data || !data.ok) {
                var message = data && data.error ? data.error : "更新启动失败";
                adgSetUpdateLog(message);
                adgFinishUpdate(false, message);
                return;
            }
            adgPollUpdateCheck();
        });
}

function adgInstallUpdatePanelGuard() {
	var updatebtn = document.getElementById("apply_update_button");
	var forceupdatebtn = document.getElementById("apply_forceupdate_button");
	var logNode = adgUpdateLogNode();
	if (!updatebtn && !forceupdatebtn && !logNode) {
		return;
	}
	if (logNode) {
		adgAddClass(logNode, "adg-update-log");
		if (adgUpdateLooksLikePageSource(("value" in logNode ? logNode.value : logNode.textContent))) {
			adgSetUpdateLog("更新日志等待中。");
		}
	}
	window.reverselog = function() {
		var node = adgUpdateLogNode();
		var text;
		if (!node) {
			return;
		}
		text = "value" in node ? node.value : node.textContent;
		window.islogreverse = !window.islogreverse;
		adgSetUpdateLog(text.split("\n").reverse().join("\n"));
	};
	window.poll_check = adgPollUpdateCheck;
	window.apply_update = function() {
		var forcebtn = document.getElementById("apply_forceupdate_button");
		if (forcebtn) {
			forcebtn.style.display = "inline";
		}
		adgRequestUpdate(false);
	};
	window.apply_forceupdate = function() {
		adgRequestUpdate(true);
	};
}

function adgApplyRuntime(runtime, status) {
	var runNode = document.getElementById("adg-runtime-running");
	var protectNode = document.getElementById("adg-runtime-protect");
	var redirectNode = document.getElementById("adg-runtime-redirect");
	var listenNode = document.getElementById("adg-runtime-listen");
	var portNode = document.getElementById("adg-runtime-port");
	var coreNode = document.getElementById("adg-runtime-core");
	var glanceModeNode = document.getElementById("adg-glance-mode");
	var glanceAuthNode = document.getElementById("adg-glance-auth");
	var glanceListenNode = document.getElementById("adg-glance-listen");
	var shellNode = document.getElementById("adg-dashboard-shell");
	var openButton = document.getElementById("adg-open-dashboard");
	var runtimeOk = adgHasRuntimePayload(runtime);
	var running = runtimeOk ? !!runtime.running : !!(status && status.running);
	var tone = running ? "ok" : "bad";
	var httpPort = (runtimeOk && runtime.http_port) || (status && status.httpport) || "3000";
	var dnsPort = (runtimeOk && runtime.dns_port) || (status && status.dnsport) || "?";
	var redirectText = adgRedirectText(status && status.redirect_mode, status && status.redirect);
	var coreText = (status && status.version) || (status && status.coreversion) || (runtime && runtime.version) || "-";
	var listenText = (runtimeOk && runtime.dns_addresses && runtime.dns_addresses.length)
		? adgListenText(runtime.dns_addresses)
		: ((status && status.listen_hosts && status.listen_hosts.length)
			? adgListenText(status.listen_hosts)
			: ((status && status.listen_text) || "未读取"));
	var protectText = runtimeOk
		? adgProtectText(runtime && runtime.protection_enabled)
		: ((status && status.dashboard_auth_ready) ? "未读取" : "需填密码");
	window.adgDashboardHttpPort = String(httpPort || "3000");

	if (shellNode) {
		shellNode.className = "adg-dashboard-shell adg-tone-" + tone;
	}
	if (openButton) {
		openButton.value = "打开 " + window.adgDashboardHttpPort + " 原版完整版";
		openButton.disabled = false;
	}
	if (runNode) {
		runNode.textContent = adgStatusText(running);
	}
	if (protectNode) {
		protectNode.textContent = protectText;
	}
	if (redirectNode) {
		redirectNode.textContent = redirectText;
	}
	if (listenNode) {
		listenNode.textContent = listenText;
	}
	if (portNode) {
		portNode.textContent = "Web " + httpPort + " / DNS " + dnsPort;
	}
	if (coreNode) {
		coreNode.textContent = coreText;
	}
	if (glanceModeNode) {
		glanceModeNode.textContent = redirectText;
	}
	if (glanceAuthNode) {
		glanceAuthNode.textContent = (status && status.dashboard_auth_ready) ? "已填写" : "待填写";
	}
	if (glanceListenNode) {
		glanceListenNode.textContent = "DNS " + dnsPort;
	}
}

function adgApplyDashboardStats(data) {
	var totalNode = document.getElementById("adg-stats-total");
	var blockedNode = document.getElementById("adg-stats-blocked");
	var metaNode = document.getElementById("adg-stats-meta");
	var glanceTotalNode = document.getElementById("adg-glance-total");
	var glanceRatioNode = document.getElementById("adg-glance-ratio");
	var totalPercentNode = document.getElementById("adg-stats-total-percent");
	var blockedPercentNode = document.getElementById("adg-stats-blocked-percent");
	var total;
	var blocked;
	var ratio;
	var ratioText;

	if (data && data.ok === false) {
		var errText = data.error || "未填写仪表盘 API 密码。";
		if (totalNode) {
			totalNode.textContent = "—";
		}
		if (blockedNode) {
			blockedNode.textContent = "—";
		}
		if (totalPercentNode) {
			totalPercentNode.textContent = "—";
		}
		if (blockedPercentNode) {
			blockedPercentNode.textContent = "—";
		}
		if (metaNode) {
			metaNode.textContent = "等待仪表盘认证";
		}
		if (glanceTotalNode) {
			glanceTotalNode.textContent = "待认证";
		}
		if (glanceRatioNode) {
			glanceRatioNode.textContent = "待认证";
		}
		adgSetInlineNote(errText, "warn");
		adgApplyChart("adg-chart-total-line", "adg-chart-total-area", []);
		adgApplyChart("adg-chart-blocked-line", "adg-chart-blocked-area", []);
		return;
	}

	if (!adgHasStatsPayload(data)) {
		if (totalNode) {
			totalNode.textContent = "—";
		}
		if (blockedNode) {
			blockedNode.textContent = "—";
		}
		if (totalPercentNode) {
			totalPercentNode.textContent = "等待";
		}
		if (blockedPercentNode) {
			blockedPercentNode.textContent = "等待";
		}
		if (metaNode) {
			metaNode.textContent = "等待统计数据";
		}
		if (glanceTotalNode) {
			glanceTotalNode.textContent = "等待";
		}
		if (glanceRatioNode) {
			glanceRatioNode.textContent = "等待数据";
		}
		adgSetInlineNote("等待仪表盘统计返回。", "soft");
		adgApplyChart("adg-chart-total-line", "adg-chart-total-area", []);
		adgApplyChart("adg-chart-blocked-line", "adg-chart-blocked-area", []);
		return;
	}

	total = Number(data && data.num_dns_queries || 0);
	blocked = Number(data && data.num_blocked_filtering || 0);
	ratio = total > 0 ? (blocked / total * 100) : 0;
	ratioText = ratio.toFixed(2) + "%";

	if (totalNode) {
		totalNode.textContent = adgFormatNumber(total);
	}
	if (totalPercentNode) {
		totalPercentNode.textContent = ratioText;
	}
	if (blockedNode) {
		blockedNode.textContent = adgFormatNumber(blocked);
	}
	if (blockedPercentNode) {
		blockedPercentNode.textContent = ratioText;
	}
	if (metaNode) {
		metaNode.textContent = "最近 24 小时";
	}
	if (glanceTotalNode) {
		glanceTotalNode.textContent = adgFormatNumber(total);
	}
	if (glanceRatioNode) {
		glanceRatioNode.textContent = "拦截率 " + ratioText;
	}

	adgSetInlineNote("已同步仪表盘统计。", "ok");
	adgApplyChart("adg-chart-total-line", "adg-chart-total-area", data && data.dns_queries ? data.dns_queries : []);
	adgApplyChart("adg-chart-blocked-line", "adg-chart-blocked-area", data && data.blocked_filtering ? data.blocked_filtering : []);
}

function adgApplyPageSkin() {
	var map = document.querySelector(".cbi-map");
	var sections = document.querySelectorAll(".cbi-section");
	var values = document.querySelectorAll(".cbi-value");
	var buttons = document.querySelectorAll("input[type='button'], input[type='submit'], .cbi-button");
	var optionals = document.querySelectorAll(".cbi-optionals");
	var pageActions = document.querySelectorAll(".cbi-page-actions");
	var themedSections = [];
	var field;
	var i;
	var actionOnly;
	var hasCheckbox;
	var hasPassword;
	var hasSelect;
	var hasTextarea;
	var hasDescription;
	var hasButton;
	var hasPlainInput;

	adgAddClass(map, "adg-themed-map");
	adgLocalizeOuterTabs(document);
	adgPolishParentShell();

	for (i = 0; i < sections.length; i++) {
		if (sections[i].id === "AdGuardHome_status_fieldset") {
			continue;
		}
		adgAddClass(sections[i], "adg-themed-section");
		themedSections.push(sections[i]);
	}

	for (i = 0; i < themedSections.length; i++) {
		if (i === 0) {
			adgAddClass(themedSections[i], "adg-section-first");
		}
		if (i === themedSections.length - 1) {
			adgAddClass(themedSections[i], "adg-section-last");
		}
	}

	for (i = 0; i < values.length; i++) {
		field = values[i];
		hasCheckbox = !!field.querySelector(".checkbox, input[type='checkbox']");
		hasPassword = !!field.querySelector("input[type='password']");
		hasSelect = !!field.querySelector("select");
		hasTextarea = !!field.querySelector("textarea");
		hasDescription = !!field.querySelector(".cbi-value-description");
		hasButton = !!field.querySelector("input[type='button'], input[type='submit'], .cbi-button");
		hasPlainInput = !!field.querySelector("input[type='text'], input[type='password']");
		actionOnly = !field.querySelector("input[type='text'], input[type='password'], textarea, select") &&
			hasButton;

		adgAddClass(field, "adg-themed-value");
		if (hasCheckbox) {
			adgAddClass(field, "adg-value-boolean");
		}
		if (hasPassword) {
			adgAddClass(field, "adg-value-password");
		}
		if (hasSelect) {
			adgAddClass(field, "adg-value-select");
		}
		if (hasTextarea) {
			adgAddClass(field, "adg-value-textarea");
		}
		if (hasDescription) {
			adgAddClass(field, "adg-value-described");
		}
		if (hasButton && (hasPlainInput || hasTextarea || hasSelect)) {
			adgAddClass(field, "adg-value-combo");
		}
		if (actionOnly) {
			adgAddClass(field, "adg-value-actions");
		}
	}

	for (i = 0; i < buttons.length; i++) {
		if (buttons[i].value && buttons[i].value.indexOf("AdGuardHome Web:") === 0) {
			adgAddClass(buttons[i], "adg-origin-button");
		}
		if (adgHasClass(buttons[i], "cbi-button-reset") || adgHasClass(buttons[i], "cbi-button-remove") || adgHasClass(buttons[i], "cbi-input-remove")) {
			adgAddClass(buttons[i], "adg-button-muted");
		}
	}

	for (i = 0; i < optionals.length; i++) {
		adgAddClass(optionals[i], "adg-optionals-bar");
	}

	for (i = 0; i < pageActions.length; i++) {
		adgAddClass(pageActions[i], "adg-page-actions");
	}
}

function adgRefreshAll() {
	adgSetRefreshState(true);
	XHR.get('<%=url([[admin]], [[services]], [[AdGuardHome]], [[dashboard_runtime]])%>', { _: Date.now() }, function(x, runtime) {
		XHR.get('<%=url([[admin]], [[services]], [[AdGuardHome]], [[status]])%>', { _: Date.now() }, function(y, status) {
			adgApplyRuntime(runtime || {}, status || {});
			adgApplyPageSkin();
		});
	});
	XHR.get('<%=url([[admin]], [[services]], [[AdGuardHome]], [[dashboard_stats]])%>', { _: Date.now() }, function(x, data) {
		adgSetRefreshState(false);
		adgApplyDashboardStats(data);
		adgApplyPageSkin();
	});
}

XHR.poll(5, '<%=url([[admin]], [[services]], [[AdGuardHome]], [[dashboard_runtime]])%>', null, function(x, runtime) {
	XHR.get('<%=url([[admin]], [[services]], [[AdGuardHome]], [[status]])%>', { _: Date.now() }, function(y, status) {
		adgApplyRuntime(runtime || {}, status || {});
		adgApplyPageSkin();
	});
});

XHR.poll(5, '<%=url([[admin]], [[services]], [[AdGuardHome]], [[dashboard_stats]])%>', null, function(x, data) {
	adgApplyDashboardStats(data);
	adgApplyPageSkin();
});

window.setTimeout(adgApplyPageSkin, 60);
window.setTimeout(adgApplyPageSkin, 260);
window.setTimeout(adgApplyPageSkin, 860);
window.setTimeout(adgApplyPageSkin, 1800);
window.setTimeout(adgPolishParentShell, 2200);
window.setTimeout(adgRefreshAll, 120);
window.setTimeout(adgInstallUpdatePanelGuard, 180);
window.setTimeout(adgInstallUpdatePanelGuard, 680);
window.setTimeout(adgInstallUpdatePanelGuard, 1600);
//]]>
</script>
