	.cbi-map .cbi-value-title::before {
		content: "";
		width: 7px;
		height: 7px;
		margin-right: 10px;
		border-radius: 50%;
		background: linear-gradient(180deg, #62a8ff, #34d3ee);
		box-shadow: 0 0 0 5px rgba(98, 168, 255, 0.08);
		flex: 0 0 auto;
