	.cbi-map .cbi-value-field {
		position: relative;
		z-index: 1;
		display: grid;
		gap: 10px;
		align-items: start;
		float: none !important;
		clear: none !important;
		width: min(100%, 640px) !important;
		flex: 0 1 640px;
		min-width: 0;
