	.cbi-map .adg-value-actions .cbi-value-field .cbi-button,
	.cbi-map .adg-value-actions .cbi-value-field input[type="button"],
	.cbi-map .adg-value-actions .cbi-value-field input[type="submit"] {
		min-width: 220px;
