patch_adguard_enable_hook() {
    base_lua="/usr/lib/lua/luci/model/cbi/AdGuardHome/base.lua"
    [ -f "$base_lua" ] || return 0
    grep -q '/etc/init.d/AdGuardHome enable >/dev/null 2>&1; /etc/init.d/AdGuardHome restart >/dev/null 2>&1 &' "$base_lua" 2>/dev/null && return 0

    backup_file "$base_lua"
    mkdir -p "$WORKDIR/adguardhome"
    tmp_file="$WORKDIR/adguardhome/base.lua"
    awk '
        BEGIN { in_hook = 0 }
        /^function m\.on_commit\(map\)$/ {
            in_hook = 1
            print "function m.on_commit(map)"
            print "\tlocal enabled=uci:get(\"AdGuardHome\",\"AdGuardHome\",\"enabled\")"
            print "\tif enabled==\"1\" then"
            print "\t\tio.popen(\"/etc/init.d/AdGuardHome enable >/dev/null 2>&1; /etc/init.d/AdGuardHome restart >/dev/null 2>&1 &\")"
            print "\telse"
            print "\t\tio.popen(\"/etc/init.d/AdGuardHome disable >/dev/null 2>&1; /etc/init.d/AdGuardHome stop >/dev/null 2>&1 &\")"
            print "\tend"
            next
        }
        in_hook {
            if ($0 ~ /^return m$/) {
                in_hook = 0
                print "end"
                print
            }
            next
        }
        { print }
    ' "$base_lua" > "$tmp_file" && mv "$tmp_file" "$base_lua"
}

get_adguard_configpath() {
    adg_configpath="$(uci -q get AdGuardHome.AdGuardHome.configpath 2>/dev/null || true)"
    [ -n "$adg_configpath" ] || adg_configpath="/etc/AdGuardHome.yaml"
    printf '%s\n' "$adg_configpath"
}

is_adguard_placeholder_config() {
    yaml_file="$1"
    [ -s "$yaml_file" ] || return 1

    grep -q '^bind_host: 0\.0\.0\.0$' "$yaml_file" 2>/dev/null || return 1
    grep -q '^bind_port: ' "$yaml_file" 2>/dev/null || return 1
    grep -q '^#bootstrap_dns$' "$yaml_file" 2>/dev/null || return 1
    grep -q '^#upstream_dns$' "$yaml_file" 2>/dev/null || return 1
    grep -Eq '^- name: (root|admin)$' "$yaml_file" 2>/dev/null || return 1
    return 0
}

cleanup_adguard_placeholder_config() {
    configpath="$(get_adguard_configpath)"
    [ -s "$configpath" ] || return 0
    is_adguard_placeholder_config "$configpath" || return 0

    backup_file "$configpath"
    rm -f "$configpath"
    log "备注:     已移除占位 AdGuardHome 配置，保留首次启动向导"
}

normalize_adguard_yaml_defaults() {
    yaml_file="$1"
    [ -s "$yaml_file" ] || return 0

    adg_defaults_tmp="$WORKDIR/adguard-defaults.$$"
    awk '
        function print_antiad_filter() {
            print "filters:"
            print "  - enabled: true"
            print "    url: https://cdn.jsdelivr.net/gh/privacy-protection-tools/anti-AD/anti-ad-easylist.txt"
            print "    name: anti-AD"
            print "    id: 1577113202"
        }

        BEGIN {
            in_users = 0
            in_filters = 0
            saw_filters = 0
        }

        /^users:[[:space:]]*$/ {
            in_users = 1
            print
            next
        }

        in_users && /^[^[:space:]#-][^:]*:/ {
            in_users = 0
        }

        in_users && /^[[:space:]]*-[[:space:]]*name:[[:space:]]*/ {
            sub(/name:.*/, "name: admin")
            print
            next
        }

        in_users && /^[[:space:]]*name:[[:space:]]*/ {
            sub(/name:.*/, "name: admin")
            print
            next
        }

        /^[[:space:]]*session_ttl:[[:space:]]*/ {
            sub(/session_ttl:[[:space:]].*/, "session_ttl: 720h", $0)
            print
            next
        }

        /^auth_attempts:[[:space:]]*/ {
            print "auth_attempts: 0"
            next
        }

        /^block_auth_min:[[:space:]]*/ {
            print "block_auth_min: 0"
            next
        }

        /^filters:[[:space:]]*$/ {
            print_antiad_filter()
            saw_filters = 1
            in_filters = 1
            next
        }

        in_filters {
            if ($0 ~ /^[^[:space:]#-][^:]*:[[:space:]]*/) {
                in_filters = 0
                print
            }
            next
        }

        { print }

        END {
            if (!saw_filters) {
                print_antiad_filter()
            }
        }
    ' "$yaml_file" > "$adg_defaults_tmp" || {
        rm -f "$adg_defaults_tmp" 2>/dev/null || true
        return 0
    }

    if ! cmp -s "$adg_defaults_tmp" "$yaml_file" 2>/dev/null; then
        backup_file "$yaml_file"
        mv "$adg_defaults_tmp" "$yaml_file" || rm -f "$adg_defaults_tmp" 2>/dev/null || true
    else
        rm -f "$adg_defaults_tmp" 2>/dev/null || true
    fi
}

is_local_port_listening() {
    listen_port="$1"
    case "$listen_port" in
        ''|*[!0-9]*|0)
            return 1
            ;;
    esac

    if command -v netstat >/dev/null 2>&1; then
        if netstat -ln 2>/dev/null | awk -v p="$listen_port" '
            $1 ~ /^(tcp|udp)/ {
                local_addr = $4
                if (local_addr ~ (":" p "$") || local_addr ~ ("\\." p "$"))
                    found = 1
            }
            END { exit found ? 0 : 1 }
        '; then
            return 0
        fi
    fi

    listen_hex="$(printf '%04X' "$listen_port" 2>/dev/null || true)"
    [ -n "$listen_hex" ] || return 1
    for proc_net_table in /proc/net/udp /proc/net/udp6 /proc/net/tcp /proc/net/tcp6; do
        [ -r "$proc_net_table" ] || continue
        case "$proc_net_table" in
            */tcp|*/tcp6) listen_state='0A' ;;
            *) listen_state='' ;;
        esac
        if awk -v p="$listen_hex" -v want_state="$listen_state" '
            NR > 1 {
                split($2, addr, ":")
                if (addr[2] == p && (want_state == "" || $4 == want_state)) {
                    found = 1
                }
            }
            END { exit found ? 0 : 1 }
        ' "$proc_net_table" 2>/dev/null; then
            return 0
        fi
    done

    return 1
}

is_openclash_runtime_present() {
    if pgrep -f '/etc/openclash/|openclash_watchdog|/etc/openclash/core/clash' >/dev/null 2>&1; then
        return 0
    fi
    if [ -x /etc/init.d/openclash ] && /etc/init.d/openclash status 2>/dev/null | grep -qi 'running'; then
        return 0
    fi
    return 1
}

ensure_openclash_dns_upstream_ready() {
    oc_dns_port="${OPENCLASH_DNS_UPSTREAM_PORT:-7874}"
    oc_dns_config_changed='0'
    oc_dns_restore_file="$WORKDIR/openclash-dns.restore.$$"

    command -v uci >/dev/null 2>&1 || return 1
    [ -f /etc/config/openclash ] || return 1

    if [ "$(uci -q get openclash.config.enable_redirect_dns 2>/dev/null || true)" != '0' ]; then
        oc_dns_config_changed='1'
    fi
    if [ "$(uci -q get openclash.config.redirect_dns 2>/dev/null || true)" != '0' ]; then
        oc_dns_config_changed='1'
    fi
    if [ "$(uci -q get openclash.config.dns_port 2>/dev/null || true)" != "$oc_dns_port" ]; then
        oc_dns_config_changed='1'
    fi

    if [ "$oc_dns_config_changed" = '1' ]; then
        mkdir -p "$WORKDIR" >/dev/null 2>&1 || return 1
        cp /etc/config/openclash "$oc_dns_restore_file" >/dev/null 2>&1 || return 1
        if ! uci set openclash.config.enable_redirect_dns='0' >/dev/null 2>&1 || \
           ! uci set openclash.config.redirect_dns='0' >/dev/null 2>&1 || \
           ! uci set "openclash.config.dns_port=$oc_dns_port" >/dev/null 2>&1 || \
           ! uci commit openclash >/dev/null 2>&1 || \
           { [ -x /etc/init.d/openclash ] && ! /etc/init.d/openclash restart >/dev/null 2>&1; }; then
            cp "$oc_dns_restore_file" /etc/config/openclash >/dev/null 2>&1 || true
            /etc/init.d/openclash restart >/dev/null 2>&1 || true
            rm -f "$oc_dns_restore_file" >/dev/null 2>&1 || true
            return 1
        fi
        sleep 2
        adg_dns_chain_changed='1'
    fi

    if ! is_openclash_runtime_present || ! is_local_port_listening "$oc_dns_port"; then
        if [ -s "$oc_dns_restore_file" ]; then
            cp "$oc_dns_restore_file" /etc/config/openclash >/dev/null 2>&1 || true
            /etc/init.d/openclash restart >/dev/null 2>&1 || true
        fi
        rm -f "$oc_dns_restore_file" >/dev/null 2>&1 || true
        return 1
    fi
    rm -f "$oc_dns_restore_file" >/dev/null 2>&1 || true
    return 0
}

ensure_adguard_dns_yaml_file() {
    yaml_file="$1"
    lan_ip="$2"
    dns_port="${3:-${ADGUARDHOME_DNS_PORT:-554}}"
    upstream_dns="${4:-127.0.0.1:${OPENCLASH_DNS_UPSTREAM_PORT:-7874}}"
    [ -f "$yaml_file" ] || return 0

    adg_dns_yaml_tmp="${yaml_file}.nradiodns.$$"
    awk -v lan_ip="$lan_ip" -v dns_port="$dns_port" -v upstream_dns="$upstream_dns" '
        function print_dns_defaults() {
            print "  bind_hosts:"
            print "    - 127.0.0.1"
            print "    - " lan_ip
            print "  port: " dns_port
            print "  upstream_dns:"
            print "    - " upstream_dns
        }
        /^dns:[[:space:]]*$/ {
            print "dns:"
            print_dns_defaults()
            in_dns = 1
            seen_dns = 1
            skip_list = 0
            next
        }
        in_dns && /^[^[:space:]]/ {
            in_dns = 0
            skip_list = 0
        }
        in_dns {
            if (skip_list) {
                if ($0 ~ /^    / || $0 ~ /^  -[[:space:]]/ || $0 ~ /^[[:space:]]*$/ || $0 ~ /^  #[[:space:]]*/) {
                    next
                }
                skip_list = 0
            }
            if ($0 ~ /^  bind_hosts:[[:space:]]*/ || $0 ~ /^  upstream_dns:[[:space:]]*/) {
                skip_list = 1
                next
            }
            if ($0 ~ /^  port:[[:space:]]*/) {
                next
            }
        }
        { print }
        END {
            if (!seen_dns) {
                print ""
                print "dns:"
                print_dns_defaults()
            }
        }
    ' "$yaml_file" > "$adg_dns_yaml_tmp" || {
        rm -f "$adg_dns_yaml_tmp" 2>/dev/null || true
        return 1
    }

    if cmp -s "$adg_dns_yaml_tmp" "$yaml_file" 2>/dev/null; then
        rm -f "$adg_dns_yaml_tmp" 2>/dev/null || true
        return 0
    fi

    backup_file "$yaml_file"
    mv "$adg_dns_yaml_tmp" "$yaml_file" || {
        rm -f "$adg_dns_yaml_tmp" 2>/dev/null || true
        return 1
    }
    adg_dns_chain_changed='1'
}

ensure_adguard_config_from_template_if_ready() {
    template_yaml="$1"
    configpath="$2"
    lan_ip="$3"
    binpath="$4"
    dns_port="${5:-${ADGUARDHOME_DNS_PORT:-554}}"
    upstream_dns="${6:-127.0.0.1:${OPENCLASH_DNS_UPSTREAM_PORT:-7874}}"

    [ -s "$configpath" ] && return 0
    [ -x "$binpath" ] || return 0
    [ -s "$template_yaml" ] || return 0

    config_dir="${configpath%/*}"
    [ "$config_dir" != "$configpath" ] && mkdir -p "$config_dir" >/dev/null 2>&1 || true

    fallback_dns="$(awk -v lan_ip="$lan_ip" '
        /^[^#]*nameserver[[:space:]]+/ {
            server = $2
            if (server != "" && server !~ /^127\./ && server != "0.0.0.0" && server != "::1" && server != lan_ip) {
                print "  - " server
            }
        }
    ' /tmp/resolv.conf.auto 2>/dev/null)"
    if [ -z "$fallback_dns" ]; then
        fallback_dns='  - 223.5.5.5
  - 119.29.29.29'
    fi

    adg_config_tmp="${configpath}.nradiocfg.$$"
    awk -v fallback_dns="$fallback_dns" '
        $0 == "#bootstrap_dns" {
            print fallback_dns
            next
        }
        $0 == "#upstream_dns" {
            print fallback_dns
            next
        }
        { print }
    ' "$template_yaml" > "$adg_config_tmp" || {
        rm -f "$adg_config_tmp" 2>/dev/null || true
        return 0
    }

    if [ -e "$configpath" ]; then
        backup_file "$configpath"
    fi
    mv "$adg_config_tmp" "$configpath" || {
        rm -f "$adg_config_tmp" 2>/dev/null || true
        return 0
    }
    chmod 600 "$configpath" 2>/dev/null || true

    ensure_adguard_dns_yaml_file "$configpath" "$lan_ip" "$dns_port" "$upstream_dns"
    normalize_adguard_yaml_defaults "$configpath"

    if "$binpath" -c "$configpath" --check-config >"$WORKDIR/AdGuardHometest.log" 2>&1; then
        adg_dns_chain_changed='1'
        log "DNS:    已生成 AdGuardHome 配置，准备接入 dnsmasq 上游"
        return 0
    fi

    backup_file "$configpath"
    rm -f "$configpath" 2>/dev/null || true
    log "DNS:    AdGuardHome 配置生成后校验失败，暂不切换 dnsmasq 上游，避免断网"
    return 0
}

restore_dnsmasq_system_dns_when_adguard_unready() {
    adg_dns_fallback_changed='0'
    adg_dns_server_rule="127.0.0.1#${ADGUARDHOME_DNS_PORT:-554}"
    adg_legacy_dns_server_rule="127.0.0.1#${ADGUARDHOME_LEGACY_DNS_PORT:-553}"
    adg_remove_legacy_dns_server_rule='1'
    adg_restore_needed='0'
    adg_primary_rule_present='0'
    adg_legacy_rule_present='0'
    adg_dhcp_restore_file=''
    command -v uci >/dev/null 2>&1 || return 0
    [ -f /etc/config/dhcp ] || return 0

    if [ -f /etc/config/mosdns ]; then
        mosdns_listen_port="$(uci -q get mosdns.main.listen_port 2>/dev/null || true)"
        [ -n "$mosdns_listen_port" ] || mosdns_listen_port="${MOSDNS_PORT:-553}"
        if [ "$mosdns_listen_port" = "${ADGUARDHOME_LEGACY_DNS_PORT:-553}" ]; then
            adg_remove_legacy_dns_server_rule='0'
        fi
    fi

    dhcp_show="$(uci -q get 'dhcp.@dnsmasq[0].server' 2>/dev/null | tr ' ' '\n' || true)"
    if printf '%s\n' "$dhcp_show" | grep -Fx "$adg_dns_server_rule" >/dev/null 2>&1; then
        adg_restore_needed='1'
        adg_primary_rule_present='1'
    fi
    if [ "$adg_remove_legacy_dns_server_rule" = '1' ] && printf '%s\n' "$dhcp_show" | grep -Fx "$adg_legacy_dns_server_rule" >/dev/null 2>&1; then
        adg_restore_needed='1'
        adg_legacy_rule_present='1'
    fi
    [ "$adg_restore_needed" = '1' ] || return 0
    [ -x /etc/init.d/dnsmasq ] || return 1

    backup_file /etc/config/dhcp
    mkdir -p "$WORKDIR" >/dev/null 2>&1 || return 1
    adg_dhcp_restore_file="$WORKDIR/adguard-dhcp.restore.$$"
    cp /etc/config/dhcp "$adg_dhcp_restore_file" >/dev/null 2>&1 || return 1

    if [ "$adg_primary_rule_present" = '1' ]; then
        uci -q del_list "dhcp.@dnsmasq[0].server=$adg_dns_server_rule" >/dev/null 2>&1 || {
            cp "$adg_dhcp_restore_file" /etc/config/dhcp >/dev/null 2>&1 || true
            rm -f "$adg_dhcp_restore_file" >/dev/null 2>&1 || true
            return 1
        }
    fi
    if [ "$adg_legacy_rule_present" = '1' ]; then
        uci -q del_list "dhcp.@dnsmasq[0].server=$adg_legacy_dns_server_rule" >/dev/null 2>&1 || {
            uci -q revert dhcp >/dev/null 2>&1 || true
            cp "$adg_dhcp_restore_file" /etc/config/dhcp >/dev/null 2>&1 || true
            rm -f "$adg_dhcp_restore_file" >/dev/null 2>&1 || true
            return 1
        }
    fi

    if ! uci set "dhcp.@dnsmasq[0].port=53" >/dev/null 2>&1 || \
       ! uci set "dhcp.@dnsmasq[0].noresolv=0" >/dev/null 2>&1 || \
       ! uci commit dhcp >/dev/null 2>&1 || \
       ! /etc/init.d/dnsmasq restart >/dev/null 2>&1; then
        uci -q revert dhcp >/dev/null 2>&1 || true
        cp "$adg_dhcp_restore_file" /etc/config/dhcp >/dev/null 2>&1 || true
        /etc/init.d/dnsmasq restart >/dev/null 2>&1 || true
        rm -f "$adg_dhcp_restore_file" >/dev/null 2>&1 || true
        return 1
    fi

    rm -f "$adg_dhcp_restore_file" >/dev/null 2>&1 || true
    adg_dns_fallback_changed='1'
    return 0
}

restore_adguard_dns_transaction() {
    [ -n "${adg_dns_txn_dir:-}" ] || return 1

    if [ -f "$adg_dns_txn_dir/dhcp.present" ]; then
        cp "$adg_dns_txn_dir/dhcp" /etc/config/dhcp >/dev/null 2>&1 || true
    fi
    if [ -f "$adg_dns_txn_dir/adguard-uci.present" ]; then
        cp "$adg_dns_txn_dir/adguard-uci" /etc/config/AdGuardHome >/dev/null 2>&1 || true
    else
        rm -f /etc/config/AdGuardHome >/dev/null 2>&1 || true
    fi
    if [ -f "$adg_dns_txn_dir/adguard-yaml.present" ]; then
        cp "$adg_dns_txn_dir/adguard-yaml" "$configpath" >/dev/null 2>&1 || true
    else
        rm -f "$configpath" >/dev/null 2>&1 || true
    fi
    if [ -f "$adg_dns_txn_dir/adguard-template.present" ]; then
        cp "$adg_dns_txn_dir/adguard-template" "$template_yaml" >/dev/null 2>&1 || true
    fi
    uci -q revert dhcp >/dev/null 2>&1 || true
    uci -q revert AdGuardHome >/dev/null 2>&1 || true
    /etc/init.d/AdGuardHome restart >/dev/null 2>&1 || true
    /etc/init.d/dnsmasq restart >/dev/null 2>&1 || true
    return 1
}

ensure_adguard_openclash_dns_chain() {
    command -v uci >/dev/null 2>&1 || return 0

    lan_ip="$(uci -q get network.lan.ipaddr 2>/dev/null || true)"
    case "$lan_ip" in
        ''|*[!0-9.]*)
            lan_ip='192.168.66.1'
            ;;
    esac

    adg_dns_chain_changed='0'
    adg_dns_port="${ADGUARDHOME_DNS_PORT:-554}"
    adg_legacy_dns_port="${ADGUARDHOME_LEGACY_DNS_PORT:-553}"
    oc_dns_port="${OPENCLASH_DNS_UPSTREAM_PORT:-7874}"
    adg_dns_server_rule="127.0.0.1#$adg_dns_port"
    adg_legacy_dns_server_rule="127.0.0.1#$adg_legacy_dns_port"
    adg_upstream_dns="127.0.0.1:$oc_dns_port"
    template_yaml="/usr/share/AdGuardHome/AdGuardHome_template.yaml"
    configpath="$(get_adguard_configpath)"
    adg_binpath="$(uci -q get AdGuardHome.AdGuardHome.binpath 2>/dev/null || true)"
    [ -n "$adg_binpath" ] || adg_binpath="/usr/bin/AdGuardHome/AdGuardHome"
    adg_dns_txn_dir="$WORKDIR/adguard-dns-transaction.$$"
    rm -rf "$adg_dns_txn_dir" >/dev/null 2>&1 || return 1
    mkdir -p "$adg_dns_txn_dir" >/dev/null 2>&1 || return 1
    if [ -f /etc/config/dhcp ]; then
        cp /etc/config/dhcp "$adg_dns_txn_dir/dhcp" >/dev/null 2>&1 || return 1
        : > "$adg_dns_txn_dir/dhcp.present"
    fi
    if [ -f /etc/config/AdGuardHome ]; then
        cp /etc/config/AdGuardHome "$adg_dns_txn_dir/adguard-uci" >/dev/null 2>&1 || return 1
        : > "$adg_dns_txn_dir/adguard-uci.present"
    fi
    if [ -f "$configpath" ]; then
        cp "$configpath" "$adg_dns_txn_dir/adguard-yaml" >/dev/null 2>&1 || return 1
        : > "$adg_dns_txn_dir/adguard-yaml.present"
    fi
    if [ -f "$template_yaml" ]; then
        cp "$template_yaml" "$adg_dns_txn_dir/adguard-template" >/dev/null 2>&1 || return 1
        : > "$adg_dns_txn_dir/adguard-template.present"
    fi

    normalize_adguard_yaml_defaults "$template_yaml" || return 1
    normalize_adguard_yaml_defaults "$configpath" || return 1

    if [ ! -x "$adg_binpath" ]; then
        restore_dnsmasq_system_dns_when_adguard_unready || return 1
        if [ "$adg_dns_fallback_changed" = '1' ]; then
            log "DNS:    AdGuardHome 核心未就绪，已恢复 dnsmasq 使用系统上游，避免断网"
        else
            log "DNS:    AdGuardHome 核心未就绪，暂不切换 dnsmasq 上游，避免断网"
        fi
        return 0
    fi

    if ! ensure_openclash_dns_upstream_ready; then
        restore_dnsmasq_system_dns_when_adguard_unready || return 1
        if [ "$adg_dns_fallback_changed" = '1' ]; then
            log "DNS:    未检测到 $OPENCLASH_DISPLAY_NAME:$oc_dns_port 可用监听，已恢复 dnsmasq 使用系统上游，避免断网"
        else
            log "DNS:    未检测到 $OPENCLASH_DISPLAY_NAME:$oc_dns_port 可用监听，暂不切换 dnsmasq 上游，避免断网"
        fi
        return 0
    fi

    ensure_adguard_dns_yaml_file "$template_yaml" "$lan_ip" "$adg_dns_port" "$adg_upstream_dns" || { restore_adguard_dns_transaction; return 1; }
    normalize_adguard_yaml_defaults "$template_yaml" || { restore_adguard_dns_transaction; return 1; }
    ensure_adguard_config_from_template_if_ready "$template_yaml" "$configpath" "$lan_ip" "$adg_binpath" "$adg_dns_port" "$adg_upstream_dns" || { restore_adguard_dns_transaction; return 1; }
    ensure_adguard_dns_yaml_file "$configpath" "$lan_ip" "$adg_dns_port" "$adg_upstream_dns" || { restore_adguard_dns_transaction; return 1; }
    normalize_adguard_yaml_defaults "$configpath" || { restore_adguard_dns_transaction; return 1; }

    if [ ! -s "$configpath" ]; then
        restore_dnsmasq_system_dns_when_adguard_unready || return 1
        if [ "$adg_dns_fallback_changed" = '1' ]; then
            log "DNS:    AdGuardHome 配置未就绪，已恢复 dnsmasq 使用系统上游，避免断网"
        else
            log "DNS:    AdGuardHome 配置未就绪，暂不切换 dnsmasq 上游，避免断网"
        fi
        return 0
    fi

    adg_dns_runtime_changed="$adg_dns_chain_changed"
    adg_dnsmasq_changed='0'
    if [ -f /etc/config/dhcp ]; then
        if [ "$(uci -q get AdGuardHome.AdGuardHome.enabled 2>/dev/null || true)" != '1' ]; then
            adg_dns_chain_changed='1'
            adg_dns_runtime_changed='1'
        fi
        if [ "$(uci -q get AdGuardHome.AdGuardHome.binpath 2>/dev/null || true)" != "$adg_binpath" ]; then
            adg_dns_chain_changed='1'
            adg_dns_runtime_changed='1'
        fi
        if [ "$(uci -q get AdGuardHome.AdGuardHome.configpath 2>/dev/null || true)" != "$configpath" ]; then
            adg_dns_chain_changed='1'
            adg_dns_runtime_changed='1'
        fi
        if [ "$(uci -q get "dhcp.@dnsmasq[0].port" 2>/dev/null || true)" != '53' ]; then
            adg_dns_chain_changed='1'
            adg_dnsmasq_changed='1'
        fi
        if [ "$(uci -q get "dhcp.@dnsmasq[0].localuse" 2>/dev/null || true)" != '1' ]; then
            adg_dns_chain_changed='1'
            adg_dnsmasq_changed='1'
        fi
        if [ "$(uci -q get "dhcp.@dnsmasq[0].noresolv" 2>/dev/null || true)" != '1' ]; then
            adg_dns_chain_changed='1'
            adg_dnsmasq_changed='1'
        fi
        if ! uci -q get 'dhcp.@dnsmasq[0].server' 2>/dev/null | tr ' ' '\n' | grep -Fx "$adg_dns_server_rule" >/dev/null 2>&1; then
            adg_dns_chain_changed='1'
            adg_dnsmasq_changed='1'
        fi
        if uci -q show dhcp 2>/dev/null | awk -F"'" -v keep="$adg_dns_server_rule" -v legacy="$adg_legacy_dns_server_rule" '
            /^dhcp\.@dnsmasq\[0\]\.server=/ {
                for (i = 2; i <= NF; i += 2) {
                    value = $i
                    if (value != "" && value != keep && value != legacy && index(value, "/") != 1) {
                        print value
                        exit
                    }
                }
            }
        ' | grep -q .; then
            adg_dns_chain_changed='1'
            adg_dnsmasq_changed='1'
        fi
        if uci -q get 'dhcp.@dnsmasq[0].server' 2>/dev/null | tr ' ' '\n' | grep -Fx "$adg_legacy_dns_server_rule" >/dev/null 2>&1; then
            adg_dns_chain_changed='1'
            adg_dnsmasq_changed='1'
        fi

        uci -q get AdGuardHome.AdGuardHome >/dev/null 2>&1 || \
            uci -q set AdGuardHome.AdGuardHome=AdGuardHome >/dev/null 2>&1 || { restore_adguard_dns_transaction; return 1; }
        uci set AdGuardHome.AdGuardHome.enabled='1' >/dev/null 2>&1 || { restore_adguard_dns_transaction; return 1; }
        uci set "AdGuardHome.AdGuardHome.binpath=$adg_binpath" >/dev/null 2>&1 || { restore_adguard_dns_transaction; return 1; }
        uci set "AdGuardHome.AdGuardHome.configpath=$configpath" >/dev/null 2>&1 || { restore_adguard_dns_transaction; return 1; }
        uci commit AdGuardHome >/dev/null 2>&1 || { restore_adguard_dns_transaction; return 1; }
        uci set "dhcp.@dnsmasq[0].port=53" >/dev/null 2>&1 || { restore_adguard_dns_transaction; return 1; }
        uci set "dhcp.@dnsmasq[0].localuse=1" >/dev/null 2>&1 || { restore_adguard_dns_transaction; return 1; }
        uci set "dhcp.@dnsmasq[0].noresolv=1" >/dev/null 2>&1 || { restore_adguard_dns_transaction; return 1; }
        stale_dns_server_rules="$(uci -q show dhcp 2>/dev/null | awk -F"'" -v keep="$adg_dns_server_rule" -v legacy="$adg_legacy_dns_server_rule" '
            /^dhcp\.@dnsmasq\[0\]\.server=/ {
                for (i = 2; i <= NF; i += 2) {
                    value = $i
                    if (value != "" && value != keep && value != legacy && index(value, "/") != 1) print value
                }
            }
        ')"
        for dns_server_rule in $stale_dns_server_rules; do
            [ -n "$dns_server_rule" ] || continue
            uci -q del_list "dhcp.@dnsmasq[0].server=$dns_server_rule" >/dev/null 2>&1 || { restore_adguard_dns_transaction; return 1; }
        done
        uci -q del_list "dhcp.@dnsmasq[0].server=$adg_dns_server_rule" >/dev/null 2>&1 || { restore_adguard_dns_transaction; return 1; }
        uci -q del_list "dhcp.@dnsmasq[0].server=$adg_legacy_dns_server_rule" >/dev/null 2>&1 || { restore_adguard_dns_transaction; return 1; }
        uci add_list "dhcp.@dnsmasq[0].server=$adg_dns_server_rule" >/dev/null 2>&1 || { restore_adguard_dns_transaction; return 1; }
        uci commit dhcp >/dev/null 2>&1 || { restore_adguard_dns_transaction; return 1; }
    fi

    if [ "$adg_dns_chain_changed" = '1' ]; then
        if [ "$adg_dns_runtime_changed" = '1' ] || ! is_local_port_listening "$adg_dns_port"; then
            [ -x /etc/init.d/AdGuardHome ] || { restore_adguard_dns_transaction; return 1; }
            /etc/init.d/AdGuardHome restart >/dev/null 2>&1 || { restore_adguard_dns_transaction; return 1; }
            sleep 2
            is_local_port_listening "$adg_dns_port" || { restore_adguard_dns_transaction; return 1; }
        fi
        if [ "$adg_dnsmasq_changed" = '1' ]; then
            [ -x /etc/init.d/dnsmasq ] || { restore_adguard_dns_transaction; return 1; }
            /etc/init.d/dnsmasq restart >/dev/null 2>&1 || { restore_adguard_dns_transaction; return 1; }
            sleep 1
            is_local_port_listening 53 || { restore_adguard_dns_transaction; return 1; }
        fi
        log "DNS:    已写入 dnsmasq:53 -> AdGuardHome:$adg_dns_port -> $OPENCLASH_DISPLAY_NAME:$oc_dns_port"
    else
        log "DNS:    已确认 dnsmasq:53 -> AdGuardHome:$adg_dns_port -> $OPENCLASH_DISPLAY_NAME:$oc_dns_port"
    fi
    log "DNS:    本机与局域网普通查询统一经 AdGuardHome，保留已有域名专用上游"
    rm -rf "$adg_dns_txn_dir" >/dev/null 2>&1 || true
    return 0
}

read_adguard_primary_user_from_config() {
    configpath="$(get_adguard_configpath)"
    [ -s "$configpath" ] || return 1

    awk '
        /^users:[[:space:]]*$/ { in_users=1; next }
        in_users && /^[^[:space:]#-][^:]*:/ { exit }
        in_users {
            if ($0 ~ /^[[:space:]]*-[[:space:]]*name:[[:space:]]*/) {
                sub(/^[[:space:]]*-[[:space:]]*name:[[:space:]]*/, "", $0)
                print
                exit
            }
            if ($0 ~ /^[[:space:]]*name:[[:space:]]*/) {
                sub(/^[[:space:]]*name:[[:space:]]*/, "", $0)
                print
                exit
            }
        }
    ' "$configpath" 2>/dev/null | sed -n '1p'
}

ensure_adguard_dashboard_auth_defaults() {
    dashboard_user="$(uci -q get AdGuardHome.AdGuardHome.dashboard_user 2>/dev/null || true)"
    dashboard_password="$(uci -q get AdGuardHome.AdGuardHome.dashboard_password 2>/dev/null || true)"
    adg_dashboard_changed='0'

    if [ -z "$dashboard_user" ] || [ "$dashboard_user" = 'root' ]; then
        dashboard_user='admin'
        uci set AdGuardHome.AdGuardHome.dashboard_user="$dashboard_user" >/dev/null 2>&1 || true
        adg_dashboard_changed='1'
    fi

    if [ "$adg_dashboard_changed" = '1' ]; then
        uci commit AdGuardHome >/dev/null 2>&1 || true
    fi

    if [ -z "$dashboard_password" ] && { [ -t 0 ] || can_use_ui_tty; }; then
        if confirm_default_yes "是否现在写入 AdGuardHome 原版仪表盘密码供应用商店页读取统计？"; then
            prompt_with_default "Dashboard API user" "$dashboard_user"
            dashboard_user="$PROMPT_RESULT"
            ui_read_secret 'Dashboard API password（与 3000 登录密码一致）: ' || die "input cancelled"
            dashboard_password="$UI_READ_RESULT"

            if [ -n "$dashboard_password" ]; then
                uci set AdGuardHome.AdGuardHome.dashboard_user="$dashboard_user" >/dev/null 2>&1 || true
                uci set AdGuardHome.AdGuardHome.dashboard_password="$dashboard_password" >/dev/null 2>&1 || true
                uci commit AdGuardHome >/dev/null 2>&1 || true
                log "备注:     已写入 AdGuardHome 应用商店页统计认证信息"
                return 0
            fi

            log "备注:     未输入 Dashboard API password，应用商店页将仅显示本地运行态与监听"
        fi
    fi

    if [ -z "$dashboard_password" ]; then
        log "备注:     AdGuardHome 应用商店页已可读取本地运行态与监听；如需同步 3000 原版统计，请在设置页填写 Dashboard API password（与 3000 登录密码一致）"
    fi
}

fix_adguard_runtime_if_possible() {
    binpath="$(uci -q get AdGuardHome.AdGuardHome.binpath 2>/dev/null || true)"
    [ -n "$binpath" ] || binpath="/usr/bin/AdGuardHome/AdGuardHome"
    [ -x "$binpath" ] || return 0

    configpath="$(get_adguard_configpath)"
    workdir="$(uci -q get AdGuardHome.AdGuardHome.workdir 2>/dev/null || true)"
    [ -n "$workdir" ] || workdir="/usr/bin/AdGuardHome"
    template_yaml="/usr/share/AdGuardHome/AdGuardHome_template.yaml"

    ensure_adguard_session_ttl() {
        yaml_file="$1"
        [ -f "$yaml_file" ] || return 0

        if grep -q '^[[:space:]]*session_ttl:[[:space:]]*' "$yaml_file" 2>/dev/null; then
            sed -i 's/^[[:space:]]*session_ttl:[[:space:]].*/session_ttl: 720h/' "$yaml_file"
        elif grep -q '^bind_port:' "$yaml_file" 2>/dev/null; then
            awk '
                {
                    print
                    if (!done && $0 ~ /^bind_port:/) {
                        print "session_ttl: 720h"
                        done = 1
                    }
                }
            ' "$yaml_file" > "$yaml_file.tmp" && mv "$yaml_file.tmp" "$yaml_file"
        fi
    }

    ensure_adguard_session_ttl "$template_yaml"
    mkdir -p "$workdir/data" >/dev/null 2>&1 || true
    [ -s "$configpath" ] || return 0

    ensure_adguard_session_ttl "$configpath"
    [ -s "$configpath" ] && "$binpath" -c "$configpath" --check-config >"$WORKDIR/AdGuardHometest.log" 2>&1 || true
}

get_adguardhome_core_arch() { get_core_arch; }

download_adguardhome_core() {
    optimize_adguardhome_cdn_order
    core_arch="$(get_adguardhome_core_arch 2>/dev/null || true)"
    [ -n "$core_arch" ] || die "无法识别 AdGuardHome 核心架构"

    mkdir -p "$WORKDIR/adguardhome/core" /usr/bin/AdGuardHome
    core_tar="$WORKDIR/adguardhome/AdGuardHome_linux_${core_arch}.tar.gz"
    core_unpack="$WORKDIR/adguardhome/core"
    core_bin="/usr/bin/AdGuardHome/AdGuardHome"

    log "提示: 正在从 CDN 下载 AdGuardHome 核心..."
    download_from_mirrors "AdGuardHome_linux_${core_arch}.tar.gz" "$core_tar" "$ADGUARDHOME_CORE_MIRRORS" || die "无法从全部 CDN 镜像获取 AdGuardHome 核心"
    [ -s "$core_tar" ] || die "AdGuardHome 核心下载失败"

    for existing in "$core_bin"; do
        [ -f "$existing" ] && backup_file "$existing"
    done

    tar -xzf "$core_tar" -C "$core_unpack" >/dev/null 2>&1 || die "AdGuardHome 核心解压失败"

    core_src=""
    for candidate in "$core_unpack"/AdGuardHome "$core_unpack"/*/AdGuardHome "$core_unpack"/*/*/AdGuardHome; do
        [ -f "$candidate" ] || continue
        core_src="$candidate"
        break
    done
    [ -n "$core_src" ] || die "无法定位解压后的 AdGuardHome 核心二进制"

    cp "$core_src" "$core_bin"
    chmod 755 "$core_bin" 2>/dev/null || true
    uci set AdGuardHome.AdGuardHome.coreversion='latest' >/dev/null 2>&1 || true
    uci commit AdGuardHome >/dev/null 2>&1 || true

    log "安装完成"
    log "核心:     AdGuardHome"
    log "版本:  latest"
    log "arch:     $core_arch"
    log "path:     $core_bin"
}

set_init_start_order() {
    init_script="$1"
    start_order="$2"
    init_name="$(basename "$init_script")"
    init_was_enabled='0'

    [ -f "$init_script" ] || return 0
    for init_link in /etc/rc.d/S[0-9][0-9]"$init_name"; do
        [ -L "$init_link" ] && init_was_enabled='1'
    done
    if ! grep -q "^START=$start_order$" "$init_script"; then
        backup_file "$init_script"
        sed -i "s/^START=.*/START=$start_order/" "$init_script" || return 1
        if [ "$init_was_enabled" = '1' ]; then
            enable_init_service_strict "$init_script" "$init_name" || return 1
        fi
    fi
    return 0
}

ensure_plugin_autostart_order() {
    set_init_start_order /etc/init.d/openvpn 90
    set_init_start_order /etc/init.d/openclash 98
    set_init_start_order /etc/init.d/AdGuardHome 120
}

get_swapfile_size_bytes() {
    local swapfile="${1:-/overlay/swapfile}"
    [ -f "$swapfile" ] || {
        printf '0\n'
        return 0
    }
    wc -c < "$swapfile" 2>/dev/null | tr -d ' ' || printf '0\n'
}

get_swapfile_size_mib() {
    local swap_bytes
    swap_bytes="$(get_swapfile_size_bytes "${1:-/overlay/swapfile}")"
    case "$swap_bytes" in
        ''|*[!0-9]*) swap_bytes=0 ;;
    esac
    printf '%s\n' "$(( (swap_bytes + 1048575) / 1048576 ))"
}

swapfile_is_active() {
    local swapfile="${1:-/overlay/swapfile}"
    awk -v dev="$swapfile" 'NR > 1 && $1 == dev { found = 1 } END { exit(found ? 0 : 1) }' /proc/swaps 2>/dev/null
}

list_swap_sections_by_device() {
    local device="${1:-/overlay/swapfile}"
    uci -q show fstab 2>/dev/null | awk -v dev="$device" '
        /^fstab\.@swap\[[0-9]+\]\.device=/ {
            sec = $0
            sub(/^fstab\./, "", sec)
            sub(/\.device=.*/, "", sec)

            value = $0
            sub(/^.*\.device=/, "", value)
            gsub(/\047/, "", value)
            if (value == dev)
                print sec
        }
    '
}

ensure_swapfile_boot_config() {
    local swapfile="${1:-/overlay/swapfile}"
    local sec sections first changed current_device current_enabled current_label

    [ -f "$swapfile" ] || return 1

    first=""
    changed=0
    sections="$(list_swap_sections_by_device "$swapfile" 2>/dev/null || true)"
    first="$(printf '%s\n' "$sections" | awk 'NF { print; exit }')"

    for sec in $(printf '%s\n' "$sections" | awk 'NF { item[++count] = $0 } END { for (i = count; i >= 2; i--) print item[i] }'); do
        [ "$changed" -eq 1 ] || backup_file /etc/config/fstab
        uci -q delete fstab."$sec" >/dev/null 2>&1 || true
        changed=1
    done

    if [ -z "$first" ]; then
        backup_file /etc/config/fstab
        first="$(uci -q add fstab swap 2>/dev/null || true)"
        [ -n "$first" ] || return 1
        changed=1
    fi

    current_device="$(uci -q get fstab."$first".device 2>/dev/null || true)"
    current_enabled="$(uci -q get fstab."$first".enabled 2>/dev/null || true)"
    current_label="$(uci -q get fstab."$first".label 2>/dev/null || true)"
    if [ "$changed" -eq 1 ] || [ "$current_device" != "$swapfile" ] || [ "$current_enabled" != '1' ] || [ "$current_label" != 'swapfile' ]; then
        [ "$changed" -eq 1 ] || backup_file /etc/config/fstab
        uci -q set fstab."$first".device="$swapfile" >/dev/null 2>&1 || true
        uci -q set fstab."$first".enabled='1' >/dev/null 2>&1 || true
        uci -q set fstab."$first".label='swapfile' >/dev/null 2>&1 || true
        uci -q commit fstab >/dev/null 2>&1 || true
    fi

    return 0
}

activate_swapfile_if_needed() {
    local swapfile="${1:-/overlay/swapfile}"

    [ -f "$swapfile" ] || return 1
    swapfile_is_active "$swapfile" && return 0
    command -v swapon >/dev/null 2>&1 || return 1
    swapon "$swapfile" >/dev/null 2>&1
}

create_or_resize_swapfile_mib() {
    local target_mib="${1:-0}"
    local swapfile="${2:-/overlay/swapfile}"
    local target_bytes current_bytes required_bytes tmp_swapfile had_active_swap

    case "$target_mib" in
        ''|*[!0-9]*)
            return 1
            ;;
    esac
    [ "$target_mib" -gt 0 ] 2>/dev/null || return 1

    target_bytes="$((target_mib * 1048576))"
    current_bytes="$(get_swapfile_size_bytes "$swapfile")"
    case "$current_bytes" in
        ''|*[!0-9]*) current_bytes=0 ;;
    esac
    required_bytes="$target_bytes"
    had_active_swap='0'

    ensure_dir_writable /overlay "/overlay"
    ensure_free_space_bytes /overlay "$required_bytes" "/overlay"

    if swapfile_is_active "$swapfile"; then
        command -v swapoff >/dev/null 2>&1 || die "系统缺少 swapoff，无法调整虚拟内存"
        had_active_swap='1'
        swapoff "$swapfile" >/dev/null 2>&1 || die "停用现有虚拟内存失败：$swapfile"
    fi

    command -v mkswap >/dev/null 2>&1 || die "系统缺少 mkswap，无法创建虚拟内存"
    tmp_swapfile="$swapfile.tmp.$$"
    rm -f "$tmp_swapfile" 2>/dev/null || true
    dd if=/dev/zero of="$tmp_swapfile" bs=1M count="$target_mib" >/dev/null 2>&1 || {
        rm -f "$tmp_swapfile" 2>/dev/null || true
        [ "$had_active_swap" = '1' ] && activate_swapfile_if_needed "$swapfile" >/dev/null 2>&1 || true
        die "创建 ${target_mib}M 虚拟内存文件失败"
    }
    chmod 600 "$tmp_swapfile" >/dev/null 2>&1 || true
    mkswap "$tmp_swapfile" >/dev/null 2>&1 || {
        rm -f "$tmp_swapfile" 2>/dev/null || true
        [ "$had_active_swap" = '1' ] && activate_swapfile_if_needed "$swapfile" >/dev/null 2>&1 || true
        die "格式化虚拟内存文件失败"
    }
    mv "$tmp_swapfile" "$swapfile" || {
        rm -f "$tmp_swapfile" 2>/dev/null || true
        [ "$had_active_swap" = '1' ] && activate_swapfile_if_needed "$swapfile" >/dev/null 2>&1 || true
        die "写入虚拟内存文件失败：$swapfile"
    }
    chmod 600 "$swapfile" >/dev/null 2>&1 || true
    sync
}

ensure_existing_swap_access() {
    local plugin_name="${1:-当前插件}"
    local swapfile="/overlay/swapfile"
    local swap_mib

    if [ ! -f "$swapfile" ]; then
        log "备注: 未检测到 /overlay/swapfile，$plugin_name 跳过虚拟内存接入"
        return 0
    fi

    swap_mib="$(get_swapfile_size_mib "$swapfile")"
    log "提示: 正在为 $plugin_name 写入虚拟内存接入配置..."
    ensure_swapfile_boot_config "$swapfile" || die "$plugin_name 写入虚拟内存开机配置失败"
    activate_swapfile_if_needed "$swapfile" || die "$plugin_name 启用虚拟内存失败"
    log "备注: 已接入现有虚拟内存（约 ${swap_mib}M）"
}

manage_swapfile() {
    local swapfile="/overlay/swapfile"
    local current_bytes current_mib target_mib final_mib swap_limit_mib

    c2000_storage_swap_model_supported || die "扩容 swap 虚拟内存仅支持 NRadio_C2000MAX / NRadio_C2000Ultra，当前机型：${CURRENT_DETECTED_MODEL:-unknown}"

    swap_limit_mib=2048

    current_bytes="$(get_swapfile_size_bytes "$swapfile")"
    case "$current_bytes" in
        ''|*[!0-9]*) current_bytes=0 ;;
    esac
    current_mib="$(( (current_bytes + 1048575) / 1048576 ))"

    if [ "$current_bytes" -gt 0 ] 2>/dev/null && [ "$current_mib" -gt "$swap_limit_mib" ] 2>/dev/null; then
        log "备注: 当前虚拟内存约 ${current_mib}M，已超过菜单 1 的 ${swap_limit_mib}M 上限；将保留当前大小，仅重新写入开机接入配置"
        target_mib="$current_mib"
    elif [ "$current_bytes" -gt 0 ] 2>/dev/null; then
        if ! confirm_default_yes "检测到当前虚拟内存约 ${current_mib}M，是否继续修改扩容？"; then
            log "备注: 已取消虚拟内存调整"
            return 0
        fi

        while :; do
            prompt_with_default "请输入要扩容到的虚拟内存大小（单位 MiB）" "$current_mib"
            target_mib="$PROMPT_RESULT"
            case "$target_mib" in
                ''|*[!0-9]*)
                    log "提示: 请输入纯数字，例如 512、1024"
                    continue
                    ;;
                0)
                    log "提示: swap 大小必须大于 0"
                    continue
                    ;;
            esac
            if [ "$target_mib" -gt "$swap_limit_mib" ] 2>/dev/null; then
                log "提示: 菜单 1 最多只允许扩容到 ${swap_limit_mib}M"
                continue
            fi
            if [ "$target_mib" -lt "$current_mib" ] 2>/dev/null; then
                log "提示: 目标大小不能小于当前约 ${current_mib}M"
                continue
            fi
            break
        done
    else
        while :; do
            prompt_with_default "未检测到 /overlay/swapfile，请输入要创建的虚拟内存大小（单位 MiB）" "512"
            target_mib="$PROMPT_RESULT"
            case "$target_mib" in
                ''|*[!0-9]*)
                    log "提示: 请输入纯数字，例如 256、512、1024"
                    continue
                    ;;
                0)
                    log "提示: swap 大小必须大于 0"
                    continue
                    ;;
            esac
            if [ "$target_mib" -gt "$swap_limit_mib" ] 2>/dev/null; then
                log "提示: 菜单 1 最多只允许扩容到 ${swap_limit_mib}M"
                continue
            fi
            break
        done
    fi

    if [ "$current_bytes" -gt 0 ] 2>/dev/null && [ "$target_mib" -eq "$current_mib" ] 2>/dev/null; then
        log "提示: 当前虚拟内存大小未变化，正在重新写入接入配置..."
    else
        log "提示: 正在写入 ${target_mib}M 虚拟内存，文件较大时可能耗时较长，请耐心等待"
        create_or_resize_swapfile_mib "$target_mib" "$swapfile"
    fi

    ensure_swapfile_boot_config "$swapfile" || die "写入虚拟内存开机配置失败"
    activate_swapfile_if_needed "$swapfile" || die "启用虚拟内存失败"
    final_mib="$(get_swapfile_size_mib "$swapfile")"
    log "备注: 虚拟内存已设置（约 ${final_mib}M）"
}

storage_expand_current_model() {
    local model

    model="${CURRENT_DETECTED_MODEL:-}"
    if [ -z "$model" ]; then
        model="$(normalize_nradio_model "$(detect_board_model_raw)" "$(detect_board_name_raw)" "$(detect_board_compatible_raw)" 2>/dev/null || true)"
    fi
    printf '%s\n' "$model"
}

storage_expand_canonical_path() {
    local target_path="$1"

    if command -v readlink >/dev/null 2>&1; then
        readlink -f "$target_path" 2>/dev/null || printf '%s\n' "$target_path"
    else
        printf '%s\n' "$target_path"
    fi
}

storage_expand_find_rootfs_2nd_device() {
    local sysdev partname dev info

    if [ -e /dev/disk/by-partlabel/rootfs_2nd ]; then
        storage_expand_canonical_path /dev/disk/by-partlabel/rootfs_2nd
        return 0
    fi

    for sysdev in /sys/class/block/*; do
        [ -f "$sysdev/uevent" ] || continue
        partname="$(sed -n 's/^PARTNAME=//p' "$sysdev/uevent" 2>/dev/null | sed -n '1p' || true)"
        [ "$partname" = 'rootfs_2nd' ] || continue
        dev="/dev/$(basename "$sysdev")"
        [ -b "$dev" ] || continue
        printf '%s\n' "$dev"
        return 0
    done

    if command -v block >/dev/null 2>&1; then
        for dev in /dev/mmcblk*p* /dev/sd*[0-9]; do
            [ -b "$dev" ] || continue
            info="$(block info "$dev" 2>/dev/null || true)"
            printf '%s\n' "$info" | grep -q 'PARTLABEL="rootfs_2nd"' || continue
            printf '%s\n' "$dev"
            return 0
        done
    fi

    return 1
}

require_rootfs_2nd_storage_capable() {
    local model device

    model="$(storage_expand_current_model)"
    [ -n "$model" ] && CURRENT_DETECTED_MODEL="$model"
    case "$model" in
        NRadio_C5800-650|NRadio_C5800-688|NRadio_C8-688|NRadio_NBCPE)
            ;;
        *)
            die "当前机型不支持 eMMC 存储扩展：${model:-unknown}"
            ;;
    esac
    device="$(storage_expand_find_rootfs_2nd_device 2>/dev/null || true)"
    [ -n "$device" ] || die "未找到 PARTLABEL=rootfs_2nd 分区，当前机型不支持 eMMC 存储扩展：${model:-unknown}"
}

storage_expand_is_booted_from_rootfs_2nd() {
    local device device_name device_id rom_device_id root_spec partuuid device_info

    root_spec="$(tr ' ' '\n' < /proc/cmdline 2>/dev/null | sed -n 's/^root=//p' | sed -n '1p' || true)"
    [ "$root_spec" = 'PARTLABEL=rootfs_2nd' ] && return 0

    device="$(storage_expand_find_rootfs_2nd_device 2>/dev/null || true)"
    [ -n "$device" ] || return 1
    device="$(storage_expand_canonical_path "$device")"
    device_name="${device##*/}"

    case "$root_spec" in
        "$device"|"/dev/$device_name")
            return 0
            ;;
        PARTUUID=*)
            partuuid="${root_spec#PARTUUID=}"
            partuuid="${partuuid%%/*}"
            if [ -e "/dev/disk/by-partuuid/$partuuid" ]; then
                [ "$(storage_expand_canonical_path "/dev/disk/by-partuuid/$partuuid")" = "$device" ] && return 0
            elif command -v blkid >/dev/null 2>&1; then
                device_info="$(blkid "$device" 2>/dev/null || true)"
                case "$device_info" in
                    *"PARTUUID=\"$partuuid\""*) return 0 ;;
                esac
            fi
            ;;
    esac

    device_id="$(cat "/sys/class/block/$device_name/dev" 2>/dev/null || true)"
    rom_device_id="$(awk '$5 == "/rom" { print $3; exit }' /proc/self/mountinfo 2>/dev/null || true)"
    [ -n "$device_id" ] && [ "$device_id" = "$rom_device_id" ]
}

storage_expand_mount_source_for_mountpoint() {
    awk -v mp="$ROOTFS_2ND_STORAGE_MOUNT_POINT" '$2 == mp { print $1; exit }' /proc/mounts 2>/dev/null
}

storage_expand_mount_source_matches_device() {
    local source="$1"
    local device="$2"
    local source_real device_real

    [ -n "$source" ] || return 1
    source_real="$(storage_expand_canonical_path "$source")"
    device_real="$(storage_expand_canonical_path "$device")"
    [ "$source_real" = "$device_real" ]
}

storage_expand_device_mountpoint() {
    local device="$1"
    local device_real source source_real mount_path fs rest

    device_real="$(storage_expand_canonical_path "$device")"
    while read -r source mount_path fs rest; do
        [ -n "$source" ] || continue
        source_real="$(storage_expand_canonical_path "$source")"
        [ "$source_real" = "$device_real" ] || continue
        printf '%s\n' "$mount_path"
        return 0
    done < /proc/mounts

    return 1
}

storage_expand_print_mount_usage() {
    if [ -n "$(storage_expand_mount_source_for_mountpoint 2>/dev/null || true)" ]; then
        df -h "$ROOTFS_2ND_STORAGE_MOUNT_POINT" 2>/dev/null || true
    else
        log "扩展挂载: 未挂载到 $ROOTFS_2ND_STORAGE_MOUNT_POINT"
    fi
}

storage_expand_status() {
    local model device mount_source mount_point boot_state marker_state info

    require_rootfs_2nd_storage_capable
    model="$(storage_expand_current_model)"
    device="$(storage_expand_find_rootfs_2nd_device 2>/dev/null || true)"
    [ -n "$device" ] || die "未找到 PARTLABEL=rootfs_2nd 分区，已停止"

    if storage_expand_is_booted_from_rootfs_2nd; then
        boot_state="当前疑似从第二系统 rootfs_2nd 启动，禁止启用扩展"
    else
        boot_state="当前未从 rootfs_2nd 启动"
    fi

    if [ -f "$ROOTFS_2ND_STORAGE_MARKER" ]; then
        marker_state="已启用标记存在"
    else
        marker_state="未发现启用标记"
    fi

    mount_source="$(storage_expand_mount_source_for_mountpoint 2>/dev/null || true)"
    mount_point="$(storage_expand_device_mountpoint "$device" 2>/dev/null || true)"

    log "机型: $model"
    log "rootfs_2nd 分区: $device"
    log "启动状态: $boot_state"
    log "扩展标记: $marker_state"
    if [ -n "$mount_source" ]; then
        log "扩展挂载点: $ROOTFS_2ND_STORAGE_MOUNT_POINT <- $mount_source"
    elif [ -n "$mount_point" ]; then
        log "rootfs_2nd 当前挂载在: $mount_point"
    else
        log "rootfs_2nd 当前未挂载"
    fi

    info="$(block info "$device" 2>/dev/null || true)"
    [ -n "$info" ] && log "分区信息: $info"

    log "第一系统 overlay:"
    df -h /overlay 2>/dev/null || true
    log "扩展空间:"
    storage_expand_print_mount_usage
    storage_expand_print_migration_list
    storage_expand_print_expand_dependencies || true
}

storage_expand_require_active() {
    local device mount_source

    require_rootfs_2nd_storage_capable
    [ -f "$ROOTFS_2ND_STORAGE_MARKER" ] || die "存储扩展未启用：缺少 $ROOTFS_2ND_STORAGE_MARKER"
    device="$(storage_expand_find_rootfs_2nd_device 2>/dev/null || true)"
    [ -n "$device" ] || die "未找到 PARTLABEL=rootfs_2nd 分区，已停止"
    mount_source="$(storage_expand_mount_source_for_mountpoint 2>/dev/null || true)"
    [ -n "$mount_source" ] || die "扩展盘未挂载到 $ROOTFS_2ND_STORAGE_MOUNT_POINT"
    storage_expand_mount_source_matches_device "$mount_source" "$device" || die "$ROOTFS_2ND_STORAGE_MOUNT_POINT 挂载源不是 rootfs_2nd：$mount_source"
    ensure_dir_writable "$ROOTFS_2ND_STORAGE_MOUNT_POINT" "$ROOTFS_2ND_STORAGE_MOUNT_POINT"
    storage_expand_repair_migrated_runtime_paths || die "修复扩展盘应用运行路径权限失败"
}

