storage_expand_appcenter_field_matches() {
    local section_type="$1"
    local field_name="$2"
    local expected="$3"
    local appcenter_sections sec actual

    [ -n "$expected" ] || return 1
    appcenter_sections="$(uci show appcenter 2>/dev/null | awk -F= -v section_type="$section_type" '$2 == section_type { sub(/^appcenter\./, "", $1); print $1 }' || true)"
    for sec in $appcenter_sections; do
        actual="$(uci -q get "appcenter.$sec.$field_name" 2>/dev/null || true)"
        [ "$actual" = "$expected" ] && return 0
    done
    return 1
}

storage_expand_appcenter_has_installed_app() {
    local app_key="$1"
    local spec label app_name app_pkg app_route

    spec="$(storage_expand_app_spec "$app_key")" || return 1
    label="$(printf '%s\n' "$spec" | awk -F '\t' '{ print $1 }')"
    app_name="$(printf '%s\n' "$spec" | awk -F '\t' '{ print $4 }')"
    app_pkg="$(printf '%s\n' "$spec" | awk -F '\t' '{ print $5 }')"
    app_route="$(printf '%s\n' "$spec" | awk -F '\t' '{ print $6 }')"
    [ -n "$app_name" ] || app_name="$label"

    storage_expand_appcenter_field_matches package name "$app_name" && return 0
    storage_expand_appcenter_field_matches package name "$label" && return 0
    storage_expand_appcenter_field_matches package name "$app_pkg" && return 0
    storage_expand_appcenter_field_matches package_list name "$app_name" && return 0
    storage_expand_appcenter_field_matches package_list name "$label" && return 0
    storage_expand_appcenter_field_matches package_list pkg_name "$app_pkg" && return 0
    storage_expand_appcenter_field_matches package_list parent "$app_name" && return 0
    storage_expand_appcenter_field_matches package_list parent "$label" && return 0
    storage_expand_appcenter_field_matches package_list luci_module_route "$app_route" && return 0
    return 1
}

storage_expand_runtime_has_installed_app() {
    local app_key="$1"
    local src="$2"

    case "$app_key" in
        picoclaw_bin)
            [ -x "$src" ]
            ;;
        picoclaw_launcher)
            [ -x "$src" ]
            ;;
        picoclaw_home)
            [ -d "$src" ] || return 1
            [ -x /usr/bin/picoclaw ] && return 0
            [ -x /usr/bin/picoclaw-launcher ] && return 0
            [ -x /etc/init.d/picoclaw ] && return 0
            command -v opkg >/dev/null 2>&1 || return 1
            opkg status picoclaw 2>/dev/null | grep -q '^Status: .* installed'
            ;;
        openclash_share)
            [ -d "$src" ] || return 1
            [ -x /etc/init.d/openclash ]
            ;;
        zeroclaw_bin)
            [ -x "$src" ]
            ;;
        nradio_skills)
            [ -d "$src" ] || return 1
            command -v opkg >/dev/null 2>&1 || return 1
            opkg status nradio-skills 2>/dev/null | grep -q '^Status: .* installed'
            ;;
        mt5700_bin)
            [ -x "$src" ]
            ;;
        mt5700_web)
            [ -f "$src/index.html" ]
            ;;
        *)
            return 1
            ;;
    esac
}

storage_expand_path_is_migrated() {
    local src="$1"
    local target="$2"
    local src_real target_real

    [ -L "$src" ] || return 1
    src_real="$(storage_expand_canonical_path "$src")"
    target_real="$(storage_expand_canonical_path "$target")"
    [ -n "$src_real" ] && [ "$src_real" = "$target_real" ]
}

storage_expand_key_for_src() {
    local src="$1"
    local app_key spec spec_src

    for app_key in $(storage_expand_app_spec_keys); do
        spec="$(storage_expand_app_spec "$app_key")" || continue
        spec_src="$(printf '%s\n' "$spec" | awk -F '\t' '{ print $3 }')"
        [ "$spec_src" = "$src" ] && {
            printf '%s\n' "$app_key"
            return 0
        }
    done
    return 1
}

storage_expand_migration_record_matches() {
    local src="$1"
    local target="$2"

    [ -f "$ROOTFS_2ND_STORAGE_MIGRATE_LIST" ] || return 1
    awk -F '\t' -v src="$src" -v target="$target" '
        $3 == src && $4 == target { found = 1 }
        END { exit(found ? 0 : 1) }
    ' "$ROOTFS_2ND_STORAGE_MIGRATE_LIST" 2>/dev/null
}

storage_expand_path_needs_relink() {
    local src="$1"
    local target="$2"

    [ -e "$src" ] || return 1
    [ ! -L "$src" ] || return 1
    [ -e "$target" ] || return 1
    [ ! -L "$target" ] || return 1
    storage_expand_migration_record_matches "$src" "$target" || return 1
    storage_expand_path_depends_on_target "$src" "$target" && return 1
    storage_expand_path_has_self_loop_child_links "$src" && return 1
    storage_expand_path_has_self_loop_child_links "$target" && return 1
    storage_expand_relink_tree_links_are_safe "$src" "$target" '1' || return 1
    storage_expand_relink_tree_links_are_safe "$target" "$target" '0' || return 1
    if [ -d "$src" ]; then
        [ -d "$target" ] || return 1
    else
        [ -f "$src" ] || return 1
        [ -f "$target" ] || return 1
    fi
    return 0
}

storage_expand_build_migrate_menu_list() {
    local list_file="$1"
    local app_key spec label src target

    : > "$list_file"
    for app_key in $(storage_expand_app_spec_keys); do
        spec="$(storage_expand_app_spec "$app_key")" || continue
        label="$(printf '%s\n' "$spec" | awk -F '\t' '{ print $1 }')"
        src="$(printf '%s\n' "$spec" | awk -F '\t' '{ print $3 }')"
        target="$(storage_expand_target_for_path "$src")"

        if ! storage_expand_appcenter_has_installed_app "$app_key" &&
           ! storage_expand_runtime_has_installed_app "$app_key" "$src"; then
            storage_expand_path_needs_relink "$src" "$target" || continue
        fi
        [ -e "$src" ] || continue
        storage_expand_path_is_migrated "$src" "$target" && continue
        storage_expand_path_has_self_loop_child_links "$src" && continue
        if storage_expand_path_has_child_links_to_target "$src" "$target"; then
            [ -e "$target" ] || [ -L "$target" ] || continue
            storage_expand_path_has_self_loop_child_links "$target" && continue
            printf '%s\t%s\t%s\n' "$app_key" "$label" "$src" >> "$list_file"
            continue
        fi
        storage_expand_path_depends_on_target "$src" "$target" && continue
        if [ -e "$target" ] || [ -L "$target" ]; then
            if storage_expand_path_needs_relink "$src" "$target"; then
                printf '%s\t%s\t%s\n' "$app_key" "$label（升级后重新接入）" "$src" >> "$list_file"
            fi
            continue
        fi
        printf '%s\t%s\t%s\n' "$app_key" "$label" "$src" >> "$list_file"
    done
}

storage_expand_build_restore_menu_list() {
    local list_file="$1"
    local label service src target kind migrated_at app_key spec

    : > "$list_file"
    if [ -f "$ROOTFS_2ND_STORAGE_MIGRATE_LIST" ]; then
        while IFS="$(printf '\t')" read -r label service src target kind migrated_at; do
            [ -n "$src" ] || continue
            [ -e "$target" ] || [ -L "$target" ] || continue
            app_key="$(storage_expand_key_for_src "$src" 2>/dev/null || true)"
            [ -n "$app_key" ] || continue
            printf '%s\t%s\t%s\n' "$app_key" "$label" "$src" >> "$list_file"
        done < "$ROOTFS_2ND_STORAGE_MIGRATE_LIST"
    fi

    for app_key in $(storage_expand_app_spec_keys); do
        spec="$(storage_expand_app_spec "$app_key")" || continue
        label="$(printf '%s\n' "$spec" | awk -F '\t' '{ print $1 }')"
        src="$(printf '%s\n' "$spec" | awk -F '\t' '{ print $3 }')"
        target="$(storage_expand_target_for_path "$src")"
        [ -e "$target" ] || [ -L "$target" ] || continue
        storage_expand_path_depends_on_target "$src" "$target" || continue
        awk -F '\t' -v app_key="$app_key" '$1 == app_key { found = 1 } END { exit(found ? 0 : 1) }' "$list_file" 2>/dev/null && continue
        printf '%s\t%s\t%s\n' "$app_key" "$label" "$src" >> "$list_file"
    done
}

storage_expand_run_app_action() {
    local action_name="$1"
    local app_key="$2"

    if [ "$action_name" = "迁移应用到扩展盘" ]; then
        storage_expand_migrate_one_app "$app_key"
    else
        storage_expand_restore_one_app "$app_key"
    fi
}

storage_expand_target_for_path() {
    local src="$1"
    printf '%s%s\n' "$ROOTFS_2ND_STORAGE_APPS_DIR" "$src"
}

storage_expand_make_searchable_storage_path() {
    local target_path="$1"
    local rel old_ifs part current_path

    [ -n "$target_path" ] || return 0
    case "$target_path" in
        "$ROOTFS_2ND_STORAGE_APPS_DIR"|"$ROOTFS_2ND_STORAGE_APPS_DIR"/*)
            ;;
        *)
            return 0
            ;;
    esac

    chmod 755 "$ROOTFS_2ND_STORAGE_MOUNT_POINT" 2>/dev/null || true
    chmod 755 "$ROOTFS_2ND_STORAGE_APPS_DIR" 2>/dev/null || true

    rel="${target_path#$ROOTFS_2ND_STORAGE_APPS_DIR/}"
    [ "$rel" != "$target_path" ] || return 0

    current_path="$ROOTFS_2ND_STORAGE_APPS_DIR"
    old_ifs="$IFS"
    IFS='/'
    for part in $rel; do
        [ -n "$part" ] || continue
        current_path="$current_path/$part"
        [ -d "$current_path" ] && chmod 755 "$current_path" 2>/dev/null || true
    done
    IFS="$old_ifs"
}

storage_expand_prepare_apps_tree() {
    local mount_real apps_real

    case "$ROOTFS_2ND_STORAGE_APPS_DIR" in
        "$ROOTFS_2ND_STORAGE_MOUNT_POINT"/*) ;;
        *)
            log "ERROR: 扩展应用目录越界：$ROOTFS_2ND_STORAGE_APPS_DIR"
            return 1
            ;;
    esac
    mkdir -p "$ROOTFS_2ND_STORAGE_MOUNT_POINT" "$ROOTFS_2ND_STORAGE_APPS_DIR" || return 1
    mount_real="$(readlink -f "$ROOTFS_2ND_STORAGE_MOUNT_POINT" 2>/dev/null || true)"
    apps_real="$(readlink -f "$ROOTFS_2ND_STORAGE_APPS_DIR" 2>/dev/null || true)"
    [ -n "$mount_real" ] && [ -n "$apps_real" ] || return 1
    case "$apps_real" in
        "$mount_real"/*) ;;
        *)
            log "ERROR: 扩展应用目录解析后越界：$apps_real"
            return 1
            ;;
    esac
    storage_expand_make_searchable_storage_path "$ROOTFS_2ND_STORAGE_APPS_DIR"
}

storage_expand_prepare_target_parent() {
    local target_path="$1"
    local target_parent

    target_parent="$(dirname "$target_path")"
    mkdir -p "$target_parent" || return 1
    storage_expand_make_searchable_storage_path "$target_parent"
}

storage_expand_repair_migrated_runtime_paths() {
    local label service src target kind migrated_at

    storage_expand_prepare_apps_tree || return 1
    [ -f "$ROOTFS_2ND_STORAGE_MIGRATE_LIST" ] || return 0
    while IFS="$(printf '\t')" read -r label service src target kind migrated_at; do
        [ -n "$target" ] || continue
        storage_expand_prepare_target_parent "$target" || return 1
    done < "$ROOTFS_2ND_STORAGE_MIGRATE_LIST"
}

storage_expand_path_size_bytes() {
    local target_path="$1"
    local size_kib

    [ -e "$target_path" ] || {
        printf '0\n'
        return 0
    }
    size_kib="$(du -sk "$target_path" 2>/dev/null | awk 'NR == 1 { print $1 }' || true)"
    case "$size_kib" in
        ''|*[!0-9]*)
            printf '0\n'
            ;;
        *)
            printf '%s\n' "$((size_kib * 1024))"
            ;;
    esac
}

storage_expand_restore_size_bytes() {
    local app_key="$1"
    local target_path="$2"

    storage_expand_path_size_bytes "$target_path"
}

storage_expand_allow_child_link_restore() {
    case "$1" in
        openclash|adguardhome)
            return 0
            ;;
    esac
    return 1
}

storage_expand_copy_restore_payload() {
    local app_key="$1"
    local target_path="$2"
    local tmp_restore="$3"
    local item name dest_item runtime_item

    if [ ! -d "$target_path" ]; then
        cp -a "$target_path" "$tmp_restore"
        return $?
    fi

    mkdir -p "$tmp_restore" || return 1
    for item in "$target_path"/* "$target_path"/.[!.]* "$target_path"/..?*; do
        [ -e "$item" ] || [ -L "$item" ] || continue
        name="$(basename "$item")"
        dest_item="$tmp_restore/$name"
        if storage_expand_link_points_to_self "$item"; then
            log "失败项: $name 是自指软链接"
            return 1
        fi
        cp -a "$item" "$tmp_restore/" || {
            if storage_expand_allow_child_link_restore "$app_key"; then
                rm -rf "$dest_item" 2>/dev/null || true
                ln -s "$item" "$dest_item" || {
                    log "失败项: $name"
                    return 1
                }
                log "链接: 大项 $name -> $item"
                continue
            fi
            log "失败项: $name"
            return 1
        }
    done

    if [ "$app_key" = 'openclash' ]; then
        [ -e "$tmp_restore/ASN.mmdb" ] || {
            log "失败项: ASN.mmdb 未成功还原"
            return 1
        }
        for runtime_item in GeoIP.dat core; do
            if [ -e "$target_path/$runtime_item" ] && [ ! -e "$tmp_restore/$runtime_item" ]; then
                log "失败项: $runtime_item 未成功还原"
                return 1
            fi
        done
    fi

    return 0
}

storage_expand_restore_overlay_space_after_failure() {
    local src="$1"
    local target="$2"

    log "失败后 /overlay 空间:"
    df -h /overlay 2>/dev/null || true
    log "扩展盘目标大小:"
    du -sh "$target" 2>/dev/null || true
    log "临时还原目录大小:"
    du -sh "$src.restore.$$" 2>/dev/null || true
}

storage_expand_restore_failure_hint() {
    local label="$1"
    local src="$2"
    local target="$3"

    storage_expand_restore_overlay_space_after_failure "$src" "$target"
    log "$label 从扩展盘复制回 overlay 失败"
    return 1
}

storage_expand_try_full_restore_copy() {
    local app_key="$1"
    local target="$2"
    local tmp_restore="$3"

    storage_expand_copy_restore_payload "$app_key" "$target" "$tmp_restore" && return 0
    return 1
}

storage_expand_restore_copy_or_fail() {
    local app_key="$1"
    local label="$2"
    local src="$3"
    local target="$4"
    local tmp_restore="$5"

    if storage_expand_try_full_restore_copy "$app_key" "$target" "$tmp_restore"; then
        return 0
    fi
    rm -rf "$tmp_restore" 2>/dev/null || true
    ln -s "$target" "$src" 2>/dev/null || die "$label 复制失败且自动恢复扩展盘软链接未完成：$src"
    storage_expand_restore_failure_hint "$label" "$src" "$target"
    return 1
}

storage_expand_restore_hybrid_payload() {
    local app_key="$1"
    local source_path="$2"
    local target_path="$3"
    local item name dest_item tmp_item

    [ -d "$source_path" ] || return 1
    for item in "$target_path"/* "$target_path"/.[!.]* "$target_path"/..?*; do
        [ -e "$item" ] || [ -L "$item" ] || continue
        name="$(basename "$item")"
        dest_item="$source_path/$name"
        if storage_expand_link_points_to_self "$item"; then
            log "失败项: $name 是扩展盘自指软链接"
            return 1
        fi
        if storage_expand_link_points_to_self "$dest_item"; then
            log "失败项: $name 原路径是自指软链接"
            return 1
        fi

        if storage_expand_link_points_under "$dest_item" "$target_path"; then
            tmp_item="$source_path/.restore-$name.$$"
            rm -rf "$tmp_item" 2>/dev/null || true
            if cp -a "$item" "$tmp_item"; then
                rm -f "$dest_item" || {
                    rm -rf "$tmp_item" 2>/dev/null || true
                    log "失败项: $name"
                    return 1
                }
                mv "$tmp_item" "$dest_item" || {
                    rm -rf "$tmp_item" 2>/dev/null || true
                    log "失败项: $name"
                    return 1
                }
                log "写回: $name"
            else
                rm -rf "$tmp_item" 2>/dev/null || true
                log "保留链接: $name -> $item"
            fi
            continue
        fi

        if [ -e "$dest_item" ] || [ -L "$dest_item" ]; then
            continue
        fi
        cp -a "$item" "$source_path/" || {
            if storage_expand_allow_child_link_restore "$app_key"; then
                rm -rf "$dest_item" 2>/dev/null || true
                ln -s "$item" "$dest_item" || {
                    log "失败项: $name"
                    return 1
                }
                log "链接: 大项 $name -> $item"
                continue
            fi
            log "失败项: $name"
            return 1
        }
    done
    return 0
}

storage_expand_sync_hybrid_to_target() {
    local source_path="$1"
    local target_path="$2"
    local item name dest_item tmp_item

    [ -d "$source_path" ] || return 1
    [ -d "$target_path" ] || return 1
    for item in "$source_path"/* "$source_path"/.[!.]* "$source_path"/..?*; do
        [ -e "$item" ] || [ -L "$item" ] || continue
        name="$(basename "$item")"
        dest_item="$target_path/$name"
        if storage_expand_link_points_to_self "$item"; then
            log "失败项: $name 是自指软链接"
            return 1
        fi
        storage_expand_link_points_under "$item" "$target_path" && continue
        tmp_item="$target_path/.migrate-$name.$$"
        rm -rf "$tmp_item" 2>/dev/null || true
        cp -a "$item" "$tmp_item" || {
            rm -rf "$tmp_item" 2>/dev/null || true
            log "失败项: $name"
            return 1
        }
        rm -rf "$dest_item" || {
            rm -rf "$tmp_item" 2>/dev/null || true
            log "失败项: $name"
            return 1
        }
        mv "$tmp_item" "$dest_item" || {
            rm -rf "$tmp_item" 2>/dev/null || true
            log "失败项: $name"
            return 1
        }
    done
    return 0
}

storage_expand_link_points_under() {
    local link_path="$1"
    local target_path="$2"
    local raw_link link_real target_real

    [ -L "$link_path" ] || return 1
    raw_link="$(readlink "$link_path" 2>/dev/null || true)"
    case "$raw_link" in
        "$target_path"|"$target_path"/*)
            return 0
            ;;
    esac

    link_real="$(storage_expand_canonical_path "$link_path" 2>/dev/null || true)"
    target_real="$(storage_expand_canonical_path "$target_path" 2>/dev/null || true)"
    [ -n "$link_real" ] && [ -n "$target_real" ] || return 1
    case "$link_real" in
        "$target_real"|"$target_real"/*)
            return 0
            ;;
    esac
    return 1
}

storage_expand_link_points_to_self() {
    local link_path="$1"
    local raw_link link_name

    [ -L "$link_path" ] || return 1
    raw_link="$(readlink "$link_path" 2>/dev/null || true)"
    [ -n "$raw_link" ] || return 1
    [ "$raw_link" = "$link_path" ] && return 0
    case "$raw_link" in
        /*)
            return 1
            ;;
    esac
    link_name="$(basename "$link_path")"
    [ "$raw_link" = "$link_name" ] && return 0
    [ "$raw_link" = "./$link_name" ] && return 0
    return 1
}

storage_expand_path_has_self_loop_child_links() {
    local source_path="$1"
    local item

    [ -d "$source_path" ] || return 1
    for item in "$source_path"/* "$source_path"/.[!.]* "$source_path"/..?*; do
        [ -L "$item" ] || continue
        storage_expand_link_points_to_self "$item" && return 0
    done
    return 1
}

storage_expand_path_has_child_links_to_target() {
    local source_path="$1"
    local target_path="$2"
    local item

    [ -d "$source_path" ] || return 1
    for item in "$source_path"/* "$source_path"/.[!.]* "$source_path"/..?*; do
        [ -e "$item" ] || [ -L "$item" ] || continue
        storage_expand_link_points_under "$item" "$target_path" && return 0
    done
    return 1
}

storage_expand_path_depends_on_target() {
    local source_path="$1"
    local target_path="$2"

    storage_expand_link_points_under "$source_path" "$target_path" && return 0
    storage_expand_path_has_child_links_to_target "$source_path" "$target_path" && return 0
    return 1
}

storage_expand_relink_tree_links_are_safe() {
    local tree_path="$1"
    local target_path="$2"
    local reject_target_links="$3"
    local link_list link_path

    [ -d "$tree_path" ] || return 0
    link_list="$(find "$tree_path" -type l -print 2>/dev/null)" || return 1
    while IFS= read -r link_path; do
        [ -n "$link_path" ] || continue
        storage_expand_link_points_to_self "$link_path" && return 1
        if [ "$reject_target_links" = '1' ] && storage_expand_link_points_under "$link_path" "$target_path"; then
            return 1
        fi
    done <<EOF_STORAGE_EXPAND_RELINK_LINKS
$link_list
EOF_STORAGE_EXPAND_RELINK_LINKS
    return 0
}

storage_expand_openclash_has_expand_dependency() {
    storage_expand_path_depends_on_target "/etc/openclash" "$ROOTFS_2ND_STORAGE_APPS_DIR/etc/openclash"
}

storage_expand_has_expand_dependency() {
    local app_key spec src target

    for app_key in $(storage_expand_app_spec_keys); do
        spec="$(storage_expand_app_spec "$app_key")" || continue
        src="$(printf '%s\n' "$spec" | awk -F '\t' '{ print $3 }')"
        target="$(storage_expand_target_for_path "$src")"
        storage_expand_path_depends_on_target "$src" "$target" && return 0
    done
    return 1
}

storage_expand_print_expand_dependencies() {
    local app_key spec label src target printed

    printed=0
    for app_key in $(storage_expand_app_spec_keys); do
        spec="$(storage_expand_app_spec "$app_key")" || continue
        label="$(printf '%s\n' "$spec" | awk -F '\t' '{ print $1 }')"
        src="$(printf '%s\n' "$spec" | awk -F '\t' '{ print $3 }')"
        target="$(storage_expand_target_for_path "$src")"
        storage_expand_path_depends_on_target "$src" "$target" || continue
        [ "$printed" = '1' ] || {
            log "扩展依赖:"
            printed=1
        }
        log "  - $label: $src -> $target"
    done
    [ "$printed" = '1' ]
}

storage_expand_remove_rootfs_2nd_orphan_links() {
    local app_key spec label src target item

    for app_key in $(storage_expand_app_spec_keys); do
        spec="$(storage_expand_app_spec "$app_key")" || continue
        label="$(printf '%s\n' "$spec" | awk -F '\t' '{ print $1 }')"
        src="$(printf '%s\n' "$spec" | awk -F '\t' '{ print $3 }')"
        target="$(storage_expand_target_for_path "$src")"
        if [ -L "$src" ]; then
            storage_expand_link_points_under "$src" "$target" || continue
            rm -f "$src" || die "$label 恢复出厂残留软链接清理失败：$src"
            log "清理: $label 恢复出厂残留软链接 $src"
            continue
        fi
        [ -d "$src" ] || continue
        for item in "$src"/* "$src"/.[!.]* "$src"/..?*; do
            [ -L "$item" ] || continue
            storage_expand_link_points_under "$item" "$target" || continue
            rm -f "$item" || die "$label 恢复出厂残留子项软链接清理失败：$item"
            log "清理: $label 恢复出厂残留子项软链接 $item"
        done
    done
}

storage_expand_qiyou_service_is_running() {
    local qiyou_state

    [ -x "$QIYOU_DIR/qy_acc.sh" ] || return 1
    qiyou_state="$("$QIYOU_DIR/qy_acc.sh" status 2>/dev/null || true)"
    case "$qiyou_state" in
        RUNNING|BOOSTING|INSTALLING|DOWNLOADING)
            return 0
            ;;
    esac
    return 1
}

storage_expand_service_is_running() {
    local service_name="$1"

    [ -n "$service_name" ] || return 1
    if [ "$service_name" = "$QIYOU_SERVICE_NAME" ]; then
        storage_expand_qiyou_service_is_running
        return $?
    fi
    [ -x "/etc/init.d/$service_name" ] || return 1
    "/etc/init.d/$service_name" status >/dev/null 2>&1
}

storage_expand_stop_service() {
    local service_name="$1"
    local wait_count

    STORAGE_EXPAND_SERVICE_WAS_RUNNING=0
    [ -n "$service_name" ] || return 0
    [ -x "/etc/init.d/$service_name" ] || return 0
    if ! storage_expand_service_is_running "$service_name"; then
        return 0
    fi

    STORAGE_EXPAND_SERVICE_WAS_RUNNING=1
    "/etc/init.d/$service_name" stop >/dev/null 2>&1 || true
    wait_count=0
    while storage_expand_service_is_running "$service_name"; do
        wait_count=$((wait_count + 1))
        [ "$wait_count" -lt 8 ] || return 1
        sleep 1
    done
    return 0
}

storage_expand_start_service() {
    local service_name="$1"
    local wait_count

    [ "${STORAGE_EXPAND_SERVICE_WAS_RUNNING:-0}" = '1' ] || return 0
    [ -n "$service_name" ] || return 1
    [ -x "/etc/init.d/$service_name" ] || return 1
    "/etc/init.d/$service_name" start >/dev/null 2>&1 || true
    wait_count=0
    until storage_expand_service_is_running "$service_name"; do
        wait_count=$((wait_count + 1))
        [ "$wait_count" -lt 15 ] || return 1
        sleep 1
    done
    return 0
}

storage_expand_relink_service_is_running() {
    local app_key="$1"
    local service_name="$2"

    [ -n "$app_key" ] || return 1
    [ -n "$service_name" ] || return 1
    if [ "$app_key" = 'qiyou' ] && [ "$service_name" = "$QIYOU_SERVICE_NAME" ]; then
        storage_expand_qiyou_service_is_running
        return $?
    fi
    [ -x "/etc/init.d/$service_name" ] || return 1
    "/etc/init.d/$service_name" status >/dev/null 2>&1
}

storage_expand_stop_service_for_relink() {
    local app_key="$1"
    local service_name="$2"
    local wait_count

    STORAGE_EXPAND_RELINK_SERVICE_WAS_RUNNING=0
    [ -n "$service_name" ] || return 0
    [ -x "/etc/init.d/$service_name" ] || return 0
    if storage_expand_relink_service_is_running "$app_key" "$service_name"; then
        STORAGE_EXPAND_RELINK_SERVICE_WAS_RUNNING=1
    fi
    "/etc/init.d/$service_name" stop >/dev/null 2>&1 || true
    wait_count=0
    while storage_expand_relink_service_is_running "$app_key" "$service_name"; do
        wait_count=$((wait_count + 1))
        [ "$wait_count" -lt 8 ] || return 1
        sleep 1
    done
    return 0
}

storage_expand_start_service_for_relink() {
    local app_key="$1"
    local service_name="$2"
    local wait_count

    [ "${STORAGE_EXPAND_RELINK_SERVICE_WAS_RUNNING:-0}" = '1' ] || return 0
    [ -n "$service_name" ] || return 1
    [ -x "/etc/init.d/$service_name" ] || return 1
    "/etc/init.d/$service_name" start >/dev/null 2>&1 || true
    wait_count=0
    until storage_expand_relink_service_is_running "$app_key" "$service_name"; do
        wait_count=$((wait_count + 1))
        [ "$wait_count" -lt 15 ] || return 1
        sleep 1
    done
    return 0
}

storage_expand_resume_service_after_relink_failure() {
    local app_key="$1"
    local service_name="$2"

    storage_expand_start_service_for_relink "$app_key" "$service_name" || log "警告: 重新接入失败后未能恢复服务状态：$service_name"
}

storage_expand_payload_fingerprint() {
    local payload_path="$1"
    local fingerprint
    local manifest_base manifest_file dirs_file dirs_sorted files_file files_sorted links_file links_sorted special_file

    command -v sha256sum >/dev/null 2>&1 || return 1
    if [ -f "$payload_path" ]; then
        fingerprint="$(sha256sum "$payload_path" 2>/dev/null | awk 'NR == 1 { print $1 }')"
    elif [ -d "$payload_path" ]; then
        manifest_base="/tmp/.nradio-storage-fingerprint.$$"
        manifest_file="$manifest_base.manifest"
        dirs_file="$manifest_base.dirs"
        dirs_sorted="$manifest_base.dirs.sorted"
        files_file="$manifest_base.files"
        files_sorted="$manifest_base.files.sorted"
        links_file="$manifest_base.links"
        links_sorted="$manifest_base.links.sorted"
        special_file="$manifest_base.special"
        rm -f "$manifest_file" "$dirs_file" "$dirs_sorted" "$files_file" "$files_sorted" "$links_file" "$links_sorted" "$special_file" 2>/dev/null || return 1
        if ! (
            local item item_hash link_target
            cd "$payload_path" 2>/dev/null || exit 1
            find . -type d -print > "$dirs_file" 2>/dev/null || exit 1
            find . -type f -print > "$files_file" 2>/dev/null || exit 1
            find . -type l -print > "$links_file" 2>/dev/null || exit 1
            find . ! -type d ! -type f ! -type l -print > "$special_file" 2>/dev/null || exit 1
            [ ! -s "$special_file" ] || exit 1
            LC_ALL=C sort "$dirs_file" > "$dirs_sorted" || exit 1
            LC_ALL=C sort "$files_file" > "$files_sorted" || exit 1
            LC_ALL=C sort "$links_file" > "$links_sorted" || exit 1
            : > "$manifest_file" || exit 1
            while IFS= read -r item; do
                [ -n "$item" ] || continue
                printf 'D\t%s\n' "$item" >> "$manifest_file" || exit 1
            done < "$dirs_sorted"
            while IFS= read -r item; do
                [ -n "$item" ] || continue
                item_hash="$(sha256sum "$item" 2>/dev/null | awk 'NR == 1 { print $1 }')"
                case "$item_hash" in
                    ''|*[!0-9a-f]*) exit 1 ;;
                esac
                [ "${#item_hash}" -eq 64 ] 2>/dev/null || exit 1
                printf 'F\t%s\t%s\n' "$item" "$item_hash" >> "$manifest_file" || exit 1
            done < "$files_sorted"
            while IFS= read -r item; do
                [ -n "$item" ] || continue
                link_target="$(readlink "$item" 2>/dev/null)" || exit 1
                [ -n "$link_target" ] || exit 1
                printf 'L\t%s\t%s\n' "$item" "$link_target" >> "$manifest_file" || exit 1
            done < "$links_sorted"
        ); then
            rm -f "$manifest_file" "$dirs_file" "$dirs_sorted" "$files_file" "$files_sorted" "$links_file" "$links_sorted" "$special_file" 2>/dev/null || true
            return 1
        fi
        fingerprint="$(sha256sum "$manifest_file" 2>/dev/null | awk 'NR == 1 { print $1 }')"
        rm -f "$manifest_file" "$dirs_file" "$dirs_sorted" "$files_file" "$files_sorted" "$links_file" "$links_sorted" "$special_file" 2>/dev/null || return 1
    else
        return 1
    fi
    case "$fingerprint" in
        ''|*[!0-9a-f]*) return 1 ;;
    esac
    [ "${#fingerprint}" -eq 64 ] 2>/dev/null || return 1
    printf '%s\n' "$fingerprint"
}

storage_expand_require_app_runtime_files() {
    local app_key="$1"

    case "$app_key" in
        openclash)
            openclash_require_asn_mmdb
            ;;
        openclash_share)
            [ -d /usr/share/openclash ] || die "哈基米运行资源缺失：/usr/share/openclash"
            ;;
        picoclaw_bin)
            [ -x /usr/bin/picoclaw ] || die "PicoClaw runtime missing: /usr/bin/picoclaw"
            ;;
        picoclaw_launcher)
            [ -x /usr/bin/picoclaw-launcher ] || die "PicoClaw launcher missing: /usr/bin/picoclaw-launcher"
            ;;
        picoclaw_home)
            [ -d /.picoclaw ] || die "PicoClaw data directory missing: /.picoclaw"
            ;;
        adguardhome)
            [ -x /usr/bin/AdGuardHome/AdGuardHome ] || die "AdGuardHome 运行文件缺失：/usr/bin/AdGuardHome/AdGuardHome"
            ;;
        zeroclaw_bin)
            [ -x /usr/bin/zeroclaw ] || die "鲲鹏智能体核心缺失：/usr/bin/zeroclaw"
            ;;
        nradio_skills)
            [ -d /etc/skills ] || die "鲲鹏智能体技能目录缺失：/etc/skills"
            ;;
        mt5700_bin)
            [ -x /usr/bin/at-webserver ] || die "MT5700 WebUI 后端缺失：/usr/bin/at-webserver"
            ;;
        mt5700_web)
            [ -f "$MT5700_WEB_ROOT/index.html" ] || die "MT5700 WebUI 页面缺失：$MT5700_WEB_ROOT/index.html"
            ;;
    esac
}

storage_expand_list_without_src() {
    local src="$1"
    local tmp_list

    [ -f "$ROOTFS_2ND_STORAGE_MIGRATE_LIST" ] || return 0
    tmp_list="$ROOTFS_2ND_STORAGE_MIGRATE_LIST.tmp.$$"
    if ! awk -F '\t' -v src="$src" '$3 != src { print }' "$ROOTFS_2ND_STORAGE_MIGRATE_LIST" > "$tmp_list" 2>/dev/null; then
        rm -f "$tmp_list" 2>/dev/null || true
        return 1
    fi
    mv "$tmp_list" "$ROOTFS_2ND_STORAGE_MIGRATE_LIST" || {
        rm -f "$tmp_list" 2>/dev/null || true
        return 1
    }
}

storage_expand_record_migration() {
    local label="$1"
    local service="$2"
    local src="$3"
    local target="$4"
    local kind="$5"
    local tmp_list migrated_at

    tmp_list="$ROOTFS_2ND_STORAGE_MIGRATE_LIST.tmp.$$"
    migrated_at="$(date '+%Y-%m-%d %H:%M:%S' 2>/dev/null || true)"
    rm -f "$tmp_list" 2>/dev/null || return 1
    if [ -f "$ROOTFS_2ND_STORAGE_MIGRATE_LIST" ]; then
        awk -F '\t' -v src="$src" '$3 != src { print }' "$ROOTFS_2ND_STORAGE_MIGRATE_LIST" > "$tmp_list" 2>/dev/null || {
            rm -f "$tmp_list" 2>/dev/null || true
            return 1
        }
    else
        : > "$tmp_list" || return 1
    fi
    printf '%s\t%s\t%s\t%s\t%s\t%s\n' "$label" "$service" "$src" "$target" "$kind" "$migrated_at" >> "$tmp_list" || {
        rm -f "$tmp_list" 2>/dev/null || true
        return 1
    }
    chmod 600 "$tmp_list" 2>/dev/null || {
        rm -f "$tmp_list" 2>/dev/null || true
        return 1
    }
    mv "$tmp_list" "$ROOTFS_2ND_STORAGE_MIGRATE_LIST" || {
        rm -f "$tmp_list" 2>/dev/null || true
        return 1
    }
    return 0
}

storage_expand_remove_migration_record() {
    local src="$1"

    storage_expand_list_without_src "$src" || return 1
    if [ -f "$ROOTFS_2ND_STORAGE_MIGRATE_LIST" ] && ! awk 'NF { found = 1 } END { exit(found ? 0 : 1) }' "$ROOTFS_2ND_STORAGE_MIGRATE_LIST" 2>/dev/null; then
        rm -f "$ROOTFS_2ND_STORAGE_MIGRATE_LIST" || return 1
    fi
    return 0
}

storage_expand_print_migration_list() {
    if [ ! -f "$ROOTFS_2ND_STORAGE_MIGRATE_LIST" ]; then
        log "迁移清单: 暂无"
        return 0
    fi

    log "迁移清单:"
    awk -F '\t' 'NF >= 4 { printf "  - %s: %s -> %s\n", $1, $3, $4 }' "$ROOTFS_2ND_STORAGE_MIGRATE_LIST" 2>/dev/null || true
}

storage_expand_recreated_payload_valid_at_path() {
    local app_key="$1"
    local payload_path="$2"
    local payload_size

    case "$app_key" in
        openclash)
            [ -f "$payload_path/ASN.mmdb" ] || return 1
            payload_size="$(wc -c < "$payload_path/ASN.mmdb" 2>/dev/null | tr -d ' ')"
            case "$payload_size" in
                ''|*[!0-9]*) return 1 ;;
            esac
            [ "$payload_size" -ge 1048576 ] 2>/dev/null
            ;;
        picoclaw_bin|picoclaw_launcher|zeroclaw_bin)
            [ -x "$payload_path" ]
            ;;
        mt5700_bin)
            [ -x "$payload_path" ]
            ;;
        mt5700_web)
            [ -f "$payload_path/index.html" ]
            ;;
        picoclaw_home)
            [ -d "$payload_path" ]
            ;;
        adguardhome)
            [ -x "$payload_path/AdGuardHome" ]
            ;;
        *)
            [ -e "$payload_path" ] || [ -L "$payload_path" ]
            ;;
    esac
}

storage_expand_rollback_recreated_path() {
    local src="$1"
    local target="$2"
    local backup_src="$3"
    local target_backup="$4"
    local tmp_target="$5"
    local link_src="$6"
    local failed_target="$7"

    if [ -L "$link_src" ]; then
        rm -f "$link_src" || return 1
    fi
    if [ -L "$src" ]; then
        rm -f "$src" || return 1
    fi
    if [ -e "$backup_src" ] || [ -L "$backup_src" ]; then
        [ ! -e "$src" ] && [ ! -L "$src" ] || return 1
        mv "$backup_src" "$src" || return 1
    fi
    if [ -e "$target_backup" ] || [ -L "$target_backup" ]; then
        if [ -e "$target" ] || [ -L "$target" ]; then
            [ ! -e "$failed_target" ] && [ ! -L "$failed_target" ] || return 1
            mv "$target" "$failed_target" || return 1
        fi
        if ! mv "$target_backup" "$target"; then
            if [ ! -e "$target" ] && [ ! -L "$target" ] && { [ -e "$failed_target" ] || [ -L "$failed_target" ]; }; then
                mv "$failed_target" "$target" 2>/dev/null || true
            fi
            return 1
        fi
        if [ -e "$failed_target" ] || [ -L "$failed_target" ]; then
            log "保留失败副本: $failed_target"
        fi
    fi
    rm -rf "$tmp_target" 2>/dev/null || true
    return 0
}

storage_expand_fail_recreated_path() {
    local app_key="$1"
    local label="$2"
    local service="$3"
    local src="$4"
    local target="$5"
    local backup_src="$6"
    local target_backup="$7"
    local tmp_target="$8"
    local link_src="$9"
    local failed_target="${10}"
    local failure_message="${11}"

    if storage_expand_rollback_recreated_path "$src" "$target" "$backup_src" "$target_backup" "$tmp_target" "$link_src" "$failed_target"; then
        log "回滚: $label 原实体路径与旧扩展盘目标已恢复"
        storage_expand_resume_service_after_relink_failure "$app_key" "$service"
        die "$failure_message，已回滚"
    fi
    log "回滚失败残留: src=$src backup_src=$backup_src target=$target target_backup=$target_backup failed_target=$failed_target"
    storage_expand_resume_service_after_relink_failure "$app_key" "$service"
    die "$failure_message；自动回滚未完成，已停止继续操作"
}

storage_expand_relink_recreated_path() {
    local app_key="$1"
    local label="$2"
    local service="$3"
    local src="$4"
    local target="$5"
    local tmp_target target_backup backup_src link_src failed_target kind source_bytes free_bytes required_bytes
    local source_fingerprint source_after_fingerprint copied_fingerprint source_backup_fingerprint target_after_fingerprint

    storage_expand_path_needs_relink "$src" "$target" || die "$label 当前状态不符合升级回弹修复条件：$src"
    storage_expand_require_app_runtime_files "$app_key"
    storage_expand_prepare_target_parent "$target" || die "$label 修复扩展盘目标父目录失败"

    source_bytes="$(storage_expand_path_size_bytes "$src")"
    free_bytes="$(get_path_free_bytes "$ROOTFS_2ND_STORAGE_MOUNT_POINT" 2>/dev/null || true)"
    case "$source_bytes" in
        ''|*[!0-9]*) die "$label 无法读取当前数据大小，拒绝升级回弹修复" ;;
    esac
    case "$free_bytes" in
        ''|*[!0-9]*) die "$label 无法读取扩展盘剩余空间，拒绝升级回弹修复" ;;
    esac
    [ "$source_bytes" -gt 0 ] 2>/dev/null || die "$label 当前实体路径为空，拒绝升级回弹修复：$src"
    required_bytes=$((source_bytes + 8388608))
    [ "$free_bytes" -ge "$required_bytes" ] 2>/dev/null || die "$label 扩展盘剩余空间不足：至少需要 $(format_bytes_human "$required_bytes")，当前 $(format_bytes_human "$free_bytes")"

    tmp_target="$target.relink.$$"
    target_backup="$target.pre-remigrate-$TS"
    backup_src="$src.nradio-storage-backup-$TS"
    link_src="$src.nradio-storage-link-$TS"
    failed_target="$target.failed-remigrate-$TS"
    [ ! -e "$tmp_target" ] && [ ! -L "$tmp_target" ] || die "$label 暂存路径已存在：$tmp_target"
    [ ! -e "$target_backup" ] && [ ! -L "$target_backup" ] || die "$label 扩展盘备份已存在：$target_backup"
    [ ! -e "$backup_src" ] && [ ! -L "$backup_src" ] || die "$label overlay 临时备份已存在：$backup_src"
    [ ! -e "$link_src" ] && [ ! -L "$link_src" ] || die "$label 软链接暂存路径已存在：$link_src"
    [ ! -e "$failed_target" ] && [ ! -L "$failed_target" ] || die "$label 失败副本路径已存在：$failed_target"

    if [ -d "$src" ]; then
        kind="dir"
    else
        kind="file"
    fi

    log "检测到: $label 更新后把已迁移路径重建到 overlay"
    log "重新接入: $src -> $target"
    log "空间参考: 当前数据 $(format_bytes_human "$source_bytes")，扩展盘剩余 $(format_bytes_human "$free_bytes")"
    storage_expand_stop_service_for_relink "$app_key" "$service" || {
        storage_expand_resume_service_after_relink_failure "$app_key" "$service"
        die "$label 服务未能确认停止，拒绝复制活动数据"
    }

    source_fingerprint="$(storage_expand_payload_fingerprint "$src" 2>/dev/null || true)"
    [ -n "$source_fingerprint" ] || {
        storage_expand_resume_service_after_relink_failure "$app_key" "$service"
        die "$label 当前数据内容指纹计算失败，原路径未改动"
    }

    cp -a "$src" "$tmp_target" || {
        rm -rf "$tmp_target" 2>/dev/null || true
        storage_expand_resume_service_after_relink_failure "$app_key" "$service"
        die "$label 当前数据复制到扩展盘暂存路径失败"
    }
    copied_fingerprint="$(storage_expand_payload_fingerprint "$tmp_target" 2>/dev/null || true)"
    source_after_fingerprint="$(storage_expand_payload_fingerprint "$src" 2>/dev/null || true)"
    if [ -z "$copied_fingerprint" ] || [ "$copied_fingerprint" != "$source_fingerprint" ] || [ "$source_after_fingerprint" != "$source_fingerprint" ] || ! storage_expand_recreated_payload_valid_at_path "$app_key" "$tmp_target"; then
        rm -rf "$tmp_target" 2>/dev/null || true
        storage_expand_resume_service_after_relink_failure "$app_key" "$service"
        die "$label 扩展盘暂存副本内容校验失败或复制期间源数据变化，原路径未改动"
    fi
    if storage_expand_relink_service_is_running "$app_key" "$service"; then
        rm -rf "$tmp_target" 2>/dev/null || true
        storage_expand_stop_service_for_relink "$app_key" "$service" 2>/dev/null || true
        storage_expand_resume_service_after_relink_failure "$app_key" "$service"
        die "$label 服务在复制期间重新启动，原路径未改动"
    fi
    ln -s "$target" "$link_src" || {
        rm -rf "$tmp_target" 2>/dev/null || true
        storage_expand_resume_service_after_relink_failure "$app_key" "$service"
        die "$label 软链接暂存创建失败，原路径未改动"
    }
    if ! storage_expand_link_points_under "$link_src" "$target"; then
        rm -f "$link_src" 2>/dev/null || true
        rm -rf "$tmp_target" 2>/dev/null || true
        storage_expand_resume_service_after_relink_failure "$app_key" "$service"
        die "$label 软链接暂存校验失败，原路径未改动"
    fi

    mv "$target" "$target_backup" || {
        rm -f "$link_src" 2>/dev/null || true
        rm -rf "$tmp_target" 2>/dev/null || true
        storage_expand_resume_service_after_relink_failure "$app_key" "$service"
        die "$label 旧扩展盘目标备份失败，原路径未改动"
    }
    mv "$tmp_target" "$target" || {
        storage_expand_fail_recreated_path "$app_key" "$label" "$service" "$src" "$target" "$backup_src" "$target_backup" "$tmp_target" "$link_src" "$failed_target" "$label 新扩展盘目标切换失败"
    }
    mv "$src" "$backup_src" || {
        storage_expand_fail_recreated_path "$app_key" "$label" "$service" "$src" "$target" "$backup_src" "$target_backup" "$tmp_target" "$link_src" "$failed_target" "$label overlay 原路径暂存失败"
    }
    mv "$link_src" "$src" || {
        storage_expand_fail_recreated_path "$app_key" "$label" "$service" "$src" "$target" "$backup_src" "$target_backup" "$tmp_target" "$link_src" "$failed_target" "$label 软链接原子切换失败"
    }
    if ! storage_expand_path_is_migrated "$src" "$target" || ! storage_expand_recreated_payload_valid_at_path "$app_key" "$src"; then
        storage_expand_fail_recreated_path "$app_key" "$label" "$service" "$src" "$target" "$backup_src" "$target_backup" "$tmp_target" "$link_src" "$failed_target" "$label 重新接入后的软链接或运行文件校验失败"
    fi
    if storage_expand_relink_service_is_running "$app_key" "$service"; then
        storage_expand_stop_service_for_relink "$app_key" "$service" || die "$label 服务意外重启且无法停止；保留 overlay 临时副本：$backup_src"
        storage_expand_fail_recreated_path "$app_key" "$label" "$service" "$src" "$target" "$backup_src" "$target_backup" "$tmp_target" "$link_src" "$failed_target" "$label 服务在切换期间重新启动"
    fi
    source_backup_fingerprint="$(storage_expand_payload_fingerprint "$backup_src" 2>/dev/null || true)"
    target_after_fingerprint="$(storage_expand_payload_fingerprint "$target" 2>/dev/null || true)"
    if [ "$source_backup_fingerprint" != "$source_fingerprint" ] || [ "$target_after_fingerprint" != "$source_fingerprint" ]; then
        storage_expand_fail_recreated_path "$app_key" "$label" "$service" "$src" "$target" "$backup_src" "$target_backup" "$tmp_target" "$link_src" "$failed_target" "$label 切换期间数据发生变化"
    fi
    if storage_expand_relink_service_is_running "$app_key" "$service"; then
        storage_expand_stop_service_for_relink "$app_key" "$service" || die "$label 最终校验期间服务意外重启且无法停止；保留 overlay 临时副本：$backup_src"
        storage_expand_fail_recreated_path "$app_key" "$label" "$service" "$src" "$target" "$backup_src" "$target_backup" "$tmp_target" "$link_src" "$failed_target" "$label 最终校验期间服务重新启动"
    fi

    storage_expand_record_migration "$label" "$service" "$src" "$target" "$kind" || {
        storage_expand_fail_recreated_path "$app_key" "$label" "$service" "$src" "$target" "$backup_src" "$target_backup" "$tmp_target" "$link_src" "$failed_target" "$label 迁移清单更新失败"
    }
    if ! storage_expand_start_service_for_relink "$app_key" "$service"; then
        storage_expand_remove_migration_record "$src" || log "警告: $label 服务启动失败后未能删除迁移清单记录"
        storage_expand_fail_recreated_path "$app_key" "$label" "$service" "$src" "$target" "$backup_src" "$target_backup" "$tmp_target" "$link_src" "$failed_target" "$label 服务启动状态校验失败"
    fi
    rm -rf "$backup_src" || log "警告: $label 重新接入成功，但 overlay 临时副本清理失败：$backup_src"
    rm -rf "$target_backup" || log "警告: $label 重新接入成功，但旧扩展盘临时副本清理失败：$target_backup"
    log "完成: $label 更新回弹路径已重新接入扩展盘"
}

storage_expand_restore_migration_backup() {
    local src="$1"
    local target="$2"
    local backup_src="$3"
    local remove_target="$4"

    if [ -L "$src" ]; then
        rm -f "$src" || return 1
    elif [ -e "$src" ]; then
        return 1
    fi
    [ -e "$backup_src" ] || [ -L "$backup_src" ] || return 1
    mv "$backup_src" "$src" || return 1
    if [ "$remove_target" = '1' ]; then
        rm -rf "$target" || return 1
    fi
    return 0
}

storage_expand_migrate_one_app() {
    local app_key="$1"
    local spec label service src target target_parent tmp_target backup_src kind src_real target_real

    storage_expand_require_active
    spec="$(storage_expand_app_spec "$app_key")" || die "未知迁移项：$app_key"
    label="$(printf '%s\n' "$spec" | awk -F '\t' '{ print $1 }')"
    service="$(printf '%s\n' "$spec" | awk -F '\t' '{ print $2 }')"
    src="$(printf '%s\n' "$spec" | awk -F '\t' '{ print $3 }')"
    target="$(storage_expand_target_for_path "$src")"
    target_parent="$(dirname "$target")"

    [ -e "$src" ] || {
        log "跳过: $label 源路径不存在：$src"
        return 0
    }

    if [ -L "$src" ]; then
        src_real="$(storage_expand_canonical_path "$src")"
        target_real="$(storage_expand_canonical_path "$target")"
        if [ "$src_real" = "$target_real" ]; then
            log "跳过: $label 已迁移：$src -> $target"
            storage_expand_prepare_target_parent "$target" || die "$label 修复扩展盘目标父目录权限失败"
            storage_expand_require_app_runtime_files "$app_key"
            storage_expand_record_migration "$label" "$service" "$src" "$target" "link" || die "$label 更新迁移清单失败"
            return 0
        fi
        die "$label 源路径已是非本功能软链接：$src -> $src_real"
    fi

    if storage_expand_path_has_child_links_to_target "$src" "$target"; then
        [ -d "$target" ] || die "$label 扩展盘目标不存在或不是目录：$target"
        storage_expand_prepare_target_parent "$target" || die "$label 修复扩展盘目标父目录权限失败"
        storage_expand_path_has_self_loop_child_links "$src" && die "$label 原路径含自指软链接，拒绝迁移：$src"
        storage_expand_path_has_self_loop_child_links "$target" && die "$label 扩展盘目标含自指软链接，请先修复目标目录：$target"
        log "迁移: $label -> $target"
        storage_expand_stop_service "$service" || die "$label 服务未能确认停止，拒绝迁移活动数据"
        storage_expand_sync_hybrid_to_target "$src" "$target" || {
            storage_expand_start_service "$service" || log "警告: $label 同步失败后未能恢复服务状态：$service"
            die "$label 同步到扩展盘失败"
        }
        backup_src="$src.nradio-storage-backup-$TS"
        mv "$src" "$backup_src" || {
            storage_expand_start_service "$service" || log "警告: $label 移动失败后未能恢复服务状态：$service"
            die "$label 移动原路径失败：$src"
        }
        ln -s "$target" "$src" || {
            mv "$backup_src" "$src" 2>/dev/null || true
            storage_expand_start_service "$service" || log "警告: $label 软链接失败后未能恢复服务状态：$service"
            die "$label 创建软链接失败"
        }
        if ! storage_expand_recreated_payload_valid_at_path "$app_key" "$src"; then
            storage_expand_restore_migration_backup "$src" "$target" "$backup_src" '0' || die "$label 运行文件校验失败且自动回滚未完成：$backup_src"
            storage_expand_start_service "$service" || log "警告: $label 回滚后未能恢复服务状态：$service"
            die "$label 运行文件校验失败，已恢复原路径"
        fi
        if ! storage_expand_start_service "$service"; then
            storage_expand_restore_migration_backup "$src" "$target" "$backup_src" '0' || die "$label 服务启动失败且自动回滚未完成：$backup_src"
            storage_expand_start_service "$service" || log "警告: $label 回滚后仍未能恢复服务状态：$service"
            die "$label 迁移后服务启动失败，已恢复原路径"
        fi
        if ! storage_expand_record_migration "$label" "$service" "$src" "$target" "link"; then
            storage_expand_stop_service "$service" || die "$label 迁移清单更新失败且服务无法停止；保留原路径备份：$backup_src"
            storage_expand_restore_migration_backup "$src" "$target" "$backup_src" '0' || die "$label 迁移清单更新失败且自动回滚未完成：$backup_src"
            storage_expand_start_service "$service" || log "警告: $label 回滚后未能恢复服务状态：$service"
            die "$label 迁移清单更新失败，已恢复原路径"
        fi
        rm -rf "$backup_src" || log "警告: $label 迁移成功，但原路径备份清理失败：$backup_src"
        log "完成: $label 已迁移到扩展盘"
        return 0
    fi
    storage_expand_path_has_self_loop_child_links "$src" && die "$label 原路径含自指软链接，拒绝迁移：$src"

    if storage_expand_path_needs_relink "$src" "$target"; then
        storage_expand_relink_recreated_path "$app_key" "$label" "$service" "$src" "$target"
        return 0
    fi

    [ ! -e "$target" ] || die "$label 目标路径已存在：$target"
    storage_expand_require_app_runtime_files "$app_key"
    storage_expand_prepare_target_parent "$target" || die "$label 创建扩展盘目标父目录失败：$target_parent"
    tmp_target="$target.tmp.$$"
    rm -rf "$tmp_target" 2>/dev/null || true

    if [ -d "$src" ]; then
        kind="dir"
    else
        kind="file"
    fi

    log "迁移: $label -> $target"
    storage_expand_stop_service "$service" || die "$label 服务未能确认停止，拒绝迁移活动数据"
    cp -a "$src" "$tmp_target" || {
        rm -rf "$tmp_target" 2>/dev/null || true
        storage_expand_start_service "$service" || log "警告: $label 复制失败后未能恢复服务状态：$service"
        die "$label 复制到扩展盘失败"
    }
    mv "$tmp_target" "$target" || {
        rm -rf "$tmp_target" 2>/dev/null || true
        storage_expand_start_service "$service" || log "警告: $label 写入失败后未能恢复服务状态：$service"
        die "$label 写入扩展盘目标失败"
    }

    backup_src="$src.nradio-storage-backup-$TS"
    mv "$src" "$backup_src" || {
        rm -rf "$target" 2>/dev/null || true
        storage_expand_start_service "$service" || log "警告: $label 移动失败后未能恢复服务状态：$service"
        die "$label 移动原路径失败：$src"
    }
    ln -s "$target" "$src" || {
        mv "$backup_src" "$src" 2>/dev/null || true
        rm -rf "$target" 2>/dev/null || true
        storage_expand_start_service "$service" || log "警告: $label 软链接失败后未能恢复服务状态：$service"
        die "$label 创建软链接失败"
    }

    if ! storage_expand_recreated_payload_valid_at_path "$app_key" "$src"; then
        storage_expand_restore_migration_backup "$src" "$target" "$backup_src" '1' || die "$label 运行文件校验失败且自动回滚未完成：$backup_src"
        storage_expand_start_service "$service" || log "警告: $label 回滚后未能恢复服务状态：$service"
        die "$label 运行文件校验失败，已恢复原路径"
    fi
    if ! storage_expand_start_service "$service"; then
        storage_expand_restore_migration_backup "$src" "$target" "$backup_src" '1' || die "$label 服务启动失败且自动回滚未完成：$backup_src"
        storage_expand_start_service "$service" || log "警告: $label 回滚后仍未能恢复服务状态：$service"
        die "$label 迁移后服务启动失败，已恢复原路径"
    fi
    if ! storage_expand_record_migration "$label" "$service" "$src" "$target" "$kind"; then
        storage_expand_stop_service "$service" || die "$label 迁移清单更新失败且服务无法停止；保留原路径备份：$backup_src"
        storage_expand_restore_migration_backup "$src" "$target" "$backup_src" '1' || die "$label 迁移清单更新失败且自动回滚未完成：$backup_src"
        storage_expand_start_service "$service" || log "警告: $label 回滚后未能恢复服务状态：$service"
        die "$label 迁移清单更新失败，已恢复原路径"
    fi
    rm -rf "$backup_src" || log "警告: $label 迁移成功，但原路径备份清理失败：$backup_src"
    log "完成: $label 已迁移到扩展盘"
}

storage_expand_restore_one_app() {
    local app_key="$1"
    local spec label service src target required_bytes free_bytes tmp_restore src_real target_real keep_target restore_mode

    storage_expand_require_active
    spec="$(storage_expand_app_spec "$app_key")" || die "未知还原项：$app_key"
    label="$(printf '%s\n' "$spec" | awk -F '\t' '{ print $1 }')"
    service="$(printf '%s\n' "$spec" | awk -F '\t' '{ print $2 }')"
    src="$(printf '%s\n' "$spec" | awk -F '\t' '{ print $3 }')"
    target="$(storage_expand_target_for_path "$src")"

    [ -e "$target" ] || {
        log "跳过: $label 扩展盘目标不存在：$target"
        storage_expand_remove_migration_record "$src" || die "$label 清理过期迁移清单失败"
        return 0
    }
    storage_expand_prepare_target_parent "$target" || die "$label 修复扩展盘目标父目录权限失败"
    storage_expand_path_has_self_loop_child_links "$target" && die "$label 扩展盘目标含自指软链接，请先修复目标目录：$target"
    if [ -L "$src" ]; then
        src_real="$(storage_expand_canonical_path "$src")"
        target_real="$(storage_expand_canonical_path "$target")"
        [ "$src_real" = "$target_real" ] || die "$label 软链接目标不匹配：$src -> $src_real"
        restore_mode="link"
    elif storage_expand_path_has_child_links_to_target "$src" "$target"; then
        restore_mode="hybrid"
    else
        die "$label 当前源路径不是本功能迁移状态，拒绝覆盖：$src"
    fi

    required_bytes="$(storage_expand_restore_size_bytes "$app_key" "$target")"
    free_bytes="$(get_path_free_bytes /overlay 2>/dev/null || true)"
    case "$free_bytes" in
        ''|*[!0-9]*)
            die "无法读取 /overlay 剩余空间，拒绝还原"
            ;;
    esac
    log "空间参考: $label 目录约 $(format_bytes_human "$required_bytes")，/overlay 剩余 $(format_bytes_human "$free_bytes")；继续尝试完整还原"
    if [ "$restore_mode" = "link" ]; then
        storage_expand_require_app_runtime_files "$app_key"
    fi

    log "还原: $label -> $src"
    storage_expand_stop_service "$service" || die "$label 服务未能确认停止，拒绝还原：$service"
    if [ "$restore_mode" = "link" ]; then
        rm -f "$src" || {
            storage_expand_start_service "$service" || log "警告: $label 删除软链接失败后未能恢复服务状态：$service"
            die "$label 删除软链接失败：$src"
        }
        tmp_restore="$src.restore.$$"
        rm -rf "$tmp_restore" 2>/dev/null || true
        if ! storage_expand_restore_copy_or_fail "$app_key" "$label" "$src" "$target" "$tmp_restore"; then
            storage_expand_start_service "$service" || log "警告: $label 复制失败后未能恢复服务状态：$service"
            die "$label 从扩展盘复制回 overlay 失败"
        fi
        mv "$tmp_restore" "$src" || {
            rm -rf "$tmp_restore" 2>/dev/null || true
            ln -s "$target" "$src" 2>/dev/null || true
            storage_expand_start_service "$service" || log "警告: $label 写回失败后未能恢复服务状态：$service"
            die "$label 写回原路径失败"
        }
    else
        storage_expand_restore_hybrid_payload "$app_key" "$src" "$target" || {
            storage_expand_start_service "$service" || log "警告: $label 续还原失败后未能恢复服务状态：$service"
            die "$label 续还原失败"
        }
    fi

    if ! storage_expand_recreated_payload_valid_at_path "$app_key" "$src"; then
        if [ "$restore_mode" = "link" ]; then
            rm -rf "$src" 2>/dev/null || true
            ln -s "$target" "$src" || die "$label 运行文件校验失败且自动回滚未完成：$src"
        fi
        storage_expand_start_service "$service" || log "警告: $label 校验失败后未能恢复服务状态：$service"
        die "$label 还原后运行文件校验失败"
    fi
    if ! storage_expand_start_service "$service"; then
        if [ "$restore_mode" = "link" ]; then
            rm -rf "$src" 2>/dev/null || true
            ln -s "$target" "$src" || die "$label 服务启动失败且自动回滚未完成：$src"
            storage_expand_start_service "$service" || log "警告: $label 回滚后仍未能恢复服务状态：$service"
        fi
        die "$label 还原后服务启动失败"
    fi

    keep_target=0
    if storage_expand_path_depends_on_target "$src" "$target"; then
        keep_target=1
        log "保留: $label 原路径含扩展盘子项链接，保留 $target"
    fi
    if [ "$keep_target" = '1' ]; then
        storage_expand_record_migration "$label" "$service" "$src" "$target" "hybrid" || die "$label 已还原且服务已恢复，但更新迁移清单失败"
    else
        storage_expand_remove_migration_record "$src" || die "$label 已还原且服务已恢复，但删除迁移清单记录失败"
        rm -rf "$target" || die "$label 已还原且服务已恢复，但删除扩展盘目标失败：$target"
    fi
    log "完成: $label 已还原到原路径"
}

storage_expand_preflight_restore_all() {
    local list_file="$1"
    local app_key label listed_src spec src target src_real target_real required_bytes free_bytes total_required

    total_required=0
    free_bytes="$(get_path_free_bytes /overlay 2>/dev/null || true)"
    case "$free_bytes" in
        ''|*[!0-9]*)
            die "无法读取 /overlay 剩余空间，拒绝全部还原"
            ;;
    esac

    log "全部还原空间预检:"
    while IFS="$(printf '\t')" read -r app_key label listed_src; do
        [ -n "$app_key" ] || continue
        spec="$(storage_expand_app_spec "$app_key")" || die "未知还原项：$app_key"
        src="$(printf '%s\n' "$spec" | awk -F '\t' '{ print $3 }')"
        target="$(storage_expand_target_for_path "$src")"
        [ -e "$target" ] || die "$label 扩展盘目标不存在：$target"
        storage_expand_path_has_self_loop_child_links "$target" && die "$label 扩展盘目标含自指软链接，请先修复目标目录：$target"
        if [ -L "$src" ]; then
            src_real="$(storage_expand_canonical_path "$src")"
            target_real="$(storage_expand_canonical_path "$target")"
            [ "$src_real" = "$target_real" ] || die "$label 软链接目标不匹配：$src -> $src_real"
        elif storage_expand_path_has_child_links_to_target "$src" "$target"; then
            :
        else
            die "$label 当前源路径不是本功能迁移状态，拒绝全部还原：$src"
        fi
        if [ -L "$src" ]; then
            storage_expand_require_app_runtime_files "$app_key"
        fi
        required_bytes="$(storage_expand_restore_size_bytes "$app_key" "$target")"
        case "$required_bytes" in
            ''|*[!0-9]*)
                required_bytes=0
                ;;
        esac
        total_required=$((total_required + required_bytes))
        log "  - $label: $(format_bytes_human "$required_bytes")"
    done < "$list_file"

    log "全部还原空间参考: 合计约 $(format_bytes_human "$total_required")；/overlay 剩余: $(format_bytes_human "$free_bytes")；继续尝试完整还原"
}

write_rootfs_2nd_storage_init() {
    backup_file "$ROOTFS_2ND_STORAGE_INIT"
    mkdir -p "$(dirname "$ROOTFS_2ND_STORAGE_INIT")"
    cat > "$ROOTFS_2ND_STORAGE_INIT" <<'EOF_ROOTFS_2ND_DATA_INIT'
#!/bin/sh /etc/rc.common

START=09
STOP=89

MOUNT_POINT="/mnt/rootfs_2nd_data"

resolve_rootfs_2nd_device() {
	if [ -e /dev/disk/by-partlabel/rootfs_2nd ]; then
		readlink -f /dev/disk/by-partlabel/rootfs_2nd 2>/dev/null || printf '%s\n' /dev/disk/by-partlabel/rootfs_2nd
		return 0
	fi

	for sysdev in /sys/class/block/*; do
		[ -f "$sysdev/uevent" ] || continue
		partname="$(sed -n 's/^PARTNAME=//p' "$sysdev/uevent" 2>/dev/null | sed -n '1p' || true)"
		[ "$partname" = 'rootfs_2nd' ] || continue
		dev="/dev/$(basename "$sysdev")"
		[ -b "$dev" ] || continue
		printf '%s\n' "$dev"
		return 0
	done

	return 1
}

start() {
	device="$(resolve_rootfs_2nd_device 2>/dev/null || true)"
	[ -n "$device" ] || return 0
	mkdir -p "$MOUNT_POINT"
	grep -qs " $MOUNT_POINT " /proc/mounts && return 0
	mount -t f2fs "$device" "$MOUNT_POINT"
}

stop() {
	umount "$MOUNT_POINT" 2>/dev/null || true
}
EOF_ROOTFS_2ND_DATA_INIT
    chmod +x "$ROOTFS_2ND_STORAGE_INIT"
}

enable_rootfs_2nd_storage_autostart() {
    write_rootfs_2nd_storage_init
    "$ROOTFS_2ND_STORAGE_INIT" enable >/dev/null 2>&1 || {
        mkdir -p /etc/rc.d
        rm -f /etc/rc.d/S12rootfs_2nd_data
        ln -sf ../init.d/rootfs_2nd_data /etc/rc.d/S09rootfs_2nd_data
    }
}

mount_rootfs_2nd_storage_now() {
    local device="$1"
    local mount_source mounted_elsewhere

    mount_source="$(storage_expand_mount_source_for_mountpoint 2>/dev/null || true)"
    if [ -n "$mount_source" ]; then
        storage_expand_mount_source_matches_device "$mount_source" "$device" || die "$ROOTFS_2ND_STORAGE_MOUNT_POINT 已被其它设备挂载：$mount_source"
        return 0
    fi

    mounted_elsewhere="$(storage_expand_device_mountpoint "$device" 2>/dev/null || true)"
    [ -z "$mounted_elsewhere" ] || die "rootfs_2nd 已挂载在 $mounted_elsewhere，已停止"

    mkdir -p "$ROOTFS_2ND_STORAGE_MOUNT_POINT"
    mount -t f2fs "$device" "$ROOTFS_2ND_STORAGE_MOUNT_POINT" >/dev/null 2>&1 || return 1
}

storage_expand_confirm_format() {
    log "警告: 启用该扩展会格式化第二系统 rootfs_2nd 分区。"
    log "影响: 第二系统 OpenWrt 内容会被清空，之后只能先关闭扩展，再重新烧录第二系统。"
    prompt_with_default "确认清空 rootfs_2nd 请输入 YES_ROOTFS_2ND" ""
    [ "$PROMPT_RESULT" = 'YES_ROOTFS_2ND' ] || {
        log "已取消"
        return 1
    }
}

storage_expand_confirm_reinitialize_format() {
    log "警告: 即将清空并重新初始化 rootfs_2nd 扩展盘。"
    log "用途: 设备恢复出厂后，overlay 已重新安装应用，但 rootfs_2nd 仍残留旧应用数据时使用。"
    log "影响: 只格式化 PARTLABEL=rootfs_2nd；当前 overlay 已安装应用会保留。"
    log "清理: $ROOTFS_2ND_STORAGE_APPS_DIR 和 $ROOTFS_2ND_STORAGE_MIGRATE_LIST 会重新生成。"
    prompt_with_default "确认格式化 rootfs_2nd 请输入 FORMAT_ROOTFS_2ND" ""
    [ "$PROMPT_RESULT" = 'FORMAT_ROOTFS_2ND' ] || {
        log "已取消"
        return 1
    }
}

enable_rootfs_2nd_storage_expand() {
    local device mount_source

    require_rootfs_2nd_storage_capable
    storage_expand_is_booted_from_rootfs_2nd && die "当前疑似从第二系统 rootfs_2nd 启动，禁止把当前系统分区改作扩展盘"
    device="$(storage_expand_find_rootfs_2nd_device 2>/dev/null || true)"
    [ -n "$device" ] || die "未找到 PARTLABEL=rootfs_2nd 分区，已停止"
    mount_source="$(storage_expand_mount_source_for_mountpoint 2>/dev/null || true)"
    if [ -n "$mount_source" ]; then
        storage_expand_mount_source_matches_device "$mount_source" "$device" || die "$ROOTFS_2ND_STORAGE_MOUNT_POINT 已被其它设备挂载：$mount_source"
        enable_rootfs_2nd_storage_autostart
        printf '%s\n' "enabled $(date '+%Y-%m-%d %H:%M:%S' 2>/dev/null || true)" > "$ROOTFS_2ND_STORAGE_MARKER"
        storage_expand_prepare_apps_tree || die "初始化扩展盘应用目录失败"
        patch_reset_page_storage_expand_guard
        patch_appcenter_storage_expand_display
        log "检测到 rootfs_2nd 已挂载，已写入自启动和启用标记"
        storage_expand_status
        return 0
    fi

    if [ -f "$ROOTFS_2ND_STORAGE_MARKER" ]; then
        enable_rootfs_2nd_storage_autostart
        mount_rootfs_2nd_storage_now "$device" || die "检测到启用标记，但挂载 rootfs_2nd 失败；请先查看分区状态"
        storage_expand_prepare_apps_tree || die "初始化扩展盘应用目录失败"
        patch_reset_page_storage_expand_guard
        patch_appcenter_storage_expand_display
        log "已按现有启用标记恢复挂载"
        storage_expand_status
        return 0
    fi

    mkdir -p "$ROOTFS_2ND_STORAGE_MOUNT_POINT"
    if mount_rootfs_2nd_storage_now "$device"; then
        enable_rootfs_2nd_storage_autostart
        printf '%s\n' "enabled $(date '+%Y-%m-%d %H:%M:%S' 2>/dev/null || true)" > "$ROOTFS_2ND_STORAGE_MARKER"
        storage_expand_prepare_apps_tree || die "初始化扩展盘应用目录失败"
        patch_reset_page_storage_expand_guard
        patch_appcenter_storage_expand_display
        log "检测到 rootfs_2nd 已是 f2fs，已直接接入扩展挂载"
        storage_expand_status
        return 0
    fi

    command -v mkfs.f2fs >/dev/null 2>&1 || die "系统缺少 mkfs.f2fs，无法格式化 rootfs_2nd"
    storage_expand_confirm_format || return 1

    mkfs.f2fs -f -l rootfs_2nd_data "$device" >/dev/null 2>&1 || die "格式化 rootfs_2nd 为 f2fs 失败"
    enable_rootfs_2nd_storage_autostart
    mount_rootfs_2nd_storage_now "$device" || die "格式化后挂载 rootfs_2nd 失败"
    printf '%s\n' "enabled $(date '+%Y-%m-%d %H:%M:%S' 2>/dev/null || true)" > "$ROOTFS_2ND_STORAGE_MARKER"
    storage_expand_prepare_apps_tree || die "初始化扩展盘应用目录失败"
    patch_reset_page_storage_expand_guard
    patch_appcenter_storage_expand_display
    log "已启用 rootfs_2nd 存储扩展"
    storage_expand_status
}

disable_rootfs_2nd_storage_expand() {
    local device mount_source

    require_rootfs_2nd_storage_capable
    device="$(storage_expand_find_rootfs_2nd_device 2>/dev/null || true)"
    [ -n "$device" ] || die "未找到 PARTLABEL=rootfs_2nd 分区，已停止"
    if [ -f "$ROOTFS_2ND_STORAGE_MIGRATE_LIST" ] && awk 'NF { found = 1 } END { exit(found ? 0 : 1) }' "$ROOTFS_2ND_STORAGE_MIGRATE_LIST" 2>/dev/null; then
        storage_expand_print_migration_list
        die "仍有应用迁移到扩展盘，请先还原应用后再关闭存储扩展"
    fi
    if storage_expand_has_expand_dependency; then
        storage_expand_print_expand_dependencies || true
        die "仍有原路径依赖扩展盘，禁止关闭存储扩展"
    fi
    patch_reset_page_storage_expand_guard
    patch_appcenter_storage_expand_display

    mount_source="$(storage_expand_mount_source_for_mountpoint 2>/dev/null || true)"
    if [ -n "$mount_source" ]; then
        storage_expand_mount_source_matches_device "$mount_source" "$device" || die "$ROOTFS_2ND_STORAGE_MOUNT_POINT 已被其它设备挂载：$mount_source"
        umount "$ROOTFS_2ND_STORAGE_MOUNT_POINT" >/dev/null 2>&1 || die "卸载 $ROOTFS_2ND_STORAGE_MOUNT_POINT 失败，请先停止正在使用扩展盘的程序"
    fi

    if [ -f "$ROOTFS_2ND_STORAGE_INIT" ]; then
        "$ROOTFS_2ND_STORAGE_INIT" disable >/dev/null 2>&1 || true
        backup_file "$ROOTFS_2ND_STORAGE_INIT"
        rm -f "$ROOTFS_2ND_STORAGE_INIT"
    fi
    rm -f /etc/rc.d/S09rootfs_2nd_data /etc/rc.d/S12rootfs_2nd_data "$ROOTFS_2ND_STORAGE_MARKER"
    rmdir "$ROOTFS_2ND_STORAGE_MOUNT_POINT" 2>/dev/null || true

    log "已关闭 rootfs_2nd 存储扩展。"
    log "说明: 这只恢复第二系统烧录入口的使用条件，不会自动恢复第二系统内容；需要重新烧录第二系统固件。"
}

reinitialize_rootfs_2nd_storage_expand() {
    local device mount_source mounted_elsewhere

    require_rootfs_2nd_storage_capable
    storage_expand_is_booted_from_rootfs_2nd && die "当前疑似从第二系统 rootfs_2nd 启动，禁止格式化当前启动分区"
    command -v mkfs.f2fs >/dev/null 2>&1 || die "系统缺少 mkfs.f2fs，无法格式化 rootfs_2nd"

    device="$(storage_expand_find_rootfs_2nd_device 2>/dev/null || true)"
    [ -n "$device" ] || die "未找到 PARTLABEL=rootfs_2nd 分区，已停止"

    log "当前 rootfs_2nd 扩展状态:"
    storage_expand_status || true
    storage_expand_confirm_reinitialize_format || return 1

    mount_source="$(storage_expand_mount_source_for_mountpoint 2>/dev/null || true)"
    if [ -n "$mount_source" ]; then
        storage_expand_mount_source_matches_device "$mount_source" "$device" || die "$ROOTFS_2ND_STORAGE_MOUNT_POINT 已被其它设备挂载：$mount_source"
        umount "$ROOTFS_2ND_STORAGE_MOUNT_POINT" >/dev/null 2>&1 || die "卸载 $ROOTFS_2ND_STORAGE_MOUNT_POINT 失败，请先停止正在使用扩展盘的程序"
    else
        mounted_elsewhere="$(storage_expand_device_mountpoint "$device" 2>/dev/null || true)"
        [ -z "$mounted_elsewhere" ] || die "rootfs_2nd 已挂载在 $mounted_elsewhere，已停止"
    fi

    mkfs.f2fs -f -l rootfs_2nd_data "$device" >/dev/null 2>&1 || die "格式化 rootfs_2nd 为 f2fs 失败"
    rm -f "$ROOTFS_2ND_STORAGE_MIGRATE_LIST" 2>/dev/null || true
    storage_expand_remove_rootfs_2nd_orphan_links
    enable_rootfs_2nd_storage_autostart
    mount_rootfs_2nd_storage_now "$device" || die "格式化后挂载 rootfs_2nd 失败"
    printf '%s\n' "enabled $(date '+%Y-%m-%d %H:%M:%S' 2>/dev/null || true)" > "$ROOTFS_2ND_STORAGE_MARKER"
    storage_expand_prepare_apps_tree || die "初始化扩展盘应用目录失败"
    patch_reset_page_storage_expand_guard
    patch_appcenter_storage_expand_display
    log "已清空并重新初始化 rootfs_2nd 扩展盘。"
    log "下一步: 重新执行 5. 迁移应用到扩展盘。"
    storage_expand_status
}

patch_reset_page_storage_expand_guard() {
