    entry({"nradioadv", "system", "openlist", "logs"}, template("nradio_adv/openlist_logs"), _("运行日志"), 20).leaf = true
    entry({"nradioadv", "system", "appcenter", "openlist"}, alias("nradioadv", "system", "openlist"), nil, nil, true).leaf = true
