schedule_mode:depends({ enabled = "1", schedule_enabled = "1" })

function m.on_after_commit(map)
    os.execute("/etc/init.d/fanctrl restart >/dev/null 2>&1")
end

m:append(Template("nradio_fanctrl/polish"))

return m
EOF_FANCTRL_CBI

