.nr-fan-dashboard{position:relative;z-index:1;margin:0 0 16px}.nr-fan-hero{display:grid;grid-template-columns:minmax(260px,1.05fr) minmax(310px,1.35fr);gap:18px;padding:20px;border:1px solid rgba(33,212,253,.20);border-radius:18px;background:linear-gradient(135deg,rgba(14,26,39,.95),rgba(10,17,28,.93));box-shadow:inset 0 1px 0 rgba(255,255,255,.05),0 14px 32px rgba(0,0,0,.20);overflow:hidden}
.nr-fan-hero:after{content:"";position:absolute;width:260px;height:260px;right:-130px;top:-150px;border-radius:50%;background:rgba(33,212,253,.08);filter:blur(4px);pointer-events:none}.nr-fan-intro{display:flex;align-items:center;gap:16px;min-width:0}.nr-fan-gauge{--nr-temp-angle:0deg;--nr-temp-color:var(--nr-fan-cyan);position:relative;flex:0 0 126px;width:126px;height:126px;border-radius:50%;display:grid;place-items:center;background:conic-gradient(var(--nr-temp-color) var(--nr-temp-angle),rgba(111,139,167,.13) 0);box-shadow:0 0 34px rgba(33,212,253,.13)}
.nr-fan-gauge:before{content:"";position:absolute;inset:8px;border-radius:50%;background:linear-gradient(145deg,#101a27,#080d15);box-shadow:inset 0 0 0 1px rgba(255,255,255,.05),inset 0 10px 28px rgba(0,0,0,.25)}.nr-fan-gauge-value{position:relative;z-index:1;text-align:center}.nr-fan-gauge-value strong{display:block;color:#f7fbff;font-size:31px;line-height:1;font-weight:900;letter-spacing:-.04em}.nr-fan-gauge-value span{display:block;margin-top:6px;color:var(--nr-fan-muted);font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase}
.nr-fan-copy{min-width:0}.nr-fan-eyebrow{display:flex;align-items:center;gap:8px;margin-bottom:6px;color:var(--nr-fan-cyan);font-size:11px;font-weight:850;letter-spacing:.12em;text-transform:uppercase}.nr-fan-eyebrow:before{content:"";width:7px;height:7px;border-radius:50%;background:currentColor;box-shadow:0 0 12px currentColor}.nr-fan-copy h3{margin:0;color:#f7fbff;font-size:22px;line-height:1.2;font-weight:900;letter-spacing:-.025em}.nr-fan-copy p{max-width:390px;margin:9px 0 0;color:var(--nr-fan-muted);font-size:12px;line-height:1.6}
.nr-fan-live{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;align-content:center}.nr-fan-metric{display:flex;align-items:center;gap:12px;min-height:64px;padding:11px 13px;border:1px solid rgba(144,166,194,.14);border-radius:13px;background:rgba(6,12,20,.52);box-sizing:border-box}.nr-fan-metric-icon{display:grid;place-items:center;flex:0 0 36px;width:36px;height:36px;border-radius:11px;background:rgba(33,212,253,.10);color:var(--nr-fan-cyan)}.nr-fan-metric-icon svg{width:23px;height:23px}.nr-fan-metric-copy{min-width:0}.nr-fan-metric-copy span{display:block;color:var(--nr-fan-muted);font-size:10px;font-weight:750;letter-spacing:.07em;text-transform:uppercase}.nr-fan-metric-copy strong{display:block;margin-top:3px;color:#f2f7fb;font-size:13px;font-weight:850;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.nr-fan-rotor{transform-origin:50% 50%;animation:nr-fan-spin 1.2s linear infinite}.nr-fan-dashboard[data-fan="off"] .nr-fan-rotor{animation-play-state:paused;opacity:.48}@keyframes nr-fan-spin{to{transform:rotate(360deg)}}
.nr-fan-state{display:inline-flex;align-items:center;gap:7px;margin-top:12px;padding:6px 10px;border:1px solid rgba(32,227,178,.22);border-radius:999px;background:rgba(32,227,178,.08);color:#8bf5dc;font-size:11px;font-weight:800}.nr-fan-state:before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor;box-shadow:0 0 10px currentColor}.nr-fan-dashboard[data-enabled="0"] .nr-fan-state{border-color:rgba(144,166,194,.18);background:rgba(144,166,194,.07);color:#9caabc}.nr-fan-safety{display:flex;align-items:flex-start;gap:10px;margin-top:10px;padding:10px 13px;border:1px solid rgba(255,173,66,.15);border-radius:12px;background:rgba(255,173,66,.055);color:#c5ced9;font-size:11px;line-height:1.55}.nr-fan-safety b{color:#ffd48d}.nr-fan-safety-mark{flex:0 0 auto;color:var(--nr-fan-warm);font-weight:900}
@media(max-width:920px){.nr-fan-hero{grid-template-columns:1fr}.nr-fan-copy p{max-width:none}.cbi-section-node{grid-template-columns:1fr!important}}
@media(max-width:560px){.cbi-map{padding:11px!important;border-radius:16px!important}.nr-fan-hero{padding:15px;border-radius:15px}.nr-fan-intro{align-items:flex-start}.nr-fan-gauge{flex-basis:104px;width:104px;height:104px}.nr-fan-gauge-value strong{font-size:26px}.nr-fan-copy h3{font-size:19px}.nr-fan-live{grid-template-columns:1fr}.cbi-value{grid-template-columns:1fr;gap:9px;min-height:0;padding:13px!important}.cbi-value-title{padding:0!important}.cbi-value-field{text-align:left!important}.cbi-value-field>select,.cbi-value-field>.cbi-input-text{max-width:none!important;margin-left:0!important}.nr-fan-group-title{display:block}.nr-fan-group-title span{display:block;margin-top:3px;text-align:left}.nr-fan-safety{font-size:10px}}
</style>
<div id="nr-fan-dashboard" class="nr-fan-dashboard" data-enabled="0" data-fan="off">
  <section class="nr-fan-hero" aria-label="风扇实时状态">
    <div>
      <div class="nr-fan-intro">
        <div id="nr-fan-gauge" class="nr-fan-gauge" aria-label="当前温度">
          <div class="nr-fan-gauge-value"><strong id="nr-fan-temp">--</strong><span>temperature</span></div>
        </div>
        <div class="nr-fan-copy">
          <div class="nr-fan-eyebrow">Thermal cockpit</div>
          <h3>智能散热控制</h3>
          <p>实时联动 CPU 与 CPE 温度，按曲线自动调速。配置保存后风扇服务会立即重载。</p>
          <div id="nr-fan-state" class="nr-fan-state" aria-live="polite">正在读取运行状态</div>
        </div>
      </div>
      <div class="nr-fan-safety"><span class="nr-fan-safety-mark">◆</span><span><b>安全优先：</b>达到过热保护温度时强制 100% 风速，不受手动模式和静音时段限制。</span></div>
    </div>
    <div class="nr-fan-live">
      <div class="nr-fan-metric">
        <span class="nr-fan-metric-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><g class="nr-fan-rotor"><path d="M12 10.2c-1.6-2.5-.9-6.7 1.7-7.2 2.2-.4 3.5 2.2 2.7 4.2-.7 1.7-2.4 2.7-4.4 3Z"/><path d="M13.8 12c2.5-1.6 6.7-.9 7.2 1.7.4 2.2-2.2 3.5-4.2 2.7-1.7-.7-2.7-2.4-3-4.4Z"/><path d="M12 13.8c1.6 2.5.9 6.7-1.7 7.2-2.2.4-3.5-2.2-2.7-4.2.7-1.7 2.4-2.7 4.4-3Z"/><path d="M10.2 12c-2.5 1.6-6.7.9-7.2-1.7-.4-2.2 2.2-3.5 4.2-2.7 1.7.7 2.7 2.4 3 4.4Z"/></g><circle cx="12" cy="12" r="1.8"/></svg></span>
        <div class="nr-fan-metric-copy"><span>Fan output</span><strong id="nr-fan-speed">--</strong></div>
      </div>
      <div class="nr-fan-metric"><span class="nr-fan-metric-icon" aria-hidden="true">◈</span><div class="nr-fan-metric-copy"><span>Active mode</span><strong id="nr-fan-mode">--</strong></div></div>
      <div class="nr-fan-metric"><span class="nr-fan-metric-icon" aria-hidden="true">◎</span><div class="nr-fan-metric-copy"><span>Temperature source</span><strong id="nr-fan-source">--</strong></div></div>
      <div class="nr-fan-metric"><span class="nr-fan-metric-icon" aria-hidden="true">◷</span><div class="nr-fan-metric-copy"><span>Quiet schedule</span><strong id="nr-fan-schedule">--</strong></div></div>
    </div>
  </section>
</div>
<script type="text/javascript">//<![CDATA[
(function(){
  function nrFanText(id,value){var el=document.getElementById(id);if(el)el.textContent=value;}
  function nrFanGroup(beforeId,title,description){
    var target=document.getElementById(beforeId);
    if(!target||document.getElementById(beforeId+'-group'))return;
    var node=document.createElement('div');
    node.id=beforeId+'-group';node.className='nr-fan-group-title';
    node.innerHTML='<strong>'+title+'</strong><span>'+description+'</span>';
    target.parentNode.insertBefore(node,target);
  }
  function nrFanLayout(){
    var dashboard=document.getElementById('nr-fan-dashboard');
    var map=document.querySelector('.cbi-map');
    var heading=map&&map.querySelector('h2');
    if(dashboard&&map&&dashboard.parentNode!==map){
      if(heading&&heading.nextSibling)map.insertBefore(dashboard,heading.nextSibling);else map.insertBefore(dashboard,map.firstChild);
    }
    nrFanGroup('cbi-fanctrl-fanctrl-enabled','运行控制','总开关、模式、温度来源、保护阈值与检测周期');
    nrFanGroup('cbi-fanctrl-fanctrl-smartmin','Smart 温控曲线','从最低风速到 100% 的四段升温曲线');
    nrFanGroup('cbi-fanctrl-fanctrl-schedule_enabled','静音时段','跨午夜时间段可临时切换到更安静的运行模式');
  }
  window.nradioFanDashboardUpdate=function(data){
    data=data||{};
    var dashboard=document.getElementById('nr-fan-dashboard');
    var gauge=document.getElementById('nr-fan-gauge');
    if(!dashboard||!gauge)return;
    var enabled=String(data.enabled||'0')==='1';
    var temp=parseInt(data.temp,10);if(!isFinite(temp))temp=0;
    var fan=parseInt(data.fan,10);if(!isFinite(fan))fan=0;
    var color=temp>=75?'var(--nr-fan-hot)':(temp>=60?'var(--nr-fan-warm)':'var(--nr-fan-cyan)');
    gauge.style.setProperty('--nr-temp-angle',(Math.max(0,Math.min(100,temp))*3.6)+'deg');
    gauge.style.setProperty('--nr-temp-color',color);
    nrFanText('nr-fan-temp',temp>0?(temp+'°C'):'--');
    nrFanText('nr-fan-speed',enabled?(fan>0?fan+'%':'关闭'):'已关闭');
    nrFanText('nr-fan-mode',enabled?(data.mode_label||'Smart 智能温控'):'停止');
    nrFanText('nr-fan-source',data.temp_source_label||'--');
    var schedule=String(data.schedule_enabled||'0')==='1';
    var active=String(data.schedule_active||'0')==='1';
    nrFanText('nr-fan-schedule',schedule?((active?'生效中 · ':'已启用 · ')+(data.schedule_start||'--')+'–'+(data.schedule_end||'--')):'未启用');
    nrFanText('nr-fan-state',enabled?('风扇服务运行中 · '+(data.mode_label||'Smart')):'风扇控制已关闭');
    dashboard.setAttribute('data-enabled',enabled?'1':'0');
    dashboard.setAttribute('data-fan',enabled&&fan>0?'on':'off');
    var rotor=dashboard.querySelector('.nr-fan-rotor');
    if(rotor)rotor.style.animationDuration=Math.max(.5,2.7-(fan/100)*2.1)+'s';
  };
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',nrFanLayout);else nrFanLayout();
  window.setTimeout(nrFanLayout,100);
}());
//]]></script>
EOF_FANCTRL_POLISH

    cat > "$FANCTRL_TEMP_AJAX_VIEW" <<'EOF_FANCTRL_TEMP_AJAX'
<%+cbi/valueheader%>

<script type="text/javascript">//<![CDATA[
	function update_fanctrl_value(id, value) {
		var s = document.getElementById(id);
		if (s) s.innerHTML = value;
	}

	XHR.poll(5, '<%=url('nradioadv/system/fanctrl/temperature')%>', null,
		function(x, rv)
		{
			if (!(rv && rv.result))
				return;

			var temp = rv.result.temp || '';
			var fan = rv.result.fan || '0';
			var mode = rv.result.mode || '4';
			var modeLabel = rv.result.mode_label || 'Smart';
			var enabled = rv.result.enabled || '0';
			var sourceLabel = rv.result.temp_source_label || '';

			var tempLabel = temp ? (temp + ' °C' + (sourceLabel ? (' / ' + sourceLabel) : '')) : '<em>暂无数据</em>';
			var fanLabel = '关闭';

			if (enabled === '1') {
				if (fan === '0')
					fanLabel = '关闭';
				else
					fanLabel = fan + '% / ' + modeLabel;
			}

			update_fanctrl_value('tempdesdevice-temperature-status', tempLabel);
			update_fanctrl_value('fandesdevice-temperature-status', fanLabel);
			if (typeof window.nradioFanDashboardUpdate === 'function')
				window.nradioFanDashboardUpdate(rv.result);
		}
	);

	$("#cbi-fanctrl-fanctrl-tempdes").css("display", "none");
	$("#cbi-fanctrl-fanctrl-tempdesdevice").css("display", "none");
	$("#cbi-fanctrl-fanctrl-fandesdevice").css("display", "none");
	$("#cbi-fanctrl-fanctrl-tempdesmodel").css("display", "none");
//]]></script>
<%+cbi/valuefooter%>
EOF_FANCTRL_TEMP_AJAX

    cat > "$FANCTRL_TEMP_VIEW" <<'EOF_FANCTRL_TEMP'
<%+cbi/valueheader%>
<style>
  #<%=self.option%>-temperature-status{margin-top: 7px;display: block;}
</style>
<span id="<%=self.option%>-temperature-status"><em><%:Collecting data...%></em></span>
<%+cbi/valuefooter%>
EOF_FANCTRL_TEMP

    cat > "$FANCTRL_BIN_PATH" <<'EOF_FANCTRL_SERVICE'
#!/bin/ash
. /lib/functions.sh
. /usr/share/libubox/jshn.sh

GPIO_FAN="/sys/class/gpio/fan-hw/value"
PWM_FAN="/sys/devices/platform/pwm-fan/hwmon/hwmon0/pwm1"
DEFAULT_WAIT=12

set_pwm_by_percent() {
    case "$1" in
        0) echo 0 ;;
        30) echo 76 ;;
        50) echo 127 ;;
        80) echo 204 ;;
        100) echo 255 ;;
        *) echo 0 ;;
    esac
}

get_fan_percent() {
    cur="$(cat "$PWM_FAN" 2>/dev/null || echo 0)"
    case "$cur" in
        0) echo 0 ;;
        76) echo 30 ;;
        127) echo 50 ;;
        204) echo 80 ;;
        255) echo 100 ;;
        *) echo 0 ;;
    esac
}

get_cpu_temp() {
    awk '{printf "%d", $1/1000}' /sys/class/thermal/thermal_zone0/temp 2>/dev/null || echo 0
}

get_model_temp() {
    cur="$(/etc/cpetools/quectel.sh -c temp 2>/dev/null || true)"
    echo "$cur" | grep -qE '^[0-9]+$' && echo "$cur" || true
}

is_uint() {
    echo "$1" | grep -qE '^[0-9]+$'
}

process_starttime() {
    local _pid="$1"
    is_uint "$_pid" || return 1
    [ -r "/proc/$_pid/stat" ] || return 1
    sed 's/^[^)]*) //' "/proc/$_pid/stat" 2>/dev/null | awk '{print $20}'
}

ensure_runtime_dir() {
    [ ! -L "$RUNTIME_DIR" ] || return 1
    if [ -e "$RUNTIME_DIR" ] && [ ! -d "$RUNTIME_DIR" ]; then return 1; fi
    mkdir -p "$RUNTIME_DIR" || return 1
    chmod 700 "$RUNTIME_DIR" || return 1
    for _runtime_path in "$STATE_FILE" "$PREFERENCE_STATE_FILE" "$RUNTIME_LOG"; do
        [ ! -L "$_runtime_path" ] || return 1
        if [ -e "$_runtime_path" ] && [ ! -f "$_runtime_path" ]; then return 1; fi
    done
    (umask 077; : >> "$RUNTIME_LOG") || return 1
    chmod 600 "$RUNTIME_LOG" || return 1
}

safe_uint() {
    value="$1"
    fallback="$2"
    if is_uint "$value"; then
        echo "$value"
    else
        echo "$fallback"
    fi
}

get_drive_temp() {
    source="$1"
    cpu_temp="$(get_cpu_temp)"
    model_temp="$(get_model_temp)"

    case "$source" in
        cpu)
            echo "${cpu_temp:-0}"
            ;;
        cpe)
            if [ -n "$model_temp" ]; then
                echo "$model_temp"
            else
                echo "${cpu_temp:-0}"
            fi
            ;;
        *)
            if [ -n "$model_temp" ] && [ "$model_temp" -gt "${cpu_temp:-0}" ]; then
                echo "$model_temp"
            else
                echo "${cpu_temp:-0}"
            fi
            ;;
    esac
}

disable_fan() {
    echo 0 > "$GPIO_FAN" 2>/dev/null || true
    echo 0 > "$PWM_FAN" 2>/dev/null || true
}

enable_fan() {
    percent="$1"
    pwm="$(set_pwm_by_percent "$percent")"
    echo 1 > "$GPIO_FAN" 2>/dev/null || true
    echo "$pwm" > "$PWM_FAN" 2>/dev/null || true
}

smart_percent() {
    temp="$1"
    smart_min="$2"
    smart_low="$3"
    smart_mid="$4"
    smart_high="$5"
    smart_full="$6"
    percent=0

    [ -n "$smart_min" ] || smart_min=30
    [ -n "$smart_low" ] || smart_low=50
    [ -n "$smart_mid" ] || smart_mid=60
    [ -n "$smart_high" ] || smart_high=70
    [ -n "$smart_full" ] || smart_full=80

    case "$smart_min" in
        0|30|50) ;;
        *) smart_min=30 ;;
    esac

    if [ "$temp" -ge "$smart_full" ]; then
        percent=100
    elif [ "$temp" -ge "$smart_high" ]; then
        percent=80
    elif [ "$temp" -ge "$smart_mid" ]; then
        percent=50
    elif [ "$temp" -ge "$smart_low" ]; then
        percent=30
    else
        percent="$smart_min"
    fi

    if [ "$percent" -lt "$smart_min" ]; then
        percent="$smart_min"
    fi
    echo "$percent"
}

report_state() {
    cpu_temp="$(get_cpu_temp)"
    model_temp="$(get_model_temp)"
    fan_percent="$(get_fan_percent)"
    ubus call infocdp passthrough "{'name':'temperature','parameter':{'device':'$cpu_temp','cpe':'$model_temp','fan':'$fan_percent'}}" >/dev/null 2>&1 || true
}

normalize_time_part() {
    part="$1"
    part="$(printf '%s\n' "$part" | sed 's/^0*//')"
    [ -n "$part" ] || part=0
    echo "$part"
}

is_hhmm() {
    value="$1"
    echo "$value" | grep -qE '^[0-9][0-9]:[0-9][0-9]$' || return 1
    hour="$(normalize_time_part "${value%:*}")"
    minute="$(normalize_time_part "${value#*:}")"
    is_uint "$hour" || return 1
    is_uint "$minute" || return 1
    [ "$hour" -le 23 ] || return 1
    [ "$minute" -le 59 ] || return 1
}

hhmm_minutes() {
    value="$1"
    is_hhmm "$value" || return 1
    hour="$(normalize_time_part "${value%:*}")"
    minute="$(normalize_time_part "${value#*:}")"
    echo $((hour * 60 + minute))
}

system_time_reliable() {
    year="$(date +%Y 2>/dev/null || echo 0)"
    is_uint "$year" || return 1
    [ "$year" -ge 2024 ]
}

schedule_is_active() {
    start_time="$1"
    end_time="$2"

    system_time_reliable || return 1
    start_min="$(hhmm_minutes "$start_time" 2>/dev/null || true)"
    end_min="$(hhmm_minutes "$end_time" 2>/dev/null || true)"
    [ -n "$start_min" ] || return 1
    [ -n "$end_min" ] || return 1
    [ "$start_min" != "$end_min" ] || return 1

    now_hour="$(normalize_time_part "$(date +%H 2>/dev/null || echo 0)")"
    now_minute="$(normalize_time_part "$(date +%M 2>/dev/null || echo 0)")"
    is_uint "$now_hour" || return 1
    is_uint "$now_minute" || return 1
    now_min=$((now_hour * 60 + now_minute))

    if [ "$start_min" -lt "$end_min" ]; then
        [ "$now_min" -ge "$start_min" ] && [ "$now_min" -lt "$end_min" ]
        return $?
    fi

    [ "$now_min" -ge "$start_min" ] || [ "$now_min" -lt "$end_min" ]
}

while true; do
    enabled="$(uci -q get fanctrl.fanctrl.enabled 2>/dev/null || echo 1)"
    mode="$(uci -q get fanctrl.fanctrl.mode 2>/dev/null || echo 4)"
    tempsource="$(uci -q get fanctrl.fanctrl.tempsource 2>/dev/null || echo max)"
    smartmin="$(uci -q get fanctrl.fanctrl.smartmin 2>/dev/null || echo 30)"
    smarttemp_low="$(uci -q get fanctrl.fanctrl.smarttemp_low 2>/dev/null || echo 50)"
    smarttemp_mid="$(uci -q get fanctrl.fanctrl.smarttemp_mid 2>/dev/null || echo 60)"
    smarttemp_high="$(uci -q get fanctrl.fanctrl.smarttemp_high 2>/dev/null || echo 70)"
    smarttemp_full="$(uci -q get fanctrl.fanctrl.smarttemp_full 2>/dev/null || echo 80)"
    protecttemp="$(uci -q get fanctrl.fanctrl.protecttemp 2>/dev/null || echo 85)"
    wait_time="$(uci -q get fanctrl.fanctrl.interval 2>/dev/null || echo "$DEFAULT_WAIT")"
    schedule_enabled="$(uci -q get fanctrl.fanctrl.schedule_enabled 2>/dev/null || echo 0)"
    schedule_start="$(uci -q get fanctrl.fanctrl.schedule_start 2>/dev/null || echo 23:00)"
    schedule_end="$(uci -q get fanctrl.fanctrl.schedule_end 2>/dev/null || echo 07:00)"
    schedule_mode="$(uci -q get fanctrl.fanctrl.schedule_mode 2>/dev/null || echo 1)"

    smarttemp_low="$(safe_uint "$smarttemp_low" 50)"
    smarttemp_mid="$(safe_uint "$smarttemp_mid" 60)"
    smarttemp_high="$(safe_uint "$smarttemp_high" 70)"
    smarttemp_full="$(safe_uint "$smarttemp_full" 80)"
    protecttemp="$(safe_uint "$protecttemp" 85)"

    case "$wait_time" in
        5|10|12|15|30) ;;
        *) wait_time="$DEFAULT_WAIT" ;;
    esac

    case "$mode" in
        0|1|2|3|4) ;;
        *) mode=4 ;;
    esac

    case "$schedule_mode" in
        0|1|2|3|4) ;;
        *) schedule_mode=1 ;;
    esac

    [ "$smarttemp_mid" -ge "$smarttemp_low" ] || smarttemp_mid="$smarttemp_low"
    [ "$smarttemp_high" -ge "$smarttemp_mid" ] || smarttemp_high="$smarttemp_mid"
    [ "$smarttemp_full" -ge "$smarttemp_high" ] || smarttemp_full="$smarttemp_high"

    if [ "$enabled" != "1" ]; then
        disable_fan
        report_state
        sleep "$wait_time"
        continue
    fi

    current_temp="$(get_drive_temp "$tempsource")"
    [ -n "$current_temp" ] || current_temp=0

    if [ "$current_temp" -ge "$protecttemp" ]; then
        enable_fan 100
        report_state
        sleep "$wait_time"
        continue
    fi

    if [ "$schedule_enabled" = "1" ] && schedule_is_active "$schedule_start" "$schedule_end"; then
        mode="$schedule_mode"
    fi

    case "$mode" in
        0) disable_fan ;;
        1) enable_fan 30 ;;
        2) enable_fan 50 ;;
        3) enable_fan 80 ;;
        4) enable_fan "$(smart_percent "$current_temp" "$smartmin" "$smarttemp_low" "$smarttemp_mid" "$smarttemp_high" "$smarttemp_full")" ;;
        *) enable_fan 50 ;;
    esac

    report_state
    sleep "$wait_time"
done
EOF_FANCTRL_SERVICE

    cat > "$FANCTRL_INIT_FILE" <<'EOF_FANCTRL_INIT'
#!/bin/sh /etc/rc.common
START=95
STOP=10
USE_PROCD=1

start_service() {
    procd_open_instance
    procd_set_param command /usr/bin/fanctrl.sh
    procd_set_param respawn
    procd_close_instance
}
EOF_FANCTRL_INIT

    if [ ! -s "$FANCTRL_CONFIG_FILE" ]; then
        cat > "$FANCTRL_CONFIG_FILE" <<EOF_FANCTRL_UCI
config service 'fanctrl'
    option enabled '1'
    option mode '4'
    option tempsource '$fanctrl_tempsource'
    option smartmin '$fanctrl_smartmin'
    option smarttemp_low '$fanctrl_smarttemp_low'
    option smarttemp_mid '$fanctrl_smarttemp_mid'
    option smarttemp_high '$fanctrl_smarttemp_high'
    option smarttemp_full '$fanctrl_smarttemp_full'
    option protecttemp '$fanctrl_protecttemp'
    option interval '$fanctrl_interval'
    option schedule_enabled '0'
    option schedule_start '23:00'
    option schedule_end '07:00'
    option schedule_mode '1'
EOF_FANCTRL_UCI
    else
        # Preserve every existing choice on update; only backfill fields absent from old firmware.
        uci -q get fanctrl.fanctrl >/dev/null 2>&1 || uci -q set fanctrl.fanctrl='service'
        uci -q get fanctrl.fanctrl.enabled >/dev/null 2>&1 || uci -q set fanctrl.fanctrl.enabled='1'
        uci -q get fanctrl.fanctrl.mode >/dev/null 2>&1 || uci -q set fanctrl.fanctrl.mode='4'
        uci -q get fanctrl.fanctrl.tempsource >/dev/null 2>&1 || uci -q set fanctrl.fanctrl.tempsource="$fanctrl_tempsource"
        uci -q get fanctrl.fanctrl.smartmin >/dev/null 2>&1 || uci -q set fanctrl.fanctrl.smartmin="$fanctrl_smartmin"
        uci -q get fanctrl.fanctrl.smarttemp_low >/dev/null 2>&1 || uci -q set fanctrl.fanctrl.smarttemp_low="$fanctrl_smarttemp_low"
        uci -q get fanctrl.fanctrl.smarttemp_mid >/dev/null 2>&1 || uci -q set fanctrl.fanctrl.smarttemp_mid="$fanctrl_smarttemp_mid"
        uci -q get fanctrl.fanctrl.smarttemp_high >/dev/null 2>&1 || uci -q set fanctrl.fanctrl.smarttemp_high="$fanctrl_smarttemp_high"
        uci -q get fanctrl.fanctrl.smarttemp_full >/dev/null 2>&1 || uci -q set fanctrl.fanctrl.smarttemp_full="$fanctrl_smarttemp_full"
        uci -q get fanctrl.fanctrl.protecttemp >/dev/null 2>&1 || uci -q set fanctrl.fanctrl.protecttemp="$fanctrl_protecttemp"
        uci -q get fanctrl.fanctrl.interval >/dev/null 2>&1 || uci -q set fanctrl.fanctrl.interval="$fanctrl_interval"
        uci -q get fanctrl.fanctrl.schedule_enabled >/dev/null 2>&1 || uci -q set fanctrl.fanctrl.schedule_enabled='0'
        uci -q get fanctrl.fanctrl.schedule_start >/dev/null 2>&1 || uci -q set fanctrl.fanctrl.schedule_start='23:00'
        uci -q get fanctrl.fanctrl.schedule_end >/dev/null 2>&1 || uci -q set fanctrl.fanctrl.schedule_end='07:00'
        uci -q get fanctrl.fanctrl.schedule_mode >/dev/null 2>&1 || uci -q set fanctrl.fanctrl.schedule_mode='1'
        if [ "$fanctrl_model" = 'NRadio_C8-788' ] && [ "$fanctrl_legacy_mode" = '1' ]; then
            uci -q set fanctrl.fanctrl.mode='4'
        fi
        uci -q commit fanctrl
    fi

    chmod 644 "$FANCTRL_CONTROLLER" "$FANCTRL_CBI" "$FANCTRL_TEMP_AJAX_VIEW" "$FANCTRL_TEMP_VIEW"
    chmod 644 "$fanctrl_polish_view" "$FANCTRL_CONFIG_FILE"
    chmod 755 "$FANCTRL_BIN_PATH" "$FANCTRL_INIT_FILE"
}

install_fanctrl() {
    local raw_model raw_board raw_compat current_model fanctrl_icon_name

    require_nradio_oem_appcenter
    raw_model="$(detect_board_model_raw)"
    raw_board="$(detect_board_name_raw)"
    raw_compat="$(detect_board_compatible_raw)"
    current_model="$(normalize_nradio_model "$raw_model" "$raw_board" "$raw_compat")"
    case "$current_model" in
        NRadio_C8-688|NRadio_C2000MAX|NRadio_C8-788)
            ;;
        *)
            log "提示: 当前机型不支持增强风扇控制。"
            log "当前机型: ${current_model:-unknown}"
            log "原始识别: model=${raw_model:-unknown} board_name=${raw_board:-unknown}"
            printf '按回车返回上一级菜单...'
            ui_read_line >/dev/null 2>&1 || true
            return 0
            ;;
    esac

    log_stage 1 5 "NRadio 增强风扇控制页面安装规划"
    log "提示: 当前机型已识别为 ${current_model}，将增强“更多-风扇”页面并保留现有风扇配置"
    case "$current_model" in
        NRadio_C8-688)
            log "适配: C8-688 使用 CPU 温度源，Smart 最低 50%，10s 检测，85°C 过热保护"
            ;;
        NRadio_C2000MAX)
            log "适配: C2000MAX 使用 CPU/CPE 取高值，Smart 最低 30%，5s 检测，80°C 过热保护"
            ;;
        NRadio_C8-788)
            log "适配: C8-788 使用 soc_thermal，12s 检测，65/75/80/85°C 分级调速"
            ;;
    esac
    confirm_or_exit "确认继续安装 ${FANCTRL_DISPLAY_NAME} 并修改系统吗？"

    log_stage 2 5 "写入增强风扇控制页面与后台脚本"
    write_fanctrl_plugin_files "$current_model"

    log_stage 3 5 "启用风扇控制服务并写入缺失配置"
    case "$current_model" in
        NRadio_C8-688)
            log "启用适配: C8-688 风扇策略已写入 fanctrl 配置"
            ;;
        NRadio_C2000MAX)
            log "启用适配: C2000MAX 风扇策略已写入 fanctrl 配置"
            ;;
        NRadio_C8-788)
            log "启用适配: C8-788 soc_thermal 风扇策略已写入 fanctrl 配置"
            ;;
    esac
    enable_init_service_strict "$FANCTRL_INIT_FILE" "$FANCTRL_DISPLAY_NAME" || die "$FANCTRL_DISPLAY_NAME 开机启动配置失败"
    restart_init_service_strict "$FANCTRL_INIT_FILE" "$FANCTRL_DISPLAY_NAME" || die "$FANCTRL_DISPLAY_NAME 启动失败"
    sleep 1
    pgrep -f '/usr/bin/fanctrl.sh' >/dev/null 2>&1 || die "$FANCTRL_DISPLAY_NAME 启动后未发现运行进程"

    log_stage 4 5 "刷新原厂更多-风扇入口"
    backup_file "$CFG"
    cleanup_appcenter_entry "$FANCTRL_DISPLAY_NAME" "$FANCTRL_PACKAGE_NAME" "$FANCTRL_ROUTE"
    rm -f /tmp/appcenter/luci/nradioadv.system.fanctrl 2>/dev/null || true
    refresh_luci_appcenter
    /etc/init.d/uhttpd reload >/dev/null 2>&1 || true

    log_stage 5 5 "校验原厂更多-风扇页面"
    verify_file_exists "$FANCTRL_CONTROLLER" "$FANCTRL_DISPLAY_NAME"
    verify_file_exists "$FANCTRL_CBI" "$FANCTRL_DISPLAY_NAME"
    verify_file_exists "$FANCTRL_VIEW_DIR/polish.htm" "$FANCTRL_DISPLAY_NAME 页面美化"
    verify_file_exists "$FANCTRL_BIN_PATH" "$FANCTRL_DISPLAY_NAME"
    verify_file_exists "$FANCTRL_INIT_FILE" "$FANCTRL_DISPLAY_NAME"
    verify_file_exists "$FANCTRL_CONFIG_FILE" "$FANCTRL_DISPLAY_NAME"
    grep -Fq 'NRadio FanControl cockpit visual layer v2' "$FANCTRL_VIEW_DIR/polish.htm" || die "$FANCTRL_DISPLAY_NAME 页面视觉层校验失败"
    grep -Fq 'window.nradioFanDashboardUpdate(rv.result)' "$FANCTRL_TEMP_AJAX_VIEW" || die "$FANCTRL_DISPLAY_NAME 实时联动校验失败"
    grep -Fq 'schedule_enabled = s:option' "$FANCTRL_CBI" || die "$FANCTRL_DISPLAY_NAME 完整控制项校验失败"
    verify_luci_route "$FANCTRL_ROUTE" "$FANCTRL_DISPLAY_NAME"

    log "安装完成"
    log "插件:   $FANCTRL_DISPLAY_NAME"
    log "版本:   builtin"
    log "路由:   $FANCTRL_ROUTE"
    log "说明:   支持 NRadio_C8-688 / NRadio_C2000MAX / NRadio_C8-788；已启用响应式仪表盘、完整控制项与实时状态联动"
}

load_easytier_route_state() {
    ET_ROUTE_VIRTUAL_IP=''
    ET_ROUTE_LOCAL_SUBNET=''
    ET_ROUTE_REMOTE_SUBNET=''
    ET_ROUTE_LAN_IF=''
    ET_ROUTE_TUN_IF=''
    if [ -f "$EASYTIER_ROUTE_STATE_FILE" ]; then
        if ! state_file_is_v2 "$EASYTIER_ROUTE_STATE_FILE" || ! . "$EASYTIER_ROUTE_STATE_FILE" 2>/dev/null; then
            rm -f "$EASYTIER_ROUTE_STATE_FILE"
            ET_ROUTE_VIRTUAL_IP=''
            ET_ROUTE_LOCAL_SUBNET=''
            ET_ROUTE_REMOTE_SUBNET=''
            ET_ROUTE_LAN_IF=''
            ET_ROUTE_TUN_IF=''
        fi
    fi
}

save_easytier_route_state() {
    ensure_state_dir
    {
        printf '%s\n' "NRADIO_STATE_FORMAT='2'"
        printf 'ET_ROUTE_VIRTUAL_IP=%s\n' "$(shell_quote "${ET_ROUTE_VIRTUAL_IP:-}")"
        printf 'ET_ROUTE_LOCAL_SUBNET=%s\n' "$(shell_quote "${ET_ROUTE_LOCAL_SUBNET:-}")"
        printf 'ET_ROUTE_REMOTE_SUBNET=%s\n' "$(shell_quote "${ET_ROUTE_REMOTE_SUBNET:-}")"
        printf 'ET_ROUTE_LAN_IF=%s\n' "$(shell_quote "${ET_ROUTE_LAN_IF:-}")"
        printf 'ET_ROUTE_TUN_IF=%s\n' "$(shell_quote "${ET_ROUTE_TUN_IF:-}")"
    } > "$EASYTIER_ROUTE_STATE_FILE"
    chmod 600 "$EASYTIER_ROUTE_STATE_FILE" 2>/dev/null || true
}

cleanup_easytier_route_runtime_state() {
    local route_local_subnet="${1:-}"
    local route_remote_subnet="${2:-}"
    local route_lan_if="${3:-br-lan}"
    local route_tun_if="${4:-tun0}"

    [ -n "$route_local_subnet" ] || return 0
    [ -n "$route_remote_subnet" ] || return 0

    ip route del "$route_remote_subnet" 2>/dev/null || true
    ip rule del to "$route_remote_subnet" lookup main priority 60 2>/dev/null || true
    ip rule del iif "$route_lan_if" to "$route_remote_subnet" lookup main priority 70 2>/dev/null || true
    ip rule del from "$route_local_subnet" to "$route_remote_subnet" lookup main priority 196 2>/dev/null || true

    command -v iptables >/dev/null 2>&1 || return 0
    while iptables -t nat -C POSTROUTING -s "$route_local_subnet" -d "$route_remote_subnet" -o "$route_tun_if" -j MASQUERADE >/dev/null 2>&1; do
        iptables -t nat -D POSTROUTING -s "$route_local_subnet" -d "$route_remote_subnet" -o "$route_tun_if" -j MASQUERADE >/dev/null 2>&1 || break
    done
    while iptables -t filter -C FORWARD -s "$route_remote_subnet" -d "$route_local_subnet" -i "$route_tun_if" -o "$route_lan_if" -j ACCEPT >/dev/null 2>&1; do
        iptables -t filter -D FORWARD -s "$route_remote_subnet" -d "$route_local_subnet" -i "$route_tun_if" -o "$route_lan_if" -j ACCEPT >/dev/null 2>&1 || break
    done
    while iptables -t filter -C FORWARD -d "$route_remote_subnet" -i "$route_lan_if" -o "$route_tun_if" -j ACCEPT >/dev/null 2>&1; do
        iptables -t filter -D FORWARD -d "$route_remote_subnet" -i "$route_lan_if" -o "$route_tun_if" -j ACCEPT >/dev/null 2>&1 || break
    done
}

cleanup_easytier_route_rc_hook() {
    local rc_local="/etc/rc.local"
    local rc_tmp="$WORKDIR/rc.local.easytier.cleanup"

    [ -f "$rc_local" ] || return 0
    grep -q 'EASYTIER_ROUTE_WIZARD_BEGIN' "$rc_local" 2>/dev/null || return 0

    backup_file "$rc_local"
    awk '
        BEGIN { skip = 0 }
        /^# EASYTIER_ROUTE_WIZARD_BEGIN$/ { skip = 1; next }
        /^# EASYTIER_ROUTE_WIZARD_END$/ { skip = 0; next }
        skip { next }
        { print }
    ' "$rc_local" > "$rc_tmp" && mv "$rc_tmp" "$rc_local"
    chmod 755 "$rc_local" 2>/dev/null || true
}

write_easytier_route_config() {
    route_virtual_ip="$1"
    route_local_subnet="$2"
    route_old_local_subnet="${3:-}"
    tmp_cfg="$WORKDIR/easytier-config.toml"

    awk -v new_ipv4="$route_virtual_ip" -v new_lan="$route_local_subnet" -v old_lan="$route_old_local_subnet" '
        function print_proxy_block() {
            print "[[proxy_network]]"
            print "cidr = \"" new_lan "\""
            print ""
            inserted_proxy = 1
            seen_target_proxy = 1
        }
        function ensure_root_ipv4() {
            if (!inserted_ipv4) {
                print "ipv4 = \"" new_ipv4 "\""
                print ""
                inserted_ipv4 = 1
            }
        }
        function flush_proxy_block(    drop_block) {
            if (!in_proxy)
                return

            drop_block = 0
            if (proxy_cidr == new_lan)
                seen_target_proxy = 1
            if (old_lan != "" && old_lan != new_lan && proxy_cidr == old_lan)
                drop_block = 1

            if (!drop_block)
                printf "%s", proxy_block

            in_proxy = 0
            proxy_block = ""
            proxy_cidr = ""
        }
        BEGIN {
            inserted_proxy = 0
            seen_target_proxy = 0
            seen_flags = 0
            inserted_ipv4 = 0
            in_proxy = 0
            proxy_block = ""
            proxy_cidr = ""
        }
        {
            line = $0
            if (in_proxy) {
                if (line ~ /^\[\[proxy_network\]\]/ || line ~ /^\[/) {
                    flush_proxy_block()
                } else {
                    proxy_block = proxy_block line ORS
                    if (line ~ /^[[:space:]]*cidr[[:space:]]*=[[:space:]]*"/) {
                        proxy_cidr = line
                        sub(/^[^"]*"/, "", proxy_cidr)
                        sub(/".*$/, "", proxy_cidr)
                    }
                    next
                }
            }
            if (line ~ /^ipv4 = "/) {
                print "ipv4 = \"" new_ipv4 "\""
                inserted_ipv4 = 1
                next
            }
            if (line ~ /^\[\[proxy_network\]\]/) {
                if (!inserted_ipv4)
                    ensure_root_ipv4()
                in_proxy = 1
                proxy_block = line ORS
                proxy_cidr = ""
                next
            }
            if (line ~ /^proxy_networks = /) next
            if (line ~ /^\[/ && !inserted_ipv4)
                ensure_root_ipv4()
            if (line ~ /^\[flags\]/) {
                if (!seen_target_proxy && !inserted_proxy) print_proxy_block()
                print line
                print "proxy_forward_by_system = true"
                seen_flags = 1
                next
            }
            if (line ~ /^proxy_forward_by_system = /) next
            print line
        }
        END {
            flush_proxy_block()
            if (!inserted_ipv4)
                ensure_root_ipv4()
            if (!seen_flags) {
                if (!seen_target_proxy && !inserted_proxy) print_proxy_block()
                print "[flags]"
                print "proxy_forward_by_system = true"
            } else if (!seen_target_proxy && !inserted_proxy) {
                print_proxy_block()
            }
        }
    ' "$EASYTIER_CONFIG_FILE" > "$tmp_cfg"

    easytier-core --check-config -c "$tmp_cfg" >/dev/null 2>&1 || die 'EasyTier 配置写入后校验失败'
    backup_file "$EASYTIER_CONFIG_FILE"
    mv "$tmp_cfg" "$EASYTIER_CONFIG_FILE"
}

write_easytier_route_apply_script() {
    mkdir -p "$(dirname "$EASYTIER_ROUTE_APPLY_SCRIPT")"
    backup_file "$EASYTIER_ROUTE_APPLY_SCRIPT"

    cat > "$EASYTIER_ROUTE_APPLY_SCRIPT" <<EOF_EASYTIER_ROUTE_APPLY
#!/bin/sh
set -eu

STATE_FILE='$EASYTIER_ROUTE_STATE_FILE'

log() { printf '%s\n' "\$*"; }
die() { printf 'ERROR: %s\n' "\$*" >&2; exit 1; }

[ -f "\$STATE_FILE" ] || die '未找到 EasyTier 路由状态文件'
[ "\$(sed -n '1p' "\$STATE_FILE" 2>/dev/null || true)" = "NRADIO_STATE_FORMAT='2'" ] || die 'EasyTier 路由状态文件格式不安全，请重新运行路由向导'
. "\$STATE_FILE" 2>/dev/null || die '读取 EasyTier 路由状态文件失败'

[ -n "\${ET_ROUTE_REMOTE_SUBNET:-}" ] || die '未找到远端 LAN 网段'
[ -n "\${ET_ROUTE_LOCAL_SUBNET:-}" ] || die '未找到本机 LAN 网段'
[ -n "\${ET_ROUTE_LAN_IF:-}" ] || ET_ROUTE_LAN_IF='br-lan'
[ -n "\${ET_ROUTE_TUN_IF:-}" ] || ET_ROUTE_TUN_IF='tun0'
command -v easytier-cli >/dev/null 2>&1 || die '未检测到 easytier-cli'
command -v ip >/dev/null 2>&1 || die '未检测到 ip 命令'
ip link show "\$ET_ROUTE_LAN_IF" >/dev/null 2>&1 || die "未检测到本地 LAN 接口：\$ET_ROUTE_LAN_IF"
tun_wait=0
until ip link show "\$ET_ROUTE_TUN_IF" >/dev/null 2>&1; do
    [ "\$tun_wait" -lt 60 ] || die "等待 EasyTier 隧道接口超时：\$ET_ROUTE_TUN_IF"
    sleep 1
    tun_wait=\$((tun_wait + 1))
done

parse_peer_virtual_ip() {
    target="\$1"
    easytier-cli route 2>/dev/null | awk -F'|' -v target="\$target" '
        function trim(s) { gsub(/^[[:space:]]+|[[:space:]]+$/, "", s); return s }
        {
            ip = trim(\$2)
            cidr = trim(\$4)
            if (cidr == target) {
                sub(/\/.*/, "", ip)
                print ip
                exit
            }
        }
    '
}

wait_for_peer_route() {
    target="\$1"
    count=0
    while [ "\$count" -lt 30 ]; do
        peer_ip="\$(parse_peer_virtual_ip "\$target" 2>/dev/null || true)"
        if [ -n "\$peer_ip" ]; then
            printf '%s\n' "\$peer_ip"
            return 0
        fi
        sleep 2
        count=\$((count + 1))
    done
    return 1
}

delete_rule_loop() {
    table="\$1"
    chain="\$2"
    shift 2
    command -v iptables >/dev/null 2>&1 || return 0
    while iptables -t "\$table" -C "\$chain" "\$@" >/dev/null 2>&1; do
        iptables -t "\$table" -D "\$chain" "\$@" >/dev/null 2>&1 || break
    done
}

ensure_rule() {
    table="\$1"
    chain="\$2"
    shift 2
    command -v iptables >/dev/null 2>&1 || return 0
    delete_rule_loop "\$table" "\$chain" "\$@"
    iptables -t "\$table" -A "\$chain" "\$@" >/dev/null 2>&1 || die "写入 iptables 规则失败：\$table/\$chain"
}

peer_virtual_ip="\$(wait_for_peer_route "\$ET_ROUTE_REMOTE_SUBNET" 2>/dev/null || true)"
[ -n "\$peer_virtual_ip" ] || die "未找到远端网段 \$ET_ROUTE_REMOTE_SUBNET 对应的 EasyTier 节点"

ip route replace "\$ET_ROUTE_REMOTE_SUBNET" via "\$peer_virtual_ip" dev "\$ET_ROUTE_TUN_IF" 2>/dev/null || die '写入远端网段路由失败'
ip rule del to "\$ET_ROUTE_REMOTE_SUBNET" lookup main priority 60 2>/dev/null || true
ip rule add to "\$ET_ROUTE_REMOTE_SUBNET" lookup main priority 60 2>/dev/null || die '写入 EasyTier 目标策略规则失败'
ip rule del iif "\$ET_ROUTE_LAN_IF" to "\$ET_ROUTE_REMOTE_SUBNET" lookup main priority 70 2>/dev/null || true
ip rule add iif "\$ET_ROUTE_LAN_IF" to "\$ET_ROUTE_REMOTE_SUBNET" lookup main priority 70 2>/dev/null || die '写入 EasyTier LAN 策略规则失败'
ip rule del from "\$ET_ROUTE_LOCAL_SUBNET" to "\$ET_ROUTE_REMOTE_SUBNET" lookup main priority 196 2>/dev/null || true
ip rule add from "\$ET_ROUTE_LOCAL_SUBNET" to "\$ET_ROUTE_REMOTE_SUBNET" lookup main priority 196 2>/dev/null || die '写入 EasyTier来源策略规则失败'

ensure_rule nat POSTROUTING -s "\$ET_ROUTE_LOCAL_SUBNET" -d "\$ET_ROUTE_REMOTE_SUBNET" -o "\$ET_ROUTE_TUN_IF" -j MASQUERADE
ensure_rule filter FORWARD -s "\$ET_ROUTE_REMOTE_SUBNET" -d "\$ET_ROUTE_LOCAL_SUBNET" -i "\$ET_ROUTE_TUN_IF" -o "\$ET_ROUTE_LAN_IF" -j ACCEPT
ensure_rule filter FORWARD -d "\$ET_ROUTE_REMOTE_SUBNET" -i "\$ET_ROUTE_LAN_IF" -o "\$ET_ROUTE_TUN_IF" -j ACCEPT

log "route applied: \$ET_ROUTE_REMOTE_SUBNET via \$peer_virtual_ip dev \$ET_ROUTE_TUN_IF"
EOF_EASYTIER_ROUTE_APPLY

    chmod 755 "$EASYTIER_ROUTE_APPLY_SCRIPT"
    sh -n "$EASYTIER_ROUTE_APPLY_SCRIPT" >/dev/null 2>&1 || die 'generated EasyTier route script has syntax error'
}

install_easytier_route_rc_hook() {
    rc_local="/etc/rc.local"
    rc_tmp="$WORKDIR/rc.local.easytier"

    if [ ! -f "$rc_local" ]; then
        cat > "$rc_local" <<'EOF_EASYTIER_RC_LOCAL'
#!/bin/sh
exit 0
EOF_EASYTIER_RC_LOCAL
        chmod 755 "$rc_local"
    fi

    grep -q 'EASYTIER_ROUTE_WIZARD_BEGIN' "$rc_local" 2>/dev/null && return 0

    backup_file "$rc_local"
    awk -v cmd='[ -x /etc/easytier/route-apply.sh ] && sh /etc/easytier/route-apply.sh >/var/log/easytier-route-apply.log 2>&1 &' '
        BEGIN { inserted = 0 }
        /^exit 0$/ {
            if (!inserted) {
                print "# EASYTIER_ROUTE_WIZARD_BEGIN"
                print cmd
                print "# EASYTIER_ROUTE_WIZARD_END"
                inserted = 1
            }
        }
        { print }
        END {
            if (!inserted) {
                print "# EASYTIER_ROUTE_WIZARD_BEGIN"
                print cmd
                print "# EASYTIER_ROUTE_WIZARD_END"
                print "exit 0"
            }
        }
    ' "$rc_local" > "$rc_tmp" && mv "$rc_tmp" "$rc_local"
    chmod 755 "$rc_local" 2>/dev/null || true
}

wait_easytier_route_publish() {
    route_target="$1"
    wait_count=0
    while [ "$wait_count" -lt 15 ]; do
        easytier-cli node 2>/dev/null | grep -F "$route_target" >/dev/null 2>&1 && return 0
        sleep 2
        wait_count=$((wait_count + 1))
    done
    return 1
}

configure_easytier_routes() {
    local old_route_local_subnet old_route_remote_subnet old_route_lan_if old_route_tun_if

    mkdir -p "$WORKDIR" >/dev/null 2>&1 || die "无法创建临时工作目录：$WORKDIR"
    ensure_state_dir
    [ -f "$EASYTIER_CONFIG_FILE" ] || die '未检测到 /etc/easytier/config.toml，请先安装并配置 EasyTier'
    command -v easytier-core >/dev/null 2>&1 || die '未检测到 easytier-core，请先安装 EasyTier'
    command -v easytier-cli >/dev/null 2>&1 || die '未检测到 easytier-cli，请先安装 EasyTier'
    command -v ip >/dev/null 2>&1 || die '未检测到 ip 命令，请先安装 ip-full 或确认系统环境完整'
    [ -f /etc/init.d/easytier ] || die '未检测到 /etc/init.d/easytier，请先安装 EasyTier'

    load_easytier_route_state
    old_route_local_subnet="${ET_ROUTE_LOCAL_SUBNET:-}"
    old_route_remote_subnet="${ET_ROUTE_REMOTE_SUBNET:-}"
    old_route_lan_if="${ET_ROUTE_LAN_IF:-}"
    old_route_tun_if="${ET_ROUTE_TUN_IF:-}"

    lan_if_default="${ET_ROUTE_LAN_IF:-br-lan}"
    prompt_with_default '本地 LAN 接口' "$lan_if_default"
    ET_ROUTE_LAN_IF="$PROMPT_RESULT"
    case "$ET_ROUTE_LAN_IF" in
        *[[:space:]]*) die 'LAN interface must not contain spaces' ;;
    esac
    ip link show "$ET_ROUTE_LAN_IF" >/dev/null 2>&1 || die "未检测到本地 LAN 接口：$ET_ROUTE_LAN_IF"

    tun_if_default="${ET_ROUTE_TUN_IF:-}"
    if [ -z "$tun_if_default" ]; then
        tun_if_default="$(ip -o link show 2>/dev/null | awk -F': ' '/tun[0-9]+/{print $2; exit}' | sed 's/@.*//')"
    fi
    [ -n "$tun_if_default" ] || tun_if_default='tun0'
    prompt_with_default 'EasyTier 隧道接口名' "$tun_if_default"
    ET_ROUTE_TUN_IF="$PROMPT_RESULT"
    case "$ET_ROUTE_TUN_IF" in
        *[[:space:]]*) die 'EasyTier interface must not contain spaces' ;;
    esac
    if ! ip link show "$ET_ROUTE_TUN_IF" >/dev/null 2>&1; then
        log "提示: 当前尚未检测到 EasyTier 隧道接口 $ET_ROUTE_TUN_IF，将在重启 EasyTier 后继续校验"
    fi

    virtual_default="$ET_ROUTE_VIRTUAL_IP"
    [ -n "$virtual_default" ] || virtual_default="$(sed -n 's/^ipv4 = "\([^\"]*\)"/\1/p' "$EASYTIER_CONFIG_FILE" | sed -n '1p')"
    [ -n "$virtual_default" ] || virtual_default='11.11.11.12/24'
    prompt_with_default 'EasyTier 虚拟 IP（CIDR，例如 11.11.11.12/24）' "$virtual_default"
    ET_ROUTE_VIRTUAL_IP="$(normalize_ipv4_interface_cidr "$PROMPT_RESULT" 2>/dev/null || true)"
    [ -n "$ET_ROUTE_VIRTUAL_IP" ] || die 'EasyTier 虚拟 IP 格式无效'

    local_default="$ET_ROUTE_LOCAL_SUBNET"
    [ -n "$local_default" ] || local_default="$(get_default_lan_subnet 2>/dev/null || true)"
    [ -n "$local_default" ] || local_default='192.168.66.0/24'
    prompt_with_default '本机 LAN 网段（CIDR，例如 192.168.66.0/24）' "$local_default"
    ET_ROUTE_LOCAL_SUBNET="$(normalize_ipv4_cidr "$PROMPT_RESULT" 2>/dev/null || true)"
    [ -n "$ET_ROUTE_LOCAL_SUBNET" ] || die '本机 LAN 网段格式无效'

    remote_default="$ET_ROUTE_REMOTE_SUBNET"
    if [ -z "$remote_default" ]; then
        remote_default="$(easytier-cli route 2>/dev/null | awk -F'|' -v local="$ET_ROUTE_LOCAL_SUBNET" '
            function trim(s) { gsub(/^[[:space:]]+|[[:space:]]+$/, "", s); return s }
            {
                cidr = trim($4)
                if (cidr ~ /^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+\/[0-9]+$/ && cidr != local && cidr != "192.0.0.0/8") {
                    print cidr
                    exit
                }
            }
        ')"
    fi
    [ -n "$remote_default" ] || remote_default='192.168.88.0/24'
    prompt_with_default '远端 LAN 网段（CIDR，例如 192.168.88.0/24）' "$remote_default"
    ET_ROUTE_REMOTE_SUBNET="$(normalize_ipv4_cidr "$PROMPT_RESULT" 2>/dev/null || true)"
    [ -n "$ET_ROUTE_REMOTE_SUBNET" ] || die '远端 LAN 网段格式无效'
    [ "$ET_ROUTE_REMOTE_SUBNET" != "$ET_ROUTE_LOCAL_SUBNET" ] || die '远端 LAN 网段不能与本机 LAN 网段相同'

    log "summary: EasyTier 隧道接口=$ET_ROUTE_TUN_IF"
    log "summary: 本地 LAN 接口=$ET_ROUTE_LAN_IF"
    log "summary: 虚拟 IP=$ET_ROUTE_VIRTUAL_IP"
    log "summary: 本机 LAN 网段=$ET_ROUTE_LOCAL_SUBNET"
    log "summary: 远端 LAN 网段=$ET_ROUTE_REMOTE_SUBNET"
    log 'summary: 将启用 EasyTier 原生子网代理，并写入独立路由脚本'
    confirm_or_exit '确认写入 EasyTier 路由配置并修改系统吗？'

    if [ -n "$old_route_remote_subnet" ] && {
        [ "$old_route_remote_subnet" != "$ET_ROUTE_REMOTE_SUBNET" ] ||
        [ "$old_route_local_subnet" != "$ET_ROUTE_LOCAL_SUBNET" ] ||
        [ "${old_route_lan_if:-br-lan}" != "$ET_ROUTE_LAN_IF" ] ||
        [ "${old_route_tun_if:-tun0}" != "$ET_ROUTE_TUN_IF" ];
    }; then
        cleanup_easytier_route_runtime_state "$old_route_local_subnet" "$old_route_remote_subnet" "$old_route_lan_if" "$old_route_tun_if"
    fi

    write_easytier_route_config "$ET_ROUTE_VIRTUAL_IP" "$ET_ROUTE_LOCAL_SUBNET" "$old_route_local_subnet"
    save_easytier_route_state
    write_easytier_route_apply_script
    install_easytier_route_rc_hook

    if uci -q get firewall.easytierzone >/dev/null 2>&1; then
        uci -q set firewall.easytierzone.masq='0'
        uci -q commit firewall >/dev/null 2>&1 || true
    fi

    /etc/init.d/easytier enable >/dev/null 2>&1 || true
    /etc/init.d/easytier restart >/dev/null 2>&1 || die '重启 EasyTier 失败'
    /etc/init.d/firewall restart >/dev/null 2>&1 || true
    sh "$EASYTIER_ROUTE_APPLY_SCRIPT" >"$WORKDIR/easytier-route-apply.log" 2>&1 || {
        sed -n '1,120p' "$WORKDIR/easytier-route-apply.log" >&2
        die '应用 EasyTier 路由脚本失败'
    }

    ip route | awk -v subnet="$ET_ROUTE_REMOTE_SUBNET" -v tun="$ET_ROUTE_TUN_IF" '
        $1 == subnet && $2 == "via" && $4 == "dev" && $5 == tun { found = 1 }
        END { exit found ? 0 : 1 }
    ' || die "route apply failed: missing $ET_ROUTE_REMOTE_SUBNET dev $ET_ROUTE_TUN_IF"
    wait_easytier_route_publish "$ET_ROUTE_LOCAL_SUBNET" || die '本机 LAN 网段尚未发布到 EasyTier'

    log "安装完成"
    log "插件:   EasyTier 路由向导"
    log "脚本:   $EASYTIER_ROUTE_APPLY_SCRIPT"
    log "lan-if:  $ET_ROUTE_LAN_IF"
    log "tun-if:  $ET_ROUTE_TUN_IF"
    log "virtual: $ET_ROUTE_VIRTUAL_IP"
    log "local:   $ET_ROUTE_LOCAL_SUBNET"
    log "remote:  $ET_ROUTE_REMOTE_SUBNET"
}

write_openvpn_custom_ui_files() {
    mkdir -p /usr/lib/lua/luci/controller/nradio_adv /usr/lib/lua/luci/view/nradio_adv /usr/lib/lua/luci/view/openvpn /usr/lib/lua/luci/model/cbi

    cat > /usr/lib/lua/luci/controller/nradio_adv/openvpn_full.lua <<'EOF_OPENVPN_FULL_CONTROLLER'
module("luci.controller.nradio_adv.openvpn_full", package.seeall)

local dispatcher = require "luci.dispatcher"
local util = require "luci.util"
local http = require "luci.http"
local fs = require "nixio.fs"
local uci = require "luci.model.uci".cursor()

local function cmd(c)
    return util.trim(util.exec(c) or "")
end

local function split_lines(s)
    local out = {}
    for line in (s or ""):gmatch("[^\r\n]+") do
        if line ~= "" then
            out[#out + 1] = line
        end
    end
    return out
end

local function contains(text, needle)
    return needle ~= "" and (text or ""):find(needle, 1, true) ~= nil
end

local function contains_proxy_target(peer_dump, target)
    if not target or target == "" then
        return false
    end
    for _, line in ipairs(split_lines(peer_dump)) do
        local ip = line:match("^([^%s]+)%s+proxy")
        if ip == target then
            return true
        end
    end
    return false
end

local function bool_text(ok)
    return ok and "已就绪" or "缺失"
end

local function badge_state(ok)
    return ok and "ok" or "bad"
end

local function ratio_text(ok_count, total_count)
    if total_count <= 0 then
        return "-"
    end
    return tostring(ok_count) .. "/" .. tostring(total_count)
end

local function shell_quote(s)
    return "'" .. tostring(s or ""):gsub("'", "'\\''") .. "'"
end

local function probe_ping(ip)
    if not ip or ip == "" then
        return false
    end
    return cmd("ping -c 1 -W 1 " .. shell_quote(ip) .. " >/dev/null 2>&1 && echo ok || echo fail") == "ok"
end

local function network_plus_one(network_ip)
    if not network_ip or network_ip == "" then
        return nil
    end
    local a, b, c, d = network_ip:match("^(%d+)%.(%d+)%.(%d+)%.(%d+)$")
    d = tonumber(d)
    if a and b and c and d then
        if d < 255 then
            return string.format("%s.%s.%s.%d", a, b, c, d + 1)
        end
        return string.format("%s.%s.%s.%d", a, b, c, d)
    end
    return nil
end

local function ipcalc_field(cidr, field)
    if not cidr or cidr == "" then
        return ""
    end
    return cmd("ipcalc.sh " .. shell_quote(cidr) .. " 2>/dev/null | grep '^" .. tostring(field or "") .. "=' | cut -d= -f2")
end

local function probe_ip_for_target(target)
    if not target or target == "" then
        return nil
    end
    if target:find("/") then
        local ip, mask = target:match("^([%d%.]+)/(%d+)$")
        if not ip then
            return nil
        end
        if mask == "32" then
            return ip
        end
        local network_ip = ipcalc_field(target, "NETWORK")
        local prefix = ipcalc_field(target, "PREFIX")
        if not network_ip or network_ip == "" then
            return nil
        end
        if tonumber(prefix or mask) <= 30 then
            return network_plus_one(network_ip)
        end
        return network_ip
    end
    return target
end

local function detect_primary_lan_cidr(lan_addr_dump)
    for _, line in ipairs(split_lines(lan_addr_dump)) do
        local cidr = line:match("inet%s+([%d%.]+/%d+)")
        if cidr and not cidr:match("/32$") then
            local network_ip = ipcalc_field(cidr, "NETWORK")
            local prefix = ipcalc_field(cidr, "PREFIX")
            return (network_ip ~= "" and prefix ~= "") and (network_ip .. "/" .. prefix) or cidr
        end
    end
    return nil
end

local ROUTE_STATE_PATH = "/root/.nradio-plugin-menu/openvpn_routes.conf"
local ROUTE_LIST_PATH = "/root/.nradio-plugin-menu/openvpn_routes.list"
local ROUTE_MAP_LIST_PATH = "/root/.nradio-plugin-menu/openvpn_map_peers.list"
local ROUTE_HOTPLUG_PATH = "/etc/hotplug.d/openvpn/99-openvpn-route"

local function read_text(path)
    local data = fs.readfile(path)
    return type(data) == "string" and data or ""
end

local function each_line(text, callback)
    for raw in ((text or "") .. "\n"):gmatch("(.-)\n") do
        callback((raw:gsub("\r$", "")))
    end
end

local function is_yes(value)
    value = tostring(value or ""):lower()
    return value == "1" or value == "y" or value == "yes" or value == "true"
end

local function valid_interface(value)
    return type(value) == "string" and #value > 0 and #value <= 32 and value:match("^[%w_.:%-]+$") ~= nil
end

local function valid_ipv4(value)
    local a, b, c, d = tostring(value or ""):match("^(%d+)%.(%d+)%.(%d+)%.(%d+)$")
    if not a then return false end
    for _, part in ipairs({ a, b, c, d }) do
        if tonumber(part) > 255 then return false end
    end
    return true
end

local function probe_ping_batch(ips)
    local args = {}
    local seen = {}
    local results = {}
    for _, ip in ipairs(ips or {}) do
        if valid_ipv4(ip) and not seen[ip] then
            seen[ip] = true
            args[#args + 1] = shell_quote(ip)
        end
    end
    if #args == 0 then return results end

    local command = "for ip in " .. table.concat(args, " ")
        .. "; do ( if ping -c 1 -W 1 \"$ip\" >/dev/null 2>&1; then printf '%s|1\\n' \"$ip\"; else printf '%s|0\\n' \"$ip\"; fi ) & done; wait"
    each_line(cmd(command), function(line)
        local ip, ok = line:match("^([%d%.]+)|([01])$")
        if ip and valid_ipv4(ip) then results[ip] = ok == "1" end
    end)
    return results
end

local function valid_target(value)
    local ip, mask = tostring(value or ""):match("^([^/]+)/(%d+)$")
    if ip then return valid_ipv4(ip) and tonumber(mask) <= 32 end
    return valid_ipv4(value)
end

local function normalize_target(value)
    return tostring(value or ""):gsub("/32$", "")
end

local function state_value(raw)
    raw = util.trim(raw or "")
    local value = raw:match("^'(.*)'$")
    if value and not value:find("'", 1, true) then return value end
    return nil
end

local function load_route_state()
    local allowed = {
        NRADIO_STATE_FORMAT = true, ROUTE_LAN_IF = true, ROUTE_TUN_IF = true,
        ROUTE_LAN_SUBNET = true, ROUTE_TUN_SUBNET = true, ROUTE_NAT = true,
        ROUTE_FORWARD = true, ROUTE_ENHANCED = true, ROUTE_MAP_ENABLE = true,
        ROUTE_MAP_IP = true, ROUTE_MAP_KIND = true, ROUTE_MAP_HOST = true,
        ROUTE_MAP_SUBNET = true, ROUTE_LAN_HOST_IP = true
    }
    local state = {}
    local content = read_text(ROUTE_STATE_PATH)
    each_line(content, function(line)
        local key, raw = line:match("^([A-Z0-9_]+)=(.*)$")
        if key and allowed[key] then
            local value = state_value(raw)
            if value ~= nil then state[key] = value end
        end
    end)
    local loaded = state.NRADIO_STATE_FORMAT == "2"
    if not loaded then state = {} end

    local hotplug = read_text(ROUTE_HOTPLUG_PATH)
    if not loaded and hotplug ~= "" then
        local hotplug_keys = {
            LAN_IF = "ROUTE_LAN_IF", TUN_IF = "ROUTE_TUN_IF",
            LAN_SUBNET = "ROUTE_LAN_SUBNET", TUN_SUBNET = "ROUTE_TUN_SUBNET",
            MAP_IP = "ROUTE_MAP_IP", MAP_KIND = "ROUTE_MAP_KIND",
            MAP_HOST = "ROUTE_MAP_HOST", MAP_SUBNET = "ROUTE_MAP_SUBNET",
            LAN_HOST_IP = "ROUTE_LAN_HOST_IP"
        }
        each_line(hotplug, function(line)
            local key, value = line:match('^([A-Z_]+)="([^"]*)"$')
            if key and hotplug_keys[key] then state[hotplug_keys[key]] = value end
        end)
        if state.ROUTE_MAP_KIND ~= "host" and state.ROUTE_MAP_KIND ~= "subnet" then
            if valid_ipv4(state.ROUTE_MAP_HOST) and tostring(state.ROUTE_MAP_IP or ""):match("/32$") then
                state.ROUTE_MAP_KIND = "host"
            elseif valid_target(state.ROUTE_MAP_SUBNET) then
                state.ROUTE_MAP_KIND = "subnet"
            end
        end
        if state.ROUTE_MAP_KIND == "host" or state.ROUTE_MAP_KIND == "subnet" then
            state.ROUTE_MAP_ENABLE = "y"
        end
        state.ROUTE_NAT = hotplug:find("ensure_iptables_rule nat POSTROUTING", 1, true) and "y" or "n"
        state.ROUTE_FORWARD = hotplug:find("ensure_iptables_rule filter FORWARD", 1, true) and "y" or "n"
        loaded = next(state) ~= nil
    end

    if not valid_interface(state.ROUTE_LAN_IF) then state.ROUTE_LAN_IF = "br-lan" end
    if not valid_interface(state.ROUTE_TUN_IF) then state.ROUTE_TUN_IF = "tun0" end
    if not valid_target(state.ROUTE_LAN_SUBNET) then state.ROUTE_LAN_SUBNET = "" end
    if not valid_target(state.ROUTE_TUN_SUBNET) then state.ROUTE_TUN_SUBNET = "" end
    if not valid_target(state.ROUTE_MAP_IP) then state.ROUTE_MAP_IP = "" end
    if not valid_ipv4(state.ROUTE_MAP_HOST) then state.ROUTE_MAP_HOST = "" end
    if not valid_target(state.ROUTE_MAP_SUBNET) then state.ROUTE_MAP_SUBNET = "" end
    if not valid_ipv4(state.ROUTE_LAN_HOST_IP) then state.ROUTE_LAN_HOST_IP = "" end
    return state, loaded, hotplug
end

local function append_expected_route(routes, index, target, via, kind, mapped, source)
    if not valid_target(target) or not valid_ipv4(via) then return end
    local key = normalize_target(target)
    local existing = index[key]
    if existing then
        routes[existing].mapped = routes[existing].mapped or mapped
        if mapped then routes[existing].kind = kind end
        return
    end
    routes[#routes + 1] = {
        target = target, via = via,
        kind = kind or (target:find("/", 1, true) and "subnet" or "host"),
        mapped = mapped == true, source = source or "saved"
    }
    index[key] = #routes
end

local function load_expected_routes(hotplug, local_map_host)
    local routes, index = {}, {}
    each_line(read_text(ROUTE_LIST_PATH), function(line)
        local target, via = line:match("^([^|]+)|([^|]+)$")
        append_expected_route(routes, index, target, via, nil, false, "saved")
    end)
    each_line(read_text(ROUTE_MAP_LIST_PATH), function(line)
        local target, via, kind = line:match("^([^|]+)|([^|]+)|([^|]+)$")
        append_expected_route(routes, index, target, via, kind, true, "saved-map")
    end)
    if #routes == 0 and hotplug ~= "" then
        each_line(hotplug, function(line)
            local target, via = line:match('ip route replace "([^"]+)" via "([^"]+)" dev')
            append_expected_route(routes, index, target, via, nil, false, "hotplug")
        end)
        local legacy_peers = hotplug:match("NRADIO_PEERS='(.-)'") or ""
        each_line(legacy_peers, function(line)
            local target, via = line:match("^([^|]+)|([^|]+)|")
            if normalize_target(target) ~= normalize_target(local_map_host) then
                append_expected_route(routes, index, target, via, "host", true, "legacy-hotplug-map")
            end
        end)
        local legacy_routes = hotplug:match("SITE_ROUTES='(.-)'") or ""
        each_line(legacy_routes, function(line)
            local target, via = line:match("^([^|]+)|([^|]+)$")
            append_expected_route(routes, index, target, via, nil, false, "legacy-hotplug")
        end)
    end
    return routes
end

local function parse_profile(content)
    local directives = {}
    local in_block = false
    each_line(content, function(raw)
        local line = util.trim(raw)
        if in_block then
            if line:match("^</[%w%-]+%s*>$") then in_block = false end
        elseif line:match("^<[%w%-]+%s*>$") then
            in_block = true
        elseif line ~= "" and not line:match("^[#;]") then
            local key, rest = line:match("^(%S+)%s*(.-)%s*$")
            if key then
                key = key:lower()
                if directives[key] == nil then directives[key] = rest ~= "" and rest or true end
            end
        end
    end)
    return directives
end

local function first_argument(value)
    if type(value) ~= "string" then return "" end
    return value:match('^"([^"]+)"') or value:match("^'([^']+)'") or value:match("^(%S+)") or ""
end

local function has_inline_block(content, tag)
    local lower = tostring(content or ""):lower()
    local _, open_end = lower:find("<" .. tag .. "%s*>")
    if not open_end then return false end
    local close_start = lower:find("</" .. tag .. "%s*>", open_end + 1)
    return close_start ~= nil and util.trim(content:sub(open_end + 1, close_start - 1)) ~= ""
end

local function auth_file_ready(path)
    if type(path) ~= "string" or path:sub(1, 1) ~= "/" or not fs.access(path) then return false end
    local lines = {}
    each_line(read_text(path), function(line)
        if #lines < 2 then lines[#lines + 1] = util.trim(line) end
    end)
    return #lines >= 2 and lines[1] ~= "" and lines[2] ~= ""
end

local function profile_auth_path(profile)
    local value = profile and profile["auth-user-pass"]
    if value == nil then return nil end
    local path = first_argument(value)
    if path == "" then return "/etc/openvpn/auth.txt" end
    if path:find("[\r\n%z]") or path == ".." or path:sub(1, 3) == "../"
        or path:find("/../", 1, true) or path:sub(-3) == "/.."
    then
        return nil
    end
    if path:sub(1, 1) ~= "/" then path = "/etc/openvpn/" .. path end
    return path
end

local function profile_file_ready(content, profile)
    if type(content) ~= "string" or util.trim(content) == "" then return false end
    if type(profile.remote) ~= "string" or first_argument(profile.remote) == "" then return false end
    if type(profile.dev) ~= "string" or first_argument(profile.dev) == "" then return false end
    return true
end

local function normalize_bare_auth_user_pass(content, auth_path)
    local lines = {}
    local in_block = false
    local changed = false
    each_line(content, function(raw)
        local line = util.trim(raw)
        if in_block then
            if line:match("^</[%w%-]+%s*>$") then in_block = false end
        elseif line:match("^<[%w%-]+%s*>$") then
            in_block = true
        elseif line ~= "" and not line:match("^[#;]") then
            local key, rest = line:match("^(%S+)%s*(.-)%s*$")
            if key and key:lower() == "auth-user-pass" and rest == "" then
                raw = (raw:match("^(%s*)") or "") .. "auth-user-pass " .. auth_path
                changed = true
            end
        end
        lines[#lines + 1] = raw
    end)
    local normalized = table.concat(lines, "\n"):gsub("\n+$", "") .. "\n"
    return normalized, changed
end

local function write_secure_file(path, content)
    local tmp = path .. ".nradio." .. tostring(os.time()) .. ".tmp"
    if not fs.writefile(tmp, content) then return false end
    fs.chmod(tmp, "0600")
    if not os.rename(tmp, path) then
        fs.unlink(tmp)
        return false
    end
    fs.chmod(path, "0600")
    return true
end

local function ensure_custom_config()
    local profile_path = "/etc/openvpn/client.ovpn"
    local content = read_text(profile_path)
    local profile = parse_profile(content)

    if not profile_file_ready(content, profile) then
        return false, "invalid profile"
    end

    local auth_required = profile["auth-user-pass"] ~= nil
    local auth_path = profile_auth_path(profile)
    if auth_required and not auth_path then
        return false, "invalid auth path"
    end
    if auth_required and not auth_file_ready(auth_path) then
        return false, "missing auth"
    end

    if auth_required then
        local normalized, changed = normalize_bare_auth_user_pass(content, auth_path)
        if changed and not write_secure_file(profile_path, normalized) then
            return false, "profile update failed"
        end
    end
    fs.chmod(profile_path, "0600")

    if not uci:get("openvpn", "custom_config") then
        uci:section("openvpn", "openvpn", "custom_config")
    end
    uci:set("openvpn", "custom_config", "enabled", "1")
    uci:set("openvpn", "custom_config", "config", profile_path)
    if auth_required then
        uci:set("openvpn", "custom_config", "auth_user_pass", auth_path)
    else
        uci:delete("openvpn", "custom_config", "auth_user_pass")
    end
    uci:save("openvpn")
    uci:commit("openvpn")
    return true
end

local function target_in_line(line, target)
    local normalized = normalize_target(target)
    return contains(line, "to " .. target .. " ")
        or contains(line, "to " .. normalized .. " ")
        or contains(line, "to " .. normalized .. "/32 ")
end

local function dump_has_target_rule(dump, target, lan_if)
    for _, line in ipairs(split_lines(dump)) do
        if contains(line, "lookup main") and target_in_line(line, target)
            and (not lan_if or contains(line, "iif " .. lan_if))
        then
            return true
        end
    end
    return false
end

local function dump_has_enhanced_rule(dump, target, lan_subnet)
    if not valid_target(target) or not valid_target(lan_subnet) then return false end
    for _, line in ipairs(split_lines(dump)) do
        if contains(line, "lookup main") and contains(line, "from " .. lan_subnet .. " ")
            and target_in_line(line, target)
        then
            return true
        end
    end
    return false
end

local function find_actual_route(route_dump, expected)
    for _, line in ipairs(split_lines(route_dump)) do
        local target, via = line:match("^([^%s]+)%s+via%s+([^%s]+)")
        if target and normalize_target(target) == normalize_target(expected.target) and via == expected.via then
            return true, line
        end
    end
    return false, expected.target .. " via " .. expected.via .. " (missing)"
end

local function dump_has_rule(text, fragments)
    for _, line in ipairs(split_lines(text)) do
        local ok = true
        for _, fragment in ipairs(fragments) do
            if not contains(line, fragment) then
                ok = false
                break
            end
        end
        if ok then return true end
    end
    return false
end

local function collect_status(opts)
    opts = opts or {}
    local fast_probe = opts.fast_probe == true
    local route_state, route_state_loaded, hotplug = load_route_state()
    local tun_if = route_state.ROUTE_TUN_IF or "tun0"
    local lan_if = route_state.ROUTE_LAN_IF or "br-lan"
    local svc = cmd("/etc/init.d/openvpn status 2>/dev/null || true")
    local ps_std = cmd("ps | grep 'openvpn(custom_config)' | grep -v grep")
    local ps_legacy = cmd("ps | grep 'openvpn --config' | grep -v grep")
    local ps = ps_std ~= "" and ps_std or ps_legacy
    local tun = cmd("ip addr show " .. shell_quote(tun_if) .. " 2>/dev/null || echo " .. shell_quote(tun_if .. "-down"))
    local route_dump = cmd("ip -4 route show dev " .. shell_quote(tun_if) .. " 2>/dev/null")
    local peer_dump = cmd("ip neigh show proxy dev " .. shell_quote(lan_if) .. " 2>/dev/null")
    local rule_dump = cmd("ip rule 2>/dev/null")
    local nat_dump = cmd("iptables -t nat -S 2>/dev/null")
    local filter_dump = cmd("iptables -S FORWARD 2>/dev/null")
    local lan_addr_dump = cmd("ip -4 addr show " .. shell_quote(lan_if) .. " 2>/dev/null")
    local cfg = read_text("/etc/openvpn/client.ovpn")
    local profile = parse_profile(cfg)
    local configured_log = first_argument(profile["log-append"] or profile.log)
    local active_log_path = "/var/log/nradio-openvpn-client.log"
    if configured_log == "/tmp/openvpn-client.log" or configured_log == "/var/log/nradio-openvpn-client.log" then
        active_log_path = configured_log
    elseif fs.access("/tmp/openvpn-client.log") then
        active_log_path = "/tmp/openvpn-client.log"
    end
    local log = nil
    local log_focus = nil
    if fast_probe then
        log = cmd("tail -18 " .. shell_quote(active_log_path) .. " 2>/dev/null")
        log_focus = cmd("tail -60 " .. shell_quote(active_log_path) .. " 2>/dev/null | grep -i -E 'openvpn|tun|tls|auth|route|error|fail|warn' | tail -16")
    else
        log = cmd("tail -40 " .. shell_quote(active_log_path) .. " 2>/dev/null")
        log_focus = cmd("tail -120 " .. shell_quote(active_log_path) .. " 2>/dev/null | grep -i -E 'openvpn|tun|tls|auth|route|error|fail|warn' | tail -30")
    end
    local tun_ip = tun:match("inet%s+([%d%.]+/%d+)") or "-"
    local remote = type(profile.remote) == "string" and profile.remote or ""
    local proto = first_argument(profile.proto)
    local cipher = first_argument(profile.cipher)
    local auth_digest = first_argument(profile.auth)

    local has_ca = has_inline_block(cfg, "ca")
    local has_cert = has_inline_block(cfg, "cert")
    local has_tls_auth = has_inline_block(cfg, "tls%-auth")
    local has_tls_crypt = has_inline_block(cfg, "tls%-crypt")
    local profile_ready = profile_file_ready(cfg, profile)
    local auth_required = profile["auth-user-pass"] ~= nil
    local auth_path = profile_auth_path(profile)
    local has_auth_file = auth_required and auth_file_ready(auth_path)
    local activation_ready = profile_ready and ((not auth_required) or has_auth_file)
    local managed_cfg = uci:get("openvpn", "custom_config", "config")
    local managed_enabled = uci:get("openvpn", "custom_config", "enabled") == "1"
    local uci_managed = managed_cfg == "/etc/openvpn/client.ovpn"
    local connected = (((svc:match("running")) or ps ~= "") and tun:match("inet ")) and true or false
    local mode = ps_std ~= "" and "UCI custom_config" or (ps_legacy ~= "" and "Legacy ovpn" or "Stopped")

    local expected_routes = load_expected_routes(hotplug, route_state.ROUTE_MAP_HOST)
    if #expected_routes == 0 and not route_state_loaded then
        local runtime_index = {}
        for _, line in ipairs(split_lines(route_dump)) do
            local target, via = line:match("^([^%s]+)%s+via%s+([^%s]+)")
            append_expected_route(expected_routes, runtime_index, target, via, nil, false, "runtime")
        end
    end

    local route_checks = {}
    local peer_lines = split_lines(peer_dump)
    local route_targets = {}
    local route_count = #expected_routes
    local route_health_ok = 0
    local route_health_total = 0
    local remote_online_count = 0
    local enhanced_required = is_yes(route_state.ROUTE_ENHANCED)
    local probe_results = {}

    if not fast_probe then
        local probe_targets = {}
        for _, expected in ipairs(expected_routes) do
            local probe_ip = probe_ip_for_target(expected.target)
            if probe_ip then probe_targets[#probe_targets + 1] = probe_ip end
        end
        probe_results = probe_ping_batch(probe_targets)
    end

    for _, expected in ipairs(expected_routes) do
        local target = expected.target
        local route_ok, line = find_actual_route(route_dump, expected)
        local is_host = expected.kind == "host" or target:find("/", 1, true) == nil or target:match("/32$")
        local proxy_required = expected.mapped and is_host
        local nat_required = expected.mapped or is_yes(route_state.ROUTE_NAT)
        local forward_required = expected.mapped or is_yes(route_state.ROUTE_FORWARD)
        local to_rule_ok = dump_has_target_rule(rule_dump, target, nil)
        local iif_rule_ok = dump_has_target_rule(rule_dump, target, lan_if)
        local enhanced_ok = (not enhanced_required) or dump_has_enhanced_rule(rule_dump, target, route_state.ROUTE_LAN_SUBNET)
        local proxy_ok = (not proxy_required) or contains_proxy_target(peer_dump, normalize_target(target))
        local target_text = normalize_target(target)
        local target_cidr = target:find("/", 1, true) and target or (target .. "/32")
        local nat_ok = (not nat_required)
            or dump_has_rule(nat_dump, { "-A POSTROUTING", "-s " .. route_state.ROUTE_LAN_SUBNET, "-d " .. target_text, "-o " .. tun_if, "-j MASQUERADE" })
            or dump_has_rule(nat_dump, { "-A POSTROUTING", "-s " .. route_state.ROUTE_LAN_SUBNET, "-d " .. target_cidr, "-o " .. tun_if, "-j MASQUERADE" })
        local forward_in_ok = (not forward_required)
            or dump_has_rule(filter_dump, { "-A FORWARD", "-s " .. target_text, "-d " .. route_state.ROUTE_LAN_SUBNET, "-i " .. tun_if, "-o " .. lan_if, "-j ACCEPT" })
            or dump_has_rule(filter_dump, { "-A FORWARD", "-s " .. target_cidr, "-d " .. route_state.ROUTE_LAN_SUBNET, "-i " .. tun_if, "-o " .. lan_if, "-j ACCEPT" })
        local forward_out_ok = (not forward_required)
            or dump_has_rule(filter_dump, { "-A FORWARD", "-d " .. target_text, "-i " .. lan_if, "-o " .. tun_if, "-j ACCEPT" })
            or dump_has_rule(filter_dump, { "-A FORWARD", "-d " .. target_cidr, "-i " .. lan_if, "-o " .. tun_if, "-j ACCEPT" })
        local forward_ok = forward_in_ok and forward_out_ok
        local probe_ip = fast_probe and "-" or probe_ip_for_target(target)
        local probe_ok = (not fast_probe) and route_ok and probe_results[probe_ip] == true

        route_checks[#route_checks + 1] = {
            line = line, target = target, via = expected.via,
            kind = is_host and "host" or "subnet", mapped = expected.mapped,
            route_ok = route_ok, to_rule_ok = to_rule_ok, iif_rule_ok = iif_rule_ok,
            enhanced_required = enhanced_required, enhanced_ok = enhanced_ok,
            proxy_required = proxy_required, proxy_ok = proxy_ok,
            nat_required = nat_required, nat_ok = nat_ok,
            forward_required = forward_required, forward_ok = forward_ok,
            probe_ip = probe_ip or "-", probe_ok = probe_ok, probe_deferred = fast_probe
        }
        route_targets[#route_targets + 1] = target
        if probe_ok then remote_online_count = remote_online_count + 1 end
        local checks = { route_ok, to_rule_ok, iif_rule_ok }
        if enhanced_required then checks[#checks + 1] = enhanced_ok end
        if proxy_required then checks[#checks + 1] = proxy_ok end
        if nat_required then checks[#checks + 1] = nat_ok end
        if forward_required then checks[#checks + 1] = forward_ok end
        for _, ok in ipairs(checks) do
            route_health_total = route_health_total + 1
            if ok then route_health_ok = route_health_ok + 1 end
        end
    end

    table.sort(route_checks, function(a, b)
        if a.kind ~= b.kind then
            return a.kind < b.kind
        end
        if a.probe_ok ~= b.probe_ok then
            return (not a.probe_ok) and b.probe_ok
        end
        return tostring(a.target) < tostring(b.target)
    end)

    local peer_count = #peer_lines
    local map_enabled = is_yes(route_state.ROUTE_MAP_ENABLE)
    local map_kind = route_state.ROUTE_MAP_KIND or ""
    local map_ip = map_kind == "subnet" and route_state.ROUTE_MAP_SUBNET or route_state.ROUTE_MAP_HOST
    if map_ip == "" then map_ip = route_state.ROUTE_MAP_IP end
    local primary_lan_cidr = route_state.ROUTE_LAN_SUBNET ~= "" and route_state.ROUTE_LAN_SUBNET or detect_primary_lan_cidr(lan_addr_dump)
    local map_ip_ok = not map_enabled
    local dnat_pre_ok = not map_enabled
    local dnat_out_ok = not map_enabled
    local map_label = "未启用"
    if map_enabled and map_kind == "host" then
        local host = route_state.ROUTE_MAP_HOST
        local alias = route_state.ROUTE_MAP_IP ~= "" and route_state.ROUTE_MAP_IP or (host .. "/32")
        map_ip_ok = host ~= "" and contains(lan_addr_dump, "inet " .. alias)
        dnat_pre_ok = dump_has_rule(nat_dump, { "-A PREROUTING", "-i " .. tun_if, "-d " .. host, "-j DNAT", "--to-destination " .. route_state.ROUTE_LAN_HOST_IP })
        dnat_out_ok = dump_has_rule(nat_dump, { "-A OUTPUT", "-d " .. host, "-j DNAT", "--to-destination " .. route_state.ROUTE_LAN_HOST_IP })
        map_label = "主机 DNAT"
    elseif map_enabled and map_kind == "subnet" then
        local subnet = route_state.ROUTE_MAP_SUBNET
        map_ip_ok = subnet ~= "" and primary_lan_cidr ~= nil
        dnat_pre_ok = dump_has_rule(nat_dump, { "-A PREROUTING", "-i " .. tun_if, "-d " .. subnet, "-j NETMAP", "--to " .. tostring(primary_lan_cidr or "") })
        dnat_out_ok = dump_has_rule(nat_dump, { "-A OUTPUT", "-d " .. subnet, "-j NETMAP", "--to " .. tostring(primary_lan_cidr or "") })
        map_label = "网段 NETMAP"
    end
    local local_map_online = map_enabled and map_ip_ok and dnat_pre_ok and dnat_out_ok
    local masquerade_hits = 0
    for _, item in ipairs(route_checks) do
        if item.nat_required and item.nat_ok then masquerade_hits = masquerade_hits + 1 end
    end

    local auth_mode = "未知"
    if has_auth_file and has_cert then
        auth_mode = "账号 + 证书"
    elseif has_auth_file then
        auth_mode = "账号密码"
    elseif has_cert then
        auth_mode = "证书"
    end

    local tls_label = "无"
    if has_tls_crypt then
        tls_label = "tls-crypt"
    elseif has_tls_auth then
        tls_label = "tls-auth"
    end

    local log_lower = tostring(log or ""):lower()
    local log_focus_lower = tostring(log_focus or ""):lower()
    local log_history_lower = log_lower .. "\n" .. log_focus_lower
    local log_has_init_marker = log_lower:find("initialization sequence completed", 1, true) ~= nil
        or log_focus_lower:find("initialization sequence completed", 1, true) ~= nil
    local current_log_lower = log_lower
    local init_search_from = 1
    while true do
        local _, init_end = log_lower:find("initialization sequence completed", init_search_from, true)
        if not init_end then break end
        current_log_lower = log_lower:sub(init_end + 1)
        init_search_from = init_end + 1
    end
    local log_error = current_log_lower:find("auth_failed", 1, true) ~= nil
        or current_log_lower:find("tls error", 1, true) ~= nil
        or current_log_lower:find("fatal", 1, true) ~= nil
        or current_log_lower:find("ping-restart", 1, true) ~= nil
        or current_log_lower:find("connection reset", 1, true) ~= nil
        or current_log_lower:find("network is unreachable", 1, true) ~= nil
        or current_log_lower:find("error", 1, true) ~= nil
    local log_state_ok = connected and not log_error
    local log_state_label = "未确认"
    if log_error then
        log_state_label = "当前会话异常"
    elseif connected then
        log_state_label = log_has_init_marker and "运行稳定" or "运行中"
    elseif log_has_init_marker then
        log_state_label = "已初始化"
    end

    local remote_cert_tls = first_argument(profile["remote-cert-tls"]):lower()
    local server_verify_ready = remote_cert_tls == "server"
        or profile["verify-x509-name"] ~= nil
        or first_argument(profile["ns-cert-type"]):lower() == "server"
    local tun_mtu = first_argument(profile["tun-mtu"])
    local has_mss_or_fragment = profile.mssfix ~= nil or profile.fragment ~= nil
    local mtu_warning = has_mss_or_fragment and tun_mtu ~= "" and tun_mtu ~= "1500"
    local rekey_seen = log_history_lower:find("tls: soft reset", 1, true) ~= nil
        or log_history_lower:find("tls_process: killed expiring key", 1, true) ~= nil
    local restart_recovered = connected and log_has_init_marker
        and log_history_lower:find("sigterm received", 1, true) ~= nil
    local ping_restart_recovered = connected and log_has_init_marker
        and log_history_lower:find("ping-restart", 1, true) ~= nil
        and not log_error
    local dns_retry_recovered = connected and log_has_init_marker
        and (log_history_lower:find("resolve: cannot resolve", 1, true) ~= nil
            or log_history_lower:find("temporary failure in name resolution", 1, true) ~= nil)
    local log_notice_label = "等待连接"
    local log_notice_tone = "bad"
    local log_notice_parts = {}
    if log_error then
        log_notice_label = "当前会话异常"
        log_notice_tone = "bad"
        log_notice_parts[#log_notice_parts + 1] = "当前初始化完成后的日志仍有连接错误，先看错误行，再决定是否手动重连。"
    elseif ping_restart_recovered then
        log_notice_label = "网络中断后已恢复"
        log_notice_tone = "warn"
        log_notice_parts[#log_notice_parts + 1] = "发现 ping-restart，说明链路曾超时；后续已重新初始化完成。"
    elseif restart_recovered then
        log_notice_label = "服务重启后已恢复"
        log_notice_tone = "warn"
        log_notice_parts[#log_notice_parts + 1] = "SIGTERM 表示本机或外部操作重启了 OpenVPN；后续已重新初始化，不属于 ping 超时掉线。"
    elseif connected then
        log_notice_label = rekey_seen and "正常 TLS 密钥轮换" or "当前会话正常"
        log_notice_tone = "good"
    end
    if rekey_seen then
        log_notice_parts[#log_notice_parts + 1] = "TLS soft reset / killed expiring key 是定时密钥轮换；后续校验成功时不算掉线。"
    end
    if dns_retry_recovered then
        log_notice_parts[#log_notice_parts + 1] = "启动阶段曾等待 DNS/WAN 就绪，后续已解析并连接成功。"
    end
    if not server_verify_ready then
        log_notice_parts[#log_notice_parts + 1] = "未启用服务端证书身份校验属于安全风险，与当前连通性分开处理。"
        if log_notice_tone == "good" then
            log_notice_label = "连接正常 · 安全警告"
            log_notice_tone = "warn"
        end
    end
    if mtu_warning then
        log_notice_parts[#log_notice_parts + 1] = "mssfix/fragment 与 tun-mtu " .. tun_mtu .. " 触发 MTU 配置提示；它本身不能证明发生掉线。"
        if log_notice_tone == "good" then
            log_notice_label = "连接正常 · MTU 提示"
            log_notice_tone = "warn"
        end
    end
    if #log_notice_parts == 0 then
        log_notice_parts[#log_notice_parts + 1] = connected and "当前未发现需要处理的连接日志。" or "当前未检测到已连接的 OpenVPN 会话。"
    end
    local log_notice_detail = table.concat(log_notice_parts, " ")

    local health_ok = 0
    local health_total = 0
    local function add_health(ok)
        health_total = health_total + 1
        if ok then
            health_ok = health_ok + 1
        end
    end

    add_health(connected)
    add_health(log_state_ok)
    if route_count > 0 then
        add_health(route_health_ok == route_health_total)
    end
    if map_enabled then
        add_health(map_ip_ok)
        add_health(dnat_pre_ok)
        add_health(dnat_out_ok)
    end

    local health_label = "离线"
    local health_class = "bad"
    if connected then
        if health_ok == health_total then
            health_label = "健康"
            health_class = "ok"
        elseif log_state_ok then
            health_label = "目标待查"
            health_class = "warn"
        else
            health_label = "会话异常"
            health_class = "warn"
        end
    end

    local action_kind = "need_profile"
    local action_label = "先写入配置"
    local action_hint = "尚未检测到可用的 client.ovpn，需先写入配置。"
    local runtime_note = "先完成配置写入，当前页面才会切换成启动或接管并启动。"
    local auth_note = "还没有可启动的配置文件。"

    if connected then
        if log_state_ok then
            action_kind = "stable"
            action_label = "OpenVPN 运行中"
            action_hint = health_class == "ok"
                and "当前隧道与目标检查正常；如需断开可直接停止。"
                or "当前隧道会话正常，告警来自路由、映射或远端目标；请查看目标检查，无需先重连。"
            runtime_note = "当前实例运行正常；路由或远端设备异常应按目标检查处理，重连不会自动修复这些问题。"
            auth_note = "当前配置已在运行，认证材料按现有实例生效。"
        else
            action_kind = "restart"
            action_label = "检查后重连 OpenVPN"
            action_hint = "当前会话日志仍有连接错误；先查看关键日志，确认后可手动重连。"
            runtime_note = "当前进程和隧道接口仍在，但本次会话日志存在错误；重连会短暂中断现有流量。"
            auth_note = "当前配置已在运行；如出现 AUTH_FAILED，请先修正认证材料再重连。"
        end
    elseif activation_ready and uci_managed then
        action_kind = "start"
        action_label = "启动 OpenVPN"
        action_hint = "配置已就绪，可直接从当前页面启动 OpenVPN。"
        runtime_note = "当前实例已在 LuCI 中登记，断开时可直接启动。"
        auth_note = "配置文件和所需认证材料已经齐全，可直接由当前页面启动。"
    elseif activation_ready then
        action_kind = "takeover"
        action_label = "接管并启动"
        action_hint = "检测到现有 client.ovpn，可由当前页面接管并启动。"
        runtime_note = "当前页会把现有 client.ovpn 接入 custom_config 后再启动。"
        auth_note = "配置文件和所需认证材料已经齐全，接管后可以直接启动。"
    elseif profile_ready then
        action_kind = "need_auth"
        action_label = "添加认证文件"
        action_hint = "已检测到配置文件，但认证材料还不完整，暂时不能直接启动。"
        runtime_note = "添加必需的认证文件后，才能从当前页面启动。"
        auth_note = "配置文件已存在，但认证材料未齐全。"
    end

    local managed_label = "未配置"
    if uci_managed and managed_enabled then
        managed_label = "已接管"
    elseif uci_managed then
        managed_label = "已接管未启用"
    elseif profile_ready then
        managed_label = "可接管"
    end

    local startup_label = activation_ready and "可启动" or (profile_ready and "待认证文件" or "待配置")
    local map_ratio = map_enabled and ratio_text(local_map_online and 1 or 0, 1) or "-"
    local remote_online_ratio = fast_probe and "探测中" or ratio_text(remote_online_count, route_count)
    local online_breakdown = fast_probe and ("远端探测中 · 映射 " .. map_ratio) or ("远端 " .. remote_online_ratio .. " · 映射 " .. map_ratio)
    local online_device_ratio = fast_probe and "探测中" or remote_online_ratio
    local online_ratio = fast_probe and "探测中" or ratio_text(remote_online_count + (local_map_online and 1 or 0), route_count + (map_enabled and 1 or 0))
    local mode_label = "未启动"
    if ps_std ~= "" then
        mode_label = "LuCI 管理实例"
    elseif ps_legacy ~= "" then
        mode_label = "外部配置直连"
    elseif profile_ready then
        mode_label = "待接管"
    end
    local service_label = connected and "运行中" or ((svc:match("enabled=yes") and profile_ready) and "已启用未连接" or "已停止")
    local process_summary = ps ~= "" and ((ps_std ~= "" and "custom_config 正在运行") or "外部配置进程正在运行") or "未检测到进程"
    local auth_badge_label = activation_ready and "可启动" or "缺认证文件"
    local route_badge_label = route_count == 0 and "未配置" or ((route_health_ok == route_health_total) and "完整" or "待检查")
    local auth_requirement_label = "无需额外文件"
    if auth_required and has_auth_file then
        auth_requirement_label = "需要账号文件 · 已就绪"
    elseif auth_required then
        auth_requirement_label = "需要账号文件"
    elseif has_cert then
        auth_requirement_label = "证书模式"
    end
    local cert_material_label = "无需证书"
    if has_ca and has_cert then
        cert_material_label = "CA + 客户端证书"
    elseif has_ca then
        cert_material_label = "仅 CA 证书"
    elseif has_cert then
        cert_material_label = "仅客户端证书"
    end

    return {
        connected = connected,
        health_label = health_label,
        health_class = health_class,
        status_summary_label = connected and ((health_class == "ok") and "已连接 · 健康" or (log_state_ok and "已连接 · 目标待查" or "已连接 · 会话异常")) or "未连接",
        status_label = connected and "已连接" or "已停止",
        health_ratio = ratio_text(health_ok, health_total),
        online_device_ratio = online_device_ratio,
        online_ratio = online_ratio,
        remote_online_ratio = remote_online_ratio,
        local_map_online_ratio = map_enabled and ratio_text(local_map_online and 1 or 0, 1) or "-",
        route_rule_ratio = ratio_text(route_health_ok, route_health_total),
        tun_ip = tun_ip,
        remote = remote ~= "" and remote or "-",
        proto = proto ~= "" and proto or "-",
        auth_mode = auth_mode,
        tls_label = tls_label,
        cipher = cipher ~= "" and cipher or "-",
        auth_digest = auth_digest ~= "" and auth_digest or "-",
        service_status = svc ~= "" and svc or "stopped",
        mode = mode,
        profile_ready = profile_ready,
        activation_ready = activation_ready,
        auth_required = auth_required,
        enhanced_required = enhanced_required,
        action_kind = action_kind,
        action_label = action_label,
        action_hint = action_hint,
        runtime_note = runtime_note,
        auth_note = auth_note,
        managed_label = managed_label,
        startup_label = startup_label,
        online_breakdown = online_breakdown,
        mode_label = mode_label,
        service_label = service_label,
        process_summary = process_summary,
        auth_badge_label = auth_badge_label,
        auth_requirement_label = auth_requirement_label,
        cert_material_label = cert_material_label,
        route_badge_label = route_badge_label,
        copy_ready = profile_ready,
        uci_managed = uci_managed,
        uci_enabled = managed_enabled,
        process_line = ps ~= "" and ps or "no process",
        log_state = log_state_label,
        log_state_ok = log_state_ok,
        log_notice_label = log_notice_label,
        log_notice_tone = log_notice_tone,
        log_notice_detail = log_notice_detail,
        server_verify_ready = server_verify_ready,
        mtu_warning = mtu_warning,
        auth_ready = bool_text((not auth_required) or has_auth_file),
        ca_ready = bool_text(has_ca),
        cert_ready = bool_text(has_cert),
        route_count = route_count,
        peer_count = peer_count,
        remote_online_count = remote_online_count,
        route_badge_ok = route_count > 0 and route_health_ok == route_health_total,
        dnat_status = map_enabled and (map_label .. ((map_ip_ok and dnat_pre_ok and dnat_out_ok) and " · 已同步" or " · 待修复")) or "未启用",
        dnat_ok = (not map_enabled) or (map_ip_ok and dnat_pre_ok and dnat_out_ok),
        dnat_pre_ok = dnat_pre_ok,
        dnat_out_ok = dnat_out_ok,
        map_enabled = map_enabled,
        map_kind = map_kind,
        map_label = map_label,
        map_ip_ok = map_ip_ok,
        map_ip = map_ip ~= "" and map_ip or "-",
        primary_lan_cidr = primary_lan_cidr or "-",
        local_map_online = local_map_online,
        masquerade_hits = masquerade_hits,
        route_targets = route_targets,
        route_checks = route_checks,
        route_state_loaded = route_state_loaded,
        route_source = (#expected_routes > 0 and expected_routes[1].source) or "none",
        tun_if = tun_if,
        lan_if = lan_if,
        probe_deferred = fast_probe,
        peer_lines = peer_lines,
        log_focus = log_focus ~= "" and log_focus or "no focus log",
        log = log ~= "" and log or "no log",
        tun = tun ~= "" and tun or (tun_if .. "-down"),
        lan_addr_dump = lan_addr_dump ~= "" and lan_addr_dump or ("no " .. lan_if .. " data"),
        ts = os.date("%Y-%m-%d %H:%M:%S")
    }
end

function index()
    local page = entry({"nradioadv", "system", "openvpnfull"}, template("nradio_adv/openvpn_full"), _("OpenVPN"), 94)
    page.show = true
    local restart_page = entry({"nradioadv", "system", "openvpnfull", "restart"}, call("restart"), nil)
    restart_page.leaf = true
    restart_page.post = true
    local apply_page = entry({"nradioadv", "system", "openvpnfull", "applycurrent"}, call("applycurrent"), nil)
    apply_page.leaf = true
    apply_page.post = true
    local stop_page = entry({"nradioadv", "system", "openvpnfull", "stop"}, call("stop"), nil)
    stop_page.leaf = true
    stop_page.post = true
    entry({"nradioadv", "system", "openvpnfull", "status"}, call("status"), nil).leaf = true
end

function restart()
    os.execute("( /etc/init.d/openvpn restart >/dev/null 2>&1 || /etc/init.d/openvpn_client restart >/dev/null 2>&1 ) &")
    http.redirect(dispatcher.build_url("nradioadv", "system", "openvpnfull"))
end

function applycurrent()
    local ok = ensure_custom_config()
    if ok then
        os.execute("( /etc/init.d/openvpn enable >/dev/null 2>&1; /etc/init.d/openvpn restart >/dev/null 2>&1 || /etc/init.d/openvpn start custom_config >/dev/null 2>&1 ) &")
    end
    http.redirect(dispatcher.build_url("nradioadv", "system", "openvpnfull"))
end

function stop()
    os.execute("( /etc/init.d/openvpn stop custom_config >/dev/null 2>&1 || /etc/init.d/openvpn stop >/dev/null 2>&1 ) &")
    http.redirect(dispatcher.build_url("nradioadv", "system", "openvpnfull"))
end

function status()
    local fast_probe = http.formvalue("fast") == "1"
    local ok, data = xpcall(function()
        return collect_status({ fast_probe = fast_probe })
    end, debug.traceback)
    if not ok then
        http.status(200, "OK")
        http.prepare_content("application/json")
        http.write_json({
            ok = false,
            error = tostring(data or "unknown error"),
            ts = os.date("%Y-%m-%d %H:%M:%S")
        })
        return
    end

    data.ok = true
    http.status(200, "OK")
    http.prepare_content("application/json")
    http.write_json(data)
end
EOF_OPENVPN_FULL_CONTROLLER

    cat > /usr/lib/lua/luci/view/nradio_adv/openvpn_full.htm <<'EOF_OPENVPN_FULL_VIEW'
<%+header%>
<%
local dispatcher = require "luci.dispatcher"
local util = require "luci.util"
local fs = require "nixio.fs"
local function esc(s) return luci.util.pcdata(s or "") end
local function read_cfg_limited(path, limit)
  local st = fs.stat(path)
  if not st or st.type ~= "reg" or tonumber(st.size or 0) > limit then return "" end
  local f = io.open(path, "rb")
  if not f then return "" end
  local data = f:read(limit + 1) or ""
  f:close()
  return #data <= limit and data or ""
end
local cfg = read_cfg_limited("/etc/openvpn/client.ovpn", 102400)
%>

