    .vpn-entry-head {
        display: flex;
        align-items: flex-start;
        justify-content: space-between;
        gap: 14px;
    }
    .vpn-kv {
        display: grid;
        grid-template-columns: minmax(110px, 0.46fr) minmax(0, 1fr);
        gap: 12px;
        padding: 11px 0;
        border-top: 1px solid rgba(148, 163, 184, 0.14);
