    .vpn-action-list-compact {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 10px;
        margin-top: 14px;
    }
    .vpn-action-tile {
        display: block;
        min-height: 84px;
        padding: 14px;
        border: 1px solid rgba(125, 211, 252, 0.16);
        border-radius: 8px;
        color: #dbeafe !important;
        background: rgba(15, 23, 42, 0.54);
        text-decoration: none !important;
    }
    .vpn-action-tile strong {
        display: block;
        color: #e0f2fe;
        font-size: 15px;
        line-height: 1.35;
    }
    .vpn-action-tile span {
        display: block;
        margin-top: 8px;
        color: var(--vpn-muted);
        font-size: 12px;
        line-height: 1.55;
