    }
    .vpn-card:hover {
        background: rgba(var(--vpn-state-rgb), 0.03);
    }
    @keyframes vpnHeroIntro {
        from {
            opacity: 0;
            transform: translateY(6px);
        }
        to {
            opacity: 1;
            transform: translateY(0);
        }
    }
    @keyframes vpnSurfaceIntro {
        from {
            opacity: 0;
            transform: translateY(8px);
        }
        to {
            opacity: 1;
            transform: translateY(0);
        }
    }
