    @media (min-width: 981px) and (max-width: 1180px) {
        .vpn-action-list-compact {
            grid-template-columns: repeat(2, minmax(0, 1fr));
        }
        .vpn-action-list-compact .vpn-action-tile:last-child {
            grid-column: 1 / -1;
        }
        .vpn-mini-grid {
            grid-template-columns: repeat(2, minmax(0, 1fr));
        }
        .vpn-mini-card-wide {
            grid-column: span 2;
        }
        .vpn-overview-grid {
            grid-template-columns: repeat(2, minmax(0, 1fr));
        }
        .vpn-card + .vpn-card {
            border-left: 1px solid #edf2f7;
        }
        .vpn-card:nth-child(2n+1) {
            border-left: 0;
        }
        .vpn-card:nth-child(n+3) {
            border-top: 1px solid #edf2f7;
        }
        .vpn-quick-rail-head {
            flex-direction: column;
        }
    }
    @media (max-width: 980px) {
        .vpn-stat-grid,
        .vpn-overview-grid,
        .vpn-mini-grid,
        .vpn-action-list-compact,
        .vpn-entry-grid,
        .vpn-split-grid {
            grid-template-columns: 1fr;
        }
        .vpn-mini-card-wide {
            grid-column: auto;
        }
        .vpn-action-list-compact .vpn-action-tile:last-child {
            grid-column: auto;
        }
        .vpn-hero {
            padding: 20px 18px 18px;
        }
        .vpn-hero-top {
            grid-template-columns: 1fr;
            gap: 16px;
        }
        .vpn-hero h2 {
            font-size: 28px;
        }
        .cbi-map .cbi-section-table,
        .cbi-map .cbi-section-table-row,
        .cbi-map .cbi-section-table-cell,
        .cbi-map .cbi-section-table-titles {
            display: block;
            width: 100%;
            box-sizing: border-box;
        }
        .vpn-hero-actions {
            justify-content: flex-start;
            min-width: 0;
        }
        .vpn-copy-feedback {
            justify-content: flex-start;
        }
        .vpn-hero-actions .cbi-button,
        .vpn-hero-actions a.cbi-button,
        .vpn-hero-actions form {
            width: 100%;
        }
        .vpn-stat-card {
            min-height: 0;
        }
        .vpn-card + .vpn-card {
            border-left: 0;
            border-top: 1px solid #edf2f7;
        }
        .vpn-panel-head {
            flex-direction: column;
        }
        .vpn-panel-head span {
            text-align: left;
        }
        .vpn-panel-shell-head {
            flex-direction: column;
        }
        .vpn-check-row {
            flex-direction: column;
        }
        .vpn-check-badges {
            justify-content: flex-start;
            min-width: 0;
        }
    }
    @media (prefers-reduced-motion: reduce) {
        .vpn-hero,
        .vpn-overview-grid,
        .vpn-quick-rail,
        .vpn-panel-shell {
            animation: none;
        }
        .vpn-hero-actions .cbi-button,
        .vpn-hero-actions a.cbi-button,
        .vpn-stat-card,
        .vpn-card,
        .vpn-action-tile,
        .vpn-tab-btn,
        .vpn-copy-feedback {
            transition: none;
        }
        .vpn-action-tile::after {
            transition: none;
        }
    }
    /* NRadio OpenVPN Mk3: dark command-center layer */
    .vpn-shell-mk3 {
        max-width: 1220px;
        padding: 8px 8px 22px;
        color: #f8fbff;
        background:
            radial-gradient(circle at 14% 8%, rgba(34, 211, 238, 0.13), transparent 30%),
            radial-gradient(circle at 86% 16%, rgba(59, 130, 246, 0.16), transparent 32%),
            linear-gradient(180deg, rgba(12, 18, 32, 0.98) 0%, rgba(16, 22, 36, 0.94) 100%);
        border: 1px solid rgba(255, 255, 255, 0.08);
        box-shadow: 0 22px 48px rgba(0, 0, 0, 0.26);
        --vpn-accent: #22d3ee;
        --vpn-accent-strong: #38bdf8;
        --vpn-border: rgba(148, 163, 184, 0.22);
        --vpn-surface: rgba(20, 27, 43, 0.82);
        --vpn-surface-soft: rgba(26, 35, 54, 0.72);
        --vpn-shadow: 0 18px 36px rgba(0, 0, 0, 0.22);
        --vpn-state-rgb: 34, 211, 238;
        --vpn-state-ink: #67e8f9;
        --vpn-state-border: rgba(34, 211, 238, 0.28);
        --vpn-state-soft: rgba(34, 211, 238, 0.10);
    }
    .vpn-shell-mk3.is-ok {
        --vpn-state-rgb: 52, 211, 153;
        --vpn-state-ink: #86efac;
        --vpn-state-border: rgba(74, 222, 128, 0.34);
        --vpn-state-soft: rgba(34, 197, 94, 0.12);
    }
    .vpn-shell-mk3.is-warn {
        --vpn-state-rgb: 251, 191, 36;
        --vpn-state-ink: #fde68a;
        --vpn-state-border: rgba(251, 191, 36, 0.34);
        --vpn-state-soft: rgba(251, 191, 36, 0.13);
    }
    .vpn-shell-mk3.is-bad,
    .vpn-shell-mk3.is-empty {
        --vpn-state-rgb: 248, 113, 113;
        --vpn-state-ink: #fecaca;
        --vpn-state-border: rgba(248, 113, 113, 0.34);
        --vpn-state-soft: rgba(248, 113, 113, 0.12);
    }
    .vpn-shell-mk3.is-ready {
        --vpn-state-rgb: 56, 189, 248;
        --vpn-state-ink: #bae6fd;
        --vpn-state-border: rgba(56, 189, 248, 0.34);
        --vpn-state-soft: rgba(56, 189, 248, 0.12);
    }
    .vpn-shell-mk3.is-profile-ready {
        --vpn-state-rgb: 251, 146, 60;
        --vpn-state-ink: #fed7aa;
        --vpn-state-border: rgba(251, 146, 60, 0.34);
        --vpn-state-soft: rgba(251, 146, 60, 0.12);
    }
    .vpn-shell-mk3 .vpn-hero-mk3 {
        margin: 8px 0 14px;
        padding: 22px;
        border-color: rgba(255, 255, 255, 0.10);
        background:
            radial-gradient(circle at 78% 18%, rgba(var(--vpn-state-rgb), 0.22), transparent 34%),
            radial-gradient(circle at 18% 92%, rgba(14, 165, 233, 0.14), transparent 32%),
            linear-gradient(145deg, rgba(24, 33, 52, 0.96) 0%, rgba(12, 18, 31, 0.98) 100%);
        box-shadow: 0 24px 48px rgba(0, 0, 0, 0.26), inset 0 1px 0 rgba(255, 255, 255, 0.08);
    }
    .vpn-shell-mk3 .vpn-hero-mk3::before {
        content: "";
        position: absolute;
        inset: 12px;
        border-radius: 20px;
        border: 1px solid rgba(255, 255, 255, 0.045);
        pointer-events: none;
    }
    .vpn-shell-mk3 .vpn-hero-main {
        position: relative;
        z-index: 1;
        display: grid;
        grid-template-columns: minmax(0, 1fr) 360px;
        gap: 20px;
        align-items: stretch;
    }
    .vpn-shell-mk3 .vpn-brand-block {
        max-width: none;
        padding: 6px 0;
    }
    .vpn-shell-mk3 .vpn-toolbar {
        margin-bottom: 4px;
    }
    .vpn-shell-mk3 .vpn-pill,
    .vpn-shell-mk3 .vpn-health-chip,
    .vpn-shell-mk3 .vpn-inline-note,
    .vpn-shell-mk3 .vpn-card-badge,
    .vpn-shell-mk3 .vpn-panel-live-badge,
    .vpn-shell-mk3 .vpn-inline-badge,
    .vpn-shell-mk3 .vpn-micro-badge,
    .vpn-shell-mk3 .vpn-focus-pill {
        border: 1px solid rgba(255, 255, 255, 0.10);
        background: rgba(255, 255, 255, 0.07);
        color: #dbeafe;
        backdrop-filter: blur(10px);
    }
    .vpn-shell-mk3 .vpn-pill {
        color: #a5f3fc;
        background: rgba(34, 211, 238, 0.12);
        border-color: rgba(34, 211, 238, 0.28);
    }
    .vpn-shell-mk3 .vpn-health-chip.ok,
    .vpn-shell-mk3 .vpn-badge-ok,
    .vpn-shell-mk3 .vpn-micro-badge.ok {
        background: rgba(34, 197, 94, 0.16);
        border-color: rgba(74, 222, 128, 0.30);
        color: #bbf7d0;
    }
    .vpn-shell-mk3 .vpn-health-chip.warn,
    .vpn-shell-mk3 .vpn-micro-badge.warn {
        background: rgba(245, 158, 11, 0.16);
        border-color: rgba(251, 191, 36, 0.30);
        color: #fde68a;
    }
    .vpn-shell-mk3 .vpn-health-chip.bad,
    .vpn-shell-mk3 .vpn-badge-bad,
    .vpn-shell-mk3 .vpn-micro-badge.bad {
        background: rgba(239, 68, 68, 0.16);
        border-color: rgba(248, 113, 113, 0.30);
        color: #fecaca;
    }
    .vpn-shell-mk3 .vpn-badge-neutral,
    .vpn-shell-mk3 .vpn-micro-badge.neutral {
        background: rgba(148, 163, 184, 0.12);
        color: #cbd5e1;
    }
    .vpn-shell-mk3 .vpn-hero h2,
    .vpn-shell-mk3 .vpn-brand-block h2 {
        display: block !important;
        max-width: 760px;
        margin: 0 !important;
        padding: 0 !important;
        border: 0 !important;
        background: none !important;
        font-size: clamp(30px, 3.4vw, 42px);
        line-height: 1.02;
        letter-spacing: -0.045em;
        color: #ffffff !important;
        text-decoration: none !important;
        text-shadow: 0 18px 34px rgba(0, 0, 0, 0.30);
    }
    .vpn-shell-mk3 .vpn-brand-block h2::before,
    .vpn-shell-mk3 .vpn-brand-block h2::after {
        display: none !important;
        content: none !important;
    }
    .vpn-shell-mk3 .vpn-sub {
        max-width: 680px;
        color: #b7c5d8;
        font-size: 13px;
        line-height: 1.65;
        opacity: 0.86;
    }
    .vpn-stage-line {
        display: flex;
        flex-wrap: wrap;
        gap: 10px;
        margin-top: 16px;
    }
    .vpn-stage-chip {
        position: relative;
        display: inline-flex;
        align-items: center;
        gap: 8px;
        min-height: 34px;
        padding: 7px 13px;
        border-radius: 999px;
        border: 1px solid rgba(255,255,255,0.10);
        background: rgba(255,255,255,0.06);
        color: #cbd5e1;
        font-size: 12px;
        font-weight: 800;
        letter-spacing: 0.06em;
    }
    .vpn-stage-chip::before {
        content: "";
        width: 7px;
        height: 7px;
        border-radius: 999px;
        background: currentColor;
        box-shadow: 0 0 16px currentColor;
    }
    .vpn-stage-chip.ok {
        color: #86efac;
        border-color: rgba(74, 222, 128, 0.30);
        background: rgba(34, 197, 94, 0.13);
    }
    .vpn-stage-chip.ready {
        color: #7dd3fc;
        border-color: rgba(56, 189, 248, 0.30);
        background: rgba(14, 165, 233, 0.13);
    }
    .vpn-stage-chip.warn {
        color: #fde68a;
        border-color: rgba(251, 191, 36, 0.30);
        background: rgba(245, 158, 11, 0.13);
    }
    .vpn-stage-chip.bad {
        color: #fecaca;
        border-color: rgba(248, 113, 113, 0.30);
        background: rgba(239, 68, 68, 0.13);
    }
    .vpn-command-card {
        display: grid;
        gap: 16px;
        align-content: start;
        padding: 16px;
        border-radius: 22px;
        border: 1px solid rgba(255, 255, 255, 0.11);
        background:
            linear-gradient(180deg, rgba(255, 255, 255, 0.075) 0%, rgba(255, 255, 255, 0.035) 100%);
        box-shadow: inset 0 1px 0 rgba(255,255,255,0.08);
    }
    .vpn-orb-wrap {
        display: grid;
        grid-template-columns: 96px minmax(0, 1fr);
        gap: 13px;
        align-items: center;
    }
    .vpn-orb-ring {
        position: relative;
        display: grid;
        place-items: center;
        width: 96px;
        height: 96px;
        border-radius: 999px;
        background:
            radial-gradient(circle, rgba(15, 23, 42, 0.88) 0 52%, transparent 53%),
            conic-gradient(from 220deg, rgba(var(--vpn-state-rgb), 0.14), rgba(var(--vpn-state-rgb), 0.96), rgba(var(--vpn-state-rgb), 0.14));
        color: var(--vpn-state-ink);
        box-shadow: 0 16px 32px rgba(0,0,0,0.25), 0 0 34px rgba(var(--vpn-state-rgb), 0.18);
        font-weight: 900;
        letter-spacing: -0.03em;
        text-align: center;
    }
    .vpn-orb-ring::after {
        content: "";
        position: absolute;
        inset: 12px;
        border-radius: inherit;
        border: 1px solid rgba(255, 255, 255, 0.08);
        pointer-events: none;
    }
    .vpn-orb-ring span {
        max-width: 62px;
        font-size: 16px;
        line-height: 1.12;
        word-break: break-word;
    }
    .vpn-orb-copy strong {
        display: block;
        color: #f8fafc;
        font-size: 17px;
        line-height: 1.35;
    }
    .vpn-orb-copy span {
        display: block;
        margin-top: 7px;
        color: #aebed2;
        font-size: 12px;
        line-height: 1.65;
    }
    .vpn-shell-mk3 .vpn-hero-actions {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 10px;
        min-width: 0;
        justify-content: stretch;
        align-items: stretch;
    }
    .vpn-shell-mk3 .vpn-hero-actions form {
        width: 100%;
    }
    .vpn-shell-mk3 .vpn-hero-actions .cbi-button,
    .vpn-shell-mk3 .vpn-hero-actions a.cbi-button {
        width: 100%;
        min-width: 0;
        min-height: 44px;
        border-radius: 14px;
        border: 1px solid rgba(255,255,255,0.12);
        color: #e2f5ff;
        background: rgba(255,255,255,0.08);
        box-shadow: inset 0 1px 0 rgba(255,255,255,0.08);
    }
    .vpn-shell-mk3 .vpn-hero-actions .cbi-button-apply {
        color: #06111f;
        background: linear-gradient(135deg, #67e8f9 0%, #38bdf8 52%, #60a5fa 100%);
        border: 0;
        box-shadow: 0 16px 28px rgba(34, 211, 238, 0.20);
        font-weight: 900;
    }
    .vpn-shell-mk3 .vpn-button-passive {
        color: #bbf7d0;
        background: rgba(34,197,94,0.13);
        border-color: rgba(74,222,128,0.30);
        box-shadow: none;
    }
    .vpn-shell-mk3 .vpn-copy-feedback {
        grid-column: 1 / -1;
        justify-content: flex-start;
        color: #aebed2;
    }
    .vpn-shell-mk3 .vpn-hero-note {
        margin: 0;
        max-width: none;
        border-color: rgba(var(--vpn-state-rgb), 0.22);
        background: rgba(var(--vpn-state-rgb), 0.08);
        color: #cbd5e1;
    }
    .vpn-shell-mk3 .vpn-mini-grid-mk3 {
        grid-template-columns: repeat(4, minmax(0, 1fr));
        gap: 10px;
        margin: 16px 0 14px;
    }
    .vpn-shell-mk3 .vpn-mini-card,
    .vpn-shell-mk3 .vpn-stat-card,
    .vpn-shell-mk3 .vpn-overview-grid,
    .vpn-shell-mk3 .vpn-quick-rail,
    .vpn-shell-mk3 .vpn-panel-shell,
    .vpn-shell-mk3 .vpn-entry-card,
    .vpn-shell-mk3 .cbi-map .cbi-section,
