    .vpn-shell-mk3 .vpn-stat-grid {
        grid-template-columns: 1fr 1.1fr 1fr .9fr;
        gap: 10px;
    }
    .vpn-shell-mk3 .vpn-stat-card {
        min-height: 116px;
    }
    .vpn-shell-mk3 .vpn-stat-card-remote,
    .vpn-shell-mk3 .vpn-action-tile[href*="admin/services/openvpn"],
