        background:
            linear-gradient(180deg, rgba(255,255,255,0.055) 0%, rgba(255,255,255,0.025) 100%);
    }
    .vpn-shell-mk3 .vpn-action-tile {
        border-color: rgba(255,255,255,0.10);
        background: rgba(255,255,255,0.045);
