    }
    /* NRadio OpenVPN Mk3 compact console polish */
    .vpn-shell-mk3 {
        padding: 6px 8px 18px;
    }
    .vpn-shell-mk3 .vpn-hero-mk3 {
        margin: 6px 0 12px;
        padding: 18px 20px 16px;
        border: 1px solid rgba(125, 211, 252, 0.22);
        border-radius: 16px;
        background:
            radial-gradient(circle at 76% 16%, rgba(var(--vpn-state-rgb), 0.24), transparent 34%),
            radial-gradient(circle at 14% 88%, rgba(34, 211, 238, 0.12), transparent 32%),
            linear-gradient(145deg, rgba(18, 29, 47, 0.98) 0%, rgba(7, 14, 27, 0.99) 100%);
        box-shadow: 0 22px 46px rgba(0,0,0,0.30), inset 0 -1px 0 rgba(255,255,255,0.035);
        background-clip: padding-box;
    }
    .vpn-shell-mk3 .vpn-hero-mk3::after {
        display: none !important;
        content: none !important;
        box-shadow: none !important;
    }
    .vpn-shell-mk3 .vpn-hero-mk3::before {
        inset: 1px;
        border-radius: 15px;
        border-color: rgba(125, 211, 252, 0.12);
        box-shadow: inset 0 0 30px rgba(var(--vpn-state-rgb), 0.08);
    }
    .vpn-shell-mk3 .vpn-hero-main {
        grid-template-columns: minmax(0, 1fr) minmax(300px, 420px);
        gap: 16px;
        align-items: stretch;
    }
    .vpn-shell-mk3 .vpn-brand-block h2 {
        margin-top: 16px;
        font-size: 28px !important;
        line-height: 1.16;
        letter-spacing: 0 !important;
    }
    .vpn-shell-mk3 .vpn-sub {
        max-width: 68ch;
        margin-bottom: 18px;
        line-height: 1.55;
    }
    .vpn-shell-mk3 .vpn-stage-line {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        padding: 6px;
        border: 1px solid rgba(125, 211, 252, 0.12);
        border-radius: 999px;
        background: rgba(7, 16, 29, 0.58);
        box-shadow: inset 0 1px 0 rgba(255,255,255,0.035);
    }
    .vpn-shell-mk3 .vpn-stage-chip {
        min-height: 34px;
        padding: 0 14px;
        border-color: rgba(148, 163, 184, 0.20);
        background: rgba(15, 23, 42, 0.56);
        color: rgba(226, 232, 240, 0.88);
        box-shadow: none;
    }
    .vpn-shell-mk3 .vpn-stage-chip.ok {
        border-color: rgba(74, 222, 128, 0.32);
        background: rgba(20, 83, 45, 0.34);
        color: #bbf7d0;
    }
    .vpn-shell-mk3 .vpn-stage-chip.warn,
    .vpn-shell-mk3 .vpn-stage-chip.wait {
        border-color: rgba(251, 191, 36, 0.26);
        background: rgba(120, 53, 15, 0.26);
        color: #fde68a;
    }
    .vpn-shell-mk3 .vpn-stage-chip.bad {
        border-color: rgba(248, 113, 113, 0.28);
        background: rgba(127, 29, 29, 0.28);
        color: #fecaca;
    }
    .vpn-shell-mk3 .vpn-command-card {
        display: flex;
        flex-direction: column;
        justify-content: space-between;
        min-height: 0;
        border: 1px solid rgba(var(--vpn-state-rgb), 0.28);
        border-radius: 16px;
        background:
            radial-gradient(circle at 28% 24%, rgba(var(--vpn-state-rgb), 0.18), transparent 38%),
            linear-gradient(145deg, rgba(25, 45, 58, 0.82) 0%, rgba(13, 28, 39, 0.92) 100%);
        box-shadow: 0 18px 38px rgba(0,0,0,0.24), inset 0 1px 0 rgba(255,255,255,0.055);
    }
    .vpn-shell-mk3 .vpn-orb-wrap {
        grid-template-columns: 124px minmax(0, 1fr);
        gap: 14px;
        align-items: center;
    }
    .vpn-shell-mk3 .vpn-orb-ring {
        width: 124px;
        height: 124px;
        min-width: 124px;
    }
    .vpn-shell-mk3 .vpn-orb-copy {
        min-width: 0;
        padding-left: 6px;
    }
    .vpn-shell-mk3 .vpn-orb-copy strong,
    .vpn-shell-mk3 .vpn-orb-copy span {
        max-width: 100%;
        overflow-wrap: anywhere;
    }
    .vpn-shell-mk3 .vpn-quick-rail::before,
    .vpn-shell-mk3 .vpn-command-card::before,
    .vpn-shell-mk3 .vpn-entry-card::before {
        display: none !important;
        content: none !important;
    }
    .vpn-shell-mk3 .vpn-quick-rail {
        background:
            linear-gradient(180deg, rgba(255,255,255,0.048) 0%, rgba(255,255,255,0.024) 100%),
            radial-gradient(circle at 12% 0%, rgba(var(--vpn-state-rgb), 0.08), transparent 34%);
        box-shadow: inset 0 1px 0 rgba(255,255,255,0.035);
    }
    .vpn-shell-mk3 .vpn-toolbar {
        display: grid;
        grid-template-columns: max-content max-content max-content;
        align-items: center;
        justify-content: start;
        gap: 12px 16px;
    }
    .vpn-shell-mk3 .vpn-pill,
    .vpn-shell-mk3 .vpn-health-chip,
    .vpn-shell-mk3 .vpn-inline-note {
        box-sizing: border-box;
        flex: 0 0 auto;
        height: 36px;
        min-height: 36px;
        padding: 0 14px;
        line-height: 1;
        white-space: nowrap;
        vertical-align: middle;
    }
    .vpn-shell-mk3 .vpn-pill::before,
    .vpn-shell-mk3 .vpn-health-chip::before,
    .vpn-shell-mk3 .vpn-inline-note::before {
        margin-top: 0;
    }
    .vpn-shell-mk3 #vpn-live-ts {
        position: relative;
        display: inline-flex;
        justify-content: center;
        min-width: 0;
        width: auto;
        max-width: none;
        padding-left: 30px;
        padding-right: 16px;
    }
    .vpn-shell-mk3 #vpn-live-ts::before {
        position: absolute;
        left: 14px;
        top: 50%;
        margin: 0;
        transform: translateY(-50%);
    }
    .vpn-shell-mk3 .vpn-hero-actions {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 10px;
        align-items: stretch;
    }
    .vpn-shell-mk3 .vpn-hero-actions form,
    .vpn-shell-mk3 .vpn-hero-actions .cbi-button,
    .vpn-shell-mk3 .vpn-hero-actions button.cbi-button,
    .vpn-shell-mk3 .vpn-hero-actions a.cbi-button {
        width: 100%;
        min-width: 0;
        min-height: 46px;
        border-radius: 14px;
        font-weight: 700;
    }
    .vpn-shell-mk3 .vpn-hero-actions button.cbi-button {
        appearance: none;
        font: inherit;
        cursor: pointer;
        text-align: center;
    }
    .vpn-shell-mk3 .vpn-hero-actions .is-disabled {
        opacity: 0.58;
        cursor: not-allowed;
    }
    .vpn-shell-mk3 .vpn-copy-feedback {
        grid-column: 1 / -1;
        min-height: 22px;
    }
    .vpn-shell-mk3 .vpn-mini-grid,
    .vpn-shell-mk3 .vpn-stat-grid,
    .vpn-shell-mk3 .vpn-overview-grid {
        gap: 12px;
    }
    .vpn-shell-mk3 .vpn-mini-card,
    .vpn-shell-mk3 .vpn-stat-card,
    .vpn-shell-mk3 .vpn-card {
        border-radius: 14px;
    }
    .vpn-shell-mk3 .vpn-mini-card,
    .vpn-shell-mk3 .vpn-stat-card {
        min-height: 112px;
        padding: 20px;
    }
    .vpn-shell-mk3 .vpn-stat-value {
        font-size: 28px !important;
        line-height: 1.12;
        letter-spacing: 0 !important;
    }
    .vpn-shell-mk3 .vpn-panel-shell {
        border-radius: 16px;
    }
    .vpn-shell-mk3 .vpn-panel-shell-head,
    .vpn-shell-mk3 .vpn-tabbar {
        position: sticky;
        top: 0;
        z-index: 5;
    }
    .vpn-shell-mk3 .vpn-tabbar {
        padding: 8px;
        border-radius: 14px;
        background: rgba(7, 16, 29, 0.86);
        backdrop-filter: blur(12px);
    }
    .vpn-shell-mk3 .vpn-tab-btn {
        min-height: 38px;
        letter-spacing: 0;
    }
    .vpn-shell-mk3 .vpn-tab-btn:focus,
    .vpn-shell-mk3 .vpn-tab-btn:focus-visible,
    .vpn-shell-mk3 .vpn-hero-actions .cbi-button:focus,
    .vpn-shell-mk3 .vpn-hero-actions .cbi-button:focus-visible {
        outline: 2px solid rgba(125, 211, 252, 0.72);
        outline-offset: 2px;
    }
    .vpn-shell-mk3.is-loading .vpn-mini-card strong,
    .vpn-shell-mk3.is-loading .vpn-stat-value,
    .vpn-shell-mk3.is-loading .vpn-card strong {
        position: relative;
        display: inline-block;
        min-width: 8ch;
        color: transparent !important;
        text-shadow: none !important;
        overflow: hidden;
        border-radius: 8px;
        background: rgba(148, 163, 184, 0.14);
    }
    .vpn-shell-mk3.is-loading .vpn-mini-card strong::after,
    .vpn-shell-mk3.is-loading .vpn-stat-value::after,
    .vpn-shell-mk3.is-loading .vpn-card strong::after {
        content: "";
        position: absolute;
        inset: 0;
        background: linear-gradient(90deg, transparent, rgba(125, 211, 252, 0.34), transparent);
        transform: translateX(-100%);
        animation: vpn-mk3-loading 1.18s ease-in-out infinite;
    }
    @keyframes vpn-mk3-loading {
        100% {
            transform: translateX(100%);
        }
    }
    /* OpenVPN Mk3 secondary page polish */
    .vpn-shell-secondary {
        padding: 6px 8px 16px;
    }
    .vpn-shell-secondary .vpn-hero-secondary {
        border: 1px solid rgba(125, 211, 252, 0.18);
        background:
            radial-gradient(circle at 80% 10%, rgba(56, 189, 248, 0.18), transparent 34%),
            radial-gradient(circle at 12% 90%, rgba(52, 211, 153, 0.10), transparent 30%),
            linear-gradient(145deg, rgba(15, 27, 45, 0.98) 0%, rgba(8, 15, 29, 0.99) 100%);
        box-shadow: 0 20px 42px rgba(0,0,0,0.28), inset 0 -1px 0 rgba(255,255,255,0.035);
    }
    .vpn-shell-secondary .vpn-hero-secondary::before {
        border-color: rgba(125, 211, 252, 0.10);
        box-shadow: inset 0 0 28px rgba(34, 211, 238, 0.055);
    }
    .vpn-shell-secondary .vpn-mini-card {
        border-color: rgba(125, 211, 252, 0.14);
        background:
            linear-gradient(180deg, rgba(255,255,255,0.06) 0%, rgba(255,255,255,0.026) 100%),
            rgba(10, 20, 34, 0.76);
    }
    .vpn-shell-secondary .vpn-mini-card strong {
        color: #e0f2fe;
    }
    .vpn-shell-secondary .vpn-category-rail,
    .vpn-shell-mk3 .vpn-entry-card {
        border-color: rgba(125, 211, 252, 0.16);
        background:
            radial-gradient(circle at 12% 0%, rgba(34, 211, 238, 0.10), transparent 34%),
            linear-gradient(180deg, rgba(255,255,255,0.055) 0%, rgba(255,255,255,0.024) 100%);
    }
    .vpn-shell-secondary .vpn-hero-actions .cbi-button,
    .vpn-shell-secondary .vpn-hero-actions a.cbi-button {
        min-height: 44px;
        border-radius: 14px;
        font-weight: 800;
    }
    .vpn-shell-secondary + .cbi-map,
    .cbi-map {
        border-color: rgba(125, 211, 252, 0.12) !important;
        background:
            radial-gradient(circle at 18% 0%, rgba(34, 211, 238, 0.12), transparent 30%),
            radial-gradient(circle at 88% 12%, rgba(74, 222, 128, 0.08), transparent 34%),
            linear-gradient(180deg, rgba(11, 19, 33, 0.98) 0%, rgba(8, 14, 27, 0.99) 100%) !important;
    }
    .cbi-map .cbi-section,
    .cbi-map .cbi-section-node,
    .cbi-map fieldset.cbi-section,
    .cbi-map fieldset.cbi-section-table {
        border-radius: 16px !important;
        border-color: rgba(125, 211, 252, 0.12) !important;
        background: rgba(255,255,255,0.04) !important;
    }
    .cbi-map .cbi-value {
        padding-top: 14px !important;
        padding-bottom: 14px !important;
    }
    .cbi-map .cbi-section-table-titles {
        background: rgba(15, 23, 42, 0.62) !important;
    }
    .cbi-map .vpn-entry-grid-mk3 {
        gap: 14px;
    }
    .cbi-map .vpn-entry-card {
        padding: 20px;
        border-radius: 16px;
    }
    /* OpenVPN Mk3 continuation polish */
    .vpn-shell-mk3 .vpn-brand-block {
        display: flex;
        min-height: 100%;
        flex-direction: column;
        justify-content: center;
        padding: 4px 0 6px;
    }
    .vpn-shell-mk3 .vpn-brand-block h2 {
        margin-bottom: 18px;
        text-shadow: 0 0 22px rgba(34, 211, 238, 0.22);
    }
    .vpn-shell-mk3 .vpn-sub {
        max-width: 60ch;
        color: rgba(203, 213, 225, 0.90);
    }
    .vpn-shell-mk3 .vpn-mini-grid-mk3 {
        grid-template-columns: minmax(240px, 1.15fr) repeat(3, minmax(160px, 1fr));
    }
    .vpn-shell-mk3 .vpn-mini-card {
        border-color: rgba(125, 211, 252, 0.13);
        background:
            radial-gradient(circle at 12% 0%, rgba(var(--vpn-state-rgb), 0.09), transparent 32%),
            linear-gradient(180deg, rgba(255,255,255,0.055) 0%, rgba(255,255,255,0.022) 100%);
    }
    .vpn-shell-mk3 .vpn-mini-card-accent {
        border-color: rgba(var(--vpn-state-rgb), 0.26);
        background:
            radial-gradient(circle at 14% 0%, rgba(var(--vpn-state-rgb), 0.16), transparent 34%),
            linear-gradient(180deg, rgba(255,255,255,0.072) 0%, rgba(255,255,255,0.026) 100%);
    }
    .vpn-shell-mk3 .vpn-quick-rail {
        border-color: rgba(125, 211, 252, 0.14);
        border-radius: 16px;
    }
    .vpn-shell-mk3 .vpn-action-list-compact {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 10px;
    }
    .vpn-shell-mk3 .vpn-action-tile {
        min-height: 78px;
        border-color: rgba(125, 211, 252, 0.14);
        background:
            linear-gradient(180deg, rgba(255,255,255,0.052), rgba(255,255,255,0.024)),
            rgba(7, 16, 29, 0.62);
    }
    .vpn-shell-mk3 .vpn-action-tile strong {
        color: #e0f2fe;
    }
    .vpn-shell-mk3 .vpn-panel-shell {
        border-color: rgba(125, 211, 252, 0.13);
        background:
            radial-gradient(circle at 8% 0%, rgba(34, 211, 238, 0.09), transparent 26%),
            linear-gradient(180deg, rgba(255,255,255,0.045) 0%, rgba(255,255,255,0.018) 100%);
    }
    .vpn-shell-mk3 .vpn-panel-shell-kicker {
        color: #7dd3fc;
        letter-spacing: 0;
    }
    .vpn-shell-mk3 .vpn-tab-btn.is-active {
        color: #06111f;
        background: linear-gradient(135deg, #67e8f9 0%, #38bdf8 58%, #5eead4 100%);
        box-shadow: 0 12px 24px rgba(34, 211, 238, 0.18);
    }
    .vpn-shell-secondary .vpn-mini-grid {
        grid-template-columns: repeat(4, minmax(0, 1fr));
    }
    .vpn-shell-secondary .vpn-mini-card {
        padding: 18px;
    }
    .vpn-shell-secondary .vpn-category-rail .vpn-toolbar {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
    }
    .cbi-map input[type="text"],
    .cbi-map input[type="password"],
    .cbi-map input[type="file"],
    .cbi-map textarea,
    .cbi-map select {
        border-radius: 12px !important;
    }
    .cbi-map .cbi-button,
    .cbi-map .btn.cbi-button,
    .cbi-map .cbi-button-add,
    .cbi-map .cbi-button-reset {
        min-height: 40px;
        border-radius: 12px !important;
        font-weight: 700;
    }
    .cbi-map .vpn-entry-head {
        align-items: center;
        gap: 12px;
    }
    .cbi-map .vpn-entry-badge {
        border-radius: 999px;
        padding: 5px 10px;
    }
    @media (min-width: 981px) {
        .vpn-shell-mk3 .vpn-panel {
            min-height: 300px;
        }
    }
    @media (max-width: 980px) {
        .vpn-shell-mk3 .vpn-hero-main {
            grid-template-columns: 1fr;
        }
        .vpn-shell-mk3 .vpn-command-card {
            min-height: auto;
        }
        .vpn-shell-mk3 .vpn-mini-grid-mk3,
        .vpn-shell-mk3 .vpn-action-list-compact,
        .vpn-shell-secondary .vpn-mini-grid {
            grid-template-columns: 1fr 1fr;
        }
        .vpn-shell-mk3 .vpn-orb-wrap {
            grid-template-columns: 124px minmax(0, 1fr);
            justify-items: start;
            text-align: left;
        }
    }
    @media (max-width: 640px) {
        .vpn-shell-mk3 {
            padding: 4px 5px 14px;
        }
        .vpn-shell-mk3 .vpn-hero-mk3 {
            padding: 16px;
        }
        .vpn-shell-mk3 .vpn-hero-actions {
            grid-template-columns: 1fr;
        }
        .vpn-shell-mk3 .vpn-mini-grid-mk3,
        .vpn-shell-mk3 .vpn-action-list-compact,
        .vpn-shell-secondary .vpn-mini-grid {
            grid-template-columns: 1fr;
        }
        .vpn-shell-mk3 .vpn-orb-wrap {
            grid-template-columns: 1fr;
        }
        .vpn-shell-mk3 .vpn-orb-ring {
            width: 112px;
            height: 112px;
            min-width: 112px;
        }
        .vpn-shell-mk3 .vpn-pill,
        .vpn-shell-mk3 .vpn-health-chip,
        .vpn-shell-mk3 .vpn-inline-note {
            height: 34px;
            min-height: 34px;
            padding: 0 11px;
        }
        .vpn-shell-mk3 .vpn-toolbar {
            flex-wrap: wrap;
        }
        .vpn-stage-chip {
            min-height: 34px;
        }
    }
</style>
EOF_OPENVPN_LEGACY_UNUSED_CSS_OLD
    cat > /usr/lib/lua/luci/view/openvpn/pageswitch.htm <<'EOF_OPENVPN_PAGESWITCH'
<%#
 Copyright 2008 Steven Barth <steven@midlink.org>
 Copyright 2008 Jo-Philipp Wich <jow@openwrt.org>
 Licensed to the public under the Apache License 2.0.
-%>

<%+openvpn/ovpn_css%>

<%
local mode = self.mode or "basic"
local uci = require("luci.model.uci").cursor()
local category_title = nil
local instance = self.instance or "-"
local cfg_path = uci:get("openvpn", instance, "config") or "-"
local enabled = uci:get("openvpn", instance, "enabled")
local proto = uci:get("openvpn", instance, "proto") or "-"
local port = uci:get("openvpn", instance, "port") or "-"
local route_noexec = uci:get("openvpn", instance, "route_noexec") == "1" and "手动路由" or "自动路由"
local enabled_label = (enabled == "1") and "已启用" or "未启用"
local mode_label = "高级配置"
local mode_desc = "适合查看与编辑更细粒度的 OpenVPN 参数分组。"
local primary_href = url("admin/services/openvpn/basic", self.instance)
local primary_label = "切换到基础配置"
if mode == "advanced" then
    for _, c in ipairs(self.categories or {}) do
        if c.id == self.category then
            category_title = c.title
            break
        end
    end
elseif mode == "basic" then
    mode_label = "基础配置"
    mode_desc = "适合快速修改常用参数，保存后会自动应用到当前实例。"
    primary_href = url("admin/services/openvpn/advanced", self.instance)
    primary_label = "切换到高级配置"
elseif mode == "file" then
    mode_label = "文件编辑"
    mode_desc = "适合直接维护 ovpn 原始配置和 auth-user-pass 凭据文件。"
    primary_href = url("admin/services/openvpn")
    primary_label = "返回标准 OpenVPN"
end
%>

<div class="vpn-shell vpn-shell-refined vpn-shell-mk5 vpn-shell-secondary vpn-shell-config">
  <div class="vpn-hero vpn-hero-mk5 vpn-hero-secondary vpn-hero-config">
    <div class="vpn-toolbar">
      <span class="vpn-pill">OpenVPN</span>
      <span class="vpn-status-chip vpn-mode-chip"><%=mode_label%></span>
    </div>
    <h2 class="vpn-page-title">
      <a href="<%=url('admin/services/openvpn')%>">标准 OpenVPN</a> &#187;
      实例 <%=pcdata(self.instance)%>
    </h2>
    <p class="vpn-sub">
      <%=mode_desc%>
    </p>
    <div class="vpn-secondary-summary">
      <span class="vpn-summary-instance">实例 <strong><%=pcdata(instance)%></strong></span>
      <span class="vpn-summary-path">配置 <strong><%=pcdata(cfg_path)%></strong></span>
      <span class="vpn-summary-route">路由 <strong><%=route_noexec%></strong></span>
    </div>
    <div class="vpn-hero-actions vpn-hero-actions-config">
      <a class="cbi-button cbi-button-apply" href="<%=primary_href%>"><%=primary_label%></a>
      <a class="cbi-button" href="<%=url('nradioadv/system/openvpnfull')%>">返回控制台</a>
    </div>
  </div>

  <div class="vpn-mini-grid">
    <div class="vpn-mini-card vpn-mini-card-accent vpn-mini-card-instance">
      <span class="vpn-mini-label">当前实例</span>
      <strong><%=pcdata(instance)%></strong>
      <span class="vpn-mini-note">当前正在编辑的 OpenVPN UCI 节点</span>
    </div>
    <div class="vpn-mini-card vpn-mini-card-source">
      <span class="vpn-mini-label">配置来源</span>
      <strong><%=pcdata(cfg_path)%></strong>
      <span class="vpn-mini-note">若使用外部 ovpn 文件，这里显示保存路径</span>
    </div>
    <div class="vpn-mini-card vpn-mini-card-status">
      <span class="vpn-mini-label">实例状态</span>
      <strong><%=enabled_label%></strong>
      <span class="vpn-mini-note">协议：<%=pcdata(proto)%> · 端口：<%=pcdata(port)%></span>
    </div>
    <div class="vpn-mini-card vpn-mini-card-route">
      <span class="vpn-mini-label">路由模式</span>
      <strong><%=route_noexec%></strong>
      <span class="vpn-mini-note">用于判断当前实例是否交给外部脚本接管</span>
    </div>
  </div>

  <% if mode == "advanced" then %>
    <div class="vpn-card vpn-category-rail vpn-category-rail-mk5">
      <div class="vpn-card-title">高级分类</div>
      <div class="vpn-toolbar">
        <% for i, c in ipairs(self.categories or {}) do %>
          <% if c.id == self.category then %>
            <span class="vpn-status-chip"><%=c.title%></span>
          <% else %>
            <a class="vpn-pill" href="<%=luci.dispatcher.build_url('admin','services','openvpn','advanced', self.instance, c.id)%>"><%=c.title%></a>
          <% end %>
        <% end %>
      </div>
      <% if category_title then %>
        <div class="vpn-mini-note vpn-category-current">当前分类：<strong><%=category_title%></strong></div>
      <% end %>
    </div>
  <% end %>
</div>
EOF_OPENVPN_PAGESWITCH

    cat > /usr/lib/lua/luci/view/openvpn/cbi-select-input-add.htm <<'EOF_OPENVPN_SELECT_INPUT_ADD'

<script type="text/javascript">
//<![CDATA[
	function vpn_add()
	{
		var vpn_name     = div_add.querySelector("#instance_name1").value.replace(/[^\x00-\x7F]|[\s\.!@#$%^&*()\-+=\[\]{};':"\\|,<>\/?]/g,'');
		var vpn_template = div_add.querySelector("#instance_template").value;
		var form         = document.getElementsByName('cbi')[0];

		if (!vpn_name || !vpn_name.length)
		{
			return info_message(vpn_output, "实例名称不能为空。", 2000);
		}

		document.getElementById("instance_name1").value = vpn_name;
		if (document.getElementById("cbi-openvpn-" + vpn_name) != null)
		{
			return info_message(vpn_output, "该实例名称已存在，请更换一个名称。", 2000);
		}

		if (!vpn_template || !vpn_template.length)
		{
			return info_message(vpn_output, "请选择一个可用的模板。", 2000);
		}

		if (form)
		{
			form.submit();
		}
	}

	function vpn_upload()
	{
		var vpn_name = div_upload.querySelector("#instance_name2").value.replace(/[^\x00-\x7F]|[\s\.!@#$%^&*()\-+=\[\]{};':"\\|,<>\/?]/g,'');
		var vpn_file = document.getElementById("ovpn_file").value;
		var form     = document.getElementsByName('cbi')[0];

		if (!vpn_name || !vpn_name.length)
		{
			return info_message(vpn_output, "实例名称不能为空。", 2000);
		}

		document.getElementById("instance_name2").value = vpn_name;
		if (document.getElementById("cbi-openvpn-" + vpn_name) != null)
		{
			return info_message(vpn_output, "该实例名称已存在，请更换一个名称。", 2000);
		}

		if (!vpn_file || !vpn_file.length)
		{
			return info_message(vpn_output, "请选择一个有效的 OVPN 配置文件。", 2000);
		}

		if (form)
		{
			form.enctype = 'multipart/form-data';
			form.action  = '<%=url('admin/services/openvpn/upload')%>';
			form.submit();
		}
	}

	function info_message(output, msg, timeout)
	{
		timeout = timeout || 0;
		output.innerHTML = '<em>' + msg + '</em>';
		if (timeout > 0)
		{
			setTimeout(function(){ output.innerHTML=""}, timeout);
		}
	}
//]]>
</script>

<%+openvpn/ovpn_css%>

<div class="vpn-entry-grid vpn-entry-grid-mk5 vpn-entry-grid-import">
	<div class="vpn-entry-card vpn-entry-card-template" id="div_add">
		<div class="vpn-entry-head">
			<h4>模板创建</h4>
			<span class="vpn-entry-badge vpn-entry-badge-template">模板</span>
		</div>
		<p class="vpn-entry-lead">适合快速生成一个标准 OpenVPN 实例，再进入基础配置或高级配置继续细化。</p>
		<label class="vpn-field-label" for="instance_name1">实例名称</label>
		<input type="text" maxlength="20" placeholder="例如 custom_config" name="cbi.cts.<%=self.config%>.<%=self.sectiontype%>.text" id="instance_name1" />
		<div class="vpn-field-help">仅允许字母、数字和下划线。创建后会出现在实例列表中。</div>
		<label class="vpn-field-label" for="instance_template">模板</label>
		<select id="instance_template" name="cbi.cts.<%=self.config%>.<%=self.sectiontype%>.select">
			<option value="" selected="selected" disabled="disabled">请选择模板...</option>
			<%- for k, v in luci.util.kspairs(self.add_select_options) do %>
				<option value="<%=k%>"><%=pcdata(v)%></option>
			<% end -%>
		</select>
		<div class="vpn-field-help">模板会预填一组常用参数，后续仍可继续编辑。</div>
		<div class="vpn-entry-actions vpn-entry-actions-template">
			<input class="btn cbi-button cbi-button-add" type="submit" onclick="vpn_add(); return false;" value="创建实例" title="创建模板实例" />
		</div>
	</div>

	<div class="vpn-entry-card vpn-entry-card-upload" id="div_upload">
		<div class="vpn-entry-head">
			<h4>OVPN 文件上传</h4>
			<span class="vpn-entry-badge vpn-badge-neutral vpn-entry-badge-upload">兼容</span>
		</div>
		<p class="vpn-entry-lead">导入现有客户端文件。上传后会创建实例，并将配置保存到 <code>/etc/openvpn/&lt;name&gt;.ovpn</code>。</p>
		<label class="vpn-field-label" for="instance_name2">实例名称</label>
		<input type="text" maxlength="20" placeholder="例如 custom_config" name="instance_name2" id="instance_name2" />
		<div class="vpn-field-help">实例名称将用作文件名和列表名称。</div>
		<label class="vpn-field-label" for="ovpn_file">配置文件</label>
		<input type="file" name="ovpn_file" id="ovpn_file" accept="application/x-openvpn-profile,.ovpn" />
		<div class="vpn-field-help">支持标准 `.ovpn` 客户端配置文件，上传后可回到控制台核对运行状态。</div>
		<div class="vpn-entry-actions vpn-entry-actions-upload">
			<input class="btn cbi-button cbi-button-add" type="submit" onclick="vpn_upload(); return false;" value="上传导入" title="上传 ovpn 文件" />
		</div>
	</div>
</div>

<div class="vpn-output vpn-output-entry" role="status" aria-live="polite">
	<span id="vpn_output"></span>
</div>
EOF_OPENVPN_SELECT_INPUT_ADD

    cat > /usr/lib/lua/luci/view/openvpn/overview_intro.htm <<'EOF_OPENVPN_OVERVIEW_INTRO'
<%+openvpn/ovpn_css%>

<div class="vpn-shell vpn-shell-refined vpn-shell-mk5 vpn-shell-secondary vpn-shell-overview">
  <div class="vpn-hero vpn-hero-mk5 vpn-hero-secondary vpn-hero-overview">
    <div class="vpn-hero-top">
      <div class="vpn-brand-block">
        <div class="vpn-toolbar">
          <span class="vpn-pill">OpenVPN</span>
          <span class="vpn-status-chip">标准实例管理</span>
        </div>
        <h2>标准 OpenVPN</h2>
        <p class="vpn-sub">新建模板实例、导入 ovpn 文件，或维护原生 OpenVPN 节点；运行状态回到控制台查看。</p>
        <div class="vpn-secondary-summary">
          <span class="vpn-summary-instance">实例 <strong><%=self.instance_count or 0%></strong></span>
          <span class="vpn-summary-enabled">启用 <strong><%=self.enabled_count or 0%></strong></span>
          <span class="vpn-summary-running">运行 <strong><%=self.running_count or 0%></strong></span>
        </div>
      </div>
      <div class="vpn-hero-actions vpn-hero-actions-overview">
        <a class="cbi-button cbi-button-apply" href="<%=url('nradioadv/system/openvpnfull')%>">返回控制台</a>
      </div>
    </div>

    <div class="vpn-mini-grid">
      <div class="vpn-mini-card vpn-mini-card-accent">
        <span class="vpn-mini-label">实例总数</span>
        <strong><%=self.instance_count or 0%></strong>
        <span class="vpn-mini-note">当前 UCI 中已注册的 OpenVPN 实例数量</span>
      </div>
      <div class="vpn-mini-card vpn-mini-card-enabled">
        <span class="vpn-mini-label">启用实例</span>
        <strong><%=self.enabled_count or 0%></strong>
        <span class="vpn-mini-note">已开启 `enabled` 的实例数量</span>
      </div>
      <div class="vpn-mini-card vpn-mini-card-status">
        <span class="vpn-mini-label">运行实例</span>
        <strong><%=self.running_count or 0%></strong>
        <span class="vpn-mini-note">当前检测到仍在运行的进程数量</span>
      </div>
      <div class="vpn-mini-card vpn-mini-card-route">
        <span class="vpn-mini-label">文件型实例</span>
        <strong><%=self.file_cfg_count or 0%></strong>
        <span class="vpn-mini-note">配置来源为外部 `.ovpn` 文件的实例数量</span>
      </div>
    </div>
  </div>
</div>
EOF_OPENVPN_OVERVIEW_INTRO

    cat > /usr/lib/lua/luci/view/openvpn/nsection.htm <<'EOF_OPENVPN_NSECTION'
<% if self:cfgvalue(self.section) then section = self.section %>
	<fieldset class="cbi-section vpn-cbi-section vpn-cbi-section-mk5 vpn-cbi-section-active">
		<% if self.title and #self.title > 0 then -%>
			<div class="vpn-section-title"><%=self.title%></div>
		<%- end %>
		<% if self.description and #self.description > 0 then -%>
			<div class="cbi-section-descr vpn-cbi-descr"><%=self.description%></div>
		<%- end %>
		<% if self.addremove then -%>
			<div class="cbi-section-remove right">
				<input type="submit" class="cbi-button" name="cbi.rns.<%=self.config%>.<%=section%>" value="<%:Delete%>" />
			</div>
		<%- end %>
		<%+cbi/tabmenu%>
		<div class="cbi-section-node<% if self.tabs then %> cbi-section-node-tabbed<% end %>" id="cbi-<%=self.config%>-<%=section%>">
			<%+cbi/ucisection%>
		</div>
		<br />
	</fieldset>
<% elseif self.addremove then %>
	<% if self.template_addremove then include(self.template_addremove) else -%>
	<fieldset class="cbi-section vpn-cbi-section vpn-cbi-section-mk5 vpn-cbi-section-empty" id="cbi-<%=self.config%>-<%=self.section%>">
		<% if self.title and #self.title > 0 then -%>
			<div class="vpn-section-title"><%=self.title%></div>
		<%- end %>
		<div class="cbi-section-descr vpn-cbi-descr"><%=self.description%></div>
		<input type="submit" class="cbi-button cbi-button-add" name="cbi.cns.<%=self.config%>.<%=self.section%>" value="<%:Add%>" />
	</fieldset>
	<%- end %>
<% end %>
EOF_OPENVPN_NSECTION

    cat >> /usr/lib/lua/luci/view/openvpn/ovpn_css.htm <<'EOF_OPENVPN_MK3_FINAL_POLISH'
<style type="text/css">
