    .vpn-panel {
        display: none;
        padding: 18px;
    }
    .vpn-panel.is-active {
        display: block;
        background: rgba(255,255,255,0.018);
    }
    .vpn-panel-major.is-active {
        min-height: 300px;
    }
    .vpn-focus-strip {
        display: flex;
        flex-wrap: wrap;
        gap: 8px;
        margin: 14px 0;
    }
    .vpn-panel pre,
    .vpn-subcard pre,
    .vpn-output {
        width: 100%;
        min-height: 220px;
        margin: 12px 0 0;
        padding: 14px;
        overflow: auto;
        border: 1px solid rgba(125, 211, 252, 0.16);
        border-radius: 8px;
        color: #dbeafe;
        background: #06101c;
        font-family: Consolas, "Cascadia Mono", monospace;
        font-size: 12px;
        line-height: 1.58;
        white-space: pre-wrap;
    }
    .vpn-copy-source {
        position: absolute;
        left: -9999px;
        width: 1px;
        height: 1px;
        opacity: 0;
    }
    .vpn-check-list {
        display: grid;
        gap: 10px;
        margin-top: 12px;
    }
    .vpn-check-row,
    .vpn-check-empty {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 12px;
        padding: 12px;
        border: 1px solid rgba(148, 163, 184, 0.15);
        border-radius: 8px;
        background: rgba(255,255,255,0.035);
    }
    .vpn-check-main {
        min-width: 0;
    }
    .vpn-check-main strong {
        display: block;
        color: #f8fafc;
        font-size: 13px;
        line-height: 1.4;
        overflow-wrap: anywhere;
    }
    .vpn-check-main span {
        display: block;
        margin-top: 5px;
        color: var(--vpn-muted);
        font-size: 12px;
        line-height: 1.5;
    }
    .vpn-check-badges {
        display: flex;
        flex-wrap: wrap;
        justify-content: flex-end;
        gap: 6px;
    }
    .vpn-shell-secondary {
        max-width: 1220px;
        margin: 0 auto 12px;
        padding: 8px;
    }
    .vpn-shell-secondary .vpn-hero-secondary {
        padding: 20px;
    }
    .vpn-shell-secondary .vpn-hero-top {
        position: relative;
        z-index: 1;
        display: grid;
        grid-template-columns: minmax(0, 1fr) auto;
        gap: 18px;
        align-items: start;
    }
    .vpn-shell-secondary .vpn-mini-grid {
        grid-template-columns: repeat(4, minmax(0, 1fr));
        margin-top: 16px;
    }
    .vpn-shell-secondary .vpn-category-rail {
        margin-top: 12px;
        padding: 16px;
    }
    .vpn-shell-secondary .vpn-category-rail .vpn-toolbar {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(128px, 1fr));
        margin-top: 12px;
    }
    .vpn-entry-grid-mk3 {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
    .vpn-entry-card {
        position: relative;
        padding: 18px;
    }
    .vpn-entry-badge {
        display: inline-flex;
        align-items: center;
        min-height: 28px;
        padding: 0 10px;
        border: 1px solid rgba(74, 222, 128, 0.34);
        border-radius: 999px;
        color: #bbf7d0;
        background: rgba(34, 197, 94, 0.16);
        font-size: 12px;
        font-weight: 800;
    }
    .vpn-shell-secondary + .cbi-map,
    .cbi-map {
        max-width: 1220px;
        margin: 0 auto 18px;
        padding: 10px !important;
        border: 1px solid rgba(125, 211, 252, 0.13) !important;
        border-radius: 8px !important;
        color: #e5edf7;
        background:
            linear-gradient(180deg, rgba(11, 19, 33, 0.98), rgba(8, 14, 27, 0.99)) !important;
    }
    .cbi-map .cbi-section,
    .cbi-map .cbi-section-node,
    .cbi-map fieldset.cbi-section,
    .cbi-map fieldset.cbi-section-table {
        margin-bottom: 14px !important;
        padding: 18px !important;
        border: 1px solid rgba(125, 211, 252, 0.14) !important;
        border-radius: 8px !important;
        background: rgba(255,255,255,0.04) !important;
        box-shadow: inset 0 1px 0 rgba(255,255,255,0.035) !important;
    }
    .cbi-map .cbi-section > h3,
    .cbi-map .cbi-section-node > h3,
    .cbi-map .cbi-section > h4,
    .cbi-map .cbi-section-node > h4,
    .cbi-map .cbi-section legend,
    .cbi-map .cbi-section-table legend,
    .vpn-cbi-section .vpn-section-title {
        margin: 0 0 14px !important;
        padding: 0 0 10px !important;
        border-bottom: 1px solid rgba(148, 163, 184, 0.16) !important;
        color: #f8fafc !important;
        background: transparent !important;
        font-size: 17px !important;
        font-weight: 900 !important;
        line-height: 1.35 !important;
    }
    .cbi-map .cbi-section-descr,
    .cbi-map .cbi-value-description,
    .cbi-map .cbi-section-table-descr {
        color: var(--vpn-muted) !important;
        font-size: 12px !important;
        line-height: 1.62 !important;
    }
    .cbi-map .cbi-value {
        display: grid !important;
        grid-template-columns: minmax(180px, 0.36fr) minmax(0, 1fr);
        gap: 14px;
        align-items: start;
        padding: 14px 0 !important;
        border-top: 1px solid rgba(148, 163, 184, 0.12);
    }
    .cbi-map .cbi-value-title,
    .cbi-map label {
        color: #f8fafc !important;
        font-size: 13px !important;
        font-weight: 850 !important;
        line-height: 1.45 !important;
    }
    .cbi-map .cbi-value-field {
        min-width: 0;
    }
    .cbi-map input[type="text"],
    .cbi-map input[type="password"],
    .cbi-map input[type="file"],
    .cbi-map textarea,
    .cbi-map select,
    .vpn-entry-card input[type="text"],
    .vpn-entry-card input[type="file"],
    .vpn-entry-card select {
        width: 100%;
        max-width: 100%;
        min-height: 42px;
        padding: 9px 12px !important;
        border: 1px solid rgba(125, 211, 252, 0.22) !important;
        border-radius: 8px !important;
        color: #e5edf7 !important;
        background: rgba(3, 7, 18, 0.60) !important;
        outline: none;
    }
    .cbi-map textarea {
        min-height: 170px;
        resize: vertical;
        font-family: Consolas, "Cascadia Mono", monospace;
        line-height: 1.55;
    }
    .cbi-map input:focus,
    .cbi-map textarea:focus,
    .cbi-map select:focus {
        border-color: rgba(103, 232, 249, 0.70) !important;
        box-shadow: 0 0 0 3px rgba(34, 211, 238, 0.12) !important;
    }
    .cbi-map .cbi-section-table-titles,
    .cbi-map .tr.table-titles,
    .cbi-map tr.cbi-section-table-titles {
        color: #e0f2fe !important;
        background: rgba(15, 23, 42, 0.72) !important;
    }
    .cbi-map .cbi-section-table-cell,
    .cbi-map td,
    .cbi-map th {
        border-color: rgba(148, 163, 184, 0.14) !important;
        color: #dbeafe !important;
    }
    .cbi-map code {
        padding: 2px 6px;
        border-radius: 6px;
        color: #a5f3fc !important;
        background: rgba(255,255,255,0.08) !important;
    }
    .vpn-shell-mk3 .vpn-hero-summary-item,
    .vpn-shell-mk3 .vpn-command-card,
    .vpn-shell-mk3 .vpn-mini-card,
    .vpn-shell-mk3 .vpn-stat-card,
    .vpn-shell-mk3 .vpn-panel-shell,
    .vpn-shell-mk3 .vpn-action-tile,
    .vpn-shell-secondary .vpn-mini-card,
    .vpn-shell-secondary + .cbi-map .cbi-section {
        transition: border-color .18s ease, background-color .18s ease, transform .18s ease, box-shadow .18s ease;
    }
    .vpn-shell-mk3 .vpn-hero-summary-item:hover,
    .vpn-shell-mk3 .vpn-action-tile:hover,
    .vpn-shell-secondary .vpn-mini-card:hover {
        transform: translateY(-1px);
        border-color: rgba(103, 232, 249, 0.36);
        box-shadow: 0 12px 24px rgba(0, 0, 0, 0.20);
    }
    .vpn-shell-mk3 .vpn-tab-btn:focus,
    .vpn-shell-mk3 .vpn-tab-btn:focus-visible,
    .vpn-shell-mk3 .vpn-hero-actions .cbi-button:focus,
    .vpn-shell-mk3 .vpn-hero-actions .cbi-button:focus-visible,
    .vpn-shell-mk3 .vpn-action-tile:focus-visible {
        outline: 2px solid rgba(103, 232, 249, 0.72);
        outline-offset: 2px;
    }
    .vpn-shell-mk3.is-loading .vpn-mini-card strong,
    .vpn-shell-mk3.is-loading .vpn-stat-value,
    .vpn-shell-mk3.is-loading .vpn-card strong {
        color: #cbd5e1;
    }
    /* Mk3 viewport polish: keep the control card in the first row */
    .vpn-shell-mk3 .vpn-brand-block {
        justify-content: flex-start;
        gap: 14px;
        padding: 26px 28px;
        background:
            linear-gradient(180deg, rgba(15, 31, 52, 0.86), rgba(8, 16, 29, 0.72)),
            rgba(7, 16, 29, 0.74);
    }
    .vpn-shell-mk3 .vpn-brand-block h2 {
        position: relative;
        width: fit-content;
        margin-bottom: 2px;
        padding-bottom: 13px;
        border-bottom: 0;
        font-size: 32px;
    }
    .vpn-shell-mk3 .vpn-brand-block h2::after {
        content: "";
        position: absolute;
        left: 0;
        bottom: 0;
        width: 100%;
        height: 3px;
        border-radius: 999px;
        background: linear-gradient(90deg, #22d3ee, #34d399);
        box-shadow: 0 0 18px rgba(34, 211, 238, 0.34);
    }
    .vpn-shell-mk3 .vpn-brand-block .vpn-toolbar {
        margin: 4px 0 2px;
        order: 2;
    }
    .vpn-shell-mk3 .vpn-sub {
        max-width: 58ch;
        order: 3;
        padding-top: 8px;
        border-top: 1px solid rgba(148, 163, 184, 0.14);
    }
    .vpn-shell-mk3 .vpn-hero-summary {
        order: 4;
        margin-top: 8px;
        padding: 10px;
        border: 1px solid rgba(125, 211, 252, 0.11);
        border-radius: 8px;
        background: rgba(3, 7, 18, 0.24);
    }
    .vpn-shell-mk3 .vpn-hero-summary-item {
        min-height: 86px;
        display: flex;
        flex-direction: column;
        justify-content: center;
        padding: 12px 14px;
    }
    .vpn-shell-mk3 .vpn-command-card {
        display: flex;
        min-height: 100%;
        flex-direction: column;
        justify-content: flex-start;
        padding: 26px 28px;
        background:
            linear-gradient(180deg, rgba(var(--vpn-state-rgb), 0.16), rgba(255,255,255,0.030)),
            rgba(8, 28, 30, 0.72);
    }
    .vpn-shell-mk3 .vpn-command-kicker {
        display: inline-flex;
        width: fit-content;
        min-height: 32px;
        align-items: center;
        padding: 0 12px;
        border: 1px solid rgba(125, 211, 252, 0.24);
        border-radius: 999px;
        background: rgba(8, 145, 178, 0.16);
    }
    .vpn-shell-mk3 .vpn-orb-wrap {
        flex: 0 0 auto;
        margin-top: 12px;
        padding: 20px;
        grid-template-columns: 118px minmax(0, 1fr);
        gap: 20px;
        justify-items: start;
        overflow: visible;
    }
    .vpn-shell-mk3 .vpn-orb-ring {
        width: 118px;
        height: 118px;
        min-width: 118px;
        border-width: 12px;
    }
    .vpn-shell-mk3 .vpn-orb-copy strong {
        max-width: none;
        font-size: clamp(22px, 2.1vw, 27px);
        line-height: 1.22;
        word-break: keep-all;
        overflow-wrap: break-word;
    }
    .vpn-shell-mk3 .vpn-orb-copy span {
        max-width: 100%;
        font-size: 14px;
        line-height: 1.72;
        word-break: normal;
        overflow-wrap: anywhere;
    }
    .vpn-shell-mk3 .vpn-orb-copy {
        width: 100%;
        min-width: 0;
    }
    .vpn-shell-mk3 .vpn-hero-actions {
        margin-top: 18px;
        gap: 14px;
    }
    .vpn-shell-mk3 .vpn-hero-note {
        margin-top: 14px;
        padding: 13px 15px;
        border-color: rgba(var(--vpn-state-rgb), 0.36);
        background: rgba(var(--vpn-state-rgb), 0.12);
    }
    .vpn-shell-mk3 .vpn-hero-actions .cbi-button,
    .vpn-shell-mk3 .vpn-hero-actions a.cbi-button,
    .vpn-shell-mk3 .vpn-hero-actions button.cbi-button {
        min-height: 48px;
        font-size: 15px;
    }
    /* Mk3 closure polish: secondary pages, forms and action surfaces */
    .vpn-shell-secondary .vpn-hero-secondary {
        padding: 22px 28px;
        background:
            linear-gradient(180deg, rgba(15, 31, 52, 0.90), rgba(8, 16, 29, 0.76)),
            rgba(7, 16, 29, 0.78);
    }
    .vpn-shell-secondary .vpn-page-title {
        width: fit-content;
        max-width: 100%;
        margin-top: 20px;
        margin-bottom: 16px;
        padding-bottom: 13px;
        font-size: 26px;
        line-height: 1.22;
        border-bottom: 3px solid #22d3ee;
        text-shadow: 0 0 18px rgba(34, 211, 238, 0.22);
    }
    .vpn-shell-secondary .vpn-sub {
        max-width: 78ch;
        padding-top: 14px;
        border-top: 1px solid rgba(148, 163, 184, 0.14);
    }
    .vpn-shell-secondary .vpn-secondary-summary {
        margin-top: 18px;
        gap: 14px;
        padding: 10px;
        border: 1px solid rgba(125, 211, 252, 0.12);
        border-radius: 8px;
        background: rgba(3, 7, 18, 0.22);
    }
    .vpn-shell-secondary .vpn-secondary-summary span {
        min-height: 78px;
        display: flex;
        flex-direction: column;
        justify-content: center;
        padding: 12px 14px;
    }
    .vpn-shell-secondary .vpn-secondary-summary strong {
        font-size: 15px;
        overflow-wrap: anywhere;
        word-break: normal;
    }
    .vpn-shell-secondary .vpn-hero-actions {
        display: flex;
        justify-content: flex-end;
        gap: 10px;
        margin-top: 16px;
        padding: 12px;
        border: 1px solid rgba(125, 211, 252, 0.12);
        border-radius: 8px;
        background: rgba(3, 7, 18, 0.20);
    }
    .vpn-shell-secondary .vpn-hero-actions .cbi-button,
    .vpn-shell-secondary .vpn-hero-actions a.cbi-button {
        width: auto;
        min-width: 176px;
        min-height: 42px;
        padding: 0 18px !important;
        flex: 0 0 auto;
        border-color: rgba(125, 211, 252, 0.28) !important;
    }
    .vpn-shell-secondary .vpn-hero-actions .cbi-button-apply {
        min-width: 214px;
        box-shadow: 0 10px 22px rgba(34, 211, 238, 0.14);
    }
    .vpn-shell-secondary .vpn-mini-grid {
        gap: 16px;
        margin-top: 18px;
    }
    .vpn-shell-secondary .vpn-mini-card {
        min-height: 118px;
        padding: 18px 20px;
        background:
            linear-gradient(180deg, rgba(255,255,255,0.050), rgba(255,255,255,0.020)),
            rgba(8, 16, 29, 0.72);
    }
    .vpn-shell-secondary .vpn-mini-card strong {
        font-size: 20px;
        overflow-wrap: anywhere;
    }
    .vpn-shell-secondary .vpn-category-rail {
        padding: 18px;
        background:
            linear-gradient(180deg, rgba(255,255,255,0.052), rgba(255,255,255,0.022)),
            rgba(8, 16, 29, 0.72);
    }
    .vpn-shell-secondary .vpn-category-rail .vpn-toolbar {
        gap: 10px;
    }
    .vpn-entry-grid-mk3 {
        gap: 16px;
    }
    .vpn-entry-card {
        padding: 20px;
        background:
            linear-gradient(180deg, rgba(255,255,255,0.052), rgba(255,255,255,0.022)),
            rgba(8, 16, 29, 0.72);
    }
    .vpn-entry-card .vpn-hero-actions {
        margin-top: 14px;
    }
    .cbi-map {
        overflow: hidden;
    }
    .cbi-map .cbi-section,
    .cbi-map .cbi-section-node,
    .cbi-map fieldset.cbi-section,
    .cbi-map fieldset.cbi-section-table {
        padding: 20px !important;
    }
    .cbi-map .cbi-value {
        min-height: 64px;
        align-items: center;
        padding: 16px 0 !important;
    }
    .cbi-map .cbi-value-title {
        padding-top: 4px;
    }
    .cbi-map input[type="text"],
    .cbi-map input[type="password"],
    .cbi-map input[type="file"],
    .cbi-map textarea,
    .cbi-map select {
        min-height: 44px;
        background:
            linear-gradient(180deg, rgba(255,255,255,0.050), rgba(255,255,255,0.018)),
            rgba(3, 7, 18, 0.66) !important;
    }
    .cbi-map .cbi-button-row,
    .cbi-map .cbi-page-actions {
        display: flex;
        flex-wrap: wrap;
        justify-content: flex-end;
        gap: 10px;
        padding-top: 14px;
    }
    .cbi-map .cbi-button-row .cbi-button,
    .cbi-map .cbi-page-actions .cbi-button {
        width: auto;
        min-width: 128px;
        flex: 0 0 auto;
    }
    .vpn-shell-mk3 .vpn-panel-shell {
        margin-top: 14px;
    }
    .vpn-shell-mk3 .vpn-tabbar {
        gap: 10px;
        padding: 12px;
    }
    .vpn-shell-mk3 .vpn-panel pre,
    .vpn-shell-mk3 .vpn-subcard pre {
        min-height: 240px;
    }
    @media (max-width: 1100px) {
        .vpn-hero-main {
            grid-template-columns: minmax(0, 1fr) minmax(360px, 0.92fr);
        }
        .vpn-overview-grid,
        .vpn-stat-grid {
            grid-template-columns: 1fr 1fr;
        }
        .vpn-command-card {
            grid-column: auto;
        }
        .vpn-mini-grid-mk3 {
            grid-template-columns: 1fr 1fr;
        }
    }
    @media (max-width: 980px) {
        .vpn-hero-main,
        .vpn-split-grid,
        .vpn-shell-secondary .vpn-hero-top,
        .vpn-entry-grid-mk3 {
            grid-template-columns: 1fr;
        }
        .vpn-tabbar {
            grid-template-columns: repeat(2, minmax(0, 1fr));
        }
        .vpn-shell-secondary .vpn-mini-grid,
        .vpn-stat-grid,
        .vpn-overview-grid {
            grid-template-columns: 1fr 1fr;
        }
        .vpn-command-card {
            grid-column: auto;
        }
        .vpn-cbi-section,
        .cbi-map .cbi-value {
            grid-template-columns: 1fr !important;
        }
        .vpn-shell-secondary .vpn-hero-actions {
            justify-content: stretch;
        }
        .vpn-shell-secondary .vpn-hero-actions .cbi-button,
        .vpn-shell-secondary .vpn-hero-actions a.cbi-button {
            flex: 1 1 0;
            min-width: 0;
        }
    }
    @media (max-width: 640px) {
        .vpn-shell {
            padding: 0 4px 14px;
        }
        .vpn-hero-main,
        .vpn-hero-secondary {
            padding: 14px;
        }
        .vpn-brand-block,
        .vpn-command-card,
        .vpn-quick-rail,
        .vpn-panel {
            padding: 14px;
        }
        .vpn-brand-block h2,
        .vpn-page-title {
            font-size: 24px;
            line-height: 1.2;
        }
        .vpn-hero-summary,
        .vpn-secondary-summary,
        .vpn-mini-grid-mk3,
        .vpn-shell-secondary .vpn-mini-grid,
        .vpn-stat-grid,
        .vpn-overview-grid,
        .vpn-action-list-compact,
        .vpn-hero-actions,
        .vpn-tabbar {
            grid-template-columns: 1fr;
        }
        .vpn-orb-wrap {
            grid-template-columns: 1fr;
            justify-items: center;
            text-align: center;
        }
        .vpn-orb-ring {
            width: 112px;
            height: 112px;
            min-width: 112px;
            font-size: 20px;
        }
        .vpn-card-head,
        .vpn-quick-rail-head,
        .vpn-panel-shell-head,
        .vpn-panel-head,
        .vpn-entry-head,
        .vpn-check-row {
            flex-direction: column;
            align-items: stretch;
        }
        .vpn-kv {
            grid-template-columns: 1fr;
            gap: 5px;
        }
        .vpn-shell-secondary .vpn-hero-secondary {
            padding: 16px;
        }
        .vpn-shell-secondary .vpn-hero-actions {
            flex-direction: column;
