            linear-gradient(180deg, rgba(148,163,184,0.14), rgba(148,163,184,0.055)) !important;
    }
    .vpn-shell-secondary .vpn-mini-card {
        position: relative;
        overflow: hidden;
    }
    .vpn-shell-secondary .vpn-mini-card::after {
        content: "";
