    }
    .vpn-entry-grid-mk3 {
        margin: 14px 0 18px;
    }
    .vpn-entry-card {
        min-height: 360px;
        display: flex;
        flex-direction: column;
        justify-content: flex-start;
    }
    .vpn-entry-head h4 {
        margin: 0;
        color: #e0f2fe;
        font-size: 18px;
        line-height: 1.35;
    }
    .vpn-entry-lead,
    .vpn-field-help {
        color: var(--vpn-muted);
