        box-shadow: inset 0 1px 0 rgba(255,255,255,0.042), 0 14px 30px rgba(0,0,0,0.16);
        -webkit-backdrop-filter: blur(12px) saturate(116%);
        backdrop-filter: blur(12px) saturate(116%);
    }
    .vpn-hero-mk5::before,
