	_res=$(_command_private_exec "$_ctl" "NRRCCAPQRY" "=3")
	[ -z "$_res" ] && return 1

	_data=$(echo "$_res"|awk -F',' '{print $2}'|xargs -r printf)
	echo  "NRRCCAPQRY:$_data"
	if [ "$_data" = "$_val" ]; then
