	end
-%>
<%+header%>

<form method="post" action="<%=pcdata(luci.http.getenv("REQUEST_URI") or luci.dispatcher.build_url("admin", "status", "details"))%>">
	<%- if fuser then %>
		<div class="alert-message warning">
			<p><%:Invalid username and/or password! Please try again.%></p>
		</div>
	<% end -%>
	<div class="cbi-map">
