leigod_write_uninstall_helper() {
    mkdir -p /usr/libexec
    cat > /usr/libexec/nradio-leigod-uninstall <<'EOF_LEIGOD_UNINSTALL'
#!/bin/sh
set -eu
APP_NAME="雷神加速器"
PKG_NAME="nradio-leigod"
APP_ROUTE="nradioadv/system/leigod"
APP_CONTROLLER="/usr/lib/lua/luci/controller/nradio_adv/leigod.lua"
APP_VIEW="/usr/lib/lua/luci/view/nradiobridge_leigod/leigod.htm"
APP_VIEW_DIR="${APP_VIEW%/*}"
APP_ICON="/www/luci-static/nradio/images/icon/leigod.svg"
LEIGOD_DIR="/usr/sbin/leigod"
LEIGOD_INIT="/etc/init.d/acc"
delete_sections() {
    st="$1"; fn="$2"; fv="$3"
    [ -n "$fv" ] || return 0
    uci -X show appcenter 2>/dev/null | while IFS= read -r line; do
        case "$line" in
            "appcenter.@${st}"*".${fn}='${fv}'"|"appcenter.cfg"*".${fn}='${fv}'")
                sec="${line#appcenter.}"; sec="${sec%%.*}"; printf '%s\n' "$sec" ;;
        esac
    done | sort -u | while IFS= read -r sec; do
        [ -n "$sec" ] && uci -q delete "appcenter.$sec" >/dev/null 2>&1 || true
    done
}
if [ -x "$LEIGOD_INIT" ]; then
    "$LEIGOD_INIT" disable >/dev/null 2>&1 || true
    "$LEIGOD_INIT" stop >/dev/null 2>&1 || true
fi
if [ -f "$LEIGOD_DIR/leigod_uninstall.sh" ]; then
    ( cd "$LEIGOD_DIR" && sh ./leigod_uninstall.sh ) || { echo "雷神官方卸载器执行失败，已保留现场" >&2; exit 1; }
fi
killall acc-gw.router.arm64 acc-gw.router.aarch64 acc_upgrade_monitor >/dev/null 2>&1 || true
rm -rf "$LEIGOD_DIR" /tmp/acc "$APP_VIEW_DIR" 2>/dev/null || { echo "删除雷神目录失败" >&2; exit 1; }
rm -f "$LEIGOD_INIT" /etc/config/accelerator /etc/config/accelerator.ini /etc/config/acc_version.ini /tmp/leigod-plugin-install.sh 2>/dev/null || { echo "删除雷神配置失败" >&2; exit 1; }
delete_sections package name "$APP_NAME"
delete_sections package name "$PKG_NAME"
delete_sections package_list name "$APP_NAME"
delete_sections package_list pkg_name "$PKG_NAME"
delete_sections package_list parent "$APP_NAME"
delete_sections package_list luci_module_route "$APP_ROUTE"
uci -q commit appcenter >/dev/null 2>&1 || { echo "提交应用商店配置失败" >&2; exit 1; }
rm -f "$APP_CONTROLLER" "$APP_VIEW" "$APP_ICON" /usr/libexec/nradio-leigod-uninstall 2>/dev/null || { echo "删除雷神页面文件失败" >&2; exit 1; }
rm -f /tmp/luci-indexcache /tmp/infocd/cache/appcenter 2>/dev/null || true
rm -f /tmp/luci-modulecache/* 2>/dev/null || true
/etc/init.d/infocd restart >/dev/null 2>&1 || true
/etc/init.d/appcenter restart >/dev/null 2>&1 || true
/etc/init.d/uhttpd reload >/dev/null 2>&1 || { echo "重载 uhttpd 失败" >&2; exit 1; }
[ ! -e "$LEIGOD_DIR" ] && [ ! -e "$LEIGOD_INIT" ] || { echo "雷神卸载后仍有核心文件残留" >&2; exit 1; }
exit 0
EOF_LEIGOD_UNINSTALL
    chmod 755 /usr/libexec/nradio-leigod-uninstall
}

leigod_write_controller() {
    mkdir -p /usr/lib/lua/luci/controller/nradio_adv
    cat > /usr/lib/lua/luci/controller/nradio_adv/leigod.lua <<'EOF_LEIGOD_CONTROLLER'
module("luci.controller.nradio_adv.leigod", package.seeall)
function index()
    local page=entry({"nradioadv","system","leigod"},template("nradiobridge_leigod/leigod"),_("LeigodAcc"),91)
    page.show=true
    entry({"nradioadv","system","leigod","status"},call("action_status"),nil).leaf=true
    local uninstall_page=entry({"nradioadv","system","leigod","uninstall"},call("action_uninstall"),nil)
    uninstall_page.leaf=true
    uninstall_page.post=true
end
local function trim(v) v=tostring(v or ""); local o=v:gsub("^%s+",""):gsub("%s+$",""); return o end
local function exec(c) return trim(require("luci.sys").exec(c.." 2>/dev/null")) end
local function has_file(p) return require("nixio.fs").access(p) and true or false end
local function write_json(data)
    local h=require "luci.http"
    local ok,jsonc=pcall(require,"luci.jsonc")
    h.prepare_content("application/json")
    if type(h.write_json)=="function" then
        h.write_json(data)
    elseif ok and jsonc and type(jsonc.stringify)=="function" then
        h.write(jsonc.stringify(data or {}))
    else
        h.write("{}")
    end
end
local function listen_line(port) return exec("netstat -lntup | grep ':"..port.." ' | head -n 1") end
local function conn_count(pattern) return tonumber(exec("netstat -tunap | grep "..pattern.." | grep ESTABLISHED | wc -l")) or 0 end
local function detect_mode()
    local tun=exec("uci -q get accelerator.base.tun")
    if tun=="1" then return "TUN" elseif tun=="0" then return "Tproxy" end
    if exec("grep -q -- '--mode tun' /etc/init.d/acc && echo yes || echo no")=="yes" then return "TUN" end
    if has_file("/etc/init.d/acc") then return "Tproxy" end
    return "UNKNOWN"
end
local function tail_log()
    local log=exec("ls -t /tmp/acc/log/acc_Game.log /tmp/acc/acc-gw.log-* 2>/dev/null | head -n 1")
    if log=="" then return "" end
    return exec("tail -n 12 "..log)
end
function action_status()
    local installed=has_file("/usr/sbin/leigod/acc-gw.router.arm64") or has_file("/usr/sbin/leigod/acc-gw.router.aarch64") or exec("ls /usr/sbin/leigod/acc-gw.router.* 2>/dev/null | head -n 1")~=""
    local acc_pid=exec("pidof acc-gw.router.arm64")
    if acc_pid=="" then acc_pid=exec("pidof acc-gw.router.aarch64") end
    if acc_pid=="" then acc_pid=exec("ps | grep 'acc-gw.router' | grep -v grep | awk '{print $1}'") end
    local acc_runner_pid=exec("ps | grep 'acc-gw.router' | grep ' -r acc ' | grep -v grep | awk '{print $1}'")
    local init_exists=has_file("/etc/init.d/acc")
    local service_enabled=false
    if init_exists then service_enabled=exec("/etc/init.d/acc enabled && echo yes || echo no")=="yes" end
    write_json({
        installed=installed,service_enabled=service_enabled,service_running=acc_pid~="",accelerating=acc_runner_pid~="",
        init_exists=init_exists,acc_pid=acc_pid,acc_runner_pid=acc_runner_pid,upgrade_pid=exec("pidof acc_upgrade_monitor"),
        web5588=listen_line("5588")~="",web5588_line=listen_line("5588"),
        port10001=listen_line("10001")~="",port10001_line=listen_line("10001"),
        udp6066=exec("netstat -lunp | grep ':6066 ' | head -n 1")~="",udp6066_line=exec("netstat -lunp | grep ':6066 ' | head -n 1"),
        mode=detect_mode(),acc_conn=conn_count("acc-gw.router"),log_tail=tail_log()
    })
end
function action_uninstall()
    local rc=os.execute("/usr/libexec/nradio-leigod-uninstall >/dev/null 2>&1")
    if rc==0 then
        write_json({ok=true,msg="雷神加速器卸载完成"})
    else
        write_json({ok=false,msg="雷神加速器卸载失败，请使用总脚本查看错误"})
    end
end
EOF_LEIGOD_CONTROLLER
    chmod 644 /usr/lib/lua/luci/controller/nradio_adv/leigod.lua 2>/dev/null || true
}

leigod_write_view() {
    mkdir -p /usr/lib/lua/luci/view/nradiobridge_leigod
    cat > /usr/lib/lua/luci/view/nradiobridge_leigod/leigod.htm <<'EOF_LEIGOD_VIEW'
<%+header%>
<style>
html,body{width:100%!important;max-width:none!important;margin:0!important;background:#101523!important;overflow-x:hidden}.container.body-container:not(.visible-xs-block),.main,.main-content,#maincontent{width:100%!important;max-width:none!important;min-width:0!important;margin:0!important;padding:0!important}.lg-wrap{width:100%;max-width:none;min-height:100vh;padding:34px 40px 42px;color:#f8fbff;background:radial-gradient(circle at 14% 8%,rgba(245,158,11,.18),transparent 30%),linear-gradient(135deg,#111827,#202a42 58%,#101827);box-sizing:border-box}.lg-head{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-bottom:22px}.lg-title{font-size:32px;font-weight:900}.lg-sub{margin-top:8px;color:#c6d3e1;font-size:14px}.lg-pill{display:inline-flex;align-items:center;gap:9px;border:1px solid rgba(248,181,74,.42);border-radius:999px;padding:10px 15px;background:rgba(245,158,11,.15);font-weight:900}.lg-dot{width:9px;height:9px;border-radius:50%;background:#94a3b8;box-shadow:0 0 10px currentColor}.lg-dot.ok{background:#22c55e;color:#22c55e}.lg-dot.warn{background:#f59e0b;color:#f59e0b}.lg-dot.bad{background:#ef4444;color:#ef4444}.lg-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin:22px 0 26px}.lg-card{border:1px solid rgba(255,255,255,.12);border-radius:14px;padding:20px 22px;background:linear-gradient(145deg,rgba(255,255,255,.085),rgba(255,255,255,.035));box-shadow:inset 0 1px 0 rgba(255,255,255,.08),0 18px 36px rgba(0,0,0,.20)}.lg-label{color:#fcd38a;font-size:13px;font-weight:900}.lg-value{margin-top:10px;font-size:26px;font-weight:900;color:#fff;word-break:break-all}.lg-row{display:grid;grid-template-columns:240px 1fr;gap:14px;padding:14px 0;border-bottom:1px solid rgba(255,255,255,.08);color:#d8e2f0}.lg-k{color:#fcd38a;font-weight:900}.lg-v{font-weight:900;word-break:break-all}.lg-actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:22px}.lg-btn{border:1px solid rgba(248,181,74,.44);border-radius:10px;background:rgba(245,158,11,.17);color:#fff7ed;font-weight:900;padding:11px 18px;cursor:pointer}.lg-btn.danger{border-color:rgba(248,113,113,.50);background:rgba(239,68,68,.18)}.lg-log{white-space:pre-wrap;line-height:1.55;font-family:monospace;font-size:12px;max-height:220px;overflow:auto;color:#dbeafe}.lg-note{margin-top:18px;color:#c6d3e1;line-height:1.7;font-size:13px}@media(max-width:900px){.lg-wrap{padding:24px 18px 30px}.lg-grid{grid-template-columns:1fr}.lg-row{grid-template-columns:1fr}.lg-head{align-items:flex-start;flex-direction:column}}
/* NRadio Leigod premium visual finish */.lg-wrap{position:relative;overflow:hidden}.lg-wrap:before{content:"";position:absolute;left:34px;right:34px;top:0;height:1px;background:linear-gradient(90deg,transparent,rgba(248,181,74,.70),rgba(248,113,113,.32),transparent);pointer-events:none}.lg-head,.lg-grid,.lg-card,.lg-actions,.lg-note{position:relative;z-index:1}.lg-title{text-shadow:0 1px 0 rgba(0,0,0,.32),0 0 24px rgba(245,158,11,.12)}.lg-sub{color:#d3dbe7}.lg-pill{box-shadow:inset 0 1px 0 rgba(255,255,255,.08),0 12px 26px rgba(2,8,23,.20);backdrop-filter:blur(10px) saturate(1.06);-webkit-backdrop-filter:blur(10px) saturate(1.06)}.lg-card{border-color:rgba(248,181,74,.22);background:radial-gradient(circle at 14% 0%,rgba(245,158,11,.13),transparent 44%),linear-gradient(145deg,rgba(255,255,255,.095),rgba(255,255,255,.038));box-shadow:inset 0 1px 0 rgba(255,255,255,.10),0 22px 42px rgba(0,0,0,.24)}.lg-card:hover{border-color:rgba(248,181,74,.36);box-shadow:inset 0 1px 0 rgba(255,255,255,.12),0 24px 46px rgba(0,0,0,.26)}.lg-label{color:#ffdf9a}.lg-value{text-shadow:0 1px 0 rgba(0,0,0,.34)}.lg-row{border-bottom-color:rgba(255,255,255,.10)}.lg-log{border:1px solid rgba(248,181,74,.18);border-radius:12px;background:rgba(2,8,23,.28);padding:10px}.lg-btn{box-shadow:inset 0 1px 0 rgba(255,255,255,.08),0 10px 22px rgba(2,8,23,.18)}.lg-btn:focus-visible{outline:0;box-shadow:0 0 0 3px rgba(245,158,11,.20),inset 0 1px 0 rgba(255,255,255,.08),0 10px 22px rgba(2,8,23,.18)}.lg-btn:hover{border-color:rgba(248,181,74,.62);background:linear-gradient(180deg,rgba(245,158,11,.25),rgba(245,158,11,.10))}.lg-btn.danger:hover{border-color:rgba(248,113,113,.66);background:linear-gradient(180deg,rgba(239,68,68,.26),rgba(239,68,68,.12))}.lg-head,.lg-grid,.lg-card,.lg-row,.lg-v,.lg-value,.lg-log{min-width:0;overflow-wrap:anywhere}.lg-card,.lg-pill,.lg-btn{backdrop-filter:saturate(1.04) blur(3px);-webkit-backdrop-filter:saturate(1.04) blur(3px)}@media(max-width:520px){.lg-title{font-size:26px}.lg-card{border-radius:13px}.lg-actions{align-items:stretch;flex-direction:column}.lg-btn{width:100%}}
</style>
<div class="lg-wrap"><div class="lg-head"><div><div class="lg-title">雷神加速器</div><div class="lg-sub">只读监听雷神后台状态；绑定设备和选择游戏仍在雷神 App 内完成。</div></div><div class="lg-pill"><span id="lg-dot" class="lg-dot"></span><span id="lg-status">读取中</span></div></div><div class="lg-grid"><div class="lg-card"><div class="lg-label">服务状态</div><div id="lg-main" class="lg-value">-</div></div><div class="lg-card"><div class="lg-label">代理连接</div><div id="lg-conn" class="lg-value">-</div></div><div class="lg-card"><div class="lg-label">运行模式</div><div id="lg-mode" class="lg-value">-</div></div></div><div class="lg-card"><div class="lg-row"><div class="lg-k">安装目录</div><div id="lg-installed" class="lg-v">-</div></div><div class="lg-row"><div class="lg-k">acc-gw</div><div id="lg-acc" class="lg-v">-</div></div><div class="lg-row"><div class="lg-k">升级监控</div><div id="lg-upgrade" class="lg-v">-</div></div><div class="lg-row"><div class="lg-k">5588 Web</div><div id="lg-web" class="lg-v">-</div></div><div class="lg-row"><div class="lg-k">10001 服务端口</div><div id="lg-port" class="lg-v">-</div></div><div class="lg-row"><div class="lg-k">6066 UDP</div><div id="lg-udp" class="lg-v">-</div></div><div class="lg-row"><div class="lg-k">启动脚本</div><div id="lg-init" class="lg-v">-</div></div><div class="lg-row"><div class="lg-k">最近日志</div><div id="lg-log" class="lg-v lg-log">-</div></div></div><div class="lg-actions"><button type="button" class="lg-btn" onclick="lgRefresh()">刷新状态</button><button type="button" class="lg-btn danger" onclick="lgUninstall()">卸载雷神加速器</button></div><div class="lg-note"><strong>状态解释：</strong>检测到 <code>-r acc</code> 进程显示加速中；仅后台 web/daemon 在线显示插件在线。</div></div>
<script>
var lgBase='<%=url("nradioadv/system/leigod")%>';var lgToken='<%=require("luci.dispatcher").context.authtoken%>';function lgText(id,text){var el=document.getElementById(id);if(el)el.textContent=text||'-';}function lgApply(d){var dot=document.getElementById('lg-dot');var running=!!d.service_running;var accelerating=!!d.accelerating;var installed=!!d.installed;var statusText=accelerating?'加速中':(running?'插件在线':(installed?'已安装未在线':'未安装'));lgText('lg-status',statusText);lgText('lg-main',statusText);lgText('lg-conn',String(d.acc_conn||0));lgText('lg-mode',d.mode||'UNKNOWN');lgText('lg-installed',installed?'已安装':'未安装');lgText('lg-acc',accelerating?('加速中 / '+(d.acc_runner_pid||'-')):(running?('插件在线 / '+(d.acc_pid||'-')):'未运行'));lgText('lg-upgrade',d.upgrade_pid?('运行中 / '+d.upgrade_pid):'未运行');lgText('lg-web',d.web5588?d.web5588_line:'未监听');lgText('lg-port',d.port10001?d.port10001_line:'未监听');lgText('lg-udp',d.udp6066?d.udp6066_line:'未监听');lgText('lg-init',d.init_exists?(d.service_enabled?'已启用':'未启用'):'缺失');lgText('lg-log',d.log_tail||'-');if(dot){dot.className='lg-dot '+(running?'ok':(installed?'warn':'bad'));}}function lgRefresh(){var x=new XMLHttpRequest();x.open('GET',lgBase+'/status?_='+Date.now(),true);x.onreadystatechange=function(){if(x.readyState===4){try{lgApply(JSON.parse(x.responseText||'{}'));}catch(e){lgText('lg-status','读取失败');}}};x.send(null);}function lgUninstall(){if(!confirm('确认卸载雷神加速器并移除应用商店入口吗？'))return;var x=new XMLHttpRequest();x.open('POST',lgBase+'/uninstall',true);x.onreadystatechange=function(){if(x.readyState===4)alert('已开始卸载，稍后刷新应用商店。');};x.setRequestHeader('Content-Type','application/x-www-form-urlencoded');x.send('token='+encodeURIComponent(lgToken));}lgRefresh();setInterval(lgRefresh,5000);
</script>
<script>
function lgUninstall(){
  if(!confirm('确认卸载雷神加速器并移除应用商店入口吗？'))return;
  var x=new XMLHttpRequest();
  x.open('POST',lgBase+'/uninstall',true);
  x.onreadystatechange=function(){
    if(x.readyState!==4)return;
    var d={};try{d=JSON.parse(x.responseText||'{}');}catch(e){}
    if(x.status>=200&&x.status<300&&d.ok){alert(d.msg||'雷神加速器卸载完成');location.href='<%=url("nradioadv/system/appcenter")%>';}
    else alert((d&&d.msg)||'雷神加速器卸载失败');
  };
  x.setRequestHeader('Content-Type','application/x-www-form-urlencoded');
  x.send('token='+encodeURIComponent(lgToken));
}
</script>
<%+footer%>
EOF_LEIGOD_VIEW
    chmod 644 /usr/lib/lua/luci/view/nradiobridge_leigod/leigod.htm 2>/dev/null || true
}

leigod_install_assets() {
    leigod_assets_log="${1:-写入雷神应用商店接入文件}"
    log "$leigod_assets_log"
    leigod_write_icon
    leigod_write_uninstall_helper
    write_plugin_uninstall_assets
    leigod_write_controller
    leigod_write_view
    game_accel_set_appcenter_entry "雷神加速器" "nradio-leigod" "$(leigod_version)" "$(leigod_size)" "nradioadv/system/leigod" "/usr/lib/lua/luci/controller/nradio_adv/leigod.lua" "leigod.svg"
    refresh_luci_appcenter
}

leigod_attach_integrated() {
    game_accel_require_appcenter
    leigod_installed || die "未检测到 /usr/sbin/leigod/acc-gw.router.*，请先安装雷神加速器"
    leigod_install_assets
    log "完成：雷神加速器已接入 NRadio 应用商店"
}

leigod_install_integrated() {
    game_accel_require_appcenter
    cat <<'EOF_LEIGOD_RISK'
高风险提示：
雷神官方脚本可能修改系统网络、防火墙、UPnP、/etc/init.d/acc 和相关依赖。
已经安装雷神时，建议优先使用“检测已安装并接入应用商店”。
EOF_LEIGOD_RISK
    confirm_or_exit "确认安装雷神官方脚本并接入 NRadio 应用商店吗？"
    command -v opkg >/dev/null 2>&1 || die "系统没有 opkg，无法自动安装雷神依赖"
    log "[1/4] 下载雷神官方安装脚本"
    download_file "$LEIGOD_INSTALLER_URL" "/tmp/leigod-plugin-install.sh" || die "下载雷神官方安装脚本失败"
    grep -q 'leigod\|acc-gw\|accelerator' /tmp/leigod-plugin-install.sh 2>/dev/null || die "雷神官方安装脚本内容异常，已停止执行"
    sh -n /tmp/leigod-plugin-install.sh >/dev/null 2>&1 || die "雷神官方安装脚本语法异常，已停止执行"
    log "[2/4] 安装雷神依赖"
    ensure_opkg_update || die "opkg update 失败，已停止雷神依赖安装"
    lg_dep_failed=''
    for lg_pkg in curl libpcap iptables kmod-ipt-nat iptables-mod-tproxy kmod-ipt-ipset ipset kmod-tun kmod-ipt-tproxy kmod-netem tc-full conntrack miniupnpd luci-app-upnp; do
        if ! opkg list-installed 2>/dev/null | grep -q "^$lg_pkg "; then
            log "安装依赖：$lg_pkg"
            if ! opkg install "$lg_pkg"; then
                lg_dep_failed="${lg_dep_failed} $lg_pkg"
            fi
        fi
    done
    if [ -n "$lg_dep_failed" ]; then
        log "提示: 以下雷神依赖安装失败或不可用，仍将交由官方脚本继续处理:${lg_dep_failed}"
    fi
    if [ -f /etc/config/upnpd ]; then
        uci set upnpd.config.enabled='1' >/dev/null 2>&1 || true
        uci commit upnpd >/dev/null 2>&1 || true
        /etc/init.d/miniupnpd start >/dev/null 2>&1 || true
        /etc/init.d/miniupnpd enable >/dev/null 2>&1 || true
    fi
    log "[3/4] 执行雷神官方安装脚本"
    sh /tmp/leigod-plugin-install.sh || die "雷神官方安装脚本执行失败"
    sleep 2
    leigod_installed || die "安装后仍未检测到 /usr/sbin/leigod/acc-gw.router.*"
    leigod_install_assets "[4/4] 写入雷神应用商店接入文件"
    leigod_show_status
    log "完成：雷神加速器已接入 NRadio 应用商店"
}

leigod_show_status() {
    log "雷神状态:"
    if leigod_installed; then log "安装状态: 已安装"; else log "安装状态: 未安装"; fi
    if [ -x /etc/init.d/acc ]; then /etc/init.d/acc enabled >/dev/null 2>&1 && log "服务启用: 是" || log "服务启用: 否"; else log "服务启用: 启动脚本缺失"; fi
    log "acc-gw PID: $(pidof acc-gw.router.arm64 2>/dev/null || pidof acc-gw.router.aarch64 2>/dev/null || true)"
    log "加速进程: $(ps | grep 'acc-gw.router' | grep ' -r acc ' | grep -v grep | awk '{print $1}' 2>/dev/null || true)"
    log "升级监控 PID: $(pidof acc_upgrade_monitor 2>/dev/null || true)"
    log "代理连接数: $(netstat -tunap 2>/dev/null | grep acc-gw.router | grep ESTABLISHED | wc -l)"
    netstat -lntup 2>/dev/null | grep -E ':5588 |:10001 ' || true
    netstat -lunp 2>/dev/null | grep ':6066 ' || true
}

leigod_uninstall_integrated() {
    confirm_or_exit "确认卸载雷神加速器并移除应用商店入口吗？"
    [ -x /usr/libexec/nradio-leigod-uninstall ] || leigod_write_uninstall_helper
    /usr/libexec/nradio-leigod-uninstall
    log "已执行雷神加速器卸载流程"
}

